--
-- Name: get_auth(text); Type: FUNCTION; Schema: pgbouncer; Owner: -
--

CREATE FUNCTION pgbouncer.get_auth(p_usename text) RETURNS TABLE(username text, password text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
  BEGIN
      RAISE DEBUG 'PgBouncer auth request: %', p_usename;

      RETURN QUERY
      SELECT
          rolname::text,
          CASE WHEN rolvaliduntil < now()
              THEN null
              ELSE rolpassword::text
          END
      FROM pg_authid
      WHERE rolname=$1 and rolcanlogin;
  END;
  $_$;


--
-- Name: act_actualizar_activo(integer, integer, character varying, date, numeric, integer, character varying, character varying, character varying, integer, character varying, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.act_actualizar_activo(p_id integer, p_id_tipo integer DEFAULT NULL::integer, p_descripcion character varying DEFAULT NULL::character varying, p_fecha_compra date DEFAULT NULL::date, p_importe numeric DEFAULT NULL::numeric, p_id_sucursal integer DEFAULT NULL::integer, p_marca character varying DEFAULT NULL::character varying, p_modelo character varying DEFAULT NULL::character varying, p_numero_serie character varying DEFAULT NULL::character varying, p_id_trabajador_responsable integer DEFAULT NULL::integer, p_imagen_principal_ruta character varying DEFAULT NULL::character varying, p_id_usuario_auditoria integer DEFAULT NULL::integer) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_existe INTEGER;
BEGIN
    SET TIME ZONE 'America/Lima';

    SELECT COUNT(*) INTO v_existe FROM act_activos WHERE id = p_id AND estado IN (0, 1);
    IF v_existe = 0 THEN
        RETURN json_build_object('registro', NULL, 'error', 'No existe un activo con id ' || p_id);
    END IF;

    BEGIN
        UPDATE act_activos
        SET
            id_tipo                     = COALESCE(p_id_tipo, id_tipo),
            descripcion                 = COALESCE(p_descripcion, descripcion),
            fecha_compra                = COALESCE(p_fecha_compra, fecha_compra),
            importe                     = COALESCE(p_importe, importe),
            id_sucursal                 = COALESCE(p_id_sucursal, id_sucursal),
            marca                       = COALESCE(p_marca, marca),
            modelo                      = COALESCE(p_modelo, modelo),
            numero_serie                = COALESCE(p_numero_serie, numero_serie),
            id_trabajador_responsable   = COALESCE(p_id_trabajador_responsable, id_trabajador_responsable),
            imagen_principal_ruta       = COALESCE(p_imagen_principal_ruta, imagen_principal_ruta),
            id_usuario_modificacion     = p_id_usuario_auditoria,
            fecha_modificacion          = NOW()
        WHERE id = p_id AND estado IN (0, 1);

    EXCEPTION
        WHEN foreign_key_violation THEN
            RETURN json_build_object('error', 'Uno de los datos de catálogo, sucursal o responsable no es válido', 'registro', NULL);
        WHEN OTHERS THEN
            RETURN json_build_object('error', 'No se pudo actualizar el activo: ' || SQLERRM, 'registro', NULL);
    END;

    RETURN act_obtener_activo(p_id);
END;
$$;


--
-- Name: act_crear_activo(integer, character varying, date, numeric, integer, character varying, character varying, character varying, integer, character varying, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.act_crear_activo(p_id_tipo integer DEFAULT NULL::integer, p_descripcion character varying DEFAULT NULL::character varying, p_fecha_compra date DEFAULT NULL::date, p_importe numeric DEFAULT NULL::numeric, p_id_sucursal integer DEFAULT NULL::integer, p_marca character varying DEFAULT NULL::character varying, p_modelo character varying DEFAULT NULL::character varying, p_numero_serie character varying DEFAULT NULL::character varying, p_id_trabajador_responsable integer DEFAULT NULL::integer, p_imagen_principal_ruta character varying DEFAULT NULL::character varying, p_id_usuario_auditoria integer DEFAULT NULL::integer) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_id INTEGER;
BEGIN
    SET TIME ZONE 'America/Lima';

    BEGIN
        INSERT INTO act_activos (
            id_tipo, descripcion, fecha_compra, importe,
            id_sucursal, marca, modelo, numero_serie,
            id_trabajador_responsable, imagen_principal_ruta,
            id_usuario_creacion, id_usuario_modificacion
        )
        VALUES (
            p_id_tipo, p_descripcion, p_fecha_compra, p_importe,
            p_id_sucursal, p_marca, p_modelo, p_numero_serie,
            p_id_trabajador_responsable, p_imagen_principal_ruta,
            p_id_usuario_auditoria, p_id_usuario_auditoria
        )
        RETURNING id INTO v_id;

    EXCEPTION
        WHEN foreign_key_violation THEN
            RETURN json_build_object('error', 'Uno de los datos de catálogo, sucursal o responsable no es válido', 'registro', NULL);
        WHEN OTHERS THEN
            RETURN json_build_object('error', 'No se pudo crear el activo: ' || SQLERRM, 'registro', NULL);
    END;

    RETURN act_obtener_activo(v_id);
END;
$$;


--
-- Name: act_eliminar_activo(integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.act_eliminar_activo(p_id integer, p_id_usuario_auditoria integer DEFAULT NULL::integer) RETURNS json
    LANGUAGE plpgsql
    AS $$
BEGIN
    SET TIME ZONE 'America/Lima';

    UPDATE act_activos
    SET estado = 0,
        id_usuario_modificacion = p_id_usuario_auditoria,
        fecha_modificacion = NOW()
    WHERE id = p_id AND estado = 1;

    IF NOT FOUND THEN
        RETURN json_build_object('eliminado', FALSE, 'id', p_id);
    END IF;

    RETURN json_build_object('eliminado', TRUE, 'id', p_id);
END;
$$;


--
-- Name: act_listar_activos(integer, integer, integer, date, date, numeric, numeric, character varying, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.act_listar_activos(p_estado integer DEFAULT NULL::integer, p_id_tipo integer DEFAULT NULL::integer, p_id_sucursal integer DEFAULT NULL::integer, p_fecha_desde date DEFAULT NULL::date, p_fecha_hasta date DEFAULT NULL::date, p_importe_min numeric DEFAULT NULL::numeric, p_importe_max numeric DEFAULT NULL::numeric, p_buscar character varying DEFAULT ''::character varying, p_limite integer DEFAULT 10, p_offset integer DEFAULT 0) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_registros JSON;
    v_total     BIGINT;
BEGIN
    SET TIME ZONE 'America/Lima';

    SELECT COUNT(*) INTO v_total
    FROM act_activos a
    WHERE (p_estado IS NULL OR a.estado = p_estado)
      AND (p_id_tipo IS NULL OR a.id_tipo = p_id_tipo)
      AND (p_id_sucursal IS NULL OR a.id_sucursal = p_id_sucursal)
      AND (p_fecha_desde IS NULL OR a.fecha_compra >= p_fecha_desde)
      AND (p_fecha_hasta IS NULL OR a.fecha_compra <= p_fecha_hasta)
      AND (p_importe_min IS NULL OR a.importe >= p_importe_min)
      AND (p_importe_max IS NULL OR a.importe <= p_importe_max)
      AND (
          p_buscar = ''
          OR gen_texto_coincide(a.descripcion, p_buscar)
          OR gen_texto_coincide(COALESCE(a.marca, ''), p_buscar)
          OR gen_texto_coincide(COALESCE(a.modelo, ''), p_buscar)
          OR gen_texto_coincide(COALESCE(a.numero_serie, ''), p_buscar)
      );

    SELECT COALESCE(json_agg(row_to_json(r)), '[]'::JSON) INTO v_registros
    FROM (
        SELECT
            a.id,
            a.id_tipo,
            tp.nombre   AS nombre_tipo,
            a.descripcion,
            a.fecha_compra,
            a.importe,
            a.id_sucursal,
            s.nombre    AS nombre_sucursal,
            a.marca,
            a.modelo,
            a.numero_serie,
            a.id_trabajador_responsable,
            CONCAT_WS(' ', tr.nombres, tr.apellido_paterno, tr.apellido_materno) AS nombre_trabajador_responsable,
            a.imagen_principal_ruta,
            a.estado,
            a.fecha_creacion,
            a.fecha_modificacion
        FROM act_activos a
        LEFT JOIN gen_lista_opciones tp ON a.id_tipo = tp.id
        LEFT JOIN gen_sucursal s        ON a.id_sucursal = s.id
        LEFT JOIN tra_trabajadores tr   ON a.id_trabajador_responsable = tr.id
        WHERE (p_estado IS NULL OR a.estado = p_estado)
          AND (p_id_tipo IS NULL OR a.id_tipo = p_id_tipo)
          AND (p_id_sucursal IS NULL OR a.id_sucursal = p_id_sucursal)
          AND (p_fecha_desde IS NULL OR a.fecha_compra >= p_fecha_desde)
          AND (p_fecha_hasta IS NULL OR a.fecha_compra <= p_fecha_hasta)
          AND (p_importe_min IS NULL OR a.importe >= p_importe_min)
          AND (p_importe_max IS NULL OR a.importe <= p_importe_max)
          AND (
              p_buscar = ''
              OR gen_texto_coincide(a.descripcion, p_buscar)
              OR gen_texto_coincide(COALESCE(a.marca, ''), p_buscar)
              OR gen_texto_coincide(COALESCE(a.modelo, ''), p_buscar)
              OR gen_texto_coincide(COALESCE(a.numero_serie, ''), p_buscar)
          )
        ORDER BY a.descripcion ASC
        LIMIT p_limite
        OFFSET p_offset
    ) r;

    RETURN json_build_object('registros', v_registros, 'total', v_total);
END;
$$;


--
-- Name: act_obtener_activo(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.act_obtener_activo(p_id integer) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_registro JSON;
BEGIN
    SET TIME ZONE 'America/Lima';

    SELECT row_to_json(t) INTO v_registro
    FROM (
        SELECT
            a.id,
            a.id_tipo,
            tp.nombre   AS nombre_tipo,
            a.descripcion,
            a.fecha_compra,
            a.importe,
            a.id_sucursal,
            s.nombre    AS nombre_sucursal,
            a.marca,
            a.modelo,
            a.numero_serie,
            a.id_trabajador_responsable,
            CONCAT_WS(' ',tr.nombres,tr.apellido_paterno,tr.apellido_materno) AS nombre_trabajador_responsable,
            a.imagen_principal_ruta,
            a.estado,
            a.fecha_creacion,
            a.fecha_modificacion,
            a.id_usuario_creacion,
            uc.nombre   AS nombre_usuario_creacion,
            a.id_usuario_modificacion,
            um.nombre   AS nombre_usuario_modificacion
        FROM act_activos a
        LEFT JOIN gen_lista_opciones tp ON a.id_tipo = tp.id
        LEFT JOIN gen_sucursal s        ON a.id_sucursal = s.id
        LEFT JOIN tra_trabajadores tr   ON a.id_trabajador_responsable = tr.id
        LEFT JOIN auth_usuarios uc      ON a.id_usuario_creacion = uc.id
        LEFT JOIN auth_usuarios um      ON a.id_usuario_modificacion = um.id
        WHERE a.id = p_id AND a.estado IN (0, 1)
    ) t;

    RETURN json_build_object('registro', v_registro);
END;
$$;


--
-- Name: age_actualizar_actividad(integer, character varying, text, date, time without time zone, time without time zone, timestamp without time zone, integer, integer, integer, integer, integer, character varying, integer, integer, integer, json); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.age_actualizar_actividad(p_id integer, p_titulo character varying, p_descripcion text, p_fecha_programada date, p_hora_inicio_estimada time without time zone, p_hora_fin_estimada time without time zone, p_fecha_hora_cierre timestamp without time zone, p_id_tipo_actividad integer, p_id_prioridad integer, p_id_cliente integer DEFAULT NULL::integer, p_id_trabajador_responsable integer DEFAULT NULL::integer, p_id_estado_actividad integer DEFAULT NULL::integer, p_observaciones character varying DEFAULT NULL::character varying, p_id_usuario_auditoria integer DEFAULT NULL::integer, p_id_comprobante integer DEFAULT NULL::integer, p_id_guia_remision integer DEFAULT NULL::integer, p_items json DEFAULT NULL::json) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_tipo VARCHAR;
    v_item JSON;
    v_n INTEGER := 0;
    v_hora_inicio TIME;
    v_hora_fin TIME;
BEGIN
    SET TIME ZONE 'America/Lima';

    IF NOT EXISTS (SELECT 1 FROM age_actividad WHERE id = p_id AND estado = 1) THEN
        RETURN json_build_object('registro', NULL);
    END IF;

    SELECT
        COALESCE(p_hora_inicio_estimada, hora_inicio_estimada),
        COALESCE(p_hora_fin_estimada, hora_fin_estimada)
    INTO v_hora_inicio, v_hora_fin
    FROM age_actividad
    WHERE id = p_id AND estado = 1;

    IF v_hora_inicio IS NOT NULL AND v_hora_fin IS NOT NULL THEN
        IF v_hora_inicio >= v_hora_fin THEN
            RETURN json_build_object('registro', NULL, 'error', 'La hora de inicio estimada debe ser menor a la hora de fin estimada.');
        END IF;
    END IF;

    IF p_id_tipo_actividad IS NOT NULL AND NOT EXISTS (
        SELECT 1
        FROM gen_lista_opciones o
        INNER JOIN gen_lista l ON l.id = o.id_lista
        WHERE o.id = p_id_tipo_actividad
          AND o.estado = 1
          AND (l.nombre = 'TipoActividad' OR l.id = 48)
    ) THEN
        RETURN json_build_object('registro', NULL, 'error', 'El tipo de actividad indicado no es válido.');
    END IF;

    IF p_id_prioridad IS NOT NULL AND NOT EXISTS (
        SELECT 1
        FROM gen_lista_opciones o
        INNER JOIN gen_lista l ON l.id = o.id_lista
        WHERE o.id = p_id_prioridad
          AND o.estado = 1
          AND (l.nombre = 'PrioridadActividad' OR l.id = 50)
    ) THEN
        RETURN json_build_object('registro', NULL, 'error', 'La prioridad indicada no es válida.');
    END IF;

    IF p_id_estado_actividad IS NOT NULL AND NOT EXISTS (
        SELECT 1
        FROM gen_lista_opciones o
        INNER JOIN gen_lista l ON l.id = o.id_lista
        WHERE o.id = p_id_estado_actividad
          AND o.estado = 1
          AND (l.nombre = 'EstadoActividad' OR l.id = 49)
    ) THEN
        RETURN json_build_object('registro', NULL, 'error', 'El estado de actividad indicado no es válido.');
    END IF;

    IF p_id_tipo_actividad IS NOT NULL THEN
        SELECT UPPER(TRIM(nombre)) INTO v_tipo
        FROM gen_lista_opciones
        WHERE id = p_id_tipo_actividad;

        IF v_tipo = 'REPARTO' THEN
            IF p_id_trabajador_responsable IS NOT NULL THEN
                IF NOT EXISTS (
                    SELECT 1 FROM tra_trabajadores t
                    INNER JOIN gen_chofer c ON c.id_trabajador = t.id
                    WHERE t.id = p_id_trabajador_responsable AND t.estado = 1 AND c.estado = 1 AND c.id_cliente IS NULL
                ) THEN
                    RETURN json_build_object('registro', NULL, 'error', 'El responsable debe ser un trabajador chofer de flota propia (repartidor).');
                END IF;
            END IF;
        END IF;
    END IF;

    IF p_id_trabajador_responsable IS NOT NULL AND p_hora_inicio_estimada IS NOT NULL AND p_hora_fin_estimada IS NOT NULL THEN
        IF EXISTS (
            SELECT 1
            FROM age_actividad
            WHERE id <> p_id
              AND id_trabajador_responsable = p_id_trabajador_responsable
              AND fecha_programada = p_fecha_programada
              AND estado = 1
              AND NOT EXISTS (
                  SELECT 1 FROM gen_lista_opciones ea
                  WHERE ea.id = age_actividad.id_estado_actividad
                    AND UPPER(TRIM(ea.nombre)) IN ('CANCELADA', 'CANCELADO')
              )
              AND (
                  (p_hora_inicio_estimada >= hora_inicio_estimada AND p_hora_inicio_estimada < hora_fin_estimada)
                  OR (p_hora_fin_estimada > hora_inicio_estimada AND p_hora_fin_estimada <= hora_fin_estimada)
                  OR (p_hora_inicio_estimada <= hora_inicio_estimada AND p_hora_fin_estimada >= hora_fin_estimada)
              )
        ) THEN
            RETURN json_build_object('registro', NULL, 'error', 'El responsable (trabajador) ya tiene otra actividad asignada que se cruza en ese horario para la fecha seleccionada.');
        END IF;
    END IF;

    UPDATE age_actividad
    SET
        titulo = COALESCE(p_titulo, titulo),
        descripcion = COALESCE(p_descripcion, descripcion),
        fecha_programada = COALESCE(p_fecha_programada, fecha_programada),
        hora_inicio_estimada = COALESCE(p_hora_inicio_estimada, hora_inicio_estimada),
        hora_fin_estimada = COALESCE(p_hora_fin_estimada, hora_fin_estimada),
        fecha_hora_cierre = COALESCE(p_fecha_hora_cierre, fecha_hora_cierre),
        id_tipo_actividad = COALESCE(p_id_tipo_actividad, id_tipo_actividad),
        id_prioridad = COALESCE(p_id_prioridad, id_prioridad),
        id_cliente = COALESCE(p_id_cliente, id_cliente),
        id_trabajador_responsable = COALESCE(p_id_trabajador_responsable, id_trabajador_responsable),
        id_comprobante = COALESCE(p_id_comprobante, id_comprobante),
        id_guia_remision = COALESCE(p_id_guia_remision, id_guia_remision),
        id_estado_actividad = COALESCE(p_id_estado_actividad, id_estado_actividad),
        observaciones = COALESCE(p_observaciones, observaciones),
        id_usuario_modificacion = p_id_usuario_auditoria,
        fecha_modificacion = NOW()
    WHERE id = p_id AND estado = 1;

    IF p_items IS NOT NULL AND json_typeof(p_items) = 'array' THEN
        UPDATE age_actividad_item
        SET estado = 0,
            id_usuario_modificacion = p_id_usuario_auditoria,
            fecha_modificacion = NOW()
        WHERE id_actividad = p_id AND estado = 1;

        FOR v_item IN SELECT value FROM json_array_elements(p_items)
        LOOP
            v_n := v_n + 1;
            INSERT INTO age_actividad_item (
                id_actividad, item, id_producto, descripcion, cantidad, id_balon,
                id_usuario_creacion, id_usuario_modificacion
            ) VALUES (
                p_id,
                COALESCE((v_item->>'item')::INTEGER, v_n),
                COALESCE((v_item->>'idProducto')::INTEGER, (v_item->>'id_producto')::INTEGER),
                NULLIF(TRIM(COALESCE(v_item->>'descripcion', '')), ''),
                COALESCE((v_item->>'cantidad')::NUMERIC, 1),
                COALESCE((v_item->>'idBalon')::INTEGER, (v_item->>'id_balon')::INTEGER),
                p_id_usuario_auditoria,
                p_id_usuario_auditoria
            );
        END LOOP;
    END IF;

    RETURN age_obtener_actividad(p_id);
END;
$$;


--
-- Name: age_asignar_responsable_actividad(integer, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.age_asignar_responsable_actividad(p_id integer, p_id_usuario_auditoria integer DEFAULT NULL::integer, p_id_trabajador_responsable integer DEFAULT NULL::integer) RETURNS json
    LANGUAGE plpgsql
    AS $$
BEGIN
    SET TIME ZONE 'America/Lima';

    IF NOT EXISTS (SELECT 1 FROM age_actividad WHERE id = p_id AND estado = 1) THEN
        RETURN json_build_object('registro', NULL);
    END IF;

    UPDATE age_actividad
    SET
        id_trabajador_responsable = p_id_trabajador_responsable,
        id_usuario_modificacion = p_id_usuario_auditoria,
        fecha_modificacion = NOW()
    WHERE id = p_id AND estado = 1;

    RETURN age_obtener_actividad(p_id);
END;
$$;


--
-- Name: age_cambiar_estado_actividad_realizada(integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.age_cambiar_estado_actividad_realizada(p_id integer, p_id_usuario_auditoria integer DEFAULT NULL::integer) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_id_estado_realizada INTEGER;
    v_id_estado_actual INTEGER;
BEGIN
    SET TIME ZONE 'America/Lima';

    SELECT id INTO v_id_estado_realizada
    FROM gen_lista_opciones
    WHERE LOWER(nombre) = 'realizada';

    IF v_id_estado_realizada IS NULL THEN
        RETURN json_build_object('registro', NULL, 'error', 'No se encontró el estado REALIZADA en la lista de opciones (gen_lista_opciones).');
    END IF;

    SELECT id_estado_actividad INTO v_id_estado_actual
    FROM age_actividad
    WHERE id = p_id AND estado = 1;

    IF NOT FOUND THEN
        RETURN json_build_object('registro', NULL);
    END IF;

    IF v_id_estado_actual = v_id_estado_realizada THEN
        RETURN json_build_object('registro', NULL, 'error', 'La actividad ya se encuentra marcada como realizada.');
    END IF;

    UPDATE age_actividad
    SET 
        id_estado_actividad = v_id_estado_realizada,
        fecha_hora_cierre = NOW(),
        id_usuario_modificacion = p_id_usuario_auditoria,
        fecha_modificacion = NOW()
    WHERE id = p_id AND estado = 1;

    RETURN age_obtener_actividad(p_id);
END;
$$;


--
-- Name: age_cancelar_actividad(integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.age_cancelar_actividad(p_id integer, p_id_usuario_auditoria integer DEFAULT NULL::integer) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_id_estado_cancelada INTEGER;
    v_id_estado_actual INTEGER;
    v_nombre_estado_actual VARCHAR;
BEGIN
    SET TIME ZONE 'America/Lima';

    SELECT o.id INTO v_id_estado_cancelada
    FROM gen_lista_opciones o
    JOIN gen_lista l ON l.id = o.id_lista
    WHERE (l.nombre = 'EstadoActividad' OR l.id = 49)
      AND UPPER(TRIM(o.nombre)) = 'CANCELADA'
    LIMIT 1;

    IF v_id_estado_cancelada IS NULL THEN
        RETURN json_build_object('registro', NULL, 'error', 'No se encontró el estado CANCELADA en EstadoActividad.');
    END IF;

    SELECT a.id_estado_actividad, UPPER(TRIM(ea.nombre))
    INTO v_id_estado_actual, v_nombre_estado_actual
    FROM age_actividad a
    LEFT JOIN gen_lista_opciones ea ON ea.id = a.id_estado_actividad
    WHERE a.id = p_id AND a.estado = 1;

    IF NOT FOUND THEN
        RETURN json_build_object('registro', NULL);
    END IF;

    IF v_nombre_estado_actual = 'CANCELADA' THEN
        RETURN json_build_object('registro', NULL, 'error', 'La actividad ya se encuentra cancelada.');
    END IF;

    UPDATE age_actividad
    SET
        id_estado_actividad = v_id_estado_cancelada,
        fecha_hora_cierre = NOW(),
        id_usuario_modificacion = p_id_usuario_auditoria,
        fecha_modificacion = NOW()
    WHERE id = p_id AND estado = 1;

    RETURN age_obtener_actividad(p_id);
END;
$$;


--
-- Name: age_crear_actividad(character varying, text, date, time without time zone, time without time zone, integer, integer, integer, integer, integer, character varying, integer, integer, integer, json); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.age_crear_actividad(p_titulo character varying, p_descripcion text, p_fecha_programada date, p_hora_inicio_estimada time without time zone, p_hora_fin_estimada time without time zone, p_id_tipo_actividad integer, p_id_prioridad integer, p_id_cliente integer DEFAULT NULL::integer, p_id_trabajador_responsable integer DEFAULT NULL::integer, p_id_estado_actividad integer DEFAULT NULL::integer, p_observaciones character varying DEFAULT NULL::character varying, p_id_usuario_auditoria integer DEFAULT NULL::integer, p_id_comprobante integer DEFAULT NULL::integer, p_id_guia_remision integer DEFAULT NULL::integer, p_items json DEFAULT NULL::json) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_id INTEGER;
    v_tipo VARCHAR;
    v_cliente INTEGER;
    v_destinatario INTEGER;
    v_titulo VARCHAR;
    v_serie VARCHAR;
    v_numero VARCHAR;
    v_item JSON;
    v_n INTEGER := 0;
BEGIN
    SET TIME ZONE 'America/Lima';

    v_cliente := p_id_cliente;
    v_titulo := NULLIF(TRIM(COALESCE(p_titulo, '')), '');

    IF p_id_comprobante IS NOT NULL THEN
        SELECT vc.id_cliente, vc.serie, vc.numero
        INTO v_cliente, v_serie, v_numero
        FROM ven_comprobante vc
        WHERE vc.id = p_id_comprobante AND vc.estado = 1;

        IF NOT FOUND THEN
            RETURN json_build_object('registro', NULL, 'error', 'El comprobante indicado no existe.');
        END IF;

        v_cliente := COALESCE(p_id_cliente, v_cliente);
        IF v_titulo IS NULL THEN
            v_titulo := TRIM(CONCAT('Reparto ', COALESCE(v_serie, ''), '-', COALESCE(v_numero, '')));
        END IF;

        IF EXISTS (
            SELECT 1
            FROM age_actividad a
            LEFT JOIN gen_lista_opciones ea ON ea.id = a.id_estado_actividad
            WHERE a.id_comprobante = p_id_comprobante
              AND a.estado = 1
              AND COALESCE(UPPER(TRIM(ea.nombre)), '') NOT IN ('CANCELADA', 'CANCELADO')
        ) THEN
            RETURN json_build_object('registro', NULL, 'error', 'Este comprobante ya tiene un reparto / actividad vigente.');
        END IF;
    END IF;

    IF p_id_guia_remision IS NOT NULL THEN
        SELECT gr.id_cliente, gr.id_destinatario, gr.serie, gr.numero
        INTO v_cliente, v_destinatario, v_serie, v_numero
        FROM gre_guia_remision gr
        WHERE gr.id = p_id_guia_remision AND gr.estado = 1;

        IF NOT FOUND THEN
            RETURN json_build_object('registro', NULL, 'error', 'La guía de remisión indicada no existe.');
        END IF;

        v_cliente := COALESCE(p_id_cliente, v_cliente, v_destinatario);
        IF v_titulo IS NULL THEN
            v_titulo := TRIM(CONCAT('Reparto GRE ', COALESCE(v_serie, ''), '-', COALESCE(v_numero, '')));
        END IF;

        IF EXISTS (
            SELECT 1
            FROM age_actividad a
            LEFT JOIN gen_lista_opciones ea ON ea.id = a.id_estado_actividad
            WHERE a.id_guia_remision = p_id_guia_remision
              AND a.estado = 1
              AND COALESCE(UPPER(TRIM(ea.nombre)), '') NOT IN ('CANCELADA', 'CANCELADO')
        ) THEN
            RETURN json_build_object('registro', NULL, 'error', 'Esta guía de remisión ya tiene un reparto / actividad vigente.');
        END IF;
    END IF;

    IF v_titulo IS NULL THEN
        RETURN json_build_object('registro', NULL, 'error', 'El título es obligatorio.');
    END IF;

    IF NOT EXISTS (
        SELECT 1
        FROM gen_lista_opciones o
        INNER JOIN gen_lista l ON l.id = o.id_lista
        WHERE o.id = p_id_tipo_actividad
          AND o.estado = 1
          AND (l.nombre = 'TipoActividad' OR l.id = 48)
    ) THEN
        RETURN json_build_object('registro', NULL, 'error', 'El tipo de actividad indicado no es válido.');
    END IF;

    IF NOT EXISTS (
        SELECT 1
        FROM gen_lista_opciones o
        INNER JOIN gen_lista l ON l.id = o.id_lista
        WHERE o.id = p_id_prioridad
          AND o.estado = 1
          AND (l.nombre = 'PrioridadActividad' OR l.id = 50)
    ) THEN
        RETURN json_build_object('registro', NULL, 'error', 'La prioridad indicada no es válida.');
    END IF;

    IF p_id_estado_actividad IS NOT NULL AND NOT EXISTS (
        SELECT 1
        FROM gen_lista_opciones o
        INNER JOIN gen_lista l ON l.id = o.id_lista
        WHERE o.id = p_id_estado_actividad
          AND o.estado = 1
          AND (l.nombre = 'EstadoActividad' OR l.id = 49)
    ) THEN
        RETURN json_build_object('registro', NULL, 'error', 'El estado de actividad indicado no es válido.');
    END IF;

    IF p_hora_inicio_estimada IS NOT NULL AND p_hora_fin_estimada IS NOT NULL THEN
        IF p_hora_inicio_estimada >= p_hora_fin_estimada THEN
            RETURN json_build_object('registro', NULL, 'error', 'La hora de inicio estimada debe ser menor a la hora de fin estimada.');
        END IF;
    END IF;

    SELECT UPPER(TRIM(nombre)) INTO v_tipo
    FROM gen_lista_opciones
    WHERE id = p_id_tipo_actividad;

    IF v_tipo = 'REPARTO' THEN
        IF p_id_trabajador_responsable IS NOT NULL THEN
            IF NOT EXISTS (
                SELECT 1 FROM tra_trabajadores t
                INNER JOIN gen_chofer c ON c.id_trabajador = t.id
                WHERE t.id = p_id_trabajador_responsable AND t.estado = 1 AND c.estado = 1 AND c.id_cliente IS NULL
            ) THEN
                RETURN json_build_object('error', 'El responsable debe ser un trabajador chofer de flota propia (repartidor).');
            END IF;
        END IF;
    END IF;

    IF p_id_trabajador_responsable IS NOT NULL AND p_hora_inicio_estimada IS NOT NULL AND p_hora_fin_estimada IS NOT NULL THEN
        IF EXISTS (
            SELECT 1
            FROM age_actividad
            WHERE id_trabajador_responsable = p_id_trabajador_responsable
              AND fecha_programada = p_fecha_programada
              AND estado = 1
              AND NOT EXISTS (
                  SELECT 1 FROM gen_lista_opciones ea
                  WHERE ea.id = age_actividad.id_estado_actividad
                    AND UPPER(TRIM(ea.nombre)) IN ('CANCELADA', 'CANCELADO')
              )
              AND (
                  (p_hora_inicio_estimada >= hora_inicio_estimada AND p_hora_inicio_estimada < hora_fin_estimada)
                  OR (p_hora_fin_estimada > hora_inicio_estimada AND p_hora_fin_estimada <= hora_fin_estimada)
                  OR (p_hora_inicio_estimada <= hora_inicio_estimada AND p_hora_fin_estimada >= hora_fin_estimada)
              )
        ) THEN
            RETURN json_build_object('error', 'El responsable (trabajador) ya tiene otra actividad asignada que se cruza en ese horario para la fecha seleccionada.');
        END IF;
    END IF;

    INSERT INTO age_actividad (
        titulo, descripcion, fecha_programada,
        hora_inicio_estimada, hora_fin_estimada,
        id_tipo_actividad, id_prioridad, id_cliente,
        id_trabajador_responsable, id_comprobante,
        id_guia_remision,
        id_estado_actividad, observaciones,
        id_usuario_creacion, id_usuario_modificacion
    )
    VALUES (
        v_titulo, p_descripcion, p_fecha_programada,
        p_hora_inicio_estimada, p_hora_fin_estimada,
        p_id_tipo_actividad, p_id_prioridad, v_cliente,
        p_id_trabajador_responsable, p_id_comprobante,
        p_id_guia_remision,
        p_id_estado_actividad, p_observaciones,
        p_id_usuario_auditoria, p_id_usuario_auditoria
    )
    RETURNING id INTO v_id;

    IF p_items IS NOT NULL AND json_typeof(p_items) = 'array' THEN
        FOR v_item IN SELECT value FROM json_array_elements(p_items)
        LOOP
            v_n := v_n + 1;
            INSERT INTO age_actividad_item (
                id_actividad, item, id_producto, descripcion, cantidad, id_balon,
                id_usuario_creacion, id_usuario_modificacion
            ) VALUES (
                v_id,
                COALESCE((v_item->>'item')::INTEGER, v_n),
                COALESCE((v_item->>'idProducto')::INTEGER, (v_item->>'id_producto')::INTEGER),
                NULLIF(TRIM(COALESCE(v_item->>'descripcion', '')), ''),
                COALESCE((v_item->>'cantidad')::NUMERIC, 1),
                COALESCE((v_item->>'idBalon')::INTEGER, (v_item->>'id_balon')::INTEGER),
                p_id_usuario_auditoria,
                p_id_usuario_auditoria
            );
        END LOOP;
    ELSIF p_id_comprobante IS NOT NULL THEN
        INSERT INTO age_actividad_item (
            id_actividad, item, id_producto, descripcion, cantidad, id_balon,
            id_usuario_creacion, id_usuario_modificacion
        )
        SELECT
            v_id,
            d.item,
            d.id_producto,
            -- Con id_producto/id_balon el nombre se resuelve por JOIN en la lectura;
            -- solo se copia el texto propio de la línea (líneas libres lo necesitan).
            NULLIF(TRIM(COALESCE(d.descripcion, '')), ''),
            d.cantidad,
            d.id_balon,
            p_id_usuario_auditoria,
            p_id_usuario_auditoria
        FROM ven_comprobante_detalle d
        WHERE d.id_comprobante = p_id_comprobante AND d.estado = 1
        ORDER BY d.item;
    ELSIF p_id_guia_remision IS NOT NULL THEN
        INSERT INTO age_actividad_item (
            id_actividad, item, id_producto, descripcion, cantidad, id_balon,
            id_usuario_creacion, id_usuario_modificacion
        )
        SELECT
            v_id,
            d.item,
            d.id_producto,
            NULLIF(TRIM(COALESCE(d.descripcion, d.glosa, '')), ''),
            d.cantidad,
            d.id_balon,
            p_id_usuario_auditoria,
            p_id_usuario_auditoria
        FROM gre_guia_remision_detalle d
        WHERE d.id_guia_remision = p_id_guia_remision AND d.estado = 1
        ORDER BY d.item;
    END IF;

    RETURN age_obtener_actividad(v_id);
END;
$$;


--
-- Name: age_eliminar_actividad(integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.age_eliminar_actividad(p_id integer, p_id_usuario_auditoria integer DEFAULT NULL::integer) RETURNS json
    LANGUAGE plpgsql
    AS $$
BEGIN
    SET TIME ZONE 'America/Lima';

    UPDATE age_actividad
    SET estado = 0,
        id_usuario_modificacion = p_id_usuario_auditoria,
        fecha_modificacion = NOW()
    WHERE id = p_id AND estado = 1;

    IF NOT FOUND THEN
        RETURN json_build_object('eliminado', FALSE, 'id', p_id);
    END IF;

    RETURN json_build_object('eliminado', TRUE, 'id', p_id);
END;
$$;


--
-- Name: age_listar_actividades(character varying, integer, integer, date, date, integer, integer, integer, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.age_listar_actividades(p_busqueda character varying DEFAULT ''::character varying, p_limite integer DEFAULT 10, p_offset integer DEFAULT 0, p_fecha_desde date DEFAULT NULL::date, p_fecha_hasta date DEFAULT NULL::date, p_id_estado integer DEFAULT NULL::integer, p_id_tipo integer DEFAULT NULL::integer, p_id_prioridad integer DEFAULT NULL::integer, p_sin_responsable boolean DEFAULT NULL::boolean) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_registros JSON;
    v_total BIGINT;
BEGIN
    SET TIME ZONE 'America/Lima';

    SELECT COUNT(*) INTO v_total
    FROM age_actividad act
    LEFT JOIN cli_clientes c ON act.id_cliente = c.id
    WHERE act.estado = 1
      AND (p_fecha_desde IS NULL OR act.fecha_programada >= p_fecha_desde)
      AND (p_fecha_hasta IS NULL OR act.fecha_programada <= p_fecha_hasta)
      AND (p_id_estado IS NULL OR act.id_estado_actividad = p_id_estado)
      AND (p_id_tipo IS NULL OR act.id_tipo_actividad = p_id_tipo)
      AND (p_id_prioridad IS NULL OR act.id_prioridad = p_id_prioridad)
       AND (p_sin_responsable IS NULL OR (
           (p_sin_responsable AND act.id_trabajador_responsable IS NULL)
           OR (NOT p_sin_responsable AND act.id_trabajador_responsable IS NOT NULL)
       ))
      AND (
          p_busqueda = ''
          OR gen_texto_coincide(act.titulo, p_busqueda)
          OR gen_texto_coincide(COALESCE(act.observaciones, ''), p_busqueda)
          OR gen_texto_coincide(COALESCE(c.razon_social, ''), p_busqueda)
      );

    SELECT COALESCE(json_agg(row_to_json(t)), '[]'::JSON) INTO v_registros
    FROM (
        SELECT
            act.id,
            act.titulo,
            act.descripcion,
            act.fecha_programada,
            act.hora_inicio_estimada,
            act.hora_fin_estimada,
            act.fecha_hora_cierre,
            act.id_tipo_actividad,
            ta.nombre AS nombre_tipo_actividad,
            act.id_prioridad,
            pr.nombre AS nombre_prioridad,
            act.id_cliente,
            c.razon_social AS razon_social_cliente,
            act.id_trabajador_responsable,
            TRIM(CONCAT_WS(' ', tr.nombres, tr.apellido_paterno, tr.apellido_materno)) AS nombre_trabajador_responsable,
            act.id_usuario_responsable,
            au.nombre AS nombre_usuario_responsable,
            act.id_chofer_responsable,
            TRIM(CONCAT_WS(' ', ch.nombres, ch.apellido_paterno, ch.apellido_materno)) AS nombre_chofer_responsable,
            act.id_comprobante,
            vc.serie AS serie_comprobante,
            vc.numero AS numero_comprobante,
            act.id_guia_remision,
            gr.serie AS serie_guia_remision,
            gr.numero AS numero_guia_remision,
            act.id_estado_actividad,
            ea.nombre AS nombre_estado_actividad,
            act.observaciones,
            act.fecha_creacion,
            act.fecha_modificacion,
            act.id_usuario_creacion,
            uc.nombre AS nombre_usuario_creacion,
            act.id_usuario_modificacion,
            um.nombre AS nombre_usuario_modificacion
        FROM age_actividad act
        LEFT JOIN gen_lista_opciones ta
            ON ta.id = act.id_tipo_actividad
           AND ta.id_lista IN (SELECT gl.id FROM gen_lista gl WHERE gl.nombre = 'TipoActividad' OR gl.id = 48)
        LEFT JOIN gen_lista_opciones pr
            ON pr.id = act.id_prioridad
           AND pr.id_lista IN (SELECT gl.id FROM gen_lista gl WHERE gl.nombre = 'PrioridadActividad' OR gl.id = 50)
        LEFT JOIN gen_lista_opciones ea
            ON ea.id = act.id_estado_actividad
           AND ea.id_lista IN (SELECT gl.id FROM gen_lista gl WHERE gl.nombre = 'EstadoActividad' OR gl.id = 49)
        LEFT JOIN cli_clientes c ON act.id_cliente = c.id
        LEFT JOIN tra_trabajadores tr ON tr.id = act.id_trabajador_responsable
        LEFT JOIN auth_usuarios au ON au.id_trabajador = tr.id AND au.estado = TRUE
        LEFT JOIN gen_chofer ch ON ch.id_trabajador = tr.id AND ch.estado = 1
        LEFT JOIN ven_comprobante vc ON act.id_comprobante = vc.id
        LEFT JOIN gre_guia_remision gr ON act.id_guia_remision = gr.id
        LEFT JOIN auth_usuarios uc ON act.id_usuario_creacion = uc.id
        LEFT JOIN auth_usuarios um ON act.id_usuario_modificacion = um.id
        WHERE act.estado = 1
          AND (p_fecha_desde IS NULL OR act.fecha_programada >= p_fecha_desde)
          AND (p_fecha_hasta IS NULL OR act.fecha_programada <= p_fecha_hasta)
          AND (p_id_estado IS NULL OR act.id_estado_actividad = p_id_estado)
          AND (p_id_tipo IS NULL OR act.id_tipo_actividad = p_id_tipo)
          AND (p_id_prioridad IS NULL OR act.id_prioridad = p_id_prioridad)
          AND (p_sin_responsable IS NULL OR (
              (p_sin_responsable AND act.id_usuario_responsable IS NULL AND act.id_chofer_responsable IS NULL)
              OR (NOT p_sin_responsable AND (act.id_usuario_responsable IS NOT NULL OR act.id_chofer_responsable IS NOT NULL))
          ))
          AND (
              p_busqueda = ''
              OR gen_texto_coincide(act.titulo, p_busqueda)
              OR gen_texto_coincide(COALESCE(act.observaciones, ''), p_busqueda)
              OR gen_texto_coincide(COALESCE(c.razon_social, ''), p_busqueda)
          )
        ORDER BY
            CASE
                WHEN UPPER(TRIM(COALESCE(ea.nombre, ''))) IN ('PENDIENTE', 'PROGRAMADA') THEN 0
                WHEN UPPER(TRIM(COALESCE(ea.nombre, ''))) IN ('CANCELADA', 'CANCELADO') THEN 2
                WHEN UPPER(TRIM(COALESCE(ea.nombre, ''))) = 'REALIZADA' THEN 3
                ELSE 1
            END ASC,
            act.fecha_programada DESC,
            act.hora_inicio_estimada DESC NULLS LAST,
            act.id DESC
        LIMIT p_limite
        OFFSET p_offset
    ) t;

    RETURN json_build_object('registros', v_registros, 'total', v_total);
END;
$$;


--
-- Name: age_listar_actividades_proximas(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.age_listar_actividades_proximas(p_minutos_adelante integer DEFAULT 60) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_registros JSON;
    v_ahora TIME;
    v_hasta TIME;
    p_minutos INTEGER;
BEGIN
    SET TIME ZONE 'America/Lima';

    p_minutos := GREATEST(COALESCE(p_minutos_adelante, 60), 5);
    v_ahora := LOCALTIME;
    v_hasta := v_ahora + make_interval(mins => p_minutos);

    SELECT COALESCE(json_agg(row_to_json(t) ORDER BY t.hora_inicio_estimada), '[]'::JSON)
    INTO v_registros
    FROM (
        SELECT
            act.id,
            act.titulo,
            act.descripcion,
            act.fecha_programada,
            act.hora_inicio_estimada,
            act.hora_fin_estimada,
            act.id_tipo_actividad,
            ta.nombre AS nombre_tipo_actividad,
            act.id_prioridad,
            pr.nombre AS nombre_prioridad,
            act.id_cliente,
            c.razon_social AS razon_social_cliente,
            dir.latitud AS latitud_cliente,
            dir.longitud AS longitud_cliente,
            act.id_usuario_responsable,
            u.nombre AS nombre_usuario_responsable,
            act.id_chofer_responsable,
            TRIM(CONCAT_WS(' ', ch.nombres, ch.apellido_paterno, ch.apellido_materno)) AS nombre_chofer_responsable,
            act.id_estado_actividad,
            ea.nombre AS nombre_estado_actividad,
            act.id_comprobante,
            vc.serie AS serie_comprobante,
            vc.numero AS numero_comprobante,
            CASE
                WHEN act.hora_inicio_estimada IS NOT NULL
                     AND act.hora_fin_estimada IS NOT NULL
                     AND v_ahora >= act.hora_inicio_estimada
                     AND v_ahora < act.hora_fin_estimada
                THEN TRUE
                ELSE FALSE
            END AS en_curso
        FROM age_actividad act
        LEFT JOIN gen_lista_opciones ta
            ON ta.id = act.id_tipo_actividad
           AND ta.id_lista IN (SELECT gl.id FROM gen_lista gl WHERE gl.nombre = 'TipoActividad' OR gl.id = 48)
        LEFT JOIN gen_lista_opciones pr
            ON pr.id = act.id_prioridad
           AND pr.id_lista IN (SELECT gl.id FROM gen_lista gl WHERE gl.nombre = 'PrioridadActividad' OR gl.id = 50)
        LEFT JOIN gen_lista_opciones ea
            ON ea.id = act.id_estado_actividad
           AND ea.id_lista IN (SELECT gl.id FROM gen_lista gl WHERE gl.nombre = 'EstadoActividad' OR gl.id = 49)
        LEFT JOIN cli_clientes c ON act.id_cliente = c.id
        LEFT JOIN LATERAL (
            SELECT cd.latitud, cd.longitud
            FROM cli_direcciones cd
            WHERE cd.id_cliente = act.id_cliente
              AND cd.estado = 1
            ORDER BY cd.es_principal DESC NULLS LAST, cd.id DESC
            LIMIT 1
        ) dir ON TRUE
        LEFT JOIN auth_usuarios u ON act.id_usuario_responsable = u.id
        LEFT JOIN gen_chofer ch ON act.id_chofer_responsable = ch.id
        LEFT JOIN ven_comprobante vc ON act.id_comprobante = vc.id
        WHERE act.estado = 1
          AND act.fecha_programada = CURRENT_DATE
          AND COALESCE(UPPER(TRIM(ea.nombre)), '') NOT IN ('REALIZADA', 'CANCELADA')
          AND act.hora_inicio_estimada IS NOT NULL
          AND (
              (act.hora_fin_estimada IS NOT NULL
               AND v_ahora >= act.hora_inicio_estimada
               AND v_ahora < act.hora_fin_estimada)
              OR (act.hora_inicio_estimada >= v_ahora AND act.hora_inicio_estimada < v_hasta)
          )
    ) t;

    RETURN json_build_object('registros', v_registros);
END;
$$;


--
-- Name: age_obtener_actividad(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.age_obtener_actividad(p_id integer) RETURNS json
    LANGUAGE plpgsql STABLE
    AS $$
DECLARE
    v_registro JSON;
    v_items JSON;
BEGIN
    SELECT COALESCE(json_agg(row_to_json(t) ORDER BY t.item), '[]'::JSON)
    INTO v_items
    FROM (
        SELECT
            i.id,
            i.item,
            i.id_producto,
            COALESCE(p.nombre, i.descripcion) AS nombre_producto,
            i.descripcion,
            i.cantidad,
            i.id_balon,
            b.codigo_balon
        FROM age_actividad_item i
        LEFT JOIN pro_producto p ON p.id = i.id_producto
        LEFT JOIN bal_balon b ON b.id = i.id_balon
        WHERE i.id_actividad = p_id AND i.estado = 1
    ) t;

    SELECT row_to_json(t)
    INTO v_registro
    FROM (
        SELECT
            act.id,
            act.titulo,
            act.descripcion,
            act.fecha_programada,
            act.hora_inicio_estimada,
            act.hora_fin_estimada,
            act.fecha_hora_cierre,
            act.id_tipo_actividad,
            ta.nombre AS nombre_tipo_actividad,
            act.id_prioridad,
            pr.nombre AS nombre_prioridad,
            act.id_cliente,
            c.razon_social AS razon_social_cliente,
            dir.latitud AS latitud_cliente,
            dir.longitud AS longitud_cliente,
            act.id_trabajador_responsable,
            TRIM(CONCAT_WS(' ', tr.nombres, tr.apellido_paterno, tr.apellido_materno)) AS nombre_trabajador_responsable,
            act.id_usuario_responsable,
            au.nombre AS nombre_usuario_responsable,
            act.id_chofer_responsable,
            TRIM(CONCAT_WS(' ', ch.nombres, ch.apellido_paterno, ch.apellido_materno)) AS nombre_chofer_responsable,
            act.id_comprobante,
            vc.serie AS serie_comprobante,
            vc.numero AS numero_comprobante,
            act.id_guia_remision,
            gr.serie AS serie_guia_remision,
            gr.numero AS numero_guia_remision,
            act.id_estado_actividad,
            ea.nombre AS nombre_estado_actividad,
            act.observaciones,
            act.estado,
            act.id_usuario_creacion,
            uc.nombre AS nombre_usuario_creacion,
            act.id_usuario_modificacion,
            um.nombre AS nombre_usuario_modificacion,
            act.fecha_creacion,
            act.fecha_modificacion,
            v_items AS items
        FROM age_actividad act
        LEFT JOIN gen_lista_opciones ta
            ON ta.id = act.id_tipo_actividad
           AND ta.id_lista IN (SELECT gl.id FROM gen_lista gl WHERE gl.nombre = 'TipoActividad' OR gl.id = 48)
        LEFT JOIN gen_lista_opciones pr
            ON pr.id = act.id_prioridad
           AND pr.id_lista IN (SELECT gl.id FROM gen_lista gl WHERE gl.nombre = 'PrioridadActividad' OR gl.id = 50)
        LEFT JOIN gen_lista_opciones ea
            ON ea.id = act.id_estado_actividad
           AND ea.id_lista IN (SELECT gl.id FROM gen_lista gl WHERE gl.nombre = 'EstadoActividad' OR gl.id = 49)
        LEFT JOIN cli_clientes c ON act.id_cliente = c.id
        LEFT JOIN LATERAL (
            SELECT cd.latitud, cd.longitud
            FROM cli_direcciones cd
            WHERE cd.id_cliente = act.id_cliente
              AND cd.estado = 1
            ORDER BY cd.es_principal DESC NULLS LAST, cd.id DESC
            LIMIT 1
        ) dir ON TRUE
        LEFT JOIN tra_trabajadores tr ON tr.id = act.id_trabajador_responsable
        LEFT JOIN auth_usuarios au ON au.id_trabajador = tr.id AND au.estado = TRUE
        LEFT JOIN gen_chofer ch ON ch.id_trabajador = tr.id AND ch.estado = 1
        LEFT JOIN ven_comprobante vc ON act.id_comprobante = vc.id
        LEFT JOIN gre_guia_remision gr ON act.id_guia_remision = gr.id
        LEFT JOIN auth_usuarios uc ON act.id_usuario_creacion = uc.id
        LEFT JOIN auth_usuarios um ON act.id_usuario_modificacion = um.id
        WHERE act.id = p_id AND act.estado = 1
    ) t;

    RETURN json_build_object('registro', v_registro);
END;
$$;


--
-- Name: auth_activar_usuario(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.auth_activar_usuario(p_id integer) RETURNS json
    LANGUAGE plpgsql
    AS $$
BEGIN
    SET TIME ZONE 'America/Lima';

    UPDATE auth_usuarios
    SET estado = TRUE, fecha_modificacion = NOW()
    WHERE id = p_id AND estado = FALSE;

    IF NOT FOUND THEN
        RETURN json_build_object('activado', FALSE, 'id', p_id);
    END IF;

    RETURN json_build_object('activado', TRUE, 'id', p_id);
END;
$$;


--
-- Name: auth_actualizar_permiso(integer, character varying, character varying, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.auth_actualizar_permiso(p_id integer, p_nombre character varying DEFAULT NULL::character varying, p_descripcion character varying DEFAULT NULL::character varying, p_id_usuario_auditoria integer DEFAULT NULL::integer) RETURNS json
    LANGUAGE plpgsql
    AS $$
BEGIN
    SET TIME ZONE 'America/Lima';

    UPDATE auth_permisos
    SET
        nombre = COALESCE(p_nombre, nombre),
        descripcion = COALESCE(p_descripcion, descripcion),
        id_usuario_modificacion = p_id_usuario_auditoria,
        fecha_modificacion = NOW()
    WHERE id = p_id AND estado = TRUE;

    IF NOT FOUND THEN
        RETURN json_build_object('registro', NULL);
    END IF;

    RETURN auth_obtener_permiso(p_id);
END;
$$;


--
-- Name: auth_actualizar_rol(integer, character varying, character varying, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.auth_actualizar_rol(p_id integer, p_nombre character varying DEFAULT NULL::character varying, p_descripcion character varying DEFAULT NULL::character varying, p_id_usuario_auditoria integer DEFAULT NULL::integer) RETURNS json
    LANGUAGE plpgsql
    AS $$
BEGIN
    SET TIME ZONE 'America/Lima';

    UPDATE auth_roles
    SET
        nombre = COALESCE(p_nombre, nombre),
        descripcion = COALESCE(p_descripcion, descripcion),
        id_usuario_modificacion = p_id_usuario_auditoria,
        fecha_modificacion = NOW()
    WHERE id = p_id AND estado = TRUE;

    IF NOT FOUND THEN
        RETURN json_build_object('registro', NULL);
    END IF;

    RETURN auth_obtener_rol(p_id);
END;
$$;


--
-- Name: auth_actualizar_usuario(integer, character varying, character varying, character varying, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.auth_actualizar_usuario(p_id integer, p_nombre character varying DEFAULT NULL::character varying, p_correo character varying DEFAULT NULL::character varying, p_contrasena character varying DEFAULT NULL::character varying, p_id_trabajador integer DEFAULT NULL::integer, p_id_usuario_auditoria integer DEFAULT NULL::integer) RETURNS json
    LANGUAGE plpgsql
    AS $$
BEGIN
    SET TIME ZONE 'America/Lima';

    IF p_correo IS NOT NULL AND EXISTS (
        SELECT 1 FROM auth_usuarios
        WHERE LOWER(correo) = LOWER(p_correo) AND id <> p_id AND estado = TRUE
    ) THEN
        RETURN json_build_object('error', 'El correo ya está registrado', 'registro', NULL);
    END IF;

    IF p_id_trabajador IS NOT NULL AND EXISTS (
        SELECT 1 FROM auth_usuarios
        WHERE id_trabajador = p_id_trabajador AND id <> p_id AND estado = TRUE
    ) THEN
        RETURN json_build_object('error', 'El trabajador ya tiene otro usuario de acceso.', 'registro', NULL);
    END IF;

    UPDATE auth_usuarios
    SET
        nombre = COALESCE(p_nombre, nombre),
        correo = COALESCE(LOWER(p_correo), correo),
        contrasena = COALESCE(p_contrasena, contrasena),
        id_trabajador = COALESCE(p_id_trabajador, id_trabajador),
        fecha_modificacion = NOW()
    WHERE id = p_id AND estado = TRUE;

    IF NOT FOUND THEN
        RETURN json_build_object('registro', NULL);
    END IF;

    RETURN auth_obtener_usuario(p_id);
END;
$$;


--
-- Name: auth_asignar_rol_permiso(integer, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.auth_asignar_rol_permiso(p_id_rol integer, p_id_permiso integer, p_id_usuario_auditoria integer DEFAULT NULL::integer) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_id INTEGER;
    v_registro JSON;
BEGIN
    SET TIME ZONE 'America/Lima';

    IF EXISTS (
        SELECT 1 FROM auth_roles_permisos
        WHERE id_rol = p_id_rol AND id_permiso = p_id_permiso AND estado = TRUE
    ) THEN
        RETURN json_build_object('error', 'El rol ya tiene asignado este permiso', 'registro', NULL);
    END IF;

    UPDATE auth_roles_permisos
    SET estado = TRUE,
        id_usuario_modificacion = p_id_usuario_auditoria,
        fecha_modificacion = NOW()
    WHERE id_rol = p_id_rol AND id_permiso = p_id_permiso
    RETURNING id INTO v_id;

    IF v_id IS NULL THEN
        INSERT INTO auth_roles_permisos (id_rol, id_permiso, id_usuario_creacion, id_usuario_modificacion)
        VALUES (p_id_rol, p_id_permiso, p_id_usuario_auditoria, p_id_usuario_auditoria)
        RETURNING id INTO v_id;
    END IF;

    SELECT row_to_json(t) INTO v_registro
    FROM (
        SELECT rp.*, r.nombre AS nombre_rol, p.nombre AS nombre_permiso
        FROM auth_roles_permisos rp
        INNER JOIN auth_roles r ON rp.id_rol = r.id
        INNER JOIN auth_permisos p ON rp.id_permiso = p.id
        WHERE rp.id = v_id
    ) t;

    RETURN json_build_object('registro', v_registro);
END;
$$;


--
-- Name: auth_asignar_usuario_rol(integer, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.auth_asignar_usuario_rol(p_id_usuario integer, p_id_rol integer, p_id_usuario_auditoria integer DEFAULT NULL::integer) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_id INTEGER;
    v_registro JSON;
BEGIN
    SET TIME ZONE 'America/Lima';

    IF EXISTS (
        SELECT 1 FROM auth_usuarios_roles
        WHERE id_usuario = p_id_usuario AND id_rol = p_id_rol AND estado = TRUE
    ) THEN
        RETURN json_build_object('error', 'El usuario ya tiene asignado este rol', 'registro', NULL);
    END IF;

    UPDATE auth_usuarios_roles
    SET estado = TRUE,
        id_usuario_modificacion = p_id_usuario_auditoria,
        fecha_modificacion = NOW()
    WHERE id_usuario = p_id_usuario AND id_rol = p_id_rol
    RETURNING id INTO v_id;

    IF v_id IS NULL THEN
        INSERT INTO auth_usuarios_roles (id_usuario, id_rol, id_usuario_creacion, id_usuario_modificacion)
        VALUES (p_id_usuario, p_id_rol, p_id_usuario_auditoria, p_id_usuario_auditoria)
        RETURNING id INTO v_id;
    END IF;

    SELECT row_to_json(t) INTO v_registro
    FROM (
        SELECT ur.*, u.nombre AS nombre_usuario, r.nombre AS nombre_rol
        FROM auth_usuarios_roles ur
        INNER JOIN auth_usuarios u ON ur.id_usuario = u.id
        INNER JOIN auth_roles r ON ur.id_rol = r.id
        WHERE ur.id = v_id
    ) t;

    RETURN json_build_object('registro', v_registro);
END;
$$;


--
-- Name: auth_cerrar_sesion(integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.auth_cerrar_sesion(p_id integer, p_id_usuario_auditoria integer DEFAULT NULL::integer) RETURNS json
    LANGUAGE plpgsql
    AS $$
BEGIN
    SET TIME ZONE 'America/Lima';

    UPDATE auth_sesiones
    SET estado = FALSE,
        fecha_fin = NOW(),
        id_usuario_modificacion = p_id_usuario_auditoria,
        fecha_modificacion = NOW()
    WHERE id = p_id AND estado = TRUE AND fecha_fin IS NULL;

    IF NOT FOUND THEN
        RETURN json_build_object('cerrada', FALSE, 'id', p_id);
    END IF;

    RETURN json_build_object('cerrada', TRUE, 'id', p_id);
END;
$$;


