--
-- Name: auth_listar_ids_usuarios_por_roles(json); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.auth_listar_ids_usuarios_por_roles(p_ids_roles json DEFAULT '[]'::json) RETURNS json
    LANGUAGE plpgsql
    AS $_$
DECLARE
    v_ids JSON;
BEGIN
    SET TIME ZONE 'America/Lima';

    SELECT COALESCE(json_agg(DISTINCT u.id ORDER BY u.id), '[]'::JSON)
    INTO v_ids
    FROM auth_usuarios u
    INNER JOIN auth_usuarios_roles ur ON ur.id_usuario = u.id AND ur.estado = TRUE
    INNER JOIN auth_roles r ON r.id = ur.id_rol AND r.estado = TRUE
    WHERE u.estado = TRUE
      AND r.id IN (
          SELECT (value)::INTEGER
          FROM json_array_elements_text(COALESCE(p_ids_roles, '[]'::JSON))
          WHERE TRIM(value) ~ '^[0-9]+$'
      );

    RETURN json_build_object('ids', v_ids);
END;
$_$;


--
-- Name: auth_listar_permisos(character varying, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.auth_listar_permisos(p_busqueda character varying DEFAULT ''::character varying, p_limite integer DEFAULT 10, p_offset integer DEFAULT 0) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_registros JSON;
    v_total BIGINT;
BEGIN
    SET TIME ZONE 'America/Lima';

    SELECT COUNT(*) INTO v_total
    FROM auth_permisos p
    WHERE p.estado = TRUE
      AND (
          p_busqueda = ''
          OR gen_texto_coincide(p.nombre, p_busqueda)
          OR gen_texto_coincide(COALESCE(p.descripcion, ''), p_busqueda)
      );

    SELECT COALESCE(json_agg(row_to_json(t)), '[]'::JSON) INTO v_registros
    FROM (
        SELECT
            p.id,
            p.nombre,
            p.descripcion,
            p.estado,
            p.fecha_creacion,
            p.fecha_modificacion,
            p.id_usuario_creacion,
            uc.nombre AS nombre_usuario_creacion,
            p.id_usuario_modificacion,
            um.nombre AS nombre_usuario_modificacion,
            (
                SELECT COUNT(*)::BIGINT
                FROM auth_roles_permisos rp
                WHERE rp.id_permiso = p.id AND rp.estado = TRUE
            ) AS cantidad_roles
        FROM auth_permisos p
        LEFT JOIN auth_usuarios uc ON p.id_usuario_creacion = uc.id
        LEFT JOIN auth_usuarios um ON p.id_usuario_modificacion = um.id
        WHERE p.estado = TRUE
          AND (
              p_busqueda = ''
              OR gen_texto_coincide(p.nombre, p_busqueda)
              OR gen_texto_coincide(COALESCE(p.descripcion, ''), p_busqueda)
          )
        ORDER BY p.nombre ASC
        LIMIT p_limite
        OFFSET p_offset
    ) t;

    RETURN json_build_object('registros', v_registros, 'total', v_total);
END;
$$;


--
-- Name: auth_listar_roles(character varying, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.auth_listar_roles(p_busqueda character varying DEFAULT ''::character varying, p_limite integer DEFAULT 10, p_offset integer DEFAULT 0) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_registros JSON;
    v_total BIGINT;
BEGIN
    SET TIME ZONE 'America/Lima';

    SELECT COUNT(*) INTO v_total
    FROM auth_roles r
    WHERE r.estado = TRUE
      AND (
          p_busqueda = ''
          OR gen_texto_coincide(r.nombre, p_busqueda)
          OR gen_texto_coincide(COALESCE(r.descripcion, ''), p_busqueda)
      );

    SELECT COALESCE(json_agg(row_to_json(t)), '[]'::JSON) INTO v_registros
    FROM (
        SELECT
            r.id,
            r.nombre,
            r.descripcion,
            r.estado,
            r.fecha_creacion,
            r.fecha_modificacion,
            r.id_usuario_creacion,
            uc.nombre AS nombre_usuario_creacion,
            r.id_usuario_modificacion,
            um.nombre AS nombre_usuario_modificacion,
            (
                SELECT COUNT(*)::BIGINT
                FROM auth_roles_permisos rp
                WHERE rp.id_rol = r.id AND rp.estado = TRUE
            ) AS cantidad_permisos,
            (
                SELECT COUNT(*)::BIGINT
                FROM auth_usuarios_roles ur
                WHERE ur.id_rol = r.id AND ur.estado = TRUE
            ) AS cantidad_usuarios
        FROM auth_roles r
        LEFT JOIN auth_usuarios uc ON r.id_usuario_creacion = uc.id
        LEFT JOIN auth_usuarios um ON r.id_usuario_modificacion = um.id
        WHERE r.estado = TRUE
          AND (
              p_busqueda = ''
              OR gen_texto_coincide(r.nombre, p_busqueda)
              OR gen_texto_coincide(COALESCE(r.descripcion, ''), p_busqueda)
          )
        ORDER BY r.nombre ASC
        LIMIT p_limite
        OFFSET p_offset
    ) t;

    RETURN json_build_object('registros', v_registros, 'total', v_total);
END;
$$;


--
-- Name: auth_listar_roles_permisos(integer, integer, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.auth_listar_roles_permisos(p_id_rol integer DEFAULT NULL::integer, p_id_permiso integer DEFAULT NULL::integer, p_limite integer DEFAULT 10, p_offset integer DEFAULT 0) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_registros JSON;
    v_total BIGINT;
BEGIN
    SET TIME ZONE 'America/Lima';

    SELECT COUNT(*) INTO v_total
    FROM auth_roles_permisos rp
    INNER JOIN auth_roles r ON rp.id_rol = r.id
    INNER JOIN auth_permisos p ON rp.id_permiso = p.id
    WHERE rp.estado = TRUE
      AND (p_id_rol IS NULL OR rp.id_rol = p_id_rol)
      AND (p_id_permiso IS NULL OR rp.id_permiso = p_id_permiso);

    SELECT COALESCE(json_agg(row_to_json(t)), '[]'::JSON) INTO v_registros
    FROM (
        SELECT
            rp.id,
            rp.id_rol,
            r.nombre AS nombre_rol,
            rp.id_permiso,
            p.nombre AS nombre_permiso,
            rp.estado,
            rp.fecha_creacion,
            rp.fecha_modificacion
        FROM auth_roles_permisos rp
        INNER JOIN auth_roles r ON rp.id_rol = r.id
        INNER JOIN auth_permisos p ON rp.id_permiso = p.id
        WHERE rp.estado = TRUE
          AND (p_id_rol IS NULL OR rp.id_rol = p_id_rol)
          AND (p_id_permiso IS NULL OR rp.id_permiso = p_id_permiso)
        ORDER BY r.nombre, p.nombre
        LIMIT p_limite
        OFFSET p_offset
    ) t;

    RETURN json_build_object('registros', v_registros, 'total', v_total);
END;
$$;


--
-- Name: auth_listar_sesiones(integer, boolean, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.auth_listar_sesiones(p_id_usuario integer DEFAULT NULL::integer, p_solo_activas boolean DEFAULT true, p_limite integer DEFAULT 10, p_offset integer DEFAULT 0) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_registros JSON;
    v_total BIGINT;
BEGIN
    SET TIME ZONE 'America/Lima';

    SELECT COUNT(*) INTO v_total
    FROM auth_sesiones s
    INNER JOIN auth_usuarios u ON s.id_usuario = u.id
    WHERE (p_id_usuario IS NULL OR s.id_usuario = p_id_usuario)
      AND (NOT p_solo_activas OR (s.estado = TRUE AND s.fecha_fin IS NULL));

    SELECT COALESCE(json_agg(row_to_json(t)), '[]'::JSON) INTO v_registros
    FROM (
        SELECT
            s.id,
            s.id_usuario,
            u.nombre AS nombre_usuario,
            u.correo,
            s.ip,
            s.user_agent,
            s.fecha_inicio,
            s.fecha_fin,
            s.estado,
            s.fecha_creacion
        FROM auth_sesiones s
        INNER JOIN auth_usuarios u ON s.id_usuario = u.id
        WHERE (p_id_usuario IS NULL OR s.id_usuario = p_id_usuario)
          AND (NOT p_solo_activas OR (s.estado = TRUE AND s.fecha_fin IS NULL))
        ORDER BY s.fecha_inicio DESC
        LIMIT p_limite
        OFFSET p_offset
    ) t;

    RETURN json_build_object('registros', v_registros, 'total', v_total);
END;
$$;


--
-- Name: auth_listar_usuarios(character varying, integer, integer, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.auth_listar_usuarios(p_busqueda character varying DEFAULT ''::character varying, p_limite integer DEFAULT 10, p_offset integer DEFAULT 0, p_estado boolean DEFAULT NULL::boolean) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_registros JSON;
    v_total BIGINT;
BEGIN
    SET TIME ZONE 'America/Lima';

    SELECT COUNT(*) INTO v_total
    FROM auth_usuarios u
    WHERE (p_estado IS NULL OR u.estado = p_estado)
      AND (
          p_busqueda = ''
          OR gen_texto_coincide(u.nombre, p_busqueda)
          OR gen_texto_coincide(u.correo, p_busqueda)
      );

    SELECT COALESCE(json_agg(row_to_json(t)), '[]'::JSON) INTO v_registros
    FROM (
        SELECT
            u.id,
            u.nombre,
            u.correo,
            u.estado,
            u.fecha_creacion,
            u.fecha_modificacion,
            (
                SELECT COALESCE(json_agg(json_build_object(
                    'id', r.id,
                    'nombre', r.nombre
                )), '[]'::JSON)
                FROM auth_usuarios_roles ur
                INNER JOIN auth_roles r ON ur.id_rol = r.id
                WHERE ur.id_usuario = u.id AND ur.estado = TRUE AND r.estado = TRUE
            ) AS roles
        FROM auth_usuarios u
        WHERE (p_estado IS NULL OR u.estado = p_estado)
          AND (
              p_busqueda = ''
              OR gen_texto_coincide(u.nombre, p_busqueda)
              OR gen_texto_coincide(u.correo, p_busqueda)
          )
        ORDER BY u.nombre ASC
        LIMIT p_limite
        OFFSET p_offset
    ) t;

    RETURN json_build_object('registros', v_registros, 'total', v_total);
END;
$$;


--
-- Name: auth_listar_usuarios_roles(integer, integer, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.auth_listar_usuarios_roles(p_id_usuario integer DEFAULT NULL::integer, p_id_rol integer DEFAULT NULL::integer, p_limite integer DEFAULT 10, p_offset integer DEFAULT 0) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_registros JSON;
    v_total BIGINT;
BEGIN
    SET TIME ZONE 'America/Lima';

    SELECT COUNT(*) INTO v_total
    FROM auth_usuarios_roles ur
    INNER JOIN auth_usuarios u ON ur.id_usuario = u.id
    INNER JOIN auth_roles r ON ur.id_rol = r.id
    WHERE ur.estado = TRUE
      AND (p_id_usuario IS NULL OR ur.id_usuario = p_id_usuario)
      AND (p_id_rol IS NULL OR ur.id_rol = p_id_rol);

    SELECT COALESCE(json_agg(row_to_json(t)), '[]'::JSON) INTO v_registros
    FROM (
        SELECT
            ur.id,
            ur.id_usuario,
            u.nombre AS nombre_usuario,
            u.correo,
            ur.id_rol,
            r.nombre AS nombre_rol,
            ur.estado,
            ur.fecha_creacion,
            ur.fecha_modificacion
        FROM auth_usuarios_roles ur
        INNER JOIN auth_usuarios u ON ur.id_usuario = u.id
        INNER JOIN auth_roles r ON ur.id_rol = r.id
        WHERE ur.estado = TRUE
          AND (p_id_usuario IS NULL OR ur.id_usuario = p_id_usuario)
          AND (p_id_rol IS NULL OR ur.id_rol = p_id_rol)
        ORDER BY u.nombre, r.nombre
        LIMIT p_limite
        OFFSET p_offset
    ) t;

    RETURN json_build_object('registros', v_registros, 'total', v_total);
END;
$$;


--
-- Name: auth_obtener_permiso(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.auth_obtener_permiso(p_id integer) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_registro JSON;
BEGIN
    SET TIME ZONE 'America/Lima';

    SELECT row_to_json(t) INTO v_registro
    FROM (
        SELECT
            p.id,
            p.nombre,
            p.descripcion,
            p.estado,
            p.fecha_creacion,
            p.fecha_modificacion,
            p.id_usuario_creacion,
            uc.nombre AS nombre_usuario_creacion,
            p.id_usuario_modificacion,
            um.nombre AS nombre_usuario_modificacion
        FROM auth_permisos p
        LEFT JOIN auth_usuarios uc ON p.id_usuario_creacion = uc.id
        LEFT JOIN auth_usuarios um ON p.id_usuario_modificacion = um.id
        WHERE p.id = p_id AND p.estado = TRUE
    ) t;

    RETURN json_build_object('registro', v_registro);
END;
$$;


--
-- Name: auth_obtener_permisos_usuario(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.auth_obtener_permisos_usuario(p_id_usuario integer) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_permisos JSON;
BEGIN
    SET TIME ZONE 'America/Lima';

    SELECT COALESCE(json_agg(DISTINCT p.nombre ORDER BY p.nombre), '[]'::JSON)
    INTO v_permisos
    FROM auth_usuarios_roles ur
    INNER JOIN auth_roles r ON ur.id_rol = r.id
    INNER JOIN auth_roles_permisos rp ON rp.id_rol = r.id
    INNER JOIN auth_permisos p ON rp.id_permiso = p.id
    WHERE ur.id_usuario = p_id_usuario
      AND ur.estado = TRUE
      AND r.estado = TRUE
      AND rp.estado = TRUE
      AND p.estado = TRUE;

    RETURN json_build_object('permisos', v_permisos);
END;
$$;


--
-- Name: auth_obtener_rol(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.auth_obtener_rol(p_id integer) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_registro JSON;
BEGIN
    SET TIME ZONE 'America/Lima';

    SELECT row_to_json(t) INTO v_registro
    FROM (
        SELECT
            r.id,
            r.nombre,
            r.descripcion,
            r.estado,
            r.fecha_creacion,
            r.fecha_modificacion,
            r.id_usuario_creacion,
            uc.nombre AS nombre_usuario_creacion,
            r.id_usuario_modificacion,
            um.nombre AS nombre_usuario_modificacion,
            (
                SELECT COALESCE(json_agg(json_build_object(
                    'id', p.id,
                    'nombre', p.nombre,
                    'descripcion', p.descripcion
                )), '[]'::JSON)
                FROM auth_roles_permisos rp
                INNER JOIN auth_permisos p ON rp.id_permiso = p.id
                WHERE rp.id_rol = r.id AND rp.estado = TRUE AND p.estado = TRUE
            ) AS permisos
        FROM auth_roles r
        LEFT JOIN auth_usuarios uc ON r.id_usuario_creacion = uc.id
        LEFT JOIN auth_usuarios um ON r.id_usuario_modificacion = um.id
        WHERE r.id = p_id AND r.estado = TRUE
    ) t;

    RETURN json_build_object('registro', v_registro);
END;
$$;


--
-- Name: auth_obtener_sesion(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.auth_obtener_sesion(p_id integer) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_registro JSON;
BEGIN
    SET TIME ZONE 'America/Lima';

    SELECT row_to_json(t) INTO v_registro
    FROM (
        SELECT
            s.id,
