    LANGUAGE plpgsql
    AS $$
BEGIN
    SET TIME ZONE 'America/Lima';

    UPDATE auth_usuarios_roles
    SET estado = FALSE,
        id_usuario_modificacion = p_id_usuario_auditoria,
        fecha_modificacion = NOW()
    WHERE id = p_id AND estado = TRUE;

    IF NOT FOUND THEN
        RETURN json_build_object('eliminado', FALSE, 'id', p_id);
    END IF;

    RETURN json_build_object('eliminado', TRUE, 'id', p_id);
END;
$$;


--
-- Name: auth_usuario_es_admin_con_permiso(integer, character varying); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.auth_usuario_es_admin_con_permiso(p_id_usuario integer, p_permiso character varying) RETURNS boolean
    LANGUAGE plpgsql STABLE
    AS $$
DECLARE
    v_ok BOOLEAN := FALSE;
BEGIN
    IF p_id_usuario IS NULL OR NULLIF(TRIM(p_permiso), '') IS NULL THEN
        RETURN FALSE;
    END IF;

    SELECT EXISTS (
        SELECT 1
        FROM auth_usuarios u
        INNER JOIN auth_usuarios_roles ur ON ur.id_usuario = u.id AND ur.estado = TRUE
        INNER JOIN auth_roles r ON r.id = ur.id_rol AND r.estado = TRUE AND r.nombre = 'Administrador'
        INNER JOIN auth_roles_permisos rp ON rp.id_rol = r.id AND rp.estado = TRUE
        INNER JOIN auth_permisos p ON p.id = rp.id_permiso AND p.estado = TRUE
        WHERE u.id = p_id_usuario
          AND u.estado = TRUE
          AND (
              p.nombre = TRIM(p_permiso)
              OR p.nombre = 'auth.todo'
          )
    )
    INTO v_ok;

    RETURN COALESCE(v_ok, FALSE);
END;
$$;


--
-- Name: auth_validar_sesion(character varying); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.auth_validar_sesion(p_token character varying) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_registro JSON;
BEGIN
    SET TIME ZONE 'America/Lima';

    SELECT row_to_json(t) INTO v_registro
    FROM (
        SELECT
            s.id,
            s.id_usuario,
            u.nombre AS nombre_usuario,
            u.correo,
            s.fecha_inicio
        FROM auth_sesiones s
        INNER JOIN auth_usuarios u ON s.id_usuario = u.id
        WHERE s.token = p_token
          AND s.estado = TRUE
          AND s.fecha_fin IS NULL
          AND u.estado = TRUE
    ) t;

    RETURN json_build_object('valida', v_registro IS NOT NULL, 'registro', v_registro);
END;
$$;


--
-- Name: bal_actualizar_alquiler(integer, character varying, integer, integer, date, date, date, numeric, numeric, integer, character varying, integer, integer, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bal_actualizar_alquiler(p_id integer, p_numero_alquiler character varying DEFAULT NULL::character varying, p_id_cliente integer DEFAULT NULL::integer, p_id_almacen integer DEFAULT NULL::integer, p_fecha_inicio date DEFAULT NULL::date, p_fecha_fin_pactada date DEFAULT NULL::date, p_fecha_fin_real date DEFAULT NULL::date, p_tarifa_diaria numeric DEFAULT NULL::numeric, p_total_cobrado numeric DEFAULT NULL::numeric, p_id_estado integer DEFAULT NULL::integer, p_observacion character varying DEFAULT NULL::character varying, p_id_comprobante_venta integer DEFAULT NULL::integer, p_id_producto_regulador integer DEFAULT NULL::integer, p_id_producto_stock integer DEFAULT NULL::integer, p_id_usuario_auditoria integer DEFAULT NULL::integer) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_numero VARCHAR;
    v_fin_real_prev DATE;
    v_numero_prev VARCHAR;
    v_almacen_prev INTEGER;
    v_fin_real DATE;
    v_producto_stock INTEGER;
    v_almacen INTEGER;
    v_mov JSON;
    v_stock_reg_ok BOOLEAN;
    v_id_mant_reg INTEGER;
BEGIN
    SET TIME ZONE 'America/Lima';

    SELECT al.fecha_fin_real, al.numero_alquiler, al.id_almacen
    INTO v_fin_real_prev, v_numero_prev, v_almacen_prev
    FROM bal_alquiler al
    WHERE al.id = p_id AND al.estado = 1;

    IF NOT FOUND THEN
        RETURN json_build_object('registro', NULL);
    END IF;

    v_numero := NULLIF(TRIM(p_numero_alquiler), '');

    IF v_numero IS NOT NULL AND EXISTS (
        SELECT 1 FROM bal_alquiler WHERE LOWER(TRIM(numero_alquiler)) = LOWER(v_numero) AND id <> p_id
    ) THEN
        RETURN json_build_object('error', 'Ya existe otro alquiler con el número ' || v_numero, 'registro', NULL);
    END IF;

    IF p_id_producto_regulador IS NOT NULL AND NOT EXISTS (
        SELECT 1
        FROM pro_producto
        WHERE id = p_id_producto_regulador
          AND estado = 1
          AND COALESCE(es_alquilable, FALSE) = TRUE
    ) THEN
        RETURN json_build_object(
            'error', 'El producto debe ser alquilable y estar activo',
            'registro', NULL
        );
    END IF;

    IF p_id_producto_stock IS NOT NULL AND NOT EXISTS (
        SELECT 1
        FROM pro_producto
        WHERE id = p_id_producto_stock
          AND estado = 1
          AND COALESCE(es_servicio, FALSE) = FALSE
          AND COALESCE(es_gas, FALSE) = FALSE
    ) THEN
        RETURN json_build_object(
            'error', 'El regulador de stock debe ser un accesorio físico activo',
            'registro', NULL
        );
    END IF;

    UPDATE bal_alquiler
    SET
        numero_alquiler = COALESCE(v_numero, numero_alquiler),
        id_cliente = COALESCE(p_id_cliente, id_cliente),
        id_almacen = COALESCE(p_id_almacen, id_almacen),
        fecha_inicio = COALESCE(p_fecha_inicio, fecha_inicio),
        fecha_fin_pactada = COALESCE(p_fecha_fin_pactada, fecha_fin_pactada),
        fecha_fin_real = COALESCE(p_fecha_fin_real, fecha_fin_real),
        tarifa_diaria = COALESCE(p_tarifa_diaria, tarifa_diaria),
        total_cobrado = COALESCE(p_total_cobrado, total_cobrado),
        id_estado = COALESCE(p_id_estado, id_estado),
        observacion = COALESCE(p_observacion, observacion),
        id_comprobante_venta = COALESCE(p_id_comprobante_venta, id_comprobante_venta),
        id_producto_regulador = COALESCE(p_id_producto_regulador, id_producto_regulador),
        id_producto_stock = COALESCE(p_id_producto_stock, id_producto_stock),
        id_usuario_modificacion = p_id_usuario_auditoria,
        fecha_modificacion = NOW()
    WHERE id = p_id AND estado = 1;

    SELECT
        fecha_fin_real,
        id_producto_stock,
        id_almacen,
        numero_alquiler,
        COALESCE(stock_regulador_reingresado, FALSE),
        id_mantenimiento_regulador
    INTO
        v_fin_real,
        v_producto_stock,
        v_almacen,
        v_numero_prev,
        v_stock_reg_ok,
        v_id_mant_reg
    FROM bal_alquiler
    WHERE id = p_id AND estado = 1;

    -- Reingreso de stock solo si aún no se hizo al devolver el regulador
    -- (BUENO → ya reingresó; PARA_REPARAR → espera fin de mantenimiento)
    IF v_fin_real_prev IS NULL
       AND v_fin_real IS NOT NULL
       AND v_producto_stock IS NOT NULL
       AND NOT COALESCE(v_stock_reg_ok, FALSE)
       AND v_id_mant_reg IS NULL
       AND EXISTS (
           SELECT 1 FROM pro_producto
           WHERE id = v_producto_stock
             AND estado = 1
             AND COALESCE(afecta_stock, FALSE) = TRUE
       )
    THEN
        v_mov := inv_registrar_movimiento(
            p_naturaleza                => 'PRODUCTO',
            p_codigo_tipo_movimiento    => 'INGRESO',
            p_fecha                     => v_fin_real,
            p_id_producto               => v_producto_stock,
            p_cantidad                  => 1,
            p_id_almacen_origen         => v_almacen,
            p_codigo_tipo_documento_origen => 'ALQUILER',
            p_id_documento_origen       => p_id,
            p_glosa                     => 'Devolución por fin de alquiler ' || v_numero_prev,
            p_id_usuario_auditoria      => p_id_usuario_auditoria
        );

        IF v_mov->>'error' IS NOT NULL THEN
            RAISE EXCEPTION '%', v_mov->>'error';
        END IF;
    END IF;

    RETURN bal_obtener_alquiler(p_id);
END;
$$;


--
-- Name: bal_actualizar_alquiler_detalle(integer, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bal_actualizar_alquiler_detalle(p_id integer, p_id_balon integer DEFAULT NULL::integer, p_id_usuario_auditoria integer DEFAULT NULL::integer) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_id_alquiler INTEGER;
    v_id_balon_actual INTEGER;
    v_fecha_devolucion DATE;
    v_id_cliente INTEGER;
    v_id_almacen INTEGER;
    v_id_estado_en_almacen INTEGER;
    v_mov JSON;
BEGIN
    SET TIME ZONE 'America/Lima';

    SELECT ad.id_alquiler, ad.id_balon, ad.fecha_devolucion, al.id_cliente, al.id_almacen
    INTO v_id_alquiler, v_id_balon_actual, v_fecha_devolucion, v_id_cliente, v_id_almacen
    FROM bal_alquiler_detalle ad
    INNER JOIN bal_alquiler al ON al.id = ad.id_alquiler AND al.estado = 1
    WHERE ad.id = p_id AND ad.estado = 1;

    IF v_id_alquiler IS NULL THEN
        RETURN json_build_object('registro', NULL);
    END IF;

    IF p_id_balon IS NOT NULL AND p_id_balon <> v_id_balon_actual THEN
        IF v_fecha_devolucion IS NOT NULL THEN
            RETURN json_build_object(
                'error', 'No se puede cambiar el cilindro de un detalle ya devuelto',
                'registro', NULL
            );
        END IF;

        IF NOT EXISTS (SELECT 1 FROM bal_balon WHERE id = p_id_balon AND estado = 1) THEN
            RETURN json_build_object('error', 'El balón indicado no existe o está inactivo', 'registro', NULL);
        END IF;

        IF EXISTS (
            SELECT 1
            FROM bal_balon b
            LEFT JOIN gen_lista_opciones eb ON eb.id = b.id_estado_balon
            WHERE b.id = p_id_balon
              AND COALESCE(eb.nombre, '') IN ('DADO_DE_BAJA', 'ROBO')
        ) THEN
            RETURN json_build_object(
                'error', 'No se puede alquilar un cilindro dado de baja o reportado como robo',
                'registro', NULL
            );
        END IF;

        IF EXISTS (
            SELECT 1 FROM bal_alquiler_detalle
            WHERE id_alquiler = v_id_alquiler AND id_balon = p_id_balon AND id <> p_id AND estado = 1
        ) THEN
            RETURN json_build_object('error', 'El balón ya está registrado en este alquiler', 'registro', NULL);
        END IF;

        IF EXISTS (
            SELECT 1
            FROM bal_alquiler_detalle ad
            INNER JOIN bal_alquiler al ON al.id = ad.id_alquiler AND al.estado = 1
            WHERE ad.id_balon = p_id_balon
              AND ad.id <> p_id
              AND ad.estado = 1
              AND ad.fecha_devolucion IS NULL
        ) THEN
            RETURN json_build_object(
                'error', 'El cilindro ya tiene un alquiler activo sin devolver',
                'registro', NULL
            );
        END IF;

        IF EXISTS (
            SELECT 1
            FROM bal_prestamo_detalle pd
            INNER JOIN bal_prestamo p2 ON p2.id = pd.id_prestamo AND p2.estado = 1
            WHERE pd.id_balon = p_id_balon
              AND pd.estado = 1
              AND pd.fecha_devolucion IS NULL
        ) THEN
            RETURN json_build_object(
                'error', 'El cilindro está prestado actualmente; no se puede alquilar',
                'registro', NULL
            );
        END IF;

        SELECT lo.id INTO v_id_estado_en_almacen
        FROM gen_lista_opciones lo
        INNER JOIN gen_lista l ON lo.id_lista = l.id
        WHERE l.nombre = 'EstadoBalon' AND lo.nombre = 'EN_ALMACEN' AND lo.estado = 1
        LIMIT 1;

        IF v_id_estado_en_almacen IS NULL THEN
            RETURN json_build_object(
                'error', 'Faltan estados ALQUILADO / EN_ALMACEN en el catálogo EstadoBalon',
                'registro', NULL
            );
        END IF;

        IF v_id_almacen IS NULL THEN
            RETURN json_build_object(
                'error', 'El alquiler no tiene almacén para devolver el cilindro anterior',
                'registro', NULL
            );
        END IF;

        v_mov := inv_registrar_movimiento(
            p_naturaleza                => 'BALON',
            p_codigo_tipo_movimiento    => 'ENTRADA_DEVOLUCION',
            p_fecha                     => NOW(),
            p_id_balon                  => v_id_balon_actual,
            p_cantidad                  => 1,
            p_id_almacen_destino        => v_id_almacen,
            p_id_cliente                => v_id_cliente,
            p_codigo_tipo_documento_origen => 'ALQUILER',
            p_id_documento_origen       => v_id_alquiler,
            p_glosa                     => 'Retorno por cambio de cilindro en alquiler',
            p_id_usuario_auditoria      => p_id_usuario_auditoria
        );
        IF v_mov->>'error' IS NOT NULL THEN
            RAISE EXCEPTION '%', v_mov->>'error';
        END IF;

        -- inv_registrar_movimiento ya deja el balón devuelto en EN_ALMACEN/v_id_almacen
        -- (mapeo ENTRADA_DEVOLUCION), no hace falta repetirlo aquí.

        v_mov := inv_registrar_movimiento(
            p_naturaleza                => 'BALON',
            p_codigo_tipo_movimiento    => 'SALIDA_ALQUILER',
            p_fecha                     => NOW(),
            p_id_balon                  => p_id_balon,
            p_cantidad                  => 1,
            p_id_almacen_origen         => v_id_almacen,
            p_id_cliente                => v_id_cliente,
            p_codigo_tipo_documento_origen => 'ALQUILER',
            p_id_documento_origen       => v_id_alquiler,
            p_glosa                     => 'Salida por cambio de cilindro en alquiler',
            p_id_usuario_auditoria      => p_id_usuario_auditoria
        );
        IF v_mov->>'error' IS NOT NULL THEN
            RAISE EXCEPTION '%', v_mov->>'error';
        END IF;

        -- inv_registrar_movimiento ya deja el balón nuevo en ALQUILADO/v_id_cliente
        -- (mapeo SALIDA_ALQUILER), no hace falta repetirlo aquí.

    END IF;

    UPDATE bal_alquiler_detalle
    SET
        id_balon = COALESCE(p_id_balon, id_balon),
        id_usuario_modificacion = p_id_usuario_auditoria,
        fecha_modificacion = NOW()
    WHERE id = p_id AND estado = 1;

    IF NOT FOUND THEN
        RETURN json_build_object('registro', NULL);
    END IF;

    RETURN bal_obtener_alquiler_detalle(p_id);
END;
$$;


--
-- Name: bal_actualizar_balon(integer, character varying, character varying, integer, date, integer, integer, integer, integer, integer, integer, integer, integer, date, integer, date, date, character varying, numeric, character varying, character varying, integer, integer, boolean, smallint, smallint, integer, character varying, numeric, character varying, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bal_actualizar_balon(p_id integer, p_codigo_balon character varying DEFAULT NULL::character varying, p_libro_cilindro character varying DEFAULT NULL::character varying, p_pagina_libro integer DEFAULT NULL::integer, p_fecha_registro date DEFAULT NULL::date, p_id_almacen integer DEFAULT NULL::integer, p_id_cliente_ubicacion integer DEFAULT NULL::integer, p_id_propietario integer DEFAULT NULL::integer, p_id_cliente_propietario integer DEFAULT NULL::integer, p_id_referencia integer DEFAULT NULL::integer, p_id_tipo_balon integer DEFAULT NULL::integer, p_id_producto_gas integer DEFAULT NULL::integer, p_id_estado_balon integer DEFAULT NULL::integer, p_fecha_ultima_prueba_hidrostatica date DEFAULT NULL::date, p_vigencia_prueba_hidrostatica_anios integer DEFAULT NULL::integer, p_fecha_proxima_prueba_hidrostatica date DEFAULT NULL::date, p_fecha_fabricacion date DEFAULT NULL::date, p_numero_recepcion character varying DEFAULT NULL::character varying, p_presion_actual numeric DEFAULT NULL::numeric, p_observacion character varying DEFAULT NULL::character varying, p_numero_serie character varying DEFAULT NULL::character varying, p_id_marca_cilindro integer DEFAULT NULL::integer, p_id_organo_inspector integer DEFAULT NULL::integer, p_organo_inspector_no_aplica boolean DEFAULT NULL::boolean, p_anio_fabricacion smallint DEFAULT NULL::smallint, p_mes_fabricacion smallint DEFAULT NULL::smallint, p_id_planta integer DEFAULT NULL::integer, p_tipo_valvula character varying DEFAULT NULL::character varying, p_peso_aproximado_kg numeric DEFAULT NULL::numeric, p_sello_inspeccion character varying DEFAULT NULL::character varying, p_id_usuario_auditoria integer DEFAULT NULL::integer) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_codigo VARCHAR;
    v_numero_serie VARCHAR;
    v_anio_fabricacion SMALLINT;
    v_mes_fabricacion SMALLINT;
    v_fecha_fabricacion DATE;
    v_fecha_ultima_ph DATE;
    v_vigencia_ph INTEGER;
    v_fecha_proxima_ph DATE;
    v_id_tipo_balon INTEGER;
    v_tiene_historial_ph BOOLEAN;
    v_id_propietario INTEGER;
    v_prop_nombre VARCHAR;
    v_id_planta INTEGER;
    v_id_cliente_propietario INTEGER;
BEGIN
    SET TIME ZONE 'America/Lima';

    IF p_mes_fabricacion IS NOT NULL AND (p_mes_fabricacion < 1 OR p_mes_fabricacion > 12) THEN
        RETURN json_build_object('error', 'El mes de fabricación debe estar entre 1 y 12', 'registro', NULL);
    END IF;

    IF p_id_planta IS NOT NULL AND NOT EXISTS (
        SELECT 1 FROM cli_clientes WHERE id = p_id_planta AND estado = 1
    ) THEN
        RETURN json_build_object('error', 'La planta / proveedor indicado no existe o está inactivo', 'registro', NULL);
    END IF;

    v_codigo := NULLIF(TRIM(p_codigo_balon), '');

    IF v_codigo IS NOT NULL AND EXISTS (
        SELECT 1 FROM bal_balon
        WHERE LOWER(TRIM(codigo_balon)) = LOWER(v_codigo) AND id <> p_id
    ) THEN
        RETURN json_build_object('error', 'Ya existe otro balón con el código ' || v_codigo, 'registro', NULL);
    END IF;

    SELECT
        COALESCE(p_anio_fabricacion, anio_fabricacion),
        COALESCE(p_mes_fabricacion, mes_fabricacion),
        COALESCE(p_fecha_fabricacion, fecha_fabricacion),
        COALESCE(p_fecha_ultima_prueba_hidrostatica, fecha_ultima_prueba_hidrostatica),
        COALESCE(p_vigencia_prueba_hidrostatica_anios, vigencia_prueba_hidrostatica_anios, 5),
        COALESCE(p_id_tipo_balon, id_tipo_balon),
        EXISTS (
            SELECT 1 FROM bal_balon_ph_historial h
            WHERE h.id_balon = bal_balon.id AND h.estado = 1
              AND COALESCE(h.observacion, '') NOT ILIKE 'PH calculado desde fabricación%'
        )
    INTO
        v_anio_fabricacion,
        v_mes_fabricacion,
        v_fecha_fabricacion,
        v_fecha_ultima_ph,
        v_vigencia_ph,
        v_id_tipo_balon,
        v_tiene_historial_ph
    FROM bal_balon
    WHERE id = p_id AND estado = 1;

    IF NOT FOUND THEN
        RETURN json_build_object('registro', NULL);
    END IF;

    -- Resolver propietario final y reglas PLANTA / CLIENTE.
    SELECT COALESCE(p_id_propietario, b.id_propietario)
    INTO v_id_propietario
    FROM bal_balon b
    WHERE b.id = p_id AND b.estado = 1;

    SELECT UPPER(glo.nombre) INTO v_prop_nombre
    FROM gen_lista_opciones glo
    WHERE glo.id = v_id_propietario;

    IF v_prop_nombre = 'PLANTA' THEN
        SELECT COALESCE(p_id_planta, b.id_planta)
        INTO v_id_planta
        FROM bal_balon b
        WHERE b.id = p_id AND b.estado = 1;

        -- Si el payload viene con propietario PLANTA y planta explícitamente vacía (formulario completo),
        -- exigir planta. Detectamos "intención de actualizar planta" cuando llega p_id_propietario
        -- o cuando p_id_planta no es null.
        IF p_id_propietario IS NOT NULL AND p_id_planta IS NULL THEN
            -- Cambio de propietario a PLANTA (o reenvío del form) sin planta: no heredar de otro tipo.
            SELECT CASE
                WHEN UPPER(COALESCE(prop.nombre, '')) = 'PLANTA' THEN b.id_planta
                ELSE NULL
            END
            INTO v_id_planta
            FROM bal_balon b
            LEFT JOIN gen_lista_opciones prop ON prop.id = b.id_propietario
            WHERE b.id = p_id AND b.estado = 1;
        END IF;

        IF v_id_planta IS NULL THEN
            RETURN json_build_object(
                'error', 'Si el propietario es planta, debe indicar el proveedor concreto (ej. Swiss Gas)',
                'registro', NULL
            );
        END IF;
        v_id_cliente_propietario := NULL;
    ELSIF v_prop_nombre = 'CLIENTE' THEN
        SELECT COALESCE(p_id_cliente_propietario, b.id_cliente_propietario)
        INTO v_id_cliente_propietario
        FROM bal_balon b
        WHERE b.id = p_id AND b.estado = 1;

        IF p_id_propietario IS NOT NULL AND p_id_cliente_propietario IS NULL THEN
            SELECT CASE
                WHEN UPPER(COALESCE(prop.nombre, '')) = 'CLIENTE' THEN b.id_cliente_propietario
                ELSE NULL
            END
            INTO v_id_cliente_propietario
            FROM bal_balon b
            LEFT JOIN gen_lista_opciones prop ON prop.id = b.id_propietario
            WHERE b.id = p_id AND b.estado = 1;
        END IF;

        IF v_id_cliente_propietario IS NULL THEN
            RETURN json_build_object(
                'error', 'Si el propietario es cliente, debe indicar el cliente propietario',
                'registro', NULL
            );
        END IF;
        v_id_planta := NULL;
    ELSE
        v_id_planta := NULL;
        v_id_cliente_propietario := NULL;
    END IF;

    IF v_id_tipo_balon IS NULL THEN
        RETURN json_build_object('error', 'El tipo de balón es obligatorio', 'registro', NULL);
    END IF;

    IF NOT EXISTS (
        SELECT 1 FROM bal_tipo_balon WHERE id = v_id_tipo_balon AND estado = 1
    ) THEN
        RETURN json_build_object('error', 'El tipo de balón indicado no existe o está inactivo', 'registro', NULL);
    END IF;

    IF COALESCE(p_id_producto_gas, (
        SELECT id_producto_gas FROM bal_balon WHERE id = p_id
    )) IS NULL THEN
        RETURN json_build_object('error', 'El gas (producto) es obligatorio', 'registro', NULL);
    END IF;

    IF NOT EXISTS (
        SELECT 1 FROM pro_producto
        WHERE id = COALESCE(p_id_producto_gas, (
            SELECT id_producto_gas FROM bal_balon WHERE id = p_id
        ))
          AND estado = 1
          AND es_gas = TRUE
    ) THEN
        RETURN json_build_object(
            'error',
            'El gas indicado no existe, está inactivo o no es un producto de gas',
            'registro',
            NULL
        );
    END IF;

    IF v_anio_fabricacion IS NOT NULL AND v_mes_fabricacion IS NOT NULL THEN
        v_fecha_fabricacion := make_date(v_anio_fabricacion::INT, v_mes_fabricacion::INT, 1);
    ELSIF v_fecha_fabricacion IS NOT NULL THEN
        v_fecha_fabricacion := make_date(
            EXTRACT(YEAR FROM v_fecha_fabricacion)::INT,
            EXTRACT(MONTH FROM v_fecha_fabricacion)::INT,
            1
        );
        v_anio_fabricacion := COALESCE(v_anio_fabricacion, EXTRACT(YEAR FROM v_fecha_fabricacion)::SMALLINT);
        v_mes_fabricacion := COALESCE(v_mes_fabricacion, EXTRACT(MONTH FROM v_fecha_fabricacion)::SMALLINT);
    END IF;

    IF v_id_tipo_balon IS NOT NULL THEN
        SELECT COALESCE(p_vigencia_prueba_hidrostatica_anios, tb.vigencia_ph_anios, v_vigencia_ph, 5)
        INTO v_vigencia_ph
        FROM bal_tipo_balon tb
        WHERE tb.id = v_id_tipo_balon;
    END IF;

    -- Recalcular PH desde fabricación solo si no hay historial real de pruebas
    IF p_fecha_ultima_prueba_hidrostatica IS NOT NULL THEN
        v_fecha_ultima_ph := make_date(
            EXTRACT(YEAR FROM p_fecha_ultima_prueba_hidrostatica)::INT,
            EXTRACT(MONTH FROM p_fecha_ultima_prueba_hidrostatica)::INT,
            1
        );
    ELSIF NOT v_tiene_historial_ph AND v_fecha_fabricacion IS NOT NULL THEN
        v_fecha_ultima_ph := v_fecha_fabricacion;
    ELSIF v_fecha_ultima_ph IS NOT NULL THEN
        v_fecha_ultima_ph := make_date(
            EXTRACT(YEAR FROM v_fecha_ultima_ph)::INT,
            EXTRACT(MONTH FROM v_fecha_ultima_ph)::INT,
            1
        );
    END IF;

    v_fecha_proxima_ph := COALESCE(
        CASE
            WHEN p_fecha_proxima_prueba_hidrostatica IS NOT NULL
            THEN make_date(
                EXTRACT(YEAR FROM p_fecha_proxima_prueba_hidrostatica)::INT,
                EXTRACT(MONTH FROM p_fecha_proxima_prueba_hidrostatica)::INT,
                1
            )
        END,
        CASE
            WHEN v_fecha_ultima_ph IS NOT NULL
            THEN (v_fecha_ultima_ph + make_interval(years => v_vigencia_ph))::DATE
        END
    );

    v_numero_serie := COALESCE(NULLIF(TRIM(p_numero_serie), ''), v_codigo);

    UPDATE bal_balon
    SET
        codigo_balon = COALESCE(v_codigo, codigo_balon),
        numero_serie = COALESCE(v_numero_serie, numero_serie),
        libro_cilindro = COALESCE(p_libro_cilindro, libro_cilindro),
        pagina_libro = COALESCE(p_pagina_libro, pagina_libro),
        fecha_registro = COALESCE(p_fecha_registro, fecha_registro),
        id_almacen = COALESCE(p_id_almacen, id_almacen),
        id_cliente_ubicacion = COALESCE(p_id_cliente_ubicacion, id_cliente_ubicacion),
        id_propietario = COALESCE(p_id_propietario, id_propietario),
        id_cliente_propietario = v_id_cliente_propietario,
        id_referencia = COALESCE(p_id_referencia, id_referencia),
        id_marca_cilindro = COALESCE(p_id_marca_cilindro, id_marca_cilindro),
        id_organo_inspector = COALESCE(p_id_organo_inspector, id_organo_inspector),
        organo_inspector_no_aplica = COALESCE(p_organo_inspector_no_aplica, organo_inspector_no_aplica),
        id_tipo_balon = COALESCE(p_id_tipo_balon, id_tipo_balon),
        id_producto_gas = COALESCE(p_id_producto_gas, id_producto_gas),
        id_estado_balon = COALESCE(p_id_estado_balon, id_estado_balon),
        id_planta = v_id_planta,
        fecha_ultima_prueba_hidrostatica = COALESCE(v_fecha_ultima_ph, fecha_ultima_prueba_hidrostatica),
        vigencia_prueba_hidrostatica_anios = COALESCE(v_vigencia_ph, vigencia_prueba_hidrostatica_anios),
        fecha_proxima_prueba_hidrostatica = COALESCE(v_fecha_proxima_ph, fecha_proxima_prueba_hidrostatica),
        fecha_fabricacion = COALESCE(v_fecha_fabricacion, fecha_fabricacion),
        anio_fabricacion = COALESCE(v_anio_fabricacion, anio_fabricacion),
        mes_fabricacion = COALESCE(v_mes_fabricacion, mes_fabricacion),
        numero_recepcion = COALESCE(p_numero_recepcion, numero_recepcion),
        presion_actual = COALESCE(p_presion_actual, presion_actual),
        observacion = COALESCE(p_observacion, observacion),
        tipo_valvula = CASE
            WHEN p_tipo_valvula IS NULL THEN tipo_valvula
            ELSE NULLIF(TRIM(p_tipo_valvula), '')
        END,
        peso_aproximado_kg = COALESCE(p_peso_aproximado_kg, peso_aproximado_kg),
        sello_inspeccion = CASE
            WHEN p_sello_inspeccion IS NULL THEN sello_inspeccion
            ELSE NULLIF(TRIM(p_sello_inspeccion), '')
        END,
        id_usuario_modificacion = p_id_usuario_auditoria,
        fecha_modificacion = NOW()
    WHERE id = p_id AND estado = 1;

    IF NOT FOUND THEN
        RETURN json_build_object('registro', NULL);
    END IF;

    RETURN bal_obtener_balon(p_id);
END;
$$;


--
-- Name: bal_actualizar_mantenimiento(integer, integer, date, date, character varying, numeric, boolean, integer, integer, integer, integer, character varying, integer, integer, integer, boolean, character varying); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bal_actualizar_mantenimiento(p_id integer, p_id_tipo_mantenimiento integer DEFAULT NULL::integer, p_fecha_ingreso date DEFAULT NULL::date, p_fecha_salida date DEFAULT NULL::date, p_descripcion character varying DEFAULT NULL::character varying, p_costo numeric DEFAULT NULL::numeric, p_es_externo boolean DEFAULT NULL::boolean, p_id_proveedor integer DEFAULT NULL::integer, p_id_estado integer DEFAULT NULL::integer, p_id_comprobante_venta integer DEFAULT NULL::integer, p_id_comprobante_compra integer DEFAULT NULL::integer, p_observacion character varying DEFAULT NULL::character varying, p_id_usuario_auditoria integer DEFAULT NULL::integer, p_vigencia_ph_anios integer DEFAULT NULL::integer, p_id_organo_inspector integer DEFAULT NULL::integer, p_organo_inspector_no_aplica boolean DEFAULT NULL::boolean, p_numero_certificado_ph character varying DEFAULT NULL::character varying) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_id_estado_finalizado INTEGER;
    v_nombre_estado_actual VARCHAR;
BEGIN
    SET TIME ZONE 'America/Lima';

    SELECT em.nombre
    INTO v_nombre_estado_actual
    FROM bal_mantenimiento m
    LEFT JOIN gen_lista_opciones em ON em.id = m.id_estado
    WHERE m.id = p_id AND m.estado = 1;

    IF NOT FOUND THEN
        RETURN json_build_object('registro', NULL);
    END IF;

    IF UPPER(COALESCE(v_nombre_estado_actual, '')) = 'FINALIZADO' THEN
        RETURN json_build_object(
            'error', 'El mantenimiento finalizado no se puede editar. Use Finalizar solo para cerrar el ciclo.',
            'registro', NULL
        );
    END IF;

    SELECT lo.id INTO v_id_estado_finalizado
    FROM gen_lista_opciones lo
    INNER JOIN gen_lista l ON lo.id_lista = l.id
    WHERE l.nombre = 'EstadoMantenimiento' AND lo.nombre = 'FINALIZADO' AND lo.estado = 1
    LIMIT 1;

    IF v_id_estado_finalizado IS NOT NULL
       AND p_id_estado IS NOT NULL
       AND p_id_estado = v_id_estado_finalizado THEN
        RETURN json_build_object(
            'error', 'Para marcar como finalizado use la acción Finalizar (reingresa el cilindro).',
            'registro', NULL
        );
    END IF;

    UPDATE bal_mantenimiento
    SET
        id_tipo_mantenimiento = COALESCE(p_id_tipo_mantenimiento, id_tipo_mantenimiento),
        fecha_ingreso = COALESCE(p_fecha_ingreso, fecha_ingreso),
        fecha_salida = COALESCE(p_fecha_salida, fecha_salida),
        descripcion = COALESCE(p_descripcion, descripcion),
        costo = COALESCE(p_costo, costo),
        es_externo = COALESCE(p_es_externo, es_externo),
        id_proveedor = COALESCE(p_id_proveedor, id_proveedor),
        id_estado = COALESCE(p_id_estado, id_estado),
        id_comprobante_venta = COALESCE(p_id_comprobante_venta, id_comprobante_venta),
        id_comprobante_compra = COALESCE(p_id_comprobante_compra, id_comprobante_compra),
        observacion = COALESCE(p_observacion, observacion),
        id_usuario_modificacion = p_id_usuario_auditoria,
        fecha_modificacion = NOW()
    WHERE id = p_id AND estado = 1;

    IF NOT FOUND THEN
        RETURN json_build_object('registro', NULL);
    END IF;

    PERFORM bal_sync_ph_desde_mantenimiento(
        p_id,
        p_id_usuario_auditoria,
        p_vigencia_ph_anios,
        p_id_organo_inspector,
        p_organo_inspector_no_aplica,
        p_numero_certificado_ph
    );

    RETURN bal_obtener_mantenimiento(p_id);
END;
$$;


--
-- Name: bal_actualizar_movimiento_recarga(integer, date, integer, numeric, integer, character varying, character varying, character varying, character varying, character varying, character varying, integer, date, character varying, date, date, integer, character varying, integer, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bal_actualizar_movimiento_recarga(p_id integer, p_fecha_salida_almacen date DEFAULT NULL::date, p_id_producto integer DEFAULT NULL::integer, p_capacidad numeric DEFAULT NULL::numeric, p_id_unidad_medida integer DEFAULT NULL::integer, p_serie_guia_salida character varying DEFAULT NULL::character varying, p_numero_guia_salida character varying DEFAULT NULL::character varying, p_serie_guia_ingreso character varying DEFAULT NULL::character varying, p_numero_guia_ingreso character varying DEFAULT NULL::character varying, p_serie_factura character varying DEFAULT NULL::character varying, p_numero_factura character varying DEFAULT NULL::character varying, p_id_comprobante integer DEFAULT NULL::integer, p_fecha_llegada_almacen date DEFAULT NULL::date, p_lote character varying DEFAULT NULL::character varying, p_fecha_vencimiento_lote date DEFAULT NULL::date, p_fecha_prueba_hidrostatica date DEFAULT NULL::date, p_id_proveedor integer DEFAULT NULL::integer, p_observacion character varying DEFAULT NULL::character varying, p_id_almacen integer DEFAULT NULL::integer, p_id_comprobante_compra integer DEFAULT NULL::integer, p_id_usuario_auditoria integer DEFAULT NULL::integer) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_id_balon INTEGER;
    v_fecha_llegada_antes DATE;
    v_fecha_llegada DATE;
    v_id_producto INTEGER;
    v_id_almacen INTEGER;
    v_id_proveedor INTEGER;
    v_capacidad_tipo NUMERIC;
    v_id_estado_en_almacen INTEGER;
    v_id_documento_ref INTEGER;
    v_id_compra INTEGER;
    v_mov JSON;
    v_obs VARCHAR;
    v_ya_tiene_entrada BOOLEAN;
    v_capacidad NUMERIC;
BEGIN
    SET TIME ZONE 'America/Lima';

    IF p_id_comprobante_compra IS NOT NULL AND NOT EXISTS (
        SELECT 1 FROM com_comprobante_compra WHERE id = p_id_comprobante_compra AND estado = 1
    ) THEN
        RETURN json_build_object(
            'error',
            'El comprobante de compra indicado no existe o está inactivo',
            'registro',
            NULL
        );
    END IF;

    SELECT fecha_llegada_almacen
    INTO v_fecha_llegada_antes
    FROM bal_movimiento_recarga
    WHERE id = p_id AND estado = 1;

    IF NOT FOUND THEN
        RETURN json_build_object('registro', NULL);
    END IF;

    UPDATE bal_movimiento_recarga
    SET
        fecha_salida_almacen = COALESCE(p_fecha_salida_almacen, fecha_salida_almacen),
        id_producto = COALESCE(p_id_producto, id_producto),
        capacidad = COALESCE(p_capacidad, capacidad),
        id_unidad_medida = COALESCE(p_id_unidad_medida, id_unidad_medida),
        serie_guia_salida = COALESCE(p_serie_guia_salida, serie_guia_salida),
        numero_guia_salida = COALESCE(p_numero_guia_salida, numero_guia_salida),
        serie_guia_ingreso = COALESCE(p_serie_guia_ingreso, serie_guia_ingreso),
        numero_guia_ingreso = COALESCE(p_numero_guia_ingreso, numero_guia_ingreso),
        serie_factura = COALESCE(p_serie_factura, serie_factura),
        numero_factura = COALESCE(p_numero_factura, numero_factura),
        id_comprobante = COALESCE(p_id_comprobante, id_comprobante),
        id_comprobante_compra = COALESCE(p_id_comprobante_compra, id_comprobante_compra),
        fecha_llegada_almacen = COALESCE(p_fecha_llegada_almacen, fecha_llegada_almacen),
        lote = CASE
            WHEN p_lote IS NOT NULL THEN NULLIF(TRIM(p_lote), '')
            ELSE lote
        END,
        fecha_vencimiento_lote = COALESCE(p_fecha_vencimiento_lote, fecha_vencimiento_lote),
        fecha_prueba_hidrostatica = COALESCE(p_fecha_prueba_hidrostatica, fecha_prueba_hidrostatica),
        id_proveedor = COALESCE(p_id_proveedor, id_proveedor),
        observacion = COALESCE(p_observacion, observacion),
        id_almacen = COALESCE(p_id_almacen, id_almacen),
        id_usuario_modificacion = p_id_usuario_auditoria,
        fecha_modificacion = NOW()
    WHERE id = p_id AND estado = 1
    RETURNING id_balon, fecha_llegada_almacen, id_producto, id_almacen, id_proveedor, observacion, capacidad
    INTO v_id_balon, v_fecha_llegada, v_id_producto, v_id_almacen, v_id_proveedor, v_obs, v_capacidad;

    IF NOT FOUND THEN
        RETURN json_build_object('registro', NULL);
    END IF;

    IF v_fecha_llegada IS NOT NULL AND v_id_balon IS NOT NULL THEN
        SELECT lo.id INTO v_id_estado_en_almacen
        FROM gen_lista_opciones lo
        INNER JOIN gen_lista l ON lo.id_lista = l.id
        WHERE l.nombre = 'EstadoBalon' AND lo.nombre = 'EN_ALMACEN' AND lo.estado = 1
        LIMIT 1;

        IF v_id_estado_en_almacen IS NULL THEN
            RETURN json_build_object(
                'error',
                'No se encontró el estado EN_ALMACEN del cilindro. Revise el catálogo EstadoBalon.',
                'registro',
                NULL
            );
        END IF;

        SELECT COALESCE(tb.capacidad, p_capacidad, 0)
        INTO v_capacidad_tipo
        FROM bal_balon b
        LEFT JOIN bal_tipo_balon tb ON tb.id = b.id_tipo_balon
        WHERE b.id = v_id_balon;

        UPDATE bal_balon
        SET
            id_estado_balon = v_id_estado_en_almacen,
            id_almacen = COALESCE(v_id_almacen, id_almacen),
            id_producto_gas = COALESCE(v_id_producto, id_producto_gas),
            id_usuario_modificacion = p_id_usuario_auditoria,
            fecha_modificacion = NOW()
        WHERE id = v_id_balon AND estado = 1;

        -- Primera vez que se registra llegada: movimiento de entrada.
        -- Si ya hay compra vinculada, el documento de referencia es COMPRA (no GRE/RECARGA).
        IF v_fecha_llegada_antes IS NULL THEN
            SELECT COALESCE(p_id_comprobante_compra, id_comprobante_compra)
            INTO v_id_compra
            FROM bal_movimiento_recarga
            WHERE id = p_id;

            IF v_id_compra IS NOT NULL THEN
                v_id_documento_ref := v_id_compra;
            ELSE
                v_id_documento_ref := p_id;
            END IF;

            SELECT EXISTS (
                SELECT 1
                FROM inv_movimiento m
                INNER JOIN gen_lista_opciones tm ON tm.id = m.id_tipo_movimiento
                WHERE m.estado = 1
                  AND m.naturaleza = 'BALON'
                  AND m.id_balon = v_id_balon
                  AND tm.nombre = 'ENTRADA_PLANTA_EXTERNA'
                  AND (
                    m.id_documento_origen = p_id
                    OR (v_id_compra IS NOT NULL AND m.id_documento_origen = v_id_compra)
                  )
            ) INTO v_ya_tiene_entrada;

            IF NOT COALESCE(v_ya_tiene_entrada, FALSE) THEN
                v_mov := inv_registrar_movimiento(
                    p_naturaleza                => 'BALON',
                    p_codigo_tipo_movimiento    => 'ENTRADA_PLANTA_EXTERNA',
                    p_fecha                     => v_fecha_llegada,
                    p_id_producto               => v_id_producto,
                    p_id_balon                  => v_id_balon,
                    p_cantidad                  => COALESCE(v_capacidad, 1),
                    p_id_almacen_destino        => v_id_almacen,
                    p_id_cliente                => v_id_proveedor,
                    p_codigo_tipo_documento_origen => CASE
                        WHEN v_id_compra IS NOT NULL THEN 'COMPRA'
                        ELSE 'RECARGA'
                    END,
                    p_id_documento_origen       => v_id_documento_ref,
                    p_glosa                     => COALESCE(
                        NULLIF(TRIM(v_obs), ''),
                        CASE
                            WHEN v_id_compra IS NOT NULL THEN 'Retorno planta externa (compra #' || v_id_compra || ')'
                            ELSE 'Retorno planta externa'
                        END
                    ),
                    p_id_usuario_auditoria      => p_id_usuario_auditoria
                );
                IF v_mov->>'error' IS NOT NULL THEN
                    RETURN json_build_object('error', v_mov->>'error', 'registro', NULL);
                END IF;
            END IF;
        ELSIF p_id_comprobante_compra IS NOT NULL THEN
            -- Compra vinculada después de la entrada: reapunta el kardex a COMPRA.
            v_mov := inv_repuntar_documento(
                p_codigo_tipo_documento_origen_actual => 'RECARGA',
                p_id_documento_origen_actual          => p_id,
                p_codigo_tipo_documento_origen_nuevo  => 'COMPRA',
                p_id_documento_origen_nuevo           => p_id_comprobante_compra,
                p_id_usuario_auditoria                => p_id_usuario_auditoria
            );
        END IF;
    END IF;

    -- Idempotente: solo inserta en bal_balon_ph_historial si hay P.H. y aún no hay fila para este movimiento.
    PERFORM bal_sync_ph_desde_recarga(p_id, p_id_usuario_auditoria);

    RETURN bal_obtener_movimiento_recarga(p_id);
END;
$$;


--
-- Name: bal_actualizar_prestamo(integer, character varying, integer, integer, integer, integer, date, date, date, character varying, character varying, integer, integer, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bal_actualizar_prestamo(p_id integer, p_numero_prestamo character varying DEFAULT NULL::character varying, p_id_tipo_prestamo integer DEFAULT NULL::integer, p_id_cliente integer DEFAULT NULL::integer, p_id_proveedor integer DEFAULT NULL::integer, p_id_almacen integer DEFAULT NULL::integer, p_fecha_salida date DEFAULT NULL::date, p_fecha_retorno_pactada date DEFAULT NULL::date, p_fecha_retorno_real date DEFAULT NULL::date, p_titulo character varying DEFAULT NULL::character varying, p_observacion character varying DEFAULT NULL::character varying, p_id_estado integer DEFAULT NULL::integer, p_id_comprobante_venta integer DEFAULT NULL::integer, p_id_comprobante_compra integer DEFAULT NULL::integer, p_id_usuario_auditoria integer DEFAULT NULL::integer) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_numero VARCHAR;
    v_id_cliente_actual INTEGER;
    v_pendientes INTEGER;
    v_nombre_estado_nuevo VARCHAR;
BEGIN
    SET TIME ZONE 'America/Lima';

    v_numero := NULLIF(TRIM(p_numero_prestamo), '');

    IF v_numero IS NOT NULL AND EXISTS (
        SELECT 1 FROM bal_prestamo WHERE numero_prestamo = v_numero AND id <> p_id
    ) THEN
        RETURN json_build_object('error', 'Ya existe otro préstamo con el número ' || v_numero, 'registro', NULL);
    END IF;

    SELECT id_cliente INTO v_id_cliente_actual
    FROM bal_prestamo
    WHERE id = p_id AND estado = 1;

    IF NOT FOUND THEN
        RETURN json_build_object('registro', NULL);
    END IF;

    SELECT COUNT(*) INTO v_pendientes
    FROM bal_prestamo_detalle
    WHERE id_prestamo = p_id AND estado = 1 AND fecha_devolucion IS NULL;

    IF p_id_estado IS NOT NULL THEN
        SELECT lo.nombre INTO v_nombre_estado_nuevo
        FROM gen_lista_opciones lo
        WHERE lo.id = p_id_estado AND lo.estado = 1;
    END IF;

    IF COALESCE(v_pendientes, 0) > 0
       AND (
           UPPER(COALESCE(v_nombre_estado_nuevo, '')) = 'CERRADO'
           OR p_fecha_retorno_real IS NOT NULL
       )
    THEN
        RETURN json_build_object(
            'error',
            'No se puede cerrar el préstamo: aún hay cilindros pendientes de devolución',
            'registro', NULL
        );
    END IF;

    UPDATE bal_prestamo
    SET
        numero_prestamo = COALESCE(v_numero, numero_prestamo),
        id_tipo_prestamo = COALESCE(p_id_tipo_prestamo, id_tipo_prestamo),
        id_cliente = COALESCE(p_id_cliente, id_cliente),
        id_proveedor = COALESCE(p_id_proveedor, id_proveedor),
        id_almacen = COALESCE(p_id_almacen, id_almacen),
        fecha_salida = COALESCE(p_fecha_salida, fecha_salida),
        fecha_retorno_pactada = COALESCE(p_fecha_retorno_pactada, fecha_retorno_pactada),
        fecha_retorno_real = COALESCE(p_fecha_retorno_real, fecha_retorno_real),
        titulo = COALESCE(p_titulo, titulo),
        observacion = COALESCE(p_observacion, observacion),
        id_estado = COALESCE(p_id_estado, id_estado),
        id_comprobante_venta = COALESCE(p_id_comprobante_venta, id_comprobante_venta),
        id_comprobante_compra = COALESCE(p_id_comprobante_compra, id_comprobante_compra),
        id_usuario_modificacion = p_id_usuario_auditoria,
        fecha_modificacion = NOW()
    WHERE id = p_id AND estado = 1;

    IF NOT FOUND THEN
        RETURN json_build_object('registro', NULL);
    END IF;

    -- Si cambia el cliente, la ubicación de los cilindros aún prestados sigue al préstamo.
    IF p_id_cliente IS NOT NULL AND p_id_cliente IS DISTINCT FROM v_id_cliente_actual THEN
        UPDATE bal_balon b
        SET
            id_cliente_ubicacion = p_id_cliente,
            id_usuario_modificacion = p_id_usuario_auditoria,
            fecha_modificacion = NOW()
        FROM bal_prestamo_detalle pd
        WHERE pd.id_prestamo = p_id
          AND pd.estado = 1
          AND pd.fecha_devolucion IS NULL
          AND pd.id_balon = b.id
          AND b.estado = 1;
    END IF;

    RETURN bal_obtener_prestamo(p_id);
END;
$$;


--
-- Name: bal_actualizar_prestamo_detalle(integer, integer, integer, character varying, date, date, integer, date, date, character varying, character varying, character varying, character varying, integer, character varying, integer, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bal_actualizar_prestamo_detalle(p_id integer, p_id_balon integer DEFAULT NULL::integer, p_id_producto integer DEFAULT NULL::integer, p_motivo_especifico character varying DEFAULT NULL::character varying, p_fecha_entregado date DEFAULT NULL::date, p_fecha_prestamo date DEFAULT NULL::date, p_dias_prestamo integer DEFAULT NULL::integer, p_fecha_vencimiento date DEFAULT NULL::date, p_fecha_devolucion date DEFAULT NULL::date, p_serie_guia_entrega character varying DEFAULT NULL::character varying, p_numero_guia_entrega character varying DEFAULT NULL::character varying, p_serie_guia_devolucion character varying DEFAULT NULL::character varying, p_numero_guia_devolucion character varying DEFAULT NULL::character varying, p_id_estado integer DEFAULT NULL::integer, p_observacion character varying DEFAULT NULL::character varying, p_id_usuario_auditoria integer DEFAULT NULL::integer, p_id_guia_entrega integer DEFAULT NULL::integer, p_id_guia_devolucion integer DEFAULT NULL::integer) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_serie_entrega VARCHAR;
    v_numero_entrega VARCHAR;
    v_serie_devolucion VARCHAR;
    v_numero_devolucion VARCHAR;
    v_id_prestamo INTEGER;
    v_id_balon_actual INTEGER;
    v_fecha_devolucion DATE;
    v_id_almacen INTEGER;
    v_id_cliente INTEGER;
    v_id_balon_nuevo INTEGER;
    v_id_producto INTEGER;
    v_nombre_estado_nuevo VARCHAR;
    v_retorno JSON;
    v_salida JSON;
BEGIN
    SET TIME ZONE 'America/Lima';

    SELECT
        pd.id_prestamo,
        pd.id_balon,
        pd.fecha_devolucion,
        pd.id_producto,
        p.id_almacen,
        p.id_cliente
    INTO
        v_id_prestamo,
        v_id_balon_actual,
        v_fecha_devolucion,
        v_id_producto,
        v_id_almacen,
        v_id_cliente
    FROM bal_prestamo_detalle pd
    INNER JOIN bal_prestamo p ON p.id = pd.id_prestamo AND p.estado = 1
    WHERE pd.id = p_id AND pd.estado = 1;

    IF v_id_prestamo IS NULL THEN
        RETURN json_build_object('error', 'El detalle de préstamo no existe o está inactivo', 'registro', NULL);
    END IF;

    v_serie_entrega := p_serie_guia_entrega;
    v_numero_entrega := p_numero_guia_entrega;
    v_serie_devolucion := p_serie_guia_devolucion;
    v_numero_devolucion := p_numero_guia_devolucion;

    -- Serie/número quedan como snapshot de la GRE vinculada (compatibilidad UI).
    IF p_id_guia_entrega IS NOT NULL THEN
        SELECT g.serie, g.numero INTO v_serie_entrega, v_numero_entrega
        FROM gre_guia_remision g
        WHERE g.id = p_id_guia_entrega AND g.estado = 1;

        IF NOT FOUND THEN
            RETURN json_build_object('error', 'La guía de remisión de entrega indicada no existe o está inactiva', 'registro', NULL);
        END IF;
    END IF;

    IF p_id_guia_devolucion IS NOT NULL THEN
        SELECT g.serie, g.numero INTO v_serie_devolucion, v_numero_devolucion
        FROM gre_guia_remision g
        WHERE g.id = p_id_guia_devolucion AND g.estado = 1;

        IF NOT FOUND THEN
            RETURN json_build_object('error', 'La guía de remisión de devolución indicada no existe o está inactiva', 'registro', NULL);
        END IF;
    END IF;

    -- El vínculo GRE se aplica antes de cualquier bifurcación para que también
    -- quede grabado cuando la actualización delega en la devolución.
    IF p_id_guia_entrega IS NOT NULL OR p_id_guia_devolucion IS NOT NULL THEN
        UPDATE bal_prestamo_detalle
        SET
            id_guia_entrega = COALESCE(p_id_guia_entrega, id_guia_entrega),
            id_guia_devolucion = COALESCE(p_id_guia_devolucion, id_guia_devolucion),
            serie_guia_entrega = COALESCE(v_serie_entrega, serie_guia_entrega),
            numero_guia_entrega = COALESCE(v_numero_entrega, numero_guia_entrega),
            serie_guia_devolucion = COALESCE(v_serie_devolucion, serie_guia_devolucion),
            numero_guia_devolucion = COALESCE(v_numero_devolucion, numero_guia_devolucion),
            id_usuario_modificacion = p_id_usuario_auditoria,
            fecha_modificacion = NOW()
        WHERE id = p_id AND estado = 1;
    END IF;

    v_id_balon_nuevo := COALESCE(p_id_balon, v_id_balon_actual);

    IF p_id_estado IS NOT NULL THEN
        SELECT lo.nombre INTO v_nombre_estado_nuevo
        FROM gen_lista_opciones lo
        WHERE lo.id = p_id_estado AND lo.estado = 1;
    END IF;

    -- Devolver por fecha/estado en el formulario de edición → misma custodia que "Devolver".
    IF v_fecha_devolucion IS NULL
       AND (
           p_fecha_devolucion IS NOT NULL
           OR UPPER(COALESCE(v_nombre_estado_nuevo, '')) = 'DEVUELTO'
       )
    THEN
        RETURN bal_devolver_prestamo_detalle(
            p_id,
            COALESCE(p_fecha_devolucion, CURRENT_DATE),
            v_id_almacen,
            p_id_usuario_auditoria,
            'VACIO',
            p_observacion
        );
    END IF;

    IF v_fecha_devolucion IS NOT NULL
       AND p_id_balon IS NOT NULL
       AND p_id_balon IS DISTINCT FROM v_id_balon_actual
    THEN
        RETURN json_build_object(
            'error', 'No se puede cambiar el cilindro de un detalle ya devuelto',
            'registro', NULL
        );
    END IF;

    IF v_fecha_devolucion IS NULL
       AND p_id_balon IS NOT NULL
       AND p_id_balon IS DISTINCT FROM v_id_balon_actual
    THEN
        IF v_id_balon_actual IS NOT NULL THEN
            IF v_id_almacen IS NULL THEN
                SELECT id INTO v_id_almacen FROM gen_almacen WHERE estado = 1 ORDER BY id LIMIT 1;
            END IF;

            v_retorno := bal_prestamo_aplicar_retorno_cilindro(
                v_id_balon_actual,
                v_id_prestamo,
                v_id_cliente,
                v_id_almacen,
                NULL,
                'Cambio de cilindro en préstamo (libera el anterior)',
                p_id_usuario_auditoria,
                TRUE
            );
            IF v_retorno->>'error' IS NOT NULL THEN
                RETURN json_build_object('error', v_retorno->>'error', 'registro', NULL);
            END IF;
        END IF;

        IF EXISTS (
            SELECT 1
            FROM bal_prestamo_detalle pd
            INNER JOIN bal_prestamo p2 ON p2.id = pd.id_prestamo AND p2.estado = 1
            WHERE pd.id_balon = v_id_balon_nuevo
              AND pd.estado = 1
              AND pd.fecha_devolucion IS NULL
              AND pd.id <> p_id
        ) THEN
            RETURN json_build_object(
                'error', 'El cilindro ya tiene un préstamo activo sin devolver',
                'registro', NULL
            );
        END IF;

        IF EXISTS (
            SELECT 1
            FROM bal_alquiler_detalle ad
            INNER JOIN bal_alquiler al ON al.id = ad.id_alquiler AND al.estado = 1
            WHERE ad.id_balon = v_id_balon_nuevo
              AND ad.estado = 1
              AND ad.fecha_devolucion IS NULL
        ) THEN
            RETURN json_build_object(
                'error', 'El cilindro está alquilado actualmente; no se puede prestar',
                'registro', NULL
            );
        END IF;

        v_salida := bal_prestamo_aplicar_salida_cilindro(
            v_id_prestamo,
            v_id_balon_nuevo,
            COALESCE(p_observacion, 'Cambio de cilindro en préstamo'),
            p_id_usuario_auditoria
        );
        IF v_salida->>'error' IS NOT NULL THEN
            RETURN json_build_object('error', v_salida->>'error', 'registro', NULL);
        END IF;
    END IF;

    IF v_id_balon_nuevo IS NOT NULL THEN
        SELECT COALESCE(b.id_producto_gas, COALESCE(p_id_producto, v_id_producto))
        INTO v_id_producto
        FROM bal_balon b
        WHERE b.id = v_id_balon_nuevo AND b.estado = 1;
    ELSE
        v_id_producto := COALESCE(p_id_producto, v_id_producto);
    END IF;

    UPDATE bal_prestamo_detalle
    SET
        id_balon = COALESCE(p_id_balon, id_balon),
        id_producto = COALESCE(v_id_producto, id_producto),
        motivo_especifico = COALESCE(p_motivo_especifico, motivo_especifico),
        fecha_entregado = COALESCE(p_fecha_entregado, fecha_entregado),
        fecha_prestamo = COALESCE(p_fecha_prestamo, fecha_prestamo),
        dias_prestamo = COALESCE(p_dias_prestamo, dias_prestamo),
        fecha_vencimiento = COALESCE(p_fecha_vencimiento, fecha_vencimiento),
        id_guia_entrega = COALESCE(p_id_guia_entrega, id_guia_entrega),
        id_guia_devolucion = COALESCE(p_id_guia_devolucion, id_guia_devolucion),
        serie_guia_entrega = COALESCE(v_serie_entrega, serie_guia_entrega),
        numero_guia_entrega = COALESCE(v_numero_entrega, numero_guia_entrega),
        serie_guia_devolucion = COALESCE(v_serie_devolucion, serie_guia_devolucion),
        numero_guia_devolucion = COALESCE(v_numero_devolucion, numero_guia_devolucion),
        id_estado = COALESCE(p_id_estado, id_estado),
        observacion = COALESCE(p_observacion, observacion),
        id_usuario_modificacion = p_id_usuario_auditoria,
        fecha_modificacion = NOW()
    WHERE id = p_id AND estado = 1;

    IF NOT FOUND THEN
        RETURN json_build_object('registro', NULL);
    END IF;

    RETURN bal_obtener_prestamo_detalle(p_id);
END;
$$;


--
-- Name: bal_actualizar_recarga_planta(integer, date, integer, integer, integer, character varying, character varying, integer, character varying, character varying, date, character varying, date, date, character varying, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bal_actualizar_recarga_planta(p_id integer, p_fecha_salida date DEFAULT NULL::date, p_id_proveedor integer DEFAULT NULL::integer, p_id_almacen integer DEFAULT NULL::integer, p_id_guia_retorno integer DEFAULT NULL::integer, p_serie_guia_ingreso character varying DEFAULT NULL::character varying, p_numero_guia_ingreso character varying DEFAULT NULL::character varying, p_id_comprobante_compra integer DEFAULT NULL::integer, p_serie_factura character varying DEFAULT NULL::character varying, p_numero_factura character varying DEFAULT NULL::character varying, p_fecha_llegada_almacen date DEFAULT NULL::date, p_lote character varying DEFAULT NULL::character varying, p_fecha_vencimiento_lote date DEFAULT NULL::date, p_fecha_prueba_hidrostatica date DEFAULT NULL::date, p_observacion character varying DEFAULT NULL::character varying, p_id_usuario_auditoria integer DEFAULT NULL::integer) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_estado_actual VARCHAR;
    v_id_estado INTEGER;
    v_det RECORD;
    v_upd JSON;
    v_fecha_llegada DATE;
    v_id_compra INTEGER;
    v_lote VARCHAR;
    v_fecha_venc_lote DATE;
    v_fecha_ph DATE;
    v_serie_factura VARCHAR;
    v_numero_factura VARCHAR;
    v_id_almacen_orden INTEGER;
    v_id_guia_retorno INTEGER;
    v_repuntar JSON;
BEGIN
    SET TIME ZONE 'America/Lima';

    IF NOT EXISTS (SELECT 1 FROM bal_recarga_planta WHERE id = p_id AND estado = 1) THEN
        RETURN json_build_object('error', 'Orden de recarga no encontrada', 'registro', NULL);
    END IF;

    SELECT est.nombre
    INTO v_estado_actual
    FROM bal_recarga_planta rp
    LEFT JOIN gen_lista_opciones est ON est.id = rp.id_estado
    WHERE rp.id = p_id;

    IF p_id_guia_retorno IS NOT NULL AND NOT EXISTS (
        SELECT 1 FROM gre_guia_remision WHERE id = p_id_guia_retorno AND estado = 1
    ) THEN
        RETURN json_build_object('error', 'La guía de retorno no existe', 'registro', NULL);
    END IF;

    IF p_id_comprobante_compra IS NOT NULL AND NOT EXISTS (
        SELECT 1 FROM com_comprobante_compra WHERE id = p_id_comprobante_compra AND estado = 1
    ) THEN
        RETURN json_build_object('error', 'El comprobante de compra no existe', 'registro', NULL);
    END IF;

    -- Con FK a la compra no se copian serie/número de factura: las lecturas los
    -- resuelven por JOIN. Los campos de texto solo guardan lo que el usuario
    -- escribe cuando la factura aún no existe como comprobante en el sistema.
    v_serie_factura := NULLIF(TRIM(p_serie_factura), '');
    v_numero_factura := NULLIF(TRIM(p_numero_factura), '');

    UPDATE bal_recarga_planta
    SET
        fecha_salida = COALESCE(p_fecha_salida, fecha_salida),
        id_proveedor = COALESCE(p_id_proveedor, id_proveedor),
        id_almacen = COALESCE(p_id_almacen, id_almacen),
        id_guia_retorno = COALESCE(p_id_guia_retorno, id_guia_retorno),
        -- Con FK el documento manda y el espejo se limpia.
        -- Sin FK: '' explícito limpia; NULL conserva.
        serie_guia_ingreso = CASE
            WHEN p_id_guia_retorno IS NOT NULL THEN NULL
            WHEN p_serie_guia_ingreso IS NOT NULL THEN NULLIF(TRIM(p_serie_guia_ingreso), '')
            ELSE serie_guia_ingreso
        END,
        numero_guia_ingreso = CASE
            WHEN p_id_guia_retorno IS NOT NULL THEN NULL
            WHEN p_numero_guia_ingreso IS NOT NULL THEN NULLIF(TRIM(p_numero_guia_ingreso), '')
            ELSE numero_guia_ingreso
        END,
        id_comprobante_compra = COALESCE(p_id_comprobante_compra, id_comprobante_compra),
        serie_factura = CASE
            WHEN p_id_comprobante_compra IS NOT NULL THEN NULL
            WHEN p_serie_factura IS NOT NULL THEN v_serie_factura
            ELSE serie_factura
        END,
        numero_factura = CASE
            WHEN p_id_comprobante_compra IS NOT NULL THEN NULL
            WHEN p_numero_factura IS NOT NULL THEN v_numero_factura
            ELSE numero_factura
        END,
        fecha_llegada_almacen = COALESCE(p_fecha_llegada_almacen, fecha_llegada_almacen),
        lote = CASE
            WHEN p_lote IS NOT NULL THEN NULLIF(TRIM(p_lote), '')
            ELSE lote
        END,
        fecha_vencimiento_lote = CASE
            WHEN p_fecha_vencimiento_lote IS NOT NULL THEN p_fecha_vencimiento_lote
            ELSE fecha_vencimiento_lote
        END,
        fecha_prueba_hidrostatica = CASE
            WHEN p_fecha_prueba_hidrostatica IS NOT NULL THEN p_fecha_prueba_hidrostatica
            ELSE fecha_prueba_hidrostatica
        END,
        observacion = CASE
            WHEN p_observacion IS NOT NULL THEN NULLIF(TRIM(p_observacion), '')
            ELSE observacion
        END,
        id_usuario_modificacion = p_id_usuario_auditoria,
        fecha_modificacion = NOW()
    WHERE id = p_id;

    -- Propagar protocolo/retorno a detalle + movimiento (también si solo corrigen lote en CERRADO).
    IF p_fecha_llegada_almacen IS NOT NULL
       OR p_lote IS NOT NULL
       OR p_fecha_vencimiento_lote IS NOT NULL
       OR p_fecha_prueba_hidrostatica IS NOT NULL
       OR p_id_comprobante_compra IS NOT NULL
       OR p_serie_guia_ingreso IS NOT NULL
       OR p_serie_factura IS NOT NULL
       OR p_numero_factura IS NOT NULL
    THEN
        SELECT
            fecha_llegada_almacen,
            NULLIF(TRIM(lote), ''),
            fecha_vencimiento_lote,
            fecha_prueba_hidrostatica,
            NULLIF(TRIM(serie_factura), ''),
            NULLIF(TRIM(numero_factura), ''),
            id_comprobante_compra,
            id_almacen,
            id_guia_retorno
        INTO
            v_fecha_llegada,
            v_lote,
            v_fecha_venc_lote,
            v_fecha_ph,
            v_serie_factura,
            v_numero_factura,
            v_id_compra,
            v_id_almacen_orden,
            v_id_guia_retorno
        FROM bal_recarga_planta
        WHERE id = p_id;

        FOR v_det IN
            SELECT d.id_movimiento_recarga, d.id, d.id_producto, d.capacidad, d.id_unidad_medida
            FROM bal_recarga_planta_detalle d
            WHERE d.id_recarga_planta = p_id
              AND d.estado = 1
              AND d.id_movimiento_recarga IS NOT NULL
        LOOP
            UPDATE bal_recarga_planta_detalle
            SET
                lote = v_lote,
                fecha_vencimiento_lote = v_fecha_venc_lote,
                fecha_prueba_hidrostatica = v_fecha_ph,
                id_usuario_modificacion = p_id_usuario_auditoria,
                fecha_modificacion = NOW()
            WHERE id = v_det.id;

            v_upd := bal_actualizar_movimiento_recarga(
                v_det.id_movimiento_recarga,
                NULL,
                v_det.id_producto,
                v_det.capacidad,
                v_det.id_unidad_medida,
                NULL,
                NULL,
                -- Con GRE de retorno vinculada, el movimiento la lee vía la orden.
                CASE WHEN v_id_guia_retorno IS NULL
                    THEN NULLIF(TRIM(COALESCE(p_serie_guia_ingreso, '')), '')
                END,
                CASE WHEN v_id_guia_retorno IS NULL
                    THEN NULLIF(TRIM(COALESCE(p_numero_guia_ingreso, '')), '')
                END,
                v_serie_factura,
                v_numero_factura,
                NULL,
                CASE WHEN p_fecha_llegada_almacen IS NOT NULL THEN p_fecha_llegada_almacen ELSE NULL END,
                COALESCE(v_lote, ''),
                v_fecha_venc_lote,
                v_fecha_ph,
                NULL,
                NULL,
                COALESCE(p_id_almacen, v_id_almacen_orden),
                COALESCE(p_id_comprobante_compra, v_id_compra),
                p_id_usuario_auditoria
            );

            IF v_upd->>'error' IS NOT NULL THEN
                RETURN json_build_object('error', v_upd->>'error', 'registro', NULL);
            END IF;
            -- P.H. → historial del balón: lo hace bal_actualizar_movimiento_recarga (idempotente).
        END LOOP;
    END IF;

    -- Si se vincula compra, el kardex unificado (inv_movimiento) debe apuntar a COMPRA.
    -- ENTRADA_LLENADO suele referenciar la orden; ENTRADA_PLANTA_EXTERNA el movimiento_recarga
    -- (bal_actualizar_movimiento_recarga también repunta, idempotente si ya quedó en COMPRA).
    IF p_id_comprobante_compra IS NOT NULL THEN
        v_repuntar := inv_repuntar_documento(
            p_codigo_tipo_documento_origen_actual => 'RECARGA',
            p_id_documento_origen_actual          => p_id,
            p_codigo_tipo_documento_origen_nuevo  => 'COMPRA',
            p_id_documento_origen_nuevo           => p_id_comprobante_compra,
            p_id_usuario_auditoria                => p_id_usuario_auditoria
        );
        IF v_repuntar->>'error' IS NOT NULL THEN
            RETURN json_build_object('error', v_repuntar->>'error', 'registro', NULL);
        END IF;

        FOR v_det IN
            SELECT d.id_movimiento_recarga
            FROM bal_recarga_planta_detalle d
            WHERE d.id_recarga_planta = p_id
              AND d.estado = 1
              AND d.id_movimiento_recarga IS NOT NULL
        LOOP
            v_repuntar := inv_repuntar_documento(
                p_codigo_tipo_documento_origen_actual => 'RECARGA',
                p_id_documento_origen_actual          => v_det.id_movimiento_recarga,
                p_codigo_tipo_documento_origen_nuevo  => 'COMPRA',
                p_id_documento_origen_nuevo           => p_id_comprobante_compra,
                p_id_usuario_auditoria                => p_id_usuario_auditoria
            );
            IF v_repuntar->>'error' IS NOT NULL THEN
                RETURN json_build_object('error', v_repuntar->>'error', 'registro', NULL);
            END IF;
        END LOOP;
    END IF;

    -- Protocolo planta al retorno (o corrección en órdenes ya retornadas/cerradas).
    SELECT
        fecha_llegada_almacen,
        id_comprobante_compra,
        NULLIF(TRIM(lote), ''),
        fecha_vencimiento_lote,
        fecha_prueba_hidrostatica
    INTO v_fecha_llegada, v_id_compra, v_lote, v_fecha_venc_lote, v_fecha_ph
    FROM bal_recarga_planta
    WHERE id = p_id;

    IF v_fecha_llegada IS NOT NULL THEN
        IF v_lote IS NULL THEN
            RETURN json_build_object(
                'error',
                'El número de lote es obligatorio al registrar el retorno (protocolo de planta)',
                'registro',
                NULL
            );
        END IF;

        IF v_fecha_venc_lote IS NULL THEN
            RETURN json_build_object(
                'error',
                'La fecha de vencimiento del lote es obligatoria al registrar el retorno',
                'registro',
                NULL
            );
        END IF;

        IF v_fecha_ph IS NULL THEN
            RETURN json_build_object(
                'error',
                'La fecha de prueba hidrostática (P.H.) es obligatoria al registrar el retorno',
                'registro',
                NULL
            );
        END IF;
    END IF;

    -- CERRADO solo con compra + retorno físico. Solo llegada → RETORNADO.
    IF v_id_compra IS NOT NULL AND v_fecha_llegada IS NOT NULL THEN
        SELECT lo.id INTO v_id_estado
        FROM gen_lista_opciones lo
        INNER JOIN gen_lista l ON l.id = lo.id_lista
        WHERE l.nombre = 'EstadoRecargaPlanta' AND lo.nombre = 'CERRADO' AND lo.estado = 1
        LIMIT 1;
    ELSIF v_fecha_llegada IS NOT NULL THEN
        SELECT lo.id INTO v_id_estado
        FROM gen_lista_opciones lo
        INNER JOIN gen_lista l ON l.id = lo.id_lista
        WHERE l.nombre = 'EstadoRecargaPlanta' AND lo.nombre = 'RETORNADO' AND lo.estado = 1
        LIMIT 1;
    ELSE
        v_id_estado := NULL;
    END IF;

    IF v_id_estado IS NOT NULL THEN
        UPDATE bal_recarga_planta
        SET id_estado = v_id_estado
        WHERE id = p_id;
    END IF;

    RETURN bal_obtener_recarga_planta(p_id);
END;
$$;


--
-- Name: bal_actualizar_recojo(integer, integer, integer, date, time without time zone, integer, character varying, character varying, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bal_actualizar_recojo(p_id integer, p_id_prestamo integer DEFAULT NULL::integer, p_id_alquiler integer DEFAULT NULL::integer, p_fecha_programada date DEFAULT NULL::date, p_hora_estimada time without time zone DEFAULT NULL::time without time zone, p_id_usuario_responsable integer DEFAULT NULL::integer, p_estado_nombre character varying DEFAULT NULL::character varying, p_observacion character varying DEFAULT NULL::character varying, p_id_usuario_auditoria integer DEFAULT NULL::integer) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_id_cliente INTEGER;
    v_estado_actual VARCHAR;
    v_estado_nuevo VARCHAR;
    v_id_estado INTEGER;
    v_id_estado_prestado INTEGER;
    v_id_estado_alquilado INTEGER;
    v_det RECORD;
BEGIN
    SET TIME ZONE 'America/Lima';

    SELECT r.id_cliente, er.nombre
    INTO v_id_cliente, v_estado_actual
    FROM bal_recojo r
    LEFT JOIN gen_lista_opciones er ON er.id = r.id_estado
    WHERE r.id = p_id AND r.estado = 1;

    IF v_id_cliente IS NULL THEN
        RETURN json_build_object('error', 'Recojo no encontrado', 'registro', NULL);
    END IF;

    IF v_estado_actual NOT IN ('PROGRAMADO', 'EN_RUTA') THEN
        RETURN json_build_object(
            'error', 'Solo se pueden editar recojos en estado PROGRAMADO o EN_RUTA',
            'registro', NULL
        );
    END IF;

    IF p_id_prestamo IS NOT NULL AND NOT EXISTS (
        SELECT 1 FROM bal_prestamo
        WHERE id = p_id_prestamo AND estado = 1 AND id_cliente = v_id_cliente
    ) THEN
        RETURN json_build_object(
            'error', 'El préstamo no existe, está inactivo o no pertenece al cliente',
            'registro', NULL
        );
    END IF;

    IF p_id_alquiler IS NOT NULL AND NOT EXISTS (
        SELECT 1 FROM bal_alquiler
        WHERE id = p_id_alquiler AND estado = 1 AND id_cliente = v_id_cliente
    ) THEN
        RETURN json_build_object(
            'error', 'El alquiler no existe, está inactivo o no pertenece al cliente',
            'registro', NULL
        );
    END IF;

    IF p_id_usuario_responsable IS NOT NULL AND NOT EXISTS (
        SELECT 1 FROM auth_usuarios WHERE id = p_id_usuario_responsable AND estado = TRUE
    ) THEN
        RETURN json_build_object(
            'error', 'El usuario responsable no existe o está inactivo',
            'registro', NULL
        );
    END IF;

    v_estado_nuevo := NULLIF(UPPER(TRIM(p_estado_nombre)), '');
    IF v_estado_nuevo IS NOT NULL THEN
        IF v_estado_nuevo NOT IN ('PROGRAMADO', 'EN_RUTA', 'CANCELADO') THEN
            RETURN json_build_object(
                'error', 'Estado no permitido en actualización: ' || v_estado_nuevo,
                'registro', NULL
            );
        END IF;

        SELECT lo.id INTO v_id_estado
        FROM gen_lista_opciones lo
        INNER JOIN gen_lista l ON l.id = lo.id_lista
        WHERE l.nombre = 'EstadoRecojo' AND lo.nombre = v_estado_nuevo AND lo.estado = 1
        LIMIT 1;

        IF v_id_estado IS NULL THEN
            RETURN json_build_object(
                'error', 'No se encontró el estado ' || v_estado_nuevo || ' en EstadoRecojo',
                'registro', NULL
            );
        END IF;
    END IF;

    IF v_estado_nuevo = 'CANCELADO' AND v_estado_actual <> 'CANCELADO' THEN
        SELECT lo.id INTO v_id_estado_prestado
        FROM gen_lista_opciones lo
        INNER JOIN gen_lista l ON l.id = lo.id_lista
        WHERE l.nombre = 'EstadoBalon' AND lo.nombre = 'PRESTADO_CLIENTE' AND lo.estado = 1
        LIMIT 1;

        SELECT lo.id INTO v_id_estado_alquilado
        FROM gen_lista_opciones lo
        INNER JOIN gen_lista l ON l.id = lo.id_lista
        WHERE l.nombre = 'EstadoBalon' AND lo.nombre = 'ALQUILADO' AND lo.estado = 1
        LIMIT 1;

        IF v_id_estado_prestado IS NOT NULL THEN
            FOR v_det IN
                SELECT pd.id_balon
                FROM bal_recojo_detalle rd
                INNER JOIN bal_prestamo_detalle pd ON pd.id = rd.id_prestamo_detalle AND pd.estado = 1
                INNER JOIN bal_balon b ON b.id = pd.id_balon AND b.estado = 1
                INNER JOIN gen_lista_opciones eb ON eb.id = b.id_estado_balon
                WHERE rd.id_recojo = p_id
                  AND rd.estado = 1
                  AND pd.fecha_devolucion IS NULL
                  AND eb.nombre = 'POR_RECOGER'
            LOOP
                UPDATE bal_balon
                SET
                    id_estado_balon = v_id_estado_prestado,
                    id_usuario_modificacion = p_id_usuario_auditoria,
                    fecha_modificacion = NOW()
                WHERE id = v_det.id_balon;
            END LOOP;
        END IF;

        IF v_id_estado_alquilado IS NOT NULL THEN
            FOR v_det IN
                SELECT ad.id_balon
                FROM bal_recojo_detalle rd
                INNER JOIN bal_alquiler_detalle ad ON ad.id = rd.id_alquiler_detalle AND ad.estado = 1
                INNER JOIN bal_balon b ON b.id = ad.id_balon AND b.estado = 1
                INNER JOIN gen_lista_opciones eb ON eb.id = b.id_estado_balon
                WHERE rd.id_recojo = p_id
                  AND rd.estado = 1
                  AND ad.fecha_devolucion IS NULL
                  AND eb.nombre = 'POR_RECOGER'
            LOOP
                UPDATE bal_balon
                SET
                    id_estado_balon = v_id_estado_alquilado,
                    id_usuario_modificacion = p_id_usuario_auditoria,
                    fecha_modificacion = NOW()
                WHERE id = v_det.id_balon;
            END LOOP;
        END IF;
    END IF;

    UPDATE bal_recojo
    SET
        id_prestamo = COALESCE(p_id_prestamo, id_prestamo),
        id_alquiler = COALESCE(p_id_alquiler, id_alquiler),
        fecha_programada = COALESCE(p_fecha_programada, fecha_programada),
        hora_estimada = COALESCE(p_hora_estimada, hora_estimada),
        id_usuario_responsable = COALESCE(p_id_usuario_responsable, id_usuario_responsable),
        id_estado = COALESCE(v_id_estado, id_estado),
        observacion = COALESCE(NULLIF(TRIM(p_observacion), ''), observacion),
        id_usuario_modificacion = p_id_usuario_auditoria,
        fecha_modificacion = NOW()
    WHERE id = p_id AND estado = 1;

    IF NOT FOUND THEN
        RETURN json_build_object('error', 'Recojo no encontrado', 'registro', NULL);
    END IF;

    RETURN bal_obtener_recojo(p_id);
END;
$$;


--
-- Name: bal_actualizar_ruta_pueblo(integer, date, integer, integer, integer, numeric, numeric, character varying, character varying, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bal_actualizar_ruta_pueblo(p_id integer, p_fecha date DEFAULT NULL::date, p_id_almacen integer DEFAULT NULL::integer, p_id_usuario_responsable integer DEFAULT NULL::integer, p_id_chofer integer DEFAULT NULL::integer, p_factor_lb_m3 numeric DEFAULT NULL::numeric, p_tolerancia_m3 numeric DEFAULT NULL::numeric, p_observacion character varying DEFAULT NULL::character varying, p_estado_nombre character varying DEFAULT NULL::character varying, p_id_usuario_auditoria integer DEFAULT NULL::integer) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_estado VARCHAR;
    v_id_estado INTEGER;
    v_estado_nuevo VARCHAR;
    v_id_almacen INTEGER;
    v_det RECORD;
    v_mov JSON;
    v_sync JSON;
    v_estado_balon VARCHAR;
BEGIN
    SET TIME ZONE 'America/Lima';

    SELECT er.nombre, r.id_almacen
    INTO v_estado, v_id_almacen
    FROM bal_ruta_pueblo r
    LEFT JOIN gen_lista_opciones er ON er.id = r.id_estado
    WHERE r.id = p_id AND r.estado = 1;

    IF v_estado IS NULL THEN
        RETURN json_build_object('error', 'Ruta no encontrada', 'registro', NULL);
    END IF;

    IF v_estado IN ('CERRADA', 'CANCELADA') THEN
        RETURN json_build_object('error', 'No se puede editar una ruta cerrada o cancelada', 'registro', NULL);
    END IF;

    v_estado_nuevo := NULLIF(UPPER(TRIM(COALESCE(p_estado_nombre, ''))), '');
    IF v_estado_nuevo IS NOT NULL THEN
        IF v_estado_nuevo NOT IN ('CANCELADA') THEN
            RETURN json_build_object(
                'error',
                'Use iniciar / retorno / cerrar para cambiar de estado; solo CANCELADA vía actualizar',
                'registro',
                NULL
            );
        END IF;
        SELECT lo.id INTO v_id_estado
        FROM gen_lista_opciones lo
        INNER JOIN gen_lista l ON l.id = lo.id_lista
        WHERE l.nombre = 'EstadoRutaPueblo' AND lo.nombre = 'CANCELADA' AND lo.estado = 1
        LIMIT 1;

        IF v_id_estado IS NULL THEN
            RETURN json_build_object('error', 'Estado CANCELADA no configurado', 'registro', NULL);
        END IF;

        -- Si ya salió a ruta: devolver a almacén los cilindros sin retorno registrado.
        IF v_estado = 'EN_RUTA' THEN
            FOR v_det IN
                SELECT d.id_balon, d.lb_salida
                FROM bal_ruta_pueblo_detalle d
                WHERE d.id_ruta_pueblo = p_id
                  AND d.estado = 1
                  AND d.lb_retorno IS NULL
            LOOP
                SELECT eb.nombre
                INTO v_estado_balon
                FROM bal_balon b
                LEFT JOIN gen_lista_opciones eb ON eb.id = b.id_estado_balon
                WHERE b.id = v_det.id_balon AND b.estado = 1;

                IF v_estado_balon IS NULL THEN
                    RAISE EXCEPTION 'Cilindro % no existe o está inactivo', v_det.id_balon;
                END IF;

                -- Solo revertir si sigue en tránsito de esta ruta
                IF v_estado_balon = 'EN_RUTA_LIMA' THEN
                    v_mov := bal_registrar_salida_documento(
                        v_det.id_balon,
                        'RETORNO_LIMA',
                        p_id,
                        'RUTA_PUEBLO',
                        NULL,
                        NULL,
                        'EN_ALMACEN',
                        FALSE,
                        v_id_almacen,
                        format(
                            'Cancelación ruta pueblos #%s · restaura %.4f lb de salida',
                            p_id,
                            v_det.lb_salida
                        ),
                        p_id_usuario_auditoria
                    );

                    IF v_mov->>'error' IS NOT NULL THEN
                        RAISE EXCEPTION 'Cilindro %: %', v_det.id_balon, v_mov->>'error';
                    END IF;

                    UPDATE bal_balon
                    SET
                        id_almacen = v_id_almacen,
                        id_cliente_ubicacion = NULL,
                        id_estado_balon = (
                            SELECT lo.id
                            FROM gen_lista_opciones lo
                            INNER JOIN gen_lista l ON l.id = lo.id_lista
                            WHERE l.nombre = 'EstadoBalon' AND lo.nombre = 'EN_ALMACEN' AND lo.estado = 1
                            LIMIT 1
                        ),
                        id_usuario_modificacion = p_id_usuario_auditoria,
                        fecha_modificacion = NOW()
                    WHERE id = v_det.id_balon AND estado = 1;


                END IF;
            END LOOP;
        END IF;
    END IF;

    UPDATE bal_ruta_pueblo
    SET
        fecha = COALESCE(p_fecha, fecha),
        id_almacen = COALESCE(p_id_almacen, id_almacen),
        id_usuario_responsable = COALESCE(p_id_usuario_responsable, id_usuario_responsable),
        id_chofer = COALESCE(p_id_chofer, id_chofer),
        factor_lb_m3 = COALESCE(NULLIF(p_factor_lb_m3, 0), factor_lb_m3),
        tolerancia_m3 = COALESCE(NULLIF(p_tolerancia_m3, 0), tolerancia_m3),
        id_estado = COALESCE(v_id_estado, id_estado),
        observacion = CASE
            WHEN p_observacion IS NULL THEN observacion
            ELSE NULLIF(TRIM(p_observacion), '')
        END,
        id_usuario_modificacion = p_id_usuario_auditoria,
        fecha_modificacion = NOW()
    WHERE id = p_id AND estado = 1;

    RETURN bal_obtener_ruta_pueblo(p_id);
END;
$$;


--
-- Name: bal_actualizar_tipo_balon(integer, character varying, integer, numeric, numeric, integer, numeric, integer, numeric, numeric, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bal_actualizar_tipo_balon(p_id integer, p_nombre character varying DEFAULT NULL::character varying, p_id_gas integer DEFAULT NULL::integer, p_capacidad numeric DEFAULT NULL::numeric, p_capacidad_lb numeric DEFAULT NULL::numeric, p_id_unidad_medida integer DEFAULT NULL::integer, p_peso numeric DEFAULT NULL::numeric, p_vigencia_ph_anios integer DEFAULT NULL::integer, p_presion_llenado_psi numeric DEFAULT NULL::numeric, p_peso_tara_lb numeric DEFAULT NULL::numeric, p_id_usuario_auditoria integer DEFAULT NULL::integer) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_nombre VARCHAR;
    v_peso NUMERIC;
    v_tara_lb NUMERIC;
BEGIN
    SET TIME ZONE 'America/Lima';

    v_nombre := NULLIF(TRIM(p_nombre), '');

    IF v_nombre IS NOT NULL AND EXISTS (
        SELECT 1 FROM bal_tipo_balon
        WHERE estado = 1 AND LOWER(TRIM(nombre)) = LOWER(v_nombre) AND id <> p_id
    ) THEN
        RETURN json_build_object('error', 'Ya existe otro tipo de balón con el nombre ' || v_nombre, 'registro', NULL);
    END IF;

    IF p_id_gas IS NOT NULL AND NOT EXISTS (
        SELECT 1 FROM pro_producto WHERE id = p_id_gas AND estado = 1
    ) THEN
        RETURN json_build_object('error', 'El gas indicado no existe o está inactivo', 'registro', NULL);
    END IF;

    IF p_id_unidad_medida IS NOT NULL AND NOT EXISTS (
        SELECT 1 FROM gen_lista_opciones WHERE id = p_id_unidad_medida AND estado = 1
    ) THEN
        RETURN json_build_object('error', 'La unidad de medida indicada no existe o está inactiva', 'registro', NULL);
    END IF;

    IF p_capacidad_lb IS NOT NULL AND p_capacidad_lb <= 0 THEN
        RETURN json_build_object('error', 'La capacidad en lb debe ser mayor a 0', 'registro', NULL);
    END IF;

    IF p_presion_llenado_psi IS NOT NULL AND p_presion_llenado_psi <= 0 THEN
        RETURN json_build_object('error', 'La presión de llenado (PSI) debe ser mayor a 0', 'registro', NULL);
    END IF;

    SELECT peso INTO v_peso FROM bal_tipo_balon WHERE id = p_id AND estado = 1;
    v_peso := COALESCE(p_peso, v_peso);
    v_tara_lb := COALESCE(
        NULLIF(p_peso_tara_lb, 0),
        CASE
            WHEN p_peso_tara_lb IS NULL AND p_peso IS NOT NULL AND p_peso > 0
                THEN ROUND(p_peso * 2.20462, 4)
            ELSE NULL
        END
    );

    UPDATE bal_tipo_balon
    SET
        nombre = COALESCE(v_nombre, nombre),
        id_gas = COALESCE(p_id_gas, id_gas),
        capacidad = COALESCE(p_capacidad, capacidad),
        capacidad_lb = COALESCE(p_capacidad_lb, capacidad_lb),
        id_unidad_medida = COALESCE(p_id_unidad_medida, id_unidad_medida),
        peso = COALESCE(p_peso, peso),
        vigencia_ph_anios = COALESCE(p_vigencia_ph_anios, vigencia_ph_anios),
        presion_llenado_psi = COALESCE(p_presion_llenado_psi, presion_llenado_psi),
        peso_tara_lb = COALESCE(v_tara_lb, peso_tara_lb),
        id_usuario_modificacion = p_id_usuario_auditoria,
        fecha_modificacion = NOW()
    WHERE id = p_id AND estado = 1;

    IF NOT FOUND THEN
        RETURN json_build_object('registro', NULL);
    END IF;

    RETURN bal_obtener_tipo_balon(p_id);
END;
$$;


--
-- Name: bal_aplicar_custodia_tipo_movimiento(integer, boolean, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bal_aplicar_custodia_tipo_movimiento(p_id_movimiento integer, p_revertir boolean DEFAULT false, p_id_usuario integer DEFAULT NULL::integer) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_mov RECORD;
    v_tipo TEXT;
    v_codigo_estado TEXT;
    v_id_estado INTEGER;
    v_almacen INTEGER;
    v_cliente INTEGER;
    v_limpiar_almacen BOOLEAN := FALSE;
    v_contenido TEXT;
BEGIN
    SELECT
        m.id_balon,
        m.id_documento_ref,
        m.id_cliente,
        m.id_almacen_origen,
        m.id_almacen_destino,
        lo.nombre AS tipo
    INTO v_mov
    FROM bal_movimiento m
    LEFT JOIN gen_lista_opciones lo ON lo.id = m.id_tipo_movimiento
    WHERE m.id = p_id_movimiento;

    IF NOT FOUND OR v_mov.id_documento_ref IS NOT NULL THEN
        RETURN json_build_object('ok', TRUE, 'skipped', TRUE);
    END IF;

    v_tipo := v_mov.tipo;

    IF p_revertir THEN
        v_codigo_estado := 'EN_ALMACEN';
        v_almacen := COALESCE(v_mov.id_almacen_origen, v_mov.id_almacen_destino);
        v_cliente := NULL;
        v_limpiar_almacen := FALSE;
    ELSE
        CASE v_tipo
            WHEN 'SALIDA_PRESTAMO' THEN
                v_codigo_estado := 'PRESTADO_CLIENTE';
                v_cliente := v_mov.id_cliente;
                v_limpiar_almacen := TRUE;
            WHEN 'SALIDA_ALQUILER' THEN
                v_codigo_estado := 'ALQUILADO';
                v_cliente := v_mov.id_cliente;
                v_limpiar_almacen := TRUE;
            WHEN 'SALIDA_VENTA' THEN
                v_codigo_estado := 'EN_PODER_CLIENTE';
                v_cliente := v_mov.id_cliente;
                v_limpiar_almacen := TRUE;
            WHEN 'SALIDA_ENTREGA_CLIENTE' THEN
                v_codigo_estado := 'EN_PODER_CLIENTE';
                v_cliente := v_mov.id_cliente;
                v_limpiar_almacen := TRUE;
            WHEN 'SALIDA_MANTENIMIENTO' THEN
                v_codigo_estado := 'EN_MANTENIMIENTO';
                v_almacen := COALESCE(v_mov.id_almacen_destino, v_mov.id_almacen_origen);
            WHEN 'SALIDA_PLANTA_EXTERNA' THEN
                v_codigo_estado := 'EN_RECARGA_EXTERNA';
                v_limpiar_almacen := TRUE;
                v_contenido := 'VACIO';
            WHEN 'ENTRADA_DEVOLUCION', 'ENTRADA_MANTENIMIENTO', 'RETORNO_LIMA' THEN
                v_codigo_estado := 'EN_ALMACEN';
                v_almacen := COALESCE(v_mov.id_almacen_destino, v_mov.id_almacen_origen);
            WHEN 'ENTRADA_LLENADO', 'ENTRADA_PLANTA_EXTERNA' THEN
                v_codigo_estado := 'EN_ALMACEN';
                v_almacen := COALESCE(v_mov.id_almacen_destino, v_mov.id_almacen_origen);
                v_contenido := 'LLENO';
            WHEN 'RECARGA_CLIENTE' THEN
                v_codigo_estado := 'EN_PODER_CLIENTE';
                v_cliente := v_mov.id_cliente;
                v_limpiar_almacen := TRUE;
            WHEN 'TRASLADO_LIMA' THEN
                v_codigo_estado := 'EN_RUTA_LIMA';
                v_limpiar_almacen := TRUE;
            ELSE
                RETURN json_build_object('ok', TRUE, 'skipped', TRUE);
        END CASE;
    END IF;

    SELECT lo.id INTO v_id_estado
    FROM gen_lista_opciones lo
    INNER JOIN gen_lista l ON l.id = lo.id_lista
    WHERE l.nombre = 'EstadoBalon' AND lo.nombre = v_codigo_estado AND lo.estado = 1
    LIMIT 1;

    IF v_id_estado IS NULL THEN
        RETURN json_build_object('ok', FALSE, 'error', format('Estado %s no configurado', v_codigo_estado));
    END IF;

    UPDATE bal_balon
    SET
        id_estado_balon = v_id_estado,
        id_cliente_ubicacion = CASE
            WHEN v_limpiar_almacen THEN v_cliente
            WHEN v_cliente IS NOT NULL THEN v_cliente
            ELSE NULL
        END,
        id_almacen = CASE
            WHEN v_limpiar_almacen THEN NULL
            ELSE v_almacen
        END,
        id_usuario_modificacion = p_id_usuario,
        fecha_modificacion = NOW()
    WHERE id = v_mov.id_balon AND estado = 1;

    RETURN json_build_object('ok', TRUE, 'skipped', FALSE);
END;
$$;


--
-- Name: bal_aplicar_salidas_guia_remision(integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bal_aplicar_salidas_guia_remision(p_id_guia integer, p_id_usuario_auditoria integer DEFAULT NULL::integer) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_id_almacen INTEGER;
    v_id_cliente INTEGER;
    v_id_destinatario INTEGER;
    v_id_motivo INTEGER;
    v_observaciones VARCHAR;
    v_motivo_codigo VARCHAR;
    v_motivo_nombre VARCHAR;
    v_es_planta BOOLEAN := FALSE;
    v_id_cliente_ubicacion INTEGER;
    v_codigo_tipo_mov VARCHAR;
    v_codigo_estado VARCHAR;
    v_id_balon INTEGER;
    v_balones INTEGER[] := ARRAY[]::INTEGER[];
    v_result JSON;
    v_serie VARCHAR;
    v_numero VARCHAR;
BEGIN
    SET TIME ZONE 'America/Lima';

    SELECT
        g.id_almacen,
        g.id_cliente,
        g.id_destinatario,
        g.id_motivo_traslado,
        g.observaciones,
        g.serie,
        g.numero
    INTO
        v_id_almacen,
        v_id_cliente,
        v_id_destinatario,
        v_id_motivo,
        v_observaciones,
        v_serie,
        v_numero
    FROM gre_guia_remision g
    WHERE g.id = p_id_guia AND g.estado = 1;

    IF NOT FOUND THEN
        RETURN json_build_object('error', 'Guía de remisión no encontrada', 'ok', FALSE);
    END IF;

    SELECT lo.descripcion, lo.nombre
    INTO v_motivo_codigo, v_motivo_nombre
    FROM gen_lista_opciones lo
    WHERE lo.id = v_id_motivo AND lo.estado = 1;

    -- Motivo SUNAT 13 (OTROS): FE lo usa para salida de vacíos a planta externa
    v_es_planta := COALESCE(v_motivo_codigo, '') = '13'
        OR (
            UPPER(COALESCE(v_motivo_nombre, '')) = 'OTROS'
            AND (
                COALESCE(v_observaciones, '') ILIKE '%planta%'
                OR COALESCE(v_observaciones, '') ILIKE '%recarga%'
            )
        );

    IF v_es_planta THEN
        v_codigo_tipo_mov := 'SALIDA_PLANTA_EXTERNA';
        v_codigo_estado := 'EN_RECARGA_EXTERNA';
        v_id_cliente_ubicacion := NULL;
    ELSIF v_id_cliente IS NOT NULL OR v_id_destinatario IS NOT NULL THEN
        v_codigo_tipo_mov := 'SALIDA_PRESTAMO';
        v_codigo_estado := 'PRESTADO_CLIENTE';
        v_id_cliente_ubicacion := COALESCE(v_id_cliente, v_id_destinatario);
    ELSE
        -- Sin cliente/destinatario: ruta a Lima. inv_registrar_movimiento resuelve el estado
        -- de custodia únicamente a partir del código de tipo de movimiento (ya no admite un
        -- estado de destino separado), así que el código debe ser TRASLADO_LIMA y no
        -- SALIDA_PRESTAMO (que siempre mapea a PRESTADO_CLIENTE).
        v_codigo_tipo_mov := 'TRASLADO_LIMA';
        v_codigo_estado := 'EN_RUTA_LIMA';
        v_id_cliente_ubicacion := NULL;
    END IF;

    FOR v_id_balon IN
        SELECT d.id_balon
        FROM gre_guia_remision_detalle d
        WHERE d.id_guia_remision = p_id_guia
          AND d.estado = 1
          AND d.id_balon IS NOT NULL
        ORDER BY d.item, d.id
    LOOP
        IF v_id_balon = ANY (v_balones) THEN
            RETURN json_build_object(
                'error',
                format('El cilindro %s está duplicado en la guía', v_id_balon),
                'ok',
                FALSE
            );
        END IF;
        v_balones := array_append(v_balones, v_id_balon);

        v_result := bal_registrar_salida_documento(
            v_id_balon,
            v_codigo_tipo_mov,
            p_id_guia,
            'GRE',
            v_id_cliente_ubicacion,
            v_id_almacen,
            v_codigo_estado,
            TRUE,
            NULL,
            format(
                'Salida automática GRE %s-%s',
                COALESCE(v_serie, ''),
                COALESCE(v_numero, '')
            ),
            p_id_usuario_auditoria
        );

        IF v_result->>'error' IS NOT NULL THEN
            RETURN json_build_object(
                'error',
                format('Cilindro %s: %s', v_id_balon, v_result->>'error'),
                'ok',
                FALSE
            );
        END IF;
    END LOOP;

    RETURN json_build_object(
        'ok', TRUE,
        'cantidad', COALESCE(array_length(v_balones, 1), 0),
        'error', NULL
    );
END;
$$;


--
-- Name: bal_aprobar_baja_balon(integer, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bal_aprobar_baja_balon(p_id_baja integer, p_id_usuario_autoriza integer, p_id_usuario_auditoria integer DEFAULT NULL::integer) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_id_balon INTEGER;
    v_id_motivo_baja INTEGER;
    v_motivo_detalle VARCHAR;
    v_id_cliente_comprador INTEGER;
    v_id_comprobante_venta INTEGER;
    v_observacion VARCHAR;
    v_fecha_baja DATE;
    v_id_movimiento INTEGER;
    v_id_estado_baja INTEGER;
    v_id_estado_anterior INTEGER;
    v_nombre_motivo VARCHAR;
    v_nombre_estado_destino VARCHAR;
    v_id_almacen INTEGER;
    v_id_usuario INTEGER;
    v_codigo_tipo_comp VARCHAR;
    v_codigo_tipo_doc_ref VARCHAR;
    v_mov JSON;
BEGIN
    SET TIME ZONE 'America/Lima';

    IF p_id_usuario_autoriza IS NULL THEN
        RETURN json_build_object('error', 'Debe indicar el administrador autorizador', 'registro', NULL);
    END IF;

    -- Rol Administrador + permiso bajas_balon.aprobar (o auth.todo). Permite auto-aprobación.
    IF NOT auth_usuario_es_admin_con_permiso(p_id_usuario_autoriza, 'bajas_balon.aprobar') THEN
        RETURN json_build_object(
            'error',
            'La baja debe ser autorizada por un administrador con permiso de aprobar bajas de cilindro',
            'registro',
            NULL
        );
    END IF;

    SELECT
        bb.id_balon,
        bb.id_motivo_baja,
        bb.motivo_detalle,
        bb.id_cliente_comprador,
        bb.id_comprobante_venta,
        bb.observacion,
        bb.fecha_baja
    INTO
        v_id_balon,
        v_id_motivo_baja,
        v_motivo_detalle,
        v_id_cliente_comprador,
        v_id_comprobante_venta,
        v_observacion,
        v_fecha_baja
    FROM bal_baja_balon bb
    WHERE bb.id = p_id_baja
      AND bb.estado = 1
      AND bb.estado_aprobacion = 'PENDIENTE';

    IF v_id_balon IS NULL THEN
        RETURN json_build_object('error', 'La solicitud de baja no existe o ya fue procesada', 'registro', NULL);
    END IF;

    SELECT id_estado_balon, id_almacen
    INTO v_id_estado_anterior, v_id_almacen
    FROM bal_balon
    WHERE id = v_id_balon AND estado = 1;

    IF NOT FOUND THEN
        RETURN json_build_object('error', 'El balón indicado no existe o está inactivo', 'registro', NULL);
    END IF;

    SELECT lo.nombre
    INTO v_nombre_motivo
    FROM gen_lista_opciones lo
    INNER JOIN gen_lista l ON lo.id_lista = l.id
    WHERE lo.id = v_id_motivo_baja
      AND l.nombre = 'MotivoBajaBalon'
      AND lo.estado = 1;

    v_nombre_estado_destino := CASE
        WHEN v_nombre_motivo = 'ROBO' THEN 'ROBO'
        ELSE 'DADO_DE_BAJA'
    END;

    SELECT lo.id INTO v_id_estado_baja
    FROM gen_lista_opciones lo
    INNER JOIN gen_lista l ON lo.id_lista = l.id
    WHERE l.nombre = 'EstadoBalon' AND lo.nombre = v_nombre_estado_destino AND lo.estado = 1;

    IF v_id_estado_baja IS NULL THEN
        RETURN json_build_object(
            'error',
            format('No está configurado el estado %s', v_nombre_estado_destino),
            'registro', NULL
        );
    END IF;

    v_id_usuario := COALESCE(p_id_usuario_auditoria, p_id_usuario_autoriza);

    IF v_nombre_motivo = 'VENDIDO' THEN
        v_codigo_tipo_doc_ref := NULL;
        IF v_id_comprobante_venta IS NOT NULL THEN
            SELECT lo.descripcion INTO v_codigo_tipo_comp
            FROM ven_comprobante c
            INNER JOIN gen_lista_opciones lo ON lo.id = c.id_tipo_comprobante
            WHERE c.id = v_id_comprobante_venta AND c.estado = 1;

            v_codigo_tipo_doc_ref := CASE
                WHEN v_codigo_tipo_comp = '01' THEN 'FACTURA'
                WHEN v_codigo_tipo_comp = '03' THEN 'BOLETA'
                WHEN v_codigo_tipo_comp IN ('NV', 'VSD') THEN 'NOTA_VENTA'
                ELSE 'FACTURA'
            END;
        END IF;

        -- Movimiento SALIDA_VENTA con trazabilidad al comprobante (estado lo aplica esta función)
        v_mov := bal_registrar_salida_documento(
            v_id_balon,
            'SALIDA_VENTA',
            v_id_comprobante_venta,
            v_codigo_tipo_doc_ref,
            v_id_cliente_comprador,
            v_id_almacen,
            NULL,
            FALSE,
            NULL,
            COALESCE(v_observacion, 'Baja por venta de cilindro'),
            v_id_usuario
        );

        IF v_mov->>'error' IS NOT NULL THEN
            RETURN json_build_object('error', v_mov->>'error', 'registro', NULL);
        END IF;

        v_id_movimiento := (v_mov->'registro'->>'id')::INTEGER;
    END IF;

    UPDATE bal_baja_balon
    SET
        estado_aprobacion = 'APROBADA',
        id_usuario_autoriza = p_id_usuario_autoriza,
        fecha_autorizacion = NOW(),
        id_movimiento = v_id_movimiento,
        id_usuario_modificacion = v_id_usuario,
        fecha_modificacion = NOW()
    WHERE id = p_id_baja;

    UPDATE bal_balon
    SET
        id_estado_balon = v_id_estado_baja,
        id_almacen = NULL,
        id_cliente_ubicacion = CASE WHEN v_nombre_motivo = 'VENDIDO' THEN v_id_cliente_comprador ELSE id_cliente_ubicacion END,
        presion_actual = NULL,
        id_usuario_modificacion = v_id_usuario,
        fecha_modificacion = NOW()
    WHERE id = v_id_balon AND estado = 1;

    PERFORM bal_registrar_estado_historial(
        v_id_balon,
        'BAJA_APROBADA',
        p_id_baja,
        v_id_motivo_baja,
        v_id_estado_anterior,
        v_id_estado_baja,
        COALESCE(NULLIF(TRIM(v_observacion), ''), NULLIF(TRIM(v_motivo_detalle), ''), 'Baja aprobada'),
        v_id_usuario,
        NOW()
    );

    RETURN bal_obtener_baja_balon(p_id_baja);
END;
$$;


--
-- Name: bal_asignar_origenes_recarga(integer, numeric, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bal_asignar_origenes_recarga(p_id_producto_gas integer, p_capacidad_requerida numeric, p_id_almacen integer DEFAULT NULL::integer, p_id_balon_preferido integer DEFAULT NULL::integer) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_requerida NUMERIC;
    v_total_disponible NUMERIC := 0;
    v_origenes JSONB := '[]'::JSONB;
    v_id_balon_origen INTEGER;
    v_codigo_balon_origen VARCHAR;
BEGIN
    SET TIME ZONE 'America/Lima';

    IF p_id_producto_gas IS NULL THEN
        RETURN json_build_object('error', 'El producto gas es obligatorio', 'origenes', '[]'::JSON);
    END IF;

    v_requerida := COALESCE(p_capacidad_requerida, 0);
    IF v_requerida <= 0 THEN
        RETURN json_build_object('error', 'La capacidad requerida debe ser mayor a cero', 'origenes', '[]'::JSON);
    END IF;

    IF p_id_almacen IS NULL THEN
        RETURN json_build_object('error', 'El almacén es obligatorio para validar el stock de gas', 'origenes', '[]'::JSON);
    END IF;

    v_total_disponible := inv_stock_producto(p_id_producto_gas, p_id_almacen);

    IF v_total_disponible < v_requerida THEN
        RETURN json_build_object(
            'error',
            format(
                'Stock insuficiente de gas en almacén (disponible: %s m³, requerido: %s m³)',
                TRIM(TO_CHAR(v_total_disponible, 'FM999999990.####')),
                TRIM(TO_CHAR(v_requerida, 'FM999999990.####'))
            ),
            'origenes', '[]'::JSON,
            'total_disponible', v_total_disponible,
            'requerido', v_requerida
        );
    END IF;

    -- Balón de referencia: el preferido si es válido, si no el EMPRESA/EN_ALMACEN más
    -- antiguo del mismo gas (solo para trazabilidad, no reparte m³ real por cilindro).
    IF p_id_balon_preferido IS NOT NULL THEN
        SELECT b.id, b.codigo_balon INTO v_id_balon_origen, v_codigo_balon_origen
        FROM bal_balon b
        WHERE b.id = p_id_balon_preferido AND b.estado = 1;
    END IF;

    IF v_id_balon_origen IS NULL THEN
        SELECT b.id, b.codigo_balon INTO v_id_balon_origen, v_codigo_balon_origen
        FROM bal_balon b
        LEFT JOIN gen_lista_opciones prop ON prop.id = b.id_propietario
        LEFT JOIN gen_lista_opciones eb ON eb.id = b.id_estado_balon
        WHERE b.estado = 1
          AND COALESCE(prop.nombre, '') IN ('EMPRESA', 'PROPIA')
          AND COALESCE(eb.nombre, '') = 'EN_ALMACEN'
          AND b.id_producto_gas = p_id_producto_gas
          AND b.id_almacen = p_id_almacen
        ORDER BY b.fecha_creacion ASC NULLS LAST, b.id ASC
        LIMIT 1;
    END IF;

    IF v_id_balon_origen IS NOT NULL THEN
        v_origenes := jsonb_build_array(
            jsonb_build_object(
                'id_balon', v_id_balon_origen,
                'codigo_balon', v_codigo_balon_origen,
                'cantidad', v_requerida,
                'orden', 1
            )
        );
    END IF;

    RETURN json_build_object(
        'origenes', v_origenes,
        'requerido', v_requerida,
        'total_disponible', v_total_disponible,
        'id_balon_origen_principal', v_id_balon_origen,
        'etiqueta', CASE
            WHEN v_codigo_balon_origen IS NOT NULL THEN
                v_codigo_balon_origen || ' (' || TRIM(TO_CHAR(v_requerida, 'FM999999990.####')) || ' m³)'
            ELSE NULL
        END
    );
END;
$$;


--
-- Name: bal_capacidad_disponible_balon(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bal_capacidad_disponible_balon(p_id_balon integer) RETURNS numeric
    LANGUAGE plpgsql STABLE
    AS $$
DECLARE
    v_disponible NUMERIC;
BEGIN
    SELECT COALESCE(tb.capacidad, 0)
    INTO v_disponible
    FROM bal_balon b
    LEFT JOIN bal_tipo_balon tb ON tb.id = b.id_tipo_balon
    WHERE b.id = p_id_balon
      AND b.estado = 1;

    RETURN COALESCE(v_disponible, 0);
END;
$$;


--
-- Name: bal_cerrar_ruta_pueblo(integer, numeric, character varying, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bal_cerrar_ruta_pueblo(p_id integer, p_m3_reportado_ventas numeric DEFAULT NULL::numeric, p_observacion character varying DEFAULT NULL::character varying, p_id_usuario_auditoria integer DEFAULT NULL::integer) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_estado VARCHAR;
    v_id_estado INTEGER;
    v_m3_calc NUMERIC;
    v_m3_rep NUMERIC;
    v_tolerancia NUMERIC;
    v_descuadre NUMERIC;
    v_pendientes INTEGER;
BEGIN
    SET TIME ZONE 'America/Lima';

    SELECT er.nombre, r.m3_calculado, r.tolerancia_m3, r.m3_reportado_ventas
    INTO v_estado, v_m3_calc, v_tolerancia, v_m3_rep
    FROM bal_ruta_pueblo r
    LEFT JOIN gen_lista_opciones er ON er.id = r.id_estado
    WHERE r.id = p_id AND r.estado = 1;

    IF v_estado IS NULL THEN
        RETURN json_build_object('error', 'Ruta no encontrada', 'registro', NULL);
    END IF;

    IF v_estado = 'CERRADA' THEN
        RETURN bal_obtener_ruta_pueblo(p_id);
    END IF;

    IF v_estado = 'CANCELADA' THEN
        RETURN json_build_object('error', 'No se puede cerrar una ruta cancelada', 'registro', NULL);
    END IF;

    SELECT COUNT(*)::INT INTO v_pendientes
    FROM bal_ruta_pueblo_detalle d
    WHERE d.id_ruta_pueblo = p_id AND d.estado = 1 AND d.lb_retorno IS NULL;

    IF v_pendientes > 0 THEN
        RETURN json_build_object(
            'error',
            format('Faltan %s cilindro(s) sin libras de retorno', v_pendientes),
            'registro',
            NULL
        );
    END IF;

    SELECT COALESCE(SUM(d.m3_delta), 0) INTO v_m3_calc
    FROM bal_ruta_pueblo_detalle d
    WHERE d.id_ruta_pueblo = p_id AND d.estado = 1;

    v_m3_rep := COALESCE(p_m3_reportado_ventas, v_m3_rep);
    IF v_m3_rep IS NULL THEN
        RETURN json_build_object(
            'error',
            'Indica los mÂ³ reportados por el repartidor (ventas de la ruta)',
            'registro',
            NULL
        );
    END IF;

    v_descuadre := ROUND(v_m3_calc - v_m3_rep, 4);

    SELECT lo.id INTO v_id_estado
    FROM gen_lista_opciones lo
    INNER JOIN gen_lista l ON l.id = lo.id_lista
    WHERE l.nombre = 'EstadoRutaPueblo' AND lo.nombre = 'CERRADA' AND lo.estado = 1
    LIMIT 1;

    UPDATE bal_ruta_pueblo
    SET
        m3_calculado = v_m3_calc,
        m3_reportado_ventas = v_m3_rep,
        descuadre_m3 = v_descuadre,
        id_estado = v_id_estado,
        observacion = CASE
            WHEN p_observacion IS NULL THEN observacion
            ELSE NULLIF(TRIM(p_observacion), '')
        END,
        id_usuario_modificacion = p_id_usuario_auditoria,
        fecha_modificacion = NOW()
    WHERE id = p_id;

    RETURN bal_obtener_ruta_pueblo(p_id);
END;
$$;


--
-- Name: bal_consumir_capacidad_balon_origen(integer, numeric, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bal_consumir_capacidad_balon_origen(p_id_balon integer, p_cantidad numeric, p_id_usuario_auditoria integer DEFAULT NULL::integer) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_disponible NUMERIC;
    v_nuevo NUMERIC;
BEGIN
    IF p_id_balon IS NULL THEN
        RETURN json_build_object('error', 'El balón origen es obligatorio');
    END IF;

    IF COALESCE(p_cantidad, 0) <= 0 THEN
        RETURN json_build_object('error', 'La cantidad a consumir debe ser mayor a cero');
    END IF;

    v_disponible := bal_capacidad_disponible_balon(p_id_balon);

    IF v_disponible < p_cantidad THEN
        RETURN json_build_object(
            'error',
            format(
                'El balón origen no tiene capacidad suficiente (disponible: %s, requerido: %s)',
                v_disponible,
                p_cantidad
            )
        );
    END IF;

    v_nuevo := GREATEST(v_disponible - p_cantidad, 0);

    RETURN json_build_object(
        'ok', TRUE,
        'consumido', p_cantidad,
        'quedo_vacio', v_nuevo <= 0
    );
END;
$$;


--
-- Name: bal_consumir_capacidad_origenes_recarga(json, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bal_consumir_capacidad_origenes_recarga(p_origenes json, p_id_usuario_auditoria integer DEFAULT NULL::integer) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    o JSONB;
    v_consumo JSON;
    v_consumidos JSONB := '[]'::JSONB;
    v_arr JSONB;
BEGIN
    IF p_origenes IS NULL THEN
        RETURN json_build_object('error', 'La asignación de orígenes es obligatoria');
    END IF;

    v_arr := CASE
        WHEN json_typeof(p_origenes) = 'array' THEN p_origenes::JSONB
        ELSE '[]'::JSONB
    END;

    IF jsonb_array_length(v_arr) = 0 THEN
        RETURN json_build_object('error', 'La asignación de orígenes es obligatoria');
    END IF;

    FOR o IN SELECT * FROM jsonb_array_elements(v_arr)
    LOOP
        v_consumo := bal_consumir_capacidad_balon_origen(
            (o->>'id_balon')::INTEGER,
            (o->>'cantidad')::NUMERIC,
            p_id_usuario_auditoria
        );

        IF v_consumo->>'error' IS NOT NULL THEN
            RETURN json_build_object('error', v_consumo->>'error');
        END IF;

        v_consumidos := v_consumidos || jsonb_build_array(
            jsonb_build_object(
                'id_balon', (o->>'id_balon')::INTEGER,
                'cantidad', (o->>'cantidad')::NUMERIC,
                'quedo_vacio', v_consumo->'quedo_vacio'
            )
        );
    END LOOP;

    RETURN json_build_object(
        'ok', TRUE,
        'consumidos', v_consumidos,
        'id_balon_origen_principal', (v_arr->0->>'id_balon')::INTEGER
    );
END;
$$;


--
-- Name: bal_crear_alquiler(character varying, integer, integer, date, date, date, numeric, numeric, integer, character varying, integer, integer, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bal_crear_alquiler(p_numero_alquiler character varying DEFAULT NULL::character varying, p_id_cliente integer DEFAULT NULL::integer, p_id_almacen integer DEFAULT NULL::integer, p_fecha_inicio date DEFAULT NULL::date, p_fecha_fin_pactada date DEFAULT NULL::date, p_fecha_fin_real date DEFAULT NULL::date, p_tarifa_diaria numeric DEFAULT 0, p_total_cobrado numeric DEFAULT 0, p_id_estado integer DEFAULT NULL::integer, p_observacion character varying DEFAULT NULL::character varying, p_id_comprobante_venta integer DEFAULT NULL::integer, p_id_producto_regulador integer DEFAULT NULL::integer, p_id_producto_stock integer DEFAULT NULL::integer, p_id_usuario_auditoria integer DEFAULT NULL::integer) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_id INTEGER;
    v_numero VARCHAR;
    v_corr JSON;
    v_prod RECORD;
    v_mov JSON;
    v_id_estado INTEGER;
BEGIN
    SET TIME ZONE 'America/Lima';

    v_numero := NULLIF(TRIM(p_numero_alquiler), '');
    IF v_numero IS NULL THEN
        v_corr := bal_obtener_siguiente_numero_alquiler();
        IF v_corr->>'error' IS NOT NULL OR NULLIF(v_corr->>'numero', '') IS NULL THEN
            RETURN json_build_object(
                'error', COALESCE(v_corr->>'error', 'No se pudo generar el número de alquiler'),
                'registro', NULL
            );
        END IF;
        v_numero := v_corr->>'numero';
    END IF;

    IF p_fecha_inicio IS NULL THEN
        RETURN json_build_object('error', 'La fecha de inicio es obligatoria', 'registro', NULL);
    END IF;

    IF p_fecha_fin_pactada IS NULL THEN
        RETURN json_build_object('error', 'La fecha de fin del alquiler es obligatoria', 'registro', NULL);
    END IF;

    IF p_fecha_fin_pactada < p_fecha_inicio THEN
        RETURN json_build_object(
            'error', 'La fecha de fin no puede ser anterior a la fecha de inicio',
            'registro', NULL
        );
    END IF;

    v_id_estado := p_id_estado;
    IF v_id_estado IS NULL THEN
        SELECT lo.id INTO v_id_estado
        FROM gen_lista_opciones lo
        INNER JOIN gen_lista l ON l.id = lo.id_lista
        WHERE l.nombre = 'EstadoAlquiler' AND lo.nombre = 'ACTIVO' AND lo.estado = 1
        LIMIT 1;

        IF v_id_estado IS NULL THEN
            RETURN json_build_object(
                'error', 'No se encontró el estado ACTIVO del alquiler. Revise el catálogo EstadoAlquiler.',
                'registro', NULL
            );
        END IF;
    END IF;

    IF EXISTS (
        SELECT 1 FROM bal_alquiler WHERE LOWER(TRIM(numero_alquiler)) = LOWER(v_numero)
    ) THEN
        RETURN json_build_object('error', 'Ya existe un alquiler con el número ' || v_numero, 'registro', NULL);
    END IF;

    IF NOT EXISTS (
        SELECT 1 FROM cli_clientes WHERE id = p_id_cliente AND estado = 1
    ) THEN
        RETURN json_build_object('error', 'El cliente indicado no existe o está inactivo', 'registro', NULL);
    END IF;

    IF NOT EXISTS (
        SELECT 1 FROM gen_almacen WHERE id = p_id_almacen AND estado = 1
    ) THEN
        RETURN json_build_object('error', 'El almacén indicado no existe o está inactivo', 'registro', NULL);
    END IF;

    IF p_id_producto_regulador IS NOT NULL AND NOT EXISTS (
        SELECT 1
        FROM pro_producto
        WHERE id = p_id_producto_regulador
          AND estado = 1
          AND COALESCE(es_alquilable, FALSE) = TRUE
    ) THEN
        RETURN json_build_object(
            'error', 'El producto debe ser alquilable y estar activo',
            'registro', NULL
        );
    END IF;

    IF p_id_producto_stock IS NOT NULL THEN
        SELECT
            p.id,
            COALESCE(p.afecta_stock, FALSE) AS afecta_stock,
            COALESCE(p.es_servicio, FALSE) AS es_servicio,
            COALESCE(p.es_gas, FALSE) AS es_gas
        INTO v_prod
        FROM pro_producto p
        WHERE p.id = p_id_producto_stock AND p.estado = 1;

        IF v_prod.id IS NULL THEN
            RETURN json_build_object(
                'error', 'El regulador de stock indicado no existe o está inactivo',
                'registro', NULL
            );
        END IF;

        IF v_prod.es_servicio OR v_prod.es_gas THEN
            RETURN json_build_object(
                'error', 'El regulador de stock debe ser un accesorio físico (no servicio ni gas)',
                'registro', NULL
            );
        END IF;
    END IF;

    INSERT INTO bal_alquiler (
        numero_alquiler, id_cliente, id_almacen, fecha_inicio,
        fecha_fin_pactada, fecha_fin_real, tarifa_diaria, total_cobrado,
        id_estado, observacion, id_comprobante_venta, id_producto_regulador,
        id_producto_stock,
        id_usuario_creacion, id_usuario_modificacion
    )
    VALUES (
        v_numero, p_id_cliente, p_id_almacen, p_fecha_inicio,
        p_fecha_fin_pactada, p_fecha_fin_real, COALESCE(p_tarifa_diaria, 0), COALESCE(p_total_cobrado, 0),
        v_id_estado, p_observacion, p_id_comprobante_venta, p_id_producto_regulador,
        p_id_producto_stock,
        p_id_usuario_auditoria, p_id_usuario_auditoria
    )
    RETURNING id INTO v_id;

    IF p_id_producto_stock IS NOT NULL THEN
    IF COALESCE(v_prod.afecta_stock, FALSE) THEN
        v_mov := inv_registrar_movimiento(
            p_naturaleza                => 'PRODUCTO',
            p_codigo_tipo_movimiento    => 'SALIDA',
            p_fecha                     => p_fecha_inicio,
            p_id_producto               => p_id_producto_stock,
            p_cantidad                  => 1,
            p_id_almacen_origen         => p_id_almacen,
            p_codigo_tipo_documento_origen => 'ALQUILER',
            p_id_documento_origen       => v_id,
            p_glosa                     => 'Salida por alquiler ' || v_numero,
            p_id_usuario_auditoria      => p_id_usuario_auditoria
        );

        IF v_mov->>'error' IS NOT NULL THEN
            RAISE EXCEPTION '%', v_mov->>'error';
        END IF;
    END IF;
    END IF;

    RETURN bal_obtener_alquiler(v_id);
EXCEPTION
    WHEN OTHERS THEN
        RETURN json_build_object('error', SQLERRM, 'registro', NULL);
END;
$$;


--
-- Name: bal_crear_alquiler_detalle(integer, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bal_crear_alquiler_detalle(p_id_alquiler integer, p_id_balon integer, p_id_usuario_auditoria integer DEFAULT NULL::integer) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_id INTEGER;
    v_id_cliente INTEGER;
    v_id_almacen INTEGER;
    v_id_estado_alquilado INTEGER;
    v_mov_result JSON;
BEGIN
    SET TIME ZONE 'America/Lima';

    IF NOT EXISTS (
        SELECT 1 FROM bal_alquiler WHERE id = p_id_alquiler AND estado = 1
    ) THEN
        RETURN json_build_object('error', 'El alquiler indicado no existe o está inactivo', 'registro', NULL);
    END IF;

    IF NOT EXISTS (
        SELECT 1 FROM bal_balon WHERE id = p_id_balon AND estado = 1
    ) THEN
        RETURN json_build_object('error', 'El balón indicado no existe o está inactivo', 'registro', NULL);
    END IF;

    IF EXISTS (
        SELECT 1
        FROM bal_balon b
        LEFT JOIN gen_lista_opciones eb ON eb.id = b.id_estado_balon
        WHERE b.id = p_id_balon
          AND COALESCE(eb.nombre, '') IN ('DADO_DE_BAJA', 'ROBO')
    ) THEN
        RETURN json_build_object(
            'error',
            'No se puede alquilar un cilindro dado de baja o reportado como robo',
            'registro',
            NULL
        );
    END IF;

    IF EXISTS (
        SELECT 1 FROM bal_alquiler_detalle
        WHERE id_alquiler = p_id_alquiler AND id_balon = p_id_balon AND estado = 1
    ) THEN
        RETURN json_build_object('error', 'El balón ya está registrado en este alquiler', 'registro', NULL);
    END IF;

    IF EXISTS (
        SELECT 1
        FROM bal_alquiler_detalle ad
        INNER JOIN bal_alquiler al ON al.id = ad.id_alquiler AND al.estado = 1
        WHERE ad.id_balon = p_id_balon
          AND ad.estado = 1
          AND ad.fecha_devolucion IS NULL
    ) THEN
        RETURN json_build_object(
            'error',
            'El cilindro ya tiene un alquiler activo sin devolver',
            'registro',
            NULL
        );
    END IF;

    IF EXISTS (
        SELECT 1
        FROM bal_prestamo_detalle pd
        INNER JOIN bal_prestamo p ON p.id = pd.id_prestamo AND p.estado = 1
        WHERE pd.id_balon = p_id_balon
          AND pd.estado = 1
          AND pd.fecha_devolucion IS NULL
    ) THEN
        RETURN json_build_object(
            'error',
            'El cilindro está prestado actualmente; no se puede alquilar',
            'registro',
            NULL
        );
    END IF;

    SELECT id_cliente, id_almacen
    INTO v_id_cliente, v_id_almacen
    FROM bal_alquiler
    WHERE id = p_id_alquiler AND estado = 1;

    SELECT lo.id INTO v_id_estado_alquilado
    FROM gen_lista_opciones lo
    INNER JOIN gen_lista l ON lo.id_lista = l.id
    WHERE l.nombre = 'EstadoBalon' AND lo.nombre = 'ALQUILADO' AND lo.estado = 1
    LIMIT 1;

    IF v_id_estado_alquilado IS NULL THEN
        RETURN json_build_object(
            'error',
            'No se encontró el estado ALQUILADO del cilindro. Revise el catálogo EstadoBalon.',
            'registro',
            NULL
        );
    END IF;

    INSERT INTO bal_alquiler_detalle (
        id_alquiler, id_balon,
        id_usuario_creacion, id_usuario_modificacion
    )
    VALUES (
        p_id_alquiler, p_id_balon,
        p_id_usuario_auditoria, p_id_usuario_auditoria
    )
    RETURNING id INTO v_id;

    v_mov_result := inv_registrar_movimiento(
        p_naturaleza                => 'BALON',
        p_codigo_tipo_movimiento    => 'SALIDA_ALQUILER',
        p_fecha                     => NOW(),
        p_id_balon                  => p_id_balon,
        p_cantidad                  => 1,
        p_id_almacen_origen         => v_id_almacen,
        p_id_cliente                => v_id_cliente,
        p_codigo_tipo_documento_origen => 'ALQUILER',
        p_id_documento_origen       => p_id_alquiler,
        p_glosa                     => 'Salida por alquiler',
        p_id_usuario_auditoria      => p_id_usuario_auditoria
    );

    IF v_mov_result->>'error' IS NOT NULL THEN
        RAISE EXCEPTION '%', v_mov_result->>'error';
    END IF;

    -- En cliente no sabemos si consume el gas → contenido DESCONOCIDO.
    UPDATE bal_balon
    SET
        id_cliente_ubicacion = v_id_cliente,
        id_almacen = NULL,
        id_estado_balon = v_id_estado_alquilado,
        id_usuario_modificacion = p_id_usuario_auditoria,
        fecha_modificacion = NOW()
    WHERE id = p_id_balon AND estado = 1;

    RETURN bal_obtener_alquiler_detalle(v_id);
END;
$$;


--
-- Name: bal_crear_balon(character varying, character varying, integer, date, integer, integer, integer, integer, integer, integer, integer, integer, date, integer, date, date, character varying, numeric, character varying, character varying, integer, integer, boolean, smallint, smallint, integer, character varying, numeric, character varying, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bal_crear_balon(p_codigo_balon character varying, p_libro_cilindro character varying DEFAULT NULL::character varying, p_pagina_libro integer DEFAULT NULL::integer, p_fecha_registro date DEFAULT NULL::date, p_id_almacen integer DEFAULT NULL::integer, p_id_cliente_ubicacion integer DEFAULT NULL::integer, p_id_propietario integer DEFAULT NULL::integer, p_id_cliente_propietario integer DEFAULT NULL::integer, p_id_referencia integer DEFAULT NULL::integer, p_id_tipo_balon integer DEFAULT NULL::integer, p_id_producto_gas integer DEFAULT NULL::integer, p_id_estado_balon integer DEFAULT NULL::integer, p_fecha_ultima_prueba_hidrostatica date DEFAULT NULL::date, p_vigencia_prueba_hidrostatica_anios integer DEFAULT NULL::integer, p_fecha_proxima_prueba_hidrostatica date DEFAULT NULL::date, p_fecha_fabricacion date DEFAULT NULL::date, p_numero_recepcion character varying DEFAULT NULL::character varying, p_presion_actual numeric DEFAULT NULL::numeric, p_observacion character varying DEFAULT NULL::character varying, p_numero_serie character varying DEFAULT NULL::character varying, p_id_marca_cilindro integer DEFAULT NULL::integer, p_id_organo_inspector integer DEFAULT NULL::integer, p_organo_inspector_no_aplica boolean DEFAULT false, p_anio_fabricacion smallint DEFAULT NULL::smallint, p_mes_fabricacion smallint DEFAULT NULL::smallint, p_id_planta integer DEFAULT NULL::integer, p_tipo_valvula character varying DEFAULT NULL::character varying, p_peso_aproximado_kg numeric DEFAULT NULL::numeric, p_sello_inspeccion character varying DEFAULT NULL::character varying, p_id_usuario_auditoria integer DEFAULT NULL::integer) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_id INTEGER;
    v_numero_serie VARCHAR;
    v_anio_fabricacion SMALLINT;
    v_mes_fabricacion SMALLINT;
    v_fecha_fabricacion DATE;
    v_vigencia_ph INTEGER;
    v_fecha_ultima_ph DATE;
    v_fecha_proxima_ph DATE;
    v_prop_nombre VARCHAR;
BEGIN
    SET TIME ZONE 'America/Lima';

    IF p_codigo_balon IS NULL OR TRIM(p_codigo_balon) = '' THEN
        RETURN json_build_object('error', 'El código del balón es obligatorio', 'registro', NULL);
    END IF;

    IF p_id_tipo_balon IS NULL THEN
        RETURN json_build_object('error', 'El tipo de balón es obligatorio', 'registro', NULL);
    END IF;

    IF p_id_producto_gas IS NULL THEN
        RETURN json_build_object('error', 'El gas (producto) es obligatorio', 'registro', NULL);
    END IF;

    IF EXISTS (
        SELECT 1 FROM bal_balon
        WHERE LOWER(TRIM(codigo_balon)) = LOWER(TRIM(p_codigo_balon))
    ) THEN
        RETURN json_build_object('error', 'Ya existe un balón con el código ' || TRIM(p_codigo_balon), 'registro', NULL);
    END IF;

    IF p_id_almacen IS NOT NULL AND NOT EXISTS (
        SELECT 1 FROM gen_almacen WHERE id = p_id_almacen AND estado = 1
    ) THEN
        RETURN json_build_object('error', 'El almacén indicado no existe o está inactivo', 'registro', NULL);
    END IF;

    IF NOT EXISTS (
        SELECT 1 FROM bal_tipo_balon WHERE id = p_id_tipo_balon AND estado = 1
    ) THEN
        RETURN json_build_object('error', 'El tipo de balón indicado no existe o está inactivo', 'registro', NULL);
    END IF;

    IF NOT EXISTS (
        SELECT 1 FROM pro_producto
        WHERE id = p_id_producto_gas AND estado = 1 AND es_gas = TRUE
    ) THEN
        RETURN json_build_object('error', 'El gas indicado no existe, está inactivo o no es un producto de gas', 'registro', NULL);
    END IF;

    IF p_mes_fabricacion IS NOT NULL AND (p_mes_fabricacion < 1 OR p_mes_fabricacion > 12) THEN
        RETURN json_build_object('error', 'El mes de fabricación debe estar entre 1 y 12', 'registro', NULL);
    END IF;

    IF p_id_planta IS NOT NULL AND NOT EXISTS (
        SELECT 1 FROM cli_clientes WHERE id = p_id_planta AND estado = 1
    ) THEN
        RETURN json_build_object('error', 'La planta / proveedor indicado no existe o está inactivo', 'registro', NULL);
    END IF;

    -- Propiedad PLANTA exige proveedor concreto (id_planta); CLIENTE exige id_cliente_propietario.
    IF p_id_propietario IS NOT NULL THEN
        SELECT UPPER(glo.nombre) INTO v_prop_nombre
        FROM gen_lista_opciones glo
        WHERE glo.id = p_id_propietario;

        IF v_prop_nombre = 'PLANTA' AND p_id_planta IS NULL THEN
            RETURN json_build_object(
                'error', 'Si el propietario es planta, debe indicar el proveedor concreto (ej. Swiss Gas)',
                'registro', NULL
            );
        END IF;

        IF v_prop_nombre = 'CLIENTE' AND p_id_cliente_propietario IS NULL THEN
            RETURN json_build_object(
                'error', 'Si el propietario es cliente, debe indicar el cliente propietario',
                'registro', NULL
            );
        END IF;

        IF v_prop_nombre IS DISTINCT FROM 'PLANTA' THEN
            p_id_planta := NULL;
        END IF;

        IF v_prop_nombre IS DISTINCT FROM 'CLIENTE' THEN
            p_id_cliente_propietario := NULL;
        END IF;
    ELSIF p_id_planta IS NOT NULL THEN
        -- Planta sin propietario PLANTA: se ignora para no dejar datos inconsistentes.
        p_id_planta := NULL;
    END IF;

    v_numero_serie := COALESCE(NULLIF(TRIM(p_numero_serie), ''), TRIM(p_codigo_balon));

    v_anio_fabricacion := COALESCE(
        p_anio_fabricacion,
        CASE WHEN p_fecha_fabricacion IS NOT NULL THEN EXTRACT(YEAR FROM p_fecha_fabricacion)::SMALLINT END
    );
    v_mes_fabricacion := COALESCE(
        p_mes_fabricacion,
        CASE WHEN p_fecha_fabricacion IS NOT NULL THEN EXTRACT(MONTH FROM p_fecha_fabricacion)::SMALLINT END
    );

    IF v_anio_fabricacion IS NOT NULL AND v_mes_fabricacion IS NOT NULL THEN
        v_fecha_fabricacion := make_date(v_anio_fabricacion::INT, v_mes_fabricacion::INT, 1);
    ELSE
        v_fecha_fabricacion := CASE
            WHEN p_fecha_fabricacion IS NOT NULL
            THEN make_date(
                EXTRACT(YEAR FROM p_fecha_fabricacion)::INT,
                EXTRACT(MONTH FROM p_fecha_fabricacion)::INT,
                1
            )
            ELSE NULL
        END;
    END IF;

    v_vigencia_ph := COALESCE(p_vigencia_prueba_hidrostatica_anios, 5);

    IF p_id_tipo_balon IS NOT NULL THEN
        SELECT COALESCE(p_vigencia_prueba_hidrostatica_anios, tb.vigencia_ph_anios, 5)
        INTO v_vigencia_ph
        FROM bal_tipo_balon tb
        WHERE tb.id = p_id_tipo_balon;
    END IF;

    -- Base PH: última prueba explícita, o fabricación (mes/año del lomo) + vigencia del tipo/gas
    v_fecha_ultima_ph := CASE
        WHEN p_fecha_ultima_prueba_hidrostatica IS NOT NULL
        THEN make_date(
            EXTRACT(YEAR FROM p_fecha_ultima_prueba_hidrostatica)::INT,
            EXTRACT(MONTH FROM p_fecha_ultima_prueba_hidrostatica)::INT,
            1
        )
        ELSE v_fecha_fabricacion
    END;

    v_fecha_proxima_ph := COALESCE(
        CASE
            WHEN p_fecha_proxima_prueba_hidrostatica IS NOT NULL
            THEN make_date(
                EXTRACT(YEAR FROM p_fecha_proxima_prueba_hidrostatica)::INT,
                EXTRACT(MONTH FROM p_fecha_proxima_prueba_hidrostatica)::INT,
                1
            )
        END,
        CASE
            WHEN v_fecha_ultima_ph IS NOT NULL
            THEN (v_fecha_ultima_ph + make_interval(years => v_vigencia_ph))::DATE
        END
    );

    INSERT INTO bal_balon (
        codigo_balon, numero_serie, libro_cilindro, pagina_libro, fecha_registro,
        id_almacen, id_cliente_ubicacion, id_propietario, id_cliente_propietario,
        id_referencia, id_marca_cilindro, id_organo_inspector, organo_inspector_no_aplica,
        id_tipo_balon, id_producto_gas, id_estado_balon, id_planta,
        fecha_ultima_prueba_hidrostatica, vigencia_prueba_hidrostatica_anios,
        fecha_proxima_prueba_hidrostatica, fecha_fabricacion, anio_fabricacion, mes_fabricacion,
        numero_recepcion, presion_actual, observacion, tipo_valvula,
        peso_aproximado_kg, sello_inspeccion,
        id_usuario_creacion, id_usuario_modificacion
    )
    VALUES (
        TRIM(p_codigo_balon), v_numero_serie, p_libro_cilindro, p_pagina_libro,
        COALESCE(p_fecha_registro, CURRENT_DATE),
        p_id_almacen, p_id_cliente_ubicacion, p_id_propietario, p_id_cliente_propietario,
        p_id_referencia, p_id_marca_cilindro, p_id_organo_inspector,
        COALESCE(p_organo_inspector_no_aplica, FALSE),
        p_id_tipo_balon, p_id_producto_gas, p_id_estado_balon, p_id_planta,
        v_fecha_ultima_ph, v_vigencia_ph,
        v_fecha_proxima_ph, v_fecha_fabricacion, v_anio_fabricacion, v_mes_fabricacion,
        p_numero_recepcion, p_presion_actual, p_observacion,
        NULLIF(TRIM(p_tipo_valvula), ''),
        p_peso_aproximado_kg,
        NULLIF(TRIM(p_sello_inspeccion), ''),
        p_id_usuario_auditoria, p_id_usuario_auditoria
    )
    RETURNING id INTO v_id;

    IF v_fecha_ultima_ph IS NOT NULL THEN
        PERFORM bal_registrar_ph_historial(
            v_id,
            v_fecha_ultima_ph,
            v_vigencia_ph,
            p_id_organo_inspector,
            COALESCE(p_organo_inspector_no_aplica, FALSE),
            NULL,
            NULL,
            NULL,
            CASE
                WHEN p_fecha_ultima_prueba_hidrostatica IS NOT NULL THEN 'Registro inicial de PH'
                ELSE 'PH calculado desde fabricación (mes/año)'
            END,
            p_id_usuario_auditoria
        );
    END IF;

    RETURN bal_obtener_balon(v_id);
END;
$$;


--
-- Name: bal_crear_mantenimiento(integer, date, integer, date, character varying, numeric, boolean, integer, integer, integer, integer, character varying, integer, integer, integer, boolean, character varying); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bal_crear_mantenimiento(p_id_balon integer, p_fecha_ingreso date, p_id_tipo_mantenimiento integer DEFAULT NULL::integer, p_fecha_salida date DEFAULT NULL::date, p_descripcion character varying DEFAULT NULL::character varying, p_costo numeric DEFAULT 0, p_es_externo boolean DEFAULT false, p_id_proveedor integer DEFAULT NULL::integer, p_id_estado integer DEFAULT NULL::integer, p_id_comprobante_venta integer DEFAULT NULL::integer, p_id_comprobante_compra integer DEFAULT NULL::integer, p_observacion character varying DEFAULT NULL::character varying, p_id_usuario_auditoria integer DEFAULT NULL::integer, p_vigencia_ph_anios integer DEFAULT NULL::integer, p_id_organo_inspector integer DEFAULT NULL::integer, p_organo_inspector_no_aplica boolean DEFAULT NULL::boolean, p_numero_certificado_ph character varying DEFAULT NULL::character varying) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_id INTEGER;
    v_id_estado_balon_mantenimiento INTEGER;
    v_id_estado_mantenimiento INTEGER;
    v_id_estado_finalizado INTEGER;
    v_id_almacen INTEGER;
    v_id_cliente_ubicacion INTEGER;
    v_id_cliente_propietario INTEGER;
    v_id_cliente_mov INTEGER;
    v_nombre_propietario VARCHAR;
    v_es_servicio_cliente BOOLEAN;
    v_mov_result JSON;
    v_obs_movimiento VARCHAR;
BEGIN
    SET TIME ZONE 'America/Lima';

    IF p_fecha_ingreso IS NULL THEN
        RETURN json_build_object('error', 'La fecha de ingreso es obligatoria', 'registro', NULL);
    END IF;

    IF NOT EXISTS (
        SELECT 1 FROM bal_balon WHERE id = p_id_balon AND estado = 1
    ) THEN
        RETURN json_build_object('error', 'El balón indicado no existe o está inactivo', 'registro', NULL);
    END IF;

    SELECT
        b.id_almacen,
        b.id_cliente_ubicacion,
        b.id_cliente_propietario,
        UPPER(COALESCE(prop.nombre, ''))
    INTO
        v_id_almacen,
        v_id_cliente_ubicacion,
        v_id_cliente_propietario,
        v_nombre_propietario
    FROM bal_balon b
    LEFT JOIN gen_lista_opciones prop ON prop.id = b.id_propietario
    WHERE b.id = p_id_balon AND b.estado = 1;

    -- Servicio entrante: cilindro del cliente o envase que viene con ubicación de cliente
    -- (ej. prestado / propio traído a taller). Inventario: sin cliente, stock de empresa.
    v_es_servicio_cliente := (
        v_nombre_propietario = 'CLIENTE'
        OR v_id_cliente_ubicacion IS NOT NULL
    );

    v_id_cliente_mov := COALESCE(
        v_id_cliente_ubicacion,
        v_id_cliente_propietario
    );

    IF p_id_comprobante_venta IS NOT NULL AND v_id_cliente_mov IS NULL THEN
        SELECT id_cliente INTO v_id_cliente_mov
        FROM ven_comprobante
        WHERE id = p_id_comprobante_venta AND estado = 1;
    END IF;

    SELECT lo.id INTO v_id_estado_balon_mantenimiento
    FROM gen_lista_opciones lo
    INNER JOIN gen_lista l ON lo.id_lista = l.id
    WHERE l.nombre = 'EstadoBalon' AND lo.nombre = 'EN_MANTENIMIENTO' AND lo.estado = 1
    LIMIT 1;

    IF v_id_estado_balon_mantenimiento IS NULL THEN
        RETURN json_build_object(
            'error',
            'No se encontró el estado EN_MANTENIMIENTO del cilindro. Revise el catálogo EstadoBalon.',
            'registro',
            NULL
        );
    END IF;

    SELECT lo.id INTO v_id_estado_finalizado
    FROM gen_lista_opciones lo
    INNER JOIN gen_lista l ON lo.id_lista = l.id
    WHERE l.nombre = 'EstadoMantenimiento' AND lo.nombre = 'FINALIZADO' AND lo.estado = 1
    LIMIT 1;

    IF p_id_estado IS NULL THEN
        SELECT lo.id INTO v_id_estado_mantenimiento
        FROM gen_lista_opciones lo
        INNER JOIN gen_lista l ON lo.id_lista = l.id
        WHERE l.nombre = 'EstadoMantenimiento' AND lo.nombre = 'PENDIENTE' AND lo.estado = 1
        LIMIT 1;
    ELSIF v_id_estado_finalizado IS NOT NULL AND p_id_estado = v_id_estado_finalizado THEN
        RETURN json_build_object(
            'error', 'No se puede crear un mantenimiento finalizado. Use la acción Finalizar.',
            'registro', NULL
        );
    ELSE
        v_id_estado_mantenimiento := p_id_estado;
    END IF;

    IF v_es_servicio_cliente THEN
        v_obs_movimiento := COALESCE(p_observacion, 'Recepción de cilindro para servicio de mantenimiento');
    ELSE
        v_obs_movimiento := COALESCE(p_observacion, 'Salida a mantenimiento');
    END IF;

    INSERT INTO bal_mantenimiento (
        id_balon, id_tipo_mantenimiento, fecha_ingreso, fecha_salida,
        descripcion, costo, es_externo, id_proveedor, id_estado,
        id_comprobante_venta, id_comprobante_compra, observacion,
        id_usuario_creacion, id_usuario_modificacion
    )
    VALUES (
        p_id_balon, p_id_tipo_mantenimiento, p_fecha_ingreso, p_fecha_salida,
        p_descripcion, COALESCE(p_costo, 0), COALESCE(p_es_externo, FALSE), p_id_proveedor,
        v_id_estado_mantenimiento,
        p_id_comprobante_venta, p_id_comprobante_compra, p_observacion,
        p_id_usuario_auditoria, p_id_usuario_auditoria
    )
    RETURNING id INTO v_id;

    IF v_es_servicio_cliente THEN
        v_mov_result := inv_registrar_movimiento(
            p_naturaleza                => 'BALON',
            p_codigo_tipo_movimiento    => 'ENTRADA_MANTENIMIENTO',
            p_fecha                     => p_fecha_ingreso,
            p_id_balon                  => p_id_balon,
            p_cantidad                  => 1,
            p_id_almacen_destino        => v_id_almacen,
            p_id_cliente                => v_id_cliente_mov,
            p_codigo_tipo_documento_origen => 'MANTENIMIENTO',
            p_id_documento_origen       => v_id,
            p_glosa                     => v_obs_movimiento,
            p_id_usuario_auditoria      => p_id_usuario_auditoria
        );
    ELSE
        v_mov_result := inv_registrar_movimiento(
            p_naturaleza                => 'BALON',
            p_codigo_tipo_movimiento    => 'SALIDA_MANTENIMIENTO',
            p_fecha                     => p_fecha_ingreso,
            p_id_balon                  => p_id_balon,
            p_cantidad                  => 1,
            p_id_almacen_origen         => v_id_almacen,
            p_id_cliente                => v_id_cliente_mov,
            p_codigo_tipo_documento_origen => 'MANTENIMIENTO',
            p_id_documento_origen       => v_id,
            p_glosa                     => v_obs_movimiento,
            p_id_usuario_auditoria      => p_id_usuario_auditoria
        );
    END IF;

    IF v_mov_result->>'error' IS NOT NULL THEN
        RAISE EXCEPTION '%', v_mov_result->>'error';
    END IF;

    -- Custodia en taller: EN_MANTENIMIENTO. Contenido: vacío (purga / PH / reparación).
    -- No se borra id_cliente_ubicacion (sirve para devolver al cliente al finalizar).
    UPDATE bal_balon
    SET
        id_estado_balon = v_id_estado_balon_mantenimiento,
        id_cliente_ubicacion = CASE
            WHEN v_es_servicio_cliente THEN COALESCE(id_cliente_ubicacion, v_id_cliente_mov)
            ELSE id_cliente_ubicacion
        END,
        id_usuario_modificacion = p_id_usuario_auditoria,
        fecha_modificacion = NOW()
    WHERE id = p_id_balon AND estado = 1;

    PERFORM bal_sync_ph_desde_mantenimiento(
        v_id,
        p_id_usuario_auditoria,
        p_vigencia_ph_anios,
        p_id_organo_inspector,
        p_organo_inspector_no_aplica,
        p_numero_certificado_ph
    );

    RETURN bal_obtener_mantenimiento(v_id);
END;
$$;


--
-- Name: bal_crear_movimiento_recarga(date, integer, integer, numeric, integer, character varying, character varying, character varying, character varying, character varying, character varying, integer, date, character varying, date, date, integer, character varying, integer, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bal_crear_movimiento_recarga(p_fecha_salida_almacen date, p_id_balon integer, p_id_producto integer DEFAULT NULL::integer, p_capacidad numeric DEFAULT NULL::numeric, p_id_unidad_medida integer DEFAULT NULL::integer, p_serie_guia_salida character varying DEFAULT NULL::character varying, p_numero_guia_salida character varying DEFAULT NULL::character varying, p_serie_guia_ingreso character varying DEFAULT NULL::character varying, p_numero_guia_ingreso character varying DEFAULT NULL::character varying, p_serie_factura character varying DEFAULT NULL::character varying, p_numero_factura character varying DEFAULT NULL::character varying, p_id_comprobante integer DEFAULT NULL::integer, p_fecha_llegada_almacen date DEFAULT NULL::date, p_lote character varying DEFAULT NULL::character varying, p_fecha_vencimiento_lote date DEFAULT NULL::date, p_fecha_prueba_hidrostatica date DEFAULT NULL::date, p_id_proveedor integer DEFAULT NULL::integer, p_observacion character varying DEFAULT NULL::character varying, p_id_almacen integer DEFAULT NULL::integer, p_id_comprobante_compra integer DEFAULT NULL::integer, p_id_usuario_auditoria integer DEFAULT NULL::integer) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_id INTEGER;
    v_id_tipo_recarga INTEGER;
    v_es_empresa BOOLEAN;
    v_capacidad_tipo NUMERIC;
    v_id_estado_recarga_externa INTEGER;
    v_id_estado_en_almacen INTEGER;
    v_id_tipo_doc_recarga INTEGER;
    v_id_tipo_salida INTEGER;
    v_id_tipo_entrada INTEGER;
    v_mov JSON;
    v_obs VARCHAR;
    v_id_producto_gas_balon INTEGER;
BEGIN
    SET TIME ZONE 'America/Lima';

    IF p_fecha_salida_almacen IS NULL THEN
        RETURN json_build_object('error', 'La fecha de salida de almacén es obligatoria', 'registro', NULL);
    END IF;

    IF NOT EXISTS (
        SELECT 1 FROM bal_balon WHERE id = p_id_balon AND estado = 1
    ) THEN
        RETURN json_build_object('error', 'El balón indicado no existe o está inactivo', 'registro', NULL);
    END IF;

    SELECT
        COALESCE(prop.nombre, '') = 'EMPRESA',
        COALESCE(tb.capacidad, p_capacidad, 0)
    INTO v_es_empresa, v_capacidad_tipo
    FROM bal_balon b
    LEFT JOIN gen_lista_opciones prop ON prop.id = b.id_propietario
    LEFT JOIN bal_tipo_balon tb ON tb.id = b.id_tipo_balon
    WHERE b.id = p_id_balon;

    IF NOT COALESCE(v_es_empresa, FALSE) THEN
        RETURN json_build_object(
            'error',
            'La recarga en planta externa solo aplica a balones de propiedad EMPRESA',
            'registro',
            NULL
        );
    END IF;

    IF p_id_comprobante_compra IS NOT NULL AND NOT EXISTS (
        SELECT 1 FROM com_comprobante_compra WHERE id = p_id_comprobante_compra AND estado = 1
    ) THEN
        RETURN json_build_object(
            'error',
            'El comprobante de compra indicado no existe o está inactivo',
            'registro',
            NULL
        );
    END IF;

    SELECT lo.id INTO v_id_tipo_recarga
    FROM gen_lista_opciones lo
    INNER JOIN gen_lista l ON lo.id_lista = l.id
    WHERE l.nombre = 'TipoRecarga' AND lo.nombre = 'PLANTA_EXTERNA' AND lo.estado = 1
    LIMIT 1;

    SELECT lo.id INTO v_id_estado_recarga_externa
    FROM gen_lista_opciones lo
    INNER JOIN gen_lista l ON lo.id_lista = l.id
    WHERE l.nombre = 'EstadoBalon' AND lo.nombre = 'EN_RECARGA_EXTERNA' AND lo.estado = 1
    LIMIT 1;

    SELECT lo.id INTO v_id_estado_en_almacen
    FROM gen_lista_opciones lo
    INNER JOIN gen_lista l ON lo.id_lista = l.id
    WHERE l.nombre = 'EstadoBalon' AND lo.nombre = 'EN_ALMACEN' AND lo.estado = 1
    LIMIT 1;

    SELECT lo.id INTO v_id_tipo_doc_recarga
    FROM gen_lista_opciones lo
    INNER JOIN gen_lista l ON lo.id_lista = l.id
    WHERE l.nombre = 'TipoDocumentoRef' AND lo.nombre = 'RECARGA' AND lo.estado = 1
    LIMIT 1;

    SELECT lo.id INTO v_id_tipo_salida
    FROM gen_lista_opciones lo
    INNER JOIN gen_lista l ON lo.id_lista = l.id
    WHERE l.nombre = 'TipoMovBalon' AND lo.nombre = 'SALIDA_PLANTA_EXTERNA' AND lo.estado = 1
    LIMIT 1;

    SELECT lo.id INTO v_id_tipo_entrada
    FROM gen_lista_opciones lo
    INNER JOIN gen_lista l ON lo.id_lista = l.id
    WHERE l.nombre = 'TipoMovBalon' AND lo.nombre = 'ENTRADA_PLANTA_EXTERNA' AND lo.estado = 1
    LIMIT 1;

    IF v_id_estado_recarga_externa IS NULL THEN
        RETURN json_build_object(
            'error',
            'No se encontró el estado EN_RECARGA_EXTERNA del cilindro. Revise el catálogo EstadoBalon.',
            'registro',
            NULL
        );
    END IF;

    IF v_id_estado_en_almacen IS NULL THEN
        RETURN json_build_object(
            'error',
            'No se encontró el estado EN_ALMACEN del cilindro. Revise el catálogo EstadoBalon.',
            'registro',
            NULL
        );
    END IF;

    IF v_id_tipo_salida IS NULL OR v_id_tipo_entrada IS NULL THEN
        RETURN json_build_object(
            'error',
            'No se encontraron los tipos SALIDA_PLANTA_EXTERNA / ENTRADA_PLANTA_EXTERNA. Revise el catálogo TipoMovBalon.',
            'registro',
            NULL
        );
    END IF;

    INSERT INTO bal_movimiento_recarga (
        fecha_salida_almacen, id_balon, id_tipo_recarga, id_producto, capacidad, id_unidad_medida,
        serie_guia_salida, numero_guia_salida, serie_guia_ingreso, numero_guia_ingreso,
        serie_factura, numero_factura, id_comprobante, id_comprobante_compra, fecha_llegada_almacen,
        lote, fecha_vencimiento_lote, fecha_prueba_hidrostatica, id_proveedor,
        observacion, id_almacen,
        id_usuario_creacion, id_usuario_modificacion
    )
    VALUES (
        p_fecha_salida_almacen, p_id_balon, v_id_tipo_recarga, p_id_producto, p_capacidad, p_id_unidad_medida,
        p_serie_guia_salida, p_numero_guia_salida, p_serie_guia_ingreso, p_numero_guia_ingreso,
        p_serie_factura, p_numero_factura, p_id_comprobante, p_id_comprobante_compra, p_fecha_llegada_almacen,
        p_lote, p_fecha_vencimiento_lote, p_fecha_prueba_hidrostatica, p_id_proveedor,
        p_observacion, p_id_almacen,
        p_id_usuario_auditoria, p_id_usuario_auditoria
    )
    RETURNING id INTO v_id;

    v_obs := COALESCE(NULLIF(TRIM(p_observacion), ''), 'Recarga planta externa');

    -- Libro de movimientos: salida a planta.
    v_mov := inv_registrar_movimiento(
        p_naturaleza                => 'BALON',
        p_codigo_tipo_movimiento    => 'SALIDA_PLANTA_EXTERNA',
        p_fecha                     => p_fecha_salida_almacen::TIMESTAMP,
        p_id_producto               => NULL,
        p_id_balon                  => p_id_balon,
        p_cantidad                  => 1,
        p_id_almacen_origen         => p_id_almacen,
        p_id_almacen_destino        => NULL,
        p_id_cliente                => p_id_proveedor,
        p_codigo_tipo_documento_origen => 'RECARGA',
        p_id_documento_origen       => v_id,
        p_glosa                     => v_obs,
        p_id_usuario_auditoria      => p_id_usuario_auditoria
    );
    IF v_mov->>'error' IS NOT NULL THEN
        RETURN json_build_object('error', v_mov->>'error', 'registro', NULL);
    END IF;

    IF p_fecha_llegada_almacen IS NOT NULL THEN
        -- inv_registrar_movimiento ya actualizó id_estado_balon a EN_ALMACEN.
        -- Solo fijamos id_producto_gas.
        UPDATE bal_balon
        SET
            id_producto_gas = COALESCE(p_id_producto, id_producto_gas),
            id_usuario_modificacion = p_id_usuario_auditoria,
            fecha_modificacion = NOW()
        WHERE id = p_id_balon AND estado = 1
        RETURNING id_producto_gas INTO v_id_producto_gas_balon;

        v_mov := inv_registrar_movimiento(
            p_naturaleza                => 'BALON',
            p_codigo_tipo_movimiento    => 'ENTRADA_PLANTA_EXTERNA',
            p_fecha                     => p_fecha_llegada_almacen::TIMESTAMP,
            p_id_producto               => v_id_producto_gas_balon,
            p_id_balon                  => p_id_balon,
            p_cantidad                  => COALESCE(p_capacidad, NULLIF(v_capacidad_tipo, 0), 1),
            p_id_almacen_origen         => NULL,
            p_id_almacen_destino        => p_id_almacen,
            p_id_cliente                => p_id_proveedor,
            p_codigo_tipo_documento_origen => 'RECARGA',
            p_id_documento_origen       => v_id,
            p_glosa                     => v_obs,
            p_id_usuario_auditoria      => p_id_usuario_auditoria
        );
        IF v_mov->>'error' IS NOT NULL THEN
            RETURN json_build_object('error', v_mov->>'error', 'registro', NULL);
        END IF;
    ELSE
        -- inv_registrar_movimiento (SALIDA_PLANTA_EXTERNA) ya puso EN_RECARGA_EXTERNA + limpió almacén.
        NULL;
    END IF;

    RETURN bal_obtener_movimiento_recarga(v_id);
END;
$$;


--
-- Name: bal_crear_prestamo(integer, character varying, integer, integer, integer, date, date, date, character varying, character varying, integer, integer, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bal_crear_prestamo(p_id_tipo_prestamo integer, p_numero_prestamo character varying DEFAULT NULL::character varying, p_id_cliente integer DEFAULT NULL::integer, p_id_proveedor integer DEFAULT NULL::integer, p_id_almacen integer DEFAULT NULL::integer, p_fecha_salida date DEFAULT NULL::date, p_fecha_retorno_pactada date DEFAULT NULL::date, p_fecha_retorno_real date DEFAULT NULL::date, p_titulo character varying DEFAULT NULL::character varying, p_observacion character varying DEFAULT NULL::character varying, p_id_estado integer DEFAULT NULL::integer, p_id_comprobante_venta integer DEFAULT NULL::integer, p_id_comprobante_compra integer DEFAULT NULL::integer, p_id_usuario_auditoria integer DEFAULT NULL::integer) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_id INTEGER;
    v_id_estado INTEGER;
    v_nombre_tipo VARCHAR;
BEGIN
    SET TIME ZONE 'America/Lima';

    IF p_id_tipo_prestamo IS NULL THEN
        RETURN json_build_object('error', 'El tipo de préstamo es obligatorio', 'registro', NULL);
    END IF;

    SELECT lo.nombre
    INTO v_nombre_tipo
    FROM gen_lista_opciones lo
    WHERE lo.id = p_id_tipo_prestamo AND lo.estado = 1;

    IF v_nombre_tipo IS NULL THEN
        RETURN json_build_object('error', 'El tipo de préstamo indicado no existe o está inactivo', 'registro', NULL);
    END IF;

    -- Contraparte cliente: el código del tipo en TipoPrestamo incluye CLIENTE
    IF v_nombre_tipo ILIKE '%CLIENTE%' THEN
        IF p_id_cliente IS NULL THEN
            RETURN json_build_object('error', 'El cliente es obligatorio para este tipo de préstamo', 'registro', NULL);
        END IF;
        IF NOT EXISTS (
            SELECT 1 FROM cli_clientes WHERE id = p_id_cliente AND estado = 1
        ) THEN
            RETURN json_build_object('error', 'El cliente indicado no existe o está inactivo', 'registro', NULL);
        END IF;
    ELSIF p_id_cliente IS NOT NULL AND NOT EXISTS (
        SELECT 1 FROM cli_clientes WHERE id = p_id_cliente AND estado = 1
    ) THEN
        RETURN json_build_object('error', 'El cliente indicado no existe o está inactivo', 'registro', NULL);
    END IF;

    -- Los préstamos a cliente deben nacer de una venta (punto de venta).
    -- De esta forma el cilindro queda reservado y vinculado al comprobante.
    IF v_nombre_tipo ILIKE '%CLIENTE%' AND p_id_comprobante_venta IS NULL THEN
        RETURN json_build_object(
            'error',
            'Los préstamos a cliente deben estar vinculados a un comprobante de venta. Regístralos desde la venta en punto de venta.',
            'registro',
            NULL
        );
    END IF;

    IF p_numero_prestamo IS NOT NULL AND EXISTS (
        SELECT 1 FROM bal_prestamo WHERE numero_prestamo = TRIM(p_numero_prestamo)
    ) THEN
        RETURN json_build_object('error', 'Ya existe un préstamo con el número ' || TRIM(p_numero_prestamo), 'registro', NULL);
    END IF;

    v_id_estado := p_id_estado;
    IF v_id_estado IS NULL THEN
        SELECT lo.id INTO v_id_estado
        FROM gen_lista_opciones lo
        INNER JOIN gen_lista l ON l.id = lo.id_lista
        WHERE l.nombre = 'EstadoPrestamo' AND lo.nombre = 'ACTIVO' AND lo.estado = 1
        LIMIT 1;

        IF v_id_estado IS NULL THEN
            RETURN json_build_object(
                'error',
                'No se encontró el estado ACTIVO del préstamo. Revise el catálogo EstadoPrestamo.',
                'registro',
                NULL
            );
        END IF;
    END IF;

    INSERT INTO bal_prestamo (
        numero_prestamo, id_tipo_prestamo, id_cliente, id_proveedor, id_almacen,
        fecha_salida, fecha_retorno_pactada, fecha_retorno_real,
        titulo, observacion, id_estado,
        id_comprobante_venta, id_comprobante_compra,
        id_usuario_creacion, id_usuario_modificacion
    )
    VALUES (
        NULLIF(TRIM(p_numero_prestamo), ''), p_id_tipo_prestamo, p_id_cliente, p_id_proveedor, p_id_almacen,
        p_fecha_salida, p_fecha_retorno_pactada, p_fecha_retorno_real,
        p_titulo, p_observacion, v_id_estado,
        p_id_comprobante_venta, p_id_comprobante_compra,
        p_id_usuario_auditoria, p_id_usuario_auditoria
    )
    RETURNING id INTO v_id;

    RETURN bal_obtener_prestamo(v_id);
END;
$$;


--
-- Name: bal_crear_prestamo_detalle(integer, integer, integer, character varying, date, date, integer, date, date, character varying, character varying, character varying, character varying, integer, character varying, integer, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bal_crear_prestamo_detalle(p_id_prestamo integer, p_id_balon integer DEFAULT NULL::integer, p_id_producto integer DEFAULT NULL::integer, p_motivo_especifico character varying DEFAULT NULL::character varying, p_fecha_entregado date DEFAULT NULL::date, p_fecha_prestamo date DEFAULT NULL::date, p_dias_prestamo integer DEFAULT 30, p_fecha_vencimiento date DEFAULT NULL::date, p_fecha_devolucion date DEFAULT NULL::date, p_serie_guia_entrega character varying DEFAULT NULL::character varying, p_numero_guia_entrega character varying DEFAULT NULL::character varying, p_serie_guia_devolucion character varying DEFAULT NULL::character varying, p_numero_guia_devolucion character varying DEFAULT NULL::character varying, p_id_estado integer DEFAULT NULL::integer, p_observacion character varying DEFAULT NULL::character varying, p_id_usuario_auditoria integer DEFAULT NULL::integer, p_id_guia_entrega integer DEFAULT NULL::integer, p_id_guia_devolucion integer DEFAULT NULL::integer) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_id INTEGER;
    v_id_producto INTEGER;
    v_id_estado_detalle INTEGER;
    v_salida JSON;
    v_serie_entrega VARCHAR;
    v_numero_entrega VARCHAR;
    v_serie_devolucion VARCHAR;
    v_numero_devolucion VARCHAR;
BEGIN
    SET TIME ZONE 'America/Lima';

    IF NOT EXISTS (
        SELECT 1 FROM bal_prestamo WHERE id = p_id_prestamo AND estado = 1
    ) THEN
        RETURN json_build_object('error', 'El préstamo indicado no existe o está inactivo', 'registro', NULL);
    END IF;

    v_id_producto := p_id_producto;
    v_id_estado_detalle := p_id_estado;
    v_serie_entrega := p_serie_guia_entrega;
    v_numero_entrega := p_numero_guia_entrega;
    v_serie_devolucion := p_serie_guia_devolucion;
    v_numero_devolucion := p_numero_guia_devolucion;

    -- Serie/número quedan como snapshot de la GRE vinculada (compatibilidad UI).
    IF p_id_guia_entrega IS NOT NULL THEN
        SELECT g.serie, g.numero INTO v_serie_entrega, v_numero_entrega
        FROM gre_guia_remision g
        WHERE g.id = p_id_guia_entrega AND g.estado = 1;

        IF NOT FOUND THEN
            RETURN json_build_object('error', 'La guía de remisión de entrega indicada no existe o está inactiva', 'registro', NULL);
        END IF;
    END IF;

    IF p_id_guia_devolucion IS NOT NULL THEN
        SELECT g.serie, g.numero INTO v_serie_devolucion, v_numero_devolucion
        FROM gre_guia_remision g
        WHERE g.id = p_id_guia_devolucion AND g.estado = 1;

        IF NOT FOUND THEN
            RETURN json_build_object('error', 'La guía de remisión de devolución indicada no existe o está inactiva', 'registro', NULL);
        END IF;
    END IF;

    IF v_id_estado_detalle IS NULL AND p_fecha_devolucion IS NULL THEN
        SELECT lo.id INTO v_id_estado_detalle
        FROM gen_lista_opciones lo
        INNER JOIN gen_lista l ON lo.id_lista = l.id
        WHERE l.nombre = 'EstadoPrestamoDetalle' AND lo.nombre = 'ACTIVO' AND lo.estado = 1
        LIMIT 1;
    END IF;

    IF p_id_balon IS NOT NULL THEN
        IF NOT EXISTS (
            SELECT 1 FROM bal_balon WHERE id = p_id_balon AND estado = 1
        ) THEN
            RETURN json_build_object('error', 'El cilindro indicado no existe o está inactivo', 'registro', NULL);
        END IF;

        SELECT COALESCE(b.id_producto_gas, v_id_producto) INTO v_id_producto
        FROM bal_balon b
        WHERE b.id = p_id_balon AND b.estado = 1;

        IF EXISTS (
            SELECT 1
            FROM bal_alquiler_detalle ad
            INNER JOIN bal_alquiler al ON al.id = ad.id_alquiler AND al.estado = 1
            WHERE ad.id_balon = p_id_balon
              AND ad.estado = 1
              AND ad.fecha_devolucion IS NULL
        ) THEN
            RETURN json_build_object(
                'error', 'El cilindro está alquilado actualmente; no se puede prestar',
                'registro', NULL
            );
        END IF;

        IF EXISTS (
            SELECT 1
            FROM bal_prestamo_detalle pd
            INNER JOIN bal_prestamo p2 ON p2.id = pd.id_prestamo AND p2.estado = 1
            WHERE pd.id_balon = p_id_balon
              AND pd.estado = 1
              AND pd.fecha_devolucion IS NULL
        ) THEN
            RETURN json_build_object(
                'error', 'El cilindro ya tiene un préstamo activo sin devolver',
                'registro', NULL
            );
        END IF;
    END IF;

    INSERT INTO bal_prestamo_detalle (
        id_prestamo, id_balon, id_producto, motivo_especifico,
        fecha_entregado, fecha_prestamo, dias_prestamo, fecha_vencimiento, fecha_devolucion,
        id_guia_entrega, id_guia_devolucion,
        serie_guia_entrega, numero_guia_entrega, serie_guia_devolucion, numero_guia_devolucion,
        id_estado, observacion,
        id_usuario_creacion, id_usuario_modificacion
    )
    VALUES (
        p_id_prestamo, p_id_balon, v_id_producto, p_motivo_especifico,
        p_fecha_entregado, p_fecha_prestamo, COALESCE(p_dias_prestamo, 30), p_fecha_vencimiento, p_fecha_devolucion,
        p_id_guia_entrega, p_id_guia_devolucion,
        v_serie_entrega, v_numero_entrega, v_serie_devolucion, v_numero_devolucion,
        v_id_estado_detalle, p_observacion,
        p_id_usuario_auditoria, p_id_usuario_auditoria
    )
    RETURNING id INTO v_id;

    -- Histórico ya devuelto: no mueve custodia. Activo: sale del almacén.
    IF p_id_balon IS NOT NULL AND p_fecha_devolucion IS NULL THEN
        v_salida := bal_prestamo_aplicar_salida_cilindro(
            p_id_prestamo,
            p_id_balon,
            p_observacion,
            p_id_usuario_auditoria
        );

        IF v_salida->>'error' IS NOT NULL THEN
            RAISE EXCEPTION '%', v_salida->>'error';
        END IF;
    END IF;

    RETURN bal_obtener_prestamo_detalle(v_id);
END;
$$;


--
-- Name: bal_crear_recarga_cliente(integer, integer, integer, numeric, numeric, integer, character varying, numeric, integer, integer, character varying, integer, integer, integer, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bal_crear_recarga_cliente(p_id_cliente integer, p_id_balon integer, p_id_producto integer, p_precio_unitario numeric, p_cantidad numeric DEFAULT 1, p_id_tipo_comprobante integer DEFAULT NULL::integer, p_serie character varying DEFAULT 'B001'::character varying, p_capacidad numeric DEFAULT NULL::numeric, p_id_medio_pago integer DEFAULT NULL::integer, p_id_almacen integer DEFAULT NULL::integer, p_observacion character varying DEFAULT NULL::character varying, p_id_balon_origen integer DEFAULT NULL::integer, p_id_usuario_auditoria integer DEFAULT NULL::integer, p_id_condicion_pago integer DEFAULT NULL::integer, p_fecha_vencimiento date DEFAULT NULL::date) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_fecha DATE;
    v_id_tipo_recarga INTEGER;
    v_id_tipo_comprobante INTEGER;
    v_id_tipo_venta INTEGER;
    v_id_afectacion_igv INTEGER;
    v_id_tipo_movimiento INTEGER;
    v_id_tipo_documento_ref INTEGER;
    v_id_moneda INTEGER;
    v_id_tipo_operacion_sunat INTEGER;
    v_detalles JSON;
    v_comprobante_result JSON;
    v_id_comprobante INTEGER;
    v_serie_comprobante VARCHAR;
    v_numero_comprobante VARCHAR;
    v_id_recarga INTEGER;
    v_recarga JSON;
    v_comprobante JSON;
    v_capacidad NUMERIC;
    v_capacidad_destino NUMERIC;
    v_mov JSON;
    v_producto_nombre VARCHAR;
    v_asignacion JSON;
    v_origenes JSON;
    v_id_balon_origen_principal INTEGER;
BEGIN
    SET TIME ZONE 'America/Lima';
    v_fecha := CURRENT_DATE;

    IF p_id_cliente IS NULL THEN
        RETURN json_build_object('error', 'El cliente es obligatorio', 'registro', NULL);
    END IF;

    IF p_id_balon IS NULL THEN
        RETURN json_build_object('error', 'El balón es obligatorio', 'registro', NULL);
    END IF;

    IF p_id_balon_origen IS NOT NULL AND p_id_balon_origen = p_id_balon THEN
        RETURN json_build_object(
            'error',
            'El balón origen no puede ser el mismo que el destino',
            'registro',
            NULL
        );
    END IF;

    IF p_id_producto IS NULL THEN
        RETURN json_build_object('error', 'El producto (gas) es obligatorio', 'registro', NULL);
    END IF;

    IF p_precio_unitario IS NULL OR p_precio_unitario < 0 THEN
        RETURN json_build_object('error', 'El precio unitario es obligatorio', 'registro', NULL);
    END IF;

    IF COALESCE(p_cantidad, 0) <= 0 THEN
        RETURN json_build_object('error', 'La cantidad debe ser mayor a cero', 'registro', NULL);
    END IF;

    IF NOT EXISTS (
        SELECT 1 FROM cli_clientes WHERE id = p_id_cliente AND estado = 1
    ) THEN
        RETURN json_build_object('error', 'El cliente indicado no existe o está inactivo', 'registro', NULL);
    END IF;

    IF NOT EXISTS (
        SELECT 1 FROM bal_balon WHERE id = p_id_balon AND estado = 1
    ) THEN
        RETURN json_build_object('error', 'El balón indicado no existe o está inactivo', 'registro', NULL);
    END IF;

    IF NOT EXISTS (
        SELECT 1 FROM pro_producto WHERE id = p_id_producto AND estado = 1
    ) THEN
        RETURN json_build_object('error', 'El producto indicado no existe o está inactivo', 'registro', NULL);
    END IF;

    SELECT lo.id INTO v_id_tipo_recarga
    FROM gen_lista_opciones lo
    INNER JOIN gen_lista l ON lo.id_lista = l.id
    WHERE l.nombre = 'TipoRecarga' AND lo.nombre = 'CLIENTE' AND lo.estado = 1
    LIMIT 1;

    IF p_id_tipo_comprobante IS NOT NULL THEN
        v_id_tipo_comprobante := p_id_tipo_comprobante;
    ELSE
        SELECT lo.id INTO v_id_tipo_comprobante
        FROM gen_lista_opciones lo
        INNER JOIN gen_lista l ON lo.id_lista = l.id
        WHERE l.nombre = 'TipoComprobante' AND lo.nombre = 'BOLETA' AND lo.estado = 1
        LIMIT 1;
    END IF;

    IF v_id_tipo_comprobante IS NULL THEN
        RETURN json_build_object('error', 'No se encontró el tipo de comprobante BOLETA en catálogos', 'registro', NULL);
    END IF;

    SELECT lo.id INTO v_id_tipo_venta
    FROM gen_lista_opciones lo
    INNER JOIN gen_lista l ON lo.id_lista = l.id
    WHERE l.nombre = 'TipoVenta' AND lo.nombre = 'VENTA_GAS' AND lo.estado = 1
    LIMIT 1;

    SELECT lo.id INTO v_id_afectacion_igv
    FROM gen_lista_opciones lo
    INNER JOIN gen_lista l ON lo.id_lista = l.id
    WHERE l.nombre = 'AfectacionIgv' AND lo.descripcion = '10' AND lo.estado = 1
    LIMIT 1;

    SELECT lo.id INTO v_id_tipo_movimiento
    FROM gen_lista_opciones lo
    INNER JOIN gen_lista l ON lo.id_lista = l.id
    WHERE l.nombre = 'TipoMovBalon' AND lo.nombre = 'RECARGA_CLIENTE' AND lo.estado = 1
    LIMIT 1;

    IF v_id_tipo_movimiento IS NULL THEN
        SELECT lo.id INTO v_id_tipo_movimiento
        FROM gen_lista_opciones lo
        INNER JOIN gen_lista l ON lo.id_lista = l.id
        WHERE l.nombre = 'TipoMovBalon' AND lo.nombre = 'ENTRADA_LLENADO' AND lo.estado = 1
        LIMIT 1;
    END IF;

    SELECT lo.id INTO v_id_tipo_documento_ref
    FROM gen_lista_opciones lo
    INNER JOIN gen_lista l ON lo.id_lista = l.id
    WHERE l.nombre = 'TipoDocumentoRef' AND lo.nombre = 'RECARGA' AND lo.estado = 1
    LIMIT 1;

    SELECT lo.id INTO v_id_moneda
    FROM gen_lista_opciones lo
    INNER JOIN gen_lista l ON lo.id_lista = l.id
    WHERE l.nombre = 'Moneda' AND lo.nombre = 'PEN' AND lo.estado = 1
    LIMIT 1;

    SELECT lo.id INTO v_id_tipo_operacion_sunat
    FROM gen_lista_opciones lo
    INNER JOIN gen_lista l ON lo.id_lista = l.id
    WHERE l.nombre = 'TipoOperacionSunat' AND lo.descripcion = '0101' AND lo.estado = 1
    LIMIT 1;

    SELECT nombre INTO v_producto_nombre
    FROM pro_producto
    WHERE id = p_id_producto;

    SELECT COALESCE(tb.capacidad, p_capacidad, p_cantidad, 0)
    INTO v_capacidad_destino
    FROM bal_balon b
    LEFT JOIN bal_tipo_balon tb ON tb.id = b.id_tipo_balon
    WHERE b.id = p_id_balon;

    v_capacidad := COALESCE(NULLIF(p_capacidad, 0), v_capacidad_destino, p_cantidad);

    IF v_capacidad <= 0 THEN
        RETURN json_build_object(
            'error',
            'No se pudo determinar la capacidad a recargar',
            'registro',
            NULL
        );
    END IF;

    v_asignacion := bal_asignar_origenes_recarga(
        p_id_producto,
        v_capacidad,
        p_id_almacen,
        p_id_balon_origen
    );

    IF v_asignacion->>'error' IS NOT NULL THEN
        RETURN json_build_object('error', v_asignacion->>'error', 'registro', NULL);
    END IF;

    v_origenes := v_asignacion->'origenes';
    v_id_balon_origen_principal := (v_asignacion->>'id_balon_origen_principal')::INTEGER;

    v_detalles := json_build_array(
        json_build_object(
            'id_producto', p_id_producto,
            'cantidad', p_cantidad,
            'precio_unitario', p_precio_unitario,
            'descuento', 0,
            'porcentaje_igv', 18,
            'id_afectacion_igv', v_id_afectacion_igv,
            'descripcion', 'Recarga ' || COALESCE(v_producto_nombre, 'gas'),
            'id_balon', p_id_balon,
            'capacidad_cilindro', v_capacidad
        )
    );

    v_comprobante_result := ven_crear_comprobante(
        v_id_tipo_comprobante,
        COALESCE(NULLIF(TRIM(p_serie), ''), 'B001'),
        NULL,
        v_fecha,
        p_id_cliente,
        v_detalles,
        v_id_tipo_operacion_sunat,
        NULL,
        NULL,
        NULL,
        v_id_tipo_venta,
        p_fecha_vencimiento,
        3.5,
        NULL,
        p_id_almacen,
        p_id_condicion_pago,
        v_id_moneda,
        p_id_medio_pago,
        'Recarga de balón',
        p_observacion,
        NULL,
        NULL,
        NULL,
        NULL,
        p_id_usuario_auditoria,
        'recarga'
    );

    IF v_comprobante_result->>'error' IS NOT NULL THEN
        RETURN json_build_object(
            'error', v_comprobante_result->>'error',
            'registro', NULL
        );
    END IF;

    v_comprobante := v_comprobante_result->'registro';
    v_id_comprobante := (v_comprobante->>'id')::INTEGER;
    v_serie_comprobante := v_comprobante->>'serie';
    v_numero_comprobante := v_comprobante->>'numero';

    -- El stock de gas ya se validó en bal_asignar_origenes_recarga (pro_stock) y se
    -- descuenta más abajo vía inv_registrar_movimiento; ya no hay capacidad por
    -- cilindro que "consumir" aparte.

    INSERT INTO bal_movimiento_recarga (
        fecha_salida_almacen,
        id_balon,
        id_balon_origen,
        id_cliente,
        id_tipo_recarga,
        id_producto,
        capacidad,
        serie_factura,
        numero_factura,
        id_comprobante,
        fecha_llegada_almacen,
        observacion,
        id_almacen,
        id_usuario_creacion,
        id_usuario_modificacion
    )
    VALUES (
        v_fecha,
        p_id_balon,
        v_id_balon_origen_principal,
        p_id_cliente,
        v_id_tipo_recarga,
        p_id_producto,
        v_capacidad,
        v_serie_comprobante,
        v_numero_comprobante,
        v_id_comprobante,
        v_fecha,
        CASE
            WHEN COALESCE(v_asignacion->>'etiqueta', '') <> '' THEN
                TRIM(BOTH ' ' FROM CONCAT_WS(
                    ' | ',
                    NULLIF(TRIM(COALESCE(p_observacion, '')), ''),
                    'Orígenes: ' || (v_asignacion->>'etiqueta')
                ))
            ELSE p_observacion
        END,
        p_id_almacen,
        p_id_usuario_auditoria,
        p_id_usuario_auditoria
    )
    RETURNING id INTO v_id_recarga;

    INSERT INTO bal_movimiento_recarga_origen (
        id_movimiento_recarga,
        id_balon,
        cantidad,
        orden,
        id_usuario_creacion
    )
    SELECT
        v_id_recarga,
        (o->>'id_balon')::INTEGER,
        (o->>'cantidad')::NUMERIC,
        COALESCE((o->>'orden')::INTEGER, 1),
        p_id_usuario_auditoria
    FROM json_array_elements(v_origenes) o;

    IF v_id_tipo_movimiento IS NOT NULL THEN
        v_mov := inv_registrar_movimiento(
            p_naturaleza                => 'BALON',
            p_codigo_tipo_movimiento    => 'RECARGA_CLIENTE',
            p_fecha                     => NOW(),
            p_id_producto               => p_id_producto,
            p_id_balon                  => p_id_balon,
            p_cantidad                  => v_capacidad,
            p_id_almacen_origen         => p_id_almacen,
            p_id_almacen_destino        => NULL,
            p_id_cliente                => p_id_cliente,
            p_codigo_tipo_documento_origen => 'RECARGA',
            p_id_documento_origen       => v_id_recarga,
            p_glosa                     => COALESCE(p_observacion, 'Recarga cliente'),
            p_id_usuario_auditoria      => p_id_usuario_auditoria
        );
        IF v_mov->>'error' IS NOT NULL THEN
            RAISE EXCEPTION '%', v_mov->>'error';
        END IF;
    END IF;

    -- inv_registrar_movimiento ya actualizó id_estado_balon, id_cliente_ubicacion, id_almacen.
    -- Solo fijamos id_producto_gas y limpiamos presion/contenido.
    UPDATE bal_balon
    SET
        id_producto_gas = p_id_producto,
        presion_actual = NULL,
        id_usuario_modificacion = p_id_usuario_auditoria,
        fecha_modificacion = NOW()
    WHERE id = p_id_balon AND estado = 1;

    v_recarga := bal_obtener_movimiento_recarga(v_id_recarga);

    RETURN json_build_object(
        'registro', json_build_object(
            'recarga', v_recarga->'registro',
            'comprobante', v_comprobante
        )
    );
END;
$$;


--
-- Name: bal_crear_recarga_planta(date, integer, integer, integer, character varying, character varying, character varying, boolean, json, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bal_crear_recarga_planta(p_fecha_salida date, p_id_proveedor integer DEFAULT NULL::integer, p_id_almacen integer DEFAULT NULL::integer, p_id_guia_salida integer DEFAULT NULL::integer, p_serie_guia_salida character varying DEFAULT NULL::character varying, p_numero_guia_salida character varying DEFAULT NULL::character varying, p_observacion character varying DEFAULT NULL::character varying, p_confirmar_salida boolean DEFAULT true, p_detalles json DEFAULT '[]'::json, p_id_usuario_auditoria integer DEFAULT NULL::integer) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_id INTEGER;
    v_numero VARCHAR(30);
    v_id_estado INTEGER;
    v_estado_nombre VARCHAR := CASE WHEN COALESCE(p_confirmar_salida, TRUE) THEN 'ENVIADO' ELSE 'BORRADOR' END;
    v_serie VARCHAR(10);
    v_numero_guia VARCHAR(15);
    v_proveedor INTEGER;
    v_almacen INTEGER;
    v_item JSON;
    v_id_balon INTEGER;
    v_id_producto INTEGER;
    v_capacidad NUMERIC;
    v_id_um INTEGER;
    v_id_det INTEGER;
    v_mov JSON;
    v_id_mov INTEGER;
    v_es_empresa BOOLEAN;
BEGIN
    SET TIME ZONE 'America/Lima';

    IF p_fecha_salida IS NULL THEN
        RETURN json_build_object('error', 'La fecha de salida es obligatoria', 'registro', NULL);
    END IF;

    IF p_detalles IS NULL OR jsonb_array_length(COALESCE(p_detalles::JSONB, '[]'::JSONB)) = 0 THEN
        RETURN json_build_object('error', 'Debe indicar al menos un cilindro en el detalle', 'registro', NULL);
    END IF;

    v_serie := NULLIF(TRIM(p_serie_guia_salida), '');
    v_numero_guia := NULLIF(TRIM(p_numero_guia_salida), '');
    v_proveedor := p_id_proveedor;
    v_almacen := p_id_almacen;

    IF p_id_guia_salida IS NOT NULL THEN
        IF NOT EXISTS (SELECT 1 FROM gre_guia_remision WHERE id = p_id_guia_salida AND estado = 1) THEN
            RETURN json_build_object('error', 'La guía de remisión de salida no existe', 'registro', NULL);
        END IF;

        IF EXISTS (
            SELECT 1
            FROM bal_recarga_planta rp
            LEFT JOIN gen_lista_opciones est ON est.id = rp.id_estado
            WHERE rp.id_guia_salida = p_id_guia_salida
              AND rp.estado = 1
              AND COALESCE(est.nombre, '') NOT IN ('ANULADO')
        ) THEN
            RETURN json_build_object(
                'error',
                'Ya existe una orden de recarga activa vinculada a esa guía de remisión',
                'registro',
                NULL
            );
        END IF;

        -- Con FK a la GRE la guía es la única fuente: no se copian serie/número
        -- (las lecturas los resuelven por JOIN). El texto libre queda reservado
        -- para órdenes cuya guía no existe como documento en el sistema.
        v_serie := NULL;
        v_numero_guia := NULL;

        SELECT
            COALESCE(v_proveedor, g.id_destinatario, g.id_cliente),
            COALESCE(v_almacen, g.id_almacen)
        INTO v_proveedor, v_almacen
        FROM gre_guia_remision g
        WHERE g.id = p_id_guia_salida;
    END IF;

    SELECT lo.id INTO v_id_estado
    FROM gen_lista_opciones lo
    INNER JOIN gen_lista l ON l.id = lo.id_lista
    WHERE l.nombre = 'EstadoRecargaPlanta' AND lo.nombre = v_estado_nombre AND lo.estado = 1
    LIMIT 1;

    INSERT INTO bal_recarga_planta (
        numero, fecha_salida, id_proveedor, id_almacen,
        id_guia_salida, serie_guia_salida, numero_guia_salida,
        id_estado, observacion,
        id_usuario_creacion, id_usuario_modificacion
    )
    VALUES (
        NULL, p_fecha_salida, v_proveedor, v_almacen,
        p_id_guia_salida, v_serie, v_numero_guia,
        v_id_estado, NULLIF(TRIM(p_observacion), ''),
        p_id_usuario_auditoria, p_id_usuario_auditoria
    )
    RETURNING id INTO v_id;

    v_numero := 'RP-' || TO_CHAR(p_fecha_salida, 'YYYYMMDD') || '-' || LPAD(v_id::TEXT, 4, '0');
    UPDATE bal_recarga_planta SET numero = v_numero WHERE id = v_id;

    FOR v_item IN SELECT * FROM jsonb_array_elements(p_detalles::JSONB)
    LOOP
        v_id_balon := NULLIF(v_item->>'idBalon', '')::INTEGER;
        IF v_id_balon IS NULL THEN
            v_id_balon := NULLIF(v_item->>'id_balon', '')::INTEGER;
        END IF;

        IF v_id_balon IS NULL THEN
            RETURN json_build_object('error', 'Detalle sin cilindro', 'registro', NULL);
        END IF;

        SELECT COALESCE(prop.nombre, '') = 'EMPRESA'
        INTO v_es_empresa
        FROM bal_balon b
        LEFT JOIN gen_lista_opciones prop ON prop.id = b.id_propietario
        WHERE b.id = v_id_balon AND b.estado = 1;

        IF NOT COALESCE(v_es_empresa, FALSE) THEN
            RETURN json_build_object(
                'error',
                'Solo cilindros de propiedad EMPRESA pueden ir a planta externa',
                'registro',
                NULL
            );
        END IF;

        v_id_producto := COALESCE(
            NULLIF(v_item->>'idProducto', '')::INTEGER,
            NULLIF(v_item->>'id_producto', '')::INTEGER
        );
        v_capacidad := COALESCE(
            NULLIF(v_item->>'capacidad', '')::NUMERIC,
            NULLIF(v_item->>'capacidad', '')::NUMERIC
        );
        v_id_um := COALESCE(
            NULLIF(v_item->>'idUnidadMedida', '')::INTEGER,
            NULLIF(v_item->>'id_unidad_medida', '')::INTEGER
        );

        IF v_id_producto IS NULL OR v_capacidad IS NULL OR v_id_um IS NULL THEN
            SELECT
                COALESCE(v_id_producto, b.id_producto_gas),
                COALESCE(v_capacidad, tb.capacidad),
                COALESCE(v_id_um, tb.id_unidad_medida)
            INTO v_id_producto, v_capacidad, v_id_um
            FROM bal_balon b
            LEFT JOIN bal_tipo_balon tb ON tb.id = b.id_tipo_balon
            WHERE b.id = v_id_balon;
        END IF;

        INSERT INTO bal_recarga_planta_detalle (
            id_recarga_planta, id_balon, id_producto, capacidad, id_unidad_medida,
            observacion, id_usuario_creacion, id_usuario_modificacion
        )
        VALUES (
            v_id, v_id_balon, v_id_producto, v_capacidad, v_id_um,
            NULLIF(TRIM(v_item->>'observacion'), ''),
            p_id_usuario_auditoria, p_id_usuario_auditoria
        )
        RETURNING id INTO v_id_det;

        IF COALESCE(p_confirmar_salida, TRUE) THEN
            v_mov := bal_crear_movimiento_recarga(
                p_fecha_salida,
                v_id_balon,
                v_id_producto,
                v_capacidad,
                v_id_um,
                v_serie,
                v_numero_guia,
                NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL,
                v_proveedor,
                NULLIF(TRIM(p_observacion), ''),
                v_almacen,
                NULL,
                p_id_usuario_auditoria
            );

            IF v_mov->>'error' IS NOT NULL THEN
                RETURN json_build_object('error', v_mov->>'error', 'registro', NULL);
            END IF;

            v_id_mov := (v_mov->'registro'->>'id')::INTEGER;

            UPDATE bal_recarga_planta_detalle
            SET id_movimiento_recarga = v_id_mov
            WHERE id = v_id_det;

            UPDATE bal_movimiento_recarga
            SET id_recarga_planta = v_id
            WHERE id = v_id_mov;
        END IF;
    END LOOP;

    RETURN bal_obtener_recarga_planta(v_id);
END;
$$;


--
-- Name: bal_crear_recojo(integer, integer, integer, integer, date, time without time zone, integer, character varying, json, integer, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bal_crear_recojo(p_id_cliente integer, p_id_prestamo integer DEFAULT NULL::integer, p_id_alquiler integer DEFAULT NULL::integer, p_id_recarga_planta integer DEFAULT NULL::integer, p_fecha_programada date DEFAULT NULL::date, p_hora_estimada time without time zone DEFAULT NULL::time without time zone, p_id_usuario_responsable integer DEFAULT NULL::integer, p_observacion character varying DEFAULT NULL::character varying, p_detalles json DEFAULT '[]'::json, p_id_usuario_auditoria integer DEFAULT NULL::integer, p_marcar_balon_por_recoger boolean DEFAULT true) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_id INTEGER;
    v_estado INTEGER;
    v_por_recoger INTEGER;
    x JSONB;
    v_pd INTEGER;
    v_ad INTEGER;
    v_b INTEGER;
    v_balon INTEGER;
    v_cliente INTEGER;
    v_dev DATE;
    v_len INTEGER;
    v_producto INTEGER;
    v_id_recarga_planta INTEGER;
    v_proveedor INTEGER;
    v_rp_estado VARCHAR;
    v_id_estado_balon_local INTEGER;
BEGIN
    SET TIME ZONE 'America/Lima';

    v_len := jsonb_array_length(COALESCE(p_detalles::JSONB, '[]'::JSONB));

    IF p_id_cliente IS NULL OR p_fecha_programada IS NULL THEN
        RETURN json_build_object(
            'error', 'Cliente y fecha son obligatorios',
            'registro', NULL
        );
    END IF;

    IF NOT EXISTS (SELECT 1 FROM cli_clientes WHERE id = p_id_cliente AND estado = 1) THEN
        RETURN json_build_object('error', 'Cliente inválido', 'registro', NULL);
    END IF;

    IF p_id_prestamo IS NOT NULL AND NOT EXISTS (
        SELECT 1
        FROM bal_prestamo p
        JOIN gen_lista_opciones e ON e.id = p.id_estado AND e.nombre = 'ACTIVO'
        WHERE p.id = p_id_prestamo
          AND p.id_cliente = p_id_cliente
          AND p.estado = 1
    ) THEN
        RETURN json_build_object(
            'error', 'Préstamo activo inválido para el cliente',
            'registro', NULL
        );
    END IF;

    IF p_id_alquiler IS NOT NULL AND NOT EXISTS (
        SELECT 1
        FROM bal_alquiler a
        JOIN gen_lista_opciones e ON e.id = a.id_estado AND e.nombre = 'ACTIVO'
        WHERE a.id = p_id_alquiler
          AND a.id_cliente = p_id_cliente
          AND a.estado = 1
    ) THEN
        RETURN json_build_object(
            'error', 'Alquiler activo inválido para el cliente',
            'registro', NULL
        );
    END IF;

    -- Validación de origen recarga en planta: el "cliente" del recojo es el proveedor
    IF p_id_recarga_planta IS NOT NULL THEN
        SELECT rp.id_proveedor, est.nombre
        INTO v_proveedor, v_rp_estado
        FROM bal_recarga_planta rp
        LEFT JOIN gen_lista_opciones est ON est.id = rp.id_estado
        WHERE rp.id = p_id_recarga_planta AND rp.estado = 1;

        IF v_proveedor IS NULL THEN
            RETURN json_build_object(
                'error', 'Orden de recarga en planta no encontrada',
                'registro', NULL
            );
        END IF;

        IF v_rp_estado NOT IN ('ENVIADO', 'CERRADO') THEN
            RETURN json_build_object(
                'error', 'La orden de recarga en planta aún no ha sido enviada',
                'registro', NULL
            );
        END IF;

        IF v_proveedor <> p_id_cliente THEN
            RETURN json_build_object(
                'error', 'El cliente del recojo debe coincidir con el proveedor de la recarga',
                'registro', NULL
            );
        END IF;

        IF v_len = 0 THEN
            RETURN json_build_object(
                'error', 'El recojo de recarga en planta requiere al menos un cilindro',
                'registro', NULL
            );
        END IF;
    END IF;

    -- Recojo sin cilindros: solo alquiler de regulador/accesorio
    IF v_len = 0 THEN
        IF p_id_alquiler IS NULL OR p_id_prestamo IS NOT NULL OR p_id_recarga_planta IS NOT NULL THEN
            RETURN json_build_object(
                'error', 'Cliente, fecha y detalles son obligatorios',
                'registro', NULL
            );
        END IF;

        SELECT COALESCE(a.id_producto_regulador, a.id_producto_stock)
        INTO v_producto
        FROM bal_alquiler a
        WHERE a.id = p_id_alquiler AND a.estado = 1;

        IF v_producto IS NULL THEN
            RETURN json_build_object(
                'error', 'El alquiler no tiene regulador/accesorio para recojo',
                'registro', NULL
            );
        END IF;

        -- Permitido con o sin cilindros pendientes: visita solo de regulador/accesorio

        IF EXISTS (
            SELECT 1
            FROM bal_recojo r
            JOIN gen_lista_opciones e ON e.id = r.id_estado
            WHERE r.id_alquiler = p_id_alquiler
              AND r.estado = 1
              AND e.nombre IN ('PROGRAMADO', 'EN_RUTA')
        ) THEN
            RETURN json_build_object(
                'error', 'El alquiler ya tiene un recojo programado o en ruta',
                'registro', NULL
            );
        END IF;
    END IF;

    SELECT lo.id INTO v_estado
    FROM gen_lista_opciones lo
    JOIN gen_lista l ON l.id = lo.id_lista
    WHERE l.nombre = 'EstadoRecojo' AND lo.nombre = 'PROGRAMADO' AND lo.estado = 1;

    SELECT lo.id INTO v_por_recoger
    FROM gen_lista_opciones lo
    JOIN gen_lista l ON l.id = lo.id_lista
    WHERE l.nombre = 'EstadoBalon' AND lo.nombre = 'POR_RECOGER' AND lo.estado = 1;

    INSERT INTO bal_recojo (
        id_cliente,
        id_prestamo,
        id_alquiler,
        id_recarga_planta,
        fecha_programada,
        hora_estimada,
        id_usuario_responsable,
        id_estado,
        observacion,
        id_usuario_creacion,
        id_usuario_modificacion
    )
    VALUES (
        p_id_cliente,
        p_id_prestamo,
        p_id_alquiler,
        p_id_recarga_planta,
        p_fecha_programada,
        p_hora_estimada,
        p_id_usuario_responsable,
        v_estado,
        NULLIF(TRIM(p_observacion), ''),
        p_id_usuario_auditoria,
        p_id_usuario_auditoria
    )
    RETURNING id INTO v_id;

    FOR x IN SELECT * FROM jsonb_array_elements(COALESCE(p_detalles::JSONB, '[]'::JSONB))
    LOOP
        v_pd := COALESCE(
            NULLIF(x->>'idPrestamoDetalle', '')::INTEGER,
            NULLIF(x->>'id_prestamo_detalle', '')::INTEGER
        );
        v_ad := COALESCE(
            NULLIF(x->>'idAlquilerDetalle', '')::INTEGER,
            NULLIF(x->>'id_alquiler_detalle', '')::INTEGER
        );
        v_b := COALESCE(
            NULLIF(x->>'idBalon', '')::INTEGER,
            NULLIF(x->>'id_balon', '')::INTEGER
        );

        IF (v_pd IS NOT NULL)::INTEGER + (v_ad IS NOT NULL)::INTEGER + (v_b IS NOT NULL)::INTEGER <> 1 THEN
            RAISE EXCEPTION 'Cada detalle debe tener exactamente un origen (préstamo, alquiler o balón)';
        END IF;

        IF v_pd IS NOT NULL THEN
            SELECT pd.id_balon, p.id_cliente, pd.fecha_devolucion
            INTO v_balon, v_cliente, v_dev
            FROM bal_prestamo_detalle pd
            JOIN bal_prestamo p ON p.id = pd.id_prestamo
            JOIN gen_lista_opciones e ON e.id = p.id_estado AND e.nombre = 'ACTIVO'
            WHERE pd.id = v_pd AND pd.estado = 1;

            IF v_cliente IS NULL
               OR v_cliente <> p_id_cliente
               OR v_dev IS NOT NULL
               OR (
                   p_id_prestamo IS NOT NULL
                   AND NOT EXISTS (
                       SELECT 1 FROM bal_prestamo_detalle
                       WHERE id = v_pd AND id_prestamo = p_id_prestamo
                   )
               )
            THEN
                RAISE EXCEPTION 'Detalle de préstamo inválido';
            END IF;

            IF EXISTS (
                SELECT 1
                FROM bal_recojo_detalle rd
                JOIN bal_recojo r ON r.id = rd.id_recojo AND r.estado = 1
                JOIN gen_lista_opciones e ON e.id = r.id_estado
                WHERE rd.id_prestamo_detalle = v_pd
                  AND rd.estado = 1
                  AND e.nombre IN ('PROGRAMADO', 'EN_RUTA')
            ) THEN
                RAISE EXCEPTION 'El detalle de préstamo ya tiene recojo';
            END IF;

            INSERT INTO bal_recojo_detalle (
                id_recojo,
                id_prestamo_detalle,
                observacion,
                id_usuario_creacion,
                id_usuario_modificacion
            )
            VALUES (
                v_id,
                v_pd,
                NULLIF(TRIM(x->>'observacion'), ''),
                p_id_usuario_auditoria,
                p_id_usuario_auditoria
            );

            IF v_balon IS NOT NULL AND v_por_recoger IS NOT NULL AND p_marcar_balon_por_recoger THEN
                UPDATE bal_balon
                SET
                    id_estado_balon = v_por_recoger,
                    id_usuario_modificacion = p_id_usuario_auditoria,
                    fecha_modificacion = NOW()
                WHERE id = v_balon AND estado = 1;
            END IF;
        ELSIF v_ad IS NOT NULL THEN
            SELECT ad.id_balon, a.id_cliente, ad.fecha_devolucion
            INTO v_balon, v_cliente, v_dev
            FROM bal_alquiler_detalle ad
            JOIN bal_alquiler a ON a.id = ad.id_alquiler
            JOIN gen_lista_opciones e ON e.id = a.id_estado AND e.nombre = 'ACTIVO'
            WHERE ad.id = v_ad AND ad.estado = 1;

            IF v_cliente IS NULL
               OR v_cliente <> p_id_cliente
               OR v_dev IS NOT NULL
               OR (
                   p_id_alquiler IS NOT NULL
                   AND NOT EXISTS (
                       SELECT 1 FROM bal_alquiler_detalle
                       WHERE id = v_ad AND id_alquiler = p_id_alquiler
                   )
               )
            THEN
                RAISE EXCEPTION 'Detalle de alquiler inválido';
            END IF;

            IF EXISTS (
                SELECT 1
                FROM bal_recojo_detalle rd
                JOIN bal_recojo r ON r.id = rd.id_recojo AND r.estado = 1
                JOIN gen_lista_opciones e ON e.id = r.id_estado
                WHERE rd.id_alquiler_detalle = v_ad
                  AND rd.estado = 1
                  AND e.nombre IN ('PROGRAMADO', 'EN_RUTA')
            ) THEN
                RAISE EXCEPTION 'El detalle de alquiler ya tiene recojo';
            END IF;

            INSERT INTO bal_recojo_detalle (
                id_recojo,
                id_alquiler_detalle,
                observacion,
                id_usuario_creacion,
                id_usuario_modificacion
            )
            VALUES (
                v_id,
                v_ad,
                NULLIF(TRIM(x->>'observacion'), ''),
                p_id_usuario_auditoria,
                p_id_usuario_auditoria
            );

            IF v_balon IS NOT NULL AND v_por_recoger IS NOT NULL AND p_marcar_balon_por_recoger THEN
                UPDATE bal_balon
                SET
                    id_estado_balon = v_por_recoger,
                    id_usuario_modificacion = p_id_usuario_auditoria,
                    fecha_modificacion = NOW()
                WHERE id = v_balon AND estado = 1;
            END IF;
        ELSE
            -- Origen recarga en planta externa: el balón permanece EN_RECARGA_EXTERNA
            -- hasta que se cierra el recojo (distribución manual de gas).
            IF p_id_recarga_planta IS NULL THEN
                RAISE EXCEPTION 'El detalle por balón requiere id_recarga_planta';
            END IF;

            SELECT b.id, b.id_estado_balon
            INTO v_balon, v_id_estado_balon_local
            FROM bal_balon b
            WHERE b.id = v_b AND b.estado = 1;

            IF v_balon IS NULL THEN
                RAISE EXCEPTION 'Balón % no encontrado', v_b;
            END IF;

            IF NOT EXISTS (
                SELECT 1
                FROM bal_recarga_planta_detalle d
                WHERE d.id_recarga_planta = p_id_recarga_planta
                  AND d.id_balon = v_b
                  AND d.estado = 1
            ) THEN
                RAISE EXCEPTION 'El balón % no pertenece a la orden de recarga en planta', v_b;
            END IF;

            IF NOT EXISTS (
                SELECT 1
                FROM bal_balon b
                JOIN gen_lista_opciones e ON e.id = b.id_estado_balon
                WHERE b.id = v_b AND b.estado = 1 AND e.nombre = 'EN_RECARGA_EXTERNA'
            ) THEN
                RAISE EXCEPTION 'El balón % no está en estado EN_RECARGA_EXTERNA', v_b;
            END IF;

            IF EXISTS (
                SELECT 1
                FROM bal_recojo_detalle rd
                JOIN bal_recojo r ON r.id = rd.id_recojo AND r.estado = 1
                JOIN gen_lista_opciones e ON e.id = r.id_estado
                WHERE rd.id_balon = v_b
                  AND rd.estado = 1
                  AND e.nombre IN ('PROGRAMADO', 'EN_RUTA')
            ) THEN
                RAISE EXCEPTION 'El balón % ya tiene un recojo programado', v_b;
            END IF;

            INSERT INTO bal_recojo_detalle (
                id_recojo,
                id_balon,
                observacion,
                id_usuario_creacion,
                id_usuario_modificacion
            )
            VALUES (
                v_id,
                v_b,
                NULLIF(TRIM(x->>'observacion'), ''),
                p_id_usuario_auditoria,
                p_id_usuario_auditoria
            );
        END IF;
    END LOOP;

    RETURN bal_obtener_recojo(v_id);
EXCEPTION
    WHEN OTHERS THEN
        IF v_id IS NOT NULL THEN
            DELETE FROM bal_recojo WHERE id = v_id;
        END IF;
        RETURN json_build_object('error', SQLERRM, 'registro', NULL);
END;
$$;


--
-- Name: bal_crear_ruta_pueblo(date, integer, integer, integer, numeric, numeric, character varying, json, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bal_crear_ruta_pueblo(p_fecha date DEFAULT NULL::date, p_id_almacen integer DEFAULT NULL::integer, p_id_usuario_responsable integer DEFAULT NULL::integer, p_id_chofer integer DEFAULT NULL::integer, p_factor_lb_m3 numeric DEFAULT NULL::numeric, p_tolerancia_m3 numeric DEFAULT NULL::numeric, p_observacion character varying DEFAULT NULL::character varying, p_detalles json DEFAULT '[]'::json, p_id_usuario_auditoria integer DEFAULT NULL::integer) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_id INTEGER;
    v_id_estado INTEGER;
    v_detalle JSON;
    v_id_balon INTEGER;
    v_lb_salida NUMERIC;
    v_sellado BOOLEAN;
    v_item INTEGER := 0;
    v_balones INTEGER[] := ARRAY[]::INTEGER[];
    v_estado_balon VARCHAR;
    v_id_almacen_balon INTEGER;
    v_factor NUMERIC;
    v_tolerancia NUMERIC;
    v_cap_m3 NUMERIC;
    v_cap_lb NUMERIC;
    v_factor_tipo NUMERIC;
    v_factores NUMERIC[] := ARRAY[]::NUMERIC[];
    v_nombre_tipo VARCHAR;
BEGIN
    SET TIME ZONE 'America/Lima';

    IF p_id_almacen IS NULL THEN
        RETURN json_build_object('error', 'El almacén es obligatorio', 'registro', NULL);
    END IF;

    IF NOT EXISTS (SELECT 1 FROM gen_almacen WHERE id = p_id_almacen AND estado = 1) THEN
        RETURN json_build_object('error', 'Almacén inválido', 'registro', NULL);
    END IF;

    IF p_detalles IS NULL OR json_typeof(p_detalles) <> 'array' OR json_array_length(p_detalles) = 0 THEN
        RETURN json_build_object('error', 'Debe registrar al menos un cilindro con libras de salida', 'registro', NULL);
    END IF;

    SELECT lo.id INTO v_id_estado
    FROM gen_lista_opciones lo
    INNER JOIN gen_lista l ON l.id = lo.id_lista
    WHERE l.nombre = 'EstadoRutaPueblo' AND lo.nombre = 'ABIERTA' AND lo.estado = 1
    LIMIT 1;

    IF v_id_estado IS NULL THEN
        RETURN json_build_object('error', 'Estado ABIERTA no configurado', 'registro', NULL);
    END IF;

    -- Tolerancia: parámetro opcional o default de empresa
    SELECT COALESCE(
        NULLIF(p_tolerancia_m3, 0),
        e.tolerancia_m3_ruta_pueblo,
        0.5000
    )
    INTO v_tolerancia
    FROM gen_empresa e
    WHERE e.estado = 1
    ORDER BY e.id
    LIMIT 1;

    IF v_tolerancia IS NULL THEN
        v_tolerancia := COALESCE(NULLIF(p_tolerancia_m3, 0), 0.5000);
    END IF;

    -- Validar cilindros y derivar factor por tipo (capacidad m³ / capacidad lb)
    FOR v_detalle IN SELECT value FROM json_array_elements(p_detalles)
    LOOP
        v_item := v_item + 1;
        v_id_balon := COALESCE(
            (v_detalle->>'idBalon')::INTEGER,
            (v_detalle->>'id_balon')::INTEGER
        );
        v_lb_salida := COALESCE(
            (v_detalle->>'lbSalida')::NUMERIC,
            (v_detalle->>'lb_salida')::NUMERIC
        );

        IF v_id_balon IS NULL THEN
            RAISE EXCEPTION 'Ítem %: cilindro obligatorio', v_item;
        END IF;

        IF v_lb_salida IS NULL OR v_lb_salida < 0 THEN
            RAISE EXCEPTION 'Ítem %: libras de salida inválidas', v_item;
        END IF;

        IF v_id_balon = ANY (v_balones) THEN
            RAISE EXCEPTION 'El cilindro % está duplicado en la ruta', v_id_balon;
        END IF;
        v_balones := array_append(v_balones, v_id_balon);

        SELECT eb.nombre, b.id_almacen, tb.capacidad, tb.capacidad_lb, tb.nombre
        INTO v_estado_balon, v_id_almacen_balon, v_cap_m3, v_cap_lb, v_nombre_tipo
        FROM bal_balon b
        LEFT JOIN gen_lista_opciones eb ON eb.id = b.id_estado_balon
        LEFT JOIN bal_tipo_balon tb ON tb.id = b.id_tipo_balon AND tb.estado = 1
        WHERE b.id = v_id_balon AND b.estado = 1;

        IF v_estado_balon IS NULL THEN
            RAISE EXCEPTION 'Cilindro % no existe o está inactivo', v_id_balon;
        END IF;

        IF v_estado_balon NOT IN ('EN_ALMACEN') THEN
            RAISE EXCEPTION 'Cilindro % debe estar en almacén (estado actual: %)', v_id_balon, v_estado_balon;
        END IF;

        IF v_id_almacen_balon IS DISTINCT FROM p_id_almacen THEN
            RAISE EXCEPTION 'Cilindro % no está en el almacén de la ruta', v_id_balon;
        END IF;

        IF v_cap_m3 IS NULL OR v_cap_m3 <= 0 OR v_cap_lb IS NULL OR v_cap_lb <= 0 THEN
            RAISE EXCEPTION
                'El tipo "%" del cilindro % no tiene capacidad m³ y lb configuradas. Edítalo en Tipos de balón.',
                COALESCE(v_nombre_tipo, '(sin tipo)'),
                v_id_balon;
        END IF;

        IF v_lb_salida > v_cap_lb THEN
            RAISE EXCEPTION
                'Cilindro %: libras de salida (%.4f) no pueden superar la capacidad lb del tipo "%" (%.4f)',
                v_id_balon,
                v_lb_salida,
                COALESCE(v_nombre_tipo, '(sin tipo)'),
                v_cap_lb;
        END IF;

        v_factor_tipo := ROUND(v_cap_m3 / v_cap_lb, 6);
        v_factores := array_append(v_factores, v_factor_tipo);

        IF EXISTS (
            SELECT 1
            FROM bal_ruta_pueblo_detalle d
            INNER JOIN bal_ruta_pueblo r ON r.id = d.id_ruta_pueblo AND r.estado = 1
            INNER JOIN gen_lista_opciones er ON er.id = r.id_estado
            WHERE d.id_balon = v_id_balon
              AND d.estado = 1
              AND er.nombre IN ('ABIERTA', 'EN_RUTA')
        ) THEN
            RAISE EXCEPTION 'Cilindro % ya está en otra ruta abierta/en tránsito', v_id_balon;
        END IF;
    END LOOP;

    -- Snapshot del factor: parámetro explícito o promedio de tipos de la ruta
    IF NULLIF(p_factor_lb_m3, 0) IS NOT NULL THEN
        v_factor := p_factor_lb_m3;
    ELSE
        SELECT ROUND(AVG(f), 6) INTO v_factor
        FROM unnest(v_factores) AS f;
    END IF;

    INSERT INTO bal_ruta_pueblo (
        fecha, id_almacen, id_usuario_responsable, id_chofer,
        factor_lb_m3, tolerancia_m3, id_estado, observacion,
        id_usuario_creacion, id_usuario_modificacion
    ) VALUES (
        COALESCE(p_fecha, CURRENT_DATE),
        p_id_almacen,
        p_id_usuario_responsable,
        p_id_chofer,
        v_factor,
        v_tolerancia,
        v_id_estado,
        NULLIF(TRIM(COALESCE(p_observacion, '')), ''),
        p_id_usuario_auditoria,
        p_id_usuario_auditoria
    )
    RETURNING id INTO v_id;

    FOR v_detalle IN SELECT value FROM json_array_elements(p_detalles)
    LOOP
        v_id_balon := COALESCE(
            (v_detalle->>'idBalon')::INTEGER,
            (v_detalle->>'id_balon')::INTEGER
        );
        v_lb_salida := COALESCE(
            (v_detalle->>'lbSalida')::NUMERIC,
            (v_detalle->>'lb_salida')::NUMERIC
        );
        v_sellado := COALESCE(
            (v_detalle->>'sellado')::BOOLEAN,
            FALSE
        );

        INSERT INTO bal_ruta_pueblo_detalle (
            id_ruta_pueblo, id_balon, sellado, lb_salida, observacion,
            id_usuario_creacion, id_usuario_modificacion
        ) VALUES (
            v_id,
            v_id_balon,
            v_sellado,
            v_lb_salida,
            NULLIF(TRIM(COALESCE(v_detalle->>'observacion', '')), ''),
            p_id_usuario_auditoria,
            p_id_usuario_auditoria
        );
    END LOOP;

    RETURN bal_obtener_ruta_pueblo(v_id);
END;
$$;


--
-- Name: bal_crear_tipo_balon(character varying, integer, numeric, numeric, integer, numeric, integer, numeric, numeric, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bal_crear_tipo_balon(p_nombre character varying, p_id_gas integer DEFAULT NULL::integer, p_capacidad numeric DEFAULT NULL::numeric, p_capacidad_lb numeric DEFAULT NULL::numeric, p_id_unidad_medida integer DEFAULT NULL::integer, p_peso numeric DEFAULT NULL::numeric, p_vigencia_ph_anios integer DEFAULT 5, p_presion_llenado_psi numeric DEFAULT NULL::numeric, p_peso_tara_lb numeric DEFAULT NULL::numeric, p_id_usuario_auditoria integer DEFAULT NULL::integer) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_id INTEGER;
    v_tara_lb NUMERIC;
BEGIN
    SET TIME ZONE 'America/Lima';

    IF p_nombre IS NULL OR TRIM(p_nombre) = '' THEN
        RETURN json_build_object('error', 'El nombre del tipo de balón es obligatorio', 'registro', NULL);
    END IF;

    IF EXISTS (
        SELECT 1 FROM bal_tipo_balon
        WHERE estado = 1 AND LOWER(TRIM(nombre)) = LOWER(TRIM(p_nombre))
    ) THEN
        RETURN json_build_object('error', 'Ya existe un tipo de balón activo con el nombre ' || TRIM(p_nombre), 'registro', NULL);
    END IF;

    IF p_id_gas IS NOT NULL AND NOT EXISTS (
        SELECT 1 FROM pro_producto WHERE id = p_id_gas AND estado = 1
    ) THEN
        RETURN json_build_object('error', 'El gas indicado no existe o está inactivo', 'registro', NULL);
    END IF;

    IF p_id_unidad_medida IS NOT NULL AND NOT EXISTS (
        SELECT 1 FROM gen_lista_opciones WHERE id = p_id_unidad_medida AND estado = 1
    ) THEN
        RETURN json_build_object('error', 'La unidad de medida indicada no existe o está inactiva', 'registro', NULL);
    END IF;

    IF p_capacidad_lb IS NOT NULL AND p_capacidad_lb <= 0 THEN
        RETURN json_build_object('error', 'La capacidad en lb debe ser mayor a 0', 'registro', NULL);
    END IF;

    IF p_presion_llenado_psi IS NOT NULL AND p_presion_llenado_psi <= 0 THEN
        RETURN json_build_object('error', 'La presión de llenado (PSI) debe ser mayor a 0', 'registro', NULL);
    END IF;

    v_tara_lb := COALESCE(
        NULLIF(p_peso_tara_lb, 0),
        CASE WHEN p_peso IS NOT NULL AND p_peso > 0 THEN ROUND(p_peso * 2.20462, 4) ELSE NULL END
    );

    INSERT INTO bal_tipo_balon (
        nombre, id_gas, capacidad, capacidad_lb, id_unidad_medida, peso, vigencia_ph_anios,
        presion_llenado_psi, peso_tara_lb,
        id_usuario_creacion, id_usuario_modificacion
    )
    VALUES (
        TRIM(p_nombre), p_id_gas, p_capacidad, p_capacidad_lb, p_id_unidad_medida, p_peso,
        COALESCE(p_vigencia_ph_anios, 5),
        p_presion_llenado_psi, v_tara_lb,
        p_id_usuario_auditoria, p_id_usuario_auditoria
    )
    RETURNING id INTO v_id;

    RETURN bal_obtener_tipo_balon(v_id);
END;
$$;


--
-- Name: bal_dar_baja_balon(integer, integer, integer, integer, character varying, integer, integer, character varying, character varying, numeric, character varying, date, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bal_dar_baja_balon(p_id_balon integer, p_id_motivo_baja integer, p_id_usuario_solicita integer, p_id_usuario_autoriza integer DEFAULT NULL::integer, p_motivo_detalle character varying DEFAULT NULL::character varying, p_id_cliente_comprador integer DEFAULT NULL::integer, p_id_comprobante_venta integer DEFAULT NULL::integer, p_serie_comprobante character varying DEFAULT NULL::character varying, p_numero_comprobante character varying DEFAULT NULL::character varying, p_monto_venta numeric DEFAULT NULL::numeric, p_observacion character varying DEFAULT NULL::character varying, p_fecha_baja date DEFAULT NULL::date, p_id_usuario_auditoria integer DEFAULT NULL::integer) RETURNS json
    LANGUAGE plpgsql
    AS $$
BEGIN
    RETURN bal_solicitar_baja_balon(
        p_id_balon,
        p_id_motivo_baja,
        p_id_usuario_solicita,
        p_motivo_detalle,
        p_id_cliente_comprador,
        p_id_comprobante_venta,
        p_serie_comprobante,
        p_numero_comprobante,
        p_monto_venta,
        p_observacion,
        p_fecha_baja,
        p_id_usuario_auditoria
    );
END;
$$;


--
-- Name: bal_devolver_alquiler_detalle(integer, date, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bal_devolver_alquiler_detalle(p_id integer, p_fecha_devolucion date DEFAULT CURRENT_DATE, p_id_almacen_destino integer DEFAULT NULL::integer, p_id_usuario_auditoria integer DEFAULT NULL::integer) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_id_alquiler INTEGER;
    v_id_balon INTEGER;
    v_id_cliente INTEGER;
    v_id_almacen INTEGER;
    v_fecha_devolucion DATE;
    v_id_almacen_destino INTEGER;
    v_id_estado_en_almacen INTEGER;
    v_id_estado_finalizado INTEGER;
    v_mov_result JSON;
    v_pendientes INTEGER;
BEGIN
    SET TIME ZONE 'America/Lima';

    SELECT
        ad.id_alquiler,
        ad.id_balon,
        ad.fecha_devolucion,
        al.id_cliente,
        al.id_almacen
    INTO
        v_id_alquiler,
        v_id_balon,
        v_fecha_devolucion,
        v_id_cliente,
        v_id_almacen
    FROM bal_alquiler_detalle ad
    INNER JOIN bal_alquiler al ON al.id = ad.id_alquiler AND al.estado = 1
    WHERE ad.id = p_id
      AND ad.estado = 1;

    IF v_id_alquiler IS NULL THEN
        RETURN json_build_object(
            'error', 'El detalle de alquiler no existe o está inactivo',
            'registro', NULL
        );
    END IF;

    IF v_fecha_devolucion IS NOT NULL THEN
        RETURN json_build_object(
            'error', 'El cilindro ya fue registrado como devuelto',
            'registro', NULL
        );
    END IF;

    v_id_almacen_destino := COALESCE(p_id_almacen_destino, v_id_almacen);

    IF v_id_almacen_destino IS NULL THEN
        RETURN json_build_object(
            'error', 'Debe indicar el almacén de destino de la devolución',
            'registro', NULL
        );
    END IF;

    IF NOT EXISTS (
        SELECT 1 FROM gen_almacen WHERE id = v_id_almacen_destino AND estado = 1
    ) THEN
        RETURN json_build_object(
            'error', 'El almacén de destino no existe o está inactivo',
            'registro', NULL
        );
    END IF;

    SELECT lo.id INTO v_id_estado_en_almacen
    FROM gen_lista_opciones lo
    INNER JOIN gen_lista l ON lo.id_lista = l.id
    WHERE l.nombre = 'EstadoBalon' AND lo.nombre = 'EN_ALMACEN' AND lo.estado = 1
    LIMIT 1;

    IF v_id_estado_en_almacen IS NULL THEN
        RETURN json_build_object(
            'error', 'No se encontró el estado EN_ALMACEN del cilindro. Revise el catálogo EstadoBalon.',
            'registro', NULL
        );
    END IF;

    SELECT lo.id INTO v_id_estado_finalizado
    FROM gen_lista_opciones lo
    INNER JOIN gen_lista l ON lo.id_lista = l.id
    WHERE l.nombre = 'EstadoAlquiler' AND lo.nombre = 'FINALIZADO' AND lo.estado = 1
    LIMIT 1;

    UPDATE bal_alquiler_detalle
    SET
        fecha_devolucion = COALESCE(p_fecha_devolucion, CURRENT_DATE),
        id_usuario_modificacion = p_id_usuario_auditoria,
        fecha_modificacion = NOW()
    WHERE id = p_id
      AND estado = 1;

    v_mov_result := inv_registrar_movimiento(
        p_naturaleza                => 'BALON',
        p_codigo_tipo_movimiento    => 'ENTRADA_DEVOLUCION',
        p_fecha                     => NOW(),
        p_id_balon                  => v_id_balon,
        p_cantidad                  => 1,
        p_id_almacen_destino        => v_id_almacen_destino,
        p_id_cliente                => v_id_cliente,
        p_codigo_tipo_documento_origen => 'ALQUILER',
        p_id_documento_origen       => v_id_alquiler,
        p_glosa                     => 'Entrada por devolución de alquiler',
        p_id_usuario_auditoria      => p_id_usuario_auditoria
    );

    IF v_mov_result->>'error' IS NOT NULL THEN
        RAISE EXCEPTION '%', v_mov_result->>'error';
    END IF;

    -- Custodia: vuelve a almacén. Contenido: se asume vacío (envase usado que regresa).
    UPDATE bal_balon
    SET
        id_cliente_ubicacion = NULL,
        id_almacen = v_id_almacen_destino,
        id_estado_balon = v_id_estado_en_almacen,
        id_usuario_modificacion = p_id_usuario_auditoria,
        fecha_modificacion = NOW()
    WHERE id = v_id_balon
      AND estado = 1;

    SELECT COUNT(*) INTO v_pendientes
    FROM bal_alquiler_detalle
    WHERE id_alquiler = v_id_alquiler
      AND estado = 1
      AND fecha_devolucion IS NULL;

    -- No cerrar si aún falta devolver el regulador/accesorio
    IF v_pendientes = 0
       AND NOT EXISTS (
           SELECT 1
           FROM bal_alquiler a
           WHERE a.id = v_id_alquiler
             AND a.estado = 1
             AND COALESCE(a.id_producto_regulador, a.id_producto_stock) IS NOT NULL
             AND a.fecha_devolucion_regulador IS NULL
       )
    THEN
        UPDATE bal_alquiler
        SET
            fecha_fin_real = COALESCE(fecha_fin_real, COALESCE(p_fecha_devolucion, CURRENT_DATE)),
            id_estado = COALESCE(v_id_estado_finalizado, id_estado),
            id_usuario_modificacion = p_id_usuario_auditoria,
            fecha_modificacion = NOW()
        WHERE id = v_id_alquiler
          AND estado = 1;
    END IF;

    RETURN bal_obtener_alquiler_detalle(p_id);
END;
$$;


--
-- Name: bal_devolver_prestamo_detalle(integer, date, integer, integer, character varying, character varying); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bal_devolver_prestamo_detalle(p_id integer, p_fecha_devolucion date DEFAULT CURRENT_DATE, p_id_almacen_destino integer DEFAULT NULL::integer, p_id_usuario_auditoria integer DEFAULT NULL::integer, p_nombre_estado_contenido character varying DEFAULT 'VACIO'::character varying, p_observacion character varying DEFAULT NULL::character varying) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_id_prestamo INTEGER;
    v_id_balon INTEGER;
    v_id_cliente INTEGER;
    v_id_almacen INTEGER;
    v_fecha_devolucion DATE;
    v_id_almacen_destino INTEGER;
    v_id_estado_detalle_devuelto INTEGER;
    v_obs_actual VARCHAR(500);
    v_obs_nueva VARCHAR(500);
    v_retorno JSON;
    v_id_producto_gas INTEGER;
BEGIN
    SET TIME ZONE 'America/Lima';

    SELECT
        pd.id_prestamo,
        pd.id_balon,
        pd.fecha_devolucion,
        pd.observacion,
        p.id_cliente,
        p.id_almacen
    INTO
        v_id_prestamo,
        v_id_balon,
        v_fecha_devolucion,
        v_obs_actual,
        v_id_cliente,
        v_id_almacen
    FROM bal_prestamo_detalle pd
    INNER JOIN bal_prestamo p ON p.id = pd.id_prestamo AND p.estado = 1
    WHERE pd.id = p_id
      AND pd.estado = 1;

    IF v_id_prestamo IS NULL THEN
        RETURN json_build_object(
            'error', 'El detalle de préstamo no existe o está inactivo',
            'registro', NULL
        );
    END IF;

    IF v_fecha_devolucion IS NOT NULL THEN
        RETURN json_build_object(
            'error', 'El cilindro ya fue registrado como devuelto',
            'registro', NULL
        );
    END IF;

    v_id_almacen_destino := COALESCE(p_id_almacen_destino, v_id_almacen);

    SELECT lo.id INTO v_id_estado_detalle_devuelto
    FROM gen_lista_opciones lo
    INNER JOIN gen_lista l ON lo.id_lista = l.id
    WHERE l.nombre = 'EstadoPrestamoDetalle' AND lo.nombre = 'DEVUELTO' AND lo.estado = 1
    LIMIT 1;

    v_obs_nueva := NULLIF(TRIM(p_observacion), '');
    IF v_obs_nueva IS NOT NULL THEN
        IF NULLIF(TRIM(v_obs_actual), '') IS NULL THEN
            v_obs_actual := LEFT(v_obs_nueva, 500);
        ELSE
            v_obs_actual := LEFT(TRIM(v_obs_actual) || ' | ' || v_obs_nueva, 500);
        END IF;
    END IF;

    IF v_id_balon IS NOT NULL THEN
        SELECT b.id_producto_gas INTO v_id_producto_gas
        FROM bal_balon b
        WHERE b.id = v_id_balon AND b.estado = 1;

        v_retorno := bal_prestamo_aplicar_retorno_cilindro(
            v_id_balon,
            v_id_prestamo,
            v_id_cliente,
            v_id_almacen_destino,
            COALESCE(NULLIF(TRIM(p_nombre_estado_contenido), ''), 'VACIO'),
            COALESCE(v_obs_nueva, 'Entrada por devolución de préstamo'),
            p_id_usuario_auditoria,
            TRUE
        );

        IF v_retorno->>'error' IS NOT NULL THEN
            RETURN json_build_object('error', v_retorno->>'error', 'registro', NULL);
        END IF;
    END IF;

    UPDATE bal_prestamo_detalle
    SET
        fecha_devolucion = COALESCE(p_fecha_devolucion, CURRENT_DATE),
        id_estado = COALESCE(v_id_estado_detalle_devuelto, id_estado),
        id_producto = COALESCE(v_id_producto_gas, id_producto),
        observacion = COALESCE(v_obs_actual, observacion),
        id_usuario_modificacion = p_id_usuario_auditoria,
        fecha_modificacion = NOW()
    WHERE id = p_id
      AND estado = 1;

    PERFORM bal_prestamo_cerrar_si_completo(
        v_id_prestamo,
        COALESCE(p_fecha_devolucion, CURRENT_DATE),
        p_id_usuario_auditoria
    );

    RETURN bal_obtener_prestamo_detalle(p_id);
END;
$$;


--
-- Name: bal_devolver_regulador_alquiler(integer, date, character varying, character varying, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bal_devolver_regulador_alquiler(p_id_alquiler integer, p_fecha date DEFAULT CURRENT_DATE, p_condicion character varying DEFAULT 'BUENO'::character varying, p_observacion character varying DEFAULT NULL::character varying, p_id_recojo integer DEFAULT NULL::integer, p_id_usuario_auditoria integer DEFAULT NULL::integer) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_producto INTEGER;
    v_almacen INTEGER;
    v_numero VARCHAR;
    v_condicion VARCHAR := UPPER(TRIM(COALESCE(p_condicion, '')));
    v_id_condicion INTEGER;
    v_id_tipo_rep INTEGER;
    v_id_estado_pend INTEGER;
    v_id_mant INTEGER;
    v_mov JSON;
    v_obs VARCHAR(500);
    v_ya_devuelto DATE;
    v_stock_ok BOOLEAN;
BEGIN
    SET TIME ZONE 'America/Lima';

    IF p_id_alquiler IS NULL THEN
        RETURN json_build_object('error', 'El alquiler es obligatorio', 'registro', NULL);
    END IF;

    IF v_condicion NOT IN ('BUENO', 'PARA_REPARAR') THEN
        RETURN json_build_object(
            'error', 'La condición del regulador debe ser BUENO o PARA_REPARAR',
            'registro', NULL
        );
    END IF;

    SELECT
        COALESCE(a.id_producto_stock, a.id_producto_regulador),
        a.id_almacen,
        a.numero_alquiler,
        a.fecha_devolucion_regulador,
        COALESCE(a.stock_regulador_reingresado, FALSE)
    INTO v_producto, v_almacen, v_numero, v_ya_devuelto, v_stock_ok
    FROM bal_alquiler a
    WHERE a.id = p_id_alquiler AND a.estado = 1;

    IF v_producto IS NULL THEN
        RETURN json_build_object(
            'error', 'El alquiler no tiene regulador/accesorio asociado',
            'registro', NULL
        );
    END IF;

    IF v_ya_devuelto IS NOT NULL THEN
        RETURN json_build_object(
            'error', NULL,
            'registro', json_build_object(
                'id_alquiler', p_id_alquiler,
                'ya_devuelto', TRUE,
                'fecha_devolucion_regulador', v_ya_devuelto
            )
        );
    END IF;

    SELECT lo.id INTO v_id_condicion
    FROM gen_lista_opciones lo
    INNER JOIN gen_lista l ON l.id = lo.id_lista
    WHERE l.nombre = 'CondicionRegulador' AND lo.nombre = v_condicion AND lo.estado = 1
    LIMIT 1;

    IF v_id_condicion IS NULL THEN
        RETURN json_build_object(
            'error', 'No se encontró la condición ' || v_condicion || ' en CondicionRegulador',
            'registro', NULL
        );
    END IF;

    v_obs := NULLIF(TRIM(COALESCE(p_observacion, '')), '');

    UPDATE bal_alquiler
    SET
        fecha_devolucion_regulador = COALESCE(p_fecha, CURRENT_DATE),
        id_condicion_regulador = v_id_condicion,
        id_usuario_modificacion = p_id_usuario_auditoria,
        fecha_modificacion = NOW()
    WHERE id = p_id_alquiler AND estado = 1;

    IF v_condicion = 'BUENO' THEN
        IF NOT v_stock_ok
           AND v_almacen IS NOT NULL
           AND EXISTS (
               SELECT 1 FROM pro_producto
               WHERE id = v_producto
                 AND estado = 1
                 AND COALESCE(afecta_stock, FALSE) = TRUE
           )
        THEN
            v_mov := inv_registrar_movimiento(
                p_naturaleza                => 'PRODUCTO',
                p_codigo_tipo_movimiento    => 'INGRESO',
                p_fecha                     => COALESCE(p_fecha, CURRENT_DATE),
                p_id_producto               => v_producto,
                p_cantidad                  => 1,
                p_id_almacen_origen         => v_almacen,
                p_codigo_tipo_documento_origen => 'ALQUILER',
                p_id_documento_origen       => p_id_alquiler,
                p_glosa                     => 'Reingreso regulador OK — alquiler ' || COALESCE(v_numero, '#' || p_id_alquiler),
                p_id_usuario_auditoria      => p_id_usuario_auditoria
            );

            IF v_mov->>'error' IS NOT NULL THEN
                RETURN json_build_object('error', v_mov->>'error', 'registro', NULL);
            END IF;

            UPDATE bal_alquiler
            SET
                stock_regulador_reingresado = TRUE,
                id_usuario_modificacion = p_id_usuario_auditoria,
                fecha_modificacion = NOW()
            WHERE id = p_id_alquiler AND estado = 1;
        END IF;
    ELSE
        -- PARA_REPARAR: crear mantenimiento de producto (sin reingresar a stock aún)
        SELECT lo.id INTO v_id_tipo_rep
        FROM gen_lista_opciones lo
        INNER JOIN gen_lista l ON l.id = lo.id_lista
        WHERE l.nombre = 'TipoMantenimiento' AND lo.nombre = 'REPARACION' AND lo.estado = 1
        LIMIT 1;

        SELECT lo.id INTO v_id_estado_pend
        FROM gen_lista_opciones lo
        INNER JOIN gen_lista l ON l.id = lo.id_lista
        WHERE l.nombre = 'EstadoMantenimiento' AND lo.nombre = 'PENDIENTE' AND lo.estado = 1
        LIMIT 1;

        IF v_id_estado_pend IS NULL THEN
            RETURN json_build_object(
                'error', 'No se encontró el estado PENDIENTE de mantenimiento',
                'registro', NULL
            );
        END IF;

        INSERT INTO bal_mantenimiento (
            id_balon,
            id_producto,
            id_almacen,
            id_alquiler,
            id_recojo,
            id_tipo_mantenimiento,
            fecha_ingreso,
            descripcion,
            costo,
            es_externo,
            id_estado,
            observacion,
            id_usuario_creacion,
            id_usuario_modificacion
        )
        VALUES (
            NULL,
            v_producto,
            v_almacen,
            p_id_alquiler,
            p_id_recojo,
            v_id_tipo_rep,
            COALESCE(p_fecha, CURRENT_DATE),
            'Reparación de regulador/accesorio devuelto del alquiler '
                || COALESCE(v_numero, '#' || p_id_alquiler),
            0,
            FALSE,
            v_id_estado_pend,
            v_obs,
            p_id_usuario_auditoria,
            p_id_usuario_auditoria
        )
        RETURNING id INTO v_id_mant;

        UPDATE bal_alquiler
        SET
            id_mantenimiento_regulador = v_id_mant,
            id_usuario_modificacion = p_id_usuario_auditoria,
            fecha_modificacion = NOW()
        WHERE id = p_id_alquiler AND estado = 1;
    END IF;

    RETURN json_build_object(
        'error', NULL,
        'registro', json_build_object(
            'id_alquiler', p_id_alquiler,
            'condicion', v_condicion,
            'id_mantenimiento', v_id_mant,
            'stock_reingresado', v_condicion = 'BUENO'
        )
    );
END;
$$;


--
-- Name: bal_eliminar_alquiler(integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bal_eliminar_alquiler(p_id integer, p_id_usuario_auditoria integer DEFAULT NULL::integer) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_id_comprobante_venta INTEGER;
BEGIN
    SET TIME ZONE 'America/Lima';

    SELECT id_comprobante_venta
    INTO v_id_comprobante_venta
    FROM bal_alquiler
    WHERE id = p_id AND estado = 1;

    IF NOT FOUND THEN
        RETURN json_build_object('eliminado', FALSE, 'id', p_id);
    END IF;

    IF v_id_comprobante_venta IS NOT NULL THEN
        RETURN json_build_object(
            'eliminado', FALSE, 'id', p_id,
            'error', 'No se puede eliminar el alquiler porque tiene un comprobante vinculado'
        );
    END IF;

    IF EXISTS (
        SELECT 1 FROM bal_alquiler_detalle WHERE id_alquiler = p_id AND estado = 1
    ) THEN
        RETURN json_build_object(
            'eliminado', FALSE, 'id', p_id,
            'error', 'No se puede eliminar el alquiler porque tiene detalles activos'
        );
    END IF;

    UPDATE bal_alquiler
    SET estado = 0,
        id_usuario_modificacion = p_id_usuario_auditoria,
        fecha_modificacion = NOW()
    WHERE id = p_id AND estado = 1;

    IF NOT FOUND THEN
        RETURN json_build_object('eliminado', FALSE, 'id', p_id);
    END IF;

    RETURN json_build_object('eliminado', TRUE, 'id', p_id);
END;
$$;


--
-- Name: bal_eliminar_alquiler_detalle(integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bal_eliminar_alquiler_detalle(p_id integer, p_id_usuario_auditoria integer DEFAULT NULL::integer) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_id_balon INTEGER;
    v_id_almacen INTEGER;
    v_id_alquiler INTEGER;
    v_id_cliente INTEGER;
    v_fecha_devolucion DATE;
    v_id_estado_en_almacen INTEGER;
    v_mov JSON;
BEGIN
    SET TIME ZONE 'America/Lima';

    SELECT
        ad.id_balon,
        ad.fecha_devolucion,
        ad.id_alquiler,
        al.id_almacen,
        al.id_cliente
    INTO
        v_id_balon,
        v_fecha_devolucion,
        v_id_alquiler,
        v_id_almacen,
        v_id_cliente
    FROM bal_alquiler_detalle ad
    INNER JOIN bal_alquiler al ON al.id = ad.id_alquiler AND al.estado = 1
    WHERE ad.id = p_id
      AND ad.estado = 1;

    IF NOT FOUND THEN
        RETURN json_build_object('eliminado', FALSE, 'id', p_id);
    END IF;

    UPDATE bal_alquiler_detalle
    SET estado = 0,
        id_usuario_modificacion = p_id_usuario_auditoria,
        fecha_modificacion = NOW()
    WHERE id = p_id AND estado = 1;

    IF NOT FOUND THEN
        RETURN json_build_object('eliminado', FALSE, 'id', p_id);
    END IF;

    -- Si el cilindro seguía pendiente de devolución, liberarlo a almacén.
    IF v_id_balon IS NOT NULL AND v_fecha_devolucion IS NULL THEN
        SELECT lo.id INTO v_id_estado_en_almacen
        FROM gen_lista_opciones lo
        INNER JOIN gen_lista l ON lo.id_lista = l.id
        WHERE l.nombre = 'EstadoBalon' AND lo.nombre = 'EN_ALMACEN' AND lo.estado = 1
        LIMIT 1;

        IF v_id_estado_en_almacen IS NOT NULL THEN
            v_mov := inv_registrar_movimiento(
                p_naturaleza                => 'BALON',
                p_codigo_tipo_movimiento    => 'ENTRADA_DEVOLUCION',
                p_fecha                     => NOW(),
                p_id_balon                  => v_id_balon,
                p_cantidad                  => 1,
                p_id_almacen_destino        => v_id_almacen,
                p_id_cliente                => v_id_cliente,
                p_codigo_tipo_documento_origen => 'ALQUILER',
                p_id_documento_origen       => v_id_alquiler,
                p_glosa                     => 'Entrada por quitar cilindro del alquiler',
                p_id_usuario_auditoria      => p_id_usuario_auditoria
            );
            IF v_mov->>'error' IS NOT NULL THEN
                RAISE EXCEPTION '%', v_mov->>'error';
            END IF;

            UPDATE bal_balon
            SET
                id_cliente_ubicacion = NULL,
                id_almacen = COALESCE(v_id_almacen, id_almacen),
                id_estado_balon = v_id_estado_en_almacen,
                id_usuario_modificacion = p_id_usuario_auditoria,
                fecha_modificacion = NOW()
            WHERE id = v_id_balon
              AND estado = 1;
        END IF;
    END IF;

    RETURN json_build_object('eliminado', TRUE, 'id', p_id);
END;
$$;


--
-- Name: bal_eliminar_balon(integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bal_eliminar_balon(p_id integer, p_id_usuario_auditoria integer DEFAULT NULL::integer) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_estado_nombre VARCHAR;
BEGIN
    SET TIME ZONE 'America/Lima';

    SELECT eb.nombre
    INTO v_estado_nombre
    FROM bal_balon b
    LEFT JOIN gen_lista_opciones eb ON b.id_estado_balon = eb.id
    WHERE b.id = p_id AND b.estado = 1;

    IF NOT FOUND THEN
        RETURN json_build_object('eliminado', FALSE, 'id', p_id);
    END IF;

    -- Conservar historial: baja aprobada / robado no se descarta del libro
    IF v_estado_nombre IN ('DADO_DE_BAJA', 'ROBO') THEN
        RETURN json_build_object(
            'eliminado', FALSE, 'id', p_id,
            'error', 'No se puede eliminar un cilindro dado de baja o robado. El historial se conserva para negociaciones con plantas.'
        );
    END IF;

    IF EXISTS (
        SELECT 1 FROM bal_baja_balon
        WHERE id_balon = p_id AND estado = 1 AND estado_aprobacion = 'APROBADA'
    ) THEN
        RETURN json_build_object(
            'eliminado', FALSE, 'id', p_id,
            'error', 'No se puede eliminar un cilindro con baja aprobada. Use el filtro «Dados de baja» para consultarlo.'
        );
    END IF;

    IF EXISTS (
        SELECT 1 FROM bal_baja_balon
        WHERE id_balon = p_id AND estado = 1 AND estado_aprobacion = 'PENDIENTE'
    ) THEN
        RETURN json_build_object(
            'eliminado', FALSE, 'id', p_id,
            'error', 'No se puede eliminar: hay una solicitud de baja pendiente. Apruebe o rechace la baja.'
        );
    END IF;

    IF EXISTS (SELECT 1 FROM inv_movimiento WHERE id_balon = p_id AND estado = 1) THEN
        RETURN json_build_object(
            'eliminado', FALSE, 'id', p_id,
            'error', 'No se puede eliminar el balón porque tiene movimientos. Solicite baja si corresponde.'
        );
    END IF;

    IF EXISTS (SELECT 1 FROM bal_movimiento_recarga WHERE id_balon = p_id AND estado = 1) THEN
        RETURN json_build_object(
            'eliminado', FALSE, 'id', p_id,
            'error', 'No se puede eliminar el balón porque tiene recargas. Solicite baja si corresponde.'
        );
    END IF;

    IF EXISTS (SELECT 1 FROM bal_prestamo_detalle WHERE id_balon = p_id AND estado = 1) THEN
        RETURN json_build_object(
            'eliminado', FALSE, 'id', p_id,
            'error', 'No se puede eliminar el balón porque está en préstamos. Solicite baja si corresponde.'
        );
    END IF;

    IF EXISTS (SELECT 1 FROM bal_alquiler_detalle WHERE id_balon = p_id AND estado = 1) THEN
        RETURN json_build_object(
            'eliminado', FALSE, 'id', p_id,
            'error', 'No se puede eliminar el balón porque está en alquileres. Solicite baja si corresponde.'
        );
    END IF;

    IF EXISTS (SELECT 1 FROM bal_mantenimiento WHERE id_balon = p_id AND estado = 1) THEN
        RETURN json_build_object(
            'eliminado', FALSE, 'id', p_id,
            'error', 'No se puede eliminar el balón porque tiene mantenimientos. Solicite baja si corresponde.'
        );
    END IF;

    IF EXISTS (SELECT 1 FROM bal_balon_ph_historial WHERE id_balon = p_id AND estado = 1) THEN
        RETURN json_build_object(
            'eliminado', FALSE, 'id', p_id,
            'error', 'No se puede eliminar el balón porque tiene historial de P.H. Solicite baja para conservarlo.'
        );
    END IF;

    IF EXISTS (SELECT 1 FROM bal_balon_estado_historial WHERE id_balon = p_id AND estado = 1) THEN
        RETURN json_build_object(
            'eliminado', FALSE, 'id', p_id,
            'error', 'No se puede eliminar el balón porque tiene historial de baja/reactivación. Solicite baja si corresponde.'
        );
    END IF;

    IF EXISTS (SELECT 1 FROM ven_comprobante_detalle WHERE id_balon = p_id AND estado = 1) THEN
        RETURN json_build_object(
            'eliminado', FALSE, 'id', p_id,
            'error', 'No se puede eliminar el balón porque está referenciado en comprobantes de venta.'
        );
    END IF;

    IF EXISTS (SELECT 1 FROM gre_guia_remision_detalle WHERE id_balon = p_id AND estado = 1) THEN
        RETURN json_build_object(
            'eliminado', FALSE, 'id', p_id,
            'error', 'No se puede eliminar el balón porque está referenciado en guías de remisión.'
        );
    END IF;

    UPDATE bal_balon
    SET estado = 0,
        id_usuario_modificacion = p_id_usuario_auditoria,
        fecha_modificacion = NOW()
    WHERE id = p_id AND estado = 1;

    IF NOT FOUND THEN
        RETURN json_build_object('eliminado', FALSE, 'id', p_id);
    END IF;

    RETURN json_build_object('eliminado', TRUE, 'id', p_id);
END;
$$;


--
-- Name: bal_eliminar_mantenimiento(integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bal_eliminar_mantenimiento(p_id integer, p_id_usuario_auditoria integer DEFAULT NULL::integer) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_id_comprobante_venta INTEGER;
    v_id_comprobante_compra INTEGER;
    v_id_balon INTEGER;
    v_id_almacen INTEGER;
    v_nombre_estado VARCHAR;
    v_id_estado_en_almacen INTEGER;
BEGIN
    SET TIME ZONE 'America/Lima';

    SELECT
        m.id_comprobante_venta,
        m.id_comprobante_compra,
        m.id_balon,
        em.nombre,
        b.id_almacen
    INTO
        v_id_comprobante_venta,
        v_id_comprobante_compra,
        v_id_balon,
        v_nombre_estado,
        v_id_almacen
    FROM bal_mantenimiento m
    LEFT JOIN gen_lista_opciones em ON em.id = m.id_estado
    LEFT JOIN bal_balon b ON b.id = m.id_balon AND b.estado = 1
    WHERE m.id = p_id AND m.estado = 1;

    IF NOT FOUND THEN
        RETURN json_build_object('eliminado', FALSE, 'id', p_id);
    END IF;

    IF v_id_comprobante_venta IS NOT NULL OR v_id_comprobante_compra IS NOT NULL THEN
        RETURN json_build_object(
            'eliminado', FALSE,
            'id', p_id,
            'error', 'No se puede eliminar el mantenimiento porque tiene un comprobante vinculado'
        );
    END IF;

    IF EXISTS (
        SELECT 1 FROM bal_balon_ph_historial WHERE id_mantenimiento = p_id AND estado = 1
    ) THEN
        RETURN json_build_object(
            'eliminado', FALSE,
            'id', p_id,
            'error', 'No se puede eliminar el mantenimiento porque tiene historial de P.H. asociado'
        );
    END IF;

    UPDATE bal_mantenimiento
    SET estado = 0,
        id_usuario_modificacion = p_id_usuario_auditoria,
        fecha_modificacion = NOW()
    WHERE id = p_id AND estado = 1;

    IF NOT FOUND THEN
        RETURN json_build_object('eliminado', FALSE, 'id', p_id);
    END IF;

    -- Si no estaba finalizado, restaurar custodia previa (alquiler / préstamo / almacén).
    IF v_id_balon IS NOT NULL AND UPPER(COALESCE(v_nombre_estado, '')) <> 'FINALIZADO' THEN
        IF EXISTS (
            SELECT 1
            FROM bal_alquiler_detalle ad
            INNER JOIN bal_alquiler al ON al.id = ad.id_alquiler AND al.estado = 1
            WHERE ad.id_balon = v_id_balon
              AND ad.estado = 1
              AND ad.fecha_devolucion IS NULL
        ) THEN
            SELECT lo.id INTO v_id_estado_en_almacen
            FROM gen_lista_opciones lo
            INNER JOIN gen_lista l ON lo.id_lista = l.id
            WHERE l.nombre = 'EstadoBalon' AND lo.nombre = 'ALQUILADO' AND lo.estado = 1
            LIMIT 1;

            UPDATE bal_balon b
            SET
                id_estado_balon = COALESCE(v_id_estado_en_almacen, b.id_estado_balon),
                id_almacen = NULL,
                id_cliente_ubicacion = (
                    SELECT al.id_cliente
                    FROM bal_alquiler_detalle ad
                    INNER JOIN bal_alquiler al ON al.id = ad.id_alquiler
                    WHERE ad.id_balon = v_id_balon
                      AND ad.estado = 1
                      AND ad.fecha_devolucion IS NULL
                    ORDER BY ad.id DESC
                    LIMIT 1
                ),
                id_usuario_modificacion = p_id_usuario_auditoria,
                fecha_modificacion = NOW()
            WHERE b.id = v_id_balon
              AND b.estado = 1
              AND EXISTS (
                  SELECT 1 FROM gen_lista_opciones eb
                  WHERE eb.id = b.id_estado_balon
                    AND UPPER(COALESCE(eb.nombre, '')) = 'EN_MANTENIMIENTO'
              );
        ELSIF EXISTS (
            SELECT 1
            FROM bal_prestamo_detalle pd
            INNER JOIN bal_prestamo p2 ON p2.id = pd.id_prestamo AND p2.estado = 1
            WHERE pd.id_balon = v_id_balon
              AND pd.estado = 1
              AND pd.fecha_devolucion IS NULL
        ) THEN
            SELECT lo.id INTO v_id_estado_en_almacen
            FROM gen_lista_opciones lo
            INNER JOIN gen_lista l ON lo.id_lista = l.id
            WHERE l.nombre = 'EstadoBalon' AND lo.nombre = 'PRESTADO_CLIENTE' AND lo.estado = 1
            LIMIT 1;

            UPDATE bal_balon b
            SET
                id_estado_balon = COALESCE(v_id_estado_en_almacen, b.id_estado_balon),
                id_almacen = NULL,
                id_cliente_ubicacion = (
                    SELECT p2.id_cliente
                    FROM bal_prestamo_detalle pd
                    INNER JOIN bal_prestamo p2 ON p2.id = pd.id_prestamo
                    WHERE pd.id_balon = v_id_balon
                      AND pd.estado = 1
                      AND pd.fecha_devolucion IS NULL
                    ORDER BY pd.id DESC
                    LIMIT 1
                ),
                id_usuario_modificacion = p_id_usuario_auditoria,
                fecha_modificacion = NOW()
            WHERE b.id = v_id_balon
              AND b.estado = 1
              AND EXISTS (
                  SELECT 1 FROM gen_lista_opciones eb
                  WHERE eb.id = b.id_estado_balon
                    AND UPPER(COALESCE(eb.nombre, '')) = 'EN_MANTENIMIENTO'
              );
        ELSE
            SELECT lo.id INTO v_id_estado_en_almacen
            FROM gen_lista_opciones lo
            INNER JOIN gen_lista l ON lo.id_lista = l.id
            WHERE l.nombre = 'EstadoBalon' AND lo.nombre = 'EN_ALMACEN' AND lo.estado = 1
            LIMIT 1;

            IF v_id_estado_en_almacen IS NOT NULL THEN
                UPDATE bal_balon
                SET
                    id_estado_balon = v_id_estado_en_almacen,
                    id_almacen = COALESCE(id_almacen, v_id_almacen),
                    id_usuario_modificacion = p_id_usuario_auditoria,
                    fecha_modificacion = NOW()
                WHERE id = v_id_balon
                  AND estado = 1
                  AND EXISTS (
                      SELECT 1
                      FROM gen_lista_opciones eb
                      WHERE eb.id = bal_balon.id_estado_balon
                        AND UPPER(COALESCE(eb.nombre, '')) = 'EN_MANTENIMIENTO'
                  )
                  AND NOT EXISTS (
                      SELECT 1
                      FROM bal_mantenimiento m2
                      LEFT JOIN gen_lista_opciones em2 ON em2.id = m2.id_estado
                      WHERE m2.id_balon = v_id_balon
                        AND m2.id <> p_id
                        AND m2.estado = 1
                        AND UPPER(COALESCE(em2.nombre, '')) <> 'FINALIZADO'
                  );
            END IF;
        END IF;
    END IF;

    RETURN json_build_object('eliminado', TRUE, 'id', p_id);
END;
$$;


--
-- Name: bal_eliminar_movimiento_recarga(integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bal_eliminar_movimiento_recarga(p_id integer, p_id_usuario_auditoria integer DEFAULT NULL::integer) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_id_balon INTEGER;
    v_fecha_llegada DATE;
    v_id_estado_en_almacen INTEGER;
BEGIN
    SET TIME ZONE 'America/Lima';

    IF EXISTS (
        SELECT 1 FROM bal_balon_ph_historial WHERE id_movimiento_recarga = p_id AND estado = 1
    ) THEN
        RETURN json_build_object(
            'eliminado', FALSE,
            'id', p_id,
            'error', 'No se puede eliminar la recarga porque tiene historial de P.H. asociado'
        );
    END IF;

    IF EXISTS (
        SELECT 1
        FROM bal_movimiento_recarga
        WHERE id = p_id AND estado = 1 AND id_comprobante IS NOT NULL
    ) THEN
        RETURN json_build_object(
            'eliminado', FALSE,
            'id', p_id,
            'error', 'No se puede eliminar la recarga porque tiene un comprobante asociado'
        );
    END IF;

    SELECT id_balon, fecha_llegada_almacen
    INTO v_id_balon, v_fecha_llegada
    FROM bal_movimiento_recarga
    WHERE id = p_id AND estado = 1;

    IF NOT FOUND THEN
        RETURN json_build_object('eliminado', FALSE, 'id', p_id);
    END IF;

    -- Revertir kardex unificado ligado a este documento de recarga.
    PERFORM inv_revertir_por_documento('RECARGA', p_id, p_id_usuario_auditoria);

    UPDATE bal_movimiento_recarga
    SET estado = 0,
        id_usuario_modificacion = p_id_usuario_auditoria,
        fecha_modificacion = NOW()
    WHERE id = p_id AND estado = 1;

    IF v_id_balon IS NOT NULL AND v_fecha_llegada IS NULL THEN
        SELECT lo.id INTO v_id_estado_en_almacen
        FROM gen_lista_opciones lo
        INNER JOIN gen_lista l ON lo.id_lista = l.id
        WHERE l.nombre = 'EstadoBalon' AND lo.nombre = 'EN_ALMACEN' AND lo.estado = 1
        LIMIT 1;

        IF v_id_estado_en_almacen IS NOT NULL THEN
            UPDATE bal_balon
            SET
                id_estado_balon = v_id_estado_en_almacen,
                id_usuario_modificacion = p_id_usuario_auditoria,
                fecha_modificacion = NOW()
            WHERE id = v_id_balon
              AND estado = 1
              AND EXISTS (
                  SELECT 1
                  FROM gen_lista_opciones eb
                  WHERE eb.id = bal_balon.id_estado_balon
                    AND UPPER(COALESCE(eb.nombre, '')) = 'EN_RECARGA_EXTERNA'
              )
              AND NOT EXISTS (
                  SELECT 1
                  FROM bal_movimiento_recarga mr
                  WHERE mr.id_balon = v_id_balon
                    AND mr.id <> p_id
                    AND mr.estado = 1
                    AND mr.fecha_llegada_almacen IS NULL
              );
        END IF;
    END IF;

    RETURN json_build_object('eliminado', TRUE, 'id', p_id);
END;
$$;


--
-- Name: bal_eliminar_prestamo(integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bal_eliminar_prestamo(p_id integer, p_id_usuario_auditoria integer DEFAULT NULL::integer) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_id_comprobante_venta INTEGER;
    v_id_comprobante_compra INTEGER;
BEGIN
    SET TIME ZONE 'America/Lima';

    SELECT id_comprobante_venta, id_comprobante_compra
    INTO v_id_comprobante_venta, v_id_comprobante_compra
    FROM bal_prestamo
    WHERE id = p_id AND estado = 1;

    IF NOT FOUND THEN
        RETURN json_build_object('eliminado', FALSE, 'id', p_id);
    END IF;

    IF v_id_comprobante_venta IS NOT NULL OR v_id_comprobante_compra IS NOT NULL THEN
        RETURN json_build_object(
            'eliminado', FALSE, 'id', p_id,
            'error', 'No se puede eliminar el préstamo porque tiene un comprobante vinculado'
        );
    END IF;

    IF EXISTS (
        SELECT 1 FROM bal_prestamo_detalle WHERE id_prestamo = p_id AND estado = 1
    ) THEN
        RETURN json_build_object(
            'eliminado', FALSE, 'id', p_id,
            'error', 'No se puede eliminar el préstamo porque tiene detalles activos'
        );
    END IF;

    IF EXISTS (
        SELECT 1 FROM ven_garantia WHERE id_prestamo = p_id AND estado = 1
    ) THEN
        RETURN json_build_object(
            'eliminado', FALSE, 'id', p_id,
            'error', 'No se puede eliminar el préstamo porque tiene garantías asociadas'
        );
    END IF;

    UPDATE bal_prestamo
    SET estado = 0,
        id_usuario_modificacion = p_id_usuario_auditoria,
        fecha_modificacion = NOW()
    WHERE id = p_id AND estado = 1;

    IF NOT FOUND THEN
        RETURN json_build_object('eliminado', FALSE, 'id', p_id);
    END IF;

    RETURN json_build_object('eliminado', TRUE, 'id', p_id);
END;
$$;


--
-- Name: bal_eliminar_prestamo_detalle(integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bal_eliminar_prestamo_detalle(p_id integer, p_id_usuario_auditoria integer DEFAULT NULL::integer) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_id_prestamo INTEGER;
    v_id_balon INTEGER;
    v_id_almacen INTEGER;
    v_id_cliente INTEGER;
    v_fecha_devolucion DATE;
    v_retorno JSON;
BEGIN
    SET TIME ZONE 'America/Lima';

    SELECT
        pd.id_prestamo,
        pd.id_balon,
        pd.fecha_devolucion,
        p.id_almacen,
        p.id_cliente
    INTO
        v_id_prestamo,
        v_id_balon,
        v_fecha_devolucion,
        v_id_almacen,
        v_id_cliente
    FROM bal_prestamo_detalle pd
    INNER JOIN bal_prestamo p ON p.id = pd.id_prestamo AND p.estado = 1
    WHERE pd.id = p_id
      AND pd.estado = 1;

    IF NOT FOUND THEN
        RETURN json_build_object('eliminado', FALSE, 'id', p_id);
    END IF;

    UPDATE bal_prestamo_detalle
    SET estado = 0,
        id_usuario_modificacion = p_id_usuario_auditoria,
        fecha_modificacion = NOW()
    WHERE id = p_id AND estado = 1;

    IF NOT FOUND THEN
        RETURN json_build_object('eliminado', FALSE, 'id', p_id);
    END IF;

    -- Si seguía pendiente, libera custodia (sin forzar vacío: es anulación, no devolución física).
    IF v_id_balon IS NOT NULL AND v_fecha_devolucion IS NULL THEN
        IF v_id_almacen IS NULL THEN
            SELECT id INTO v_id_almacen FROM gen_almacen WHERE estado = 1 ORDER BY id LIMIT 1;
        END IF;

        v_retorno := bal_prestamo_aplicar_retorno_cilindro(
            v_id_balon,
            v_id_prestamo,
            v_id_cliente,
            v_id_almacen,
            NULL,
            'Anulación de detalle de préstamo',
            p_id_usuario_auditoria,
            TRUE
        );

        IF v_retorno->>'error' IS NOT NULL THEN
            RAISE EXCEPTION '%', v_retorno->>'error';
        END IF;

        PERFORM bal_prestamo_cerrar_si_completo(
            v_id_prestamo,
            CURRENT_DATE,
            p_id_usuario_auditoria
        );
    END IF;

    RETURN json_build_object('eliminado', TRUE, 'id', p_id);
END;
$$;


--
-- Name: bal_eliminar_recarga_planta(integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bal_eliminar_recarga_planta(p_id integer, p_id_usuario_auditoria integer DEFAULT NULL::integer) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_estado VARCHAR;
    v_id_compra INTEGER;
    v_det RECORD;
    v_del JSON;
    v_id_estado_en_almacen INTEGER;
    v_id_balon INTEGER;
BEGIN
    SET TIME ZONE 'America/Lima';

    SELECT est.nombre, rp.id_comprobante_compra
    INTO v_estado, v_id_compra
    FROM bal_recarga_planta rp
    LEFT JOIN gen_lista_opciones est ON est.id = rp.id_estado
    WHERE rp.id = p_id AND rp.estado = 1;

    IF v_estado IS NULL THEN
        RETURN json_build_object('error', 'Orden de recarga no encontrada', 'eliminado', FALSE);
    END IF;

    IF v_estado IN ('RETORNADO', 'CERRADO') THEN
        RETURN json_build_object(
            'error',
            'No se puede eliminar una orden retornada o cerrada',
            'eliminado',
            FALSE
        );
    END IF;

    -- Compra vinculada: no anular/eliminar la orden
    IF v_id_compra IS NOT NULL
       OR EXISTS (
           SELECT 1
           FROM com_comprobante_compra c
           WHERE c.id_recarga_planta = p_id AND c.estado = 1
       )
    THEN
        RETURN json_build_object(
            'error',
            'No se puede eliminar: ya hay una compra registrada con esta orden',
            'eliminado',
            FALSE
        );
    END IF;

    -- Anular movimientos de recarga (por vínculo en detalle o por id_recarga_planta)
    FOR v_det IN
        SELECT DISTINCT mr.id AS id_movimiento_recarga
        FROM bal_movimiento_recarga mr
        WHERE mr.estado = 1
          AND (
              mr.id_recarga_planta = p_id
              OR mr.id IN (
                  SELECT d.id_movimiento_recarga
                  FROM bal_recarga_planta_detalle d
                  WHERE d.id_recarga_planta = p_id
                    AND d.estado = 1
                    AND d.id_movimiento_recarga IS NOT NULL
              )
          )
    LOOP
        v_del := bal_eliminar_movimiento_recarga(v_det.id_movimiento_recarga, p_id_usuario_auditoria);
        IF COALESCE((v_del->>'eliminado')::BOOLEAN, FALSE) IS NOT TRUE
           AND v_del->>'error' IS NOT NULL THEN
            RETURN json_build_object('error', v_del->>'error', 'eliminado', FALSE);
        END IF;
    END LOOP;

    SELECT lo.id INTO v_id_estado_en_almacen
    FROM gen_lista_opciones lo
    INNER JOIN gen_lista l ON lo.id_lista = l.id
    WHERE l.nombre = 'EstadoBalon' AND lo.nombre = 'EN_ALMACEN' AND lo.estado = 1
    LIMIT 1;

    -- Devolver cilindros a EN_ALMACEN si quedaron en EN_RECARGA_EXTERNA
    -- (p.ej. salida marcada por GRE o movimiento no vinculado).
    IF v_id_estado_en_almacen IS NOT NULL THEN
        FOR v_id_balon IN
            SELECT DISTINCT d.id_balon
            FROM bal_recarga_planta_detalle d
            WHERE d.id_recarga_planta = p_id
              AND d.estado = 1
              AND d.id_balon IS NOT NULL
        LOOP
            UPDATE bal_balon b
            SET
                id_estado_balon = v_id_estado_en_almacen,
                id_usuario_modificacion = p_id_usuario_auditoria,
                fecha_modificacion = NOW()
            WHERE b.id = v_id_balon
              AND b.estado = 1
              AND EXISTS (
                  SELECT 1
                  FROM gen_lista_opciones eb
                  WHERE eb.id = b.id_estado_balon
                    AND UPPER(COALESCE(eb.nombre, '')) = 'EN_RECARGA_EXTERNA'
              )
              AND NOT EXISTS (
                  SELECT 1
                  FROM bal_recarga_planta_detalle d2
                  INNER JOIN bal_recarga_planta rp2 ON rp2.id = d2.id_recarga_planta
                  WHERE d2.id_balon = v_id_balon
                    AND d2.estado = 1
                    AND rp2.estado = 1
                    AND rp2.id <> p_id
                    AND rp2.fecha_llegada_almacen IS NULL
              )
              AND NOT EXISTS (
                  SELECT 1
                  FROM bal_movimiento_recarga mr
                  WHERE mr.id_balon = v_id_balon
                    AND mr.estado = 1
                    AND mr.fecha_llegada_almacen IS NULL
              );
        END LOOP;
    END IF;

    UPDATE bal_recarga_planta_detalle
    SET
        estado = 0,
        id_usuario_modificacion = p_id_usuario_auditoria,
        fecha_modificacion = NOW()
    WHERE id_recarga_planta = p_id AND estado = 1;

    UPDATE bal_recarga_planta
    SET
        estado = 0,
        id_usuario_modificacion = p_id_usuario_auditoria,
        fecha_modificacion = NOW()
    WHERE id = p_id;

    RETURN json_build_object('eliminado', TRUE, 'id', p_id);
END;
$$;


--
-- Name: bal_eliminar_recojo(integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bal_eliminar_recojo(p_id integer, p_id_usuario_auditoria integer DEFAULT NULL::integer) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_estado VARCHAR;
    v_id_estado_prestado INTEGER;
    v_id_estado_alquilado INTEGER;
    v_det RECORD;
BEGIN
    SET TIME ZONE 'America/Lima';

    SELECT er.nombre
    INTO v_estado
    FROM bal_recojo r
    LEFT JOIN gen_lista_opciones er ON er.id = r.id_estado
    WHERE r.id = p_id AND r.estado = 1;

    IF v_estado IS NULL THEN
        RETURN json_build_object('eliminado', FALSE, 'id', p_id, 'error', 'Recojo no encontrado');
    END IF;

    IF v_estado NOT IN ('PROGRAMADO', 'EN_RUTA', 'CANCELADO') THEN
        RETURN json_build_object(
            'eliminado', FALSE,
            'id', p_id,
            'error', 'Solo se pueden eliminar recojos PROGRAMADO, EN_RUTA o CANCELADO'
        );
    END IF;

    SELECT lo.id INTO v_id_estado_prestado
    FROM gen_lista_opciones lo
    INNER JOIN gen_lista l ON l.id = lo.id_lista
    WHERE l.nombre = 'EstadoBalon' AND lo.nombre = 'PRESTADO_CLIENTE' AND lo.estado = 1
    LIMIT 1;

    SELECT lo.id INTO v_id_estado_alquilado
    FROM gen_lista_opciones lo
    INNER JOIN gen_lista l ON l.id = lo.id_lista
    WHERE l.nombre = 'EstadoBalon' AND lo.nombre = 'ALQUILADO' AND lo.estado = 1
    LIMIT 1;

    -- POR_RECOGER → PRESTADO o ALQUILADO según el origen del detalle.
    IF v_id_estado_prestado IS NOT NULL THEN
        FOR v_det IN
            SELECT pd.id_balon
            FROM bal_recojo_detalle rd
            INNER JOIN bal_prestamo_detalle pd ON pd.id = rd.id_prestamo_detalle AND pd.estado = 1
            INNER JOIN bal_balon b ON b.id = pd.id_balon AND b.estado = 1
            INNER JOIN gen_lista_opciones eb ON eb.id = b.id_estado_balon
            WHERE rd.id_recojo = p_id
              AND rd.estado = 1
              AND pd.fecha_devolucion IS NULL
              AND eb.nombre = 'POR_RECOGER'
        LOOP
            UPDATE bal_balon
            SET
                id_estado_balon = v_id_estado_prestado,
                id_usuario_modificacion = p_id_usuario_auditoria,
                fecha_modificacion = NOW()
            WHERE id = v_det.id_balon;
        END LOOP;
    END IF;

    IF v_id_estado_alquilado IS NOT NULL THEN
        FOR v_det IN
            SELECT ad.id_balon
            FROM bal_recojo_detalle rd
            INNER JOIN bal_alquiler_detalle ad ON ad.id = rd.id_alquiler_detalle AND ad.estado = 1
            INNER JOIN bal_balon b ON b.id = ad.id_balon AND b.estado = 1
            INNER JOIN gen_lista_opciones eb ON eb.id = b.id_estado_balon
            WHERE rd.id_recojo = p_id
              AND rd.estado = 1
              AND ad.fecha_devolucion IS NULL
              AND eb.nombre = 'POR_RECOGER'
        LOOP
            UPDATE bal_balon
            SET
                id_estado_balon = v_id_estado_alquilado,
                id_usuario_modificacion = p_id_usuario_auditoria,
                fecha_modificacion = NOW()
            WHERE id = v_det.id_balon;
        END LOOP;
    END IF;

    UPDATE bal_recojo_detalle
    SET
        estado = 0,
        id_usuario_modificacion = p_id_usuario_auditoria,
        fecha_modificacion = NOW()
    WHERE id_recojo = p_id AND estado = 1;

    UPDATE bal_recojo
    SET
        estado = 0,
        id_usuario_modificacion = p_id_usuario_auditoria,
        fecha_modificacion = NOW()
    WHERE id = p_id AND estado = 1;

    RETURN json_build_object('eliminado', TRUE, 'id', p_id);
END;
$$;


--
-- Name: bal_eliminar_ruta_pueblo(integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bal_eliminar_ruta_pueblo(p_id integer, p_id_usuario_auditoria integer DEFAULT NULL::integer) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_estado VARCHAR;
BEGIN
    SET TIME ZONE 'America/Lima';

    SELECT er.nombre INTO v_estado
    FROM bal_ruta_pueblo r
    LEFT JOIN gen_lista_opciones er ON er.id = r.id_estado
    WHERE r.id = p_id AND r.estado = 1;

    IF v_estado IS NULL THEN
        RETURN json_build_object('eliminado', FALSE, 'id', p_id, 'error', 'Ruta no encontrada');
    END IF;

    IF v_estado = 'EN_RUTA' THEN
        RETURN json_build_object(
            'eliminado', FALSE,
            'id', p_id,
            'error', 'No se puede eliminar una ruta EN_RUTA; regÃ­strela o cancÃ©lela'
        );
    END IF;

    UPDATE bal_ruta_pueblo_detalle
    SET estado = 0,
        id_usuario_modificacion = p_id_usuario_auditoria,
        fecha_modificacion = NOW()
    WHERE id_ruta_pueblo = p_id AND estado = 1;

    UPDATE bal_ruta_pueblo
    SET estado = 0,
        id_usuario_modificacion = p_id_usuario_auditoria,
        fecha_modificacion = NOW()
    WHERE id = p_id AND estado = 1;

    RETURN json_build_object('eliminado', TRUE, 'id', p_id);
END;
$$;


--
-- Name: bal_eliminar_tipo_balon(integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bal_eliminar_tipo_balon(p_id integer, p_id_usuario_auditoria integer DEFAULT NULL::integer) RETURNS json
    LANGUAGE plpgsql
    AS $$
BEGIN
    SET TIME ZONE 'America/Lima';

    IF EXISTS (
        SELECT 1 FROM bal_balon WHERE id_tipo_balon = p_id AND estado = 1
    ) THEN
        RETURN json_build_object(
            'eliminado', FALSE,
            'id', p_id,
            'error', 'No se puede eliminar el tipo de balón porque tiene cilindros activos asociados'
        );
    END IF;

    IF EXISTS (
        SELECT 1 FROM pro_catalogo_precio WHERE id_tipo_balon = p_id AND estado = 1
    ) THEN
        RETURN json_build_object(
            'eliminado', FALSE,
            'id', p_id,
            'error', 'No se puede eliminar el tipo de balón porque está usado en el catálogo de precios'
        );
    END IF;

    UPDATE bal_tipo_balon
    SET estado = 0,
        id_usuario_modificacion = p_id_usuario_auditoria,
        fecha_modificacion = NOW()
    WHERE id = p_id AND estado = 1;

    IF NOT FOUND THEN
        RETURN json_build_object('eliminado', FALSE, 'id', p_id);
    END IF;

    RETURN json_build_object('eliminado', TRUE, 'id', p_id);
END;
$$;


--
-- Name: bal_factor_lb_m3(integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bal_factor_lb_m3(p_id_tipo_balon integer DEFAULT NULL::integer, p_id_producto_gas integer DEFAULT NULL::integer) RETURNS numeric
    LANGUAGE plpgsql STABLE
    AS $$
DECLARE
    v_cap_m3 NUMERIC;
    v_cap_lb NUMERIC;
    v_factor_prod NUMERIC;
BEGIN
    IF p_id_tipo_balon IS NOT NULL THEN
        SELECT tb.capacidad, tb.capacidad_lb
        INTO v_cap_m3, v_cap_lb
        FROM bal_tipo_balon tb
        WHERE tb.id = p_id_tipo_balon AND tb.estado = 1;

        IF v_cap_m3 IS NOT NULL AND v_cap_m3 > 0 AND v_cap_lb IS NOT NULL AND v_cap_lb > 0 THEN
            RETURN ROUND(v_cap_m3 / v_cap_lb, 6);
        END IF;
    END IF;

    IF p_id_producto_gas IS NOT NULL THEN
        SELECT p.factor_lb_m3
        INTO v_factor_prod
        FROM pro_producto p
        WHERE p.id = p_id_producto_gas AND p.estado = 1;

        IF v_factor_prod IS NOT NULL AND v_factor_prod > 0 THEN
            RETURN ROUND(v_factor_prod, 6);
        END IF;
    END IF;

    RETURN 0.317400;
END;
$$;


--
-- Name: bal_finalizar_mantenimiento(integer, date, integer, character varying, integer, integer, integer, boolean, character varying); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bal_finalizar_mantenimiento(p_id integer, p_fecha_salida date DEFAULT CURRENT_DATE, p_id_almacen_destino integer DEFAULT NULL::integer, p_observacion character varying DEFAULT NULL::character varying, p_id_usuario_auditoria integer DEFAULT NULL::integer, p_vigencia_ph_anios integer DEFAULT NULL::integer, p_id_organo_inspector integer DEFAULT NULL::integer, p_organo_inspector_no_aplica boolean DEFAULT NULL::boolean, p_numero_certificado_ph character varying DEFAULT NULL::character varying) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_id_balon INTEGER;
    v_id_producto INTEGER;
    v_id_alquiler INTEGER;
    v_id_almacen INTEGER;
    v_id_cliente_ubicacion INTEGER;
    v_id_cliente_propietario INTEGER;
    v_id_cliente_comprobante INTEGER;
    v_id_cliente_destino INTEGER;
    v_nombre_propietario VARCHAR;
    v_nombre_estado VARCHAR;
    v_es_servicio_cliente BOOLEAN;
    v_id_almacen_destino INTEGER;
    v_id_estado_finalizado INTEGER;
    v_id_estado_destino INTEGER;
    v_mov_result JSON;
    v_obs_movimiento VARCHAR;
BEGIN
    SET TIME ZONE 'America/Lima';

    SELECT
        m.id_balon,
        m.id_producto,
        m.id_alquiler,
        em.nombre,
        COALESCE(m.id_almacen, b.id_almacen),
        b.id_cliente_ubicacion,
        b.id_cliente_propietario,
        UPPER(COALESCE(prop.nombre, '')),
        cv.id_cliente
    INTO
        v_id_balon,
        v_id_producto,
        v_id_alquiler,
        v_nombre_estado,
        v_id_almacen,
        v_id_cliente_ubicacion,
        v_id_cliente_propietario,
        v_nombre_propietario,
        v_id_cliente_comprobante
    FROM bal_mantenimiento m
    LEFT JOIN bal_balon b ON b.id = m.id_balon AND b.estado = 1
    LEFT JOIN gen_lista_opciones em ON em.id = m.id_estado
    LEFT JOIN gen_lista_opciones prop ON prop.id = b.id_propietario
    LEFT JOIN ven_comprobante cv ON cv.id = m.id_comprobante_venta AND cv.estado = 1
    WHERE m.id = p_id
      AND m.estado = 1;

    IF v_id_balon IS NULL AND v_id_producto IS NULL THEN
        RETURN json_build_object(
            'error', 'El mantenimiento no existe o está inactivo',
            'registro', NULL
        );
    END IF;

    IF UPPER(COALESCE(v_nombre_estado, '')) = 'FINALIZADO' THEN
        RETURN json_build_object(
            'error', 'El mantenimiento ya está finalizado',
            'registro', NULL
        );
    END IF;

    SELECT lo.id INTO v_id_estado_finalizado
    FROM gen_lista_opciones lo
    INNER JOIN gen_lista l ON lo.id_lista = l.id
    WHERE l.nombre = 'EstadoMantenimiento' AND lo.nombre = 'FINALIZADO' AND lo.estado = 1
    LIMIT 1;

    IF v_id_estado_finalizado IS NULL THEN
        RETURN json_build_object(
            'error', 'No se encontró el estado FINALIZADO de mantenimiento',
            'registro', NULL
        );
    END IF;

    UPDATE bal_mantenimiento
    SET
        fecha_salida = COALESCE(p_fecha_salida, CURRENT_DATE),
        id_estado = v_id_estado_finalizado,
        observacion = COALESCE(NULLIF(TRIM(p_observacion), ''), observacion),
        id_usuario_modificacion = p_id_usuario_auditoria,
        fecha_modificacion = NOW()
    WHERE id = p_id
      AND estado = 1;

    -- Regulador/accesorio (producto): reingreso a stock al finalizar reparación
    IF v_id_producto IS NOT NULL THEN
        v_id_almacen_destino := COALESCE(p_id_almacen_destino, v_id_almacen);

        IF v_id_almacen_destino IS NULL THEN
            RETURN json_build_object(
                'error', 'Debe indicar el almacén de destino del reingreso del regulador',
                'registro', NULL
            );
        END IF;

        IF EXISTS (
            SELECT 1 FROM pro_producto
            WHERE id = v_id_producto
              AND estado = 1
              AND COALESCE(afecta_stock, FALSE) = TRUE
        ) THEN
            v_mov_result := inv_registrar_movimiento(
                p_naturaleza                => 'PRODUCTO',
                p_codigo_tipo_movimiento    => 'INGRESO',
                p_fecha                     => COALESCE(p_fecha_salida, CURRENT_DATE),
                p_id_producto               => v_id_producto,
                p_cantidad                  => 1,
                p_id_almacen_origen         => v_id_almacen_destino,
                p_codigo_tipo_documento_origen => 'MANTENIMIENTO',
                p_id_documento_origen       => p_id,
                p_glosa                     => COALESCE(
                    NULLIF(TRIM(p_observacion), ''),
                    'Reingreso regulador tras mantenimiento #' || p_id
                ),
                p_id_usuario_auditoria      => p_id_usuario_auditoria
            );

            IF v_mov_result->>'error' IS NOT NULL THEN
                RETURN json_build_object('error', v_mov_result->>'error', 'registro', NULL);
            END IF;
        END IF;

        IF v_id_alquiler IS NOT NULL THEN
            UPDATE bal_alquiler
            SET
                stock_regulador_reingresado = TRUE,
                id_usuario_modificacion = p_id_usuario_auditoria,
                fecha_modificacion = NOW()
            WHERE id = v_id_alquiler AND estado = 1;
        END IF;

        RETURN bal_obtener_mantenimiento(p_id);
    END IF;

    v_es_servicio_cliente := (
        v_nombre_propietario = 'CLIENTE'
        OR v_id_cliente_ubicacion IS NOT NULL
    );

    -- Inventario empresa: sin dueño cliente ni ubicación en cliente → reingreso a almacén
    -- (el comprobante de venta solo indica cobro del servicio, no cambia la custodia del envase)

    IF v_es_servicio_cliente THEN
        v_id_cliente_destino := COALESCE(
            v_id_cliente_ubicacion,
            v_id_cliente_propietario,
            v_id_cliente_comprobante
        );

        IF v_nombre_propietario = 'CLIENTE' THEN
            SELECT lo.id INTO v_id_estado_destino
            FROM gen_lista_opciones lo
            INNER JOIN gen_lista l ON lo.id_lista = l.id
            WHERE l.nombre = 'EstadoBalon' AND lo.nombre = 'EN_PODER_CLIENTE' AND lo.estado = 1
            LIMIT 1;
        ELSE
            -- Envase de empresa que estaba prestado / con el cliente
            SELECT lo.id INTO v_id_estado_destino
            FROM gen_lista_opciones lo
            INNER JOIN gen_lista l ON lo.id_lista = l.id
            WHERE l.nombre = 'EstadoBalon' AND lo.nombre = 'PRESTADO_CLIENTE' AND lo.estado = 1
            LIMIT 1;
        END IF;

        IF v_id_estado_destino IS NULL THEN
            RETURN json_build_object(
                'error', 'No se encontró el estado destino del cilindro (EN_PODER_CLIENTE / PRESTADO_CLIENTE). Revise el catálogo EstadoBalon.',
                'registro', NULL
            );
        END IF;

        v_obs_movimiento := COALESCE(
            NULLIF(TRIM(p_observacion), ''),
            'Entrega al cliente tras servicio de mantenimiento'
        );

        v_mov_result := inv_registrar_movimiento(
            p_naturaleza                => 'BALON',
            p_codigo_tipo_movimiento    => 'SALIDA_ENTREGA_CLIENTE',
            p_fecha                     => COALESCE(p_fecha_salida, CURRENT_DATE),
            p_id_balon                  => v_id_balon,
            p_cantidad                  => 1,
            p_id_almacen_origen         => v_id_almacen,
            p_id_cliente                => v_id_cliente_destino,
            p_codigo_tipo_documento_origen => 'MANTENIMIENTO',
            p_id_documento_origen       => p_id,
            p_glosa                     => v_obs_movimiento,
            p_id_usuario_auditoria      => p_id_usuario_auditoria
        );

        IF v_mov_result->>'error' IS NOT NULL THEN
            RAISE EXCEPTION '%', v_mov_result->>'error';
        END IF;

        -- Custodia al cliente. Tras mant. sale vacío; residual no aplica fuera de planta.
        UPDATE bal_balon
        SET
            id_almacen = NULL,
            id_cliente_ubicacion = v_id_cliente_destino,
            id_estado_balon = v_id_estado_destino,
            id_usuario_modificacion = p_id_usuario_auditoria,
            fecha_modificacion = NOW()
        WHERE id = v_id_balon
          AND estado = 1;

    ELSE
        -- Inventario empresa: reingreso a almacén
        v_id_almacen_destino := COALESCE(p_id_almacen_destino, v_id_almacen);

        IF v_id_almacen_destino IS NULL THEN
            RETURN json_build_object(
                'error', 'Debe indicar el almacén de destino del reingreso',
                'registro', NULL
            );
        END IF;

        IF NOT EXISTS (
            SELECT 1 FROM gen_almacen WHERE id = v_id_almacen_destino AND estado = 1
        ) THEN
            RETURN json_build_object(
                'error', 'El almacén de destino no existe o está inactivo',
                'registro', NULL
            );
        END IF;

        SELECT lo.id INTO v_id_estado_destino
        FROM gen_lista_opciones lo
        INNER JOIN gen_lista l ON lo.id_lista = l.id
        WHERE l.nombre = 'EstadoBalon' AND lo.nombre = 'EN_ALMACEN' AND lo.estado = 1
        LIMIT 1;

        IF v_id_estado_destino IS NULL THEN
            RETURN json_build_object(
                'error', 'No se encontró el estado EN_ALMACEN del cilindro. Revise el catálogo EstadoBalon.',
                'registro', NULL
            );
        END IF;

        v_obs_movimiento := COALESCE(
            NULLIF(TRIM(p_observacion), ''),
            'Entrada por finalización de mantenimiento'
        );

        v_mov_result := inv_registrar_movimiento(
            p_naturaleza                => 'BALON',
            p_codigo_tipo_movimiento    => 'ENTRADA_MANTENIMIENTO',
            p_fecha                     => COALESCE(p_fecha_salida, CURRENT_DATE),
            p_id_balon                  => v_id_balon,
            p_cantidad                  => 1,
            p_id_almacen_destino        => v_id_almacen_destino,
            p_codigo_tipo_documento_origen => 'MANTENIMIENTO',
            p_id_documento_origen       => p_id,
            p_glosa                     => v_obs_movimiento,
            p_id_usuario_auditoria      => p_id_usuario_auditoria
        );

        IF v_mov_result->>'error' IS NOT NULL THEN
            RAISE EXCEPTION '%', v_mov_result->>'error';
        END IF;

        -- Reingreso a almacén vacío (tras PH/reparación no se asume recarga).
        UPDATE bal_balon
        SET
            id_cliente_ubicacion = NULL,
            id_almacen = v_id_almacen_destino,
            id_estado_balon = v_id_estado_destino,
            id_usuario_modificacion = p_id_usuario_auditoria,
            fecha_modificacion = NOW()
        WHERE id = v_id_balon
          AND estado = 1;
    END IF;

    PERFORM bal_sync_ph_desde_mantenimiento(
        p_id,
        p_id_usuario_auditoria,
        p_vigencia_ph_anios,
        p_id_organo_inspector,
        p_organo_inspector_no_aplica,
        p_numero_certificado_ph
    );

    RETURN bal_obtener_mantenimiento(p_id);
END;
$$;


--
-- Name: bal_finalizar_recarga_planta(integer, integer, date, integer, integer, boolean, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bal_finalizar_recarga_planta(p_id_recarga_planta integer, p_id_comprobante_compra integer, p_fecha_llegada_almacen date, p_id_almacen integer, p_id_proveedor integer DEFAULT NULL::integer, p_guardar_balones_almacen boolean DEFAULT false, p_id_usuario_auditoria integer DEFAULT NULL::integer) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_resultado             JSON;
    v_id_estado_en_almacen  INTEGER;
    v_id_documento_ref      INTEGER;
    v_det                   RECORD;
    v_mov                   JSON;
BEGIN
    SET TIME ZONE 'America/Lima';

    IF NOT EXISTS (
        SELECT 1 FROM bal_recarga_planta WHERE id = p_id_recarga_planta AND estado = 1
    ) THEN
        RETURN json_build_object('error', 'La orden de recarga en planta externa no existe o está inactiva', 'registro', NULL);
    END IF;

    -- Si p_fecha_llegada_almacen viene, bal_actualizar exige lote + vencimiento + P.H. en la orden.
    v_resultado := bal_actualizar_recarga_planta(
        p_id                    => p_id_recarga_planta,
        p_id_proveedor          => p_id_proveedor,
        p_id_almacen            => p_id_almacen,
        p_id_comprobante_compra => p_id_comprobante_compra,
        p_fecha_llegada_almacen => p_fecha_llegada_almacen,
        p_id_usuario_auditoria  => p_id_usuario_auditoria
    );

    IF v_resultado->>'error' IS NOT NULL THEN
        RETURN json_build_object('error', v_resultado->>'error', 'registro', NULL);
    END IF;

    IF p_guardar_balones_almacen THEN
        SELECT lo.id INTO v_id_estado_en_almacen
        FROM gen_lista_opciones lo
        INNER JOIN gen_lista l ON l.id = lo.id_lista
        WHERE l.nombre = 'EstadoBalon' AND lo.nombre = 'EN_ALMACEN' AND lo.estado = 1
        LIMIT 1;

        -- Preferir COMPRA como documento de referencia cuando la factura ya está vinculada.
        IF p_id_comprobante_compra IS NOT NULL THEN
            v_id_documento_ref := p_id_comprobante_compra;
        ELSE
            v_id_documento_ref := p_id_recarga_planta;
        END IF;

        FOR v_det IN
            SELECT d.id_balon, COALESCE(d.id_producto, b.id_producto_gas) AS id_producto, d.capacidad
            FROM bal_recarga_planta_detalle d
            LEFT JOIN bal_balon b ON b.id = d.id_balon
            WHERE d.id_recarga_planta = p_id_recarga_planta
              AND d.estado = 1
        LOOP
            PERFORM bal_actualizar_balon(
                p_id                   => v_det.id_balon,
                p_id_almacen           => p_id_almacen,
                p_id_estado_balon      => v_id_estado_en_almacen,
                p_id_usuario_auditoria => p_id_usuario_auditoria
            );

            v_mov := inv_registrar_movimiento(
                p_naturaleza                => 'BALON',
                p_codigo_tipo_movimiento    => 'ENTRADA_LLENADO',
                p_fecha                     => NOW(),
                p_id_producto               => v_det.id_producto,
                p_id_balon                  => v_det.id_balon,
                p_cantidad                  => COALESCE(v_det.capacidad, 1),
                p_id_almacen_destino        => p_id_almacen,
                p_id_cliente                => p_id_proveedor,
                p_codigo_tipo_documento_origen => CASE
                    WHEN p_id_comprobante_compra IS NOT NULL THEN 'COMPRA'
                    ELSE 'RECARGA'
                END,
                p_id_documento_origen       => v_id_documento_ref,
                p_glosa                     => CASE
                    WHEN p_id_comprobante_compra IS NOT NULL THEN
                        'Entrada por compra #' || p_id_comprobante_compra
                        || ' (orden planta #' || p_id_recarga_planta || ')'
                    ELSE
                        'Entrada por recarga en planta externa (orden #' || p_id_recarga_planta || ')'
                END,
                p_id_usuario_auditoria      => p_id_usuario_auditoria
            );

            IF v_mov->>'error' IS NOT NULL THEN
                RAISE EXCEPTION 'No se pudo registrar el movimiento de entrada del balón %: %', v_det.id_balon, v_mov->>'error';
            END IF;
        END LOOP;
    END IF;

    RETURN json_build_object(
        'error', NULL,
        'registro', json_build_object('id_recarga_planta', p_id_recarga_planta)
    );
END;
$$;


--
-- Name: bal_generar_recojo_recarga_planta(integer, date, integer, character varying, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bal_generar_recojo_recarga_planta(p_id_recarga_planta integer, p_fecha_programada date DEFAULT NULL::date, p_id_usuario_responsable integer DEFAULT NULL::integer, p_observacion character varying DEFAULT NULL::character varying, p_id_usuario_auditoria integer DEFAULT NULL::integer) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_proveedor INTEGER;
    v_rp_estado VARCHAR;
    v_fecha DATE;
    v_detalles JSONB := '[]'::JSONB;
    v_item JSONB;
    v_id_balon INTEGER;
    v_id INTEGER;
    v_existente INTEGER;
    v_rec RECORD;
BEGIN
    SET TIME ZONE 'America/Lima';

    SELECT rp.id_proveedor, est.nombre
    INTO v_proveedor, v_rp_estado
    FROM bal_recarga_planta rp
    LEFT JOIN gen_lista_opciones est ON est.id = rp.id_estado
    WHERE rp.id = p_id_recarga_planta AND rp.estado = 1;

    IF v_proveedor IS NULL THEN
        RETURN json_build_object('error', 'Orden de recarga en planta no encontrada', 'registro', NULL);
    END IF;

    IF v_rp_estado NOT IN ('ENVIADO', 'CERRADO') THEN
        RETURN json_build_object(
            'error', 'La orden de recarga en planta aún no ha sido enviada',
            'registro', NULL
        );
    END IF;

    SELECT r.id INTO v_existente
    FROM bal_recojo r
    WHERE r.id_recarga_planta = p_id_recarga_planta
      AND r.estado = 1
    LIMIT 1;

    IF v_existente IS NOT NULL THEN
        RETURN json_build_object(
            'error', 'Ya existe un recojo para esta orden de recarga en planta',
            'registro', bal_obtener_recojo(v_existente)
        );
    END IF;

    v_fecha := COALESCE(p_fecha_programada, CURRENT_DATE + 5);

    FOR v_rec IN
        SELECT d.id_balon
        FROM bal_recarga_planta_detalle d
        WHERE d.id_recarga_planta = p_id_recarga_planta
          AND d.estado = 1
    LOOP
        v_id_balon := v_rec.id_balon;
        IF NOT EXISTS (
            SELECT 1
            FROM bal_balon b
            JOIN gen_lista_opciones e ON e.id = b.id_estado_balon
            WHERE b.id = v_id_balon AND b.estado = 1 AND e.nombre = 'EN_RECARGA_EXTERNA'
        ) THEN
            RETURN json_build_object(
                'error', 'El balón ' || v_id_balon || ' no está en estado EN_RECARGA_EXTERNA',
                'registro', NULL
            );
        END IF;

        v_item := jsonb_build_object('id_balon', v_id_balon, 'observacion', NULL);
        v_detalles := v_detalles || jsonb_build_array(v_item);
    END LOOP;

    IF jsonb_array_length(v_detalles) = 0 THEN
        RETURN json_build_object(
            'error', 'La orden de recarga en planta no tiene cilindros para recojo',
            'registro', NULL
        );
    END IF;

    RETURN bal_crear_recojo(
        v_proveedor,
        NULL,
        NULL,
        p_id_recarga_planta,
        v_fecha,
        NULL::TIME,
        p_id_usuario_responsable,
        NULLIF(TRIM(p_observacion), ''),
        v_detalles::JSON,
        p_id_usuario_auditoria
    );
END;
$$;


--
-- Name: bal_iniciar_ruta_pueblo(integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bal_iniciar_ruta_pueblo(p_id integer, p_id_usuario_auditoria integer DEFAULT NULL::integer) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_estado VARCHAR;
    v_id_almacen INTEGER;
    v_id_estado_ruta INTEGER;
    v_det RECORD;
    v_mov JSON;
BEGIN
    SET TIME ZONE 'America/Lima';

    SELECT er.nombre, r.id_almacen
    INTO v_estado, v_id_almacen
    FROM bal_ruta_pueblo r
    LEFT JOIN gen_lista_opciones er ON er.id = r.id_estado
    WHERE r.id = p_id AND r.estado = 1;

    IF v_estado IS NULL THEN
        RETURN json_build_object('error', 'Ruta no encontrada', 'registro', NULL);
    END IF;

    IF v_estado <> 'ABIERTA' THEN
        RETURN json_build_object('error', 'Solo se puede iniciar una ruta ABIERTA', 'registro', NULL);
    END IF;

    IF NOT EXISTS (
        SELECT 1 FROM bal_ruta_pueblo_detalle WHERE id_ruta_pueblo = p_id AND estado = 1
    ) THEN
        RETURN json_build_object('error', 'La ruta no tiene cilindros', 'registro', NULL);
    END IF;

    SELECT lo.id INTO v_id_estado_ruta
    FROM gen_lista_opciones lo
    INNER JOIN gen_lista l ON l.id = lo.id_lista
    WHERE l.nombre = 'EstadoRutaPueblo' AND lo.nombre = 'EN_RUTA' AND lo.estado = 1
    LIMIT 1;

    FOR v_det IN
        SELECT d.id_balon, d.lb_salida
        FROM bal_ruta_pueblo_detalle d
        WHERE d.id_ruta_pueblo = p_id AND d.estado = 1
    LOOP
        v_mov := bal_registrar_salida_documento(
            v_det.id_balon,
            'TRASLADO_LIMA',
            p_id,
            'RUTA_PUEBLO',
            NULL,
            v_id_almacen,
            'EN_RUTA_LIMA',
            TRUE,
            NULL,
            format('Salida ruta pueblos #%s · %.4f lb', p_id, v_det.lb_salida),
            p_id_usuario_auditoria
        );

        IF v_mov->>'error' IS NOT NULL THEN
            RAISE EXCEPTION 'Cilindro %: %', v_det.id_balon, v_mov->>'error';
        END IF;

        UPDATE bal_balon
        SET
            id_usuario_modificacion = p_id_usuario_auditoria,
            fecha_modificacion = NOW()
        WHERE id = v_det.id_balon AND estado = 1;
    END LOOP;

    UPDATE bal_ruta_pueblo
    SET
        id_estado = v_id_estado_ruta,
        id_usuario_modificacion = p_id_usuario_auditoria,
        fecha_modificacion = NOW()
    WHERE id = p_id;

    RETURN bal_obtener_ruta_pueblo(p_id);
END;
$$;


--
-- Name: bal_listar_alquiler_detalles(character varying, integer, integer, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bal_listar_alquiler_detalles(p_busqueda character varying DEFAULT ''::character varying, p_limite integer DEFAULT 10, p_offset integer DEFAULT 0, p_id_alquiler integer DEFAULT NULL::integer, p_id_balon integer DEFAULT NULL::integer) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_registros JSON;
    v_total BIGINT;
BEGIN
    SET TIME ZONE 'America/Lima';

    SELECT COUNT(*) INTO v_total
    FROM bal_alquiler_detalle ad
    INNER JOIN bal_alquiler al ON ad.id_alquiler = al.id
    INNER JOIN bal_balon b ON ad.id_balon = b.id
    LEFT JOIN cli_clientes c ON al.id_cliente = c.id
    WHERE ad.estado = 1
      AND (p_id_alquiler IS NULL OR ad.id_alquiler = p_id_alquiler)
      AND (p_id_balon IS NULL OR ad.id_balon = p_id_balon)
      AND (
          p_busqueda = ''
          OR gen_texto_coincide(b.codigo_balon, p_busqueda)
          OR gen_texto_coincide(COALESCE(al.numero_alquiler, ''), p_busqueda)
          OR gen_texto_coincide(COALESCE(c.razon_social, ''), p_busqueda)
      );

    SELECT COALESCE(json_agg(row_to_json(t)), '[]'::JSON) INTO v_registros
    FROM (
        SELECT
            ad.id,
            ad.id_alquiler,
            al.numero_alquiler,
            ad.id_balon,
            b.codigo_balon,
            ad.fecha_devolucion,
            al.id_cliente,
            c.razon_social AS nombre_cliente,
            al.fecha_inicio,
            al.fecha_fin_pactada,
            al.fecha_fin_real,
            al.tarifa_diaria,
            al.id_estado,
            ea.nombre AS nombre_estado,
            CASE
                WHEN ad.fecha_devolucion IS NOT NULL THEN 'DEVUELTO'
                ELSE 'PENDIENTE'
            END AS estado_devolucion,
            ad.estado,
            ad.fecha_creacion
        FROM bal_alquiler_detalle ad
        INNER JOIN bal_alquiler al ON ad.id_alquiler = al.id
        INNER JOIN bal_balon b ON ad.id_balon = b.id
        LEFT JOIN cli_clientes c ON al.id_cliente = c.id
        LEFT JOIN gen_lista_opciones ea ON al.id_estado = ea.id
        WHERE ad.estado = 1
          AND (p_id_alquiler IS NULL OR ad.id_alquiler = p_id_alquiler)
          AND (p_id_balon IS NULL OR ad.id_balon = p_id_balon)
          AND (
              p_busqueda = ''
              OR gen_texto_coincide(b.codigo_balon, p_busqueda)
              OR gen_texto_coincide(COALESCE(al.numero_alquiler, ''), p_busqueda)
              OR gen_texto_coincide(COALESCE(c.razon_social, ''), p_busqueda)
          )
        ORDER BY al.fecha_inicio DESC NULLS LAST, ad.id DESC
        LIMIT p_limite
        OFFSET p_offset
    ) t;

    RETURN json_build_object('registros', v_registros, 'total', v_total);
END;
$$;


--
-- Name: bal_listar_alquiler_periodos(integer, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bal_listar_alquiler_periodos(p_id_alquiler integer, p_limite integer DEFAULT 100, p_offset integer DEFAULT 0) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_registros JSON;
    v_total BIGINT;
BEGIN
    SET TIME ZONE 'America/Lima';

    IF p_id_alquiler IS NULL THEN
        RETURN json_build_object('error', 'id_alquiler es obligatorio', 'registros', '[]'::JSON, 'total', 0);
    END IF;

    SELECT COUNT(*) INTO v_total
    FROM bal_alquiler_periodo p
    WHERE p.id_alquiler = p_id_alquiler AND p.estado = 1;

    SELECT COALESCE(json_agg(row_to_json(t)), '[]'::JSON) INTO v_registros
    FROM (
        SELECT
            p.id,
            p.id_alquiler,
            p.numero_periodo,
            p.fecha_inicio,
            p.fecha_fin,
            p.monto,
            p.id_producto,
            pr.codigo AS codigo_producto,
            pr.nombre AS nombre_producto,
            p.id_comprobante,
            CASE
                WHEN cv.id IS NULL THEN NULL
                ELSE CONCAT_WS('-', cv.serie, cv.numero)
            END AS comprobante,
            p.id_estado,
            ea.nombre AS nombre_estado,
            p.observacion,
            p.fecha_creacion
        FROM bal_alquiler_periodo p
        LEFT JOIN pro_producto pr ON p.id_producto = pr.id
        LEFT JOIN ven_comprobante cv ON p.id_comprobante = cv.id
        LEFT JOIN gen_lista_opciones ea ON p.id_estado = ea.id
        WHERE p.id_alquiler = p_id_alquiler AND p.estado = 1
        ORDER BY p.numero_periodo DESC
        LIMIT p_limite
        OFFSET p_offset
    ) t;

    RETURN json_build_object('registros', v_registros, 'total', v_total);
END;
$$;


--
-- Name: bal_listar_alquileres(character varying, integer, integer, integer, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bal_listar_alquileres(p_busqueda character varying DEFAULT ''::character varying, p_limite integer DEFAULT 10, p_offset integer DEFAULT 0, p_id_cliente integer DEFAULT NULL::integer, p_id_almacen integer DEFAULT NULL::integer, p_id_estado integer DEFAULT NULL::integer) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_registros JSON;
    v_total BIGINT;
BEGIN
    SET TIME ZONE 'America/Lima';

    SELECT COUNT(*) INTO v_total
    FROM bal_alquiler al
    LEFT JOIN pro_producto pr ON al.id_producto_regulador = pr.id
    LEFT JOIN pro_producto ps ON al.id_producto_stock = ps.id
    WHERE al.estado = 1
      AND (p_id_cliente IS NULL OR al.id_cliente = p_id_cliente)
      AND (p_id_almacen IS NULL OR al.id_almacen = p_id_almacen)
      AND (p_id_estado IS NULL OR al.id_estado = p_id_estado)
      AND (
          p_busqueda = ''
          OR gen_texto_coincide(al.numero_alquiler, p_busqueda)
          OR gen_texto_coincide(COALESCE(al.observacion, ''), p_busqueda)
          OR gen_texto_coincide(COALESCE(pr.nombre, ''), p_busqueda)
          OR gen_texto_coincide(COALESCE(pr.codigo, ''), p_busqueda)
          OR gen_texto_coincide(COALESCE(ps.nombre, ''), p_busqueda)
          OR gen_texto_coincide(COALESCE(ps.codigo, ''), p_busqueda)
      );

    SELECT COALESCE(json_agg(row_to_json(t)), '[]'::JSON) INTO v_registros
    FROM (
        SELECT
            al.id,
            al.numero_alquiler,
            al.id_cliente,
            COALESCE(
                NULLIF(TRIM(c.razon_social), ''),
                NULLIF(TRIM(CONCAT_WS(' ', c.nombres, c.apellido_paterno, c.apellido_materno)), ''),
                c.numero_documento
            ) AS nombre_cliente,
            al.id_almacen,
            a.nombre AS nombre_almacen,
            al.fecha_inicio,
            al.fecha_fin_pactada,
            al.fecha_fin_real,
            al.tarifa_diaria,
            al.total_cobrado,
            al.id_estado,
            ea.nombre AS nombre_estado,
            al.id_comprobante_venta,
            CASE
                WHEN cv.id IS NULL THEN NULL
                ELSE CONCAT_WS('-', cv.serie, cv.numero)
            END AS comprobante_venta,
            al.id_producto_regulador,
            pr.codigo AS codigo_producto_regulador,
            pr.nombre AS nombre_producto_regulador,
            al.id_producto_stock,
            ps.codigo AS codigo_producto_stock,
            ps.nombre AS nombre_producto_stock,
            al.estado,
            al.fecha_creacion,
            (
                SELECT COUNT(*)::INTEGER
                FROM bal_alquiler_detalle ad
                WHERE ad.id_alquiler = al.id AND ad.estado = 1
            ) AS total_detalles,
            (
                al.id_comprobante_venta IS NULL
                AND NOT EXISTS (
                    SELECT 1 FROM bal_alquiler_detalle ad
                    WHERE ad.id_alquiler = al.id AND ad.estado = 1
                )
            ) AS puede_eliminar
        FROM bal_alquiler al
        INNER JOIN cli_clientes c ON al.id_cliente = c.id
        INNER JOIN gen_almacen a ON al.id_almacen = a.id
        LEFT JOIN gen_lista_opciones ea ON al.id_estado = ea.id
        LEFT JOIN ven_comprobante cv ON al.id_comprobante_venta = cv.id
        LEFT JOIN pro_producto pr ON al.id_producto_regulador = pr.id
        LEFT JOIN pro_producto ps ON al.id_producto_stock = ps.id
        WHERE al.estado = 1
          AND (p_id_cliente IS NULL OR al.id_cliente = p_id_cliente)
          AND (p_id_almacen IS NULL OR al.id_almacen = p_id_almacen)
          AND (p_id_estado IS NULL OR al.id_estado = p_id_estado)
          AND (
              p_busqueda = ''
              OR gen_texto_coincide(al.numero_alquiler, p_busqueda)
              OR gen_texto_coincide(COALESCE(al.observacion, ''), p_busqueda)
              OR gen_texto_coincide(COALESCE(pr.nombre, ''), p_busqueda)
              OR gen_texto_coincide(COALESCE(pr.codigo, ''), p_busqueda)
              OR gen_texto_coincide(COALESCE(ps.nombre, ''), p_busqueda)
              OR gen_texto_coincide(COALESCE(ps.codigo, ''), p_busqueda)
          )
        ORDER BY al.fecha_inicio DESC, al.id DESC
        LIMIT p_limite
        OFFSET p_offset
    ) t;

    RETURN json_build_object('registros', v_registros, 'total', v_total);
END;
$$;


--
-- Name: bal_listar_alquileres_por_vencer_notificar(integer, integer, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bal_listar_alquileres_por_vencer_notificar(p_dias_min integer DEFAULT 3, p_dias_max integer DEFAULT 7, p_fecha date DEFAULT NULL::date) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_fecha DATE;
    v_min INTEGER;
    v_max INTEGER;
    v_registros JSON;
BEGIN
    SET TIME ZONE 'America/Lima';
    v_fecha := COALESCE(p_fecha, CURRENT_DATE);
    v_min := GREATEST(COALESCE(p_dias_min, 3), 0);
    v_max := GREATEST(COALESCE(p_dias_max, 7), v_min);

    SELECT COALESCE(json_agg(t.row_data ORDER BY t.fecha_vencimiento, t.id), '[]'::JSON)
    INTO v_registros
    FROM (
        SELECT json_build_object(
            'id', a.id,
            'id_cliente', a.id_cliente,
            'nombre_cliente', COALESCE(c.razon_social, TRIM(CONCAT_WS(' ', c.nombres, c.apellido_paterno, c.apellido_materno))),
            'fecha_inicio', a.fecha_inicio,
            'fecha_fin_pactada', a.fecha_fin_pactada,
            'dias_periodo', a.dias_periodo,
            'fecha_vencimiento', COALESCE(per.fecha_fin, a.fecha_fin_pactada),
            'id_periodo', per.id,
            'numero_periodo', per.numero_periodo,
            'dias_para_vencer', (COALESCE(per.fecha_fin, a.fecha_fin_pactada) - v_fecha)
        ) AS row_data,
        a.id,
        COALESCE(per.fecha_fin, a.fecha_fin_pactada) AS fecha_vencimiento
        FROM bal_alquiler a
        LEFT JOIN gen_lista_opciones ea ON ea.id = a.id_estado
        LEFT JOIN cli_clientes c ON c.id = a.id_cliente
        LEFT JOIN LATERAL (
            SELECT p.id, p.numero_periodo, p.fecha_fin
            FROM bal_alquiler_periodo p
            WHERE p.id_alquiler = a.id
              AND p.estado = 1
            ORDER BY p.numero_periodo DESC, p.id DESC
            LIMIT 1
        ) per ON TRUE
        WHERE a.estado = 1
          AND COALESCE(ea.nombre, 'ACTIVO') = 'ACTIVO'
          AND COALESCE(per.fecha_fin, a.fecha_fin_pactada) IS NOT NULL
          AND COALESCE(per.fecha_fin, a.fecha_fin_pactada)
              BETWEEN (v_fecha + v_min) AND (v_fecha + v_max)
    ) t;

    RETURN json_build_object('registros', v_registros);
END;
$$;


--
-- Name: bal_listar_alquileres_vencidos_notificar(date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bal_listar_alquileres_vencidos_notificar(p_fecha date DEFAULT NULL::date) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_fecha DATE;
    v_registros JSON;
BEGIN
    SET TIME ZONE 'America/Lima';
    v_fecha := COALESCE(p_fecha, CURRENT_DATE);

    SELECT COALESCE(json_agg(t.row_data ORDER BY t.fecha_vencimiento, t.id), '[]'::JSON)
    INTO v_registros
    FROM (
        SELECT json_build_object(
            'id', a.id,
            'id_cliente', a.id_cliente,
            'nombre_cliente', COALESCE(c.razon_social, TRIM(CONCAT_WS(' ', c.nombres, c.apellido_paterno, c.apellido_materno))),
            'fecha_inicio', a.fecha_inicio,
            'fecha_fin_pactada', a.fecha_fin_pactada,
            'dias_periodo', a.dias_periodo,
            'fecha_vencimiento', COALESCE(per.fecha_fin, a.fecha_fin_pactada),
            'id_periodo', per.id,
            'numero_periodo', per.numero_periodo,
            'dias_vencido', (v_fecha - COALESCE(per.fecha_fin, a.fecha_fin_pactada))
        ) AS row_data,
        a.id,
        COALESCE(per.fecha_fin, a.fecha_fin_pactada) AS fecha_vencimiento
        FROM bal_alquiler a
        LEFT JOIN gen_lista_opciones ea ON ea.id = a.id_estado
        LEFT JOIN cli_clientes c ON c.id = a.id_cliente
        LEFT JOIN LATERAL (
            SELECT p.id, p.numero_periodo, p.fecha_fin
            FROM bal_alquiler_periodo p
            WHERE p.id_alquiler = a.id
              AND p.estado = 1
            ORDER BY p.numero_periodo DESC, p.id DESC
            LIMIT 1
        ) per ON TRUE
        WHERE a.estado = 1
          -- Sin id_estado: se trata como vigente (datos legacy / incompletos)
          AND COALESCE(ea.nombre, 'ACTIVO') = 'ACTIVO'
          AND COALESCE(per.fecha_fin, a.fecha_fin_pactada) IS NOT NULL
          AND COALESCE(per.fecha_fin, a.fecha_fin_pactada) < v_fecha
    ) t;

    RETURN json_build_object('registros', v_registros);
END;
$$;


--
-- Name: bal_listar_balones(character varying, integer, integer, integer, integer, integer, integer, integer, boolean, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bal_listar_balones(p_busqueda character varying DEFAULT ''::character varying, p_limite integer DEFAULT 10, p_offset integer DEFAULT 0, p_id_tipo_balon integer DEFAULT NULL::integer, p_id_almacen integer DEFAULT NULL::integer, p_id_estado_balon integer DEFAULT NULL::integer, p_id_cliente_ubicacion integer DEFAULT NULL::integer, p_id_marca_cilindro integer DEFAULT NULL::integer, p_ph_vencida boolean DEFAULT NULL::boolean, p_ph_por_vencer_dias integer DEFAULT NULL::integer) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_registros JSON;
    v_total BIGINT;
BEGIN
    SET TIME ZONE 'America/Lima';

    SELECT COUNT(*) INTO v_total
    FROM bal_balon b
    LEFT JOIN bal_tipo_balon tb ON b.id_tipo_balon = tb.id
    LEFT JOIN gen_almacen a ON b.id_almacen = a.id
    LEFT JOIN gen_lista_opciones eb ON b.id_estado_balon = eb.id
    LEFT JOIN gen_lista_opciones mc ON b.id_marca_cilindro = mc.id
    WHERE b.estado = 1
      AND (p_id_tipo_balon IS NULL OR b.id_tipo_balon = p_id_tipo_balon)
      AND (p_id_almacen IS NULL OR b.id_almacen = p_id_almacen)
      AND (p_id_estado_balon IS NULL OR b.id_estado_balon = p_id_estado_balon)
      AND (p_id_cliente_ubicacion IS NULL OR b.id_cliente_ubicacion = p_id_cliente_ubicacion)
      AND (p_id_marca_cilindro IS NULL OR b.id_marca_cilindro = p_id_marca_cilindro)
      AND (
          p_ph_vencida IS NULL
          OR (
              p_ph_vencida = TRUE
              AND b.fecha_proxima_prueba_hidrostatica IS NOT NULL
              AND b.fecha_proxima_prueba_hidrostatica < CURRENT_DATE
          )
          OR (
              p_ph_vencida = FALSE
              AND (
                  b.fecha_proxima_prueba_hidrostatica IS NULL
                  OR b.fecha_proxima_prueba_hidrostatica >= CURRENT_DATE
              )
          )
      )
      AND (
          p_ph_por_vencer_dias IS NULL
          OR (
              b.fecha_proxima_prueba_hidrostatica IS NOT NULL
              AND b.fecha_proxima_prueba_hidrostatica >= CURRENT_DATE
              AND b.fecha_proxima_prueba_hidrostatica <= CURRENT_DATE + make_interval(days => p_ph_por_vencer_dias)
          )
      )
      AND (
          p_busqueda = ''
          OR LOWER(b.codigo_balon) LIKE LOWER('%' || p_busqueda || '%')
          OR LOWER(COALESCE(b.numero_serie, '')) LIKE LOWER('%' || p_busqueda || '%')
          OR LOWER(COALESCE(b.libro_cilindro, '')) LIKE LOWER('%' || p_busqueda || '%')
          OR LOWER(COALESCE(tb.nombre, '')) LIKE LOWER('%' || p_busqueda || '%')
          OR LOWER(COALESCE(a.nombre, '')) LIKE LOWER('%' || p_busqueda || '%')
          OR LOWER(COALESCE(mc.nombre, '')) LIKE LOWER('%' || p_busqueda || '%')
      );

    SELECT COALESCE(json_agg(row_to_json(t)), '[]'::JSON) INTO v_registros
    FROM (
        SELECT
            b.id,
            b.codigo_balon,
            b.numero_serie,
            b.libro_cilindro,
            b.pagina_libro,
            b.fecha_registro,
            b.id_almacen,
            a.nombre AS nombre_almacen,
            b.id_cliente_ubicacion,
            b.id_tipo_balon,
            tb.nombre AS nombre_tipo_balon,
            b.id_producto_gas,
            pg.nombre AS nombre_producto_gas,
            b.id_estado_balon,
            eb.nombre AS nombre_estado_balon,
            b.id_marca_cilindro,
            mc.nombre AS nombre_marca_cilindro,
            b.anio_fabricacion,
            b.fecha_proxima_prueba_hidrostatica,
            CASE
                WHEN b.fecha_proxima_prueba_hidrostatica IS NULL THEN NULL
                WHEN b.fecha_proxima_prueba_hidrostatica < CURRENT_DATE THEN 'VENCIDA'
                WHEN b.fecha_proxima_prueba_hidrostatica <= CURRENT_DATE + INTERVAL '90 days' THEN 'POR_VENCER'
                ELSE 'VIGENTE'
            END AS estado_ph,
            b.presion_actual,
            EXISTS (
                SELECT 1
                FROM bal_baja_balon bb
                WHERE bb.id_balon = b.id
                  AND bb.estado = 1
                  AND bb.estado_aprobacion = 'PENDIENTE'
            ) AS tiene_solicitud_baja_pendiente,
            b.estado,
            b.fecha_creacion,
            b.fecha_modificacion
        FROM bal_balon b
        LEFT JOIN bal_tipo_balon tb ON b.id_tipo_balon = tb.id
        LEFT JOIN gen_almacen a ON b.id_almacen = a.id
        LEFT JOIN pro_producto pg ON b.id_producto_gas = pg.id
        LEFT JOIN gen_lista_opciones eb ON b.id_estado_balon = eb.id
        LEFT JOIN gen_lista_opciones mc ON b.id_marca_cilindro = mc.id
        WHERE b.estado = 1
          AND (p_id_tipo_balon IS NULL OR b.id_tipo_balon = p_id_tipo_balon)
          AND (p_id_almacen IS NULL OR b.id_almacen = p_id_almacen)
          AND (p_id_estado_balon IS NULL OR b.id_estado_balon = p_id_estado_balon)
          AND (p_id_cliente_ubicacion IS NULL OR b.id_cliente_ubicacion = p_id_cliente_ubicacion)
          AND (p_id_marca_cilindro IS NULL OR b.id_marca_cilindro = p_id_marca_cilindro)
          AND (
              p_ph_vencida IS NULL
              OR (
                  p_ph_vencida = TRUE
                  AND b.fecha_proxima_prueba_hidrostatica IS NOT NULL
                  AND b.fecha_proxima_prueba_hidrostatica < CURRENT_DATE
              )
              OR (
                  p_ph_vencida = FALSE
                  AND (
                      b.fecha_proxima_prueba_hidrostatica IS NULL
                      OR b.fecha_proxima_prueba_hidrostatica >= CURRENT_DATE
                  )
              )
          )
          AND (
              p_ph_por_vencer_dias IS NULL
              OR (
                  b.fecha_proxima_prueba_hidrostatica IS NOT NULL
                  AND b.fecha_proxima_prueba_hidrostatica >= CURRENT_DATE
                  AND b.fecha_proxima_prueba_hidrostatica <= CURRENT_DATE + make_interval(days => p_ph_por_vencer_dias)
              )
          )
          AND (
              p_busqueda = ''
              OR LOWER(b.codigo_balon) LIKE LOWER('%' || p_busqueda || '%')
              OR LOWER(COALESCE(b.numero_serie, '')) LIKE LOWER('%' || p_busqueda || '%')
              OR LOWER(COALESCE(b.libro_cilindro, '')) LIKE LOWER('%' || p_busqueda || '%')
              OR LOWER(COALESCE(tb.nombre, '')) LIKE LOWER('%' || p_busqueda || '%')
              OR LOWER(COALESCE(a.nombre, '')) LIKE LOWER('%' || p_busqueda || '%')
              OR LOWER(COALESCE(mc.nombre, '')) LIKE LOWER('%' || p_busqueda || '%')
          )
        ORDER BY b.codigo_balon ASC
        LIMIT p_limite
        OFFSET p_offset
    ) t;

    RETURN json_build_object('registros', v_registros, 'total', v_total);
END;
$$;


--
-- Name: bal_listar_balones(character varying, integer, integer, integer, integer, integer, integer, integer, boolean, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bal_listar_balones(p_busqueda character varying DEFAULT ''::character varying, p_limite integer DEFAULT 10, p_offset integer DEFAULT 0, p_id_tipo_balon integer DEFAULT NULL::integer, p_id_almacen integer DEFAULT NULL::integer, p_id_estado_balon integer DEFAULT NULL::integer, p_id_cliente_ubicacion integer DEFAULT NULL::integer, p_id_marca_cilindro integer DEFAULT NULL::integer, p_ph_vencida boolean DEFAULT NULL::boolean, p_ph_por_vencer_dias integer DEFAULT NULL::integer, p_id_cliente_relacionado integer DEFAULT NULL::integer) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_registros JSON;
    v_total BIGINT;
BEGIN
    SET TIME ZONE 'America/Lima';

    SELECT COUNT(*) INTO v_total
    FROM bal_balon b
    LEFT JOIN bal_tipo_balon tb ON b.id_tipo_balon = tb.id
    LEFT JOIN gen_almacen a ON b.id_almacen = a.id
    LEFT JOIN gen_lista_opciones eb ON b.id_estado_balon = eb.id
    LEFT JOIN gen_lista_opciones mc ON b.id_marca_cilindro = mc.id
    WHERE b.estado = 1
      AND (p_id_tipo_balon IS NULL OR b.id_tipo_balon = p_id_tipo_balon)
      AND (p_id_almacen IS NULL OR b.id_almacen = p_id_almacen)
      AND (p_id_estado_balon IS NULL OR b.id_estado_balon = p_id_estado_balon)
      AND (p_id_cliente_ubicacion IS NULL OR b.id_cliente_ubicacion = p_id_cliente_ubicacion)
      AND (p_id_marca_cilindro IS NULL OR b.id_marca_cilindro = p_id_marca_cilindro)
      AND (
          p_id_cliente_relacionado IS NULL
          OR b.id_cliente_ubicacion = p_id_cliente_relacionado
          OR b.id_cliente_propietario = p_id_cliente_relacionado
      )
      AND (
          p_id_cliente_relacionado IS NULL
          OR eb.nombre IS NULL
          OR eb.nombre NOT IN ('DADO_DE_BAJA', 'ROBO')
      )
      AND (
          p_ph_vencida IS NULL
          OR (
              p_ph_vencida = TRUE
              AND b.fecha_proxima_prueba_hidrostatica IS NOT NULL
              AND b.fecha_proxima_prueba_hidrostatica < CURRENT_DATE
          )
          OR (
              p_ph_vencida = FALSE
              AND (
                  b.fecha_proxima_prueba_hidrostatica IS NULL
                  OR b.fecha_proxima_prueba_hidrostatica >= CURRENT_DATE
              )
          )
      )
      AND (
          p_ph_por_vencer_dias IS NULL
          OR (
              b.fecha_proxima_prueba_hidrostatica IS NOT NULL
              AND b.fecha_proxima_prueba_hidrostatica >= CURRENT_DATE
              AND b.fecha_proxima_prueba_hidrostatica <= CURRENT_DATE + make_interval(days => p_ph_por_vencer_dias)
          )
      )
      AND (
          p_busqueda = ''
          OR LOWER(b.codigo_balon) LIKE LOWER('%' || p_busqueda || '%')
          OR LOWER(COALESCE(b.numero_serie, '')) LIKE LOWER('%' || p_busqueda || '%')
          OR LOWER(COALESCE(b.libro_cilindro, '')) LIKE LOWER('%' || p_busqueda || '%')
          OR LOWER(COALESCE(tb.nombre, '')) LIKE LOWER('%' || p_busqueda || '%')
          OR LOWER(COALESCE(a.nombre, '')) LIKE LOWER('%' || p_busqueda || '%')
          OR LOWER(COALESCE(mc.nombre, '')) LIKE LOWER('%' || p_busqueda || '%')
      );

    SELECT COALESCE(json_agg(row_to_json(t)), '[]'::JSON) INTO v_registros
    FROM (
        SELECT
            b.id,
            b.codigo_balon,
            b.numero_serie,
            b.libro_cilindro,
            b.pagina_libro,
            b.fecha_registro,
            b.id_almacen,
            a.nombre AS nombre_almacen,
            b.id_cliente_ubicacion,
            b.id_propietario,
            prop.nombre AS nombre_propietario,
            b.id_cliente_propietario,
            b.id_tipo_balon,
            tb.nombre AS nombre_tipo_balon,
            b.id_producto_gas,
            pg.nombre AS nombre_producto_gas,
            b.id_estado_balon,
            eb.nombre AS nombre_estado_balon,
            b.id_marca_cilindro,
            mc.nombre AS nombre_marca_cilindro,
            b.anio_fabricacion,
            b.fecha_proxima_prueba_hidrostatica,
            CASE
                WHEN b.fecha_proxima_prueba_hidrostatica IS NULL THEN NULL
                WHEN b.fecha_proxima_prueba_hidrostatica < CURRENT_DATE THEN 'VENCIDA'
                WHEN b.fecha_proxima_prueba_hidrostatica <= CURRENT_DATE + INTERVAL '90 days' THEN 'POR_VENCER'
                ELSE 'VIGENTE'
            END AS estado_ph,
            b.presion_actual,
            EXISTS (
                SELECT 1
