                WHERE bb.id_balon = b.id
                  AND bb.estado = 1
                  AND bb.estado_aprobacion = 'PENDIENTE'
            ) AS tiene_solicitud_baja_pendiente,
            b.estado,
            b.fecha_creacion,
            b.fecha_modificacion
        FROM bal_balon b
        LEFT JOIN bal_tipo_balon tb ON b.id_tipo_balon = tb.id
        LEFT JOIN gen_almacen a ON b.id_almacen = a.id
        LEFT JOIN pro_producto pg ON b.id_producto_gas = pg.id
        LEFT JOIN gen_lista_opciones eb ON b.id_estado_balon = eb.id
        LEFT JOIN gen_lista_opciones mc ON b.id_marca_cilindro = mc.id
        LEFT JOIN gen_lista_opciones prop ON b.id_propietario = prop.id
        WHERE b.estado = 1
          AND (p_id_tipo_balon IS NULL OR b.id_tipo_balon = p_id_tipo_balon)
          AND (p_id_almacen IS NULL OR b.id_almacen = p_id_almacen)
          AND (p_id_estado_balon IS NULL OR b.id_estado_balon = p_id_estado_balon)
          AND (p_id_cliente_ubicacion IS NULL OR b.id_cliente_ubicacion = p_id_cliente_ubicacion)
          AND (p_id_marca_cilindro IS NULL OR b.id_marca_cilindro = p_id_marca_cilindro)
          AND (
              p_id_cliente_relacionado IS NULL
              OR b.id_cliente_ubicacion = p_id_cliente_relacionado
              OR b.id_cliente_propietario = p_id_cliente_relacionado
          )
          AND (
              p_id_cliente_relacionado IS NULL
              OR eb.nombre IS NULL
              OR eb.nombre NOT IN ('DADO_DE_BAJA', 'ROBO')
          )
          AND (
              p_ph_vencida IS NULL
              OR (
                  p_ph_vencida = TRUE
                  AND b.fecha_proxima_prueba_hidrostatica IS NOT NULL
                  AND b.fecha_proxima_prueba_hidrostatica < CURRENT_DATE
              )
              OR (
                  p_ph_vencida = FALSE
                  AND (
                      b.fecha_proxima_prueba_hidrostatica IS NULL
                      OR b.fecha_proxima_prueba_hidrostatica >= CURRENT_DATE
                  )
              )
          )
          AND (
              p_ph_por_vencer_dias IS NULL
              OR (
                  b.fecha_proxima_prueba_hidrostatica IS NOT NULL
                  AND b.fecha_proxima_prueba_hidrostatica >= CURRENT_DATE
                  AND b.fecha_proxima_prueba_hidrostatica <= CURRENT_DATE + make_interval(days => p_ph_por_vencer_dias)
              )
          )
          AND (
              p_busqueda = ''
              OR LOWER(b.codigo_balon) LIKE LOWER('%' || p_busqueda || '%')
              OR LOWER(COALESCE(b.numero_serie, '')) LIKE LOWER('%' || p_busqueda || '%')
              OR LOWER(COALESCE(b.libro_cilindro, '')) LIKE LOWER('%' || p_busqueda || '%')
              OR LOWER(COALESCE(tb.nombre, '')) LIKE LOWER('%' || p_busqueda || '%')
              OR LOWER(COALESCE(a.nombre, '')) LIKE LOWER('%' || p_busqueda || '%')
              OR LOWER(COALESCE(mc.nombre, '')) LIKE LOWER('%' || p_busqueda || '%')
          )
        ORDER BY b.codigo_balon ASC
        LIMIT p_limite
        OFFSET p_offset
    ) t;

    RETURN json_build_object('registros', v_registros, 'total', v_total);
END;
$$;


--
-- Name: bal_listar_balones(character varying, integer, integer, integer, integer, integer, integer, integer, boolean, integer, integer, boolean, character varying, integer, integer, boolean, integer, character varying); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bal_listar_balones(p_busqueda character varying DEFAULT ''::character varying, p_limite integer DEFAULT 10, p_offset integer DEFAULT 0, p_id_tipo_balon integer DEFAULT NULL::integer, p_id_almacen integer DEFAULT NULL::integer, p_id_estado_balon integer DEFAULT NULL::integer, p_id_cliente_ubicacion integer DEFAULT NULL::integer, p_id_marca_cilindro integer DEFAULT NULL::integer, p_ph_vencida boolean DEFAULT NULL::boolean, p_ph_por_vencer_dias integer DEFAULT NULL::integer, p_id_cliente_relacionado integer DEFAULT NULL::integer, p_solo_bajas boolean DEFAULT NULL::boolean, p_familia_gas character varying DEFAULT NULL::character varying, p_id_propietario integer DEFAULT NULL::integer, p_id_producto_gas integer DEFAULT NULL::integer, p_solo_llenos_fuera boolean DEFAULT NULL::boolean, p_id_planta integer DEFAULT NULL::integer, p_tipo_valvula character varying DEFAULT NULL::character varying) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_registros JSON;
    v_total BIGINT;
    v_alertas JSON;
    v_resumen JSON;
    v_familia_gas VARCHAR;
BEGIN
    SET TIME ZONE 'America/Lima';

    v_familia_gas := NULLIF(TRIM(COALESCE(p_familia_gas, '')), '');

    SELECT
        COUNT(*),
        json_build_object(
            'total', COUNT(*),
            'en_almacen', COUNT(*) FILTER (WHERE eb.nombre = 'EN_ALMACEN'),
            'llenos', COUNT(*) FILTER (WHERE eb.nombre = 'EN_ALMACEN'),
            'vacios', COUNT(*) FILTER (WHERE eb.nombre = 'EN_ALMACEN')
        )
    INTO v_total, v_resumen
    FROM bal_balon b
    LEFT JOIN bal_tipo_balon tb ON b.id_tipo_balon = tb.id
    LEFT JOIN pro_producto pg ON b.id_producto_gas = pg.id
    LEFT JOIN gen_almacen a ON b.id_almacen = a.id
    LEFT JOIN gen_lista_opciones eb ON b.id_estado_balon = eb.id
    LEFT JOIN gen_lista_opciones mc ON b.id_marca_cilindro = mc.id
    LEFT JOIN cli_clientes cu ON b.id_cliente_ubicacion = cu.id
    LEFT JOIN cli_clientes cp ON b.id_cliente_propietario = cp.id
    WHERE b.estado = 1
      AND (p_id_tipo_balon IS NULL OR b.id_tipo_balon = p_id_tipo_balon)
      AND (p_id_almacen IS NULL OR b.id_almacen = p_id_almacen)
      AND (p_id_estado_balon IS NULL OR b.id_estado_balon = p_id_estado_balon)
      AND (p_id_producto_gas IS NULL OR b.id_producto_gas = p_id_producto_gas)
      AND (p_id_cliente_ubicacion IS NULL OR b.id_cliente_ubicacion = p_id_cliente_ubicacion)
      AND (p_id_marca_cilindro IS NULL OR b.id_marca_cilindro = p_id_marca_cilindro)
      AND (p_id_propietario IS NULL OR b.id_propietario = p_id_propietario)
      AND (
          p_id_cliente_relacionado IS NULL
          OR b.id_cliente_ubicacion = p_id_cliente_relacionado
          OR b.id_cliente_propietario = p_id_cliente_relacionado
      )
      AND (
          p_id_cliente_relacionado IS NULL
          OR eb.nombre IS NULL
          OR eb.nombre NOT IN ('DADO_DE_BAJA', 'ROBO')
      )
      AND (
          p_solo_bajas IS NULL
          OR (
              p_solo_bajas = TRUE
              AND eb.nombre IN ('DADO_DE_BAJA', 'ROBO')
          )
          OR (
              p_solo_bajas = FALSE
              AND (eb.nombre IS NULL OR eb.nombre NOT IN ('DADO_DE_BAJA', 'ROBO'))
          )
      )
      AND (
          p_solo_llenos_fuera IS NOT TRUE
          OR (
              COALESCE(eb.nombre, '') IS DISTINCT FROM 'EN_ALMACEN'
              AND COALESCE(eb.nombre, '') NOT IN ('DADO_DE_BAJA', 'ROBO')
          )
      )
      AND (
          p_ph_vencida IS NULL
          OR (
              p_ph_vencida = TRUE
              AND b.fecha_proxima_prueba_hidrostatica IS NOT NULL
              AND b.fecha_proxima_prueba_hidrostatica < CURRENT_DATE
          )
          OR (
              p_ph_vencida = FALSE
              AND (
                  b.fecha_proxima_prueba_hidrostatica IS NULL
                  OR b.fecha_proxima_prueba_hidrostatica >= CURRENT_DATE
              )
          )
      )
      AND (
          p_ph_por_vencer_dias IS NULL
          OR (
              b.fecha_proxima_prueba_hidrostatica IS NOT NULL
              AND b.fecha_proxima_prueba_hidrostatica >= CURRENT_DATE
              AND b.fecha_proxima_prueba_hidrostatica <= CURRENT_DATE + make_interval(days => p_ph_por_vencer_dias)
          )
      )
      AND (
          v_familia_gas IS NULL
          OR gen_texto_coincide(COALESCE(tb.nombre, ''), v_familia_gas)
          OR gen_texto_coincide(COALESCE(pg.nombre, ''), v_familia_gas)
          OR gen_texto_coincide(COALESCE(pg.codigo, ''), v_familia_gas)
      )
      AND (p_id_planta IS NULL OR b.id_planta = p_id_planta)
      AND (
          p_tipo_valvula IS NULL
          OR b.tipo_valvula ILIKE '%' || TRIM(p_tipo_valvula) || '%'
      )
      AND (
          p_busqueda = ''
          OR gen_texto_coincide(b.codigo_balon, p_busqueda)
          OR gen_texto_coincide(COALESCE(b.numero_serie, ''), p_busqueda)
          OR gen_texto_coincide(COALESCE(b.libro_cilindro, ''), p_busqueda)
          OR gen_texto_coincide(COALESCE(tb.nombre, ''), p_busqueda)
          OR gen_texto_coincide(COALESCE(pg.nombre, ''), p_busqueda)
          OR gen_texto_coincide(COALESCE(pg.codigo, ''), p_busqueda)
          OR gen_texto_coincide(COALESCE(a.nombre, ''), p_busqueda)
          OR gen_texto_coincide(COALESCE(mc.nombre, ''), p_busqueda)
          OR gen_texto_coincide(COALESCE(cu.razon_social, ''), p_busqueda)
          OR gen_texto_coincide(COALESCE(cu.nombres, ''), p_busqueda)
          OR gen_texto_coincide(COALESCE(cu.numero_documento, ''), p_busqueda)
          OR gen_texto_coincide(COALESCE(cp.razon_social, ''), p_busqueda)
          OR gen_texto_coincide(COALESCE(cp.nombres, ''), p_busqueda)
          OR gen_texto_coincide(COALESCE(cp.numero_documento, ''), p_busqueda)
      );

    SELECT COALESCE(json_agg(row_to_json(t)), '[]'::JSON) INTO v_registros
    FROM (
        SELECT
            b.id,
            b.codigo_balon,
            b.numero_serie,
            b.libro_cilindro,
            b.pagina_libro,
            b.fecha_registro,
            b.id_almacen,
            a.nombre AS nombre_almacen,
            b.id_cliente_ubicacion,
            COALESCE(
                NULLIF(TRIM(cu.razon_social), ''),
                NULLIF(TRIM(CONCAT_WS(' ', cu.nombres, cu.apellido_paterno, cu.apellido_materno)), ''),
                cu.numero_documento
            ) AS nombre_cliente_ubicacion,
            b.id_propietario,
            prop.nombre AS nombre_propietario,
            b.id_cliente_propietario,
            COALESCE(
                NULLIF(TRIM(cp.razon_social), ''),
                NULLIF(TRIM(CONCAT_WS(' ', cp.nombres, cp.apellido_paterno, cp.apellido_materno)), ''),
                cp.numero_documento
            ) AS nombre_cliente_propietario,
            b.id_tipo_balon,
            tb.nombre AS nombre_tipo_balon,
            tb.capacidad,
            tb.capacidad_lb,
            tb.peso AS peso_tipo_balon,
            b.peso_aproximado_kg,
            COALESCE(b.peso_aproximado_kg, tb.peso) AS peso_guia_kg,
            b.sello_inspeccion,
            um.nombre AS nombre_unidad_medida,
            b.id_producto_gas,
            pg.nombre AS nombre_producto_gas,
            b.id_estado_balon,
            eb.nombre AS nombre_estado_balon,
            b.id_marca_cilindro,
            mc.nombre AS nombre_marca_cilindro,
            b.id_organo_inspector,
            oi.nombre AS nombre_organo_inspector,
            b.organo_inspector_no_aplica,
            b.id_planta,
            COALESCE(pl.razon_social, TRIM(CONCAT_WS(' ', pl.nombres, pl.apellido_paterno))) AS nombre_planta,
            b.anio_fabricacion,
            b.mes_fabricacion,
            b.fecha_proxima_prueba_hidrostatica,
            CASE
                WHEN b.fecha_proxima_prueba_hidrostatica IS NULL THEN NULL
                WHEN b.fecha_proxima_prueba_hidrostatica < CURRENT_DATE THEN 'VENCIDA'
                WHEN b.fecha_proxima_prueba_hidrostatica <= CURRENT_DATE + INTERVAL '90 days' THEN 'POR_VENCER'
                ELSE 'VIGENTE'
            END AS estado_ph,
            b.presion_actual,
            b.tipo_valvula,
            EXISTS (
                SELECT 1
                FROM bal_baja_balon bb
                WHERE bb.id_balon = b.id
                  AND bb.estado = 1
                  AND bb.estado_aprobacion = 'PENDIENTE'
            ) AS tiene_solicitud_baja_pendiente,
            EXISTS (
                SELECT 1
                FROM bal_baja_balon bb
                WHERE bb.id_balon = b.id
                  AND bb.estado = 1
                  AND bb.estado_aprobacion = 'APROBADA'
            ) AS tiene_baja_aprobada,
            NOT (
                COALESCE(eb.nombre, '') IN ('DADO_DE_BAJA', 'ROBO')
                OR EXISTS (
                    SELECT 1 FROM bal_baja_balon bb
                    WHERE bb.id_balon = b.id AND bb.estado = 1
                      AND bb.estado_aprobacion IN ('PENDIENTE', 'APROBADA')
                )
                OR EXISTS (SELECT 1 FROM inv_movimiento m WHERE m.id_balon = b.id AND m.estado = 1)
                OR EXISTS (SELECT 1 FROM bal_movimiento_recarga mr WHERE mr.id_balon = b.id AND mr.estado = 1)
                OR EXISTS (SELECT 1 FROM bal_prestamo_detalle pd WHERE pd.id_balon = b.id AND pd.estado = 1)
                OR EXISTS (SELECT 1 FROM bal_alquiler_detalle ad WHERE ad.id_balon = b.id AND ad.estado = 1)
                OR EXISTS (SELECT 1 FROM bal_mantenimiento mt WHERE mt.id_balon = b.id AND mt.estado = 1)
                OR EXISTS (SELECT 1 FROM bal_balon_ph_historial ph WHERE ph.id_balon = b.id AND ph.estado = 1)
                OR EXISTS (SELECT 1 FROM bal_balon_estado_historial eh WHERE eh.id_balon = b.id AND eh.estado = 1)
                OR EXISTS (SELECT 1 FROM ven_comprobante_detalle vd WHERE vd.id_balon = b.id AND vd.estado = 1)
                OR EXISTS (SELECT 1 FROM gre_guia_remision_detalle gd WHERE gd.id_balon = b.id AND gd.estado = 1)
            ) AS puede_eliminar,
            b.estado,
            b.fecha_creacion,
            b.fecha_modificacion
        FROM bal_balon b
        LEFT JOIN bal_tipo_balon tb ON b.id_tipo_balon = tb.id
        LEFT JOIN gen_lista_opciones um ON tb.id_unidad_medida = um.id
        LEFT JOIN gen_almacen a ON b.id_almacen = a.id
        LEFT JOIN pro_producto pg ON b.id_producto_gas = pg.id
        LEFT JOIN gen_lista_opciones eb ON b.id_estado_balon = eb.id
        LEFT JOIN gen_lista_opciones mc ON b.id_marca_cilindro = mc.id
        LEFT JOIN gen_lista_opciones oi ON b.id_organo_inspector = oi.id
        LEFT JOIN gen_lista_opciones prop ON b.id_propietario = prop.id
        LEFT JOIN cli_clientes cu ON b.id_cliente_ubicacion = cu.id
        LEFT JOIN cli_clientes cp ON b.id_cliente_propietario = cp.id
        LEFT JOIN cli_clientes pl ON b.id_planta = pl.id
        WHERE b.estado = 1
          AND (p_id_tipo_balon IS NULL OR b.id_tipo_balon = p_id_tipo_balon)
          AND (p_id_almacen IS NULL OR b.id_almacen = p_id_almacen)
          AND (p_id_estado_balon IS NULL OR b.id_estado_balon = p_id_estado_balon)
          AND (p_id_producto_gas IS NULL OR b.id_producto_gas = p_id_producto_gas)
          AND (p_id_cliente_ubicacion IS NULL OR b.id_cliente_ubicacion = p_id_cliente_ubicacion)
          AND (p_id_marca_cilindro IS NULL OR b.id_marca_cilindro = p_id_marca_cilindro)
          AND (p_id_propietario IS NULL OR b.id_propietario = p_id_propietario)
          AND (
              p_id_cliente_relacionado IS NULL
              OR b.id_cliente_ubicacion = p_id_cliente_relacionado
              OR b.id_cliente_propietario = p_id_cliente_relacionado
          )
          AND (
              p_id_cliente_relacionado IS NULL
              OR eb.nombre IS NULL
              OR eb.nombre NOT IN ('DADO_DE_BAJA', 'ROBO')
          )
          AND (
              p_solo_bajas IS NULL
              OR (
                  p_solo_bajas = TRUE
                  AND eb.nombre IN ('DADO_DE_BAJA', 'ROBO')
              )
              OR (
                  p_solo_bajas = FALSE
                  AND (eb.nombre IS NULL OR eb.nombre NOT IN ('DADO_DE_BAJA', 'ROBO'))
              )
          )
          AND (
              p_solo_llenos_fuera IS NOT TRUE
              OR (
                  COALESCE(eb.nombre, '') IS DISTINCT FROM 'EN_ALMACEN'
                  AND COALESCE(eb.nombre, '') NOT IN ('DADO_DE_BAJA', 'ROBO')
              )
          )
          AND (
              p_ph_vencida IS NULL
              OR (
                  p_ph_vencida = TRUE
                  AND b.fecha_proxima_prueba_hidrostatica IS NOT NULL
                  AND b.fecha_proxima_prueba_hidrostatica < CURRENT_DATE
              )
              OR (
                  p_ph_vencida = FALSE
                  AND (
                      b.fecha_proxima_prueba_hidrostatica IS NULL
                      OR b.fecha_proxima_prueba_hidrostatica >= CURRENT_DATE
                  )
              )
          )
          AND (
              p_ph_por_vencer_dias IS NULL
              OR (
                  b.fecha_proxima_prueba_hidrostatica IS NOT NULL
                  AND b.fecha_proxima_prueba_hidrostatica >= CURRENT_DATE
                  AND b.fecha_proxima_prueba_hidrostatica <= CURRENT_DATE + make_interval(days => p_ph_por_vencer_dias)
              )
          )
          AND (
              v_familia_gas IS NULL
              OR gen_texto_coincide(COALESCE(tb.nombre, ''), v_familia_gas)
              OR gen_texto_coincide(COALESCE(pg.nombre, ''), v_familia_gas)
              OR gen_texto_coincide(COALESCE(pg.codigo, ''), v_familia_gas)
          )
          AND (p_id_planta IS NULL OR b.id_planta = p_id_planta)
          AND (
              p_tipo_valvula IS NULL
              OR b.tipo_valvula ILIKE '%' || TRIM(p_tipo_valvula) || '%'
          )
          AND (
              p_busqueda = ''
              OR gen_texto_coincide(b.codigo_balon, p_busqueda)
              OR gen_texto_coincide(COALESCE(b.numero_serie, ''), p_busqueda)
              OR gen_texto_coincide(COALESCE(b.libro_cilindro, ''), p_busqueda)
              OR gen_texto_coincide(COALESCE(tb.nombre, ''), p_busqueda)
              OR gen_texto_coincide(COALESCE(pg.nombre, ''), p_busqueda)
              OR gen_texto_coincide(COALESCE(pg.codigo, ''), p_busqueda)
              OR gen_texto_coincide(COALESCE(a.nombre, ''), p_busqueda)
              OR gen_texto_coincide(COALESCE(mc.nombre, ''), p_busqueda)
              OR gen_texto_coincide(COALESCE(cu.razon_social, ''), p_busqueda)
              OR gen_texto_coincide(COALESCE(cu.nombres, ''), p_busqueda)
              OR gen_texto_coincide(COALESCE(cu.numero_documento, ''), p_busqueda)
              OR gen_texto_coincide(COALESCE(cp.razon_social, ''), p_busqueda)
              OR gen_texto_coincide(COALESCE(cp.nombres, ''), p_busqueda)
              OR gen_texto_coincide(COALESCE(cp.numero_documento, ''), p_busqueda)
          )
        ORDER BY b.fecha_creacion DESC NULLS LAST, b.id DESC
        LIMIT p_limite
        OFFSET p_offset
    ) t;

    SELECT json_build_object(
        'ph_por_vencer_90', COUNT(*) FILTER (
            WHERE b.fecha_proxima_prueba_hidrostatica IS NOT NULL
              AND b.fecha_proxima_prueba_hidrostatica >= CURRENT_DATE
              AND b.fecha_proxima_prueba_hidrostatica <= CURRENT_DATE + INTERVAL '90 days'
              AND (eb.nombre IS NULL OR eb.nombre NOT IN ('DADO_DE_BAJA', 'ROBO'))
        ),
        'ph_vencida', COUNT(*) FILTER (
            WHERE b.fecha_proxima_prueba_hidrostatica IS NOT NULL
              AND b.fecha_proxima_prueba_hidrostatica < CURRENT_DATE
              AND (eb.nombre IS NULL OR eb.nombre NOT IN ('DADO_DE_BAJA', 'ROBO'))
        ),
        'dados_de_baja', COUNT(*) FILTER (
            WHERE eb.nombre IN ('DADO_DE_BAJA', 'ROBO')
        )
    )
    INTO v_alertas
    FROM bal_balon b
    LEFT JOIN gen_lista_opciones eb ON b.id_estado_balon = eb.id
    WHERE b.estado = 1;

    RETURN json_build_object(
        'registros', v_registros,
        'total', v_total,
        'alertas', v_alertas,
        'resumen', v_resumen
    );
END;
$$;


--
-- Name: bal_listar_balones_origen_recarga(integer, numeric, integer, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bal_listar_balones_origen_recarga(p_id_producto_gas integer, p_capacidad_requerida numeric DEFAULT NULL::numeric, p_id_almacen integer DEFAULT NULL::integer, p_limite integer DEFAULT 50, p_offset integer DEFAULT 0) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_registros JSON;
    v_total BIGINT;
BEGIN
    SET TIME ZONE 'America/Lima';

    IF p_id_producto_gas IS NULL THEN
        RETURN json_build_object(
            'error', 'El producto gas es obligatorio',
            'registros', '[]'::JSON,
            'total', 0
        );
    END IF;

    WITH candidatos AS (
        SELECT
            b.id,
            b.codigo_balon,
            b.numero_serie,
            b.id_almacen,
            a.nombre AS nombre_almacen,
            b.id_producto_gas,
            p.nombre AS nombre_producto,
            b.id_tipo_balon,
            tb.nombre AS nombre_tipo_balon,
            tb.capacidad AS capacidad_tipo,
            bal_capacidad_disponible_balon(b.id) AS capacidad_disponible,
            b.fecha_creacion
        FROM bal_balon b
        LEFT JOIN bal_tipo_balon tb ON tb.id = b.id_tipo_balon
        LEFT JOIN gen_almacen a ON a.id = b.id_almacen
        LEFT JOIN pro_producto p ON p.id = b.id_producto_gas
        LEFT JOIN gen_lista_opciones prop ON prop.id = b.id_propietario
        LEFT JOIN gen_lista_opciones eb ON eb.id = b.id_estado_balon
        WHERE b.estado = 1
          AND COALESCE(prop.nombre, '') IN ('EMPRESA', 'PROPIA')
          AND COALESCE(eb.nombre, '') = 'EN_ALMACEN'
          AND b.id_producto_gas = p_id_producto_gas
          AND (p_id_almacen IS NULL OR b.id_almacen = p_id_almacen)
          AND bal_capacidad_disponible_balon(b.id) > 0
    )
    SELECT
        (SELECT COUNT(*) FROM candidatos),
        (
            SELECT COALESCE(json_agg(row_to_json(t)), '[]'::JSON)
            FROM (
                SELECT
                    id,
                    codigo_balon,
                    numero_serie,
                    id_almacen,
                    nombre_almacen,
                    id_producto_gas,
                    nombre_producto,
                    id_tipo_balon,
                    nombre_tipo_balon,
                    capacidad_tipo,
                    capacidad_disponible,
                    fecha_creacion
                FROM candidatos
                ORDER BY fecha_creacion ASC NULLS LAST, id ASC
                LIMIT GREATEST(COALESCE(p_limite, 50), 1)
                OFFSET GREATEST(COALESCE(p_offset, 0), 0)
            ) t
        )
    INTO v_total, v_registros;

    RETURN json_build_object(
        'registros', v_registros,
        'total', v_total
    );
END;
$$;


--
-- Name: bal_listar_estado_historial(integer, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bal_listar_estado_historial(p_id_balon integer, p_limite integer DEFAULT 50, p_offset integer DEFAULT 0) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_registros JSON;
    v_total BIGINT;
BEGIN
    SET TIME ZONE 'America/Lima';

    IF NOT EXISTS (SELECT 1 FROM bal_balon WHERE id = p_id_balon AND estado = 1) THEN
        RETURN json_build_object('error', 'El balón indicado no existe o está inactivo', 'registros', '[]'::JSON, 'total', 0);
    END IF;

    SELECT COUNT(*) INTO v_total
    FROM bal_balon_estado_historial h
    WHERE h.id_balon = p_id_balon AND h.estado = 1;

    SELECT COALESCE(json_agg(row_to_json(t)), '[]'::JSON) INTO v_registros
    FROM (
        SELECT
            h.id,
            h.id_balon,
            h.tipo_evento,
            CASE h.tipo_evento
                WHEN 'SOLICITUD_BAJA' THEN 'Solicitud de baja'
                WHEN 'BAJA_APROBADA' THEN 'Baja aprobada'
                WHEN 'BAJA_RECHAZADA' THEN 'Baja rechazada'
                WHEN 'REACTIVACION' THEN 'Reactivación'
                ELSE h.tipo_evento
            END AS nombre_tipo_evento,
            h.id_baja,
            h.id_motivo_baja,
            mb.nombre AS nombre_motivo_baja,
            h.id_estado_anterior,
            ea.nombre AS nombre_estado_anterior,
            h.id_estado_nuevo,
            en.nombre AS nombre_estado_nuevo,
            h.observacion,
            h.id_usuario,
            u.nombre AS nombre_usuario,
            h.fecha_evento,
            h.fecha_creacion
        FROM bal_balon_estado_historial h
        LEFT JOIN gen_lista_opciones mb ON h.id_motivo_baja = mb.id
        LEFT JOIN gen_lista_opciones ea ON h.id_estado_anterior = ea.id
        LEFT JOIN gen_lista_opciones en ON h.id_estado_nuevo = en.id
        LEFT JOIN auth_usuarios u ON h.id_usuario = u.id
        WHERE h.id_balon = p_id_balon AND h.estado = 1
        ORDER BY h.fecha_evento DESC, h.id DESC
        LIMIT p_limite
        OFFSET p_offset
    ) t;

    RETURN json_build_object('registros', v_registros, 'total', v_total);
END;
$$;


--
-- Name: bal_listar_mantenimientos(character varying, integer, integer, integer, integer, integer, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bal_listar_mantenimientos(p_busqueda character varying DEFAULT ''::character varying, p_limite integer DEFAULT 10, p_offset integer DEFAULT 0, p_id_balon integer DEFAULT NULL::integer, p_id_tipo_mantenimiento integer DEFAULT NULL::integer, p_id_estado integer DEFAULT NULL::integer, p_es_externo boolean DEFAULT NULL::boolean) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_registros JSON;
    v_total BIGINT;
BEGIN
    SET TIME ZONE 'America/Lima';

    SELECT COUNT(*) INTO v_total
    FROM bal_mantenimiento m
    LEFT JOIN bal_balon b ON m.id_balon = b.id
    LEFT JOIN pro_producto p ON p.id = m.id_producto
    WHERE m.estado = 1
      AND (p_id_balon IS NULL OR m.id_balon = p_id_balon)
      AND (p_id_tipo_mantenimiento IS NULL OR m.id_tipo_mantenimiento = p_id_tipo_mantenimiento)
      AND (p_id_estado IS NULL OR m.id_estado = p_id_estado)
      AND (p_es_externo IS NULL OR m.es_externo = p_es_externo)
      AND (
          p_busqueda = ''
          OR gen_texto_coincide(COALESCE(b.codigo_balon, ''), p_busqueda)
          OR gen_texto_coincide(COALESCE(p.codigo, ''), p_busqueda)
          OR gen_texto_coincide(COALESCE(p.nombre, ''), p_busqueda)
          OR gen_texto_coincide(COALESCE(m.descripcion, ''), p_busqueda)
      );

    SELECT COALESCE(json_agg(row_to_json(t)), '[]'::JSON) INTO v_registros
    FROM (
        SELECT
            m.id,
            m.id_balon,
            b.codigo_balon,
            m.id_producto,
            p.codigo AS codigo_producto,
            p.nombre AS nombre_producto,
            CASE
                WHEN m.id_producto IS NOT NULL THEN 'PRODUCTO'
                ELSE 'CILINDRO'
            END AS tipo_origen,
            b.id_propietario,
            prop.nombre AS nombre_propietario,
            b.id_cliente_propietario,
            COALESCE(
                NULLIF(TRIM(cp.razon_social), ''),
                NULLIF(
                    TRIM(CONCAT_WS(' ', cp.nombres, cp.apellido_paterno, cp.apellido_materno)),
                    ''
                ),
                cp.numero_documento
            ) AS nombre_cliente_propietario,
            b.id_cliente_ubicacion,
            m.id_tipo_mantenimiento,
            tm.nombre AS nombre_tipo_mantenimiento,
            m.fecha_ingreso,
            m.fecha_salida,
            m.descripcion,
            m.costo,
            m.es_externo,
            m.id_estado,
            em.nombre AS nombre_estado,
            m.id_comprobante_venta,
            CASE
                WHEN cv.id IS NULL THEN NULL
                ELSE CONCAT_WS('-', cv.serie, cv.numero)
            END AS comprobante_venta,
            m.id_comprobante_compra,
            CASE
                WHEN cc.id IS NULL THEN NULL
                ELSE CONCAT_WS('-', cc.serie, cc.numero)
            END AS comprobante_compra,
            m.id_alquiler,
            m.id_recojo,
            m.estado,
            m.fecha_creacion,
            (
                m.id_comprobante_venta IS NULL
                AND m.id_comprobante_compra IS NULL
                AND NOT EXISTS (
                    SELECT 1 FROM bal_balon_ph_historial ph
                    WHERE ph.id_mantenimiento = m.id AND ph.estado = 1
                )
            ) AS puede_eliminar
        FROM bal_mantenimiento m
        LEFT JOIN bal_balon b ON m.id_balon = b.id
        LEFT JOIN pro_producto p ON p.id = m.id_producto
        LEFT JOIN gen_lista_opciones prop ON b.id_propietario = prop.id
        LEFT JOIN cli_clientes cp ON b.id_cliente_propietario = cp.id
        LEFT JOIN gen_lista_opciones tm ON m.id_tipo_mantenimiento = tm.id
        LEFT JOIN gen_lista_opciones em ON m.id_estado = em.id
        LEFT JOIN ven_comprobante cv ON m.id_comprobante_venta = cv.id
        LEFT JOIN com_comprobante_compra cc ON m.id_comprobante_compra = cc.id
        WHERE m.estado = 1
          AND (p_id_balon IS NULL OR m.id_balon = p_id_balon)
          AND (p_id_tipo_mantenimiento IS NULL OR m.id_tipo_mantenimiento = p_id_tipo_mantenimiento)
          AND (p_id_estado IS NULL OR m.id_estado = p_id_estado)
          AND (p_es_externo IS NULL OR m.es_externo = p_es_externo)
          AND (
              p_busqueda = ''
              OR gen_texto_coincide(COALESCE(b.codigo_balon, ''), p_busqueda)
              OR gen_texto_coincide(COALESCE(p.codigo, ''), p_busqueda)
              OR gen_texto_coincide(COALESCE(p.nombre, ''), p_busqueda)
              OR gen_texto_coincide(COALESCE(m.descripcion, ''), p_busqueda)
          )
        ORDER BY m.fecha_ingreso DESC, m.id DESC
        LIMIT p_limite
        OFFSET p_offset
    ) t;

    RETURN json_build_object('registros', v_registros, 'total', v_total);
END;
$$;


--
-- Name: bal_listar_movimientos(character varying, integer, integer, integer, integer, integer, date, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bal_listar_movimientos(p_busqueda character varying DEFAULT ''::character varying, p_limite integer DEFAULT 10, p_offset integer DEFAULT 0, p_id_balon integer DEFAULT NULL::integer, p_id_tipo_movimiento integer DEFAULT NULL::integer, p_id_cliente integer DEFAULT NULL::integer, p_fecha_desde date DEFAULT NULL::date, p_fecha_hasta date DEFAULT NULL::date) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_registros JSON;
    v_total BIGINT;
BEGIN
    SET TIME ZONE 'America/Lima';

    SELECT COUNT(*) INTO v_total
    FROM bal_movimiento m
    INNER JOIN bal_balon b ON m.id_balon = b.id
    LEFT JOIN gen_lista_opciones tm ON m.id_tipo_movimiento = tm.id
    WHERE m.estado = 1
      AND (p_id_balon IS NULL OR m.id_balon = p_id_balon)
      AND (p_id_tipo_movimiento IS NULL OR m.id_tipo_movimiento = p_id_tipo_movimiento)
      AND (p_id_cliente IS NULL OR m.id_cliente = p_id_cliente)
      AND (p_fecha_desde IS NULL OR m.fecha_movimiento::DATE >= p_fecha_desde)
      AND (p_fecha_hasta IS NULL OR m.fecha_movimiento::DATE <= p_fecha_hasta)
      AND (
          p_busqueda = ''
          OR gen_texto_coincide(b.codigo_balon, p_busqueda)
          OR gen_texto_coincide(COALESCE(tm.nombre, ''), p_busqueda)
          OR gen_texto_coincide(COALESCE(m.observacion, ''), p_busqueda)
      );

    SELECT COALESCE(json_agg(row_to_json(t)), '[]'::JSON) INTO v_registros
    FROM (
        SELECT
            m.id,
            m.id_balon,
            b.codigo_balon,
            m.id_tipo_movimiento,
            tm.nombre AS nombre_tipo_movimiento,
            m.id_documento_ref,
            m.id_tipo_documento_ref,
            tdr.nombre AS nombre_tipo_documento_ref,
            COALESCE(
                m.id_cliente,
                mr.id_proveedor,
                rp.id_proveedor,
                mt.id_proveedor
            ) AS id_cliente,
            COALESCE(
                NULLIF(TRIM(c.razon_social), ''),
                NULLIF(TRIM(CONCAT_WS(' ', c.nombres, c.apellido_paterno, c.apellido_materno)), ''),
                c.numero_documento
            ) AS nombre_cliente,
            m.id_almacen_origen,
            COALESCE(
                ao.nombre,
                CASE
                    WHEN tm.nombre IN ('ENTRADA_LLENADO', 'ENTRADA_PLANTA_EXTERNA')
                    THEN 'Planta externa'
                    ELSE NULL
                END
            ) AS nombre_almacen_origen,
            m.id_almacen_destino,
            ad.nombre AS nombre_almacen_destino,
            m.fecha_movimiento,
            m.observacion,
            m.estado,
            m.fecha_creacion,
            (
                m.id_documento_ref IS NULL
                AND NOT EXISTS (
                    SELECT 1 FROM bal_baja_balon bb
                    WHERE bb.id_movimiento = m.id AND bb.estado = 1
                )
            ) AS puede_eliminar
        FROM bal_movimiento m
        INNER JOIN bal_balon b ON m.id_balon = b.id
        LEFT JOIN gen_lista_opciones tm ON m.id_tipo_movimiento = tm.id
        LEFT JOIN gen_lista_opciones tdr ON m.id_tipo_documento_ref = tdr.id
        LEFT JOIN bal_movimiento_recarga mr
            ON tdr.nombre = 'RECARGA'
           AND mr.id = m.id_documento_ref
        LEFT JOIN bal_recarga_planta rp
            ON tdr.nombre = 'RECARGA'
           AND rp.id = COALESCE(mr.id_recarga_planta, m.id_documento_ref)
        LEFT JOIN bal_mantenimiento mt
            ON tdr.nombre = 'MANTENIMIENTO'
           AND mt.id = m.id_documento_ref
        LEFT JOIN cli_clientes c ON c.id = COALESCE(
            m.id_cliente,
            mr.id_proveedor,
            rp.id_proveedor,
            mt.id_proveedor
        )
        LEFT JOIN gen_almacen ao ON m.id_almacen_origen = ao.id
        LEFT JOIN gen_almacen ad ON m.id_almacen_destino = ad.id
        WHERE m.estado = 1
          AND (p_id_balon IS NULL OR m.id_balon = p_id_balon)
          AND (p_id_tipo_movimiento IS NULL OR m.id_tipo_movimiento = p_id_tipo_movimiento)
          AND (p_id_cliente IS NULL OR m.id_cliente = p_id_cliente)
          AND (p_fecha_desde IS NULL OR m.fecha_movimiento::DATE >= p_fecha_desde)
          AND (p_fecha_hasta IS NULL OR m.fecha_movimiento::DATE <= p_fecha_hasta)
          AND (
              p_busqueda = ''
              OR gen_texto_coincide(b.codigo_balon, p_busqueda)
              OR gen_texto_coincide(COALESCE(tm.nombre, ''), p_busqueda)
              OR gen_texto_coincide(COALESCE(m.observacion, ''), p_busqueda)
          )
        ORDER BY m.fecha_movimiento DESC, m.id DESC
        LIMIT p_limite
        OFFSET p_offset
    ) t;

    RETURN json_build_object('registros', v_registros, 'total', v_total);
END;
$$;


--
-- Name: bal_listar_movimientos_recarga(character varying, integer, integer, integer, integer, date, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bal_listar_movimientos_recarga(p_busqueda character varying DEFAULT ''::character varying, p_limite integer DEFAULT 10, p_offset integer DEFAULT 0, p_id_balon integer DEFAULT NULL::integer, p_id_almacen integer DEFAULT NULL::integer, p_fecha_desde date DEFAULT NULL::date, p_fecha_hasta date DEFAULT NULL::date) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_registros JSON;
    v_total BIGINT;
BEGIN
    SET TIME ZONE 'America/Lima';

    SELECT COUNT(*) INTO v_total
    FROM bal_movimiento_recarga mr
    INNER JOIN bal_balon b ON mr.id_balon = b.id
    LEFT JOIN bal_recarga_planta rp ON rp.id = mr.id_recarga_planta AND rp.estado = 1
    LEFT JOIN gre_guia_remision grs ON grs.id = rp.id_guia_salida AND grs.estado = 1
    LEFT JOIN com_comprobante_compra cc ON cc.id = mr.id_comprobante_compra AND cc.estado = 1
    LEFT JOIN cli_clientes cli ON mr.id_cliente = cli.id
    LEFT JOIN gen_lista_opciones tr ON mr.id_tipo_recarga = tr.id
    WHERE mr.estado = 1
      AND (p_id_balon IS NULL OR mr.id_balon = p_id_balon)
      AND (p_id_almacen IS NULL OR mr.id_almacen = p_id_almacen)
      AND (p_fecha_desde IS NULL OR mr.fecha_salida_almacen >= p_fecha_desde)
      AND (p_fecha_hasta IS NULL OR mr.fecha_salida_almacen <= p_fecha_hasta)
      AND (
          p_busqueda = ''
          OR gen_texto_coincide(b.codigo_balon, p_busqueda)
          OR gen_texto_coincide(COALESCE(cli.razon_social, ''), p_busqueda)
          OR gen_texto_coincide(COALESCE(mr.numero_guia_salida, rp.numero_guia_salida, grs.numero, ''), p_busqueda)
          OR gen_texto_coincide(COALESCE(mr.numero_factura, cc.numero, rp.numero_factura, ''), p_busqueda)
          OR gen_texto_coincide(COALESCE(tr.nombre, ''), p_busqueda)
      );

    SELECT COALESCE(json_agg(row_to_json(t)), '[]'::JSON) INTO v_registros
    FROM (
        SELECT
            mr.id,
            mr.fecha_salida_almacen,
            mr.id_balon,
            b.codigo_balon,
            mr.id_balon_origen,
            bo.codigo_balon AS codigo_balon_origen,
            mr.id_comprobante_compra,
            mr.id_cliente,
            cli.razon_social AS nombre_cliente,
            mr.id_tipo_recarga,
            tr.nombre AS tipo_recarga_nombre,
            mr.id_producto,
            p.nombre AS nombre_producto,
            COALESCE(mr.capacidad, tb.capacidad) AS capacidad,
            mr.id_recarga_planta,
            rp.numero AS numero_recarga_planta,
            rp.id_guia_salida,
            COALESCE(mr.serie_guia_salida, rp.serie_guia_salida, grs.serie) AS serie_guia_salida,
            COALESCE(mr.numero_guia_salida, rp.numero_guia_salida, grs.numero) AS numero_guia_salida,
            COALESCE(mr.serie_factura, cc.serie, rp.serie_factura) AS serie_factura,
            COALESCE(mr.numero_factura, cc.numero, rp.numero_factura) AS numero_factura,
            mr.id_comprobante,
            mr.fecha_llegada_almacen,
            mr.id_almacen,
            a.nombre AS nombre_almacen,
            mr.estado,
            mr.fecha_creacion,
            mr.id_comprobante IS NULL
            AND NOT EXISTS (
                SELECT 1 FROM bal_balon_ph_historial ph
                WHERE ph.id_movimiento_recarga = mr.id AND ph.estado = 1
            ) AS puede_eliminar
        FROM bal_movimiento_recarga mr
        INNER JOIN bal_balon b ON mr.id_balon = b.id
        LEFT JOIN bal_tipo_balon tb ON tb.id = b.id_tipo_balon
        LEFT JOIN bal_balon bo ON mr.id_balon_origen = bo.id
        LEFT JOIN bal_recarga_planta rp ON rp.id = mr.id_recarga_planta AND rp.estado = 1
        LEFT JOIN gre_guia_remision grs ON grs.id = rp.id_guia_salida AND grs.estado = 1
        LEFT JOIN com_comprobante_compra cc ON cc.id = mr.id_comprobante_compra AND cc.estado = 1
        LEFT JOIN cli_clientes cli ON mr.id_cliente = cli.id
        LEFT JOIN gen_lista_opciones tr ON mr.id_tipo_recarga = tr.id
        LEFT JOIN pro_producto p ON mr.id_producto = p.id
        LEFT JOIN gen_almacen a ON mr.id_almacen = a.id
        WHERE mr.estado = 1
          AND (p_id_balon IS NULL OR mr.id_balon = p_id_balon)
          AND (p_id_almacen IS NULL OR mr.id_almacen = p_id_almacen)
          AND (p_fecha_desde IS NULL OR mr.fecha_salida_almacen >= p_fecha_desde)
          AND (p_fecha_hasta IS NULL OR mr.fecha_salida_almacen <= p_fecha_hasta)
          AND (
              p_busqueda = ''
              OR gen_texto_coincide(b.codigo_balon, p_busqueda)
              OR gen_texto_coincide(COALESCE(cli.razon_social, ''), p_busqueda)
              OR gen_texto_coincide(COALESCE(mr.numero_guia_salida, rp.numero_guia_salida, grs.numero, ''), p_busqueda)
              OR gen_texto_coincide(COALESCE(mr.numero_factura, cc.numero, rp.numero_factura, ''), p_busqueda)
              OR gen_texto_coincide(COALESCE(tr.nombre, ''), p_busqueda)
          )
        ORDER BY mr.fecha_salida_almacen DESC, mr.id DESC
        LIMIT p_limite
        OFFSET p_offset
    ) t;

    RETURN json_build_object('registros', v_registros, 'total', v_total);
END;
$$;


--
-- Name: bal_listar_pendientes_recojo(character varying, integer, integer, integer, character varying, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bal_listar_pendientes_recojo(p_busqueda character varying DEFAULT ''::character varying, p_limite integer DEFAULT 10, p_offset integer DEFAULT 0, p_id_cliente integer DEFAULT NULL::integer, p_tipo_origen character varying DEFAULT NULL::character varying, p_fecha_hasta date DEFAULT NULL::date) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_rows JSON;
    v_total BIGINT;
    v_tipo VARCHAR := NULLIF(UPPER(TRIM(p_tipo_origen)), '');
BEGIN
    SET TIME ZONE 'America/Lima';

    IF v_tipo IS NOT NULL AND v_tipo NOT IN ('PRESTAMO', 'ALQUILER') THEN
        RETURN json_build_object('registros', '[]'::JSON, 'total', 0);
    END IF;

    WITH pendientes AS (
        SELECT
            'PRESTAMO'::VARCHAR AS origen,
            p.id AS id_origen,
            p.numero_prestamo AS numero_origen,
            pd.id AS id_detalle,
            'CILINDRO'::VARCHAR AS tipo_item,
            p.id_cliente,
            COALESCE(
                NULLIF(TRIM(c.razon_social), ''),
                NULLIF(TRIM(CONCAT_WS(' ', c.nombres, c.apellido_paterno)), ''),
                c.numero_documento
            ) AS nombre_cliente,
            pd.id_balon,
            b.codigo_balon,
            pd.fecha_vencimiento AS fecha_retorno,
            CURRENT_DATE - pd.fecha_vencimiento AS dias_pendientes,
            EXISTS (
                SELECT 1
                FROM bal_recojo_detalle rd
                JOIN bal_recojo r ON r.id = rd.id_recojo AND r.estado = 1
                JOIN gen_lista_opciones e ON e.id = r.id_estado
                WHERE rd.id_prestamo_detalle = pd.id
                  AND rd.estado = 1
                  AND e.nombre IN ('PROGRAMADO', 'EN_RUTA')
            ) AS tiene_recojo_programado
        FROM bal_prestamo_detalle pd
        JOIN bal_prestamo p ON p.id = pd.id_prestamo AND p.estado = 1
        JOIN gen_lista_opciones ep ON ep.id = p.id_estado AND ep.nombre = 'ACTIVO'
        LEFT JOIN cli_clientes c ON c.id = p.id_cliente
        LEFT JOIN bal_balon b ON b.id = pd.id_balon
        WHERE pd.estado = 1
          AND pd.fecha_devolucion IS NULL

        UNION ALL

        -- Alquiler activo con regulador/accesorio pendiente (con o sin cilindros)
        SELECT
            'ALQUILER'::VARCHAR,
            a.id,
            a.numero_alquiler,
            0 AS id_detalle,
            'REGULADOR'::VARCHAR,
            a.id_cliente,
            COALESCE(
                NULLIF(TRIM(c.razon_social), ''),
                NULLIF(TRIM(CONCAT_WS(' ', c.nombres, c.apellido_paterno)), ''),
                c.numero_documento
            ),
            NULL::INTEGER AS id_balon,
            COALESCE(
                NULLIF(TRIM(CONCAT_WS(
                    ' — ',
                    NULLIF(TRIM(COALESCE(pr.codigo, ps.codigo)), ''),
                    NULLIF(TRIM(COALESCE(pr.nombre, ps.nombre)), '')
                )), ''),
                'Regulador / accesorio'
            ) AS codigo_balon,
            a.fecha_fin_pactada,
            CURRENT_DATE - a.fecha_fin_pactada,
            EXISTS (
                SELECT 1
                FROM bal_recojo r
                JOIN gen_lista_opciones e ON e.id = r.id_estado
                WHERE r.id_alquiler = a.id
                  AND r.estado = 1
                  AND e.nombre IN ('PROGRAMADO', 'EN_RUTA')
                  AND NOT EXISTS (
                      SELECT 1
                      FROM bal_recojo_detalle rd
                      WHERE rd.id_recojo = r.id
                        AND rd.estado = 1
                        AND (
                            rd.id_prestamo_detalle IS NOT NULL
                            OR rd.id_alquiler_detalle IS NOT NULL
                        )
                  )
            )
        FROM bal_alquiler a
        JOIN gen_lista_opciones ea ON ea.id = a.id_estado AND ea.nombre = 'ACTIVO'
        LEFT JOIN cli_clientes c ON c.id = a.id_cliente
        LEFT JOIN pro_producto pr ON pr.id = a.id_producto_regulador
        LEFT JOIN pro_producto ps ON ps.id = a.id_producto_stock
        WHERE a.estado = 1
          AND a.fecha_fin_real IS NULL
          AND a.fecha_devolucion_regulador IS NULL
          AND COALESCE(a.id_producto_regulador, a.id_producto_stock) IS NOT NULL
    ),
    filtrados AS (
        SELECT *
        FROM pendientes x
        WHERE (v_tipo IS NULL OR x.origen = v_tipo)
          AND (p_id_cliente IS NULL OR x.id_cliente = p_id_cliente)
          AND (p_fecha_hasta IS NULL OR x.fecha_retorno <= p_fecha_hasta)
          AND (
              COALESCE(p_busqueda, '') = ''
              OR gen_texto_coincide(COALESCE(x.numero_origen, ''), p_busqueda)
              OR gen_texto_coincide(COALESCE(x.nombre_cliente, ''), p_busqueda)
              OR gen_texto_coincide(COALESCE(x.codigo_balon, ''), p_busqueda)
          )
    ),
    pagina AS (
        SELECT
            origen,
            id_origen,
            numero_origen,
            id_detalle,
            tipo_item,
            id_cliente,
            nombre_cliente,
            id_balon,
            codigo_balon,
            fecha_retorno,
            dias_pendientes,
            tiene_recojo_programado
        FROM filtrados
        ORDER BY fecha_retorno ASC NULLS LAST, origen, id_origen, id_detalle
        LIMIT p_limite OFFSET COALESCE(p_offset, 0)
    )
    SELECT
        (SELECT COUNT(*)::BIGINT FROM filtrados),
        COALESCE(
            (
                SELECT json_agg(row_to_json(p) ORDER BY p.fecha_retorno ASC NULLS LAST, p.origen, p.id_origen, p.id_detalle)
                FROM pagina p
            ),
            '[]'::JSON
        )
    INTO v_total, v_rows;

    RETURN json_build_object('registros', COALESCE(v_rows, '[]'::JSON), 'total', COALESCE(v_total, 0));
END;
$$;


--
-- Name: bal_listar_ph_historial(integer, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bal_listar_ph_historial(p_id_balon integer, p_limite integer DEFAULT 50, p_offset integer DEFAULT 0) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_registros JSON;
    v_total BIGINT;
BEGIN
    SET TIME ZONE 'America/Lima';

    IF NOT EXISTS (SELECT 1 FROM bal_balon WHERE id = p_id_balon AND estado = 1) THEN
        RETURN json_build_object('registros', '[]'::JSON, 'total', 0);
    END IF;

    SELECT COUNT(*) INTO v_total
    FROM bal_balon_ph_historial h
    WHERE h.id_balon = p_id_balon AND h.estado = 1;

    SELECT COALESCE(json_agg(row_to_json(t)), '[]'::JSON) INTO v_registros
    FROM (
        SELECT
            h.id,
            h.id_balon,
            h.fecha_prueba,
            h.vigencia_anios,
            h.fecha_proxima,
            h.id_organo_inspector,
            oi.nombre AS nombre_organo_inspector,
            h.organo_inspector_no_aplica,
            h.numero_certificado,
            h.id_mantenimiento,
            h.id_movimiento_recarga,
            h.es_vigente,
            h.observacion,
            h.fecha_creacion
        FROM bal_balon_ph_historial h
        LEFT JOIN gen_lista_opciones oi ON h.id_organo_inspector = oi.id
        WHERE h.id_balon = p_id_balon AND h.estado = 1
        ORDER BY h.fecha_prueba DESC, h.id DESC
        LIMIT p_limite
        OFFSET p_offset
    ) t;

    RETURN json_build_object('registros', v_registros, 'total', v_total);
END;
$$;


--
-- Name: bal_listar_ph_por_vencer(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bal_listar_ph_por_vencer(p_dias integer DEFAULT 60) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_dias INTEGER;
    v_registros JSON;
BEGIN
    SET TIME ZONE 'America/Lima';
    v_dias := GREATEST(COALESCE(p_dias, 60), 0);

    SELECT COALESCE(json_agg(t.row_data ORDER BY t.fecha_proxima, t.id), '[]'::JSON)
    INTO v_registros
    FROM (
        SELECT json_build_object(
            'id', b.id,
            'codigo_balon', b.codigo_balon,
            'fecha_proxima', b.fecha_proxima_prueba_hidrostatica,
            'dias_restantes', (b.fecha_proxima_prueba_hidrostatica - CURRENT_DATE)
        ) AS row_data,
        b.id,
        b.fecha_proxima_prueba_hidrostatica AS fecha_proxima
        FROM bal_balon b
        LEFT JOIN gen_lista_opciones eb ON eb.id = b.id_estado_balon
        WHERE b.estado = 1
          AND b.fecha_proxima_prueba_hidrostatica IS NOT NULL
          AND b.fecha_proxima_prueba_hidrostatica >= CURRENT_DATE
          AND b.fecha_proxima_prueba_hidrostatica <= CURRENT_DATE + make_interval(days => v_dias)
          AND COALESCE(eb.nombre, '') NOT IN ('DADO_DE_BAJA', 'ROBO')
    ) t;

    RETURN json_build_object('registros', v_registros);
END;
$$;


--
-- Name: bal_listar_prestamo_detalles(character varying, integer, integer, integer, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bal_listar_prestamo_detalles(p_busqueda character varying DEFAULT ''::character varying, p_limite integer DEFAULT 10, p_offset integer DEFAULT 0, p_id_prestamo integer DEFAULT NULL::integer, p_id_balon integer DEFAULT NULL::integer, p_id_estado integer DEFAULT NULL::integer) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_registros JSON;
    v_total BIGINT;
BEGIN
    SET TIME ZONE 'America/Lima';

    SELECT COUNT(*) INTO v_total
    FROM bal_prestamo_detalle pd
    INNER JOIN bal_prestamo pr ON pd.id_prestamo = pr.id
    LEFT JOIN bal_balon b ON pd.id_balon = b.id
    LEFT JOIN cli_clientes c ON pr.id_cliente = c.id
    WHERE pd.estado = 1
      AND (p_id_prestamo IS NULL OR pd.id_prestamo = p_id_prestamo)
      AND (p_id_balon IS NULL OR pd.id_balon = p_id_balon)
      AND (p_id_estado IS NULL OR pd.id_estado = p_id_estado)
      AND (
          p_busqueda = ''
          OR gen_texto_coincide(COALESCE(b.codigo_balon, ''), p_busqueda)
          OR gen_texto_coincide(COALESCE(pd.motivo_especifico, ''), p_busqueda)
          OR gen_texto_coincide(COALESCE(pr.numero_prestamo, ''), p_busqueda)
          OR gen_texto_coincide(COALESCE(c.razon_social, ''), p_busqueda)
      );

    SELECT COALESCE(json_agg(row_to_json(t)), '[]'::JSON) INTO v_registros
    FROM (
        SELECT
            pd.id,
            pd.id_prestamo,
            pr.numero_prestamo,
            pd.id_balon,
            b.codigo_balon,
            pr.id_tipo_prestamo,
            tp.nombre AS nombre_tipo_prestamo,
            pr.id_cliente,
            c.razon_social AS nombre_cliente,
            pr.id_almacen,
            a.nombre AS nombre_almacen,
            pd.id_producto,
            COALESCE(pg.nombre, p.nombre) AS nombre_producto,
            b.id_producto_gas,
            pg.nombre AS nombre_producto_gas,
            eb.nombre AS nombre_estado_balon,
            pd.fecha_entregado,
            pd.fecha_prestamo,
            pd.fecha_vencimiento,
            pd.fecha_devolucion,
            pd.id_guia_entrega,
            pd.serie_guia_entrega,
            pd.numero_guia_entrega,
            pd.id_guia_devolucion,
            pd.serie_guia_devolucion,
            pd.numero_guia_devolucion,
            pd.id_estado,
            ep.nombre AS nombre_estado,
            pd.estado,
            pd.fecha_creacion
        FROM bal_prestamo_detalle pd
        INNER JOIN bal_prestamo pr ON pd.id_prestamo = pr.id
        LEFT JOIN bal_balon b ON pd.id_balon = b.id
        LEFT JOIN gen_lista_opciones tp ON pr.id_tipo_prestamo = tp.id
        LEFT JOIN cli_clientes c ON pr.id_cliente = c.id
        LEFT JOIN gen_almacen a ON pr.id_almacen = a.id
        LEFT JOIN pro_producto p ON pd.id_producto = p.id
        LEFT JOIN pro_producto pg ON b.id_producto_gas = pg.id
        LEFT JOIN gen_lista_opciones eb ON b.id_estado_balon = eb.id
        LEFT JOIN gen_lista_opciones ep ON pd.id_estado = ep.id
        WHERE pd.estado = 1
          AND (p_id_prestamo IS NULL OR pd.id_prestamo = p_id_prestamo)
          AND (p_id_balon IS NULL OR pd.id_balon = p_id_balon)
          AND (p_id_estado IS NULL OR pd.id_estado = p_id_estado)
          AND (
              p_busqueda = ''
              OR gen_texto_coincide(COALESCE(b.codigo_balon, ''), p_busqueda)
              OR gen_texto_coincide(COALESCE(pd.motivo_especifico, ''), p_busqueda)
              OR gen_texto_coincide(COALESCE(pr.numero_prestamo, ''), p_busqueda)
              OR gen_texto_coincide(COALESCE(c.razon_social, ''), p_busqueda)
          )
        ORDER BY pd.fecha_prestamo DESC NULLS LAST, pd.id DESC
        LIMIT p_limite
        OFFSET p_offset
    ) t;

    RETURN json_build_object('registros', v_registros, 'total', v_total);
END;
$$;


--
-- Name: bal_listar_prestamos(character varying, integer, integer, integer, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bal_listar_prestamos(p_busqueda character varying DEFAULT ''::character varying, p_limite integer DEFAULT 10, p_offset integer DEFAULT 0, p_id_tipo_prestamo integer DEFAULT NULL::integer, p_id_cliente integer DEFAULT NULL::integer, p_id_estado integer DEFAULT NULL::integer) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_registros JSON;
    v_total BIGINT;
BEGIN
    SET TIME ZONE 'America/Lima';

    SELECT COUNT(*) INTO v_total
    FROM bal_prestamo pr
    LEFT JOIN gen_lista_opciones tp ON pr.id_tipo_prestamo = tp.id
    WHERE pr.estado = 1
      AND (p_id_tipo_prestamo IS NULL OR pr.id_tipo_prestamo = p_id_tipo_prestamo)
      AND (p_id_cliente IS NULL OR pr.id_cliente = p_id_cliente)
      AND (p_id_estado IS NULL OR pr.id_estado = p_id_estado)
      AND (
          p_busqueda = ''
          OR gen_texto_coincide(COALESCE(pr.numero_prestamo, ''), p_busqueda)
          OR gen_texto_coincide(COALESCE(pr.titulo, ''), p_busqueda)
      );

    SELECT COALESCE(json_agg(row_to_json(t)), '[]'::JSON) INTO v_registros
    FROM (
        SELECT
            pr.id,
            pr.numero_prestamo,
            pr.id_tipo_prestamo,
            tp.nombre AS nombre_tipo_prestamo,
            pr.id_cliente,
            COALESCE(
                NULLIF(TRIM(c.razon_social), ''),
                NULLIF(TRIM(CONCAT_WS(' ', c.nombres, c.apellido_paterno, c.apellido_materno)), ''),
                c.numero_documento
            ) AS nombre_cliente,
            pr.fecha_salida,
            pr.fecha_retorno_pactada,
            pr.fecha_retorno_real,
            pr.titulo,
            pr.id_estado,
            ep.nombre AS nombre_estado,
            pr.id_comprobante_venta,
            CASE
                WHEN cv.id IS NULL THEN NULL
                ELSE CONCAT_WS('-', cv.serie, cv.numero)
            END AS comprobante_venta,
            pr.id_comprobante_compra,
            CASE
                WHEN cc.id IS NULL THEN NULL
                ELSE CONCAT_WS('-', cc.serie, cc.numero)
            END AS comprobante_compra,
            pr.estado,
            pr.fecha_creacion,
            (
                SELECT COUNT(*)::INTEGER
                FROM bal_prestamo_detalle pd
                WHERE pd.id_prestamo = pr.id AND pd.estado = 1
            ) AS total_detalles,
            (
                SELECT COUNT(*)::INTEGER
                FROM ven_garantia vg
                WHERE vg.id_prestamo = pr.id AND vg.estado = 1
            ) AS total_garantias,
            (
                pr.id_comprobante_venta IS NULL
                AND pr.id_comprobante_compra IS NULL
                AND NOT EXISTS (
                    SELECT 1 FROM bal_prestamo_detalle pd
                    WHERE pd.id_prestamo = pr.id AND pd.estado = 1
                )
                AND NOT EXISTS (
                    SELECT 1 FROM ven_garantia vg
                    WHERE vg.id_prestamo = pr.id AND vg.estado = 1
                )
            ) AS puede_eliminar
        FROM bal_prestamo pr
        LEFT JOIN gen_lista_opciones tp ON pr.id_tipo_prestamo = tp.id
        LEFT JOIN cli_clientes c ON pr.id_cliente = c.id
        LEFT JOIN gen_lista_opciones ep ON pr.id_estado = ep.id
        LEFT JOIN ven_comprobante cv ON pr.id_comprobante_venta = cv.id
        LEFT JOIN com_comprobante_compra cc ON pr.id_comprobante_compra = cc.id
        WHERE pr.estado = 1
          AND (p_id_tipo_prestamo IS NULL OR pr.id_tipo_prestamo = p_id_tipo_prestamo)
          AND (p_id_cliente IS NULL OR pr.id_cliente = p_id_cliente)
          AND (p_id_estado IS NULL OR pr.id_estado = p_id_estado)
          AND (
              p_busqueda = ''
              OR gen_texto_coincide(COALESCE(pr.numero_prestamo, ''), p_busqueda)
              OR gen_texto_coincide(COALESCE(pr.titulo, ''), p_busqueda)
          )
        ORDER BY pr.fecha_salida DESC NULLS LAST, pr.id DESC
        LIMIT p_limite
        OFFSET p_offset
    ) t;

    RETURN json_build_object('registros', v_registros, 'total', v_total);
END;
$$;


--
-- Name: bal_listar_prestamos_por_vencer_notificar(integer, integer, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bal_listar_prestamos_por_vencer_notificar(p_dias_min integer DEFAULT 3, p_dias_max integer DEFAULT 7, p_fecha date DEFAULT NULL::date) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_fecha DATE;
    v_min INTEGER;
    v_max INTEGER;
    v_registros JSON;
BEGIN
    SET TIME ZONE 'America/Lima';
    v_fecha := COALESCE(p_fecha, CURRENT_DATE);
    v_min := GREATEST(COALESCE(p_dias_min, 3), 0);
    v_max := GREATEST(COALESCE(p_dias_max, 7), v_min);

    SELECT COALESCE(json_agg(t.row_data ORDER BY t.fecha_vencimiento, t.id_detalle), '[]'::JSON)
    INTO v_registros
    FROM (
        SELECT json_build_object(
            'id_detalle', pd.id,
            'id_prestamo', p.id,
            'numero_prestamo', p.numero_prestamo,
            'id_cliente', p.id_cliente,
            'nombre_cliente', COALESCE(c.razon_social, TRIM(CONCAT_WS(' ', c.nombres, c.apellido_paterno, c.apellido_materno))),
            'id_balon', pd.id_balon,
            'codigo_balon', b.codigo_balon,
            'fecha_vencimiento', COALESCE(pd.fecha_vencimiento, p.fecha_retorno_pactada),
            'dias_para_vencer', (COALESCE(pd.fecha_vencimiento, p.fecha_retorno_pactada) - v_fecha)
        ) AS row_data,
        pd.id AS id_detalle,
        COALESCE(pd.fecha_vencimiento, p.fecha_retorno_pactada) AS fecha_vencimiento
        FROM bal_prestamo_detalle pd
        INNER JOIN bal_prestamo p ON p.id = pd.id_prestamo AND p.estado = 1
        LEFT JOIN gen_lista_opciones ep ON ep.id = p.id_estado
        LEFT JOIN gen_lista_opciones ed ON ed.id = pd.id_estado
        LEFT JOIN cli_clientes c ON c.id = p.id_cliente
        LEFT JOIN bal_balon b ON b.id = pd.id_balon
        WHERE pd.estado = 1
          AND pd.fecha_devolucion IS NULL
          AND COALESCE(ep.nombre, 'ACTIVO') = 'ACTIVO'
          AND COALESCE(ed.nombre, 'ACTIVO') NOT IN ('DEVUELTO', 'VENCIDO')
          AND COALESCE(pd.fecha_vencimiento, p.fecha_retorno_pactada) IS NOT NULL
          AND COALESCE(pd.fecha_vencimiento, p.fecha_retorno_pactada)
              BETWEEN (v_fecha + v_min) AND (v_fecha + v_max)
    ) t;

    RETURN json_build_object('registros', v_registros);
END;
$$;


--
-- Name: bal_listar_prestamos_vencidos_notificar(date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bal_listar_prestamos_vencidos_notificar(p_fecha date DEFAULT NULL::date) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_fecha DATE;
    v_registros JSON;
BEGIN
    SET TIME ZONE 'America/Lima';
    v_fecha := COALESCE(p_fecha, CURRENT_DATE);

    SELECT COALESCE(json_agg(t.row_data ORDER BY t.fecha_vencimiento, t.id_detalle), '[]'::JSON)
    INTO v_registros
    FROM (
        SELECT json_build_object(
            'id_detalle', pd.id,
            'id_prestamo', p.id,
            'numero_prestamo', p.numero_prestamo,
            'id_cliente', p.id_cliente,
            'nombre_cliente', COALESCE(c.razon_social, TRIM(CONCAT_WS(' ', c.nombres, c.apellido_paterno, c.apellido_materno))),
            'id_balon', pd.id_balon,
            'codigo_balon', b.codigo_balon,
            'fecha_vencimiento', COALESCE(pd.fecha_vencimiento, p.fecha_retorno_pactada),
            'dias_vencido', (v_fecha - COALESCE(pd.fecha_vencimiento, p.fecha_retorno_pactada))
        ) AS row_data,
        pd.id AS id_detalle,
        COALESCE(pd.fecha_vencimiento, p.fecha_retorno_pactada) AS fecha_vencimiento
        FROM bal_prestamo_detalle pd
        INNER JOIN bal_prestamo p ON p.id = pd.id_prestamo AND p.estado = 1
        LEFT JOIN gen_lista_opciones ep ON ep.id = p.id_estado
        LEFT JOIN gen_lista_opciones ed ON ed.id = pd.id_estado
        LEFT JOIN cli_clientes c ON c.id = p.id_cliente
        LEFT JOIN bal_balon b ON b.id = pd.id_balon
        WHERE pd.estado = 1
          AND pd.fecha_devolucion IS NULL
          AND COALESCE(ep.nombre, 'ACTIVO') IN ('ACTIVO', 'VENCIDO')
          AND COALESCE(ed.nombre, 'ACTIVO') NOT IN ('DEVUELTO')
          AND COALESCE(pd.fecha_vencimiento, p.fecha_retorno_pactada) IS NOT NULL
          AND COALESCE(pd.fecha_vencimiento, p.fecha_retorno_pactada) < v_fecha
    ) t;

    RETURN json_build_object('registros', v_registros);
END;
$$;


--
-- Name: bal_listar_protocolo_recarga_planta(character varying, integer, integer, integer, date, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bal_listar_protocolo_recarga_planta(p_busqueda character varying DEFAULT ''::character varying, p_id_proveedor integer DEFAULT NULL::integer, p_id_almacen integer DEFAULT NULL::integer, p_id_estado integer DEFAULT NULL::integer, p_fecha_desde date DEFAULT NULL::date, p_fecha_hasta date DEFAULT NULL::date) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_registros JSON;
    v_total BIGINT;
BEGIN
    SET TIME ZONE 'America/Lima';

    -- Una fila por cilindro (detalle) con cabecera documental: ida, GRE, factura, retorno, lote.
    SELECT
        COUNT(*)::BIGINT,
        COALESCE(
            json_agg(row_to_json(t) ORDER BY t.fecha_salida DESC, t.id_recarga_planta DESC, t.codigo_balon),
            '[]'::JSON
        )
    INTO v_total, v_registros
    FROM (
        SELECT
            rp.id AS id_recarga_planta,
            rp.numero AS numero_orden,
            rp.fecha_salida,
            rp.id_proveedor,
            COALESCE(
                NULLIF(TRIM(prv.razon_social), ''),
                NULLIF(TRIM(CONCAT_WS(' ', prv.nombres, prv.apellido_paterno)), ''),
                prv.numero_documento
            ) AS nombre_proveedor,
            rp.id_almacen,
            a.nombre AS nombre_almacen,
            rp.id_guia_salida,
            COALESCE(rp.serie_guia_salida, gs.serie) AS serie_guia_salida,
            COALESCE(rp.numero_guia_salida, gs.numero) AS numero_guia_salida,
            rp.id_guia_retorno,
            COALESCE(rp.serie_guia_ingreso, gi.serie) AS serie_guia_ingreso,
            COALESCE(rp.numero_guia_ingreso, gi.numero) AS numero_guia_ingreso,
            rp.id_comprobante_compra,
            COALESCE(rp.serie_factura, cc.serie) AS serie_factura,
            COALESCE(rp.numero_factura, cc.numero) AS numero_factura,
            rp.fecha_llegada_almacen,
            COALESCE(NULLIF(TRIM(det.lote), ''), NULLIF(TRIM(rp.lote), '')) AS lote,
            COALESCE(det.fecha_vencimiento_lote, rp.fecha_vencimiento_lote) AS fecha_vencimiento_lote,
            COALESCE(det.fecha_prueba_hidrostatica, rp.fecha_prueba_hidrostatica) AS fecha_prueba_hidrostatica,
            est.nombre AS nombre_estado,
            det.id AS id_detalle,
            det.id_balon,
            b.codigo_balon,
            det.id_producto,
            p.nombre AS nombre_producto,
            p.codigo AS codigo_producto,
            COALESCE(det.capacidad, tb.capacidad) AS capacidad,
            um.nombre AS nombre_unidad_medida,
            det.observacion AS observacion_detalle,
            rp.observacion AS observacion_orden
        FROM bal_recarga_planta rp
        LEFT JOIN bal_recarga_planta_detalle det
            ON det.id_recarga_planta = rp.id AND det.estado = 1
        LEFT JOIN bal_balon b ON b.id = det.id_balon
        LEFT JOIN bal_tipo_balon tb ON tb.id = b.id_tipo_balon
        LEFT JOIN pro_producto p ON p.id = det.id_producto
        LEFT JOIN gen_lista_opciones um ON um.id = det.id_unidad_medida
        LEFT JOIN cli_clientes prv ON prv.id = rp.id_proveedor
        LEFT JOIN gen_almacen a ON a.id = rp.id_almacen
        LEFT JOIN gen_lista_opciones est ON est.id = rp.id_estado
        LEFT JOIN gre_guia_remision gs ON gs.id = rp.id_guia_salida AND gs.estado = 1
        LEFT JOIN gre_guia_remision gi ON gi.id = rp.id_guia_retorno AND gi.estado = 1
        LEFT JOIN com_comprobante_compra cc ON cc.id = rp.id_comprobante_compra AND cc.estado = 1
        WHERE rp.estado = 1
          AND (p_id_proveedor IS NULL OR rp.id_proveedor = p_id_proveedor)
          AND (p_id_almacen IS NULL OR rp.id_almacen = p_id_almacen)
          AND (p_id_estado IS NULL OR rp.id_estado = p_id_estado)
          AND (p_fecha_desde IS NULL OR rp.fecha_salida >= p_fecha_desde)
          AND (p_fecha_hasta IS NULL OR rp.fecha_salida <= p_fecha_hasta)
          AND (
              p_busqueda = ''
              OR gen_texto_coincide(COALESCE(rp.numero, ''), p_busqueda)
              OR gen_texto_coincide(COALESCE(rp.lote, ''), p_busqueda)
              OR gen_texto_coincide(COALESCE(det.lote, ''), p_busqueda)
              OR gen_texto_coincide(COALESCE(rp.serie_guia_salida, gs.serie, ''), p_busqueda)
              OR gen_texto_coincide(COALESCE(rp.numero_guia_salida, gs.numero, ''), p_busqueda)
              OR gen_texto_coincide(COALESCE(rp.serie_guia_ingreso, gi.serie, ''), p_busqueda)
              OR gen_texto_coincide(COALESCE(rp.numero_guia_ingreso, gi.numero, ''), p_busqueda)
              OR gen_texto_coincide(COALESCE(rp.serie_factura, cc.serie, ''), p_busqueda)
              OR gen_texto_coincide(COALESCE(rp.numero_factura, cc.numero, ''), p_busqueda)
              OR gen_texto_coincide(COALESCE(b.codigo_balon, ''), p_busqueda)
              OR gen_texto_coincide(COALESCE(prv.razon_social, ''), p_busqueda)
              OR gen_texto_coincide(COALESCE(prv.nombres, ''), p_busqueda)
              OR gen_texto_coincide(COALESCE(a.nombre, ''), p_busqueda)
          )
    ) t;

    RETURN json_build_object(
        'registros', COALESCE(v_registros, '[]'::JSON),
        'total', COALESCE(v_total, 0)
    );
END;
$$;


--
-- Name: bal_listar_recargas_planta(character varying, integer, integer, integer, integer, integer, date, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bal_listar_recargas_planta(p_busqueda character varying DEFAULT ''::character varying, p_limite integer DEFAULT 10, p_offset integer DEFAULT 0, p_id_proveedor integer DEFAULT NULL::integer, p_id_almacen integer DEFAULT NULL::integer, p_id_estado integer DEFAULT NULL::integer, p_fecha_desde date DEFAULT NULL::date, p_fecha_hasta date DEFAULT NULL::date) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_registros JSON;
    v_total BIGINT;
BEGIN
    SET TIME ZONE 'America/Lima';
    SELECT COUNT(*)
    INTO v_total
    FROM bal_recarga_planta rp
    LEFT JOIN cli_clientes prv ON prv.id = rp.id_proveedor
    LEFT JOIN gen_almacen a ON a.id = rp.id_almacen
    LEFT JOIN gen_lista_opciones est ON est.id = rp.id_estado
    LEFT JOIN gre_guia_remision gs ON gs.id = rp.id_guia_salida AND gs.estado = 1
    LEFT JOIN gre_guia_remision gi ON gi.id = rp.id_guia_retorno AND gi.estado = 1
    LEFT JOIN com_comprobante_compra cc ON cc.id = rp.id_comprobante_compra AND cc.estado = 1
    WHERE rp.estado = 1
      AND (p_id_proveedor IS NULL OR rp.id_proveedor = p_id_proveedor)
      AND (p_id_almacen IS NULL OR rp.id_almacen = p_id_almacen)
      AND (p_id_estado IS NULL OR rp.id_estado = p_id_estado)
      AND (p_fecha_desde IS NULL OR rp.fecha_salida >= p_fecha_desde)
      AND (p_fecha_hasta IS NULL OR rp.fecha_salida <= p_fecha_hasta)
      AND (
          p_busqueda = ''
          OR gen_texto_coincide(COALESCE(rp.numero, ''), p_busqueda)
          OR gen_texto_coincide(COALESCE(rp.lote, ''), p_busqueda)
          OR gen_texto_coincide(COALESCE(rp.serie_guia_salida, gs.serie, ''), p_busqueda)
          OR gen_texto_coincide(COALESCE(rp.numero_guia_salida, gs.numero, ''), p_busqueda)
          OR gen_texto_coincide(COALESCE(rp.serie_guia_ingreso, gi.serie, ''), p_busqueda)
          OR gen_texto_coincide(COALESCE(rp.numero_guia_ingreso, gi.numero, ''), p_busqueda)
          OR gen_texto_coincide(COALESCE(rp.serie_factura, cc.serie, ''), p_busqueda)
          OR gen_texto_coincide(COALESCE(rp.numero_factura, cc.numero, ''), p_busqueda)
          OR gen_texto_coincide(COALESCE(prv.razon_social, ''), p_busqueda)
          OR gen_texto_coincide(COALESCE(prv.nombres, ''), p_busqueda)
          OR gen_texto_coincide(COALESCE(a.nombre, ''), p_busqueda)
      );

    SELECT COALESCE(json_agg(row_to_json(t)), '[]'::JSON)
    INTO v_registros
    FROM (
        SELECT
            rp.id,
            rp.numero,
            rp.fecha_salida,
            rp.id_proveedor,
            COALESCE(
                NULLIF(TRIM(prv.razon_social), ''),
                NULLIF(TRIM(CONCAT_WS(' ', prv.nombres, prv.apellido_paterno)), ''),
                prv.numero_documento
            ) AS nombre_proveedor,
            rp.id_almacen,
            a.nombre AS nombre_almacen,
            rp.id_guia_salida,
            COALESCE(rp.serie_guia_salida, gs.serie) AS serie_guia_salida,
            COALESCE(rp.numero_guia_salida, gs.numero) AS numero_guia_salida,
            rp.id_guia_retorno,
            COALESCE(rp.serie_guia_ingreso, gi.serie) AS serie_guia_ingreso,
            COALESCE(rp.numero_guia_ingreso, gi.numero) AS numero_guia_ingreso,
            rp.id_comprobante_compra,
            COALESCE(rp.serie_factura, cc.serie) AS serie_factura,
            COALESCE(rp.numero_factura, cc.numero) AS numero_factura,
            rp.fecha_llegada_almacen,
            rp.lote,
            rp.fecha_vencimiento_lote,
            rp.id_estado,
            est.nombre AS nombre_estado,
            est.descripcion AS descripcion_estado,
            (
                SELECT COUNT(*)::INT
                FROM bal_recarga_planta_detalle d
                WHERE d.id_recarga_planta = rp.id AND d.estado = 1
            ) AS total_cilindros,
            rp.observacion,
            rp.estado,
            rp.fecha_creacion,
            rp.fecha_modificacion,
            (
                CASE
                    WHEN COALESCE(est.nombre, '') IN ('RETORNADO', 'CERRADO') THEN FALSE
                    WHEN rp.id_comprobante_compra IS NOT NULL THEN FALSE
                    WHEN EXISTS (
                        SELECT 1
                        FROM com_comprobante_compra c
                        WHERE c.id_recarga_planta = rp.id AND c.estado = 1
                    ) THEN FALSE
                    ELSE TRUE
                END
            ) AS puede_eliminar,
            (
                CASE
                    WHEN rp.id_comprobante_compra IS NOT NULL
                      OR EXISTS (
                          SELECT 1
                          FROM com_comprobante_compra c
                          WHERE c.id_recarga_planta = rp.id AND c.estado = 1
                      ) THEN 'tiene compra'
                    WHEN COALESCE(est.nombre, '') IN ('RETORNADO', 'CERRADO') THEN 'estado no permite'
                    ELSE NULL
                END
            ) AS motivo_bloqueo_eliminar
        FROM bal_recarga_planta rp
        LEFT JOIN cli_clientes prv ON prv.id = rp.id_proveedor
        LEFT JOIN gen_almacen a ON a.id = rp.id_almacen
        LEFT JOIN gen_lista_opciones est ON est.id = rp.id_estado
        LEFT JOIN gre_guia_remision gs ON gs.id = rp.id_guia_salida AND gs.estado = 1
        LEFT JOIN gre_guia_remision gi ON gi.id = rp.id_guia_retorno AND gi.estado = 1
        LEFT JOIN com_comprobante_compra cc ON cc.id = rp.id_comprobante_compra AND cc.estado = 1
        WHERE rp.estado = 1
          AND (p_id_proveedor IS NULL OR rp.id_proveedor = p_id_proveedor)
          AND (p_id_almacen IS NULL OR rp.id_almacen = p_id_almacen)
          AND (p_id_estado IS NULL OR rp.id_estado = p_id_estado)
          AND (p_fecha_desde IS NULL OR rp.fecha_salida >= p_fecha_desde)
          AND (p_fecha_hasta IS NULL OR rp.fecha_salida <= p_fecha_hasta)
          AND (
              p_busqueda = ''
              OR gen_texto_coincide(COALESCE(rp.numero, ''), p_busqueda)
              OR gen_texto_coincide(COALESCE(rp.lote, ''), p_busqueda)
              OR gen_texto_coincide(COALESCE(rp.serie_guia_salida, gs.serie, ''), p_busqueda)
              OR gen_texto_coincide(COALESCE(rp.numero_guia_salida, gs.numero, ''), p_busqueda)
              OR gen_texto_coincide(COALESCE(rp.serie_guia_ingreso, gi.serie, ''), p_busqueda)
              OR gen_texto_coincide(COALESCE(rp.numero_guia_ingreso, gi.numero, ''), p_busqueda)
              OR gen_texto_coincide(COALESCE(rp.serie_factura, cc.serie, ''), p_busqueda)
              OR gen_texto_coincide(COALESCE(rp.numero_factura, cc.numero, ''), p_busqueda)
              OR gen_texto_coincide(COALESCE(prv.razon_social, ''), p_busqueda)
              OR gen_texto_coincide(COALESCE(prv.nombres, ''), p_busqueda)
              OR gen_texto_coincide(COALESCE(a.nombre, ''), p_busqueda)
          )
        ORDER BY rp.fecha_salida DESC, rp.id DESC
        LIMIT p_limite
        OFFSET p_offset
    ) t;

    RETURN json_build_object('registros', v_registros, 'total', v_total);
END;
$$;


--
-- Name: bal_listar_recojos(character varying, integer, integer, integer, integer, character varying, date, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bal_listar_recojos(p_busqueda character varying DEFAULT ''::character varying, p_limite integer DEFAULT 10, p_offset integer DEFAULT 0, p_id_cliente integer DEFAULT NULL::integer, p_id_prestamo integer DEFAULT NULL::integer, p_estado_nombre character varying DEFAULT NULL::character varying, p_fecha_desde date DEFAULT NULL::date, p_fecha_hasta date DEFAULT NULL::date) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_registros JSON;
    v_total BIGINT;
    v_estado_nombre VARCHAR;
BEGIN
    SET TIME ZONE 'America/Lima';

    v_estado_nombre := NULLIF(UPPER(TRIM(p_estado_nombre)), '');

    SELECT COUNT(*)
    INTO v_total
    FROM bal_recojo r
    LEFT JOIN cli_clientes c ON c.id = r.id_cliente
    LEFT JOIN bal_prestamo pr ON pr.id = r.id_prestamo
    LEFT JOIN gen_lista_opciones er ON er.id = r.id_estado
    WHERE r.estado = 1
      AND (p_id_cliente IS NULL OR r.id_cliente = p_id_cliente)
      AND (p_id_prestamo IS NULL OR r.id_prestamo = p_id_prestamo)
      AND (v_estado_nombre IS NULL OR er.nombre = v_estado_nombre)
      AND (p_fecha_desde IS NULL OR r.fecha_programada >= p_fecha_desde)
      AND (p_fecha_hasta IS NULL OR r.fecha_programada <= p_fecha_hasta)
      AND (
          COALESCE(p_busqueda, '') = ''
          OR gen_texto_coincide(COALESCE(pr.numero_prestamo, ''), p_busqueda)
          OR gen_texto_coincide(COALESCE(c.razon_social, ''), p_busqueda)
          OR gen_texto_coincide(COALESCE(c.nombres, ''), p_busqueda)
          OR gen_texto_coincide(COALESCE(c.numero_documento, ''), p_busqueda)
          OR gen_texto_coincide(COALESCE(er.nombre, ''), p_busqueda)
          OR gen_texto_coincide(COALESCE(r.observacion, ''), p_busqueda)
      );

    SELECT COALESCE(json_agg(row_to_json(t)), '[]'::JSON)
    INTO v_registros
    FROM (
        SELECT
            r.id,
            r.id_cliente,
            COALESCE(
                NULLIF(TRIM(c.razon_social), ''),
                NULLIF(TRIM(CONCAT_WS(' ', c.nombres, c.apellido_paterno)), ''),
                c.numero_documento
            ) AS nombre_cliente,
            c.numero_documento AS documento_cliente,
            r.id_prestamo,
            pr.numero_prestamo,
            r.fecha_programada,
            r.hora_estimada,
            r.fecha_visita,
            r.id_usuario_responsable,
            ur.nombre AS nombre_usuario_responsable,
            r.id_estado,
            er.nombre AS nombre_estado,
            r.id_motivo_fallo,
            mf.nombre AS nombre_motivo_fallo,
            (
                SELECT COUNT(*)::INTEGER
                FROM bal_recojo_detalle rd
                WHERE rd.id_recojo = r.id AND rd.estado = 1
            ) AS total_detalles,
            r.observacion,
            r.estado,
            r.fecha_creacion,
            r.fecha_modificacion
        FROM bal_recojo r
        LEFT JOIN cli_clientes c ON c.id = r.id_cliente
        LEFT JOIN bal_prestamo pr ON pr.id = r.id_prestamo
        LEFT JOIN auth_usuarios ur ON ur.id = r.id_usuario_responsable
        LEFT JOIN gen_lista_opciones er ON er.id = r.id_estado
        LEFT JOIN gen_lista_opciones mf ON mf.id = r.id_motivo_fallo
        WHERE r.estado = 1
          AND (p_id_cliente IS NULL OR r.id_cliente = p_id_cliente)
          AND (p_id_prestamo IS NULL OR r.id_prestamo = p_id_prestamo)
          AND (v_estado_nombre IS NULL OR er.nombre = v_estado_nombre)
          AND (p_fecha_desde IS NULL OR r.fecha_programada >= p_fecha_desde)
          AND (p_fecha_hasta IS NULL OR r.fecha_programada <= p_fecha_hasta)
          AND (
              COALESCE(p_busqueda, '') = ''
              OR gen_texto_coincide(COALESCE(pr.numero_prestamo, ''), p_busqueda)
              OR gen_texto_coincide(COALESCE(c.razon_social, ''), p_busqueda)
              OR gen_texto_coincide(COALESCE(c.nombres, ''), p_busqueda)
              OR gen_texto_coincide(COALESCE(c.numero_documento, ''), p_busqueda)
              OR gen_texto_coincide(COALESCE(er.nombre, ''), p_busqueda)
              OR gen_texto_coincide(COALESCE(r.observacion, ''), p_busqueda)
          )
        ORDER BY r.fecha_programada DESC NULLS LAST, r.id DESC
        LIMIT p_limite
        OFFSET COALESCE(p_offset, 0)
    ) t;

    RETURN json_build_object('registros', v_registros, 'total', v_total);
END;
$$;


--
-- Name: bal_listar_recojos(character varying, integer, integer, integer, integer, integer, character varying, date, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bal_listar_recojos(p_busqueda character varying DEFAULT ''::character varying, p_limite integer DEFAULT 10, p_offset integer DEFAULT 0, p_id_cliente integer DEFAULT NULL::integer, p_id_prestamo integer DEFAULT NULL::integer, p_id_alquiler integer DEFAULT NULL::integer, p_estado_nombre character varying DEFAULT NULL::character varying, p_fecha_desde date DEFAULT NULL::date, p_fecha_hasta date DEFAULT NULL::date) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_registros JSON;
    v_total BIGINT;
    v_estado_nombre VARCHAR;
BEGIN
    SET TIME ZONE 'America/Lima';

    v_estado_nombre := NULLIF(UPPER(TRIM(p_estado_nombre)), '');

    SELECT COUNT(*)
    INTO v_total
    FROM bal_recojo r
    LEFT JOIN cli_clientes c ON c.id = r.id_cliente
    LEFT JOIN bal_prestamo pr ON pr.id = r.id_prestamo
    LEFT JOIN bal_alquiler al ON al.id = r.id_alquiler
    LEFT JOIN gen_lista_opciones er ON er.id = r.id_estado
    WHERE r.estado = 1
      AND (p_id_cliente IS NULL OR r.id_cliente = p_id_cliente)
      AND (p_id_prestamo IS NULL OR r.id_prestamo = p_id_prestamo)
      AND (p_id_alquiler IS NULL OR r.id_alquiler = p_id_alquiler)
      AND (v_estado_nombre IS NULL OR er.nombre = v_estado_nombre)
      AND (p_fecha_desde IS NULL OR r.fecha_programada >= p_fecha_desde)
      AND (p_fecha_hasta IS NULL OR r.fecha_programada <= p_fecha_hasta)
      AND (
          COALESCE(p_busqueda, '') = ''
          OR gen_texto_coincide(COALESCE(pr.numero_prestamo, ''), p_busqueda)
          OR gen_texto_coincide(COALESCE(al.numero_alquiler, ''), p_busqueda)
          OR gen_texto_coincide(COALESCE(c.razon_social, ''), p_busqueda)
          OR gen_texto_coincide(COALESCE(c.nombres, ''), p_busqueda)
          OR gen_texto_coincide(COALESCE(c.numero_documento, ''), p_busqueda)
          OR gen_texto_coincide(COALESCE(er.nombre, ''), p_busqueda)
          OR gen_texto_coincide(COALESCE(r.observacion, ''), p_busqueda)
      );

    SELECT COALESCE(json_agg(row_to_json(t)), '[]'::JSON)
    INTO v_registros
    FROM (
        SELECT
            r.id,
            r.id_cliente,
            COALESCE(
                NULLIF(TRIM(c.razon_social), ''),
                NULLIF(TRIM(CONCAT_WS(' ', c.nombres, c.apellido_paterno)), ''),
                c.numero_documento
            ) AS nombre_cliente,
            c.numero_documento AS documento_cliente,
            dir.latitud,
            dir.longitud,
            dir.direccion,
            r.id_prestamo,
            pr.numero_prestamo,
            r.id_alquiler,
            al.numero_alquiler,
            CASE
                WHEN r.id_prestamo IS NOT NULL AND r.id_alquiler IS NOT NULL THEN 'MIXTO'
                WHEN r.id_alquiler IS NOT NULL THEN 'ALQUILER'
                ELSE 'PRESTAMO'
            END AS tipo_origen,
            r.fecha_programada,
            r.hora_estimada,
            r.fecha_visita,
            r.id_usuario_responsable,
            ur.nombre AS nombre_usuario_responsable,
            r.id_estado,
            er.nombre AS nombre_estado,
            r.id_motivo_fallo,
            mf.nombre AS nombre_motivo_fallo,
            (
                SELECT COUNT(*)::INTEGER
                FROM bal_recojo_detalle rd
                WHERE rd.id_recojo = r.id AND rd.estado = 1
            ) AS total_detalles,
            CASE
                WHEN r.id_alquiler IS NOT NULL
                     AND COALESCE(al.id_producto_regulador, al.id_producto_stock) IS NOT NULL
                THEN TRUE
                ELSE FALSE
            END AS tiene_regulador,
            CASE
                WHEN r.id_alquiler IS NOT NULL
                     AND COALESCE(al.id_producto_regulador, al.id_producto_stock) IS NOT NULL
                     AND NOT EXISTS (
                         SELECT 1
                         FROM bal_recojo_detalle rd0
                         WHERE rd0.id_recojo = r.id AND rd0.estado = 1
                     )
                THEN TRUE
                ELSE FALSE
            END AS es_solo_regulador,
            r.observacion,
            r.estado,
            r.fecha_creacion,
            r.fecha_modificacion
        FROM bal_recojo r
        LEFT JOIN cli_clientes c ON c.id = r.id_cliente
        LEFT JOIN bal_prestamo pr ON pr.id = r.id_prestamo
        LEFT JOIN bal_alquiler al ON al.id = r.id_alquiler
        LEFT JOIN auth_usuarios ur ON ur.id = r.id_usuario_responsable
        LEFT JOIN gen_lista_opciones er ON er.id = r.id_estado
        LEFT JOIN gen_lista_opciones mf ON mf.id = r.id_motivo_fallo
        LEFT JOIN LATERAL (
            SELECT cd.latitud, cd.longitud, cd.direccion
            FROM cli_direcciones cd
            WHERE cd.id_cliente = r.id_cliente
              AND cd.es_principal = TRUE
              AND cd.estado = 1
            ORDER BY cd.id DESC
            LIMIT 1
        ) dir ON TRUE
        WHERE r.estado = 1
          AND (p_id_cliente IS NULL OR r.id_cliente = p_id_cliente)
          AND (p_id_prestamo IS NULL OR r.id_prestamo = p_id_prestamo)
          AND (p_id_alquiler IS NULL OR r.id_alquiler = p_id_alquiler)
          AND (v_estado_nombre IS NULL OR er.nombre = v_estado_nombre)
          AND (p_fecha_desde IS NULL OR r.fecha_programada >= p_fecha_desde)
          AND (p_fecha_hasta IS NULL OR r.fecha_programada <= p_fecha_hasta)
          AND (
              COALESCE(p_busqueda, '') = ''
              OR gen_texto_coincide(COALESCE(pr.numero_prestamo, ''), p_busqueda)
              OR gen_texto_coincide(COALESCE(al.numero_alquiler, ''), p_busqueda)
              OR gen_texto_coincide(COALESCE(c.razon_social, ''), p_busqueda)
              OR gen_texto_coincide(COALESCE(c.nombres, ''), p_busqueda)
              OR gen_texto_coincide(COALESCE(c.numero_documento, ''), p_busqueda)
              OR gen_texto_coincide(COALESCE(er.nombre, ''), p_busqueda)
              OR gen_texto_coincide(COALESCE(r.observacion, ''), p_busqueda)
          )
        ORDER BY r.fecha_programada DESC NULLS LAST, r.id DESC
        LIMIT p_limite
        OFFSET COALESCE(p_offset, 0)
    ) t;

    RETURN json_build_object('registros', v_registros, 'total', v_total);
END;
$$;


--
-- Name: bal_listar_rutas_pueblo(character varying, integer, integer, character varying, integer, date, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bal_listar_rutas_pueblo(p_busqueda character varying DEFAULT ''::character varying, p_limite integer DEFAULT 10, p_offset integer DEFAULT 0, p_estado_nombre character varying DEFAULT NULL::character varying, p_id_almacen integer DEFAULT NULL::integer, p_fecha_desde date DEFAULT NULL::date, p_fecha_hasta date DEFAULT NULL::date) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_registros JSON;
    v_total BIGINT;
    v_estado_nombre VARCHAR;
BEGIN
    SET TIME ZONE 'America/Lima';

    v_estado_nombre := NULLIF(UPPER(TRIM(p_estado_nombre)), '');

    SELECT COUNT(*)
    INTO v_total
    FROM bal_ruta_pueblo r
    LEFT JOIN gen_almacen a ON a.id = r.id_almacen
    LEFT JOIN auth_usuarios u ON u.id = r.id_usuario_responsable
    LEFT JOIN gen_chofer ch ON ch.id = r.id_chofer
    LEFT JOIN gen_lista_opciones er ON er.id = r.id_estado
    WHERE r.estado = 1
      AND (p_id_almacen IS NULL OR r.id_almacen = p_id_almacen)
      AND (v_estado_nombre IS NULL OR er.nombre = v_estado_nombre)
      AND (p_fecha_desde IS NULL OR r.fecha >= p_fecha_desde)
      AND (p_fecha_hasta IS NULL OR r.fecha <= p_fecha_hasta)
      AND (
          COALESCE(p_busqueda, '') = ''
          OR gen_texto_coincide(COALESCE(a.nombre, ''), p_busqueda)
          OR gen_texto_coincide(COALESCE(u.nombre, ''), p_busqueda)
          OR gen_texto_coincide(COALESCE(CONCAT_WS(' ', ch.nombres, ch.apellido_paterno), ''), p_busqueda)
          OR gen_texto_coincide(COALESCE(er.nombre, ''), p_busqueda)
          OR gen_texto_coincide(COALESCE(r.observacion, ''), p_busqueda)
      );

    SELECT COALESCE(json_agg(row_to_json(t)), '[]'::JSON)
    INTO v_registros
    FROM (
        SELECT
            r.id,
            r.fecha,
            r.id_almacen,
            a.nombre AS nombre_almacen,
            r.id_usuario_responsable,
            u.nombre AS nombre_usuario_responsable,
            r.id_chofer,
            NULLIF(TRIM(CONCAT_WS(' ', ch.nombres, ch.apellido_paterno, ch.apellido_materno)), '') AS nombre_chofer,
            r.factor_lb_m3,
            r.tolerancia_m3,
            r.m3_reportado_ventas,
            r.m3_calculado,
            r.descuadre_m3,
            r.id_estado,
            er.nombre AS nombre_estado,
            r.observacion,
            (
                SELECT COUNT(*)::INT
                FROM bal_ruta_pueblo_detalle d
                WHERE d.id_ruta_pueblo = r.id AND d.estado = 1
            ) AS total_cilindros,
            (
                SELECT COUNT(*)::INT
                FROM bal_ruta_pueblo_detalle d
                WHERE d.id_ruta_pueblo = r.id AND d.estado = 1 AND d.lb_retorno IS NOT NULL
            ) AS total_retornados
        FROM bal_ruta_pueblo r
        LEFT JOIN gen_almacen a ON a.id = r.id_almacen
        LEFT JOIN auth_usuarios u ON u.id = r.id_usuario_responsable
        LEFT JOIN gen_chofer ch ON ch.id = r.id_chofer
        LEFT JOIN gen_lista_opciones er ON er.id = r.id_estado
        WHERE r.estado = 1
          AND (p_id_almacen IS NULL OR r.id_almacen = p_id_almacen)
          AND (v_estado_nombre IS NULL OR er.nombre = v_estado_nombre)
          AND (p_fecha_desde IS NULL OR r.fecha >= p_fecha_desde)
          AND (p_fecha_hasta IS NULL OR r.fecha <= p_fecha_hasta)
          AND (
              COALESCE(p_busqueda, '') = ''
              OR gen_texto_coincide(COALESCE(a.nombre, ''), p_busqueda)
              OR gen_texto_coincide(COALESCE(u.nombre, ''), p_busqueda)
              OR gen_texto_coincide(COALESCE(CONCAT_WS(' ', ch.nombres, ch.apellido_paterno), ''), p_busqueda)
              OR gen_texto_coincide(COALESCE(er.nombre, ''), p_busqueda)
              OR gen_texto_coincide(COALESCE(r.observacion, ''), p_busqueda)
          )
        ORDER BY r.fecha DESC, r.id DESC
        LIMIT GREATEST(COALESCE(p_limite, 10), 1)
        OFFSET GREATEST(COALESCE(p_offset, 0), 0)
    ) t;

    RETURN json_build_object('registros', v_registros, 'total', v_total);
END;
$$;


--
-- Name: bal_listar_solicitudes_baja(character varying, integer, integer, character varying); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bal_listar_solicitudes_baja(p_busqueda character varying DEFAULT ''::character varying, p_limite integer DEFAULT 10, p_offset integer DEFAULT 0, p_estado_aprobacion character varying DEFAULT NULL::character varying) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_registros JSON;
    v_total BIGINT;
    v_estado VARCHAR := NULLIF(UPPER(TRIM(COALESCE(p_estado_aprobacion, ''))), '');
BEGIN
    SET TIME ZONE 'America/Lima';

    IF v_estado = 'TODOS' THEN
        v_estado := NULL;
    END IF;

    SELECT COUNT(*) INTO v_total
    FROM bal_baja_balon bb
    INNER JOIN bal_balon b ON bb.id_balon = b.id
    LEFT JOIN gen_lista_opciones mb ON bb.id_motivo_baja = mb.id
    LEFT JOIN auth_usuarios us ON bb.id_usuario_solicita = us.id
    WHERE bb.estado = 1
      AND (v_estado IS NULL OR bb.estado_aprobacion = v_estado)
      AND (
          p_busqueda = ''
          OR gen_texto_coincide(b.codigo_balon, p_busqueda)
          OR gen_texto_coincide(COALESCE(b.numero_serie, ''), p_busqueda)
          OR gen_texto_coincide(COALESCE(mb.nombre, ''), p_busqueda)
          OR gen_texto_coincide(COALESCE(us.nombre, ''), p_busqueda)
      );

    SELECT COALESCE(json_agg(row_to_json(t)), '[]'::JSON) INTO v_registros
    FROM (
        SELECT
            bb.id,
            bb.id_balon,
            b.codigo_balon,
            b.numero_serie,
            bb.id_motivo_baja,
            mb.nombre AS nombre_motivo_baja,
            bb.fecha_baja,
            bb.motivo_detalle,
            bb.id_cliente_comprador,
            cc.razon_social AS nombre_cliente_comprador,
            bb.serie_comprobante,
            bb.numero_comprobante,
            bb.monto_venta,
            bb.observacion,
            bb.id_usuario_solicita,
            us.nombre AS nombre_usuario_solicita,
            bb.estado_aprobacion,
            bb.fecha_creacion
        FROM bal_baja_balon bb
        INNER JOIN bal_balon b ON bb.id_balon = b.id
        LEFT JOIN gen_lista_opciones mb ON bb.id_motivo_baja = mb.id
        LEFT JOIN cli_clientes cc ON bb.id_cliente_comprador = cc.id
        LEFT JOIN auth_usuarios us ON bb.id_usuario_solicita = us.id
        WHERE bb.estado = 1
          AND (v_estado IS NULL OR bb.estado_aprobacion = v_estado)
          AND (
              p_busqueda = ''
              OR gen_texto_coincide(b.codigo_balon, p_busqueda)
              OR gen_texto_coincide(COALESCE(b.numero_serie, ''), p_busqueda)
              OR gen_texto_coincide(COALESCE(mb.nombre, ''), p_busqueda)
              OR gen_texto_coincide(COALESCE(us.nombre, ''), p_busqueda)
          )
        -- Pendientes primero, luego más recientes
        ORDER BY
            CASE WHEN bb.estado_aprobacion = 'PENDIENTE' THEN 0 ELSE 1 END ASC,
            bb.fecha_creacion DESC,
            bb.id DESC
        LIMIT p_limite
        OFFSET p_offset
    ) t;

    RETURN json_build_object('registros', v_registros, 'total', v_total);
END;
$$;


--
-- Name: bal_listar_stock_gas(character varying, integer, integer, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bal_listar_stock_gas(p_busqueda character varying DEFAULT ''::character varying, p_limite integer DEFAULT 10, p_offset integer DEFAULT 0, p_id_almacen integer DEFAULT NULL::integer, p_id_producto_gas integer DEFAULT NULL::integer) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_registros JSON;
    v_total BIGINT;
    v_resumen JSON;
BEGIN
    SET TIME ZONE 'America/Lima';

    WITH filtrado AS (
        SELECT
            p.id AS id_producto_gas,
            p.codigo AS codigo_producto,
            p.nombre AS nombre_producto,
            um.nombre AS nombre_unidad_medida,
            s.id_almacen,
            al.nombre AS nombre_almacen,
            COALESCE(s.stock, 0) AS capacidad_disponible,
            COALESCE(s.stock_minimo, 0) AS stock_minimo,
            (COALESCE(s.stock, 0) <= COALESCE(s.stock_minimo, 0)) AS bajo_minimo
        FROM pro_producto p
        LEFT JOIN gen_lista_opciones um ON um.id = p.id_unidad_medida
        INNER JOIN pro_stock s ON s.id_producto = p.id AND s.estado = 1
        INNER JOIN gen_almacen al ON al.id = s.id_almacen AND al.estado = 1
        WHERE p.estado = 1
          AND COALESCE(p.es_gas, FALSE) = TRUE
          AND (p_id_producto_gas IS NULL OR p.id = p_id_producto_gas)
          AND (p_id_almacen IS NULL OR s.id_almacen = p_id_almacen)
          AND (
              p_busqueda = ''
              OR gen_texto_coincide(COALESCE(p.codigo, ''), p_busqueda)
              OR gen_texto_coincide(COALESCE(p.nombre, ''), p_busqueda)
              OR gen_texto_coincide(COALESCE(al.nombre, ''), p_busqueda)
          )
    )
    SELECT
        (SELECT COUNT(*) FROM filtrado),
        (
            SELECT COALESCE(json_agg(row_to_json(t)), '[]'::JSON)
            FROM (
                SELECT *
                FROM filtrado
                ORDER BY
                    CASE WHEN capacidad_disponible > 0 THEN 0 ELSE 1 END,
                    nombre_producto ASC,
                    nombre_almacen ASC NULLS LAST
                LIMIT p_limite
                OFFSET p_offset
            ) t
        ),
        (
            SELECT json_build_object(
                'total_productos', COUNT(*),
                'capacidad_disponible', COALESCE(SUM(capacidad_disponible), 0),
                'bajo_minimo', COUNT(*) FILTER (WHERE bajo_minimo)
            )
            FROM filtrado
        )
    INTO v_total, v_registros, v_resumen;

    RETURN json_build_object(
        'registros', v_registros,
        'total', v_total,
        'resumen', v_resumen
    );
END;
$$;


--
-- Name: bal_listar_tipos_balon(character varying, integer, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bal_listar_tipos_balon(p_busqueda character varying DEFAULT ''::character varying, p_limite integer DEFAULT 10, p_offset integer DEFAULT 0, p_id_gas integer DEFAULT NULL::integer) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_registros JSON;
    v_total BIGINT;
BEGIN
    SET TIME ZONE 'America/Lima';

    SELECT COUNT(*) INTO v_total
    FROM bal_tipo_balon tb
    LEFT JOIN pro_producto g ON tb.id_gas = g.id
    WHERE tb.estado = 1
      AND (p_id_gas IS NULL OR tb.id_gas = p_id_gas)
      AND (
          p_busqueda = ''
          OR gen_texto_coincide(tb.nombre, p_busqueda)
          OR gen_texto_coincide(COALESCE(g.nombre, ''), p_busqueda)
      );

    SELECT COALESCE(json_agg(row_to_json(t)), '[]'::JSON) INTO v_registros
    FROM (
        SELECT
            tb.id,
            tb.nombre,
            tb.id_gas,
            g.nombre AS nombre_gas,
            tb.capacidad,
            tb.capacidad_lb,
            tb.id_unidad_medida,
            um.nombre AS nombre_unidad_medida,
            tb.peso,
            tb.peso_tara_lb,
            tb.presion_llenado_psi,
            tb.vigencia_ph_anios,
            tb.estado,
            tb.fecha_creacion,
            tb.fecha_modificacion,
            (
                SELECT COUNT(*)::INTEGER
                FROM bal_balon b
                WHERE b.id_tipo_balon = tb.id AND b.estado = 1
            ) AS total_balones
        FROM bal_tipo_balon tb
        LEFT JOIN pro_producto g ON tb.id_gas = g.id
        LEFT JOIN gen_lista_opciones um ON tb.id_unidad_medida = um.id
        WHERE tb.estado = 1
          AND (p_id_gas IS NULL OR tb.id_gas = p_id_gas)
          AND (
              p_busqueda = ''
              OR gen_texto_coincide(tb.nombre, p_busqueda)
              OR gen_texto_coincide(COALESCE(g.nombre, ''), p_busqueda)
          )
        ORDER BY tb.nombre ASC
        LIMIT p_limite
        OFFSET p_offset
    ) t;

    RETURN json_build_object('registros', v_registros, 'total', v_total);
END;
$$;


--
-- Name: bal_m3_desde_psi(integer, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bal_m3_desde_psi(p_id_tipo_balon integer, p_psi numeric) RETURNS numeric
    LANGUAGE plpgsql STABLE
    AS $$
DECLARE
    v_cap NUMERIC;
    v_psi_lleno NUMERIC;
BEGIN
    IF p_id_tipo_balon IS NULL OR p_psi IS NULL OR p_psi < 0 THEN
        RETURN NULL;
    END IF;

    SELECT tb.capacidad, tb.presion_llenado_psi
    INTO v_cap, v_psi_lleno
    FROM bal_tipo_balon tb
    WHERE tb.id = p_id_tipo_balon AND tb.estado = 1;

    IF v_cap IS NULL OR v_cap <= 0 OR v_psi_lleno IS NULL OR v_psi_lleno <= 0 THEN
        RETURN NULL;
    END IF;

    RETURN ROUND(v_cap * LEAST(p_psi / v_psi_lleno, 1), 4);
END;
$$;


--
-- Name: bal_movimiento_aplicar_snapshot(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bal_movimiento_aplicar_snapshot() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_tipo TEXT;
    v_estado_codigo TEXT;
    v_contenido_codigo TEXT;
    v_id_estado INTEGER;
    v_id_contenido INTEGER;
    v_id_contenido_actual INTEGER;
    v_almacen INTEGER;
    v_cliente INTEGER;
BEGIN
    SELECT lo.nombre INTO v_tipo
    FROM gen_lista_opciones lo
    WHERE lo.id = NEW.id_tipo_movimiento;

    v_estado_codigo := NULL;
    v_contenido_codigo := NULL;
    v_almacen := NULL;
    v_cliente := NULL;

    CASE v_tipo
        WHEN 'SALIDA_PRESTAMO' THEN
            v_estado_codigo := 'PRESTADO_CLIENTE';
            v_cliente := NEW.id_cliente;
            v_contenido_codigo := 'LLENO';
        WHEN 'SALIDA_ALQUILER' THEN
            v_estado_codigo := 'ALQUILADO';
            v_cliente := NEW.id_cliente;
            v_contenido_codigo := 'LLENO';
        WHEN 'SALIDA_VENTA' THEN
            v_estado_codigo := 'EN_PODER_CLIENTE';
            v_cliente := NEW.id_cliente;
            v_contenido_codigo := 'LLENO';
        WHEN 'SALIDA_ENTREGA_CLIENTE' THEN
            v_estado_codigo := 'EN_PODER_CLIENTE';
            v_cliente := NEW.id_cliente;
            v_contenido_codigo := 'LLENO';
        WHEN 'SALIDA_MANTENIMIENTO' THEN
            v_estado_codigo := 'EN_MANTENIMIENTO';
            v_almacen := COALESCE(NEW.id_almacen_destino, NEW.id_almacen_origen);
        WHEN 'SALIDA_PLANTA_EXTERNA' THEN
            v_estado_codigo := 'EN_RECARGA_EXTERNA';
            v_contenido_codigo := 'VACIO';
        WHEN 'ENTRADA_DEVOLUCION' THEN
            v_estado_codigo := 'EN_ALMACEN';
            v_almacen := COALESCE(NEW.id_almacen_destino, NEW.id_almacen_origen);
            v_contenido_codigo := 'VACIO';
        WHEN 'ENTRADA_MANTENIMIENTO' THEN
            v_estado_codigo := 'EN_ALMACEN';
            v_almacen := COALESCE(NEW.id_almacen_destino, NEW.id_almacen_origen);
        WHEN 'ENTRADA_LLENADO' THEN
            v_estado_codigo := 'EN_ALMACEN';
            v_almacen := COALESCE(NEW.id_almacen_destino, NEW.id_almacen_origen);
            v_contenido_codigo := 'LLENO';
        WHEN 'ENTRADA_PLANTA_EXTERNA' THEN
            v_estado_codigo := 'EN_ALMACEN';
            v_almacen := COALESCE(NEW.id_almacen_destino, NEW.id_almacen_origen);
            v_contenido_codigo := 'LLENO';
        WHEN 'RECARGA_CLIENTE' THEN
            v_estado_codigo := 'EN_PODER_CLIENTE';
            v_cliente := NEW.id_cliente;
            v_contenido_codigo := 'DESCONOCIDO';
        WHEN 'TRASLADO_LIMA' THEN
            v_estado_codigo := 'EN_RUTA_LIMA';
        WHEN 'RETORNO_LIMA' THEN
            v_estado_codigo := 'EN_ALMACEN';
            v_almacen := COALESCE(NEW.id_almacen_destino, NEW.id_almacen_origen);
        ELSE
            NULL;
    END CASE;

    IF v_estado_codigo IS NOT NULL THEN
        SELECT lo.id INTO v_id_estado
        FROM gen_lista_opciones lo
        INNER JOIN gen_lista l ON l.id = lo.id_lista
        WHERE l.nombre = 'EstadoBalon'
          AND lo.nombre = v_estado_codigo
          AND lo.estado = 1
        LIMIT 1;
        NEW.id_estado_balon := v_id_estado;
    ELSE
        NEW.id_estado_balon := NULL;
    END IF;

    NEW.id_almacen_ubicacion := v_almacen;
    NEW.id_cliente_ubicacion := v_cliente;

    RETURN NEW;
END;
$$;


--
-- Name: bal_obtener_alquiler(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bal_obtener_alquiler(p_id integer) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_registro JSON;
BEGIN
    SET TIME ZONE 'America/Lima';

    SELECT row_to_json(t) INTO v_registro
    FROM (
        SELECT
            al.id,
            al.numero_alquiler,
            al.id_cliente,
            COALESCE(
                NULLIF(TRIM(c.razon_social), ''),
                NULLIF(TRIM(CONCAT_WS(' ', c.nombres, c.apellido_paterno, c.apellido_materno)), ''),
                c.numero_documento
            ) AS nombre_cliente,
            al.id_almacen,
            a.nombre AS nombre_almacen,
            al.fecha_inicio,
            al.fecha_fin_pactada,
            al.fecha_fin_real,
            al.tarifa_diaria,
            al.total_cobrado,
            al.id_estado,
            ea.nombre AS nombre_estado,
            al.observacion,
            al.id_comprobante_venta,
            cv.serie AS serie_comprobante_venta,
            cv.numero AS numero_comprobante_venta,
            cv.fecha AS fecha_comprobante_venta,
            cv_cli.razon_social AS nombre_cliente_comprobante_venta,
            cv.total_importe AS total_comprobante_venta,
            al.id_producto_regulador,
            pr.codigo AS codigo_producto_regulador,
            pr.nombre AS nombre_producto_regulador,
            al.id_producto_stock,
            ps.codigo AS codigo_producto_stock,
            ps.nombre AS nombre_producto_stock,
            al.dias_periodo,
            al.estado,
            al.fecha_creacion,
            al.fecha_modificacion,
            al.id_usuario_creacion,
            uc.nombre AS nombre_usuario_creacion,
            al.id_usuario_modificacion,
            um.nombre AS nombre_usuario_modificacion,
            (
                SELECT COUNT(*)::INTEGER
                FROM bal_alquiler_detalle ad
                WHERE ad.id_alquiler = al.id AND ad.estado = 1
            ) AS total_detalles
        FROM bal_alquiler al
        INNER JOIN cli_clientes c ON al.id_cliente = c.id
        INNER JOIN gen_almacen a ON al.id_almacen = a.id
        LEFT JOIN gen_lista_opciones ea ON al.id_estado = ea.id
        LEFT JOIN ven_comprobante cv ON al.id_comprobante_venta = cv.id
        LEFT JOIN cli_clientes cv_cli ON cv.id_cliente = cv_cli.id
        LEFT JOIN pro_producto pr ON al.id_producto_regulador = pr.id
        LEFT JOIN pro_producto ps ON al.id_producto_stock = ps.id
        LEFT JOIN auth_usuarios uc ON al.id_usuario_creacion = uc.id
        LEFT JOIN auth_usuarios um ON al.id_usuario_modificacion = um.id
        WHERE al.id = p_id AND al.estado = 1
    ) t;

    RETURN json_build_object('registro', v_registro);
END;
$$;


--
-- Name: bal_obtener_alquiler_detalle(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bal_obtener_alquiler_detalle(p_id integer) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_registro JSON;
BEGIN
