            ad.id_alquiler,
            al.numero_alquiler,
            ad.id_balon,
            b.codigo_balon,
            ad.fecha_devolucion,
            ad.estado,
            ad.fecha_creacion,
            ad.fecha_modificacion,
            ad.id_usuario_creacion,
            uc.nombre AS nombre_usuario_creacion,
            ad.id_usuario_modificacion,
            um.nombre AS nombre_usuario_modificacion
        FROM bal_alquiler_detalle ad
        INNER JOIN bal_alquiler al ON ad.id_alquiler = al.id
        INNER JOIN bal_balon b ON ad.id_balon = b.id
        LEFT JOIN auth_usuarios uc ON ad.id_usuario_creacion = uc.id
        LEFT JOIN auth_usuarios um ON ad.id_usuario_modificacion = um.id
        WHERE ad.id = p_id AND ad.estado = 1
    ) t;

    RETURN json_build_object('registro', v_registro);
END;
$$;


--
-- Name: bal_obtener_baja_balon(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bal_obtener_baja_balon(p_id integer) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_registro JSON;
BEGIN
    SET TIME ZONE 'America/Lima';

    SELECT row_to_json(t) INTO v_registro
    FROM (
        SELECT
            bb.id,
            bb.id_balon,
            b.codigo_balon,
            b.numero_serie,
            bb.id_motivo_baja,
            mb.nombre AS nombre_motivo_baja,
            bb.fecha_baja,
            bb.motivo_detalle,
            bb.id_cliente_comprador,
            cc.razon_social AS nombre_cliente_comprador,
            bb.id_comprobante_venta,
            bb.serie_comprobante,
            bb.numero_comprobante,
            bb.monto_venta,
            bb.id_movimiento,
            bb.observacion,
            bb.id_usuario_solicita,
            us.nombre AS nombre_usuario_solicita,
            bb.id_usuario_autoriza,
            ua.nombre AS nombre_usuario_autoriza,
            bb.fecha_autorizacion,
            bb.estado_aprobacion,
            bb.estado,
            bb.fecha_creacion,
            bb.fecha_modificacion
        FROM bal_baja_balon bb
        INNER JOIN bal_balon b ON bb.id_balon = b.id
        LEFT JOIN gen_lista_opciones mb ON bb.id_motivo_baja = mb.id
        LEFT JOIN cli_clientes cc ON bb.id_cliente_comprador = cc.id
        LEFT JOIN auth_usuarios us ON bb.id_usuario_solicita = us.id
        LEFT JOIN auth_usuarios ua ON bb.id_usuario_autoriza = ua.id
        WHERE bb.id = p_id
    ) t;

    RETURN json_build_object('registro', v_registro);
END;
$$;


--
-- Name: bal_obtener_baja_por_balon(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bal_obtener_baja_por_balon(p_id_balon integer) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_id INTEGER;
BEGIN
    SET TIME ZONE 'America/Lima';

    SELECT id INTO v_id
    FROM bal_baja_balon
    WHERE id_balon = p_id_balon AND estado = 1 AND estado_aprobacion = 'APROBADA'
    ORDER BY id DESC
    LIMIT 1;

    IF v_id IS NULL THEN
        RETURN json_build_object('registro', NULL);
    END IF;

    RETURN bal_obtener_baja_balon(v_id);
END;
$$;


--
-- Name: bal_obtener_balon(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bal_obtener_balon(p_id integer) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_registro JSON;
BEGIN
    SET TIME ZONE 'America/Lima';

    SELECT row_to_json(t) INTO v_registro
    FROM (
        SELECT
            b.id,
            b.codigo_balon,
            b.numero_serie,
            b.libro_cilindro,
            b.pagina_libro,
            b.fecha_registro,
            b.id_almacen,
            a.nombre AS nombre_almacen,
            b.id_cliente_ubicacion,
            cu.razon_social AS nombre_cliente_ubicacion,
            b.id_propietario,
            prop.nombre AS nombre_propietario,
            b.id_cliente_propietario,
            cp.razon_social AS nombre_cliente_propietario,
            b.id_referencia,
            ref.nombre AS nombre_referencia,
            b.id_marca_cilindro,
            mc.nombre AS nombre_marca_cilindro,
            b.id_organo_inspector,
            oi.nombre AS nombre_organo_inspector,
            b.organo_inspector_no_aplica,
            b.id_planta,
            COALESCE(pl.razon_social, TRIM(CONCAT_WS(' ', pl.nombres, pl.apellido_paterno))) AS nombre_planta,
            b.id_tipo_balon,
            tb.nombre AS nombre_tipo_balon,
            tb.capacidad,
            tb.capacidad_lb,
            tb.peso AS peso_tipo_balon,
            b.peso_aproximado_kg,
            COALESCE(b.peso_aproximado_kg, tb.peso) AS peso_guia_kg,
            b.sello_inspeccion,
            um.nombre AS nombre_unidad_medida,
            tb.vigencia_ph_anios AS vigencia_ph_tipo_anios,
            b.id_producto_gas,
            pg.nombre AS nombre_producto_gas,
            b.id_estado_balon,
            eb.nombre AS nombre_estado_balon,
            b.fecha_ultima_prueba_hidrostatica,
            b.vigencia_prueba_hidrostatica_anios,
            b.fecha_proxima_prueba_hidrostatica,
            CASE
                WHEN b.fecha_proxima_prueba_hidrostatica IS NULL THEN NULL
                WHEN b.fecha_proxima_prueba_hidrostatica < CURRENT_DATE THEN 'VENCIDA'
                WHEN b.fecha_proxima_prueba_hidrostatica <= CURRENT_DATE + INTERVAL '90 days' THEN 'POR_VENCER'
                ELSE 'VIGENTE'
            END AS estado_ph,
            b.fecha_fabricacion,
            b.anio_fabricacion,
            b.mes_fabricacion,
            b.numero_recepcion,
            b.presion_actual,
            b.observacion,
            b.tipo_valvula,
            b.estado,
            b.fecha_creacion,
            b.fecha_modificacion,
            b.id_usuario_creacion,
            uc.nombre AS nombre_usuario_creacion,
            b.id_usuario_modificacion,
            umu.nombre AS nombre_usuario_modificacion,
            EXISTS (
                SELECT 1
                FROM bal_baja_balon bb
                WHERE bb.id_balon = b.id
                  AND bb.estado = 1
                  AND bb.estado_aprobacion = 'PENDIENTE'
            ) AS tiene_solicitud_baja_pendiente,
            (
                SELECT row_to_json(bj)
                FROM (
                    SELECT
                        bb.id,
                        bb.id_motivo_baja,
                        mb.nombre AS nombre_motivo_baja,
                        bb.fecha_baja,
                        bb.motivo_detalle,
                        bb.id_cliente_comprador,
                        cc.razon_social AS nombre_cliente_comprador,
                        bb.serie_comprobante,
                        bb.numero_comprobante,
                        bb.monto_venta,
                        bb.observacion,
                        bb.id_usuario_solicita,
                        us.nombre AS nombre_usuario_solicita,
                        bb.id_usuario_autoriza,
                        ua.nombre AS nombre_usuario_autoriza,
                        bb.fecha_autorizacion,
                        bb.estado_aprobacion
                    FROM bal_baja_balon bb
                    LEFT JOIN gen_lista_opciones mb ON bb.id_motivo_baja = mb.id
                    LEFT JOIN cli_clientes cc ON bb.id_cliente_comprador = cc.id
                    LEFT JOIN auth_usuarios us ON bb.id_usuario_solicita = us.id
                    LEFT JOIN auth_usuarios ua ON bb.id_usuario_autoriza = ua.id
                    WHERE bb.id_balon = b.id AND bb.estado = 1 AND bb.estado_aprobacion = 'APROBADA'
                    ORDER BY bb.fecha_autorizacion DESC NULLS LAST, bb.id DESC
                    LIMIT 1
                ) bj
            ) AS baja
        FROM bal_balon b
        LEFT JOIN gen_almacen a ON b.id_almacen = a.id
        LEFT JOIN cli_clientes cu ON b.id_cliente_ubicacion = cu.id
        LEFT JOIN gen_lista_opciones prop ON b.id_propietario = prop.id
        LEFT JOIN cli_clientes cp ON b.id_cliente_propietario = cp.id
        LEFT JOIN gen_lista_opciones ref ON b.id_referencia = ref.id
        LEFT JOIN gen_lista_opciones mc ON b.id_marca_cilindro = mc.id
        LEFT JOIN gen_lista_opciones oi ON b.id_organo_inspector = oi.id
        LEFT JOIN cli_clientes pl ON b.id_planta = pl.id
        LEFT JOIN bal_tipo_balon tb ON b.id_tipo_balon = tb.id
        LEFT JOIN gen_lista_opciones um ON tb.id_unidad_medida = um.id
        LEFT JOIN pro_producto pg ON b.id_producto_gas = pg.id
        LEFT JOIN gen_lista_opciones eb ON b.id_estado_balon = eb.id
        LEFT JOIN auth_usuarios uc ON b.id_usuario_creacion = uc.id
        LEFT JOIN auth_usuarios umu ON b.id_usuario_modificacion = umu.id
        WHERE b.id = p_id AND b.estado = 1
    ) t;

    RETURN json_build_object('registro', v_registro);
END;
$$;


--
-- Name: bal_obtener_mantenimiento(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bal_obtener_mantenimiento(p_id integer) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_registro JSON;
BEGIN
    SET TIME ZONE 'America/Lima';

    SELECT row_to_json(t) INTO v_registro
    FROM (
        SELECT
            m.id,
            m.id_balon,
            b.codigo_balon,
            m.id_producto,
            p.codigo AS codigo_producto,
            p.nombre AS nombre_producto,
            CASE
                WHEN m.id_producto IS NOT NULL THEN 'PRODUCTO'
                ELSE 'CILINDRO'
            END AS tipo_origen,
            m.id_almacen,
            m.id_alquiler,
            m.id_recojo,
            b.id_propietario,
            prop.nombre AS nombre_propietario,
            b.id_cliente_propietario,
            cp.razon_social AS nombre_cliente_propietario,
            b.id_cliente_ubicacion,
            m.id_tipo_mantenimiento,
            tm.nombre AS nombre_tipo_mantenimiento,
            m.fecha_ingreso,
            m.fecha_salida,
            m.descripcion,
            m.costo,
            m.es_externo,
            m.id_proveedor,
            prov.razon_social AS nombre_proveedor,
            m.id_estado,
            em.nombre AS nombre_estado,
            m.id_comprobante_venta,
            cv.serie AS serie_comprobante_venta,
            cv.numero AS numero_comprobante_venta,
            cv.fecha AS fecha_comprobante_venta,
            cv_cli.razon_social AS nombre_cliente_comprobante_venta,
            cv.total_importe AS total_comprobante_venta,
            m.id_comprobante_compra,
            cc.serie AS serie_comprobante_compra,
            cc.numero AS numero_comprobante_compra,
            cc.fecha AS fecha_comprobante_compra,
            cc_prov.razon_social AS nombre_proveedor_comprobante_compra,
            cc.total_importe AS total_comprobante_compra,
            m.observacion,
            m.estado,
            m.fecha_creacion,
            m.fecha_modificacion,
            m.id_usuario_creacion,
            uc.nombre AS nombre_usuario_creacion,
            m.id_usuario_modificacion,
            um.nombre AS nombre_usuario_modificacion
        FROM bal_mantenimiento m
        LEFT JOIN bal_balon b ON m.id_balon = b.id
        LEFT JOIN pro_producto p ON p.id = m.id_producto
        LEFT JOIN gen_lista_opciones prop ON b.id_propietario = prop.id
        LEFT JOIN cli_clientes cp ON b.id_cliente_propietario = cp.id
        LEFT JOIN gen_lista_opciones tm ON m.id_tipo_mantenimiento = tm.id
        LEFT JOIN cli_clientes prov ON m.id_proveedor = prov.id
        LEFT JOIN gen_lista_opciones em ON m.id_estado = em.id
        LEFT JOIN ven_comprobante cv ON m.id_comprobante_venta = cv.id
        LEFT JOIN cli_clientes cv_cli ON cv.id_cliente = cv_cli.id
        LEFT JOIN com_comprobante_compra cc ON m.id_comprobante_compra = cc.id
        LEFT JOIN cli_clientes cc_prov ON cc.id_proveedor = cc_prov.id
        LEFT JOIN auth_usuarios uc ON m.id_usuario_creacion = uc.id
        LEFT JOIN auth_usuarios um ON m.id_usuario_modificacion = um.id
        WHERE m.id = p_id AND m.estado = 1
    ) t;

    RETURN json_build_object('registro', v_registro);
END;
$$;


--
-- Name: bal_obtener_movimiento(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bal_obtener_movimiento(p_id integer) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_registro JSON;
BEGIN
    SET TIME ZONE 'America/Lima';

    SELECT row_to_json(t) INTO v_registro
    FROM (
        SELECT
            m.id,
            m.id_balon,
            b.codigo_balon,
            m.id_tipo_movimiento,
            tm.nombre AS nombre_tipo_movimiento,
            m.id_documento_ref,
            m.id_tipo_documento_ref,
            tdr.nombre AS nombre_tipo_documento_ref,
            CASE tdr.nombre
                WHEN 'RECARGA' THEN COALESCE(
                    NULLIF(CONCAT_WS('-', NULLIF(cc.serie, ''), NULLIF(cc.numero, '')), ''),
                    NULLIF(CONCAT_WS('-', NULLIF(mr.serie_factura, ''), NULLIF(mr.numero_factura, '')), ''),
                    NULLIF(CONCAT_WS('-', NULLIF(mr_linea.serie_factura, ''), NULLIF(mr_linea.numero_factura, '')), ''),
                    NULLIF(CONCAT_WS('-', NULLIF(rp.serie_factura, ''), NULLIF(rp.numero_factura, '')), ''),
                    NULLIF(TRIM(rp.numero), ''),
                    NULLIF(mr.lote, ''),
                    NULLIF(mr_linea.lote, ''),
                    CASE
                        WHEN mr.id IS NOT NULL THEN 'Recarga #' || mr.id::TEXT
                        WHEN rp.id IS NOT NULL THEN 'Orden ' || COALESCE(NULLIF(TRIM(rp.numero), ''), '#' || rp.id::TEXT)
                        ELSE NULL
                    END
                )
                WHEN 'ALQUILER' THEN COALESCE(alq.numero_alquiler, 'Alquiler #' || alq.id::TEXT)
                WHEN 'PRESTAMO' THEN COALESCE(pr.numero_prestamo, 'Préstamo #' || pr.id::TEXT)
                WHEN 'MANTENIMIENTO' THEN 'Mantenimiento #' || mt.id::TEXT
                WHEN 'GRE' THEN CONCAT_WS('-', gre.serie, gre.numero)
                WHEN 'COMPRA' THEN CONCAT_WS('-', cc_doc.serie, cc_doc.numero)
                WHEN 'FACTURA' THEN COALESCE(
                    CONCAT_WS('-', vc.serie, vc.numero),
                    CASE WHEN mt.id IS NOT NULL THEN 'Mantenimiento #' || mt.id::TEXT END
                )
                WHEN 'BOLETA' THEN CONCAT_WS('-', vc.serie, vc.numero)
                WHEN 'NOTA_CREDITO' THEN CONCAT_WS('-', vc.serie, vc.numero)
                WHEN 'NOTA_DEBITO' THEN CONCAT_WS('-', vc.serie, vc.numero)
                WHEN 'NOTA_VENTA' THEN CONCAT_WS('-', vc.serie, vc.numero)
                ELSE NULL
            END AS documento_numero,
            CASE tdr.nombre
                WHEN 'RECARGA' THEN COALESCE(
                    cc.fecha::TEXT,
                    mr.fecha_salida_almacen::TEXT,
                    mr_linea.fecha_salida_almacen::TEXT,
                    rp.fecha_salida::TEXT,
                    rp.fecha_llegada_almacen::TEXT
                )
                WHEN 'ALQUILER' THEN alq.fecha_inicio::TEXT
                WHEN 'PRESTAMO' THEN pr.fecha_salida::TEXT
                WHEN 'MANTENIMIENTO' THEN mt.fecha_ingreso::TEXT
                WHEN 'GRE' THEN gre.fecha::TEXT
                WHEN 'COMPRA' THEN cc_doc.fecha::TEXT
                WHEN 'FACTURA' THEN COALESCE(vc.fecha::TEXT, mt.fecha_ingreso::TEXT)
                WHEN 'BOLETA' THEN vc.fecha::TEXT
                WHEN 'NOTA_CREDITO' THEN vc.fecha::TEXT
                WHEN 'NOTA_DEBITO' THEN vc.fecha::TEXT
                WHEN 'NOTA_VENTA' THEN vc.fecha::TEXT
                ELSE NULL
            END AS documento_fecha,
            CASE tdr.nombre
                WHEN 'RECARGA' THEN COALESCE(
                    NULLIF(TRIM(rp_prov.razon_social), ''),
                    NULLIF(TRIM(CONCAT_WS(' ', rp_prov.nombres, rp_prov.apellido_paterno, rp_prov.apellido_materno)), ''),
                    rp_prov.numero_documento,
                    NULLIF(TRIM(mr_prov.razon_social), ''),
                    NULLIF(TRIM(CONCAT_WS(' ', mr_prov.nombres, mr_prov.apellido_paterno, mr_prov.apellido_materno)), ''),
                    mr_prov.numero_documento,
                    NULLIF(TRIM(mr_linea_prov.razon_social), ''),
                    NULLIF(TRIM(CONCAT_WS(' ', mr_linea_prov.nombres, mr_linea_prov.apellido_paterno, mr_linea_prov.apellido_materno)), ''),
                    mr_linea_prov.numero_documento,
                    NULLIF(TRIM(cc_prov.razon_social), ''),
                    NULLIF(TRIM(CONCAT_WS(' ', cc_prov.nombres, cc_prov.apellido_paterno, cc_prov.apellido_materno)), ''),
                    cc_prov.numero_documento,
                    NULLIF(TRIM(c.razon_social), ''),
                    NULLIF(TRIM(CONCAT_WS(' ', c.nombres, c.apellido_paterno, c.apellido_materno)), ''),
                    c.numero_documento
                )
                WHEN 'ALQUILER' THEN COALESCE(
                    NULLIF(TRIM(alq_cli.razon_social), ''),
                    NULLIF(TRIM(CONCAT_WS(' ', alq_cli.nombres, alq_cli.apellido_paterno, alq_cli.apellido_materno)), ''),
                    alq_cli.numero_documento
                )
                WHEN 'PRESTAMO' THEN COALESCE(
                    NULLIF(TRIM(pr_cli.razon_social), ''),
                    NULLIF(TRIM(CONCAT_WS(' ', pr_cli.nombres, pr_cli.apellido_paterno, pr_cli.apellido_materno)), ''),
                    pr_cli.numero_documento,
                    NULLIF(TRIM(pr_prov.razon_social), ''),
                    NULLIF(TRIM(CONCAT_WS(' ', pr_prov.nombres, pr_prov.apellido_paterno, pr_prov.apellido_materno)), ''),
                    pr_prov.numero_documento
                )
                WHEN 'MANTENIMIENTO' THEN COALESCE(
                    NULLIF(TRIM(mt_vc_cli.razon_social), ''),
                    NULLIF(TRIM(CONCAT_WS(' ', mt_vc_cli.nombres, mt_vc_cli.apellido_paterno, mt_vc_cli.apellido_materno)), ''),
                    mt_vc_cli.numero_documento,
                    NULLIF(TRIM(mt_prov.razon_social), ''),
                    NULLIF(TRIM(CONCAT_WS(' ', mt_prov.nombres, mt_prov.apellido_paterno, mt_prov.apellido_materno)), ''),
                    mt_prov.numero_documento
                )
                WHEN 'GRE' THEN COALESCE(
                    NULLIF(TRIM(gre_cli.razon_social), ''),
                    NULLIF(TRIM(CONCAT_WS(' ', gre_cli.nombres, gre_cli.apellido_paterno, gre_cli.apellido_materno)), ''),
                    gre_cli.numero_documento
                )
                WHEN 'COMPRA' THEN COALESCE(
                    NULLIF(TRIM(cc_doc_prov.razon_social), ''),
                    NULLIF(TRIM(CONCAT_WS(' ', cc_doc_prov.nombres, cc_doc_prov.apellido_paterno, cc_doc_prov.apellido_materno)), ''),
                    cc_doc_prov.numero_documento
                )
                WHEN 'FACTURA' THEN COALESCE(
                    NULLIF(TRIM(vc_cli.razon_social), ''),
                    NULLIF(TRIM(CONCAT_WS(' ', vc_cli.nombres, vc_cli.apellido_paterno, vc_cli.apellido_materno)), ''),
                    vc_cli.numero_documento,
                    NULLIF(TRIM(mt_prov.razon_social), ''),
                    NULLIF(TRIM(CONCAT_WS(' ', mt_prov.nombres, mt_prov.apellido_paterno, mt_prov.apellido_materno)), ''),
                    mt_prov.numero_documento
                )
                WHEN 'BOLETA' THEN COALESCE(
                    NULLIF(TRIM(vc_cli.razon_social), ''),
                    NULLIF(TRIM(CONCAT_WS(' ', vc_cli.nombres, vc_cli.apellido_paterno, vc_cli.apellido_materno)), ''),
                    vc_cli.numero_documento
                )
                WHEN 'NOTA_CREDITO' THEN COALESCE(
                    NULLIF(TRIM(vc_cli.razon_social), ''),
                    NULLIF(TRIM(CONCAT_WS(' ', vc_cli.nombres, vc_cli.apellido_paterno, vc_cli.apellido_materno)), ''),
                    vc_cli.numero_documento
                )
                WHEN 'NOTA_DEBITO' THEN COALESCE(
                    NULLIF(TRIM(vc_cli.razon_social), ''),
                    NULLIF(TRIM(CONCAT_WS(' ', vc_cli.nombres, vc_cli.apellido_paterno, vc_cli.apellido_materno)), ''),
                    vc_cli.numero_documento
                )
                WHEN 'NOTA_VENTA' THEN COALESCE(
                    NULLIF(TRIM(vc_cli.razon_social), ''),
                    NULLIF(TRIM(CONCAT_WS(' ', vc_cli.nombres, vc_cli.apellido_paterno, vc_cli.apellido_materno)), ''),
                    vc_cli.numero_documento
                )
                ELSE NULL
            END AS documento_cliente,
            CASE
                WHEN tdr.nombre = 'RECARGA' THEN COALESCE(mr.lote, mr_linea.lote, rp.lote, rpd.lote)
                ELSE NULL
            END AS documento_lote,
            CASE tdr.nombre
                WHEN 'RECARGA' THEN NULLIF(CONCAT_WS(
                    ' · ',
                    NULLIF(COALESCE(mr_tipo.nombre, mr_linea_tipo.nombre), ''),
                    NULLIF(COALESCE(mr_prod.nombre, mr_linea_prod.nombre, rpd_prod.nombre), ''),
                    CASE
                        WHEN rp.numero IS NOT NULL THEN 'Orden ' || rp.numero
                        ELSE NULL
                    END,
                    CASE
                        WHEN COALESCE(mr.serie_guia_salida, mr_linea.serie_guia_salida, rp.serie_guia_salida, rp_gre_salida.serie) IS NOT NULL
                         AND COALESCE(mr.numero_guia_salida, mr_linea.numero_guia_salida, rp.numero_guia_salida, rp_gre_salida.numero) IS NOT NULL
                        THEN 'Guía salida '
                            || COALESCE(mr.serie_guia_salida, mr_linea.serie_guia_salida, rp.serie_guia_salida, rp_gre_salida.serie)
                            || '-'
                            || COALESCE(mr.numero_guia_salida, mr_linea.numero_guia_salida, rp.numero_guia_salida, rp_gre_salida.numero)
                        ELSE NULL
                    END
                ), '')
                WHEN 'COMPRA' THEN NULLIF(CONCAT_WS(
                    ' · ',
                    NULLIF(COALESCE(rpd_prod.nombre, mr_linea_prod.nombre, mr_prod.nombre), ''),
                    CASE
                        WHEN rp_compra.numero IS NOT NULL THEN 'Orden planta ' || rp_compra.numero
                        WHEN rp_compra.id IS NOT NULL THEN 'Orden planta #' || rp_compra.id::TEXT
                        ELSE NULL
                    END,
                    CASE
                        WHEN COALESCE(rp_compra.serie_guia_salida, rp_compra_gre_salida.serie) IS NOT NULL
                         AND COALESCE(rp_compra.numero_guia_salida, rp_compra_gre_salida.numero) IS NOT NULL
                        THEN 'Guía salida '
                            || COALESCE(rp_compra.serie_guia_salida, rp_compra_gre_salida.serie)
                            || '-'
                            || COALESCE(rp_compra.numero_guia_salida, rp_compra_gre_salida.numero)
                        ELSE NULL
                    END
                ), '')
                WHEN 'ALQUILER' THEN NULLIF(CONCAT_WS(
                    ' · ',
                    CASE WHEN alq.fecha_fin_pactada IS NOT NULL
                        THEN 'Fin pactado ' || alq.fecha_fin_pactada::TEXT
                        ELSE NULL
                    END,
                    CASE WHEN alq_vc.id IS NOT NULL
                        THEN 'Comprobante ' || CONCAT_WS('-', alq_vc.serie, alq_vc.numero)
                        ELSE NULL
                    END,
                    NULLIF(alq.observacion, '')
                ), '')
                WHEN 'PRESTAMO' THEN NULLIF(CONCAT_WS(
                    ' · ',
                    NULLIF(pr.titulo, ''),
                    NULLIF(pr_tipo.nombre, ''),
                    CASE WHEN pr_vc.id IS NOT NULL
                        THEN 'Comprobante ' || CONCAT_WS('-', pr_vc.serie, pr_vc.numero)
                        ELSE NULL
                    END,
                    NULLIF(pr.observacion, '')
                ), '')
                WHEN 'MANTENIMIENTO' THEN NULLIF(CONCAT_WS(
                    ' · ',
                    NULLIF(mt_tipo.nombre, ''),
                    NULLIF(mt.descripcion, ''),
                    CASE WHEN mt_vc.id IS NOT NULL
                        THEN 'Comprobante ' || CONCAT_WS('-', mt_vc.serie, mt_vc.numero)
                        ELSE NULL
                    END
                ), '')
                WHEN 'GRE' THEN NULLIF(CONCAT_WS(
                    ' · ',
                    NULLIF(gre_motivo.nombre, ''),
                    CASE WHEN gre.fecha_traslado IS NOT NULL
                        THEN 'Traslado ' || gre.fecha_traslado::TEXT
                        ELSE NULL
                    END
                ), '')
                WHEN 'FACTURA' THEN COALESCE(
                    NULLIF(CONCAT_WS(' · ', NULLIF(vc_tipo.nombre, ''), 'Total ' || COALESCE(vc.total_importe::TEXT, '0')), ''),
                    NULLIF(CONCAT_WS(' · ', NULLIF(mt_tipo.nombre, ''), NULLIF(mt.descripcion, '')), '')
                )
                WHEN 'BOLETA' THEN NULLIF(CONCAT_WS(' · ', NULLIF(vc_tipo.nombre, ''), 'Total ' || COALESCE(vc.total_importe::TEXT, '0')), '')
                WHEN 'NOTA_CREDITO' THEN NULLIF(CONCAT_WS(' · ', NULLIF(vc_tipo.nombre, ''), 'Total ' || COALESCE(vc.total_importe::TEXT, '0')), '')
                WHEN 'NOTA_DEBITO' THEN NULLIF(CONCAT_WS(' · ', NULLIF(vc_tipo.nombre, ''), 'Total ' || COALESCE(vc.total_importe::TEXT, '0')), '')
                WHEN 'NOTA_VENTA' THEN NULLIF(CONCAT_WS(' · ', NULLIF(vc_tipo.nombre, ''), 'Total ' || COALESCE(vc.total_importe::TEXT, '0')), '')
                ELSE NULL
            END AS documento_detalle,
            m.id_cliente,
            COALESCE(
                NULLIF(TRIM(c.razon_social), ''),
                NULLIF(TRIM(CONCAT_WS(' ', c.nombres, c.apellido_paterno, c.apellido_materno)), ''),
                c.numero_documento,
                NULLIF(TRIM(rp_prov.razon_social), ''),
                NULLIF(TRIM(CONCAT_WS(' ', rp_prov.nombres, rp_prov.apellido_paterno, rp_prov.apellido_materno)), ''),
                rp_prov.numero_documento,
                NULLIF(TRIM(mr_prov.razon_social), ''),
                NULLIF(TRIM(CONCAT_WS(' ', mr_prov.nombres, mr_prov.apellido_paterno, mr_prov.apellido_materno)), ''),
                mr_prov.numero_documento,
                NULLIF(TRIM(mr_linea_prov.razon_social), ''),
                NULLIF(TRIM(CONCAT_WS(' ', mr_linea_prov.nombres, mr_linea_prov.apellido_paterno, mr_linea_prov.apellido_materno)), ''),
                mr_linea_prov.numero_documento
            ) AS nombre_cliente,
            m.id_almacen_origen,
            COALESCE(
                ao.nombre,
                CASE
                    WHEN tm.nombre IN ('ENTRADA_LLENADO', 'ENTRADA_PLANTA_EXTERNA')
                    THEN 'Planta externa'
                    ELSE NULL
                END
            ) AS nombre_almacen_origen,
            m.id_almacen_destino,
            ad.nombre AS nombre_almacen_destino,
            m.fecha_movimiento,
            m.observacion,
            m.id_estado_balon,
            eb_snap.nombre AS nombre_estado_balon,
            m.id_almacen_ubicacion,
            au_snap.nombre AS nombre_almacen_ubicacion,
            m.id_cliente_ubicacion,
            COALESCE(
                NULLIF(TRIM(cu_snap.razon_social), ''),
                NULLIF(TRIM(CONCAT_WS(' ', cu_snap.nombres, cu_snap.apellido_paterno, cu_snap.apellido_materno)), ''),
                cu_snap.numero_documento
            ) AS nombre_cliente_ubicacion,
            m.estado,
            m.fecha_creacion,
            m.fecha_modificacion,
            m.id_usuario_creacion,
            uc.nombre AS nombre_usuario_creacion,
            m.id_usuario_modificacion,
            um.nombre AS nombre_usuario_modificacion
        FROM bal_movimiento m
        INNER JOIN bal_balon b ON m.id_balon = b.id
        LEFT JOIN gen_lista_opciones tm ON m.id_tipo_movimiento = tm.id
        LEFT JOIN gen_lista_opciones tdr ON m.id_tipo_documento_ref = tdr.id
        LEFT JOIN cli_clientes c ON m.id_cliente = c.id
        LEFT JOIN gen_almacen ao ON m.id_almacen_origen = ao.id
        LEFT JOIN gen_almacen ad ON m.id_almacen_destino = ad.id
        LEFT JOIN gen_lista_opciones eb_snap ON eb_snap.id = m.id_estado_balon
        LEFT JOIN gen_almacen au_snap ON au_snap.id = m.id_almacen_ubicacion
        LEFT JOIN cli_clientes cu_snap ON cu_snap.id = m.id_cliente_ubicacion
        LEFT JOIN auth_usuarios uc ON m.id_usuario_creacion = uc.id
        LEFT JOIN auth_usuarios um ON m.id_usuario_modificacion = um.id
        -- Recarga por línea (salida/entrada planta externa): id_documento_ref = bal_movimiento_recarga.id
        LEFT JOIN bal_movimiento_recarga mr
            ON tdr.nombre = 'RECARGA'
           AND tm.nombre IN ('SALIDA_PLANTA_EXTERNA', 'ENTRADA_PLANTA_EXTERNA')
           AND mr.id = m.id_documento_ref
        LEFT JOIN cli_clientes mr_prov ON mr.id_proveedor = mr_prov.id
        LEFT JOIN pro_producto mr_prod ON mr.id_producto = mr_prod.id
        LEFT JOIN gen_lista_opciones mr_tipo ON mr.id_tipo_recarga = mr_tipo.id
        -- Orden de recarga planta (ENTRADA_LLENADO) o vía línea
        LEFT JOIN bal_recarga_planta rp
            ON tdr.nombre = 'RECARGA'
           AND (
                (tm.nombre = 'ENTRADA_LLENADO' AND rp.id = m.id_documento_ref)
                OR (mr.id IS NOT NULL AND rp.id = mr.id_recarga_planta)
           )
        LEFT JOIN cli_clientes rp_prov ON rp.id_proveedor = rp_prov.id
        -- La orden guarda el FK a la GRE de salida; la serie/número puede no estar copiada.
        LEFT JOIN gre_guia_remision rp_gre_salida
            ON rp_gre_salida.id = rp.id_guia_salida
           AND rp_gre_salida.estado = 1
        LEFT JOIN com_comprobante_compra cc ON cc.id = rp.id_comprobante_compra AND cc.estado = 1
        LEFT JOIN cli_clientes cc_prov ON cc.id_proveedor = cc_prov.id
        -- Compra como documento principal del movimiento (entrada con factura vinculada)
        LEFT JOIN com_comprobante_compra cc_doc
            ON tdr.nombre = 'COMPRA'
           AND cc_doc.id = m.id_documento_ref
           AND cc_doc.estado = 1
        LEFT JOIN cli_clientes cc_doc_prov ON cc_doc.id_proveedor = cc_doc_prov.id
        LEFT JOIN bal_recarga_planta rp_compra
            ON tdr.nombre = 'COMPRA'
           AND rp_compra.id_comprobante_compra = m.id_documento_ref
           AND rp_compra.estado = 1
        LEFT JOIN gre_guia_remision rp_compra_gre_salida
            ON rp_compra_gre_salida.id = rp_compra.id_guia_salida
           AND rp_compra_gre_salida.estado = 1
        -- Línea de la orden para este cilindro (enriquece ENTRADA_LLENADO / COMPRA)
        LEFT JOIN bal_recarga_planta_detalle rpd
            ON tm.nombre IN ('ENTRADA_LLENADO', 'ENTRADA_PLANTA_EXTERNA')
           AND rpd.id_balon = m.id_balon
           AND rpd.estado = 1
           AND (
                (tdr.nombre = 'RECARGA' AND rpd.id_recarga_planta = rp.id)
                OR (tdr.nombre = 'COMPRA' AND rpd.id_recarga_planta = rp_compra.id)
           )
        LEFT JOIN pro_producto rpd_prod ON rpd.id_producto = rpd_prod.id
        LEFT JOIN bal_movimiento_recarga mr_linea
            ON mr_linea.id = rpd.id_movimiento_recarga
           AND mr_linea.estado = 1
        LEFT JOIN cli_clientes mr_linea_prov ON mr_linea.id_proveedor = mr_linea_prov.id
        LEFT JOIN pro_producto mr_linea_prod ON mr_linea.id_producto = mr_linea_prod.id
        LEFT JOIN gen_lista_opciones mr_linea_tipo ON mr_linea.id_tipo_recarga = mr_linea_tipo.id
        LEFT JOIN bal_alquiler alq
            ON tdr.nombre = 'ALQUILER'
           AND alq.id = m.id_documento_ref
        LEFT JOIN cli_clientes alq_cli ON alq.id_cliente = alq_cli.id
        LEFT JOIN ven_comprobante alq_vc ON alq.id_comprobante_venta = alq_vc.id
        LEFT JOIN bal_prestamo pr
            ON tdr.nombre = 'PRESTAMO'
           AND pr.id = m.id_documento_ref
        LEFT JOIN cli_clientes pr_cli ON pr.id_cliente = pr_cli.id
        LEFT JOIN cli_clientes pr_prov ON pr.id_proveedor = pr_prov.id
        LEFT JOIN gen_lista_opciones pr_tipo ON pr.id_tipo_prestamo = pr_tipo.id
        LEFT JOIN ven_comprobante pr_vc ON pr.id_comprobante_venta = pr_vc.id
        LEFT JOIN gre_guia_remision gre
            ON tdr.nombre = 'GRE'
           AND gre.id = m.id_documento_ref
        LEFT JOIN cli_clientes gre_cli ON gre.id_cliente = gre_cli.id
        LEFT JOIN gen_lista_opciones gre_motivo ON gre.id_motivo_traslado = gre_motivo.id
        LEFT JOIN ven_comprobante vc
            ON tdr.nombre IN ('FACTURA', 'BOLETA', 'NOTA_CREDITO', 'NOTA_DEBITO', 'NOTA_VENTA')
           AND vc.id = m.id_documento_ref
        LEFT JOIN cli_clientes vc_cli ON vc.id_cliente = vc_cli.id
        LEFT JOIN gen_lista_opciones vc_tipo ON vc.id_tipo_comprobante = vc_tipo.id
        LEFT JOIN bal_mantenimiento mt
            ON (
                tdr.nombre = 'MANTENIMIENTO'
                OR (tdr.nombre = 'FACTURA' AND vc.id IS NULL)
            )
           AND mt.id = m.id_documento_ref
        LEFT JOIN cli_clientes mt_prov ON mt.id_proveedor = mt_prov.id
        LEFT JOIN gen_lista_opciones mt_tipo ON mt.id_tipo_mantenimiento = mt_tipo.id
        LEFT JOIN ven_comprobante mt_vc ON mt.id_comprobante_venta = mt_vc.id
        LEFT JOIN cli_clientes mt_vc_cli ON mt_vc.id_cliente = mt_vc_cli.id
        WHERE m.id = p_id AND m.estado = 1
    ) t;

    RETURN json_build_object('registro', v_registro);
END;
$$;


--
-- Name: bal_obtener_movimiento_recarga(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bal_obtener_movimiento_recarga(p_id integer) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_registro JSON;
BEGIN
    SET TIME ZONE 'America/Lima';

    SELECT row_to_json(t) INTO v_registro
    FROM (
        SELECT
            mr.id,
            mr.fecha_salida_almacen,
            mr.id_balon,
            b.codigo_balon,
            mr.id_balon_origen,
            bo.codigo_balon AS codigo_balon_origen,
            mr.id_comprobante_compra,
            mr.id_cliente,
            cli.razon_social AS nombre_cliente,
            cli.numero_documento AS documento_cliente,
            mr.id_tipo_recarga,
            tr.nombre AS tipo_recarga_nombre,
            tr.descripcion AS tipo_recarga_descripcion,
            mr.id_producto,
            p.nombre AS nombre_producto,
            COALESCE(mr.capacidad, tb.capacidad) AS capacidad,
            mr.id_unidad_medida,
            um.nombre AS nombre_unidad_medida,
            mr.id_recarga_planta,
            rp.numero AS numero_recarga_planta,
            rp.id_guia_salida,
            rp.id_guia_retorno,
            -- Guías/factura se resuelven desde la orden de planta y sus FKs;
            -- el texto propio del movimiento manda solo si existe (legacy).
            COALESCE(mr.serie_guia_salida, rp.serie_guia_salida, grs.serie) AS serie_guia_salida,
            COALESCE(mr.numero_guia_salida, rp.numero_guia_salida, grs.numero) AS numero_guia_salida,
            COALESCE(mr.serie_guia_ingreso, rp.serie_guia_ingreso, gri.serie) AS serie_guia_ingreso,
            COALESCE(mr.numero_guia_ingreso, rp.numero_guia_ingreso, gri.numero) AS numero_guia_ingreso,
            COALESCE(mr.serie_factura, cc.serie, rp.serie_factura) AS serie_factura,
            COALESCE(mr.numero_factura, cc.numero, rp.numero_factura) AS numero_factura,
            mr.id_comprobante,
            mr.fecha_llegada_almacen,
            mr.lote,
            mr.fecha_vencimiento_lote,
            mr.fecha_prueba_hidrostatica,
            mr.id_proveedor,
            prov.razon_social AS nombre_proveedor,
            mr.observacion,
            mr.id_almacen,
            a.nombre AS nombre_almacen,
            mr.estado,
            mr.fecha_creacion,
            mr.fecha_modificacion,
            mr.id_usuario_creacion,
            uc.nombre AS nombre_usuario_creacion,
            mr.id_usuario_modificacion,
            um2.nombre AS nombre_usuario_modificacion
        FROM bal_movimiento_recarga mr
        INNER JOIN bal_balon b ON mr.id_balon = b.id
        LEFT JOIN bal_tipo_balon tb ON tb.id = b.id_tipo_balon
        LEFT JOIN bal_balon bo ON mr.id_balon_origen = bo.id
        LEFT JOIN bal_recarga_planta rp ON rp.id = mr.id_recarga_planta AND rp.estado = 1
        LEFT JOIN gre_guia_remision grs ON grs.id = rp.id_guia_salida AND grs.estado = 1
        LEFT JOIN gre_guia_remision gri ON gri.id = rp.id_guia_retorno AND gri.estado = 1
        LEFT JOIN com_comprobante_compra cc ON cc.id = mr.id_comprobante_compra AND cc.estado = 1
        LEFT JOIN cli_clientes cli ON mr.id_cliente = cli.id
        LEFT JOIN gen_lista_opciones tr ON mr.id_tipo_recarga = tr.id
        LEFT JOIN pro_producto p ON mr.id_producto = p.id
        LEFT JOIN gen_lista_opciones um ON mr.id_unidad_medida = um.id
        LEFT JOIN cli_clientes prov ON mr.id_proveedor = prov.id
        LEFT JOIN gen_almacen a ON mr.id_almacen = a.id
        LEFT JOIN auth_usuarios uc ON mr.id_usuario_creacion = uc.id
        LEFT JOIN auth_usuarios um2 ON mr.id_usuario_modificacion = um2.id
        WHERE mr.id = p_id AND mr.estado = 1
    ) t;

    RETURN json_build_object('registro', v_registro);
END;
$$;


--
-- Name: bal_obtener_ph_historial(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bal_obtener_ph_historial(p_id integer) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_registro JSON;
BEGIN
    SET TIME ZONE 'America/Lima';

    SELECT row_to_json(t) INTO v_registro
    FROM (
        SELECT
            h.id,
            h.id_balon,
            b.codigo_balon,
            h.fecha_prueba,
            h.vigencia_anios,
            h.fecha_proxima,
            h.id_organo_inspector,
            oi.nombre AS nombre_organo_inspector,
            h.organo_inspector_no_aplica,
            h.numero_certificado,
            h.id_mantenimiento,
            h.id_movimiento_recarga,
            h.es_vigente,
            h.observacion,
            h.estado,
            h.fecha_creacion,
            h.fecha_modificacion
        FROM bal_balon_ph_historial h
        INNER JOIN bal_balon b ON h.id_balon = b.id
        LEFT JOIN gen_lista_opciones oi ON h.id_organo_inspector = oi.id
        WHERE h.id = p_id AND h.estado = 1
    ) t;

    RETURN json_build_object('registro', v_registro);
END;
$$;


--
-- Name: bal_obtener_prestamo(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bal_obtener_prestamo(p_id integer) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_registro JSON;
BEGIN
    SET TIME ZONE 'America/Lima';

    SELECT row_to_json(t) INTO v_registro
    FROM (
        SELECT
            pr.id,
            pr.numero_prestamo,
            pr.id_tipo_prestamo,
            tp.nombre AS nombre_tipo_prestamo,
            pr.id_cliente,
            COALESCE(
                NULLIF(TRIM(c.razon_social), ''),
                NULLIF(TRIM(CONCAT_WS(' ', c.nombres, c.apellido_paterno, c.apellido_materno)), ''),
                c.numero_documento
            ) AS nombre_cliente,
            pr.id_proveedor,
            COALESCE(
                NULLIF(TRIM(prov.razon_social), ''),
                NULLIF(TRIM(CONCAT_WS(' ', prov.nombres, prov.apellido_paterno, prov.apellido_materno)), ''),
                prov.numero_documento
            ) AS nombre_proveedor,
            pr.id_almacen,
            a.nombre AS nombre_almacen,
            pr.fecha_salida,
            pr.fecha_retorno_pactada,
            pr.fecha_retorno_real,
            pr.titulo,
            pr.observacion,
            pr.id_estado,
            ep.nombre AS nombre_estado,
            pr.id_comprobante_venta,
            cv.serie AS serie_comprobante_venta,
            cv.numero AS numero_comprobante_venta,
            cv.fecha AS fecha_comprobante_venta,
            COALESCE(
                NULLIF(TRIM(cv_cli.razon_social), ''),
                NULLIF(TRIM(CONCAT_WS(' ', cv_cli.nombres, cv_cli.apellido_paterno, cv_cli.apellido_materno)), ''),
                cv_cli.numero_documento
            ) AS nombre_cliente_comprobante_venta,
            cv.total_importe AS total_comprobante_venta,
            pr.id_comprobante_compra,
            cc.serie AS serie_comprobante_compra,
            cc.numero AS numero_comprobante_compra,
            cc.fecha AS fecha_comprobante_compra,
            cc_prov.razon_social AS nombre_proveedor_comprobante_compra,
            cc.total_importe AS total_comprobante_compra,
            pr.estado,
            pr.fecha_creacion,
            pr.fecha_modificacion,
            pr.id_usuario_creacion,
            uc.nombre AS nombre_usuario_creacion,
            pr.id_usuario_modificacion,
            um.nombre AS nombre_usuario_modificacion,
            (
                SELECT COUNT(*)::INTEGER
                FROM bal_prestamo_detalle pd
                WHERE pd.id_prestamo = pr.id AND pd.estado = 1
            ) AS total_detalles
        FROM bal_prestamo pr
        LEFT JOIN gen_lista_opciones tp ON pr.id_tipo_prestamo = tp.id
        LEFT JOIN cli_clientes c ON pr.id_cliente = c.id
        LEFT JOIN cli_clientes prov ON pr.id_proveedor = prov.id
        LEFT JOIN gen_almacen a ON pr.id_almacen = a.id
        LEFT JOIN gen_lista_opciones ep ON pr.id_estado = ep.id
        LEFT JOIN ven_comprobante cv ON pr.id_comprobante_venta = cv.id
        LEFT JOIN cli_clientes cv_cli ON cv.id_cliente = cv_cli.id
        LEFT JOIN com_comprobante_compra cc ON pr.id_comprobante_compra = cc.id
        LEFT JOIN cli_clientes cc_prov ON cc.id_proveedor = cc_prov.id
        LEFT JOIN auth_usuarios uc ON pr.id_usuario_creacion = uc.id
        LEFT JOIN auth_usuarios um ON pr.id_usuario_modificacion = um.id
        WHERE pr.id = p_id AND pr.estado = 1
    ) t;

    RETURN json_build_object('registro', v_registro);
END;
$$;


--
-- Name: bal_obtener_prestamo_detalle(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bal_obtener_prestamo_detalle(p_id integer) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_registro JSON;
BEGIN
    SET TIME ZONE 'America/Lima';

    SELECT row_to_json(t) INTO v_registro
    FROM (
        SELECT
            pd.id,
            pd.id_prestamo,
            pr.numero_prestamo,
            pd.id_balon,
            b.codigo_balon,
            pr.id_cliente,
            pr.id_almacen,
            pd.id_producto,
            COALESCE(pg.nombre, p.nombre) AS nombre_producto,
            b.id_producto_gas,
            pg.nombre AS nombre_producto_gas,
            eb.nombre AS nombre_estado_balon,
            pd.motivo_especifico,
            pd.fecha_entregado,
            pd.fecha_prestamo,
            pd.dias_prestamo,
            pd.fecha_vencimiento,
            pd.fecha_devolucion,
            pd.id_guia_entrega,
            ge.serie AS serie_guia_entrega_gre,
            ge.numero AS numero_guia_entrega_gre,
            pd.id_guia_devolucion,
            gd.serie AS serie_guia_devolucion_gre,
            gd.numero AS numero_guia_devolucion_gre,
            pd.serie_guia_entrega,
            pd.numero_guia_entrega,
            pd.serie_guia_devolucion,
            pd.numero_guia_devolucion,
            pd.id_estado,
            ep.nombre AS nombre_estado,
            pd.observacion,
            pd.estado,
            pd.fecha_creacion,
            pd.fecha_modificacion,
            pd.id_usuario_creacion,
            uc.nombre AS nombre_usuario_creacion,
            pd.id_usuario_modificacion,
            um.nombre AS nombre_usuario_modificacion
        FROM bal_prestamo_detalle pd
        INNER JOIN bal_prestamo pr ON pd.id_prestamo = pr.id
        LEFT JOIN bal_balon b ON pd.id_balon = b.id
        LEFT JOIN pro_producto p ON pd.id_producto = p.id
        LEFT JOIN pro_producto pg ON b.id_producto_gas = pg.id
        LEFT JOIN gen_lista_opciones eb ON b.id_estado_balon = eb.id
        LEFT JOIN gen_lista_opciones ep ON pd.id_estado = ep.id
        LEFT JOIN gre_guia_remision ge ON pd.id_guia_entrega = ge.id
        LEFT JOIN gre_guia_remision gd ON pd.id_guia_devolucion = gd.id
        LEFT JOIN auth_usuarios uc ON pd.id_usuario_creacion = uc.id
        LEFT JOIN auth_usuarios um ON pd.id_usuario_modificacion = um.id
        WHERE pd.id = p_id AND pd.estado = 1
    ) t;

    RETURN json_build_object('registro', v_registro);
END;
$$;


--
-- Name: bal_obtener_recarga_planta(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bal_obtener_recarga_planta(p_id integer) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_registro JSONB;
    v_detalles JSON;
BEGIN
    SET TIME ZONE 'America/Lima';

    SELECT to_jsonb(t)
    INTO v_registro
    FROM (
        SELECT
            rp.id,
            rp.numero,
            rp.fecha_salida,
            rp.id_proveedor,
            COALESCE(
                NULLIF(TRIM(prv.razon_social), ''),
                NULLIF(TRIM(CONCAT_WS(' ', prv.nombres, prv.apellido_paterno)), ''),
                prv.numero_documento
            ) AS nombre_proveedor,
            rp.id_almacen,
            a.nombre AS nombre_almacen,
            rp.id_guia_salida,
            -- Serie/número se resuelven desde el documento vinculado; el texto
            -- guardado solo aplica a órdenes sin FK (guías fuera del sistema).
            COALESCE(rp.serie_guia_salida, gs.serie) AS serie_guia_salida,
            COALESCE(rp.numero_guia_salida, gs.numero) AS numero_guia_salida,
            rp.id_guia_retorno,
            COALESCE(rp.serie_guia_ingreso, gi.serie) AS serie_guia_ingreso,
            COALESCE(rp.numero_guia_ingreso, gi.numero) AS numero_guia_ingreso,
            rp.id_comprobante_compra,
            COALESCE(rp.serie_factura, cc.serie) AS serie_factura,
            COALESCE(rp.numero_factura, cc.numero) AS numero_factura,
            rp.fecha_llegada_almacen,
            rp.lote,
            rp.fecha_vencimiento_lote,
            rp.fecha_prueba_hidrostatica,
            rp.id_estado,
            est.nombre AS nombre_estado,
            est.descripcion AS descripcion_estado,
            rp.observacion,
            rp.estado,
            rp.fecha_creacion,
            rp.fecha_modificacion
        FROM bal_recarga_planta rp
        LEFT JOIN cli_clientes prv ON prv.id = rp.id_proveedor
        LEFT JOIN gen_almacen a ON a.id = rp.id_almacen
        LEFT JOIN gen_lista_opciones est ON est.id = rp.id_estado
        LEFT JOIN gre_guia_remision gs ON gs.id = rp.id_guia_salida AND gs.estado = 1
        LEFT JOIN gre_guia_remision gi ON gi.id = rp.id_guia_retorno AND gi.estado = 1
        LEFT JOIN com_comprobante_compra cc ON cc.id = rp.id_comprobante_compra AND cc.estado = 1
        WHERE rp.id = p_id AND rp.estado = 1
    ) t;

    IF v_registro IS NULL THEN
        RETURN json_build_object('error', 'Orden de recarga no encontrada', 'registro', NULL);
    END IF;

    SELECT COALESCE(json_agg(row_to_json(d) ORDER BY d.id), '[]'::JSON)
    INTO v_detalles
    FROM (
        SELECT
            det.id,
            det.id_recarga_planta,
            det.id_balon,
            b.codigo_balon,
            det.id_producto,
            p.nombre AS nombre_producto,
            p.codigo AS codigo_producto,
            COALESCE(det.capacidad, tb.capacidad) AS capacidad,
            det.id_unidad_medida,
            um.nombre AS nombre_unidad_medida,
            det.lote,
            det.fecha_vencimiento_lote,
            det.fecha_prueba_hidrostatica,
            det.id_movimiento_recarga,
            det.observacion,
            eb.nombre AS nombre_estado_balon,
            det.estado
        FROM bal_recarga_planta_detalle det
        INNER JOIN bal_balon b ON b.id = det.id_balon
        LEFT JOIN bal_tipo_balon tb ON tb.id = b.id_tipo_balon
        LEFT JOIN gen_lista_opciones eb ON eb.id = b.id_estado_balon
        LEFT JOIN pro_producto p ON p.id = det.id_producto
        LEFT JOIN gen_lista_opciones um ON um.id = det.id_unidad_medida
        WHERE det.id_recarga_planta = p_id AND det.estado = 1
    ) d;

    RETURN json_build_object(
        'error', NULL,
        'registro', (v_registro || jsonb_build_object('detalles', COALESCE(v_detalles::JSONB, '[]'::JSONB)))::JSON
    );
END;
$$;


--
-- Name: bal_obtener_recojo(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bal_obtener_recojo(p_id integer) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_registro JSONB;
    v_detalles JSON;
BEGIN
    SET TIME ZONE 'America/Lima';

    SELECT to_jsonb(t)
    INTO v_registro
    FROM (
        SELECT
            r.id,
            r.id_cliente,
            COALESCE(
                NULLIF(TRIM(c.razon_social), ''),
                NULLIF(TRIM(CONCAT_WS(' ', c.nombres, c.apellido_paterno)), ''),
                c.numero_documento
            ) AS nombre_cliente,
            c.numero_documento AS documento_cliente,
            dir.latitud,
            dir.longitud,
            dir.direccion,
            r.id_prestamo,
            pr.numero_prestamo,
            r.id_alquiler,
            al.numero_alquiler,
            COALESCE(al.id_producto_regulador, al.id_producto_stock) AS id_producto_alquiler,
            COALESCE(pr_alq.codigo, ps_alq.codigo) AS codigo_producto_alquiler,
            COALESCE(pr_alq.nombre, ps_alq.nombre) AS nombre_producto_alquiler,
            CASE
                WHEN r.id_alquiler IS NOT NULL
                     AND COALESCE(al.id_producto_regulador, al.id_producto_stock) IS NOT NULL
                THEN TRUE
                ELSE FALSE
            END AS tiene_regulador,
            CASE
                WHEN r.id_alquiler IS NOT NULL
                     AND COALESCE(al.id_producto_regulador, al.id_producto_stock) IS NOT NULL
                     AND NOT EXISTS (
                         SELECT 1
                         FROM bal_recojo_detalle rd0
                         WHERE rd0.id_recojo = r.id AND rd0.estado = 1
                     )
                THEN TRUE
                ELSE FALSE
            END AS es_solo_regulador,
            r.id_resultado_regulador,
            rr.nombre AS nombre_resultado_regulador,
            r.id_condicion_regulador,
            cr.nombre AS nombre_condicion_regulador,
            cr.descripcion AS descripcion_condicion_regulador,
            r.nueva_fecha_retorno_regulador,
            r.observacion_regulador,
            CASE
                WHEN r.id_recarga_planta IS NOT NULL THEN 'RECARGAR_PLANTA'
                WHEN r.id_prestamo IS NOT NULL AND r.id_alquiler IS NOT NULL THEN 'MIXTO'
                WHEN r.id_alquiler IS NOT NULL THEN 'ALQUILER'
                ELSE 'PRESTAMO'
            END AS tipo_origen,
            r.id_recarga_planta,
            rp.numero AS numero_recarga_planta,
            r.id_compra,
            r.fecha_programada,
            r.hora_estimada,
            r.fecha_visita,
            r.id_usuario_responsable,
            ur.nombre AS nombre_usuario_responsable,
            r.id_estado,
            er.nombre AS nombre_estado,
            er.descripcion AS descripcion_estado,
            r.id_motivo_fallo,
            mf.nombre AS nombre_motivo_fallo,
            mf.descripcion AS descripcion_motivo_fallo,
            r.observacion,
            r.estado,
            r.fecha_creacion,
            r.fecha_modificacion,
            r.id_usuario_creacion,
            uc.nombre AS nombre_usuario_creacion,
            r.id_usuario_modificacion,
            um.nombre AS nombre_usuario_modificacion
        FROM bal_recojo r
        LEFT JOIN cli_clientes c ON c.id = r.id_cliente
        LEFT JOIN bal_prestamo pr ON pr.id = r.id_prestamo
        LEFT JOIN bal_alquiler al ON al.id = r.id_alquiler
        LEFT JOIN bal_recarga_planta rp ON rp.id = r.id_recarga_planta
        LEFT JOIN pro_producto pr_alq ON pr_alq.id = al.id_producto_regulador
        LEFT JOIN pro_producto ps_alq ON ps_alq.id = al.id_producto_stock
        LEFT JOIN auth_usuarios ur ON ur.id = r.id_usuario_responsable
        LEFT JOIN gen_lista_opciones er ON er.id = r.id_estado
        LEFT JOIN gen_lista_opciones mf ON mf.id = r.id_motivo_fallo
        LEFT JOIN gen_lista_opciones rr ON rr.id = r.id_resultado_regulador
        LEFT JOIN gen_lista_opciones cr ON cr.id = r.id_condicion_regulador
        LEFT JOIN auth_usuarios uc ON uc.id = r.id_usuario_creacion
        LEFT JOIN auth_usuarios um ON um.id = r.id_usuario_modificacion
        LEFT JOIN LATERAL (
            SELECT cd.latitud, cd.longitud, cd.direccion
            FROM cli_direcciones cd
            WHERE cd.id_cliente = r.id_cliente
              AND cd.es_principal = TRUE
              AND cd.estado = 1
            ORDER BY cd.id DESC
            LIMIT 1
        ) dir ON TRUE
        WHERE r.id = p_id AND r.estado = 1
    ) t;

    IF v_registro IS NULL THEN
        RETURN json_build_object('error', 'Recojo no encontrado', 'registro', NULL);
    END IF;

    SELECT COALESCE(json_agg(row_to_json(d) ORDER BY d.id), '[]'::JSON)
    INTO v_detalles
    FROM (
        SELECT
            rd.id,
            rd.id_recojo,
            rd.id_prestamo_detalle,
            rd.id_alquiler_detalle,
            rd.id_balon,
            CASE
                WHEN rd.id_balon IS NOT NULL THEN 'RECARGAR_PLANTA'
                WHEN rd.id_alquiler_detalle IS NOT NULL THEN 'ALQUILER'
                ELSE 'PRESTAMO'
            END AS origen,
            COALESCE(pd.id_prestamo, ad.id_alquiler, rp.id) AS id_origen,
            COALESCE(pr.numero_prestamo, al.numero_alquiler, rp.numero) AS numero_origen,
            COALESCE(pd.id_balon, ad.id_balon, rd.id_balon) AS id_balon,
            b.codigo_balon,
            b.id_producto_gas,
            pg.nombre AS nombre_producto_gas,
            tb.capacidad AS capacidad,
            COALESCE(um_prod.nombre, um_tipo.nombre) AS nombre_unidad_medida,
            COALESCE(um_prod.descripcion, um_tipo.descripcion) AS descripcion_unidad_medida,
            COALESCE(pd.fecha_vencimiento, al.fecha_fin_pactada) AS fecha_vencimiento,
            COALESCE(pd.fecha_devolucion, ad.fecha_devolucion) AS fecha_devolucion,
            rd.id_resultado,
            res.nombre AS nombre_resultado,
            res.descripcion AS descripcion_resultado,
            rd.cantidad_restante,
            rd.nueva_fecha_retorno,
            rd.id_almacen_destino,
            a.nombre AS nombre_almacen_destino,
            rd.observacion,
            rd.estado
        FROM bal_recojo_detalle rd
        LEFT JOIN bal_prestamo_detalle pd
            ON pd.id = rd.id_prestamo_detalle AND pd.estado = 1
        LEFT JOIN bal_prestamo pr ON pr.id = pd.id_prestamo
        LEFT JOIN bal_alquiler_detalle ad
            ON ad.id = rd.id_alquiler_detalle AND ad.estado = 1
        LEFT JOIN bal_alquiler al ON al.id = ad.id_alquiler
        LEFT JOIN bal_recarga_planta rp
            ON rp.id = (SELECT r2.id_recarga_planta FROM bal_recojo r2 WHERE r2.id = p_id)
        LEFT JOIN bal_balon b ON b.id = COALESCE(pd.id_balon, ad.id_balon, rd.id_balon)
        LEFT JOIN bal_tipo_balon tb ON tb.id = b.id_tipo_balon
        LEFT JOIN pro_producto pg ON pg.id = b.id_producto_gas
        LEFT JOIN gen_lista_opciones um_prod ON um_prod.id = pg.id_unidad_medida
        LEFT JOIN gen_lista_opciones um_tipo ON um_tipo.id = tb.id_unidad_medida
        LEFT JOIN gen_lista_opciones res ON res.id = rd.id_resultado
        LEFT JOIN gen_almacen a ON a.id = rd.id_almacen_destino
        WHERE rd.id_recojo = p_id AND rd.estado = 1
    ) d;

    RETURN json_build_object(
        'error', NULL,
        'registro', (v_registro || jsonb_build_object('detalles', COALESCE(v_detalles::JSONB, '[]'::JSONB)))::JSON
    );
END;
$$;


--
-- Name: bal_obtener_ruta_pueblo(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bal_obtener_ruta_pueblo(p_id integer) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_registro JSON;
    v_detalles JSON;
BEGIN
    SET TIME ZONE 'America/Lima';

    SELECT row_to_json(t) INTO v_registro
    FROM (
        SELECT
            r.id,
            r.fecha,
            r.id_almacen,
            a.nombre AS nombre_almacen,
            r.id_usuario_responsable,
            u.nombre AS nombre_usuario_responsable,
            r.id_chofer,
            NULLIF(TRIM(CONCAT_WS(' ', ch.nombres, ch.apellido_paterno, ch.apellido_materno)), '') AS nombre_chofer,
            r.factor_lb_m3,
            r.tolerancia_m3,
            r.m3_reportado_ventas,
            r.m3_calculado,
            r.descuadre_m3,
            r.id_estado,
            er.nombre AS nombre_estado,
            r.observacion,
            r.fecha_creacion,
            r.fecha_modificacion
        FROM bal_ruta_pueblo r
        LEFT JOIN gen_almacen a ON a.id = r.id_almacen
        LEFT JOIN auth_usuarios u ON u.id = r.id_usuario_responsable
        LEFT JOIN gen_chofer ch ON ch.id = r.id_chofer
        LEFT JOIN gen_lista_opciones er ON er.id = r.id_estado
        WHERE r.id = p_id AND r.estado = 1
    ) t;

    IF v_registro IS NULL THEN
        RETURN json_build_object('error', 'Ruta no encontrada', 'registro', NULL);
    END IF;

    SELECT COALESCE(json_agg(row_to_json(d) ORDER BY d.id), '[]'::JSON)
    INTO v_detalles
    FROM (
        SELECT
            det.id,
            det.id_ruta_pueblo,
            det.id_balon,
            b.codigo_balon,
            tb.nombre AS nombre_tipo_balon,
            tb.capacidad AS capacidad_tipo,
            tb.capacidad_lb AS capacidad_lb_tipo,
            bal_factor_lb_m3(tb.id, b.id_producto_gas) AS factor_lb_m3_tipo,
            det.sellado,
            det.lb_salida,
            det.lb_retorno,
            det.m3_delta,
            det.observacion
        FROM bal_ruta_pueblo_detalle det
        INNER JOIN bal_balon b ON b.id = det.id_balon
        LEFT JOIN bal_tipo_balon tb ON tb.id = b.id_tipo_balon
        WHERE det.id_ruta_pueblo = p_id AND det.estado = 1
    ) d;

    RETURN json_build_object(
        'error', NULL,
        'registro', (v_registro::JSONB || jsonb_build_object('detalles', v_detalles))::JSON
    );
END;
$$;


--
-- Name: bal_obtener_siguiente_numero_alquiler(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bal_obtener_siguiente_numero_alquiler(p_anio integer DEFAULT NULL::integer) RETURNS json
    LANGUAGE plpgsql
    AS $_$
DECLARE
    v_anio INTEGER;
    v_prefijo VARCHAR;
    v_ultimo INTEGER;
    v_siguiente VARCHAR;
BEGIN
    SET TIME ZONE 'America/Lima';

    v_anio := COALESCE(p_anio, EXTRACT(YEAR FROM CURRENT_DATE)::INTEGER);
    v_prefijo := 'ALQ-' || v_anio::TEXT || '-';

    SELECT COALESCE(
        MAX(
            NULLIF(
                REGEXP_REPLACE(UPPER(TRIM(numero_alquiler)), '^ALQ-' || v_anio::TEXT || '-', ''),
                ''
            )::INTEGER
        ),
        0
    )
    INTO v_ultimo
    FROM bal_alquiler
    WHERE UPPER(TRIM(numero_alquiler)) ~ ('^ALQ-' || v_anio::TEXT || '-[0-9]+$');

    v_siguiente := v_prefijo || LPAD((v_ultimo + 1)::TEXT, 3, '0');

    RETURN json_build_object(
        'error', NULL,
        'anio', v_anio,
        'ultimo', CASE WHEN v_ultimo = 0 THEN NULL ELSE v_prefijo || LPAD(v_ultimo::TEXT, 3, '0') END,
        'numero', v_siguiente
    );
EXCEPTION
    WHEN others THEN
        RETURN json_build_object(
            'error', 'No se pudo calcular el correlativo de alquiler',
            'numero', NULL
        );
END;
$_$;


--
-- Name: bal_obtener_tipo_balon(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bal_obtener_tipo_balon(p_id integer) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_registro JSON;
BEGIN
    SET TIME ZONE 'America/Lima';

    SELECT row_to_json(t) INTO v_registro
    FROM (
        SELECT
            tb.id,
            tb.nombre,
            tb.id_gas,
            g.nombre AS nombre_gas,
            g.codigo AS codigo_gas,
            tb.capacidad,
            tb.capacidad_lb,
            tb.id_unidad_medida,
            um.nombre AS nombre_unidad_medida,
            tb.peso,
            tb.peso_tara_lb,
            tb.presion_llenado_psi,
            tb.vigencia_ph_anios,
            tb.estado,
            tb.fecha_creacion,
            tb.fecha_modificacion,
            tb.id_usuario_creacion,
            uc.nombre AS nombre_usuario_creacion,
            tb.id_usuario_modificacion,
            um2.nombre AS nombre_usuario_modificacion,
            (
                SELECT COUNT(*)::INTEGER
                FROM bal_balon b
                WHERE b.id_tipo_balon = tb.id AND b.estado = 1
            ) AS total_balones
        FROM bal_tipo_balon tb
        LEFT JOIN pro_producto g ON tb.id_gas = g.id
        LEFT JOIN gen_lista_opciones um ON tb.id_unidad_medida = um.id
        LEFT JOIN auth_usuarios uc ON tb.id_usuario_creacion = uc.id
        LEFT JOIN auth_usuarios um2 ON tb.id_usuario_modificacion = um2.id
        WHERE tb.id = p_id AND tb.estado = 1
    ) t;

    RETURN json_build_object('registro', v_registro);
END;
$$;


--
-- Name: bal_prestamo_aplicar_retorno_cilindro(integer, integer, integer, integer, character varying, character varying, integer, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bal_prestamo_aplicar_retorno_cilindro(p_id_balon integer, p_id_prestamo integer, p_id_cliente integer DEFAULT NULL::integer, p_id_almacen_destino integer DEFAULT NULL::integer, p_nombre_contenido character varying DEFAULT NULL::character varying, p_observacion character varying DEFAULT NULL::character varying, p_id_usuario_auditoria integer DEFAULT NULL::integer, p_crear_movimiento boolean DEFAULT true) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_nombre_estado VARCHAR;
    v_id_almacen INTEGER;
    v_id_estado_en_almacen INTEGER;
    v_contenido VARCHAR;
    v_capacidad NUMERIC;
    v_mov JSON;
    v_en_campo BOOLEAN := FALSE;
BEGIN
    IF p_id_balon IS NULL THEN
        RETURN json_build_object('ok', TRUE, 'skipped', TRUE);
    END IF;

    SELECT eb.nombre, b.id_almacen, tb.capacidad
    INTO v_nombre_estado, v_id_almacen, v_capacidad
    FROM bal_balon b
    LEFT JOIN gen_lista_opciones eb ON eb.id = b.id_estado_balon
    LEFT JOIN bal_tipo_balon tb ON tb.id = b.id_tipo_balon
    WHERE b.id = p_id_balon AND b.estado = 1;

    IF NOT FOUND THEN
        RETURN json_build_object('error', 'El cilindro indicado no existe o está inactivo', 'ok', FALSE);
    END IF;

    v_en_campo := COALESCE(v_nombre_estado, '') IN (
        'PRESTADO_CLIENTE', 'POR_RECOGER', 'EN_PODER_CLIENTE', 'EN_RUTA_LIMA'
    ) OR (COALESCE(v_nombre_estado, '') = 'EN_ALMACEN' AND v_id_almacen IS NULL);

    -- Ya está en almacén (p. ej. volvió por otro flujo): no pisar contenido/stock.
    IF COALESCE(v_nombre_estado, '') = 'EN_ALMACEN' AND v_id_almacen IS NOT NULL THEN
        RETURN json_build_object('ok', TRUE, 'skipped', TRUE);
    END IF;

    -- Custodia de otro proceso (alquiler / recarga / taller): solo se cierra el préstamo.
    IF COALESCE(v_nombre_estado, '') IN (
        'ALQUILADO', 'EN_MANTENIMIENTO', 'EN_RECARGA_EXTERNA', 'DADO_DE_BAJA', 'ROBO'
    ) THEN
        RETURN json_build_object('ok', TRUE, 'skipped', TRUE);
    END IF;

    IF NOT v_en_campo AND COALESCE(v_nombre_estado, '') <> '' THEN
        RETURN json_build_object('ok', TRUE, 'skipped', TRUE);
    END IF;

    IF p_id_almacen_destino IS NULL THEN
        RETURN json_build_object('error', 'Debe indicar el almacén de destino de la devolución', 'ok', FALSE);
    END IF;

    IF NOT EXISTS (
        SELECT 1 FROM gen_almacen WHERE id = p_id_almacen_destino AND estado = 1
    ) THEN
        RETURN json_build_object('error', 'El almacén de destino no existe o está inactivo', 'ok', FALSE);
    END IF;

    SELECT lo.id INTO v_id_estado_en_almacen
    FROM gen_lista_opciones lo
    INNER JOIN gen_lista l ON lo.id_lista = l.id
    WHERE l.nombre = 'EstadoBalon' AND lo.nombre = 'EN_ALMACEN' AND lo.estado = 1
    LIMIT 1;

    IF v_id_estado_en_almacen IS NULL THEN
        RETURN json_build_object(
            'error', 'No se encontró el estado EN_ALMACEN del cilindro. Revise el catálogo EstadoBalon.',
            'ok', FALSE
        );
    END IF;

    IF p_crear_movimiento THEN
        v_mov := inv_registrar_movimiento(
            p_naturaleza                => 'BALON',
            p_codigo_tipo_movimiento    => 'ENTRADA_DEVOLUCION',
            p_fecha                     => NOW(),
            p_id_balon                  => p_id_balon,
            p_cantidad                  => 1,
            p_id_almacen_destino        => p_id_almacen_destino,
            p_id_cliente                => p_id_cliente,
            p_codigo_tipo_documento_origen => 'PRESTAMO',
            p_id_documento_origen       => p_id_prestamo,
            p_glosa                     => COALESCE(NULLIF(TRIM(p_observacion), ''), 'Entrada por devolución de préstamo'),
            p_id_usuario_auditoria      => p_id_usuario_auditoria
        );

        IF v_mov->>'error' IS NOT NULL THEN
            RETURN json_build_object('error', v_mov->>'error', 'ok', FALSE);
        END IF;
    END IF;

    UPDATE bal_balon
    SET
        id_cliente_ubicacion = NULL,
        id_almacen = p_id_almacen_destino,
        id_estado_balon = v_id_estado_en_almacen,
        id_usuario_modificacion = p_id_usuario_auditoria,
        fecha_modificacion = NOW()
    WHERE id = p_id_balon AND estado = 1;

    RETURN json_build_object('ok', TRUE, 'skipped', FALSE);
END;
$$;


--
-- Name: bal_prestamo_aplicar_salida_cilindro(integer, integer, character varying, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bal_prestamo_aplicar_salida_cilindro(p_id_prestamo integer, p_id_balon integer, p_observacion character varying DEFAULT NULL::character varying, p_id_usuario_auditoria integer DEFAULT NULL::integer) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_id_cliente INTEGER;
    v_id_comprobante INTEGER;
    v_id_almacen_origen INTEGER;
    v_nombre_estado VARCHAR;
    v_id_estado_prestado INTEGER;
    v_codigo_tipo_comp VARCHAR;
    v_id_documento_ref INTEGER;
    v_codigo_tipo_doc_ref VARCHAR;
    v_mov JSON;
    v_custodia BOOLEAN := FALSE;
BEGIN
    IF p_id_prestamo IS NULL OR p_id_balon IS NULL THEN
        RETURN json_build_object('error', 'Préstamo y cilindro son obligatorios', 'ok', FALSE);
    END IF;

    SELECT p.id_cliente, p.id_comprobante_venta
    INTO v_id_cliente, v_id_comprobante
    FROM bal_prestamo p
    WHERE p.id = p_id_prestamo AND p.estado = 1;

    IF NOT FOUND THEN
        RETURN json_build_object('error', 'El préstamo indicado no existe o está inactivo', 'ok', FALSE);
    END IF;

    SELECT b.id_almacen, eb.nombre
    INTO v_id_almacen_origen, v_nombre_estado
    FROM bal_balon b
    LEFT JOIN gen_lista_opciones eb ON eb.id = b.id_estado_balon
    WHERE b.id = p_id_balon AND b.estado = 1;

    IF NOT FOUND THEN
        RETURN json_build_object('error', 'El cilindro indicado no existe o está inactivo', 'ok', FALSE);
    END IF;

    IF COALESCE(v_nombre_estado, '') IN ('DADO_DE_BAJA', 'ROBO') THEN
        RETURN json_build_object(
            'error', 'No se puede prestar un cilindro dado de baja o reportado como robo',
            'ok', FALSE
        );
    END IF;

    IF COALESCE(v_nombre_estado, '') IN (
        'ALQUILADO', 'EN_MANTENIMIENTO', 'EN_RECARGA_EXTERNA', 'POR_RECOGER', 'EN_PODER_CLIENTE'
    ) THEN
        RETURN json_build_object(
            'error',
            format('El cilindro está %s; no se puede prestar', LOWER(REPLACE(v_nombre_estado, '_', ' '))),
            'ok', FALSE
        );
    END IF;

    SELECT lo.id INTO v_id_estado_prestado
    FROM gen_lista_opciones lo
    INNER JOIN gen_lista l ON lo.id_lista = l.id
    WHERE l.nombre = 'EstadoBalon' AND lo.nombre = 'PRESTADO_CLIENTE' AND lo.estado = 1
    LIMIT 1;

    IF v_id_estado_prestado IS NULL THEN
        RETURN json_build_object(
            'error', 'No se encontró el estado PRESTADO_CLIENTE del cilindro. Revise el catálogo EstadoBalon.',
            'ok', FALSE
        );
    END IF;

    IF v_id_comprobante IS NOT NULL THEN
        SELECT lo.descripcion INTO v_codigo_tipo_comp
        FROM ven_comprobante c
        INNER JOIN gen_lista_opciones lo ON lo.id = c.id_tipo_comprobante
        WHERE c.id = v_id_comprobante AND c.estado = 1;

        v_id_documento_ref := v_id_comprobante;
        v_codigo_tipo_doc_ref := CASE
            WHEN v_codigo_tipo_comp = '01' THEN 'FACTURA'
            WHEN v_codigo_tipo_comp = '03' THEN 'BOLETA'
            WHEN v_codigo_tipo_comp IN ('NV', 'VSD') THEN 'NOTA_VENTA'
            ELSE 'FACTURA'
        END;
    ELSE
        v_id_documento_ref := p_id_prestamo;
        v_codigo_tipo_doc_ref := 'PRESTAMO';
    END IF;

    v_mov := bal_registrar_salida_documento(
        p_id_balon,
        'SALIDA_PRESTAMO',
        v_id_documento_ref,
        v_codigo_tipo_doc_ref,
        v_id_cliente,
        v_id_almacen_origen,
        'PRESTADO_CLIENTE',
        TRUE,
        NULL,
        COALESCE(NULLIF(TRIM(p_observacion), ''), 'Salida automática por préstamo'),
        p_id_usuario_auditoria
    );

    IF v_mov->>'error' IS NOT NULL THEN
        RETURN json_build_object('error', v_mov->>'error', 'ok', FALSE);
    END IF;

    IF COALESCE(v_nombre_estado, '') IN ('EN_ALMACEN', '', 'PRESTADO_CLIENTE', 'EN_RUTA_LIMA')
       OR v_nombre_estado IS NULL
    THEN
        UPDATE bal_balon
        SET
            id_estado_balon = v_id_estado_prestado,
            id_cliente_ubicacion = COALESCE(v_id_cliente, id_cliente_ubicacion),
            id_almacen = NULL,
            id_usuario_modificacion = p_id_usuario_auditoria,
            fecha_modificacion = NOW()
        WHERE id = p_id_balon AND estado = 1;
    END IF;

    IF COALESCE(v_nombre_estado, '') = 'EN_ALMACEN' THEN
        v_custodia := TRUE;
    END IF;

    RETURN json_build_object('ok', TRUE, 'custodia_actualizada', v_custodia);
END;
$$;


--
-- Name: bal_prestamo_cerrar_si_completo(integer, date, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bal_prestamo_cerrar_si_completo(p_id_prestamo integer, p_fecha date DEFAULT CURRENT_DATE, p_id_usuario_auditoria integer DEFAULT NULL::integer) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_pendientes INTEGER;
    v_id_estado_cerrado INTEGER;
BEGIN
    IF p_id_prestamo IS NULL THEN
        RETURN;
    END IF;

    SELECT COUNT(*) INTO v_pendientes
    FROM bal_prestamo_detalle
    WHERE id_prestamo = p_id_prestamo
      AND estado = 1
      AND fecha_devolucion IS NULL;

    IF COALESCE(v_pendientes, 0) > 0 THEN
        RETURN;
    END IF;

    SELECT lo.id INTO v_id_estado_cerrado
    FROM gen_lista_opciones lo
    INNER JOIN gen_lista l ON lo.id_lista = l.id
    WHERE l.nombre = 'EstadoPrestamo' AND lo.nombre = 'CERRADO' AND lo.estado = 1
    LIMIT 1;

    UPDATE bal_prestamo
    SET
        fecha_retorno_real = COALESCE(fecha_retorno_real, COALESCE(p_fecha, CURRENT_DATE)),
        id_estado = COALESCE(v_id_estado_cerrado, id_estado),
        id_usuario_modificacion = p_id_usuario_auditoria,
        fecha_modificacion = NOW()
    WHERE id = p_id_prestamo
      AND estado = 1;
END;
$$;


--
-- Name: bal_psi_minimo_util(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bal_psi_minimo_util() RETURNS numeric
    LANGUAGE plpgsql STABLE
    AS $$
DECLARE
    v_psi NUMERIC;
BEGIN
    SELECT e.psi_minimo_util
    INTO v_psi
    FROM gen_empresa e
    WHERE e.estado = 1
    ORDER BY e.id
    LIMIT 1;

    RETURN COALESCE(v_psi, 100);
END;
$$;


--
-- Name: bal_rechazar_baja_balon(integer, integer, character varying, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bal_rechazar_baja_balon(p_id_baja integer, p_id_usuario_autoriza integer, p_motivo_rechazo character varying DEFAULT NULL::character varying, p_id_usuario_auditoria integer DEFAULT NULL::integer) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_id_balon INTEGER;
    v_id_motivo_baja INTEGER;
    v_id_estado_actual INTEGER;
    v_observacion VARCHAR;
    v_id_usuario INTEGER;
BEGIN
    SET TIME ZONE 'America/Lima';

    IF p_id_usuario_autoriza IS NULL THEN
        RETURN json_build_object('error', 'Debe indicar el administrador que rechaza', 'registro', NULL);
    END IF;

    IF NOT auth_usuario_es_admin_con_permiso(p_id_usuario_autoriza, 'bajas_balon.rechazar')
       AND NOT auth_usuario_es_admin_con_permiso(p_id_usuario_autoriza, 'bajas_balon.aprobar')
    THEN
        RETURN json_build_object(
            'error',
            'Solo un administrador con permiso de rechazar/aprobar bajas de cilindro puede rechazar la solicitud',
            'registro',
            NULL
        );
    END IF;

    SELECT bb.id_balon, bb.id_motivo_baja, b.id_estado_balon
    INTO v_id_balon, v_id_motivo_baja, v_id_estado_actual
    FROM bal_baja_balon bb
    INNER JOIN bal_balon b ON b.id = bb.id_balon
    WHERE bb.id = p_id_baja
      AND bb.estado = 1
      AND bb.estado_aprobacion = 'PENDIENTE';

    IF v_id_balon IS NULL THEN
        RETURN json_build_object('error', 'La solicitud de baja no existe o ya fue procesada', 'registro', NULL);
    END IF;

    v_id_usuario := COALESCE(p_id_usuario_auditoria, p_id_usuario_autoriza);
    v_observacion := CASE
        WHEN p_motivo_rechazo IS NOT NULL AND TRIM(p_motivo_rechazo) <> ''
            THEN TRIM(p_motivo_rechazo)
        ELSE NULL
    END;

    UPDATE bal_baja_balon
    SET
        estado_aprobacion = 'RECHAZADA',
        estado = 0,
        id_usuario_autoriza = p_id_usuario_autoriza,
        fecha_autorizacion = NOW(),
        observacion = COALESCE(v_observacion, observacion),
        id_usuario_modificacion = v_id_usuario,
        fecha_modificacion = NOW()
    WHERE id = p_id_baja;

    PERFORM bal_registrar_estado_historial(
        v_id_balon,
        'BAJA_RECHAZADA',
        p_id_baja,
        v_id_motivo_baja,
        v_id_estado_actual,
        v_id_estado_actual,
        COALESCE(v_observacion, 'Solicitud de baja rechazada'),
        v_id_usuario,
        NOW()
    );

    RETURN bal_obtener_baja_balon(p_id_baja);
END;
$$;


--
-- Name: bal_registrar_alquiler_periodo(integer, date, date, numeric, integer, integer, character varying, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bal_registrar_alquiler_periodo(p_id_alquiler integer, p_fecha_inicio date, p_fecha_fin date, p_monto numeric DEFAULT 0, p_id_producto integer DEFAULT NULL::integer, p_id_comprobante integer DEFAULT NULL::integer, p_observacion character varying DEFAULT NULL::character varying, p_id_usuario_auditoria integer DEFAULT NULL::integer) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_numero INTEGER;
    v_id INTEGER;
    v_id_estado INTEGER;
BEGIN
    SET TIME ZONE 'America/Lima';

    IF NOT EXISTS (SELECT 1 FROM bal_alquiler WHERE id = p_id_alquiler AND estado = 1) THEN
        RETURN json_build_object('error', 'Alquiler no encontrado', 'registro', NULL);
    END IF;

    IF p_fecha_inicio IS NULL OR p_fecha_fin IS NULL THEN
        RETURN json_build_object('error', 'Fechas de periodo obligatorias', 'registro', NULL);
    END IF;

    IF p_fecha_fin < p_fecha_inicio THEN
        RETURN json_build_object('error', 'fecha_fin debe ser >= fecha_inicio', 'registro', NULL);
    END IF;

    SELECT COALESCE(MAX(numero_periodo), 0) + 1 INTO v_numero
    FROM bal_alquiler_periodo
    WHERE id_alquiler = p_id_alquiler AND estado = 1;

    SELECT lo.id INTO v_id_estado
    FROM gen_lista_opciones lo
    INNER JOIN gen_lista l ON l.id = lo.id_lista
    WHERE l.nombre = 'EstadoAlquilerPeriodo'
      AND lo.nombre = CASE WHEN p_id_comprobante IS NULL THEN 'PENDIENTE' ELSE 'COBRADO' END
      AND lo.estado = 1
    LIMIT 1;

    INSERT INTO bal_alquiler_periodo (
        id_alquiler, numero_periodo, fecha_inicio, fecha_fin, monto,
        id_producto, id_comprobante, id_estado, observacion,
        id_usuario_creacion, id_usuario_modificacion
    )
    VALUES (
        p_id_alquiler, v_numero, p_fecha_inicio, p_fecha_fin, COALESCE(p_monto, 0),
        p_id_producto, p_id_comprobante, v_id_estado, p_observacion,
        p_id_usuario_auditoria, p_id_usuario_auditoria
    )
    RETURNING id INTO v_id;

    UPDATE bal_alquiler
    SET
        fecha_fin_pactada = GREATEST(COALESCE(fecha_fin_pactada, p_fecha_fin), p_fecha_fin),
        fecha_modificacion = NOW(),
        id_usuario_modificacion = p_id_usuario_auditoria
    WHERE id = p_id_alquiler;

    RETURN json_build_object(
        'registro', (
            SELECT row_to_json(t)
            FROM (
                SELECT p.*, pr.codigo AS codigo_producto, pr.nombre AS nombre_producto
                FROM bal_alquiler_periodo p
                LEFT JOIN pro_producto pr ON p.id_producto = pr.id
                WHERE p.id = v_id
            ) t
        )
    );
END;
$$;


--
-- Name: bal_registrar_estado_historial(integer, text, integer, integer, integer, integer, text, integer, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bal_registrar_estado_historial(p_id_balon integer, p_tipo_evento text, p_id_baja integer DEFAULT NULL::integer, p_id_motivo_baja integer DEFAULT NULL::integer, p_id_estado_anterior integer DEFAULT NULL::integer, p_id_estado_nuevo integer DEFAULT NULL::integer, p_observacion text DEFAULT NULL::text, p_id_usuario integer DEFAULT NULL::integer, p_fecha_evento timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_id INTEGER;
BEGIN
    SET TIME ZONE 'America/Lima';

    IF p_id_balon IS NULL THEN
        RETURN NULL;
    END IF;

    IF p_tipo_evento IS NULL OR p_tipo_evento NOT IN (
        'SOLICITUD_BAJA', 'BAJA_APROBADA', 'BAJA_RECHAZADA', 'REACTIVACION'
    ) THEN
        RETURN NULL;
    END IF;

    INSERT INTO bal_balon_estado_historial (
        id_balon, tipo_evento, id_baja, id_motivo_baja,
        id_estado_anterior, id_estado_nuevo, observacion,
        id_usuario, fecha_evento,
        id_usuario_creacion, id_usuario_modificacion
    )
    VALUES (
        p_id_balon, p_tipo_evento, p_id_baja, p_id_motivo_baja,
        p_id_estado_anterior, p_id_estado_nuevo, NULLIF(TRIM(p_observacion), ''),
        p_id_usuario, COALESCE(p_fecha_evento, NOW()),
        p_id_usuario, p_id_usuario
    )
    RETURNING id INTO v_id;

    RETURN v_id;
END;
$$;


--
-- Name: bal_registrar_ph_historial(integer, date, integer, integer, boolean, character varying, integer, integer, character varying, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bal_registrar_ph_historial(p_id_balon integer, p_fecha_prueba date, p_vigencia_anios integer DEFAULT NULL::integer, p_id_organo_inspector integer DEFAULT NULL::integer, p_organo_inspector_no_aplica boolean DEFAULT false, p_numero_certificado character varying DEFAULT NULL::character varying, p_id_mantenimiento integer DEFAULT NULL::integer, p_id_movimiento_recarga integer DEFAULT NULL::integer, p_observacion character varying DEFAULT NULL::character varying, p_id_usuario_auditoria integer DEFAULT NULL::integer) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_id INTEGER;
    v_vigencia INTEGER;
    v_fecha_prueba DATE;
    v_fecha_proxima DATE;
BEGIN
    SET TIME ZONE 'America/Lima';

    IF NOT EXISTS (SELECT 1 FROM bal_balon WHERE id = p_id_balon AND estado = 1) THEN
        RETURN json_build_object('error', 'El balón indicado no existe o está inactivo', 'registro', NULL);
    END IF;

    IF p_fecha_prueba IS NULL THEN
        RETURN json_build_object('error', 'La fecha de prueba hidrostática es obligatoria', 'registro', NULL);
    END IF;

    -- Formato de negocio: solo mes/año (día 1)
    v_fecha_prueba := make_date(
        EXTRACT(YEAR FROM p_fecha_prueba)::INT,
        EXTRACT(MONTH FROM p_fecha_prueba)::INT,
        1
    );

    SELECT COALESCE(
        p_vigencia_anios,
        b.vigencia_prueba_hidrostatica_anios,
        tb.vigencia_ph_anios,
        5
    )
    INTO v_vigencia
    FROM bal_balon b
    LEFT JOIN bal_tipo_balon tb ON b.id_tipo_balon = tb.id
    WHERE b.id = p_id_balon;

    v_fecha_proxima := (v_fecha_prueba + make_interval(years => v_vigencia))::DATE;

    UPDATE bal_balon_ph_historial
    SET es_vigente = FALSE,
        id_usuario_modificacion = p_id_usuario_auditoria,
        fecha_modificacion = NOW()
    WHERE id_balon = p_id_balon AND es_vigente = TRUE AND estado = 1;

    INSERT INTO bal_balon_ph_historial (
        id_balon, fecha_prueba, vigencia_anios, fecha_proxima,
        id_organo_inspector, organo_inspector_no_aplica, numero_certificado,
        id_mantenimiento, id_movimiento_recarga, es_vigente, observacion,
        id_usuario_creacion, id_usuario_modificacion
    )
    VALUES (
        p_id_balon, v_fecha_prueba, v_vigencia, v_fecha_proxima,
        p_id_organo_inspector, COALESCE(p_organo_inspector_no_aplica, FALSE), p_numero_certificado,
        p_id_mantenimiento, p_id_movimiento_recarga, TRUE, p_observacion,
        p_id_usuario_auditoria, p_id_usuario_auditoria
    )
    RETURNING id INTO v_id;

    UPDATE bal_balon
    SET
        fecha_ultima_prueba_hidrostatica = v_fecha_prueba,
        vigencia_prueba_hidrostatica_anios = v_vigencia,
        fecha_proxima_prueba_hidrostatica = v_fecha_proxima,
        id_organo_inspector = COALESCE(p_id_organo_inspector, id_organo_inspector),
        organo_inspector_no_aplica = COALESCE(p_organo_inspector_no_aplica, organo_inspector_no_aplica),
        id_usuario_modificacion = p_id_usuario_auditoria,
        fecha_modificacion = NOW()
    WHERE id = p_id_balon AND estado = 1;

    RETURN bal_obtener_ph_historial(v_id);
END;
$$;


--
-- Name: bal_registrar_resultado_recojo(integer, date, integer, character varying, json, integer, json); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bal_registrar_resultado_recojo(p_id integer, p_fecha_visita date DEFAULT NULL::date, p_id_motivo_fallo integer DEFAULT NULL::integer, p_observacion character varying DEFAULT NULL::character varying, p_detalles json DEFAULT '[]'::json, p_id_usuario_auditoria integer DEFAULT NULL::integer, p_regulador json DEFAULT NULL::json) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_id_cliente INTEGER;
    v_id_prestamo INTEGER;
    v_id_alquiler INTEGER;
    v_id_recarga_planta INTEGER;
    v_estado_actual VARCHAR;
    v_fecha_visita DATE;
    v_item JSON;
    v_id_pd INTEGER;
    v_id_ad INTEGER;
    v_id_b INTEGER;
    v_resultado VARCHAR;
    v_nombre_contenido VARCHAR;
    v_nueva_fecha DATE;
    v_id_almacen INTEGER;
    v_obs VARCHAR(500);
    v_id_resultado INTEGER;
    v_id_prestamo_det INTEGER;
    v_id_alquiler_det INTEGER;
    v_dev JSON;
    v_cnt_total INTEGER := 0;
    v_cnt_recogido INTEGER := 0;
    v_cnt_no_recogido INTEGER := 0;
    v_cnt_extendido INTEGER := 0;
    v_cnt_efectivo INTEGER := 0;
    v_cnt_cubiertos INTEGER := 0;
    v_estado_header VARCHAR;
    v_id_estado_header INTEGER;
    v_id_motivo INTEGER;
    v_motivo_nombre VARCHAR;
    v_pendientes_json JSONB := '[]'::JSONB;
    v_fecha_repro DATE;
    v_nuevo JSON;
    v_id_estado_prestado INTEGER;
    v_id_balon INTEGER;
    v_repro_detalles JSONB := '[]'::JSONB;
    v_cantidad_restante NUMERIC(10,4);
    v_capacidad_tipo NUMERIC(10,4);
    v_id_producto_gas_recojo INTEGER;
    v_lb_restante NUMERIC(10,4);
    v_peso_bruto_lb NUMERIC(10,4);
    v_presion_psi NUMERIC(10,4);
    v_tiene_regulador BOOLEAN := FALSE;
    v_procesa_regulador BOOLEAN := FALSE;
    v_reg JSONB;
    v_reg_resultado VARCHAR;
    v_reg_condicion VARCHAR;
    v_reg_nueva_fecha DATE;
    v_reg_obs VARCHAR(500);
    v_id_resultado_reg INTEGER;
    v_id_condicion_reg INTEGER;
    v_cil_pendientes INTEGER;
    v_seen_pd INTEGER[] := '{}';
    v_seen_ad INTEGER[] := '{}';
    v_seen_b INTEGER[] := '{}';
    v_ya_devuelto DATE;
    v_pass INTEGER;
    v_id_estado_en_almacen INTEGER;
BEGIN
    SET TIME ZONE 'America/Lima';

    SELECT r.id_cliente, r.id_prestamo, r.id_alquiler, r.id_recarga_planta, er.nombre
    INTO v_id_cliente, v_id_prestamo, v_id_alquiler, v_id_recarga_planta, v_estado_actual
    FROM bal_recojo r
    LEFT JOIN gen_lista_opciones er ON er.id = r.id_estado
    WHERE r.id = p_id AND r.estado = 1;

    SELECT lo.id INTO v_id_estado_en_almacen
    FROM gen_lista_opciones lo
    INNER JOIN gen_lista l ON l.id = lo.id_lista
    WHERE l.nombre = 'EstadoBalon' AND lo.nombre = 'EN_ALMACEN' AND lo.estado = 1
    LIMIT 1;

    IF v_id_cliente IS NULL THEN
        RETURN json_build_object('error', 'Recojo no encontrado', 'registro', NULL);
    END IF;

    IF v_estado_actual NOT IN ('PROGRAMADO', 'EN_RUTA') THEN
        RETURN json_build_object(
            'error', 'Solo se puede registrar resultado en recojos PROGRAMADO o EN_RUTA',
            'registro', NULL
        );
    END IF;

    v_fecha_visita := COALESCE(p_fecha_visita, CURRENT_DATE);

    SELECT COUNT(*)::INTEGER INTO v_cnt_total
    FROM bal_recojo_detalle
    WHERE id_recojo = p_id AND estado = 1;

    IF v_id_alquiler IS NOT NULL THEN
        SELECT COALESCE(a.id_producto_regulador, a.id_producto_stock) IS NOT NULL
        INTO v_tiene_regulador
        FROM bal_alquiler a
        WHERE a.id = v_id_alquiler AND a.estado = 1;
    END IF;

    v_reg := CASE
        WHEN p_regulador IS NULL OR p_regulador::TEXT IN ('null', '') THEN NULL
        ELSE p_regulador::JSONB
    END;

    -- Compat: recojo solo regulador enviando un ítem en detalles sin ids de cilindro
    IF v_tiene_regulador
       AND v_reg IS NULL
       AND v_cnt_total = 0
       AND jsonb_array_length(COALESCE(p_detalles::JSONB, '[]'::JSONB)) = 1
       AND COALESCE(
           NULLIF((p_detalles::JSONB -> 0)->>'idPrestamoDetalle', ''),
           NULLIF((p_detalles::JSONB -> 0)->>'id_prestamo_detalle', ''),
           NULLIF((p_detalles::JSONB -> 0)->>'idAlquilerDetalle', ''),
           NULLIF((p_detalles::JSONB -> 0)->>'id_alquiler_detalle', '')
       ) IS NULL
    THEN
        v_reg := p_detalles::JSONB -> 0;
    END IF;

    -- Regulador solo si visita accesorio-only o el cliente envió p_regulador
    v_procesa_regulador := (v_cnt_total = 0 AND v_tiene_regulador) OR (v_reg IS NOT NULL);

    IF v_cnt_total = 0 THEN
        IF NOT v_tiene_regulador THEN
            RETURN json_build_object(
                'error', 'Este recojo no tiene detalles ni regulador asociado',
                'registro', NULL
            );
        END IF;
    ELSE
        IF p_detalles IS NULL
           OR jsonb_array_length(COALESCE(p_detalles::JSONB, '[]'::JSONB)) = 0 THEN
            RETURN json_build_object(
                'error', 'Debe indicar el resultado de al menos un detalle',
                'registro', NULL
            );
        END IF;

        IF v_cnt_total <> jsonb_array_length(p_detalles::JSONB) THEN
            RETURN json_build_object(
                'error',
                'Debe informar resultado para todos los detalles del recojo (' || v_cnt_total || ')',
                'registro', NULL
            );
        END IF;
    END IF;

    v_id_motivo := p_id_motivo_fallo;
    IF v_id_motivo IS NOT NULL THEN
        SELECT lo.nombre INTO v_motivo_nombre
        FROM gen_lista_opciones lo
        INNER JOIN gen_lista l ON l.id = lo.id_lista
        WHERE lo.id = v_id_motivo
          AND l.nombre = 'MotivoFalloRecojo'
          AND lo.estado = 1;

        IF v_motivo_nombre IS NULL THEN
            RETURN json_build_object(
                'error', 'El motivo de fallo no existe o no pertenece a MotivoFalloRecojo',
                'registro', NULL
            );
        END IF;
    END IF;

    -- Pass 1: validar cilindros. Antes del pass 2: regulador + FALLIDO + reprogram.
    -- Pass 2: mutar stock / fechas.
    FOR v_pass IN 1..2 LOOP
        v_seen_pd := '{}';
        v_seen_ad := '{}';
        IF v_pass = 1 THEN
            v_cnt_recogido := 0;
            v_cnt_no_recogido := 0;
            v_cnt_extendido := 0;
            v_pendientes_json := '[]'::JSONB;
        END IF;

        IF v_pass = 2 THEN
            IF v_procesa_regulador THEN
                IF v_reg IS NULL OR COALESCE(NULLIF(TRIM(COALESCE(
                    v_reg->>'resultado', v_reg->>'nombre_resultado', ''
                )), ''), '') = '' THEN
                    RETURN json_build_object(
                        'error', 'Debe indicar el resultado del regulador/accesorio',
                        'registro', NULL
                    );
                END IF;

                v_reg_resultado := UPPER(TRIM(COALESCE(
                    v_reg->>'resultado',
                    v_reg->>'nombre_resultado',
                    ''
                )));
                v_reg_condicion := UPPER(TRIM(COALESCE(
                    v_reg->>'condicion',
                    v_reg->>'nombreCondicion',
                    v_reg->>'nombre_condicion',
                    ''
                )));
                v_reg_nueva_fecha := COALESCE(
                    NULLIF(v_reg->>'nuevaFechaRetorno', '')::DATE,
                    NULLIF(v_reg->>'nueva_fecha_retorno', '')::DATE
                );
                v_reg_obs := NULLIF(TRIM(COALESCE(v_reg->>'observacion', '')), '');

                IF v_reg_resultado NOT IN ('RECOGIDO', 'NO_RECOGIDO', 'EXTENDIDO') THEN
                    RETURN json_build_object(
                        'error', 'Resultado de regulador inválido: ' || COALESCE(v_reg_resultado, '(vacío)'),
                        'registro', NULL
                    );
                END IF;

                SELECT lo.id INTO v_id_resultado_reg
                FROM gen_lista_opciones lo
                INNER JOIN gen_lista l ON l.id = lo.id_lista
                WHERE l.nombre = 'ResultadoRecojoDetalle'
                  AND lo.nombre = v_reg_resultado
                  AND lo.estado = 1
                LIMIT 1;

                IF v_id_resultado_reg IS NULL THEN
                    RETURN json_build_object(
                        'error', 'No se encontró el resultado ' || v_reg_resultado || ' en ResultadoRecojoDetalle',
                        'registro', NULL
                    );
                END IF;

                IF v_reg_resultado = 'RECOGIDO' THEN
                    IF v_reg_condicion NOT IN ('BUENO', 'PARA_REPARAR') THEN
                        RETURN json_build_object(
                            'error', 'Debe indicar si el regulador está BUENO o PARA_REPARAR',
                            'registro', NULL
                        );
                    END IF;

                    SELECT lo.id INTO v_id_condicion_reg
                    FROM gen_lista_opciones lo
                    INNER JOIN gen_lista l ON l.id = lo.id_lista
                    WHERE l.nombre = 'CondicionRegulador'
                      AND lo.nombre = v_reg_condicion
                      AND lo.estado = 1
                    LIMIT 1;

                    IF v_id_condicion_reg IS NULL THEN
                        RETURN json_build_object(
                            'error', 'No se encontró la condición ' || v_reg_condicion || ' en CondicionRegulador',
                            'registro', NULL
                        );
                    END IF;

                    v_cnt_recogido := v_cnt_recogido + 1;
                ELSIF v_reg_resultado = 'EXTENDIDO' THEN
                    v_cnt_extendido := v_cnt_extendido + 1;
                ELSE
                    v_cnt_no_recogido := v_cnt_no_recogido + 1;
                    v_pendientes_json := v_pendientes_json || jsonb_build_array(
                        jsonb_build_object(
                            'solo_regulador', TRUE,
                            'nueva_fecha_retorno', v_fecha_visita + 1,
                            'observacion', v_reg_obs,
                            'no_recogido', TRUE
                        )
                    );
                END IF;
            END IF;

            v_cnt_efectivo := v_cnt_total + CASE WHEN v_procesa_regulador THEN 1 ELSE 0 END;

            IF v_cnt_efectivo = 0 THEN
                RETURN json_build_object(
                    'error', 'No hay ítems para registrar en este recojo',
                    'registro', NULL
                );
            END IF;

            IF v_cnt_no_recogido = v_cnt_efectivo THEN
                v_estado_header := 'FALLIDO';
            ELSIF v_cnt_no_recogido > 0 THEN
                v_estado_header := 'REPROGRAMADO';
            ELSE
                v_estado_header := 'EXITOSO';
            END IF;

            SELECT lo.id INTO v_id_estado_header
            FROM gen_lista_opciones lo
            INNER JOIN gen_lista l ON l.id = lo.id_lista
            WHERE l.nombre = 'EstadoRecojo' AND lo.nombre = v_estado_header AND lo.estado = 1
            LIMIT 1;

            IF v_id_estado_header IS NULL THEN
                RETURN json_build_object(
                    'error', 'No se encontró el estado ' || v_estado_header || ' en EstadoRecojo',
                    'registro', NULL
                );
            END IF;

            IF v_estado_header = 'FALLIDO' AND v_id_motivo IS NULL THEN
                RETURN json_build_object(
                    'error', 'Debe indicar el motivo de fallo cuando el recojo es FALLIDO',
                    'registro', NULL
                );
            END IF;

            IF v_cnt_no_recogido > 0 THEN
                SELECT MIN((elem->>'nueva_fecha_retorno')::DATE)
                INTO v_fecha_repro
                FROM jsonb_array_elements(v_pendientes_json) elem;

                v_fecha_repro := COALESCE(v_fecha_repro, v_fecha_visita + 1);

                SELECT COALESCE(
                    jsonb_agg(
                        CASE
                            WHEN NULLIF(elem->>'id_prestamo_detalle', '') IS NOT NULL THEN
                                jsonb_build_object(
                                    'id_prestamo_detalle', (elem->>'id_prestamo_detalle')::INTEGER,
                                    'observacion', elem->>'observacion'
                                )
                            WHEN NULLIF(elem->>'id_alquiler_detalle', '') IS NOT NULL THEN
                                jsonb_build_object(
                                    'id_alquiler_detalle', (elem->>'id_alquiler_detalle')::INTEGER,
                                    'observacion', elem->>'observacion'
                                )
                            WHEN NULLIF(elem->>'id_balon', '') IS NOT NULL THEN
                                jsonb_build_object(
                                    'id_balon', (elem->>'id_balon')::INTEGER,
                                    'observacion', elem->>'observacion'
                                )
                            ELSE NULL
                        END
                    ) FILTER (WHERE COALESCE(elem->>'solo_regulador', 'false') <> 'true'
                              AND (
                                  NULLIF(elem->>'id_prestamo_detalle', '') IS NOT NULL
                                  OR NULLIF(elem->>'id_alquiler_detalle', '') IS NOT NULL
                                  OR NULLIF(elem->>'id_balon', '') IS NOT NULL
                              )),
                    '[]'::JSONB
                )
                INTO v_repro_detalles
                FROM jsonb_array_elements(v_pendientes_json) elem;

                IF v_id_cliente IS NULL OR v_fecha_repro IS NULL THEN
                    RETURN json_build_object(
                        'error', 'No se puede reprogramar el recojo: faltan cliente o fecha',
                        'registro', NULL
                    );
                END IF;

                IF v_id_recarga_planta IS NULL
                   AND COALESCE(jsonb_array_length(v_repro_detalles), 0) = 0
                   AND v_id_alquiler IS NULL THEN
                    RETURN json_build_object(
                        'error', 'No se puede reprogramar el recojo: no hay pendientes válidos',
                        'registro', NULL
                    );
                END IF;
            END IF;
        END IF;

        FOR v_item IN
            SELECT * FROM jsonb_array_elements(
                CASE WHEN v_cnt_total = 0 THEN '[]'::JSONB ELSE p_detalles::JSONB END
            )
        LOOP
            v_id_pd := COALESCE(
                NULLIF(v_item->>'idPrestamoDetalle', '')::INTEGER,
                NULLIF(v_item->>'id_prestamo_detalle', '')::INTEGER
            );
            v_id_ad := COALESCE(
                NULLIF(v_item->>'idAlquilerDetalle', '')::INTEGER,
                NULLIF(v_item->>'id_alquiler_detalle', '')::INTEGER
            );
            v_id_b := COALESCE(
                NULLIF(v_item->>'idBalon', '')::INTEGER,
                NULLIF(v_item->>'id_balon', '')::INTEGER
            );
            v_resultado := UPPER(TRIM(COALESCE(
                v_item->>'resultado',
                v_item->>'nombre_resultado',
                ''
            )));
            v_nombre_contenido := NULLIF(TRIM(COALESCE(
                v_item->>'nombreEstadoContenido',
                v_item->>'nombre_estado_contenido',
                ''
            )), '');
            v_nueva_fecha := COALESCE(
                NULLIF(v_item->>'nuevaFechaRetorno', '')::DATE,
                NULLIF(v_item->>'nueva_fecha_retorno', '')::DATE
            );
            v_id_almacen := COALESCE(
                NULLIF(v_item->>'idAlmacenDestino', '')::INTEGER,
                NULLIF(v_item->>'id_almacen_destino', '')::INTEGER
            );
            v_obs := NULLIF(TRIM(COALESCE(v_item->>'observacion', '')), '');
            v_cantidad_restante := COALESCE(
                NULLIF(v_item->>'cantidadRestante', '')::NUMERIC,
                NULLIF(v_item->>'cantidad_restante', '')::NUMERIC
            );
            v_lb_restante := COALESCE(
                NULLIF(v_item->>'lbRetorno', '')::NUMERIC,
                NULLIF(v_item->>'lb_retorno', '')::NUMERIC
            );
            v_peso_bruto_lb := COALESCE(
                NULLIF(v_item->>'pesoBrutoLb', '')::NUMERIC,
                NULLIF(v_item->>'peso_bruto_lb', '')::NUMERIC
            );
            v_presion_psi := COALESCE(
                NULLIF(v_item->>'presionActual', '')::NUMERIC,
                NULLIF(v_item->>'presion_actual', '')::NUMERIC,
                NULLIF(v_item->>'presionPsi', '')::NUMERIC,
                NULLIF(v_item->>'presion_psi', '')::NUMERIC
            );

            IF (v_id_pd IS NOT NULL)::INTEGER + (v_id_ad IS NOT NULL)::INTEGER + (v_id_b IS NOT NULL)::INTEGER <> 1 THEN
                RETURN json_build_object(
                    'error', 'Cada detalle debe indicar id_prestamo_detalle, id_alquiler_detalle o id_balon',
                    'registro', NULL
                );
            END IF;

            IF v_id_pd IS NOT NULL THEN
                IF v_id_pd = ANY(v_seen_pd) THEN
                    RETURN json_build_object(
                        'error', 'Detalle de préstamo duplicado: ' || v_id_pd,
                        'registro', NULL
                    );
                END IF;
                v_seen_pd := array_append(v_seen_pd, v_id_pd);

                IF NOT EXISTS (
                    SELECT 1 FROM bal_recojo_detalle
                    WHERE id_recojo = p_id AND id_prestamo_detalle = v_id_pd AND estado = 1
                ) THEN
                    RETURN json_build_object(
                        'error', 'El detalle de préstamo ' || v_id_pd || ' no pertenece a este recojo',
                        'registro', NULL
                    );
                END IF;
            END IF;

            IF v_id_ad IS NOT NULL THEN
                IF v_id_ad = ANY(v_seen_ad) THEN
                    RETURN json_build_object(
                        'error', 'Detalle de alquiler duplicado: ' || v_id_ad,
                        'registro', NULL
                    );
                END IF;
                v_seen_ad := array_append(v_seen_ad, v_id_ad);

                IF NOT EXISTS (
                    SELECT 1 FROM bal_recojo_detalle
                    WHERE id_recojo = p_id AND id_alquiler_detalle = v_id_ad AND estado = 1
                ) THEN
                    RETURN json_build_object(
                        'error', 'El detalle de alquiler ' || v_id_ad || ' no pertenece a este recojo',
                        'registro', NULL
                    );
                END IF;
            END IF;

            IF v_id_b IS NOT NULL THEN
                IF v_id_b = ANY(v_seen_b) THEN
                    RETURN json_build_object(
                        'error', 'Balón duplicado en el recojo: ' || v_id_b,
                        'registro', NULL
                    );
                END IF;
                v_seen_b := array_append(v_seen_b, v_id_b);

                IF NOT EXISTS (
                    SELECT 1 FROM bal_recojo_detalle
                    WHERE id_recojo = p_id AND id_balon = v_id_b AND estado = 1
                ) THEN
                    RETURN json_build_object(
                        'error', 'El balón ' || v_id_b || ' no pertenece a este recojo',
                        'registro', NULL
                    );
                END IF;
            END IF;

            IF v_resultado NOT IN ('RECOGIDO', 'NO_RECOGIDO', 'EXTENDIDO') THEN
                RETURN json_build_object(
                    'error', 'Resultado inválido: ' || COALESCE(v_resultado, '(vacío)'),
                    'registro', NULL
                );
            END IF;

            SELECT lo.id INTO v_id_resultado
            FROM gen_lista_opciones lo
            INNER JOIN gen_lista l ON l.id = lo.id_lista
            WHERE l.nombre = 'ResultadoRecojoDetalle' AND lo.nombre = v_resultado AND lo.estado = 1
            LIMIT 1;

            IF v_id_resultado IS NULL THEN
                RETURN json_build_object(
                    'error', 'No se encontró el resultado ' || v_resultado || ' en ResultadoRecojoDetalle',
                    'registro', NULL
                );
            END IF;



            IF v_resultado = 'EXTENDIDO' THEN
                v_nueva_fecha := COALESCE(v_nueva_fecha, v_fecha_visita + 1);
            END IF;

            IF v_resultado = 'RECOGIDO' THEN
                IF v_id_pd IS NOT NULL THEN
                    SELECT pd.id_balon, tb.capacidad
                    INTO v_id_balon, v_capacidad_tipo
                    FROM bal_prestamo_detalle pd
                    JOIN bal_balon b ON b.id = pd.id_balon AND b.estado = 1
                    JOIN bal_tipo_balon tb ON tb.id = b.id_tipo_balon
                    WHERE pd.id = v_id_pd AND pd.estado = 1;
                ELSIF v_id_ad IS NOT NULL THEN
                    SELECT ad.id_balon, tb.capacidad
                    INTO v_id_balon, v_capacidad_tipo
                    FROM bal_alquiler_detalle ad
                    JOIN bal_balon b ON b.id = ad.id_balon AND b.estado = 1
                    JOIN bal_tipo_balon tb ON tb.id = b.id_tipo_balon
                    WHERE ad.id = v_id_ad AND ad.estado = 1;
                ELSE
                    v_id_balon := v_id_b;
                    SELECT tb.capacidad
                    INTO v_capacidad_tipo
                    FROM bal_balon b
                    JOIN bal_tipo_balon tb ON tb.id = b.id_tipo_balon
                    WHERE b.id = v_id_b AND b.estado = 1;
                END IF;

                IF v_cantidad_restante IS NULL THEN
                    IF UPPER(COALESCE(v_nombre_contenido, 'VACIO')) = 'VACIO' THEN
                        v_cantidad_restante := 0;
                    ELSIF UPPER(COALESCE(v_nombre_contenido, '')) = 'LLENO' THEN
                        v_cantidad_restante := v_capacidad_tipo;
                    END IF;
                ELSIF v_cantidad_restante < 0 THEN
                    RETURN json_build_object(
                        'error', 'La cantidad restante no puede ser negativa',
                        'registro', NULL
                    );
                ELSIF v_capacidad_tipo IS NOT NULL AND v_cantidad_restante > v_capacidad_tipo THEN
                    RETURN json_build_object(
                        'error',
                        'La cantidad restante (' || v_cantidad_restante
                            || ') supera la capacidad del cilindro (' || v_capacidad_tipo || ')',
                        'registro', NULL
                    );
                END IF;

                IF v_nombre_contenido IS NULL AND v_cantidad_restante IS NOT NULL THEN
                    IF v_cantidad_restante <= 0 THEN
                        v_nombre_contenido := 'VACIO';
                    ELSIF v_capacidad_tipo IS NOT NULL AND v_cantidad_restante >= v_capacidad_tipo THEN
                        v_nombre_contenido := 'LLENO';
                    ELSIF v_capacidad_tipo IS NOT NULL AND v_cantidad_restante < v_capacidad_tipo THEN
                        v_nombre_contenido := 'SEMILLLENO';
                    ELSE
                        v_nombre_contenido := 'DESCONOCIDO';
                    END IF;
                END IF;
            ELSE
                v_cantidad_restante := NULL;
                v_id_balon := NULL;
            END IF;

            IF v_pass = 1 THEN
                IF v_resultado = 'RECOGIDO' THEN
                    v_cnt_recogido := v_cnt_recogido + 1;
                ELSIF v_resultado = 'EXTENDIDO' THEN
                    v_cnt_extendido := v_cnt_extendido + 1;
                ELSE
                    v_cnt_no_recogido := v_cnt_no_recogido + 1;
                    v_pendientes_json := v_pendientes_json || jsonb_build_array(
                        jsonb_build_object(
                            'id_prestamo_detalle', v_id_pd,
                            'id_alquiler_detalle', v_id_ad,
                            'id_balon', v_id_b,
                            'nueva_fecha_retorno', v_fecha_visita + 1,
                            'observacion', v_obs,
                            'no_recogido', TRUE
                        )
                    );
                END IF;
            ELSE
                UPDATE bal_recojo_detalle
                SET
                    id_resultado = v_id_resultado,
                    cantidad_restante = CASE
                        WHEN v_resultado = 'RECOGIDO' THEN v_cantidad_restante
                        ELSE cantidad_restante
                    END,
                    nueva_fecha_retorno = CASE
                        WHEN v_resultado = 'EXTENDIDO' THEN v_nueva_fecha
                        ELSE nueva_fecha_retorno
                    END,
                    id_almacen_destino = COALESCE(v_id_almacen, id_almacen_destino),
                    observacion = COALESCE(v_obs, observacion),
                    id_usuario_modificacion = p_id_usuario_auditoria,
                    fecha_modificacion = NOW()
                WHERE id_recojo = p_id
                  AND estado = 1
                  AND (
                      (v_id_pd IS NOT NULL AND id_prestamo_detalle = v_id_pd)
                      OR (v_id_ad IS NOT NULL AND id_alquiler_detalle = v_id_ad)
                  );

                IF v_resultado = 'RECOGIDO' THEN
                    v_dev := NULL;
                    IF v_id_pd IS NOT NULL THEN
                        SELECT pd.fecha_devolucion INTO v_ya_devuelto
                        FROM bal_prestamo_detalle pd
                        WHERE pd.id = v_id_pd AND pd.estado = 1;
                    ELSIF v_id_ad IS NOT NULL THEN
                        SELECT ad.fecha_devolucion INTO v_ya_devuelto
                        FROM bal_alquiler_detalle ad
                        WHERE ad.id = v_id_ad AND ad.estado = 1;
                    ELSE
                        v_ya_devuelto := NULL;
                    END IF;

                    IF v_ya_devuelto IS NULL THEN
                        IF v_id_pd IS NOT NULL THEN
                            v_dev := bal_devolver_prestamo_detalle(
                                v_id_pd,
                                v_fecha_visita,
                                v_id_almacen,
                                p_id_usuario_auditoria,
                                COALESCE(v_nombre_contenido, 'VACIO'),
                                v_obs
                            );
                        ELSIF v_id_ad IS NOT NULL THEN
                            v_dev := bal_devolver_alquiler_detalle(
                                v_id_ad,
                                v_fecha_visita,
                                v_id_almacen,
                                p_id_usuario_auditoria
                            );
                        ELSE
                            -- Recarga en planta externa: ingreso físico del balón al almacén
                            PERFORM bal_actualizar_balon(
                                p_id                   => v_id_balon,
                                p_id_almacen           => v_id_almacen,
                                p_id_estado_balon      => v_id_estado_en_almacen,
                                p_id_usuario_auditoria => p_id_usuario_auditoria
                            );

                            IF v_id_recarga_planta IS NOT NULL THEN
                                SELECT id_producto_gas INTO v_id_producto_gas_recojo
                                FROM bal_balon WHERE id = v_id_balon;

                                v_dev := inv_registrar_movimiento(
                                    p_naturaleza                => 'BALON',
                                    p_codigo_tipo_movimiento    => 'ENTRADA_LLENADO',
                                    p_fecha                     => NOW(),
                                    p_id_producto               => v_id_producto_gas_recojo,
                                    p_id_balon                  => v_id_balon,
                                    p_cantidad                  => COALESCE(v_cantidad_restante, NULLIF(v_capacidad_tipo, 0), 1),
                                    p_id_almacen_destino        => v_id_almacen,
                                    p_id_cliente                => v_id_cliente,
                                    p_codigo_tipo_documento_origen => 'RECARGA',
                                    p_id_documento_origen       => v_id_recarga_planta,
                                    p_glosa                     => 'Entrada por recojo de recarga en planta (orden #'
                                        || v_id_recarga_planta || ')',
                                    p_id_usuario_auditoria      => p_id_usuario_auditoria
                                );
                                IF v_dev->>'error' IS NOT NULL THEN
                                    RAISE EXCEPTION 'No se pudo registrar el movimiento de entrada del balón %: %',
                                        v_id_balon, v_dev->>'error';
                                END IF;
                            END IF;
                        END IF;
                        IF v_dev->>'error' IS NOT NULL THEN
                            RAISE EXCEPTION '%', v_dev->>'error';
                        END IF;
                    END IF;

                    IF v_id_balon IS NOT NULL AND (
                        v_peso_bruto_lb IS NOT NULL
                        OR v_lb_restante IS NOT NULL
                        OR v_cantidad_restante IS NOT NULL
                    ) THEN
                        NULL;
                    END IF;
                ELSIF v_resultado = 'EXTENDIDO' THEN
                    IF v_id_pd IS NOT NULL THEN
                        SELECT pd.id_prestamo, pd.id_balon
                        INTO v_id_prestamo_det, v_id_balon
                        FROM bal_prestamo_detalle pd
                        WHERE pd.id = v_id_pd AND pd.estado = 1;

                        UPDATE bal_prestamo_detalle
                        SET
                            fecha_vencimiento = v_nueva_fecha,
                            id_usuario_modificacion = p_id_usuario_auditoria,
                            fecha_modificacion = NOW()
                        WHERE id = v_id_pd AND estado = 1;

                        UPDATE bal_prestamo
                        SET
                            fecha_retorno_pactada = v_nueva_fecha,
                            id_usuario_modificacion = p_id_usuario_auditoria,
                            fecha_modificacion = NOW()
                        WHERE id = v_id_prestamo_det AND estado = 1;
                    ELSE
                        SELECT ad.id_alquiler, ad.id_balon
                        INTO v_id_alquiler_det, v_id_balon
                        FROM bal_alquiler_detalle ad
                        WHERE ad.id = v_id_ad AND ad.estado = 1;

                        UPDATE bal_alquiler
                        SET
                            fecha_fin_pactada = v_nueva_fecha,
                            id_usuario_modificacion = p_id_usuario_auditoria,
                            fecha_modificacion = NOW()
                        WHERE id = v_id_alquiler_det AND estado = 1;
                    END IF;

                    SELECT lo.id INTO v_id_estado_prestado
                    FROM gen_lista_opciones lo
                    INNER JOIN gen_lista l ON l.id = lo.id_lista
                    WHERE l.nombre = 'EstadoBalon'
                      AND lo.nombre = CASE WHEN v_id_ad IS NOT NULL THEN 'ALQUILADO' ELSE 'PRESTADO_CLIENTE' END
                      AND lo.estado = 1
                    LIMIT 1;

                    IF v_id_balon IS NOT NULL AND v_id_estado_prestado IS NOT NULL THEN
                        UPDATE bal_balon b
                        SET
                            id_estado_balon = v_id_estado_prestado,
                            id_usuario_modificacion = p_id_usuario_auditoria,
                            fecha_modificacion = NOW()
                        FROM gen_lista_opciones eb
                        WHERE b.id = v_id_balon
                          AND b.estado = 1
                          AND eb.id = b.id_estado_balon
                          AND eb.nombre = 'POR_RECOGER';
                    END IF;
                END IF;
            END IF;
        END LOOP;

        IF v_pass = 1 AND v_cnt_total > 0 THEN
            SELECT COUNT(*)::INTEGER INTO v_cnt_cubiertos
            FROM bal_recojo_detalle rd
            WHERE rd.id_recojo = p_id
              AND rd.estado = 1
              AND (
                  (rd.id_prestamo_detalle IS NOT NULL AND rd.id_prestamo_detalle = ANY(v_seen_pd))
                  OR (rd.id_alquiler_detalle IS NOT NULL AND rd.id_alquiler_detalle = ANY(v_seen_ad))
                  OR (rd.id_balon IS NOT NULL AND rd.id_balon = ANY(v_seen_b))
              );

            IF v_cnt_cubiertos <> v_cnt_total THEN
                RETURN json_build_object(
                    'error',
                    'Debe informar resultado para todos los detalles del recojo (' || v_cnt_total || ')',
                    'registro', NULL
                );
            END IF;
        END IF;
    END LOOP;

    -- Mutación de regulador (después de validar todo el payload)
    IF v_procesa_regulador THEN
        IF v_reg_resultado = 'RECOGIDO' THEN
            v_dev := bal_devolver_regulador_alquiler(
                v_id_alquiler,
                v_fecha_visita,
                v_reg_condicion,
                v_reg_obs,
                p_id,
                p_id_usuario_auditoria
            );

            IF v_dev->>'error' IS NOT NULL THEN
                RAISE EXCEPTION '%', v_dev->>'error';
            END IF;
        ELSIF v_reg_resultado = 'EXTENDIDO' THEN
            v_reg_nueva_fecha := COALESCE(v_reg_nueva_fecha, v_fecha_visita + 1);

            UPDATE bal_alquiler
            SET
                fecha_fin_pactada = v_reg_nueva_fecha,
                id_usuario_modificacion = p_id_usuario_auditoria,
                fecha_modificacion = NOW()
            WHERE id = v_id_alquiler AND estado = 1;
        END IF;
    END IF;

    UPDATE bal_recojo
    SET
        fecha_visita = v_fecha_visita,
        id_estado = v_id_estado_header,
        id_motivo_fallo = CASE
            WHEN v_estado_header IN ('FALLIDO', 'REPROGRAMADO') AND v_cnt_no_recogido > 0
                THEN COALESCE(v_id_motivo, id_motivo_fallo)
            WHEN v_estado_header = 'FALLIDO' THEN v_id_motivo
            ELSE id_motivo_fallo
        END,
        observacion = COALESCE(NULLIF(TRIM(p_observacion), ''), observacion),
        id_resultado_regulador = COALESCE(v_id_resultado_reg, id_resultado_regulador),
        id_condicion_regulador = COALESCE(v_id_condicion_reg, id_condicion_regulador),
        nueva_fecha_retorno_regulador = CASE
            WHEN v_reg_resultado = 'EXTENDIDO' THEN v_reg_nueva_fecha
            ELSE nueva_fecha_retorno_regulador
        END,
        observacion_regulador = COALESCE(v_reg_obs, observacion_regulador),
        id_usuario_modificacion = p_id_usuario_auditoria,
        fecha_modificacion = NOW()
    WHERE id = p_id AND estado = 1;

    IF v_id_alquiler IS NOT NULL AND v_reg_resultado = 'RECOGIDO' THEN
        SELECT COUNT(*)::INTEGER INTO v_cil_pendientes
        FROM bal_alquiler_detalle ad
        WHERE ad.id_alquiler = v_id_alquiler
          AND ad.estado = 1
          AND ad.fecha_devolucion IS NULL;

        IF v_cil_pendientes = 0 THEN
            SELECT lo.id INTO v_id_estado_prestado
            FROM gen_lista_opciones lo
            INNER JOIN gen_lista l ON l.id = lo.id_lista
            WHERE l.nombre = 'EstadoAlquiler' AND lo.nombre = 'FINALIZADO' AND lo.estado = 1
            LIMIT 1;

            IF v_id_estado_prestado IS NOT NULL THEN
                v_dev := bal_actualizar_alquiler(
                    v_id_alquiler,
                    NULL::VARCHAR,
                    NULL::INTEGER,
                    NULL::INTEGER,
                    NULL::DATE,
                    NULL::DATE,
                    v_fecha_visita,
                    NULL::NUMERIC,
                    NULL::NUMERIC,
                    v_id_estado_prestado,
                    NULL::VARCHAR,
                    NULL::INTEGER,
                    NULL::INTEGER,
                    NULL::INTEGER,
                    p_id_usuario_auditoria
                );

                IF v_dev->>'error' IS NOT NULL THEN
                    RAISE EXCEPTION '%', v_dev->>'error';
                END IF;
            END IF;
        END IF;
    END IF;

    IF v_cnt_no_recogido > 0 THEN
        v_nuevo := bal_crear_recojo(
            v_id_cliente,
            CASE
                WHEN COALESCE(jsonb_array_length(v_repro_detalles), 0) = 0 THEN NULL
                ELSE v_id_prestamo
            END,
            v_id_alquiler,
            v_id_recarga_planta,
            v_fecha_repro,
            NULL::TIME,
            NULL::INTEGER,
            'Reprogramado desde recojo #' || p_id,
            COALESCE(v_repro_detalles, '[]'::JSONB)::JSON,
            p_id_usuario_auditoria
        );

        IF v_nuevo->>'error' IS NOT NULL THEN
            RAISE EXCEPTION 'No se pudo reprogramar el recojo: %', v_nuevo->>'error';
        END IF;
    END IF;

    RETURN bal_obtener_recojo(p_id);
END;
$$;


--
-- Name: bal_registrar_retorno_ruta_pueblo(integer, json, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bal_registrar_retorno_ruta_pueblo(p_id integer, p_detalles json DEFAULT '[]'::json, p_id_usuario_auditoria integer DEFAULT NULL::integer) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_estado VARCHAR;
    v_id_almacen INTEGER;
    v_factor_ruta NUMERIC;
    v_factor NUMERIC;
    v_detalle JSON;
    v_id_balon INTEGER;
    v_lb_retorno NUMERIC;
    v_id_det INTEGER;
    v_lb_salida NUMERIC;
    v_lb_retorno_existente NUMERIC;
    v_m3_delta NUMERIC;
    v_restante_m3 NUMERIC;
    v_mov JSON;
    v_cap_m3 NUMERIC;
    v_cap_lb NUMERIC;
    v_sync JSON;
BEGIN
    SET TIME ZONE 'America/Lima';

    SELECT er.nombre, r.id_almacen, r.factor_lb_m3
    INTO v_estado, v_id_almacen, v_factor_ruta
    FROM bal_ruta_pueblo r
    LEFT JOIN gen_lista_opciones er ON er.id = r.id_estado
    WHERE r.id = p_id AND r.estado = 1;

    IF v_estado IS NULL THEN
        RETURN json_build_object('error', 'Ruta no encontrada', 'registro', NULL);
    END IF;

    IF v_estado NOT IN ('EN_RUTA', 'ABIERTA') THEN
        RETURN json_build_object('error', 'Solo se registra retorno en rutas ABIERTA o EN_RUTA', 'registro', NULL);
    END IF;

    -- Si aún ABIERTA, iniciar primero (salida física)
    IF v_estado = 'ABIERTA' THEN
        PERFORM bal_iniciar_ruta_pueblo(p_id, p_id_usuario_auditoria);
        SELECT er.nombre, r.id_almacen, r.factor_lb_m3
        INTO v_estado, v_id_almacen, v_factor_ruta
        FROM bal_ruta_pueblo r
        LEFT JOIN gen_lista_opciones er ON er.id = r.id_estado
        WHERE r.id = p_id AND r.estado = 1;
    END IF;

    IF p_detalles IS NULL OR json_typeof(p_detalles) <> 'array' OR json_array_length(p_detalles) = 0 THEN
        RETURN json_build_object('error', 'Debe indicar libras de retorno por cilindro', 'registro', NULL);
    END IF;

    FOR v_detalle IN SELECT value FROM json_array_elements(p_detalles)
    LOOP
        v_id_balon := COALESCE(
            (v_detalle->>'idBalon')::INTEGER,
            (v_detalle->>'id_balon')::INTEGER
        );
        v_lb_retorno := COALESCE(
            (v_detalle->>'lbRetorno')::NUMERIC,
            (v_detalle->>'lb_retorno')::NUMERIC
        );

        IF v_id_balon IS NULL OR v_lb_retorno IS NULL OR v_lb_retorno < 0 THEN
            RAISE EXCEPTION 'Cada ítem requiere idBalon y lbRetorno ≥ 0';
        END IF;

        SELECT d.id, d.lb_salida, d.lb_retorno
        INTO v_id_det, v_lb_salida, v_lb_retorno_existente
        FROM bal_ruta_pueblo_detalle d
        WHERE d.id_ruta_pueblo = p_id
          AND d.id_balon = v_id_balon
          AND d.estado = 1;

        IF v_id_det IS NULL THEN
            RAISE EXCEPTION 'Cilindro % no pertenece a esta ruta', v_id_balon;
        END IF;

        -- Idempotente: no reprocesar cilindros ya retornados
        IF v_lb_retorno_existente IS NOT NULL THEN
            CONTINUE;
        END IF;

        IF v_lb_retorno > v_lb_salida THEN
            RAISE EXCEPTION 'Cilindro %: lb retorno (%.4f) no puede superar lb salida (%.4f)',
                v_id_balon, v_lb_retorno, v_lb_salida;
        END IF;

        -- Factor por tipo del cilindro; fallback al snapshot de la ruta
        SELECT tb.capacidad, tb.capacidad_lb
        INTO v_cap_m3, v_cap_lb
        FROM bal_balon b
        LEFT JOIN bal_tipo_balon tb ON tb.id = b.id_tipo_balon AND tb.estado = 1
        WHERE b.id = v_id_balon AND b.estado = 1;

        IF v_cap_m3 IS NOT NULL AND v_cap_m3 > 0 AND v_cap_lb IS NOT NULL AND v_cap_lb > 0 THEN
            v_factor := ROUND(v_cap_m3 / v_cap_lb, 6);
        ELSE
            v_factor := COALESCE(v_factor_ruta, 0.317400);
        END IF;

        v_m3_delta := ROUND((v_lb_salida - v_lb_retorno) * v_factor, 4);
        v_restante_m3 := ROUND(v_lb_retorno * v_factor, 4);

        UPDATE bal_ruta_pueblo_detalle
        SET
            lb_retorno = v_lb_retorno,
            m3_delta = v_m3_delta,
            observacion = COALESCE(
                NULLIF(TRIM(COALESCE(v_detalle->>'observacion', '')), ''),
                observacion
            ),
            id_usuario_modificacion = p_id_usuario_auditoria,
            fecha_modificacion = NOW()
        WHERE id = v_id_det;

        -- Retorno a almacén con residual (CY4: no forzar vacío)
        v_mov := bal_registrar_salida_documento(
            v_id_balon,
            'RETORNO_LIMA',
            p_id,
            'RUTA_PUEBLO',
            NULL,
            NULL,
            'EN_ALMACEN',
            FALSE,
            v_id_almacen,
            format('Retorno ruta pueblos #%s · %.4f lb residual', p_id, v_lb_retorno),
            p_id_usuario_auditoria
        );

        IF v_mov->>'error' IS NOT NULL THEN
            -- Si ya existe movimiento retorno idempotente, igual actualizamos balón
            NULL;
        END IF;

        UPDATE bal_balon
        SET
            id_almacen = v_id_almacen,
            id_cliente_ubicacion = NULL,
            id_estado_balon = (
                SELECT lo.id
                FROM gen_lista_opciones lo
                INNER JOIN gen_lista l ON l.id = lo.id_lista
                WHERE l.nombre = 'EstadoBalon' AND lo.nombre = 'EN_ALMACEN' AND lo.estado = 1
                LIMIT 1
            ),
            id_usuario_modificacion = p_id_usuario_auditoria,
            fecha_modificacion = NOW()
        WHERE id = v_id_balon AND estado = 1;


    END LOOP;

    UPDATE bal_ruta_pueblo
    SET
        m3_calculado = (
            SELECT COALESCE(SUM(d.m3_delta), 0)
            FROM bal_ruta_pueblo_detalle d
            WHERE d.id_ruta_pueblo = p_id AND d.estado = 1 AND d.lb_retorno IS NOT NULL
        ),
        id_usuario_modificacion = p_id_usuario_auditoria,
        fecha_modificacion = NOW()
    WHERE id = p_id;

    RETURN bal_obtener_ruta_pueblo(p_id);
END;
$$;


--
-- Name: bal_registrar_salida_documento(integer, character varying, integer, character varying, integer, integer, character varying, boolean, integer, character varying, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bal_registrar_salida_documento(p_id_balon integer, p_codigo_tipo_mov character varying, p_id_documento_ref integer DEFAULT NULL::integer, p_codigo_tipo_doc_ref character varying DEFAULT NULL::character varying, p_id_cliente integer DEFAULT NULL::integer, p_id_almacen_origen integer DEFAULT NULL::integer, p_codigo_estado_destino character varying DEFAULT NULL::character varying, p_limpiar_almacen boolean DEFAULT true, p_id_almacen_destino integer DEFAULT NULL::integer, p_observacion character varying DEFAULT NULL::character varying, p_id_usuario_auditoria integer DEFAULT NULL::integer) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_result JSON;
    v_creado BOOLEAN;
    v_nombre_estado_actual VARCHAR;
BEGIN
    SET TIME ZONE 'America/Lima';

    IF p_id_balon IS NULL THEN
        RETURN json_build_object('error', 'El cilindro es obligatorio', 'registro', NULL);
    END IF;

    IF p_codigo_tipo_mov IS NULL OR TRIM(p_codigo_tipo_mov) = '' THEN
        RETURN json_build_object('error', 'El tipo de movimiento es obligatorio', 'registro', NULL);
    END IF;

    SELECT eb.nombre INTO v_nombre_estado_actual
    FROM bal_balon b
    LEFT JOIN gen_lista_opciones eb ON eb.id = b.id_estado_balon
    WHERE b.id = p_id_balon AND b.estado = 1;

    IF NOT FOUND THEN
        RETURN json_build_object('error', 'El cilindro indicado no existe o está inactivo', 'registro', NULL);
    END IF;

    IF COALESCE(v_nombre_estado_actual, '') IN ('DADO_DE_BAJA', 'ROBO') THEN
        RETURN json_build_object(
            'error',
            'No se puede registrar salida de un cilindro dado de baja o reportado como robo',
            'registro',
            NULL
        );
    END IF;

    v_result := inv_registrar_movimiento(
        p_naturaleza                => 'BALON',
        p_codigo_tipo_movimiento    => p_codigo_tipo_mov,
        p_fecha                     => NOW(),
        p_id_producto               => NULL,
        p_id_balon                  => p_id_balon,
        p_cantidad                  => 1,
        p_id_almacen_origen         => COALESCE(p_id_almacen_origen,
            (SELECT id_almacen FROM bal_balon WHERE id = p_id_balon AND estado = 1)),
        p_id_almacen_destino        => p_id_almacen_destino,
        p_id_cliente                => p_id_cliente,
        p_codigo_tipo_documento_origen => p_codigo_tipo_doc_ref,
        p_id_documento_origen       => p_id_documento_ref,
        p_glosa                     => p_observacion,
        p_id_usuario_auditoria      => p_id_usuario_auditoria
    );

    v_creado := COALESCE((v_result->>'creado')::BOOLEAN, FALSE);

    -- Si la función creó el movimiento, lo retorna; si era idempotente, retorna el existente
    RETURN v_result;
END;
$$;


--
-- Name: bal_renovar_alquiler(integer, integer, numeric, date, date, character varying, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bal_renovar_alquiler(p_id_alquiler integer, p_id_comprobante integer, p_monto numeric DEFAULT NULL::numeric, p_fecha_inicio date DEFAULT NULL::date, p_fecha_fin date DEFAULT NULL::date, p_observacion character varying DEFAULT NULL::character varying, p_id_usuario_auditoria integer DEFAULT NULL::integer) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_alq RECORD;
    v_ultimo RECORD;
    v_inicio DATE;
    v_fin DATE;
    v_monto NUMERIC;
    v_dias INTEGER;
    v_periodo JSON;
BEGIN
    SET TIME ZONE 'America/Lima';

    SELECT * INTO v_alq
    FROM bal_alquiler
    WHERE id = p_id_alquiler AND estado = 1;

    IF NOT FOUND THEN
        RETURN json_build_object('error', 'Alquiler no encontrado', 'registro', NULL);
    END IF;

    IF v_alq.id_producto_regulador IS NULL THEN
        RETURN json_build_object(
            'error', 'El alquiler no tiene regulador vinculado; no se puede renovar',
            'registro', NULL
        );
    END IF;

    IF p_id_comprobante IS NULL OR NOT EXISTS (
        SELECT 1 FROM ven_comprobante WHERE id = p_id_comprobante AND estado = 1
    ) THEN
        RETURN json_build_object('error', 'Comprobante de renovación inválido', 'registro', NULL);
    END IF;

    SELECT * INTO v_ultimo
    FROM bal_alquiler_periodo
    WHERE id_alquiler = p_id_alquiler AND estado = 1
    ORDER BY numero_periodo DESC
    LIMIT 1;

    v_dias := COALESCE(NULLIF(v_alq.dias_periodo, 0), 14);
    v_inicio := COALESCE(p_fecha_inicio, CASE
        WHEN v_ultimo.id IS NOT NULL THEN (v_ultimo.fecha_fin + 1)
        ELSE COALESCE(v_alq.fecha_fin_pactada, CURRENT_DATE) + 1
    END);
    v_fin := COALESCE(p_fecha_fin, v_inicio + (v_dias - 1));
    v_monto := COALESCE(p_monto, v_alq.tarifa_diaria, 0);

    v_periodo := bal_registrar_alquiler_periodo(
        p_id_alquiler,
        v_inicio,
        v_fin,
        v_monto,
        v_alq.id_producto_regulador,
        p_id_comprobante,
        COALESCE(p_observacion, 'Renovación regulador'),
        p_id_usuario_auditoria
    );

    IF (v_periodo->>'error') IS NOT NULL THEN
        RETURN v_periodo;
    END IF;

    UPDATE bal_alquiler
    SET
        total_cobrado = COALESCE(total_cobrado, 0) + v_monto,
        fecha_fin_pactada = v_fin,
        fecha_modificacion = NOW(),
        id_usuario_modificacion = p_id_usuario_auditoria
    WHERE id = p_id_alquiler;

    RETURN bal_obtener_alquiler(p_id_alquiler);
END;
$$;


--
-- Name: bal_reporte_alquileres_antiguedad(character varying, integer, integer, integer, character varying, boolean, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bal_reporte_alquileres_antiguedad(p_busqueda character varying DEFAULT ''::character varying, p_limite integer DEFAULT 50, p_offset integer DEFAULT 0, p_id_cliente integer DEFAULT NULL::integer, p_rango_dias character varying DEFAULT NULL::character varying, p_excluir_bajas boolean DEFAULT true, p_solo_pendientes boolean DEFAULT true) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_registros JSON;
    v_total BIGINT;
    v_resumen JSON;
BEGIN
    SET TIME ZONE 'America/Lima';

    WITH base AS (
        SELECT
            ad.id AS id_detalle,
            a.id AS id_alquiler,
            a.numero_alquiler,
            a.id_cliente,
            COALESCE(
                c.razon_social,
                TRIM(CONCAT_WS(' ', c.nombres, c.apellido_paterno, c.apellido_materno))
            ) AS nombre_cliente,
            a.id_almacen,
            alm.nombre AS nombre_almacen,
            ad.id_balon,
            b.codigo_balon,
            b.numero_serie,
            b.id_tipo_balon,
            tb.nombre AS nombre_tipo_balon,
            tb.capacidad,
            um.nombre AS nombre_unidad_medida,
            b.id_producto_gas,
            pg.nombre AS nombre_producto_gas,
            b.id_marca_cilindro,
            mc.nombre AS nombre_marca_cilindro,
            b.id_organo_inspector,
            oi.nombre AS nombre_organo_inspector,
            b.organo_inspector_no_aplica,
            b.id_planta,
            COALESCE(pl.razon_social, TRIM(CONCAT_WS(' ', pl.nombres, pl.apellido_paterno))) AS nombre_planta,
            b.fecha_proxima_prueba_hidrostatica,
            b.mes_fabricacion,
            b.anio_fabricacion,
            eb.nombre AS nombre_estado_balon,
            a.fecha_inicio AS fecha_inicio_alquiler,
            a.fecha_fin_pactada,
            ad.fecha_devolucion,
            CASE
                WHEN ad.fecha_devolucion IS NOT NULL THEN NULL
                ELSE (CURRENT_DATE - a.fecha_inicio)::INTEGER
            END AS dias_en_alquiler,
            CASE
                WHEN ad.fecha_devolucion IS NOT NULL THEN 'DEVUELTO'
                WHEN (CURRENT_DATE - a.fecha_inicio) >= 180 THEN 'CRITICO_180'
                WHEN (CURRENT_DATE - a.fecha_inicio) >= 90 THEN 'SEGUIMIENTO_90_180'
                WHEN (CURRENT_DATE - a.fecha_inicio) >= 30 THEN 'ATENCION_30_90'
                ELSE 'RECIENTE_0_30'
            END AS rango_antiguedad
        FROM bal_alquiler_detalle ad
        INNER JOIN bal_alquiler a ON a.id = ad.id_alquiler AND a.estado = 1
        LEFT JOIN bal_balon b ON b.id = ad.id_balon
        LEFT JOIN bal_tipo_balon tb ON b.id_tipo_balon = tb.id
        LEFT JOIN gen_lista_opciones um ON tb.id_unidad_medida = um.id
        LEFT JOIN pro_producto pg ON b.id_producto_gas = pg.id
        LEFT JOIN gen_lista_opciones mc ON b.id_marca_cilindro = mc.id
        LEFT JOIN gen_lista_opciones oi ON b.id_organo_inspector = oi.id
        LEFT JOIN gen_lista_opciones eb ON b.id_estado_balon = eb.id
        LEFT JOIN cli_clientes c ON a.id_cliente = c.id
        LEFT JOIN cli_clientes pl ON b.id_planta = pl.id
        LEFT JOIN gen_almacen alm ON a.id_almacen = alm.id
        WHERE ad.estado = 1
          AND (p_solo_pendientes = FALSE OR ad.fecha_devolucion IS NULL)
          AND (
              p_excluir_bajas = FALSE
              OR eb.nombre IS NULL
              OR eb.nombre NOT IN ('DADO_DE_BAJA', 'ROBO')
          )
          AND (p_id_cliente IS NULL OR a.id_cliente = p_id_cliente)
          AND a.fecha_inicio IS NOT NULL
          AND (
              p_busqueda = ''
              OR gen_texto_coincide(COALESCE(a.numero_alquiler, ''), p_busqueda)
              OR gen_texto_coincide(COALESCE(b.codigo_balon, ''), p_busqueda)
              OR gen_texto_coincide(COALESCE(b.numero_serie, ''), p_busqueda)
              OR gen_texto_coincide(COALESCE(c.razon_social, ''), p_busqueda)
              OR gen_texto_coincide(COALESCE(c.nombres, ''), p_busqueda)
              OR gen_texto_coincide(COALESCE(pg.nombre, ''), p_busqueda)
          )
    ),
    filtrado AS (
        SELECT *
        FROM base
        WHERE (
            p_rango_dias IS NULL
            OR p_rango_dias = ''
            OR rango_antiguedad = p_rango_dias
        )
    ),
    agregado AS (
        SELECT
            (SELECT COUNT(*) FROM filtrado) AS total,
            (
                SELECT COALESCE(json_agg(row_to_json(t)), '[]'::JSON)
                FROM (
                    SELECT *
                    FROM filtrado
                    ORDER BY
                        CASE WHEN dias_en_alquiler IS NULL THEN 1 ELSE 0 END,
                        dias_en_alquiler DESC NULLS LAST,
                        nombre_cliente ASC NULLS LAST,
                        codigo_balon ASC NULLS LAST
                    LIMIT p_limite
                    OFFSET p_offset
                ) t
            ) AS registros,
            (
                SELECT json_build_object(
                    'total_pendientes', COUNT(*) FILTER (WHERE rango_antiguedad <> 'DEVUELTO'),
                    'reciente_0_30', COUNT(*) FILTER (WHERE rango_antiguedad = 'RECIENTE_0_30'),
                    'atencion_30_90', COUNT(*) FILTER (WHERE rango_antiguedad = 'ATENCION_30_90'),
                    'seguimiento_90_180', COUNT(*) FILTER (WHERE rango_antiguedad = 'SEGUIMIENTO_90_180'),
                    'critico_180', COUNT(*) FILTER (WHERE rango_antiguedad = 'CRITICO_180')
                )
                FROM base
            ) AS resumen
    )
    SELECT a.total, a.registros, a.resumen
    INTO v_total, v_registros, v_resumen
    FROM agregado a;

    RETURN json_build_object(
        'registros', COALESCE(v_registros, '[]'::JSON),
        'total', COALESCE(v_total, 0),
        'resumen', COALESCE(
            v_resumen,
            json_build_object(
                'total_pendientes', 0,
                'reciente_0_30', 0,
                'atencion_30_90', 0,
                'seguimiento_90_180', 0,
                'critico_180', 0
            )
        )
    );
END;
$$;


--
-- Name: bal_reporte_balones_propietario(character varying, integer, integer, character varying, integer, integer, integer, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bal_reporte_balones_propietario(p_busqueda character varying DEFAULT ''::character varying, p_limite integer DEFAULT 50, p_offset integer DEFAULT 0, p_tipo_propietario character varying DEFAULT NULL::character varying, p_id_planta integer DEFAULT NULL::integer, p_id_cliente_propietario integer DEFAULT NULL::integer, p_id_almacen integer DEFAULT NULL::integer, p_excluir_bajas boolean DEFAULT true) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_registros JSON;
    v_total BIGINT;
    v_resumen JSON;
    v_buscar VARCHAR;
    v_tipo VARCHAR;
BEGIN
    SET TIME ZONE 'America/Lima';

    v_buscar := NULLIF(TRIM(COALESCE(p_busqueda, '')), '');
    v_tipo := NULLIF(UPPER(TRIM(COALESCE(p_tipo_propietario, ''))), '');

    WITH base AS (
        SELECT
            b.id,
            b.codigo_balon,
            b.numero_serie,
            b.id_propietario,
            UPPER(COALESCE(prop.nombre, '')) AS nombre_propietario,
            b.id_planta,
            COALESCE(
                NULLIF(TRIM(pl.razon_social), ''),
                NULLIF(TRIM(CONCAT_WS(' ', pl.nombres, pl.apellido_paterno, pl.apellido_materno)), ''),
                pl.numero_documento
            ) AS nombre_planta,
            b.id_cliente_propietario,
            COALESCE(
                NULLIF(TRIM(cp.razon_social), ''),
                NULLIF(TRIM(CONCAT_WS(' ', cp.nombres, cp.apellido_paterno, cp.apellido_materno)), ''),
                cp.numero_documento
            ) AS nombre_cliente_propietario,
            CASE UPPER(COALESCE(prop.nombre, ''))
                WHEN 'PLANTA' THEN COALESCE(
                    NULLIF(TRIM(pl.razon_social), ''),
                    NULLIF(TRIM(CONCAT_WS(' ', pl.nombres, pl.apellido_paterno, pl.apellido_materno)), ''),
                    pl.numero_documento,
                    'Sin proveedor'
                )
                WHEN 'CLIENTE' THEN COALESCE(
                    NULLIF(TRIM(cp.razon_social), ''),
                    NULLIF(TRIM(CONCAT_WS(' ', cp.nombres, cp.apellido_paterno, cp.apellido_materno)), ''),
                    cp.numero_documento,
                    'Sin cliente'
                )
                WHEN 'EMPRESA' THEN 'Empresa'
                ELSE COALESCE(prop.nombre, 'Sin propietario')
            END AS nombre_titular,
            b.id_tipo_balon,
            tb.nombre AS nombre_tipo_balon,
            tb.capacidad,
            um.nombre AS nombre_unidad_medida,
            b.id_producto_gas,
            pg.nombre AS nombre_producto_gas,
            b.id_estado_balon,
            eb.nombre AS nombre_estado_balon,
            b.id_almacen,
            a.nombre AS nombre_almacen,
            b.fecha_proxima_prueba_hidrostatica
        FROM bal_balon b
        LEFT JOIN gen_lista_opciones prop ON prop.id = b.id_propietario
        LEFT JOIN cli_clientes pl ON pl.id = b.id_planta
        LEFT JOIN cli_clientes cp ON cp.id = b.id_cliente_propietario
        LEFT JOIN bal_tipo_balon tb ON tb.id = b.id_tipo_balon
        LEFT JOIN gen_lista_opciones um ON um.id = tb.id_unidad_medida
        LEFT JOIN pro_producto pg ON pg.id = b.id_producto_gas
        LEFT JOIN gen_lista_opciones eb ON eb.id = b.id_estado_balon
        LEFT JOIN gen_almacen a ON a.id = b.id_almacen
        WHERE b.estado = 1
          AND (
              p_excluir_bajas = FALSE
              OR eb.nombre IS NULL
              OR eb.nombre NOT IN ('DADO_DE_BAJA', 'ROBO')
          )
          AND (p_id_almacen IS NULL OR b.id_almacen = p_id_almacen)
          AND (p_id_planta IS NULL OR b.id_planta = p_id_planta)
          AND (p_id_cliente_propietario IS NULL OR b.id_cliente_propietario = p_id_cliente_propietario)
          AND (
              v_tipo IS NULL
              OR UPPER(COALESCE(prop.nombre, '')) = v_tipo
          )
          AND (
              v_buscar IS NULL
              OR gen_texto_coincide(COALESCE(b.codigo_balon, ''), v_buscar)
              OR gen_texto_coincide(COALESCE(b.numero_serie, ''), v_buscar)
              OR gen_texto_coincide(COALESCE(prop.nombre, ''), v_buscar)
              OR gen_texto_coincide(COALESCE(pl.razon_social, ''), v_buscar)
              OR gen_texto_coincide(COALESCE(pl.nombres, ''), v_buscar)
              OR gen_texto_coincide(COALESCE(cp.razon_social, ''), v_buscar)
              OR gen_texto_coincide(COALESCE(cp.nombres, ''), v_buscar)
              OR gen_texto_coincide(COALESCE(pg.nombre, ''), v_buscar)
              OR gen_texto_coincide(COALESCE(a.nombre, ''), v_buscar)
          )
    ),
    universo AS (
        -- Conteos globales (sin filtro de tipo/titular) para las cards del resumen.
        SELECT
            b.id,
            UPPER(COALESCE(prop.nombre, '')) AS nombre_propietario,
            b.id_planta,
            COALESCE(
                NULLIF(TRIM(pl.razon_social), ''),
                NULLIF(TRIM(CONCAT_WS(' ', pl.nombres, pl.apellido_paterno, pl.apellido_materno)), ''),
                pl.numero_documento,
                'Sin proveedor'
            ) AS nombre_planta,
            b.id_cliente_propietario,
            COALESCE(
                NULLIF(TRIM(cp.razon_social), ''),
                NULLIF(TRIM(CONCAT_WS(' ', cp.nombres, cp.apellido_paterno, cp.apellido_materno)), ''),
                cp.numero_documento,
                'Sin cliente'
            ) AS nombre_cliente_propietario
        FROM bal_balon b
        LEFT JOIN gen_lista_opciones prop ON prop.id = b.id_propietario
        LEFT JOIN cli_clientes pl ON pl.id = b.id_planta
        LEFT JOIN cli_clientes cp ON cp.id = b.id_cliente_propietario
        LEFT JOIN gen_lista_opciones eb ON eb.id = b.id_estado_balon
        WHERE b.estado = 1
          AND (
              p_excluir_bajas = FALSE
              OR eb.nombre IS NULL
              OR eb.nombre NOT IN ('DADO_DE_BAJA', 'ROBO')
          )
          AND (p_id_almacen IS NULL OR b.id_almacen = p_id_almacen)
    ),
    agregado AS (
        SELECT
            (SELECT COUNT(*) FROM base) AS total,
            (
                SELECT COALESCE(json_agg(row_to_json(t)), '[]'::JSON)
                FROM (
                    SELECT *
                    FROM base
                    ORDER BY
                        nombre_propietario ASC,
                        nombre_titular ASC NULLS LAST,
                        codigo_balon ASC NULLS LAST
                    LIMIT GREATEST(COALESCE(p_limite, 50), 1)
                    OFFSET GREATEST(COALESCE(p_offset, 0), 0)
                ) t
            ) AS registros,
            (
                SELECT json_build_object(
                    'total', COUNT(*),
                    'empresa', COUNT(*) FILTER (WHERE nombre_propietario = 'EMPRESA'),
                    'planta', COUNT(*) FILTER (WHERE nombre_propietario = 'PLANTA'),
                    'cliente', COUNT(*) FILTER (WHERE nombre_propietario = 'CLIENTE'),
                    'otros', COUNT(*) FILTER (
                        WHERE nombre_propietario NOT IN ('EMPRESA', 'PLANTA', 'CLIENTE')
                           OR nombre_propietario = ''
                    ),
                    'por_planta', (
                        SELECT COALESCE(json_agg(row_to_json(p) ORDER BY p.cantidad DESC, p.nombre_planta), '[]'::JSON)
                        FROM (
                            SELECT
                                id_planta,
                                nombre_planta,
                                COUNT(*)::INT AS cantidad
                            FROM universo
                            WHERE nombre_propietario = 'PLANTA'
                            GROUP BY id_planta, nombre_planta
                        ) p
                    ),
                    'por_cliente', (
                        SELECT COALESCE(json_agg(row_to_json(c) ORDER BY c.cantidad DESC, c.nombre_cliente_propietario), '[]'::JSON)
                        FROM (
                            SELECT
                                id_cliente_propietario,
                                nombre_cliente_propietario,
                                COUNT(*)::INT AS cantidad
                            FROM universo
                            WHERE nombre_propietario = 'CLIENTE'
                            GROUP BY id_cliente_propietario, nombre_cliente_propietario
                        ) c
                    )
                )
                FROM universo
            ) AS resumen
    )
    SELECT a.total, a.registros, a.resumen
    INTO v_total, v_registros, v_resumen
    FROM agregado a;

    RETURN json_build_object(
        'registros', COALESCE(v_registros, '[]'::JSON),
        'total', COALESCE(v_total, 0),
        'resumen', COALESCE(
            v_resumen,
            json_build_object(
                'total', 0,
                'empresa', 0,
                'planta', 0,
                'cliente', 0,
                'otros', 0,
                'por_planta', '[]'::JSON,
                'por_cliente', '[]'::JSON
            )
        )
    );
END;
$$;


--
-- Name: bal_reporte_prestamos_antiguedad(character varying, integer, integer, integer, character varying, boolean, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bal_reporte_prestamos_antiguedad(p_busqueda character varying DEFAULT ''::character varying, p_limite integer DEFAULT 50, p_offset integer DEFAULT 0, p_id_cliente integer DEFAULT NULL::integer, p_rango_dias character varying DEFAULT NULL::character varying, p_excluir_bajas boolean DEFAULT true, p_solo_pendientes boolean DEFAULT true) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_registros JSON;
    v_total BIGINT;
    v_resumen JSON;
BEGIN
    SET TIME ZONE 'America/Lima';

    WITH base AS (
        SELECT
            pd.id AS id_detalle,
            p.id AS id_prestamo,
            p.numero_prestamo,
            p.id_almacen,
            p.id_cliente,
            COALESCE(
                NULLIF(TRIM(c.razon_social), ''),
                NULLIF(TRIM(CONCAT_WS(' ', c.nombres, c.apellido_paterno, c.apellido_materno)), ''),
                c.numero_documento
            ) AS nombre_cliente,
            p.id_proveedor,
            COALESCE(
                NULLIF(TRIM(prov.razon_social), ''),
                NULLIF(TRIM(CONCAT_WS(' ', prov.nombres, prov.apellido_paterno, prov.apellido_materno)), ''),
                prov.numero_documento
            ) AS nombre_proveedor,
            pd.id_balon,
            b.codigo_balon,
            b.numero_serie,
            b.id_tipo_balon,
            tb.nombre AS nombre_tipo_balon,
            tb.capacidad,
            um.nombre AS nombre_unidad_medida,
            b.id_producto_gas,
            pg.nombre AS nombre_producto_gas,
            b.id_marca_cilindro,
            mc.nombre AS nombre_marca_cilindro,
            b.id_organo_inspector,
            oi.nombre AS nombre_organo_inspector,
            b.organo_inspector_no_aplica,
            b.id_planta,
            COALESCE(pl.razon_social, TRIM(CONCAT_WS(' ', pl.nombres, pl.apellido_paterno))) AS nombre_planta,
            b.fecha_proxima_prueba_hidrostatica,
            b.mes_fabricacion,
            b.anio_fabricacion,
            eb.nombre AS nombre_estado_balon,
            COALESCE(pd.fecha_prestamo, pd.fecha_entregado, p.fecha_salida) AS fecha_inicio_prestamo,
            pd.fecha_devolucion,
            pd.fecha_vencimiento,
            pd.dias_prestamo,
            CASE
                WHEN pd.fecha_devolucion IS NOT NULL THEN NULL
                ELSE (CURRENT_DATE - COALESCE(pd.fecha_prestamo, pd.fecha_entregado, p.fecha_salida))::INTEGER
            END AS dias_en_prestamo,
            CASE
                WHEN pd.fecha_devolucion IS NOT NULL THEN 'DEVUELTO'
                WHEN (CURRENT_DATE - COALESCE(pd.fecha_prestamo, pd.fecha_entregado, p.fecha_salida)) >= 180 THEN 'CRITICO_180'
                WHEN (CURRENT_DATE - COALESCE(pd.fecha_prestamo, pd.fecha_entregado, p.fecha_salida)) >= 90 THEN 'SEGUIMIENTO_90_180'
                WHEN (CURRENT_DATE - COALESCE(pd.fecha_prestamo, pd.fecha_entregado, p.fecha_salida)) >= 30 THEN 'ATENCION_30_90'
                ELSE 'RECIENTE_0_30'
            END AS rango_antiguedad
        FROM bal_prestamo_detalle pd
        INNER JOIN bal_prestamo p ON p.id = pd.id_prestamo AND p.estado = 1
        LEFT JOIN bal_balon b ON b.id = pd.id_balon
        LEFT JOIN bal_tipo_balon tb ON b.id_tipo_balon = tb.id
        LEFT JOIN gen_lista_opciones um ON tb.id_unidad_medida = um.id
        LEFT JOIN pro_producto pg ON b.id_producto_gas = pg.id
        LEFT JOIN gen_lista_opciones mc ON b.id_marca_cilindro = mc.id
        LEFT JOIN gen_lista_opciones oi ON b.id_organo_inspector = oi.id
        LEFT JOIN gen_lista_opciones eb ON b.id_estado_balon = eb.id
        LEFT JOIN cli_clientes c ON p.id_cliente = c.id
        LEFT JOIN cli_clientes prov ON p.id_proveedor = prov.id
        LEFT JOIN cli_clientes pl ON b.id_planta = pl.id
        WHERE pd.estado = 1
          AND (p_solo_pendientes = FALSE OR pd.fecha_devolucion IS NULL)
          AND (
              p_excluir_bajas = FALSE
              OR eb.nombre IS NULL
              OR eb.nombre NOT IN ('DADO_DE_BAJA', 'ROBO')
          )
          AND (p_id_cliente IS NULL OR p.id_cliente = p_id_cliente)
          AND COALESCE(pd.fecha_prestamo, pd.fecha_entregado, p.fecha_salida) IS NOT NULL
          AND (
              p_busqueda = ''
              OR gen_texto_coincide(COALESCE(p.numero_prestamo, ''), p_busqueda)
              OR gen_texto_coincide(COALESCE(b.codigo_balon, ''), p_busqueda)
              OR gen_texto_coincide(COALESCE(b.numero_serie, ''), p_busqueda)
              OR gen_texto_coincide(COALESCE(c.razon_social, ''), p_busqueda)
              OR gen_texto_coincide(COALESCE(c.nombres, ''), p_busqueda)
              OR gen_texto_coincide(COALESCE(pg.nombre, ''), p_busqueda)
          )
    ),
    filtrado AS (
        SELECT *
        FROM base
        WHERE (
            p_rango_dias IS NULL
            OR p_rango_dias = ''
            OR rango_antiguedad = p_rango_dias
        )
    ),
    agregado AS (
        SELECT
            (SELECT COUNT(*) FROM filtrado) AS total,
            (
                SELECT COALESCE(json_agg(row_to_json(t)), '[]'::JSON)
                FROM (
                    SELECT *
                    FROM filtrado
                    ORDER BY
                        CASE WHEN dias_en_prestamo IS NULL THEN 1 ELSE 0 END,
                        dias_en_prestamo DESC NULLS LAST,
                        nombre_cliente ASC NULLS LAST,
                        codigo_balon ASC NULLS LAST
                    LIMIT p_limite
                    OFFSET p_offset
                ) t
            ) AS registros,
            (
                SELECT json_build_object(
                    'total_pendientes', COUNT(*) FILTER (WHERE rango_antiguedad <> 'DEVUELTO'),
                    'reciente_0_30', COUNT(*) FILTER (WHERE rango_antiguedad = 'RECIENTE_0_30'),
                    'atencion_30_90', COUNT(*) FILTER (WHERE rango_antiguedad = 'ATENCION_30_90'),
                    'seguimiento_90_180', COUNT(*) FILTER (WHERE rango_antiguedad = 'SEGUIMIENTO_90_180'),
                    'critico_180', COUNT(*) FILTER (WHERE rango_antiguedad = 'CRITICO_180')
                )
                FROM base
            ) AS resumen
    )
    SELECT a.total, a.registros, a.resumen
    INTO v_total, v_registros, v_resumen
    FROM agregado a;

    RETURN json_build_object(
        'registros', COALESCE(v_registros, '[]'::JSON),
        'total', COALESCE(v_total, 0),
        'resumen', COALESCE(
            v_resumen,
            json_build_object(
                'total_pendientes', 0,
                'reciente_0_30', 0,
                'atencion_30_90', 0,
                'seguimiento_90_180', 0,
                'critico_180', 0
            )
        )
    );
END;
$$;


--
-- Name: bal_reporte_prestamos_huerfanos(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bal_reporte_prestamos_huerfanos() RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_registros JSON;
    v_total INTEGER;
BEGIN
    SET TIME ZONE 'America/Lima';

    SELECT
        COALESCE(
            json_agg(
                json_build_object(
                    'id', p.id,
                    'numero_prestamo', p.numero_prestamo,
                    'id_tipo_prestamo', p.id_tipo_prestamo,
                    'nombre_tipo', tp.nombre,
                    'id_cliente', p.id_cliente,
                    'id_comprobante_venta', p.id_comprobante_venta,
                    'id_comprobante_compra', p.id_comprobante_compra,
                    'total_detalles', (
                        SELECT COUNT(*) FROM bal_prestamo_detalle pd
                        WHERE pd.id_prestamo = p.id AND pd.estado = 1
                    ),
                    'total_detalles_con_balon', (
                        SELECT COUNT(*) FROM bal_prestamo_detalle pd
                        WHERE pd.id_prestamo = p.id AND pd.estado = 1 AND pd.id_balon IS NOT NULL
                    ),
                    'fecha_retorno_pactada', p.fecha_retorno_pactada
                )
            ),
            '[]'::JSON
        ),
        COUNT(*)
    INTO v_registros, v_total
    FROM bal_prestamo p
    LEFT JOIN gen_lista_opciones tp ON tp.id = p.id_tipo_prestamo
    WHERE p.estado = 1
      AND p.id_comprobante_venta IS NULL
      AND p.id_comprobante_compra IS NULL
      AND EXISTS (
          SELECT 1 FROM bal_prestamo_detalle pd
          WHERE pd.id_prestamo = p.id AND pd.estado = 1 AND pd.id_balon IS NULL
      );

    RETURN json_build_object(
        'ok', TRUE,
        'total', v_total,
        'registros', v_registros
    );
END;
$$;


--
-- Name: bal_restaurar_balon(integer, integer, character varying, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bal_restaurar_balon(p_id_balon integer, p_id_usuario_auditoria integer DEFAULT NULL::integer, p_observacion character varying DEFAULT NULL::character varying, p_id_almacen integer DEFAULT NULL::integer) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_estado_actual VARCHAR;
    v_id_estado_actual INTEGER;
    v_id_estado_almacen INTEGER;
    v_id_baja INTEGER;
    v_id_motivo INTEGER;
BEGIN
    SET TIME ZONE 'America/Lima';

    SELECT b.id_estado_balon, eb.nombre
    INTO v_id_estado_actual, v_estado_actual
    FROM bal_balon b
    LEFT JOIN gen_lista_opciones eb ON b.id_estado_balon = eb.id
    WHERE b.id = p_id_balon AND b.estado = 1;

    IF NOT FOUND THEN
        RETURN json_build_object('error', 'El balón indicado no existe o está inactivo', 'registro', NULL);
    END IF;

    IF v_estado_actual IS NULL OR v_estado_actual NOT IN ('DADO_DE_BAJA', 'ROBO') THEN
        RETURN json_build_object(
            'error',
            'Solo se pueden reactivar cilindros dados de baja o reportados como robo',
            'registro', NULL
        );
    END IF;

    IF EXISTS (
        SELECT 1 FROM bal_baja_balon
        WHERE id_balon = p_id_balon AND estado = 1 AND estado_aprobacion = 'PENDIENTE'
    ) THEN
        RETURN json_build_object(
            'error',
            'Hay una solicitud de baja pendiente. Resuélvala antes de reactivar.',
            'registro', NULL
        );
    END IF;

    SELECT lo.id INTO v_id_estado_almacen
    FROM gen_lista_opciones lo
    INNER JOIN gen_lista l ON lo.id_lista = l.id
    WHERE l.nombre = 'EstadoBalon' AND lo.nombre = 'EN_ALMACEN' AND lo.estado = 1;

    IF v_id_estado_almacen IS NULL THEN
        RETURN json_build_object('error', 'No está configurado el estado EN_ALMACEN', 'registro', NULL);
    END IF;

    SELECT bb.id, bb.id_motivo_baja
    INTO v_id_baja, v_id_motivo
    FROM bal_baja_balon bb
    WHERE bb.id_balon = p_id_balon
      AND bb.estado = 1
      AND bb.estado_aprobacion = 'APROBADA'
    ORDER BY bb.fecha_autorizacion DESC NULLS LAST, bb.id DESC
    LIMIT 1;

    IF v_id_baja IS NOT NULL THEN
        UPDATE bal_baja_balon
        SET
            estado_aprobacion = 'REACTIVADA',
            id_usuario_modificacion = p_id_usuario_auditoria,
            fecha_modificacion = NOW()
        WHERE id = v_id_baja;
    END IF;

    UPDATE bal_balon
    SET
        id_estado_balon = v_id_estado_almacen,
        id_almacen = COALESCE(p_id_almacen, id_almacen),
        id_usuario_modificacion = p_id_usuario_auditoria,
        fecha_modificacion = NOW()
    WHERE id = p_id_balon AND estado = 1;

    PERFORM bal_registrar_estado_historial(
        p_id_balon,
        'REACTIVACION',
        v_id_baja,
        v_id_motivo,
        v_id_estado_actual,
        v_id_estado_almacen,
        COALESCE(NULLIF(TRIM(p_observacion), ''), 'Cilindro reactivado / reintegrado al parque'),
        p_id_usuario_auditoria,
        NOW()
    );

    RETURN bal_obtener_balon(p_id_balon);
END;
$$;


--
-- Name: bal_revertir_salidas_guia_remision(integer, integer[], integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bal_revertir_salidas_guia_remision(p_id_guia integer, p_ids_conservar integer[] DEFAULT NULL::integer[], p_id_usuario_auditoria integer DEFAULT NULL::integer) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_result JSON;
    v_revertidos INTEGER;
    v_mov JSON;
    v_balones INTEGER[];
    v_tipos VARCHAR[];
    v_clientes INTEGER[];
    v_almacenes_origen INTEGER[];
    v_almacenes_destino INTEGER[];
    v_i INTEGER;
BEGIN
    SET TIME ZONE 'America/Lima';

    -- Capturar el tipo/cliente/almacén original de los balones a conservar ANTES de
    -- revertir, para poder re-registrarlos igual a como estaban (no siempre es
    -- SALIDA_PRESTAMO: puede ser TRASLADO_LIMA, SALIDA_PLANTA_EXTERNA, etc.).
    IF p_ids_conservar IS NOT NULL AND array_length(p_ids_conservar, 1) > 0 THEN
        SELECT
            array_agg(m.id_balon ORDER BY m.id),
            array_agg(tm.nombre ORDER BY m.id),
            array_agg(m.id_cliente ORDER BY m.id),
            array_agg(m.id_almacen_origen ORDER BY m.id),
            array_agg(m.id_almacen_destino ORDER BY m.id)
        INTO v_balones, v_tipos, v_clientes, v_almacenes_origen, v_almacenes_destino
        FROM inv_movimiento m
        INNER JOIN gen_lista_opciones tm ON tm.id = m.id_tipo_movimiento
        INNER JOIN gen_lista_opciones tdo ON tdo.id = m.id_tipo_documento_origen
        WHERE m.estado = 1
          AND m.naturaleza = 'BALON'
          AND tdo.nombre = 'GRE'
          AND m.id_documento_origen = p_id_guia
          AND m.id_balon = ANY (p_ids_conservar);
    END IF;

    -- Revertir todos los inv_movimiento de esta GRE
    v_result := inv_revertir_por_documento(
        'GRE',
        p_id_guia,
        p_id_usuario_auditoria
    );

    v_revertidos := COALESCE((v_result->>'revertidos')::INTEGER, 0);

    -- Re-registrar los conservados con su tipo/cliente/almacén original
    IF v_balones IS NOT NULL THEN
        FOR v_i IN 1 .. array_length(v_balones, 1)
        LOOP
            v_mov := inv_registrar_movimiento(
                p_naturaleza                => 'BALON',
                p_codigo_tipo_movimiento    => v_tipos[v_i],
                p_fecha                     => NOW(),
                p_id_balon                  => v_balones[v_i],
                p_cantidad                  => 1,
                p_id_almacen_origen         => v_almacenes_origen[v_i],
                p_id_almacen_destino        => v_almacenes_destino[v_i],
                p_id_cliente                => v_clientes[v_i],
                p_codigo_tipo_documento_origen => 'GRE',
                p_id_documento_origen       => p_id_guia,
                p_glosa                     => 'Re-registro conservado de GRE',
                p_id_usuario_auditoria      => p_id_usuario_auditoria
            );
            IF v_mov->>'error' IS NOT NULL THEN
                RAISE EXCEPTION '%', v_mov->>'error';
            END IF;
        END LOOP;
    END IF;

    RETURN json_build_object('ok', TRUE, 'revertidos', v_revertidos, 'error', NULL);
END;
$$;


--
-- Name: bal_solicitar_baja_balon(integer, integer, integer, character varying, integer, integer, character varying, character varying, numeric, character varying, date, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bal_solicitar_baja_balon(p_id_balon integer, p_id_motivo_baja integer, p_id_usuario_solicita integer, p_motivo_detalle character varying DEFAULT NULL::character varying, p_id_cliente_comprador integer DEFAULT NULL::integer, p_id_comprobante_venta integer DEFAULT NULL::integer, p_serie_comprobante character varying DEFAULT NULL::character varying, p_numero_comprobante character varying DEFAULT NULL::character varying, p_monto_venta numeric DEFAULT NULL::numeric, p_observacion character varying DEFAULT NULL::character varying, p_fecha_baja date DEFAULT NULL::date, p_id_usuario_auditoria integer DEFAULT NULL::integer) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_id_baja INTEGER;
    v_nombre_motivo VARCHAR;
    v_id_estado_actual INTEGER;
    v_id_usuario INTEGER;
BEGIN
    SET TIME ZONE 'America/Lima';

    IF p_id_motivo_baja IS NULL THEN
        RETURN json_build_object('error', 'El motivo de baja es obligatorio', 'registro', NULL);
    END IF;

    IF p_id_usuario_solicita IS NULL THEN
        RETURN json_build_object('error', 'Debe indicar el usuario solicitante', 'registro', NULL);
    END IF;

    SELECT id_estado_balon INTO v_id_estado_actual
    FROM bal_balon
    WHERE id = p_id_balon AND estado = 1;

    IF NOT FOUND THEN
        RETURN json_build_object('error', 'El balón indicado no existe o está inactivo', 'registro', NULL);
    END IF;

    IF EXISTS (
        SELECT 1
        FROM bal_baja_balon
        WHERE id_balon = p_id_balon
          AND estado = 1
          AND estado_aprobacion IN ('PENDIENTE', 'APROBADA')
    ) THEN
        RETURN json_build_object('error', 'El balón ya tiene una solicitud o baja activa', 'registro', NULL);
    END IF;

    SELECT lo.nombre
    INTO v_nombre_motivo
    FROM gen_lista_opciones lo
    INNER JOIN gen_lista l ON lo.id_lista = l.id
    WHERE lo.id = p_id_motivo_baja
      AND l.nombre = 'MotivoBajaBalon'
      AND lo.estado = 1;

    IF v_nombre_motivo IS NULL THEN
        RETURN json_build_object('error', 'El motivo de baja indicado no es válido', 'registro', NULL);
    END IF;

    IF v_nombre_motivo = 'OTROS' AND (p_motivo_detalle IS NULL OR TRIM(p_motivo_detalle) = '') THEN
        RETURN json_build_object('error', 'Debe indicar el detalle cuando el motivo de baja es OTROS', 'registro', NULL);
    END IF;

    v_id_usuario := COALESCE(p_id_usuario_auditoria, p_id_usuario_solicita);

    INSERT INTO bal_baja_balon (
        id_balon, id_motivo_baja, fecha_baja,
        id_usuario_solicita, estado_aprobacion,
        motivo_detalle, id_cliente_comprador, id_comprobante_venta,
        serie_comprobante, numero_comprobante, monto_venta, observacion,
        id_usuario_creacion, id_usuario_modificacion
    )
    VALUES (
        p_id_balon, p_id_motivo_baja, COALESCE(p_fecha_baja, CURRENT_DATE),
        p_id_usuario_solicita, 'PENDIENTE',
        NULLIF(TRIM(p_motivo_detalle), ''), p_id_cliente_comprador, p_id_comprobante_venta,
        p_serie_comprobante, p_numero_comprobante, p_monto_venta, p_observacion,
        v_id_usuario,
        v_id_usuario
    )
    RETURNING id INTO v_id_baja;

    PERFORM bal_registrar_estado_historial(
        p_id_balon,
        'SOLICITUD_BAJA',
        v_id_baja,
        p_id_motivo_baja,
        v_id_estado_actual,
        NULL,
        COALESCE(NULLIF(TRIM(p_motivo_detalle), ''), NULLIF(TRIM(p_observacion), ''), 'Solicitud de baja'),
        v_id_usuario,
        NOW()
    );

    RETURN bal_obtener_baja_balon(v_id_baja);
END;
$$;


--
-- Name: bal_sugerir_balon_origen_recarga(integer, numeric, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bal_sugerir_balon_origen_recarga(p_id_producto_gas integer, p_capacidad_requerida numeric DEFAULT NULL::numeric, p_id_almacen integer DEFAULT NULL::integer) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_asignacion JSON;
    v_principal JSON;
BEGIN
    IF COALESCE(p_capacidad_requerida, 0) > 0 THEN
        v_asignacion := bal_asignar_origenes_recarga(
            p_id_producto_gas,
            p_capacidad_requerida,
            p_id_almacen,
            NULL
        );

        IF v_asignacion->>'error' IS NOT NULL THEN
            RETURN json_build_object('error', v_asignacion->>'error', 'registro', NULL);
        END IF;

        v_principal := (v_asignacion->'origenes')->0;
        IF v_principal IS NULL OR v_principal::TEXT = 'null' THEN
            RETURN json_build_object(
                'error',
                'No hay balón empresa LLENO del mismo gas con stock en almacén',
                'registro',
                NULL
            );
        END IF;

        RETURN json_build_object(
            'registro', json_build_object(
                'id', (v_principal->>'id_balon')::INTEGER,
                'codigo_balon', v_principal->>'codigo_balon',
                'capacidad_disponible', (v_principal->>'capacidad_disponible')::NUMERIC,
                'capacidad_tipo', (v_principal->>'capacidad_tipo')::NUMERIC,
                'nombre_almacen', v_principal->>'nombre_almacen',
                'asignacion_etiqueta', v_asignacion->>'etiqueta',
                'origenes', v_asignacion->'origenes'
            )
        );
    END IF;

    -- Sin capacidad: primer balón con stock (FIFO)
    RETURN (
        SELECT json_build_object(
            'registro', row_to_json(t)
        )
        FROM (
            SELECT
                b.id,
                b.codigo_balon,
                bal_capacidad_disponible_balon(b.id) AS capacidad_disponible,
                tb.capacidad AS capacidad_tipo,
                a.nombre AS nombre_almacen
            FROM bal_balon b
            LEFT JOIN bal_tipo_balon tb ON tb.id = b.id_tipo_balon
            LEFT JOIN gen_almacen a ON a.id = b.id_almacen
            LEFT JOIN gen_lista_opciones prop ON prop.id = b.id_propietario
            LEFT JOIN gen_lista_opciones eb ON eb.id = b.id_estado_balon
            WHERE b.estado = 1
              AND COALESCE(prop.nombre, '') IN ('EMPRESA', 'PROPIA')
              AND COALESCE(eb.nombre, '') = 'EN_ALMACEN'
              AND b.id_producto_gas = p_id_producto_gas
              AND (p_id_almacen IS NULL OR b.id_almacen = p_id_almacen)
              AND bal_capacidad_disponible_balon(b.id) > 0
            ORDER BY b.fecha_creacion ASC NULLS LAST, b.id ASC
            LIMIT 1
        ) t
    );
END;
$$;


--
-- Name: bal_sync_ph_desde_mantenimiento(integer, integer, integer, integer, boolean, character varying); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bal_sync_ph_desde_mantenimiento(p_id_mantenimiento integer, p_id_usuario_auditoria integer DEFAULT NULL::integer, p_vigencia_anios integer DEFAULT NULL::integer, p_id_organo_inspector integer DEFAULT NULL::integer, p_organo_inspector_no_aplica boolean DEFAULT NULL::boolean, p_numero_certificado character varying DEFAULT NULL::character varying) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_row RECORD;
BEGIN
    SELECT
        m.id,
        m.id_balon,
        m.fecha_salida,
        m.descripcion,
        m.observacion,
        tm.nombre AS nombre_tipo
    INTO v_row
    FROM bal_mantenimiento m
    LEFT JOIN gen_lista_opciones tm ON m.id_tipo_mantenimiento = tm.id
    WHERE m.id = p_id_mantenimiento AND m.estado = 1;

    IF NOT FOUND OR v_row.fecha_salida IS NULL THEN
        RETURN;
    END IF;

    IF UPPER(COALESCE(v_row.nombre_tipo, '')) NOT IN ('PRUEBA_HIDROSTATICA', 'RECERTIFICACION') THEN
        RETURN;
    END IF;

    IF EXISTS (
        SELECT 1
        FROM bal_balon_ph_historial
        WHERE id_mantenimiento = p_id_mantenimiento AND estado = 1
    ) THEN
        RETURN;
    END IF;

    PERFORM bal_registrar_ph_historial(
        v_row.id_balon,
        v_row.fecha_salida,
        p_vigencia_anios,
        p_id_organo_inspector,
        COALESCE(p_organo_inspector_no_aplica, FALSE),
        p_numero_certificado,
        p_id_mantenimiento,
        NULL,
        NULLIF(TRIM(COALESCE(v_row.descripcion, v_row.observacion, '')), ''),
        p_id_usuario_auditoria
    );
END;
$$;


--
-- Name: bal_sync_ph_desde_recarga(integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bal_sync_ph_desde_recarga(p_id_movimiento_recarga integer, p_id_usuario_auditoria integer DEFAULT NULL::integer) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_row RECORD;
BEGIN
    SELECT
        r.id,
        r.id_balon,
        r.fecha_prueba_hidrostatica,
        r.observacion
    INTO v_row
    FROM bal_movimiento_recarga r
    WHERE r.id = p_id_movimiento_recarga AND r.estado = 1;

    IF NOT FOUND OR v_row.fecha_prueba_hidrostatica IS NULL THEN
        RETURN;
    END IF;

    IF EXISTS (
        SELECT 1
        FROM bal_balon_ph_historial
        WHERE id_movimiento_recarga = p_id_movimiento_recarga AND estado = 1
    ) THEN
        RETURN;
    END IF;

    PERFORM bal_registrar_ph_historial(
        v_row.id_balon,
        v_row.fecha_prueba_hidrostatica,
        NULL,
        NULL,
        NULL,
        NULL,
        NULL,
        p_id_movimiento_recarga,
        NULLIF(TRIM(COALESCE(v_row.observacion, '')), ''),
        p_id_usuario_auditoria
    );
END;
$$;


--
-- Name: bal_tara_lb_tipo(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bal_tara_lb_tipo(p_id_tipo_balon integer) RETURNS numeric
    LANGUAGE plpgsql STABLE
    AS $$
DECLARE
    v_tara_lb NUMERIC;
    v_peso_kg NUMERIC;
BEGIN
    IF p_id_tipo_balon IS NULL THEN
        RETURN NULL;
    END IF;

    SELECT tb.peso_tara_lb, tb.peso
    INTO v_tara_lb, v_peso_kg
    FROM bal_tipo_balon tb
    WHERE tb.id = p_id_tipo_balon AND tb.estado = 1;

    IF v_tara_lb IS NOT NULL AND v_tara_lb > 0 THEN
        RETURN ROUND(v_tara_lb, 4);
    END IF;

    IF v_peso_kg IS NOT NULL AND v_peso_kg > 0 THEN
        RETURN ROUND(v_peso_kg * 2.20462, 4);
    END IF;

    RETURN NULL;
END;
$$;


--
-- Name: bal_validar_codigos_recojo(integer, json); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bal_validar_codigos_recojo(p_id_recojo integer, p_codigos json DEFAULT '[]'::json) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_estado VARCHAR;
    v_codigos TEXT[];
    v_esperados JSONB := '[]'::JSONB;
    v_coinciden JSONB := '[]'::JSONB;
    v_faltantes JSONB := '[]'::JSONB;
    v_no_pertenecen JSONB := '[]'::JSONB;
    v_rec RECORD;
    v_codigo TEXT;
    v_encontrado BOOLEAN;
    v_idx INTEGER;
BEGIN
    SET TIME ZONE 'America/Lima';

    SELECT er.nombre
    INTO v_estado
    FROM bal_recojo r
    LEFT JOIN gen_lista_opciones er ON er.id = r.id_estado
    WHERE r.id = p_id_recojo AND r.estado = 1;

    IF v_estado IS NULL THEN
        RETURN json_build_object('error', 'Recojo no encontrado', 'registro', NULL);
    END IF;

    IF v_estado NOT IN ('PROGRAMADO', 'EN_RUTA') THEN
        RETURN json_build_object(
            'error', 'Solo se pueden validar códigos en recojos PROGRAMADO o EN_RUTA',
            'registro', NULL
        );
    END IF;

    -- Detalles esperados (con el código de cilindro vinculado).
    FOR v_rec IN
        SELECT
            rd.id AS id_recojo_detalle,
            rd.id_prestamo_detalle,
            rd.id_alquiler_detalle,
            COALESCE(pd.id_balon, ad.id_balon) AS id_balon,
            b.codigo_balon
        FROM bal_recojo_detalle rd
        LEFT JOIN bal_prestamo_detalle pd ON pd.id = rd.id_prestamo_detalle AND pd.estado = 1
        LEFT JOIN bal_alquiler_detalle ad ON ad.id = rd.id_alquiler_detalle AND ad.estado = 1
        LEFT JOIN bal_balon b ON b.id = COALESCE(pd.id_balon, ad.id_balon) AND b.estado = 1
        WHERE rd.id_recojo = p_id_recojo AND rd.estado = 1
    LOOP
        v_esperados := v_esperados || jsonb_build_object(
            'idRecojoDetalle', v_rec.id_recojo_detalle,
            'idPrestamoDetalle', v_rec.id_prestamo_detalle,
            'idAlquilerDetalle', v_rec.id_alquiler_detalle,
            'idBalon', v_rec.id_balon,
            'codigo', v_rec.codigo_balon
        );
    END LOOP;

    -- Normaliza los códigos escaneados a un array de texto.
    SELECT COALESCE(
        ARRAY_AGG(NULLIF(TRIM(VALUE::TEXT), '"')),
        ARRAY[]::TEXT[]
    )
    INTO v_codigos
    FROM json_array_elements_text(COALESCE(p_codigos::JSON, '[]'::JSON));

    -- Marca los detalles cuyo código fue escaneado.
    v_idx := 0;
    WHILE v_idx < jsonb_array_length(v_esperados)
    LOOP
        v_rec := NULL;
        SELECT
            (v_esperados -> v_idx ->> 'idRecojoDetalle')::INTEGER AS id_recojo_detalle,
            (v_esperados -> v_idx ->> 'idPrestamoDetalle')::INTEGER AS id_prestamo_detalle,
            (v_esperados -> v_idx ->> 'idAlquilerDetalle')::INTEGER AS id_alquiler_detalle,
            (v_esperados -> v_idx ->> 'idBalon')::INTEGER AS id_balon,
            v_esperados -> v_idx ->> 'codigo' AS codigo
        INTO v_rec;

        v_encontrado := FALSE;
        IF v_rec.codigo IS NOT NULL THEN
            SELECT TRUE INTO v_encontrado
            FROM unnest(v_codigos) c
            WHERE UPPER(c) = UPPER(v_rec.codigo);
        END IF;

        IF v_encontrado THEN
            v_coinciden := v_coinciden || (v_esperados -> v_idx);
        ELSE
            v_faltantes := v_faltantes || (v_esperados -> v_idx);
        END IF;

        v_idx := v_idx + 1;
    END LOOP;

    -- Códigos escaneados que no corresponden a ningún detalle del recojo.
    SELECT COALESCE(
        jsonb_agg(DISTINCT to_jsonb(c)),
        '[]'::JSONB
    )
    INTO v_no_pertenecen
    FROM unnest(v_codigos) c
    WHERE NOT EXISTS (
        SELECT 1 FROM jsonb_array_elements(v_esperados) e
        WHERE e ->> 'codigo' IS NOT NULL
          AND UPPER(e ->> 'codigo') = UPPER(c)
    );

    RETURN json_build_object(
        'ok', TRUE,
        'total', jsonb_array_length(v_esperados),
        'coinciden', v_coinciden,
        'faltantes', v_faltantes,
        'no_pertenecen', v_no_pertenecen,
        'completo', jsonb_array_length(v_faltantes) = 0
    );
END;
$$;


--
-- Name: bal_vincular_recarga_cliente_comprobante(integer, integer, integer, integer, numeric, integer, character varying, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bal_vincular_recarga_cliente_comprobante(p_id_comprobante integer, p_id_cliente integer, p_id_balon integer, p_id_producto integer, p_capacidad numeric DEFAULT NULL::numeric, p_id_almacen integer DEFAULT NULL::integer, p_observacion character varying DEFAULT NULL::character varying, p_id_balon_origen integer DEFAULT NULL::integer, p_id_usuario_auditoria integer DEFAULT NULL::integer) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_fecha DATE;
    v_id_tipo_recarga INTEGER;
    v_id_tipo_movimiento INTEGER;
    v_id_tipo_documento_ref INTEGER;
    v_id_recarga INTEGER;
    v_serie_comprobante VARCHAR;
    v_numero_comprobante VARCHAR;
    v_capacidad NUMERIC;
    v_capacidad_destino NUMERIC;
    v_recarga JSON;
    v_asignacion JSON;
    v_origenes JSON;
    v_id_balon_origen_principal INTEGER;
    v_mov JSON;
BEGIN
    SET TIME ZONE 'America/Lima';
    v_fecha := CURRENT_DATE;

    IF p_id_comprobante IS NULL THEN
        RETURN json_build_object('error', 'El comprobante es obligatorio', 'registro', NULL);
    END IF;

    IF p_id_cliente IS NULL THEN
        RETURN json_build_object('error', 'El cliente es obligatorio', 'registro', NULL);
    END IF;

    IF p_id_balon IS NULL THEN
        RETURN json_build_object('error', 'El balón es obligatorio', 'registro', NULL);
    END IF;

    IF p_id_producto IS NULL THEN
        RETURN json_build_object('error', 'El producto (gas) es obligatorio', 'registro', NULL);
    END IF;

    IF p_id_balon_origen IS NOT NULL AND p_id_balon_origen = p_id_balon THEN
        RETURN json_build_object(
            'error',
            'El balón origen no puede ser el mismo que el destino',
            'registro',
            NULL
        );
    END IF;

    IF NOT EXISTS (
        SELECT 1 FROM ven_comprobante WHERE id = p_id_comprobante AND estado = 1
    ) THEN
        RETURN json_build_object('error', 'El comprobante indicado no existe o está inactivo', 'registro', NULL);
    END IF;

    IF NOT EXISTS (
        SELECT 1 FROM cli_clientes WHERE id = p_id_cliente AND estado = 1
    ) THEN
        RETURN json_build_object('error', 'El cliente indicado no existe o está inactivo', 'registro', NULL);
    END IF;

    IF NOT EXISTS (
        SELECT 1 FROM bal_balon WHERE id = p_id_balon AND estado = 1
    ) THEN
        RETURN json_build_object('error', 'El balón indicado no existe o está inactivo', 'registro', NULL);
    END IF;

    IF NOT EXISTS (
        SELECT 1 FROM pro_producto WHERE id = p_id_producto AND estado = 1 AND es_gas = TRUE
    ) THEN
        RETURN json_build_object('error', 'El producto indicado no es un gas activo', 'registro', NULL);
    END IF;

    IF EXISTS (
        SELECT 1
        FROM bal_movimiento_recarga
        WHERE id_comprobante = p_id_comprobante
          AND id_balon = p_id_balon
          AND estado = 1
    ) THEN
        RETURN json_build_object(
            'error',
            'Ya existe una recarga vinculada a este comprobante y balón',
            'registro',
            NULL
        );
    END IF;

    SELECT
        COALESCE(tb.capacidad, p_capacidad, 0)
    INTO v_capacidad_destino
    FROM bal_balon b
    LEFT JOIN bal_tipo_balon tb ON tb.id = b.id_tipo_balon
    WHERE b.id = p_id_balon;

    v_capacidad := COALESCE(NULLIF(p_capacidad, 0), v_capacidad_destino, 0);

    IF v_capacidad <= 0 THEN
        RETURN json_build_object(
            'error',
            'No se pudo determinar la capacidad a recargar',
            'registro',
            NULL
        );
    END IF;

    v_asignacion := bal_asignar_origenes_recarga(
        p_id_producto,
        v_capacidad,
        p_id_almacen,
        p_id_balon_origen
    );

    IF v_asignacion->>'error' IS NOT NULL THEN
        RETURN json_build_object('error', v_asignacion->>'error', 'registro', NULL);
    END IF;

    v_origenes := v_asignacion->'origenes';
    v_id_balon_origen_principal := (v_asignacion->>'id_balon_origen_principal')::INTEGER;

    SELECT lo.id INTO v_id_tipo_recarga
    FROM gen_lista_opciones lo
    INNER JOIN gen_lista l ON lo.id_lista = l.id
    WHERE l.nombre = 'TipoRecarga' AND lo.nombre = 'CLIENTE' AND lo.estado = 1
    LIMIT 1;

    SELECT lo.id INTO v_id_tipo_movimiento
    FROM gen_lista_opciones lo
    INNER JOIN gen_lista l ON lo.id_lista = l.id
    WHERE l.nombre = 'TipoMovBalon' AND lo.nombre = 'RECARGA_CLIENTE' AND lo.estado = 1
    LIMIT 1;

    IF v_id_tipo_movimiento IS NULL THEN
        SELECT lo.id INTO v_id_tipo_movimiento
        FROM gen_lista_opciones lo
        INNER JOIN gen_lista l ON lo.id_lista = l.id
        WHERE l.nombre = 'TipoMovBalon' AND lo.nombre = 'RECARGA' AND lo.estado = 1
        LIMIT 1;
    END IF;

    SELECT lo.id INTO v_id_tipo_documento_ref
    FROM gen_lista_opciones lo
    INNER JOIN gen_lista l ON lo.id_lista = l.id
    WHERE l.nombre = 'TipoDocumentoRef' AND lo.nombre = 'RECARGA' AND lo.estado = 1
    LIMIT 1;

    SELECT serie, numero INTO v_serie_comprobante, v_numero_comprobante
    FROM ven_comprobante
    WHERE id = p_id_comprobante;

    -- El stock de gas ya se validó en bal_asignar_origenes_recarga (pro_stock) y se
    -- descuenta más abajo vía inv_registrar_movimiento; ya no hay capacidad por
    -- cilindro que "consumir" aparte.

    INSERT INTO bal_movimiento_recarga (
        fecha_salida_almacen,
        id_balon,
        id_balon_origen,
        id_cliente,
        id_tipo_recarga,
        id_producto,
        capacidad,
        serie_factura,
        numero_factura,
        id_comprobante,
        fecha_llegada_almacen,
        observacion,
        id_almacen,
        id_usuario_creacion,
        id_usuario_modificacion
    )
    VALUES (
        v_fecha,
        p_id_balon,
        v_id_balon_origen_principal,
        p_id_cliente,
        v_id_tipo_recarga,
        p_id_producto,
        v_capacidad,
        v_serie_comprobante,
        v_numero_comprobante,
        p_id_comprobante,
        v_fecha,
        CASE
            WHEN COALESCE(v_asignacion->>'etiqueta', '') <> '' THEN
                TRIM(BOTH ' ' FROM CONCAT_WS(
                    ' | ',
                    NULLIF(TRIM(COALESCE(p_observacion, '')), ''),
                    'Orígenes: ' || (v_asignacion->>'etiqueta')
                ))
            ELSE p_observacion
        END,
        p_id_almacen,
        p_id_usuario_auditoria,
        p_id_usuario_auditoria
    )
    RETURNING id INTO v_id_recarga;

    INSERT INTO bal_movimiento_recarga_origen (
        id_movimiento_recarga,
        id_balon,
        cantidad,
        orden,
        id_usuario_creacion
    )
    SELECT
        v_id_recarga,
        (o->>'id_balon')::INTEGER,
        (o->>'cantidad')::NUMERIC,
        COALESCE((o->>'orden')::INTEGER, 1),
        p_id_usuario_auditoria
    FROM json_array_elements(v_origenes) o;

    IF v_id_tipo_movimiento IS NOT NULL THEN
        v_mov := inv_registrar_movimiento(
            p_naturaleza                => 'BALON',
            p_codigo_tipo_movimiento    => 'RECARGA_CLIENTE',
            p_fecha                     => NOW(),
            p_id_producto               => p_id_producto,
            p_id_balon                  => p_id_balon,
            p_cantidad                  => v_capacidad,
            p_id_almacen_origen         => p_id_almacen,
            p_id_almacen_destino        => NULL,
            p_id_cliente                => p_id_cliente,
            p_codigo_tipo_documento_origen => 'RECARGA',
            p_id_documento_origen       => v_id_recarga,
            p_glosa                     => COALESCE(p_observacion, 'Recarga cliente (POS)'),
            p_id_usuario_auditoria      => p_id_usuario_auditoria
        );
        IF v_mov->>'error' IS NOT NULL THEN
            RAISE EXCEPTION '%', v_mov->>'error';
        END IF;
    END IF;

    -- inv_registrar_movimiento ya actualizó id_estado_balon, id_cliente_ubicacion, id_almacen.
    -- Solo fijamos id_producto_gas y limpiamos presion/contenido.
    UPDATE bal_balon
    SET
        id_producto_gas = p_id_producto,
        presion_actual = NULL,
        id_usuario_modificacion = p_id_usuario_auditoria,
        fecha_modificacion = NOW()
    WHERE id = p_id_balon AND estado = 1;

    v_recarga := bal_obtener_movimiento_recarga(v_id_recarga);

    RETURN json_build_object('registro', v_recarga->'registro');
END;
$$;


--
-- Name: cli_actualizar_contacto(integer, integer, character varying, character varying, character varying, character varying, character varying, character varying, character varying, character varying, boolean, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cli_actualizar_contacto(p_id integer, p_id_cliente integer DEFAULT NULL::integer, p_nombre character varying DEFAULT NULL::character varying, p_apellido_paterno character varying DEFAULT NULL::character varying, p_apellido_materno character varying DEFAULT NULL::character varying, p_direccion character varying DEFAULT NULL::character varying, p_email character varying DEFAULT NULL::character varying, p_telefono1 character varying DEFAULT NULL::character varying, p_telefono2 character varying DEFAULT NULL::character varying, p_telefono3 character varying DEFAULT NULL::character varying, p_es_principal boolean DEFAULT NULL::boolean, p_id_usuario_auditoria integer DEFAULT NULL::integer) RETURNS json
    LANGUAGE plpgsql
    AS $$
BEGIN
    SET TIME ZONE 'America/Lima';

    -- Validar existencia
    IF NOT EXISTS (SELECT 1 FROM cli_contacto WHERE id = p_id) THEN
        RETURN json_build_object('error', 'El contacto no existe', 'registro', NULL);
    END IF;

    -- Logica de contacto principal
    IF p_es_principal = TRUE THEN
        UPDATE cli_contacto 
        SET es_principal = FALSE 
        WHERE id_cliente = COALESCE(p_id_cliente, (SELECT id_cliente FROM cli_contacto WHERE id = p_id));
    END IF;

    UPDATE cli_contacto
    SET 
        id_cliente       = COALESCE(p_id_cliente, id_cliente),
        nombre           = COALESCE(p_nombre, nombre),
        apellido_paterno = COALESCE(p_apellido_paterno, apellido_paterno),
        apellido_materno = COALESCE(p_apellido_materno, apellido_materno),
        direccion        = COALESCE(p_direccion, direccion),
        email            = COALESCE(p_email, email),
        telefono1        = COALESCE(p_telefono1, telefono1),
        telefono2        = COALESCE(p_telefono2, telefono2),
        telefono3        = COALESCE(p_telefono3, telefono3),
        es_principal     = COALESCE(p_es_principal, es_principal),
        id_usuario_modificacion = COALESCE(p_id_usuario_auditoria, id_usuario_modificacion),
        fecha_modificacion = NOW()
    WHERE id = p_id;

    RETURN cli_obtener_por_id_contacto(p_id);
END;
$$;


--
-- Name: cli_actualizar_direccion(integer, integer, character varying, character varying, integer, integer, integer, integer, character varying, numeric, numeric, boolean, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cli_actualizar_direccion(p_id integer, p_id_cliente integer DEFAULT NULL::integer, p_direccion character varying DEFAULT NULL::character varying, p_descripcion character varying DEFAULT NULL::character varying, p_id_pais integer DEFAULT NULL::integer, p_id_departamento integer DEFAULT NULL::integer, p_id_provincia integer DEFAULT NULL::integer, p_id_distrito integer DEFAULT NULL::integer, p_referencia character varying DEFAULT NULL::character varying, p_latitud numeric DEFAULT NULL::numeric, p_longitud numeric DEFAULT NULL::numeric, p_es_principal boolean DEFAULT NULL::boolean, p_id_usuario_auditoria integer DEFAULT NULL::integer) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_id_cliente INTEGER;
BEGIN
    SET TIME ZONE 'America/Lima';

    SELECT id_cliente INTO v_id_cliente
    FROM cli_direcciones
    WHERE id = p_id AND estado = 1;

    IF NOT FOUND THEN
        RETURN json_build_object('registro', NULL);
    END IF;

    IF p_es_principal IS TRUE THEN
        UPDATE cli_direcciones
        SET es_principal = FALSE,
            id_usuario_modificacion = p_id_usuario_auditoria,
            fecha_modificacion = NOW()
        WHERE id_cliente = v_id_cliente AND estado = 1 AND id <> p_id;
    END IF;

    UPDATE cli_direcciones
    SET
        id_cliente = COALESCE(p_id_cliente, id_cliente),
        direccion = COALESCE(p_direccion, direccion),
        descripcion = COALESCE(p_descripcion, descripcion),
        id_pais = COALESCE(p_id_pais, id_pais),
        id_departamento = COALESCE(p_id_departamento, id_departamento),
        id_provincia = COALESCE(p_id_provincia, id_provincia),
        id_distrito = COALESCE(p_id_distrito, id_distrito),
        referencia = COALESCE(p_referencia, referencia),
        latitud = COALESCE(p_latitud, latitud),
        longitud = COALESCE(p_longitud, longitud),
        es_principal = COALESCE(p_es_principal, es_principal),
        id_usuario_modificacion = p_id_usuario_auditoria,
        fecha_modificacion = NOW()
    WHERE id = p_id AND estado = 1;

    RETURN cli_obtener_por_id_direccion(p_id);
END;
$$;


--
-- Name: cli_actualizar_por_id_cliente(integer, character varying, character varying, integer, integer, character varying, character varying, character varying, integer, character varying, character varying, character varying, boolean, boolean, boolean, boolean, character varying, character varying, character varying, character varying, character varying, integer, integer, integer, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cli_actualizar_por_id_cliente(p_id integer, p_codigo_interno character varying DEFAULT NULL::character varying, p_razon_social character varying DEFAULT NULL::character varying, p_id_tipo_cliente integer DEFAULT NULL::integer, p_id_tipo_persona integer DEFAULT NULL::integer, p_nombres character varying DEFAULT NULL::character varying, p_apellido_paterno character varying DEFAULT NULL::character varying, p_apellido_materno character varying DEFAULT NULL::character varying, p_id_tipo_documento integer DEFAULT NULL::integer, p_numero_documento character varying DEFAULT NULL::character varying, p_telefono character varying DEFAULT NULL::character varying, p_email character varying DEFAULT NULL::character varying, p_es_agente_percepcion boolean DEFAULT NULL::boolean, p_es_buen_contribuyente boolean DEFAULT NULL::boolean, p_es_agente_retenedor boolean DEFAULT NULL::boolean, p_afecto_rus boolean DEFAULT NULL::boolean, p_situacion_sunat character varying DEFAULT NULL::character varying, p_estado_contribuyente_sunat character varying DEFAULT NULL::character varying, p_observacion character varying DEFAULT NULL::character varying, p_direccion character varying DEFAULT NULL::character varying, p_referencia character varying DEFAULT NULL::character varying, p_id_departamento integer DEFAULT NULL::integer, p_id_provincia integer DEFAULT NULL::integer, p_id_distrito integer DEFAULT NULL::integer, p_id_pais integer DEFAULT NULL::integer, p_id_usuario_auditoria integer DEFAULT NULL::integer) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_id_direccion INT;
BEGIN
    SET TIME ZONE 'America/Lima';

    IF NOT EXISTS (SELECT 1 FROM cli_clientes WHERE id = p_id) THEN
        RETURN json_build_object('error', 'No existe un cliente con id ' || p_id, 'registro', NULL);
    END IF;

    IF p_numero_documento IS NOT NULL AND EXISTS (
        SELECT 1 FROM cli_clientes WHERE numero_documento = p_numero_documento AND id <> p_id
    ) THEN
        RETURN json_build_object('error', 'Ya existe otro cliente registrado con el documento ' || p_numero_documento, 'registro', NULL);
    END IF;

    IF p_codigo_interno IS NOT NULL AND EXISTS (
        SELECT 1 FROM cli_clientes WHERE codigo_interno = p_codigo_interno AND id <> p_id
    ) THEN
        RETURN json_build_object('error', 'Ya existe otro cliente con el código interno ' || p_codigo_interno, 'registro', NULL);
    END IF;

    BEGIN
        UPDATE cli_clientes SET
            codigo_interno              = COALESCE(p_codigo_interno, codigo_interno),
            razon_social                = COALESCE(p_razon_social, razon_social),
            id_tipo_cliente             = COALESCE(p_id_tipo_cliente, id_tipo_cliente),
            id_tipo_persona             = COALESCE(p_id_tipo_persona, id_tipo_persona),
            nombres                     = COALESCE(p_nombres, nombres),
            apellido_paterno            = COALESCE(p_apellido_paterno, apellido_paterno),
            apellido_materno            = COALESCE(p_apellido_materno, apellido_materno),
            id_tipo_documento           = COALESCE(p_id_tipo_documento, id_tipo_documento),
            numero_documento            = COALESCE(p_numero_documento, numero_documento),
            telefono                    = COALESCE(p_telefono, telefono),
            email                       = COALESCE(p_email, email),
            es_agente_percepcion        = COALESCE(p_es_agente_percepcion, es_agente_percepcion),
            es_buen_contribuyente       = COALESCE(p_es_buen_contribuyente, es_buen_contribuyente),
            es_agente_retenedor         = COALESCE(p_es_agente_retenedor, es_agente_retenedor),
            afecto_rus                  = COALESCE(p_afecto_rus, afecto_rus),
            situacion_sunat             = COALESCE(p_situacion_sunat, situacion_sunat),
            estado_contribuyente_sunat  = COALESCE(p_estado_contribuyente_sunat, estado_contribuyente_sunat),
            observacion                 = COALESCE(p_observacion, observacion),
            id_usuario_modificacion     = COALESCE(p_id_usuario_auditoria, id_usuario_modificacion),
            fecha_modificacion          = NOW()
        WHERE id = p_id;
        IF p_direccion IS NOT NULL OR p_referencia IS NOT NULL OR p_id_departamento IS NOT NULL
           OR p_id_provincia IS NOT NULL OR p_id_distrito IS NOT NULL OR p_id_pais IS NOT NULL THEN

            SELECT id INTO v_id_direccion
            FROM cli_direcciones
            WHERE id_cliente = p_id AND es_principal = TRUE AND estado = 1
            ORDER BY id DESC
            LIMIT 1;

            IF v_id_direccion IS NOT NULL THEN
                UPDATE cli_direcciones SET
                    direccion               = COALESCE(p_direccion, direccion),
                    referencia              = COALESCE(p_referencia, referencia),
                    id_departamento         = COALESCE(p_id_departamento, id_departamento),
                    id_provincia            = COALESCE(p_id_provincia, id_provincia),
                    id_distrito             = COALESCE(p_id_distrito, id_distrito),
                    id_pais                 = COALESCE(p_id_pais, id_pais),
                    id_usuario_modificacion = COALESCE(p_id_usuario_auditoria, id_usuario_modificacion),
                    fecha_modificacion      = NOW()
                WHERE id = v_id_direccion;
            ELSE
                INSERT INTO cli_direcciones (
                    id_cliente, direccion, referencia,
                    id_departamento, id_provincia, id_distrito, id_pais,
                    es_principal, estado,
                    id_usuario_creacion, id_usuario_modificacion
                )
                VALUES (
                    p_id, p_direccion, p_referencia,
                    p_id_departamento, p_id_provincia, p_id_distrito, p_id_pais,
                    TRUE, 1,
                    p_id_usuario_auditoria, p_id_usuario_auditoria
                );
            END IF;
        END IF;

    EXCEPTION
        WHEN unique_violation THEN
            RETURN json_build_object('error', 'Ya existe un registro con datos duplicados (documento o código interno)', 'registro', NULL);
        WHEN foreign_key_violation THEN
            RETURN json_build_object('error', 'Uno de los datos de ubicación o clasificación no es válido', 'registro', NULL);
        WHEN OTHERS THEN
            RETURN json_build_object('error', 'No se pudo actualizar el cliente: ' || SQLERRM, 'registro', NULL);
    END;

    RETURN cli_obtener_por_id_cliente(p_id);
END;
$$;


--
-- Name: cli_aprobar_baja_cliente(integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cli_aprobar_baja_cliente(p_id_baja integer, p_id_usuario_auditoria integer DEFAULT NULL::integer) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_id_pendiente INTEGER;
    v_id_aprobada INTEGER;
    v_id_estado_actual INTEGER;
    v_id_cliente INTEGER;
    v_tipo_solicitud VARCHAR;
BEGIN
    SET TIME ZONE 'America/Lima';

    IF p_id_usuario_auditoria IS NULL THEN
        RETURN json_build_object('registro', NULL, 'error', 'Debe indicar el administrador autorizador');
    END IF;

    -- Rol Administrador + permiso bajas_cliente.aprobar (o auth.todo). Permite auto-aprobación.
    IF NOT auth_usuario_es_admin_con_permiso(p_id_usuario_auditoria, 'bajas_cliente.aprobar') THEN
        RETURN json_build_object(
            'registro',
            NULL,
            'error',
            'La solicitud debe ser autorizada por un administrador con permiso de aprobar bajas de cliente'
        );
    END IF;

    SELECT lo.id INTO v_id_pendiente
    FROM gen_lista_opciones lo
    INNER JOIN gen_lista l ON lo.id_lista = l.id
    WHERE l.nombre = 'EstadoAprobacion' AND lo.nombre = 'PENDIENTE';

    SELECT lo.id INTO v_id_aprobada
    FROM gen_lista_opciones lo
    INNER JOIN gen_lista l ON lo.id_lista = l.id
    WHERE l.nombre = 'EstadoAprobacion' AND lo.nombre = 'APROBADA';

    SELECT
        bc.id_estado_aprobacion,
        bc.id_cliente,
        ts.nombre
    INTO
        v_id_estado_actual,
        v_id_cliente,
        v_tipo_solicitud
    FROM cli_baja_cliente bc
    LEFT JOIN gen_lista_opciones ts ON ts.id = bc.id_tipo_solicitud
    WHERE bc.id = p_id_baja AND bc.estado = 1;

    IF NOT FOUND THEN
        RETURN json_build_object('registro', NULL, 'error', 'La solicitud no existe');
    END IF;

    IF v_id_estado_actual <> v_id_pendiente THEN
        RETURN json_build_object('registro', NULL, 'error', 'La solicitud ya fue procesada');
    END IF;

    UPDATE cli_baja_cliente
    SET
        id_estado_aprobacion = v_id_aprobada,
        id_usuario_autoriza = p_id_usuario_auditoria,
        fecha_autorizacion = NOW(),
        id_usuario_modificacion = p_id_usuario_auditoria,
        fecha_modificacion = NOW()
    WHERE id = p_id_baja;

    IF UPPER(COALESCE(v_tipo_solicitud, 'BAJA')) = 'REACTIVACION' THEN
        UPDATE cli_clientes
        SET
            estado = 1,
            id_usuario_modificacion = p_id_usuario_auditoria,
            fecha_modificacion = NOW()
        WHERE id = v_id_cliente;
    ELSE
        UPDATE cli_clientes
        SET
            estado = 0,
            id_usuario_modificacion = p_id_usuario_auditoria,
            fecha_modificacion = NOW()
        WHERE id = v_id_cliente;
    END IF;

    RETURN cli_obtener_baja_cliente(p_id_baja);
END;
$$;


--
-- Name: cli_crear_clientes(character varying, character varying, integer, integer, character varying, character varying, character varying, integer, character varying, character varying, character varying, boolean, boolean, boolean, boolean, character varying, character varying, character varying, character varying, character varying, numeric, numeric, integer, integer, integer, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cli_crear_clientes(p_codigo_interno character varying DEFAULT NULL::character varying, p_razon_social character varying DEFAULT NULL::character varying, p_id_tipo_cliente integer DEFAULT NULL::integer, p_id_tipo_persona integer DEFAULT NULL::integer, p_nombres character varying DEFAULT NULL::character varying, p_apellido_paterno character varying DEFAULT NULL::character varying, p_apellido_materno character varying DEFAULT NULL::character varying, p_id_tipo_documento integer DEFAULT NULL::integer, p_numero_documento character varying DEFAULT NULL::character varying, p_telefono character varying DEFAULT NULL::character varying, p_email character varying DEFAULT NULL::character varying, p_es_agente_percepcion boolean DEFAULT false, p_es_buen_contribuyente boolean DEFAULT false, p_es_agente_retenedor boolean DEFAULT false, p_afecto_rus boolean DEFAULT false, p_situacion_sunat character varying DEFAULT NULL::character varying, p_estado_contribuyente_sunat character varying DEFAULT NULL::character varying, p_observacion character varying DEFAULT NULL::character varying, p_direccion character varying DEFAULT NULL::character varying, p_referencia character varying DEFAULT NULL::character varying, p_latitud numeric DEFAULT NULL::numeric, p_longitud numeric DEFAULT NULL::numeric, p_id_departamento integer DEFAULT NULL::integer, p_id_provincia integer DEFAULT NULL::integer, p_id_distrito integer DEFAULT NULL::integer, p_id_pais integer DEFAULT NULL::integer, p_id_usuario_auditoria integer DEFAULT NULL::integer) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_id_cliente INT;
BEGIN
    SET TIME ZONE 'America/Lima';

    IF p_razon_social IS NULL AND p_nombres IS NULL THEN
        RETURN json_build_object('error', 'Debe indicar razon_social o nombres del cliente', 'registro', NULL);
    END IF;

    IF p_numero_documento IS NOT NULL AND EXISTS (
        SELECT 1 FROM cli_clientes WHERE numero_documento = p_numero_documento
    ) THEN
        RETURN json_build_object('error', 'Ya existe un cliente registrado con el documento ' || p_numero_documento, 'registro', NULL);
    END IF;

    IF p_codigo_interno IS NOT NULL AND EXISTS (
        SELECT 1 FROM cli_clientes WHERE codigo_interno = p_codigo_interno
    ) THEN
        RETURN json_build_object('error', 'Ya existe un cliente con el código interno ' || p_codigo_interno, 'registro', NULL);
    END IF;

    BEGIN
        INSERT INTO cli_clientes (
            codigo_interno, razon_social, id_tipo_cliente, id_tipo_persona,
            nombres, apellido_paterno, apellido_materno,
            id_tipo_documento, numero_documento,
            telefono, email,
            es_agente_percepcion, es_buen_contribuyente, es_agente_retenedor, afecto_rus,
            situacion_sunat, estado_contribuyente_sunat, observacion,
            estado, id_usuario_creacion, id_usuario_modificacion
        )
        VALUES (
            p_codigo_interno, p_razon_social, p_id_tipo_cliente, p_id_tipo_persona,
            p_nombres, p_apellido_paterno, p_apellido_materno,
            p_id_tipo_documento, p_numero_documento,
            p_telefono, p_email,
            p_es_agente_percepcion, p_es_buen_contribuyente, p_es_agente_retenedor, p_afecto_rus,
            p_situacion_sunat, p_estado_contribuyente_sunat, p_observacion,
            1, p_id_usuario_auditoria, p_id_usuario_auditoria
        )
        RETURNING id INTO v_id_cliente;

        IF p_direccion IS NOT NULL THEN
            INSERT INTO cli_direcciones (
                id_cliente, direccion, referencia, latitud, longitud,
                id_departamento, id_provincia, id_distrito, id_pais,
                es_principal, estado,
                id_usuario_creacion, id_usuario_modificacion
            )
            VALUES (
                v_id_cliente, p_direccion, p_referencia, p_latitud, p_longitud,
                p_id_departamento, p_id_provincia, p_id_distrito, p_id_pais,
                TRUE, 1,
                p_id_usuario_auditoria, p_id_usuario_auditoria
            );
        END IF;

    EXCEPTION
        WHEN unique_violation THEN
            RETURN json_build_object('error', 'Ya existe un registro con datos duplicados (documento o código interno)', 'registro', NULL);
        WHEN foreign_key_violation THEN
            RETURN json_build_object('error', 'Uno de los datos de ubicación o clasificación no es válido', 'registro', NULL);
        WHEN OTHERS THEN
            RETURN json_build_object('error', 'No se pudo crear el cliente: ' || SQLERRM, 'registro', NULL);
    END;

    RETURN cli_obtener_por_id_cliente(v_id_cliente);
END;
$$;


--
-- Name: cli_crear_contacto(integer, character varying, character varying, character varying, character varying, character varying, character varying, character varying, character varying, boolean, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cli_crear_contacto(p_id_cliente integer, p_nombre character varying DEFAULT NULL::character varying, p_apellido_paterno character varying DEFAULT NULL::character varying, p_apellido_materno character varying DEFAULT NULL::character varying, p_direccion character varying DEFAULT NULL::character varying, p_email character varying DEFAULT NULL::character varying, p_telefono1 character varying DEFAULT NULL::character varying, p_telefono2 character varying DEFAULT NULL::character varying, p_telefono3 character varying DEFAULT NULL::character varying, p_es_principal boolean DEFAULT false, p_id_usuario_auditoria integer DEFAULT NULL::integer) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_id INT;
BEGIN
    SET TIME ZONE 'America/Lima';

    IF p_id_cliente IS NULL THEN
        RETURN json_build_object('error', 'El id_cliente es obligatorio', 'registro', NULL);
    END IF;

    IF p_nombre IS NULL THEN
        RETURN json_build_object('error', 'El nombre del contacto es obligatorio', 'registro', NULL);
    END IF;

    IF p_es_principal = TRUE THEN
        UPDATE cli_contacto 
        SET es_principal = FALSE 
        WHERE id_cliente = p_id_cliente;
    END IF;

    INSERT INTO cli_contacto (
        id_cliente, nombre, apellido_paterno, apellido_materno, 
        direccion, email, telefono1, telefono2, telefono3, 
        es_principal, estado, id_usuario_creacion, id_usuario_modificacion
    )
    VALUES (
        p_id_cliente, p_nombre, p_apellido_paterno, p_apellido_materno, 
        p_direccion, p_email, p_telefono1, p_telefono2, p_telefono3, 
        p_es_principal, 1, p_id_usuario_auditoria, p_id_usuario_auditoria
    )
    RETURNING id INTO v_id;

    RETURN cli_obtener_por_id_contacto(v_id);
END;
$$;


--
-- Name: cli_crear_direccion(integer, character varying, character varying, integer, integer, integer, character varying, numeric, numeric, boolean, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cli_crear_direccion(p_id_cliente integer, p_direccion character varying, p_descripcion character varying DEFAULT NULL::character varying, p_id_departamento integer DEFAULT NULL::integer, p_id_provincia integer DEFAULT NULL::integer, p_id_distrito integer DEFAULT NULL::integer, p_referencia character varying DEFAULT NULL::character varying, p_latitud numeric DEFAULT NULL::numeric, p_longitud numeric DEFAULT NULL::numeric, p_es_principal boolean DEFAULT false, p_id_usuario_auditoria integer DEFAULT NULL::integer) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_id INTEGER;
BEGIN
    SET TIME ZONE 'America/Lima';

    IF p_es_principal THEN
        UPDATE cli_direcciones
        SET es_principal = FALSE,
            id_usuario_modificacion = p_id_usuario_auditoria,
            fecha_modificacion = NOW()
        WHERE id_cliente = p_id_cliente AND estado = 1;
    END IF;

    INSERT INTO cli_direcciones (
        id_cliente,
        descripcion,
        direccion,
        id_departamento,
        id_provincia,
        id_distrito,
        referencia,
        latitud,
        longitud,
        es_principal,
        id_usuario_creacion,
        id_usuario_modificacion
    )
    VALUES (
        p_id_cliente,
        p_descripcion,
        p_direccion,
        p_id_departamento,
        p_id_provincia,
        p_id_distrito,
        p_referencia,
        p_latitud,
        p_longitud,
        COALESCE(p_es_principal, FALSE),
        p_id_usuario_auditoria,
        p_id_usuario_auditoria
    )
    RETURNING id INTO v_id;

    RETURN cli_obtener_por_id_direccion(v_id);
END;
$$;


--
-- Name: cli_editar_contacto(integer, integer, character varying, character varying, character varying, character varying, character varying, character varying, character varying, character varying, boolean, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cli_editar_contacto(p_id integer, p_id_cliente integer DEFAULT NULL::integer, p_nombre character varying DEFAULT NULL::character varying, p_apellido_paterno character varying DEFAULT NULL::character varying, p_apellido_materno character varying DEFAULT NULL::character varying, p_direccion character varying DEFAULT NULL::character varying, p_email character varying DEFAULT NULL::character varying, p_telefono1 character varying DEFAULT NULL::character varying, p_telefono2 character varying DEFAULT NULL::character varying, p_telefono3 character varying DEFAULT NULL::character varying, p_es_principal boolean DEFAULT NULL::boolean, p_id_usuario integer DEFAULT NULL::integer) RETURNS json
    LANGUAGE plpgsql
    AS $$
BEGIN
    SET TIME ZONE 'America/Lima';

    -- Validar existencia
    IF NOT EXISTS (SELECT 1 FROM cli_contacto WHERE id = p_id) THEN
        RETURN json_build_object('error', 'El contacto no existe', 'registro', NULL);
    END IF;

    -- Logica de contacto principal
    IF p_es_principal = TRUE THEN
        UPDATE cli_contacto 
        SET es_principal = FALSE 
        WHERE id_cliente = COALESCE(p_id_cliente, (SELECT id_cliente FROM cli_contacto WHERE id = p_id));
    END IF;

    UPDATE cli_contacto
    SET 
        id_cliente       = COALESCE(p_id_cliente, id_cliente),
        nombre           = COALESCE(p_nombre, nombre),
        apellido_paterno = COALESCE(p_apellido_paterno, apellido_paterno),
        apellido_materno = COALESCE(p_apellido_materno, apellido_materno),
        direccion        = COALESCE(p_direccion, direccion),
        email            = COALESCE(p_email, email),
        telefono1        = COALESCE(p_telefono1, telefono1),
        telefono2        = COALESCE(p_telefono2, telefono2),
        telefono3        = COALESCE(p_telefono3, telefono3),
        es_principal     = COALESCE(p_es_principal, es_principal),
        id_usuario_modificacion = COALESCE(p_id_usuario, id_usuario_modificacion),
        fecha_modificacion = NOW()
    WHERE id = p_id;

    RETURN cli_obtener_por_id_contacto(p_id);
END;
$$;


--
-- Name: cli_eliminar_baja_cliente(integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cli_eliminar_baja_cliente(p_id integer, p_id_usuario_auditoria integer DEFAULT NULL::integer) RETURNS json
    LANGUAGE plpgsql
    AS $$
BEGIN
    SET TIME ZONE 'America/Lima';

    UPDATE cli_baja_cliente
    SET estado = 0,
        id_usuario_modificacion = p_id_usuario_auditoria,
        fecha_modificacion = NOW()
    WHERE id = p_id AND estado = 1;

    IF NOT FOUND THEN
        RETURN json_build_object('eliminado', FALSE, 'id', p_id);
    END IF;

    RETURN json_build_object('eliminado', TRUE, 'id', p_id);
END;
$$;


--
-- Name: cli_eliminar_contacto(integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cli_eliminar_contacto(p_id integer, p_id_usuario_auditoria integer DEFAULT NULL::integer) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_estado INT;
BEGIN
    SET TIME ZONE 'America/Lima';

    SELECT estado INTO v_estado FROM cli_contacto WHERE id = p_id;

    IF NOT FOUND THEN
        RETURN json_build_object('eliminado', false, 'id', p_id);
    END IF;

    IF v_estado = 0 THEN
        RETURN json_build_object('eliminado', false, 'id', p_id);
    END IF;

    UPDATE cli_contacto
    SET
        estado = 0,
        id_usuario_modificacion = COALESCE(p_id_usuario_auditoria, id_usuario_modificacion),
        fecha_modificacion = NOW()
    WHERE id = p_id;

    RETURN json_build_object('eliminado', true, 'id', p_id);
END;
$$;


--
-- Name: cli_eliminar_direccion(integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cli_eliminar_direccion(p_id integer, p_id_usuario_auditoria integer DEFAULT NULL::integer) RETURNS json
    LANGUAGE plpgsql
    AS $$
BEGIN
    SET TIME ZONE 'America/Lima';

    UPDATE cli_direcciones
    SET estado = 0,
        id_usuario_modificacion = p_id_usuario_auditoria,
        fecha_modificacion = NOW()
    WHERE id = p_id AND estado = 1;

    IF NOT FOUND THEN
        RETURN json_build_object('eliminado', FALSE, 'id', p_id);
    END IF;

    RETURN json_build_object('eliminado', TRUE, 'id', p_id);
END;
$$;


--
-- Name: cli_eliminar_logico_cliente(integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cli_eliminar_logico_cliente(p_id integer, p_id_usuario_auditoria integer DEFAULT NULL::integer) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_estado INT;
BEGIN
    SET TIME ZONE 'America/Lima';

    SELECT estado INTO v_estado FROM cli_clientes WHERE id = p_id;

    IF NOT FOUND THEN
        RETURN json_build_object(
            'eliminado', false,
            'id', p_id
        );
    END IF;

    IF v_estado = 0 THEN
        RETURN json_build_object(
            'eliminado', false,
            'id', p_id
        );
    END IF;

    UPDATE cli_clientes
    SET estado = 0,
        id_usuario_modificacion = COALESCE(p_id_usuario_auditoria, id_usuario_modificacion),
        fecha_modificacion = NOW()
    WHERE id = p_id;

    UPDATE cli_direcciones
    SET estado = 0,
        id_usuario_modificacion = COALESCE(p_id_usuario_auditoria, id_usuario_modificacion),
        fecha_modificacion = NOW()
    WHERE id_cliente = p_id AND estado = 1;

    UPDATE gen_chofer
    SET estado = 0,
        id_usuario_modificacion = COALESCE(p_id_usuario_auditoria, id_usuario_modificacion),
        fecha_modificacion = NOW()
    WHERE id_cliente = p_id AND estado = 1;

    UPDATE gen_vehiculo
    SET estado = 0,
        id_usuario_modificacion = COALESCE(p_id_usuario_auditoria, id_usuario_modificacion),
        fecha_modificacion = NOW()
    WHERE id_cliente = p_id AND estado = 1;

    UPDATE gen_cuenta_bancaria
    SET estado = 0,
        id_usuario_modificacion = COALESCE(p_id_usuario_auditoria, id_usuario_modificacion),
        fecha_modificacion = NOW()
    WHERE id_cliente = p_id AND estado = 1;

    UPDATE cli_contacto
    SET estado = 0,
        id_usuario_modificacion = COALESCE(p_id_usuario_auditoria, id_usuario_modificacion),
        fecha_modificacion = NOW()
    WHERE id_cliente = p_id AND estado = 1;

    RETURN json_build_object(
        'eliminado', true,
        'id', p_id
    );
END;
$$;


--
-- Name: cli_exportar_relacionados(integer[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cli_exportar_relacionados(p_ids_cliente integer[]) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_resultado JSON;
BEGIN
    SET TIME ZONE 'America/Lima';

    SELECT json_build_object(
        'direcciones', COALESCE((
            SELECT json_agg(row_to_json(t))
            FROM (
                SELECT
                    d.id,
                    d.id_cliente,
                    c.razon_social AS cliente_razon_social,
                    c.nombres AS cliente_nombres,
                    c.apellido_paterno AS cliente_apellido_paterno,
                    c.apellido_materno AS cliente_apellido_materno,
                    c.numero_documento AS cliente_numero_documento,
                    d.descripcion,
                    d.direccion,
                    d.id_pais,
                    pa.nombre AS nombre_pais,
                    d.id_departamento,
                    dep.nombre AS nombre_departamento,
                    d.id_provincia,
                    prov.nombre AS nombre_provincia,
                    d.id_distrito,
                    dist.nombre AS nombre_distrito,
                    d.referencia,
                    d.latitud,
                    d.longitud,
                    d.es_principal,
                    d.estado,
                    d.fecha_creacion,
                    d.fecha_modificacion
                FROM cli_direcciones d
                INNER JOIN cli_clientes c ON d.id_cliente = c.id
                LEFT JOIN gen_pais pa ON d.id_pais = pa.id
                LEFT JOIN gen_departamento dep ON d.id_departamento = dep.id
                LEFT JOIN gen_provincia prov ON d.id_provincia = prov.id
                LEFT JOIN gen_distrito dist ON d.id_distrito = dist.id
                WHERE d.id_cliente = ANY(p_ids_cliente)
                ORDER BY d.id_cliente, d.es_principal DESC, d.id DESC
            ) t
        ), '[]'::json),

        'vehiculos', COALESCE((
            SELECT json_agg(row_to_json(t))
            FROM (
                SELECT
                    v.id,
                    v.id_cliente,
                    c.razon_social AS cliente_razon_social,
                    c.nombres AS cliente_nombres,
                    c.apellido_paterno AS cliente_apellido_paterno,
                    c.apellido_materno AS cliente_apellido_materno,
                    c.numero_documento AS cliente_numero_documento,
                    v.id_tipo_vehiculo,
                    tv.nombre AS nombre_tipo_vehiculo,
                    v.placa,
                    v.placa2,
                    v.marca,
                    v.marca2,
                    v.modelo,
                    v.anio,
                    v.color,
                    v.certificado_inscripcion,
                    v.certificado2,
                    v.estado,
                    v.fecha_creacion,
                    v.fecha_modificacion
                FROM gen_vehiculo v
                LEFT JOIN cli_clientes c ON v.id_cliente = c.id
                LEFT JOIN gen_lista_opciones tv ON v.id_tipo_vehiculo = tv.id
                WHERE v.id_cliente = ANY(p_ids_cliente)
                ORDER BY v.id_cliente, v.placa ASC
            ) t
        ), '[]'::json),

        'choferes', COALESCE((
            SELECT json_agg(row_to_json(t))
            FROM (
                SELECT
                    ch.id,
                    ch.id_cliente,
                    c.razon_social AS cliente_razon_social,
                    c.nombres AS cliente_nombres,
                    c.apellido_paterno AS cliente_apellido_paterno,
                    c.apellido_materno AS cliente_apellido_materno,
                    c.numero_documento AS cliente_numero_documento,
                    ch.apellido_paterno,
                    ch.apellido_materno,
                    ch.nombres,
                    ch.id_tipo_documento,
                    td.nombre AS nombre_tipo_documento,
                    ch.numero_documento,
                    ch.telefono,
                    lic.codigo AS codigo_licencia,
                    lic.fecha_emision,
                    lic.fecha_vencimiento,
                    lic.id_tipo_licencia,
                    tl.nombre AS nombre_tipo_licencia,
                    lic.id_categoria_licencia,
                    cl.nombre AS nombre_categoria_licencia,
                    ch.estado,
                    ch.fecha_creacion,
                    ch.fecha_modificacion
                FROM gen_chofer ch
                LEFT JOIN cli_clientes c ON ch.id_cliente = c.id
                LEFT JOIN gen_lista_opciones td ON ch.id_tipo_documento = td.id
                LEFT JOIN LATERAL (
                    SELECT l.codigo, l.fecha_emision, l.fecha_vencimiento,
                           l.id_tipo_licencia, l.id_categoria_licencia
                    FROM gen_licencia l
                    WHERE l.id_chofer = ch.id
                    ORDER BY l.fecha_vencimiento DESC
                    LIMIT 1
                ) lic ON true
                LEFT JOIN gen_lista_opciones tl ON lic.id_tipo_licencia = tl.id
                LEFT JOIN gen_lista_opciones cl ON lic.id_categoria_licencia = cl.id
                WHERE ch.id_cliente = ANY(p_ids_cliente)
                ORDER BY ch.id_cliente, ch.nombres ASC
            ) t
        ), '[]'::json),

        'cuentas_bancarias', COALESCE((
            SELECT json_agg(row_to_json(t))
            FROM (
                SELECT
                    cb.id,
                    cb.id_cliente,
                    c.razon_social AS cliente_razon_social,
                    c.nombres AS cliente_nombres,
                    c.apellido_paterno AS cliente_apellido_paterno,
                    c.apellido_materno AS cliente_apellido_materno,
                    c.numero_documento AS cliente_numero_documento,
                    cb.id_banco,
                    b.nombre AS nombre_banco,
                    cb.id_tipo_cuenta,
                    tc.nombre AS nombre_tipo_cuenta,
                    cb.titular,
                    cb.numero_cuenta,
                    cb.numero_cuenta_interbancaria,
                    cb.telefono_billetera,
                    cb.es_principal,
                    cb.estado,
                    cb.fecha_creacion,
                    cb.fecha_modificacion
                FROM gen_cuenta_bancaria cb
                LEFT JOIN cli_clientes c ON cb.id_cliente = c.id
                LEFT JOIN gen_lista_opciones b ON cb.id_banco = b.id
                LEFT JOIN gen_lista_opciones tc ON cb.id_tipo_cuenta = tc.id
                WHERE cb.id_cliente = ANY(p_ids_cliente)
                ORDER BY cb.id_cliente, cb.es_principal DESC, cb.id ASC
            ) t
        ), '[]'::json)
    )
    INTO v_resultado;

    RETURN v_resultado;
END;
$$;


--
-- Name: cli_listar_bajas_cliente(integer, character varying, integer, integer, integer, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cli_listar_bajas_cliente(p_solo_activos integer DEFAULT NULL::integer, p_buscar character varying DEFAULT ''::character varying, p_limite integer DEFAULT 10, p_offset integer DEFAULT 0, p_id_cliente integer DEFAULT NULL::integer, p_id_estado_aprobacion integer DEFAULT NULL::integer, p_id_tipo_solicitud integer DEFAULT NULL::integer) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_registros JSON;
    v_total BIGINT;
BEGIN
    SET TIME ZONE 'America/Lima';

    SELECT COUNT(*) INTO v_total
    FROM cli_baja_cliente bc
    INNER JOIN cli_clientes c ON bc.id_cliente = c.id
    LEFT JOIN auth_usuarios us ON bc.id_usuario_solicita = us.id
    WHERE (p_solo_activos IS NULL OR bc.estado = p_solo_activos)
      AND (p_id_cliente IS NULL OR bc.id_cliente = p_id_cliente)
      AND (p_id_estado_aprobacion IS NULL OR bc.id_estado_aprobacion = p_id_estado_aprobacion)
      AND (p_id_tipo_solicitud IS NULL OR bc.id_tipo_solicitud = p_id_tipo_solicitud)
      AND (
          p_buscar = ''
          OR gen_texto_coincide(COALESCE(bc.motivo_detalle, ''), p_buscar)
          OR gen_texto_coincide(COALESCE(c.razon_social, ''), p_buscar)
          OR gen_texto_coincide(
              TRIM(CONCAT_WS(' ', c.nombres, c.apellido_paterno, c.apellido_materno)),
              p_buscar
          )
          OR gen_texto_coincide(COALESCE(c.numero_documento, ''), p_buscar)
          OR gen_texto_coincide(COALESCE(us.nombre, ''), p_buscar)
      );

    SELECT COALESCE(json_agg(row_to_json(t)), '[]'::JSON) INTO v_registros
    FROM (
        SELECT
            bc.id,
            bc.id_tipo_solicitud,
            ts.nombre AS nombre_tipo_solicitud,
            bc.id_cliente,
            c.razon_social AS cliente_razon_social,
            c.nombres AS cliente_nombres,
            c.apellido_paterno AS cliente_apellido_paterno,
            c.apellido_materno AS cliente_apellido_materno,
            c.numero_documento AS cliente_numero_documento,
            bc.id_motivo_baja,
            mb.nombre AS nombre_motivo_baja,
            bc.fecha_baja,
            bc.id_usuario_solicita,
            us.nombre AS nombre_usuario_solicita,
            bc.id_usuario_autoriza,
            ua.nombre AS nombre_usuario_autoriza,
            bc.fecha_autorizacion,
            bc.id_estado_aprobacion,
            ea.nombre AS nombre_estado_aprobacion,
            bc.motivo_detalle,
            bc.estado,
            bc.fecha_creacion,
            bc.fecha_modificacion,
            bc.id_usuario_creacion,
            uc.nombre AS nombre_usuario_creacion,
            bc.id_usuario_modificacion,
            um.nombre AS nombre_usuario_modificacion
        FROM cli_baja_cliente bc
        INNER JOIN cli_clientes c ON bc.id_cliente = c.id
        LEFT JOIN gen_lista_opciones ts ON bc.id_tipo_solicitud = ts.id
        LEFT JOIN gen_lista_opciones mb ON bc.id_motivo_baja = mb.id
        LEFT JOIN gen_lista_opciones ea ON bc.id_estado_aprobacion = ea.id
        LEFT JOIN auth_usuarios us ON bc.id_usuario_solicita = us.id
        LEFT JOIN auth_usuarios ua ON bc.id_usuario_autoriza = ua.id
        LEFT JOIN auth_usuarios uc ON bc.id_usuario_creacion = uc.id
        LEFT JOIN auth_usuarios um ON bc.id_usuario_modificacion = um.id
        WHERE (p_solo_activos IS NULL OR bc.estado = p_solo_activos)
          AND (p_id_cliente IS NULL OR bc.id_cliente = p_id_cliente)
          AND (p_id_estado_aprobacion IS NULL OR bc.id_estado_aprobacion = p_id_estado_aprobacion)
          AND (p_id_tipo_solicitud IS NULL OR bc.id_tipo_solicitud = p_id_tipo_solicitud)
          AND (
              p_buscar = ''
              OR gen_texto_coincide(COALESCE(bc.motivo_detalle, ''), p_buscar)
              OR gen_texto_coincide(COALESCE(c.razon_social, ''), p_buscar)
              OR gen_texto_coincide(
                  TRIM(CONCAT_WS(' ', c.nombres, c.apellido_paterno, c.apellido_materno)),
                  p_buscar
              )
              OR gen_texto_coincide(COALESCE(c.numero_documento, ''), p_buscar)
              OR gen_texto_coincide(COALESCE(us.nombre, ''), p_buscar)
          )
        -- Pendientes primero (trabajo pendiente), luego más recientes
        ORDER BY
            CASE WHEN ea.nombre = 'PENDIENTE' THEN 0 ELSE 1 END ASC,
            bc.fecha_creacion DESC,
            bc.id DESC
        LIMIT p_limite
        OFFSET p_offset
    ) t;

    RETURN json_build_object('registros', v_registros, 'total', v_total);
END;
$$;


--
-- Name: cli_listar_clientes(integer, integer, character varying, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cli_listar_clientes(p_solo_activos integer DEFAULT NULL::integer, p_id_tipo_cliente integer DEFAULT NULL::integer, p_buscar character varying DEFAULT NULL::character varying, p_limite integer DEFAULT 10, p_offset integer DEFAULT 0) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_resultado JSON;
    v_buscar    VARCHAR;
BEGIN
    SET TIME ZONE 'America/Lima';

    v_buscar := NULLIF(TRIM(p_buscar), '');

    WITH filtrados AS (
        SELECT
            c.id,
            c.codigo_interno,
            c.razon_social,
            c.id_tipo_cliente,
            tc.nombre AS nombre_tipo_cliente,
            c.id_tipo_persona,
            tp.nombre AS nombre_tipo_persona,
            c.nombres,
            c.apellido_paterno,
            c.apellido_materno,
            c.id_tipo_documento,
            td.nombre AS nombre_tipo_documento,
            c.numero_documento,
            -- Dirección principal 
            dir.id            AS id_direccion,
            dir.direccion,
            dir.referencia,
            dir.latitud,
            dir.longitud,
            dir.id_departamento,
            dep.nombre         AS nombre_departamento,
            dir.id_provincia,
            prov.nombre        AS nombre_provincia,
            dir.id_distrito,
            dist.nombre        AS nombre_distrito,
            dir.id_pais,
            pa.nombre          AS nombre_pais,
            c.telefono,
            c.email,
            c.es_agente_percepcion,
            c.es_buen_contribuyente,
            c.es_agente_retenedor,
            c.afecto_rus,
            c.situacion_sunat,
            c.estado_contribuyente_sunat,
            c.observacion,
            c.estado,
            c.id_usuario_creacion,
            uc.nombre AS nombre_usuario_creacion,
            c.id_usuario_modificacion,
            um.nombre AS nombre_usuario_modificacion,
            c.fecha_creacion,
            c.fecha_modificacion,
            -- Datos de baja (si tiene solicitud pendiente/activa)
            bc.id AS id_baja_pendiente,
            ea.nombre AS estado_baja_aprobacion,
            bc.motivo_detalle AS motivo_baja_detalle,
            mb.nombre AS motivo_baja_opciones
        FROM cli_clientes c
        LEFT JOIN gen_lista_opciones tc ON c.id_tipo_cliente = tc.id
        LEFT JOIN gen_lista_opciones tp ON c.id_tipo_persona = tp.id
        LEFT JOIN gen_lista_opciones td ON c.id_tipo_documento = td.id
        LEFT JOIN auth_usuarios uc ON c.id_usuario_creacion = uc.id
        LEFT JOIN auth_usuarios um ON c.id_usuario_modificacion = um.id

        -- FIX: se reemplaza el LEFT JOIN directo por LATERAL + LIMIT 1
        -- para evitar duplicar la fila del cliente cuando existe más
        -- de un registro de baja con estado = 1 para el mismo cliente.
        LEFT JOIN LATERAL (
            SELECT b.*
            FROM cli_baja_cliente b
            WHERE b.id_cliente = c.id
              AND b.estado = 1
            ORDER BY b.id DESC
            LIMIT 1
        ) bc ON TRUE
        LEFT JOIN gen_lista_opciones ea ON bc.id_estado_aprobacion = ea.id
                                       AND ea.nombre = 'PENDIENTE'
        LEFT JOIN gen_lista_opciones mb ON bc.id_motivo_baja = mb.id

        LEFT JOIN LATERAL (
            SELECT cd.*
            FROM cli_direcciones cd
            WHERE cd.id_cliente = c.id
              AND cd.es_principal = TRUE
              AND cd.estado = 1
            ORDER BY cd.id DESC
            LIMIT 1
        ) dir ON TRUE

        LEFT JOIN gen_departamento dep  ON dir.id_departamento = dep.id
        LEFT JOIN gen_provincia    prov ON dir.id_provincia    = prov.id
        LEFT JOIN gen_distrito     dist ON dir.id_distrito     = dist.id
        LEFT JOIN gen_pais         pa   ON dir.id_pais          = pa.id

        WHERE (p_solo_activos IS NULL OR c.estado = p_solo_activos)
          AND (p_id_tipo_cliente IS NULL OR c.id_tipo_cliente = p_id_tipo_cliente)
          AND (
                v_buscar IS NULL
                OR gen_texto_coincide(c.razon_social, v_buscar)
                OR gen_texto_coincide(c.nombres, v_buscar)
                OR gen_texto_coincide(c.apellido_paterno, v_buscar)
                OR gen_texto_coincide(c.apellido_materno, v_buscar)
                OR gen_texto_coincide(c.numero_documento, v_buscar)
                OR gen_texto_coincide(c.codigo_interno, v_buscar)
                OR gen_texto_coincide(dir.direccion, v_buscar)
              )
    ),
    total_count AS (
        SELECT COUNT(*) AS total FROM filtrados
    ),
    paginados AS (
        SELECT * FROM filtrados
        ORDER BY fecha_creacion DESC NULLS LAST, id DESC
        LIMIT p_limite
        OFFSET p_offset
    )
    SELECT json_build_object(
        'total', COALESCE((SELECT total FROM total_count), 0),
        'registros', COALESCE((SELECT json_agg(row_to_json(p)) FROM paginados p), '[]'::json)
    ) INTO v_resultado;

    RETURN v_resultado;
END;
$$;


--
-- Name: cli_listar_clientes_mapa(integer, character varying, character varying, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cli_listar_clientes_mapa(p_solo_activos integer DEFAULT 1, p_buscar character varying DEFAULT NULL::character varying, p_filtro_balones character varying DEFAULT NULL::character varying, p_limite integer DEFAULT 500, p_offset integer DEFAULT 0) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_resultado JSON;
    v_buscar    VARCHAR;
    v_filtro    VARCHAR;
BEGIN
    SET TIME ZONE 'America/Lima';

    v_buscar := NULLIF(TRIM(p_buscar), '');
    v_filtro := NULLIF(UPPER(TRIM(p_filtro_balones)), '');

    WITH balones_campo AS (
        SELECT
            x.id_cliente,
            x.id_balon,
            x.codigo_balon,
            x.numero_serie,
            x.nombre_estado_balon,
            x.nombre_tipo_balon,
            x.tipo_relacion,
            x.fecha_inicio,
            x.fecha_limite,
            x.dias_en_cliente,
            x.vencido,
            x.alerta_antiguedad
        FROM (
            SELECT
                COALESCE(b.id_cliente_ubicacion, b.id_cliente_propietario) AS id_cliente,
                b.id AS id_balon,
                b.codigo_balon,
                b.numero_serie,
                eb.nombre AS nombre_estado_balon,
                tb.nombre AS nombre_tipo_balon,
                CASE eb.nombre
                    WHEN 'PRESTADO_CLIENTE' THEN 'PRESTAMO'
                    WHEN 'POR_RECOGER' THEN 'PRESTAMO'
                    WHEN 'ALQUILADO' THEN 'ALQUILER'
                    WHEN 'EN_PODER_CLIENTE' THEN 'PROPIO'
                    ELSE eb.nombre
                END AS tipo_relacion,
                CASE
                    WHEN eb.nombre IN ('PRESTADO_CLIENTE', 'POR_RECOGER')
                        THEN COALESCE(prest.fecha_inicio, b.fecha_modificacion::date)
                    WHEN eb.nombre = 'ALQUILADO'
                        THEN COALESCE(alq.fecha_inicio, b.fecha_modificacion::date)
                    ELSE NULL
                END AS fecha_inicio,
                CASE
                    WHEN eb.nombre IN ('PRESTADO_CLIENTE', 'POR_RECOGER') THEN prest.fecha_limite
                    WHEN eb.nombre = 'ALQUILADO' THEN alq.fecha_limite
                    ELSE NULL
                END AS fecha_limite,
                CASE
                    WHEN eb.nombre IN ('PRESTADO_CLIENTE', 'POR_RECOGER', 'ALQUILADO')
                         AND COALESCE(
                             CASE
                                 WHEN eb.nombre IN ('PRESTADO_CLIENTE', 'POR_RECOGER') THEN prest.fecha_inicio
                                 WHEN eb.nombre = 'ALQUILADO' THEN alq.fecha_inicio
                             END,
                             b.fecha_modificacion::date
                         ) IS NOT NULL
                    THEN (
                        CURRENT_DATE - COALESCE(
                            CASE
                                WHEN eb.nombre IN ('PRESTADO_CLIENTE', 'POR_RECOGER') THEN prest.fecha_inicio
                                WHEN eb.nombre = 'ALQUILADO' THEN alq.fecha_inicio
                            END,
                            b.fecha_modificacion::date
                        )
                    )::INTEGER
                    ELSE NULL
                END AS dias_en_cliente,
                CASE
                    WHEN eb.nombre = 'ALQUILADO'
                         AND alq.fecha_limite IS NOT NULL
                         AND CURRENT_DATE > alq.fecha_limite
                    THEN TRUE
                    WHEN eb.nombre IN ('PRESTADO_CLIENTE', 'POR_RECOGER')
                         AND prest.fecha_limite IS NOT NULL
                         AND CURRENT_DATE > prest.fecha_limite
                    THEN TRUE
                    ELSE FALSE
                END AS vencido,
                CASE
                    WHEN eb.nombre NOT IN ('PRESTADO_CLIENTE', 'POR_RECOGER', 'ALQUILADO') THEN NULL
                    WHEN (
                        CURRENT_DATE - COALESCE(
                            CASE
                                WHEN eb.nombre IN ('PRESTADO_CLIENTE', 'POR_RECOGER') THEN prest.fecha_inicio
                                WHEN eb.nombre = 'ALQUILADO' THEN alq.fecha_inicio
                            END,
                            b.fecha_modificacion::date
                        )
                    ) >= 180 THEN 'CRITICO'
                    WHEN (
                        CURRENT_DATE - COALESCE(
                            CASE
                                WHEN eb.nombre IN ('PRESTADO_CLIENTE', 'POR_RECOGER') THEN prest.fecha_inicio
                                WHEN eb.nombre = 'ALQUILADO' THEN alq.fecha_inicio
                            END,
                            b.fecha_modificacion::date
                        )
                    ) >= 90 THEN 'SEGUIMIENTO'
                    WHEN (
                        CURRENT_DATE - COALESCE(
                            CASE
                                WHEN eb.nombre IN ('PRESTADO_CLIENTE', 'POR_RECOGER') THEN prest.fecha_inicio
                                WHEN eb.nombre = 'ALQUILADO' THEN alq.fecha_inicio
                            END,
                            b.fecha_modificacion::date
                        )
                    ) >= 30 THEN 'ATENCION'
                    ELSE 'RECIENTE'
                END AS alerta_antiguedad
            FROM bal_balon b
            INNER JOIN gen_lista_opciones eb ON b.id_estado_balon = eb.id
            LEFT JOIN bal_tipo_balon tb ON b.id_tipo_balon = tb.id
            LEFT JOIN LATERAL (
                SELECT
                    COALESCE(pd.fecha_prestamo, pd.fecha_entregado, pr.fecha_salida) AS fecha_inicio,
                    pd.fecha_vencimiento AS fecha_limite
                FROM bal_prestamo_detalle pd
                INNER JOIN bal_prestamo pr ON pr.id = pd.id_prestamo AND pr.estado = 1
                WHERE pd.id_balon = b.id
                  AND pd.estado = 1
                  AND pd.fecha_devolucion IS NULL
                  AND pr.id_cliente = COALESCE(b.id_cliente_ubicacion, b.id_cliente_propietario)
                ORDER BY pd.id DESC
                LIMIT 1
            ) prest ON TRUE
            LEFT JOIN LATERAL (
                SELECT
                    al.fecha_inicio,
                    al.fecha_fin_pactada AS fecha_limite
                FROM bal_alquiler_detalle ad
                INNER JOIN bal_alquiler al ON al.id = ad.id_alquiler AND al.estado = 1
                WHERE ad.id_balon = b.id
                  AND ad.estado = 1
                  AND ad.fecha_devolucion IS NULL
                  AND al.id_cliente = COALESCE(b.id_cliente_ubicacion, b.id_cliente_propietario)
                ORDER BY ad.id DESC
                LIMIT 1
            ) alq ON TRUE
            WHERE b.estado = 1
              AND eb.nombre IN (
                  'PRESTADO_CLIENTE',
                  'POR_RECOGER',
                  'ALQUILADO',
                  'EN_PODER_CLIENTE'
              )
              AND COALESCE(b.id_cliente_ubicacion, b.id_cliente_propietario) IS NOT NULL
        ) x
    ),
    balones_agg AS (
        SELECT
            bc.id_cliente,
            json_agg(
                json_build_object(
                    'id_balon', bc.id_balon,
                    'codigo_balon', bc.codigo_balon,
                    'numero_serie', bc.numero_serie,
                    'nombre_estado_balon', bc.nombre_estado_balon,
                    'nombre_tipo_balon', bc.nombre_tipo_balon,
                    'tipo_relacion', bc.tipo_relacion,
                    'fecha_inicio', bc.fecha_inicio,
                    'fecha_limite', bc.fecha_limite,
                    'dias_en_cliente', bc.dias_en_cliente,
                    'vencido', bc.vencido,
                    'alerta_antiguedad', bc.alerta_antiguedad
                )
                ORDER BY
                    CASE WHEN bc.vencido THEN 0 ELSE 1 END,
                    bc.dias_en_cliente DESC NULLS LAST,
                    bc.codigo_balon
            ) AS balones,
            COUNT(*)::INT AS total_balones,
            BOOL_OR(bc.tipo_relacion = 'PRESTAMO') AS tiene_prestamo,
            BOOL_OR(bc.tipo_relacion = 'ALQUILER') AS tiene_alquiler,
            BOOL_OR(bc.tipo_relacion = 'PROPIO') AS tiene_propio,
            BOOL_OR(COALESCE(bc.vencido, FALSE)) AS tiene_vencidos,
            MAX(bc.dias_en_cliente) AS max_dias_en_cliente
        FROM (
            SELECT DISTINCT ON (id_cliente, id_balon)
                id_cliente,
                id_balon,
                codigo_balon,
                numero_serie,
                nombre_estado_balon,
                nombre_tipo_balon,
                tipo_relacion,
                fecha_inicio,
                fecha_limite,
                dias_en_cliente,
                vencido,
                alerta_antiguedad
            FROM balones_campo
            ORDER BY id_cliente, id_balon, tipo_relacion
        ) bc
        GROUP BY bc.id_cliente
    ),
    filtrados AS (
        SELECT
            c.id,
            c.codigo_interno,
            c.razon_social,
            c.nombres,
            c.apellido_paterno,
            c.apellido_materno,
            c.numero_documento,
            tp.nombre AS nombre_tipo_persona,
            c.telefono,
            dir.direccion,
            dir.referencia,
            dir.latitud,
            dir.longitud,
            c.estado,
            COALESCE(ba.balones, '[]'::json) AS balones,
            COALESCE(ba.total_balones, 0) AS total_balones,
            COALESCE(ba.tiene_prestamo, FALSE) AS tiene_prestamo,
            COALESCE(ba.tiene_alquiler, FALSE) AS tiene_alquiler,
            COALESCE(ba.tiene_propio, FALSE) AS tiene_propio,
            COALESCE(ba.tiene_vencidos, FALSE) AS tiene_vencidos,
            ba.max_dias_en_cliente
        FROM cli_clientes c
        LEFT JOIN gen_lista_opciones tp ON c.id_tipo_persona = tp.id
        INNER JOIN LATERAL (
            SELECT cd.*
            FROM cli_direcciones cd
            WHERE cd.id_cliente = c.id
              AND cd.es_principal = TRUE
              AND cd.estado = 1
              AND cd.latitud IS NOT NULL
              AND cd.longitud IS NOT NULL
            ORDER BY cd.id DESC
            LIMIT 1
        ) dir ON TRUE
        LEFT JOIN balones_agg ba ON ba.id_cliente = c.id
        WHERE (p_solo_activos IS NULL OR c.estado = p_solo_activos)
          AND (
                v_buscar IS NULL
                OR gen_texto_coincide(c.razon_social, v_buscar)
                OR gen_texto_coincide(c.nombres, v_buscar)
                OR gen_texto_coincide(c.apellido_paterno, v_buscar)
                OR gen_texto_coincide(c.apellido_materno, v_buscar)
                OR gen_texto_coincide(c.numero_documento, v_buscar)
                OR gen_texto_coincide(c.codigo_interno, v_buscar)
                OR gen_texto_coincide(dir.direccion, v_buscar)
              )
          AND (
                v_filtro IS NULL
                OR (v_filtro = 'CON_BALONES' AND COALESCE(ba.total_balones, 0) > 0)
                OR (v_filtro = 'PRESTADO_CLIENTE' AND COALESCE(ba.tiene_prestamo, FALSE))
                OR (v_filtro = 'ALQUILADO' AND COALESCE(ba.tiene_alquiler, FALSE))
                OR (v_filtro = 'EN_PODER_CLIENTE' AND COALESCE(ba.tiene_propio, FALSE))
              )
    ),
    total_count AS (
        SELECT COUNT(*) AS total FROM filtrados
    ),
    paginados AS (
        SELECT * FROM filtrados
        ORDER BY
            CASE WHEN tiene_vencidos THEN 0 ELSE 1 END,
            total_balones DESC,
            razon_social NULLS LAST,
            nombres NULLS LAST,
            id DESC
        LIMIT GREATEST(COALESCE(p_limite, 500), 1)
        OFFSET GREATEST(COALESCE(p_offset, 0), 0)
    )
    SELECT json_build_object(
        'total', COALESCE((SELECT total FROM total_count), 0),
        'registros', COALESCE((SELECT json_agg(row_to_json(p)) FROM paginados p), '[]'::json)
    ) INTO v_resultado;

    RETURN v_resultado;
END;
$$;


--
-- Name: cli_listar_contactos(integer, integer, character varying, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cli_listar_contactos(p_solo_activos integer DEFAULT NULL::integer, p_id_cliente integer DEFAULT NULL::integer, p_buscar character varying DEFAULT NULL::character varying, p_limite integer DEFAULT 10, p_offset integer DEFAULT 0) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_resultado JSON;
    v_buscar    VARCHAR;
BEGIN
    SET TIME ZONE 'America/Lima';

    v_buscar := NULLIF(TRIM(p_buscar), '');

    WITH filtrados AS (
        SELECT 
            co.id,
            co.id_cliente,
            c.razon_social AS cliente_razon_social,
            c.nombres AS cliente_nombres,
            c.apellido_paterno AS cliente_apellido_paterno,
            c.apellido_materno AS cliente_apellido_materno,
            c.numero_documento AS cliente_numero_documento,
            co.nombre,
            co.apellido_paterno,
            co.apellido_materno,
            co.direccion,
            co.email,
            co.telefono1,
            co.telefono2,
            co.telefono3,
            co.es_principal,
            co.estado,
            co.id_usuario_creacion,
            uc.nombre AS nombre_usuario_creacion,
            co.id_usuario_modificacion,
            um.nombre AS nombre_usuario_modificacion,
            co.fecha_creacion,
            co.fecha_modificacion
        FROM cli_contacto co
        LEFT JOIN cli_clientes c ON co.id_cliente = c.id
        LEFT JOIN auth_usuarios uc ON co.id_usuario_creacion = uc.id
        LEFT JOIN auth_usuarios um ON co.id_usuario_modificacion = um.id
        WHERE (p_solo_activos IS NULL OR co.estado = p_solo_activos)
          AND (p_id_cliente IS NULL OR co.id_cliente = p_id_cliente)
          AND (
                v_buscar IS NULL 
                OR gen_texto_coincide(co.nombre, v_buscar)
                OR gen_texto_coincide(co.apellido_paterno, v_buscar)
                OR gen_texto_coincide(co.apellido_materno, v_buscar)
                OR gen_texto_coincide(co.email, v_buscar)
                OR gen_texto_coincide(co.telefono1, v_buscar)
                OR gen_texto_coincide(c.razon_social, v_buscar)
                OR gen_texto_coincide(c.numero_documento, v_buscar)
              )
    ),
    total_count AS (
        SELECT COUNT(*) AS total FROM filtrados
    ),
    paginados AS (
        SELECT * FROM filtrados
        ORDER BY es_principal DESC, nombre ASC, id DESC
        LIMIT p_limite 
        OFFSET p_offset
    )
    SELECT json_build_object(
        'total', COALESCE((SELECT total FROM total_count), 0),
        'registros', COALESCE((SELECT json_agg(row_to_json(p)) FROM paginados p), '[]'::json)
    ) INTO v_resultado;

    RETURN v_resultado;
END;
$$;


--
-- Name: cli_listar_direcciones(integer, integer, character varying, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cli_listar_direcciones(p_solo_activos integer DEFAULT NULL::integer, p_id_cliente integer DEFAULT NULL::integer, p_buscar character varying DEFAULT NULL::character varying, p_limite integer DEFAULT 10, p_offset integer DEFAULT 0) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_resultado JSON;
    v_buscar VARCHAR;
BEGIN
    SET TIME ZONE 'America/Lima';

    v_buscar := NULLIF(TRIM(p_buscar), '');

    WITH filtrados AS (
        SELECT
            d.id,
            d.id_cliente,
            c.razon_social AS cliente_razon_social,
            c.nombres AS cliente_nombres,
            c.apellido_paterno AS cliente_apellido_paterno,
            c.apellido_materno AS cliente_apellido_materno,
            c.numero_documento AS cliente_numero_documento,
            d.descripcion,
            d.direccion,
            d.id_pais,
            pa.nombre AS nombre_pais,
            d.id_departamento,
            dep.nombre AS nombre_departamento,
            d.id_provincia,
            prov.nombre AS nombre_provincia,
            d.id_distrito,
            dist.nombre AS nombre_distrito,
            d.referencia,
            d.latitud,
            d.longitud,
            d.es_principal,
            d.estado,
            d.fecha_creacion,
            d.fecha_modificacion,
            d.id_usuario_creacion,
            uc.nombre AS nombre_usuario_creacion,
            d.id_usuario_modificacion,
            um.nombre AS nombre_usuario_modificacion
        FROM cli_direcciones d
        INNER JOIN cli_clientes c
            ON d.id_cliente = c.id
        LEFT JOIN gen_pais pa
            ON d.id_pais = pa.id
        LEFT JOIN gen_departamento dep
            ON d.id_departamento = dep.id
        LEFT JOIN gen_provincia prov
            ON d.id_provincia = prov.id
        LEFT JOIN gen_distrito dist
            ON d.id_distrito = dist.id
        LEFT JOIN auth_usuarios uc
            ON d.id_usuario_creacion = uc.id
        LEFT JOIN auth_usuarios um
            ON d.id_usuario_modificacion = um.id
        WHERE
            (p_solo_activos IS NULL OR d.estado = p_solo_activos)
            AND (p_id_cliente IS NULL OR d.id_cliente = p_id_cliente)
            AND (
                v_buscar IS NULL
                OR d.direccion ILIKE '%' || v_buscar || '%'
                OR COALESCE(d.descripcion, '') ILIKE '%' || v_buscar || '%'
                OR COALESCE(d.referencia, '') ILIKE '%' || v_buscar || '%'
                OR c.razon_social ILIKE '%' || v_buscar || '%'
                OR c.nombres ILIKE '%' || v_buscar || '%'
                OR c.apellido_paterno ILIKE '%' || v_buscar || '%'
                OR c.apellido_materno ILIKE '%' || v_buscar || '%'
                OR c.numero_documento ILIKE '%' || v_buscar || '%'
            )
    ),
    total_count AS (
        SELECT COUNT(*) AS total
        FROM filtrados
    ),
    paginados AS (
        SELECT *
        FROM filtrados
        ORDER BY es_principal DESC, id DESC
        LIMIT p_limite
        OFFSET p_offset
    )
    SELECT json_build_object(
        'total', COALESCE((SELECT total FROM total_count), 0),
        'registros', COALESCE((SELECT json_agg(row_to_json(p)) FROM paginados p), '[]'::json)
    )
    INTO v_resultado;

    RETURN v_resultado;
END;
$$;


--
-- Name: cli_obtener_baja_cliente(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cli_obtener_baja_cliente(p_id integer) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_registro JSON;
BEGIN
    SET TIME ZONE 'America/Lima';

    SELECT row_to_json(t) INTO v_registro
    FROM (
        SELECT
            bc.id,
            bc.id_tipo_solicitud,
            ts.nombre AS nombre_tipo_solicitud,
            bc.id_cliente,
            c.razon_social AS cliente_razon_social,
            c.nombres AS cliente_nombres,
            c.apellido_paterno AS cliente_apellido_paterno,
            c.apellido_materno AS cliente_apellido_materno,
            c.numero_documento AS cliente_numero_documento,
            bc.id_motivo_baja,
            mb.nombre AS nombre_motivo_baja,
            bc.fecha_baja,
            bc.id_usuario_solicita,
            us.nombre AS nombre_usuario_solicita,
            bc.id_usuario_autoriza,
            ua.nombre AS nombre_usuario_autoriza,
            bc.fecha_autorizacion,
            bc.id_estado_aprobacion,
            ea.nombre AS nombre_estado_aprobacion,
            bc.motivo_detalle,
            bc.estado,
            bc.fecha_creacion,
            bc.fecha_modificacion,
            bc.id_usuario_creacion,
            uc.nombre AS nombre_usuario_creacion,
            bc.id_usuario_modificacion,
            um.nombre AS nombre_usuario_modificacion
        FROM cli_baja_cliente bc
        INNER JOIN cli_clientes c ON bc.id_cliente = c.id
        LEFT JOIN gen_lista_opciones ts ON bc.id_tipo_solicitud = ts.id
        LEFT JOIN gen_lista_opciones mb ON bc.id_motivo_baja = mb.id
        LEFT JOIN gen_lista_opciones ea ON bc.id_estado_aprobacion = ea.id
        LEFT JOIN auth_usuarios us ON bc.id_usuario_solicita = us.id
        LEFT JOIN auth_usuarios ua ON bc.id_usuario_autoriza = ua.id
        LEFT JOIN auth_usuarios uc ON bc.id_usuario_creacion = uc.id
        LEFT JOIN auth_usuarios um ON bc.id_usuario_modificacion = um.id
        WHERE bc.id = p_id AND bc.estado = 1
    ) t;

    RETURN json_build_object('registro', v_registro);
END;
$$;


--
-- Name: cli_obtener_por_id_cliente(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cli_obtener_por_id_cliente(p_id integer) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_registro JSON;
BEGIN
    SET TIME ZONE 'America/Lima';

    SELECT row_to_json(t) INTO v_registro
    FROM (
        SELECT
            c.id,
            c.codigo_interno,
            c.razon_social,
            c.id_tipo_cliente,
            tc.nombre AS nombre_tipo_cliente,
            c.id_tipo_persona,
            tp.nombre AS nombre_tipo_persona,
            c.nombres,
            c.apellido_paterno,
            c.apellido_materno,
            c.id_tipo_documento,
            td.nombre AS nombre_tipo_documento,
            c.numero_documento,
            -- Dirección principal 
            dir.id            AS id_direccion,
            dir.direccion,
            dir.referencia,
            dir.latitud,
            dir.longitud,
            dir.id_departamento,
            dep.nombre         AS nombre_departamento,
            dir.id_provincia,
            prov.nombre        AS nombre_provincia,
            dir.id_distrito,
            dist.nombre        AS nombre_distrito,
            dir.id_pais,
            pa.nombre          AS nombre_pais,

            c.telefono,
            c.email,
            c.es_agente_percepcion,
            c.es_buen_contribuyente,
            c.es_agente_retenedor,
            c.afecto_rus,
            c.situacion_sunat,
            c.estado_contribuyente_sunat,
            c.observacion,
            c.estado,
            c.id_usuario_creacion,
            uc.nombre AS nombre_usuario_creacion,
            c.id_usuario_modificacion,
            um.nombre AS nombre_usuario_modificacion,
            c.fecha_creacion,
            c.fecha_modificacion,
            -- Datos de baja (si tiene solicitud pendiente)
            bc.id AS id_baja_pendiente,
            ea.nombre AS estado_baja_aprobacion,
            bc.motivo_detalle AS motivo_baja_detalle,
            mb.nombre AS motivo_baja_opciones
        FROM cli_clientes c
        LEFT JOIN gen_lista_opciones tc ON c.id_tipo_cliente = tc.id
        LEFT JOIN gen_lista_opciones tp ON c.id_tipo_persona = tp.id
        LEFT JOIN gen_lista_opciones td ON c.id_tipo_documento = td.id
        LEFT JOIN auth_usuarios uc ON c.id_usuario_creacion = uc.id
        LEFT JOIN auth_usuarios um ON c.id_usuario_modificacion = um.id

        LEFT JOIN cli_baja_cliente bc ON bc.id_cliente = c.id
                                     AND bc.estado = 1
        LEFT JOIN gen_lista_opciones ea ON bc.id_estado_aprobacion = ea.id
                                       AND ea.nombre = 'PENDIENTE'
        LEFT JOIN gen_lista_opciones mb ON bc.id_motivo_baja = mb.id

        -- Dirección principal del cliente
        LEFT JOIN LATERAL (
            SELECT cd.*
            FROM cli_direcciones cd
            WHERE cd.id_cliente = c.id
              AND cd.es_principal = TRUE
              AND cd.estado = 1
            ORDER BY cd.id DESC
            LIMIT 1
        ) dir ON TRUE

        LEFT JOIN gen_departamento dep ON dir.id_departamento = dep.id
        LEFT JOIN gen_provincia    prov ON dir.id_provincia   = prov.id
        LEFT JOIN gen_distrito     dist ON dir.id_distrito    = dist.id
        LEFT JOIN gen_pais         pa   ON dir.id_pais         = pa.id

        WHERE c.id = p_id
    ) t;

    IF v_registro IS NULL THEN
        RETURN json_build_object(
            'registro', NULL,
            'error', 'Cliente no encontrado'
        );
    END IF;
    RETURN json_build_object('registro', v_registro);
END;
$$;


--
-- Name: cli_obtener_por_id_contacto(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cli_obtener_por_id_contacto(p_id integer) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_resultado JSON;
BEGIN
    SELECT json_build_object(
        'error', NULL,
        'registro', row_to_json(c)
    ) INTO v_resultado
    FROM (
        SELECT 
            co.id,
            co.id_cliente,
            c.razon_social AS cliente_razon_social,
            c.nombres AS cliente_nombres,
            c.apellido_paterno AS cliente_apellido_paterno,
            c.apellido_materno AS cliente_apellido_materno,
            c.numero_documento AS cliente_numero_documento,
            co.nombre,
            co.apellido_paterno,
            co.apellido_materno,
            co.direccion,
            co.email,
            co.telefono1,
            co.telefono2,
            co.telefono3,
            co.es_principal,
            co.estado,
            co.id_usuario_creacion,
            uc.nombre AS nombre_usuario_creacion,
            co.id_usuario_modificacion,
            um.nombre AS nombre_usuario_modificacion,
            co.fecha_creacion,
            co.fecha_modificacion
        FROM cli_contacto co
        LEFT JOIN cli_clientes c ON co.id_cliente = c.id
        LEFT JOIN auth_usuarios uc ON co.id_usuario_creacion = uc.id
        LEFT JOIN auth_usuarios um ON co.id_usuario_modificacion = um.id
        WHERE co.id = p_id
    ) c;

    IF v_resultado IS NULL THEN
        RETURN json_build_object('error', 'Contacto no encontrado', 'registro', NULL);
    END IF;

    RETURN v_resultado;
END;
$$;


--
-- Name: cli_obtener_por_id_direccion(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cli_obtener_por_id_direccion(p_id integer) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_registro JSON;
BEGIN
    SET TIME ZONE 'America/Lima';

    SELECT row_to_json(t) INTO v_registro
    FROM (
        SELECT
            d.id,
            d.id_cliente,
            c.razon_social AS cliente_razon_social,
            c.nombres AS cliente_nombres,
            c.apellido_paterno AS cliente_apellido_paterno,
            c.apellido_materno AS cliente_apellido_materno,
            c.numero_documento AS cliente_numero_documento,
            d.descripcion,
            d.direccion,
            d.id_pais,
            pa.nombre AS nombre_pais,
            d.id_departamento,
            dep.nombre AS nombre_departamento,
            d.id_provincia,
            prov.nombre AS nombre_provincia,
            d.id_distrito,
            dist.nombre AS nombre_distrito,
            d.referencia,
            d.latitud,
            d.longitud,
            d.es_principal,
            d.estado,
            d.fecha_creacion,
            d.fecha_modificacion,
            d.id_usuario_creacion,
            uc.nombre AS nombre_usuario_creacion,
            d.id_usuario_modificacion,
            um.nombre AS nombre_usuario_modificacion
        FROM cli_direcciones d
        INNER JOIN cli_clientes c ON d.id_cliente = c.id
        LEFT JOIN gen_pais pa ON d.id_pais = pa.id
        LEFT JOIN gen_departamento dep ON d.id_departamento = dep.id
        LEFT JOIN gen_provincia prov ON d.id_provincia = prov.id
        LEFT JOIN gen_distrito dist ON d.id_distrito = dist.id
        LEFT JOIN auth_usuarios uc ON d.id_usuario_creacion = uc.id
        LEFT JOIN auth_usuarios um ON d.id_usuario_modificacion = um.id
        WHERE d.id = p_id AND d.estado = 1
    ) t;

    RETURN json_build_object('registro', v_registro);
END;
$$;


--
-- Name: cli_rechazar_baja_cliente(integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cli_rechazar_baja_cliente(p_id_baja integer, p_id_usuario_auditoria integer DEFAULT NULL::integer) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_id_rechazada INTEGER;
    v_id_pendiente INTEGER;
    v_id_estado_actual INTEGER;
BEGIN
    SET TIME ZONE 'America/Lima';

    IF p_id_usuario_auditoria IS NULL THEN
        RETURN json_build_object('registro', NULL, 'error', 'Debe indicar el administrador que rechaza');
    END IF;

    IF NOT auth_usuario_es_admin_con_permiso(p_id_usuario_auditoria, 'bajas_cliente.rechazar')
       AND NOT auth_usuario_es_admin_con_permiso(p_id_usuario_auditoria, 'bajas_cliente.aprobar')
    THEN
        RETURN json_build_object(
            'registro',
            NULL,
            'error',
            'Solo un administrador con permiso de rechazar/aprobar bajas de cliente puede rechazar la solicitud'
        );
    END IF;

    SELECT lo.id INTO v_id_rechazada
    FROM gen_lista_opciones lo
    INNER JOIN gen_lista l ON lo.id_lista = l.id
    WHERE l.nombre = 'EstadoAprobacion' AND lo.nombre = 'RECHAZADA';

    SELECT lo.id INTO v_id_pendiente
    FROM gen_lista_opciones lo
    INNER JOIN gen_lista l ON lo.id_lista = l.id
    WHERE l.nombre = 'EstadoAprobacion' AND lo.nombre = 'PENDIENTE';

    SELECT bc.id_estado_aprobacion INTO v_id_estado_actual
    FROM cli_baja_cliente bc
    WHERE bc.id = p_id_baja AND bc.estado = 1;

    IF NOT FOUND THEN
        RETURN json_build_object('registro', NULL, 'error', 'La solicitud de baja no existe');
    END IF;

    IF v_id_estado_actual <> v_id_pendiente THEN
        RETURN json_build_object('registro', NULL, 'error', 'La solicitud ya fue procesada');
    END IF;

    UPDATE cli_baja_cliente
    SET
        id_estado_aprobacion = v_id_rechazada,
        id_usuario_autoriza = p_id_usuario_auditoria,
        fecha_autorizacion = NOW(),
        id_usuario_modificacion = p_id_usuario_auditoria,
        fecha_modificacion = NOW()
    WHERE id = p_id_baja;

    RETURN cli_obtener_baja_cliente(p_id_baja);
END;
$$;


--
-- Name: cli_restaurar_cliente(integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cli_restaurar_cliente(p_id integer, p_id_usuario_auditoria integer DEFAULT NULL::integer) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_estado INT;
BEGIN
    SET TIME ZONE 'America/Lima';

    SELECT estado INTO v_estado FROM cli_clientes WHERE id = p_id;

    IF NOT FOUND THEN
        RETURN json_build_object('eliminado', false, 'id', p_id);
    END IF;

    IF v_estado = 1 THEN
        RETURN json_build_object('eliminado', false, 'id', p_id);
    END IF;

    UPDATE cli_clientes
    SET estado = 1,
        id_usuario_modificacion = COALESCE(p_id_usuario_auditoria, id_usuario_modificacion),
        fecha_modificacion = NOW()
    WHERE id = p_id;

    UPDATE cli_direcciones
    SET estado = 1,
        id_usuario_modificacion = COALESCE(p_id_usuario_auditoria, id_usuario_modificacion),
        fecha_modificacion = NOW()
    WHERE id_cliente = p_id AND estado = 0;

    UPDATE gen_chofer
    SET estado = 1,
        id_usuario_modificacion = COALESCE(p_id_usuario_auditoria, id_usuario_modificacion),
        fecha_modificacion = NOW()
    WHERE id_cliente = p_id AND estado = 0;

    UPDATE gen_vehiculo
    SET estado = 1,
        id_usuario_modificacion = COALESCE(p_id_usuario_auditoria, id_usuario_modificacion),
        fecha_modificacion = NOW()
    WHERE id_cliente = p_id AND estado = 0;

    UPDATE gen_cuenta_bancaria
    SET estado = 1,
        id_usuario_modificacion = COALESCE(p_id_usuario_auditoria, id_usuario_modificacion),
        fecha_modificacion = NOW()
    WHERE id_cliente = p_id AND estado = 0;

    UPDATE cli_contacto
    SET estado = 1,
        id_usuario_modificacion = COALESCE(p_id_usuario_auditoria, id_usuario_modificacion),
        fecha_modificacion = NOW()  
    WHERE id_cliente = p_id AND estado = 0;

    RETURN json_build_object('eliminado', true, 'id', p_id);
END;
$$;


--
-- Name: cli_solicitar_baja_cliente(integer, integer, character varying, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cli_solicitar_baja_cliente(p_id_cliente integer, p_id_motivo_baja integer DEFAULT NULL::integer, p_motivo_detalle character varying DEFAULT NULL::character varying, p_id_usuario_auditoria integer DEFAULT NULL::integer, p_id_tipo_solicitud integer DEFAULT NULL::integer) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_id_baja INTEGER;
    v_estado_cliente INT;
    v_id_pendiente INTEGER;
    v_id_tipo INTEGER;
BEGIN
    SET TIME ZONE 'America/Lima';

    SELECT estado INTO v_estado_cliente FROM cli_clientes WHERE id = p_id_cliente;

    IF NOT FOUND THEN
        RETURN json_build_object('registro', NULL, 'error', 'El cliente no existe');
    END IF;

    IF v_estado_cliente = 0 THEN
        RETURN json_build_object('registro', NULL, 'error', 'El cliente ya está inactivo');
    END IF;

    SELECT lo.id INTO v_id_pendiente
    FROM gen_lista_opciones lo
    INNER JOIN gen_lista l ON lo.id_lista = l.id
    WHERE l.nombre = 'EstadoAprobacion' AND lo.nombre = 'PENDIENTE';

    v_id_tipo := COALESCE(p_id_tipo_solicitud, (SELECT lo.id
        FROM gen_lista_opciones lo
        INNER JOIN gen_lista l ON lo.id_lista = l.id
        WHERE l.nombre = 'TipoSolicitud' AND lo.nombre = 'BAJA'));

    IF EXISTS (
        SELECT 1 FROM cli_baja_cliente
        WHERE id_cliente = p_id_cliente
          AND estado = 1
          AND id_estado_aprobacion = v_id_pendiente
    ) THEN
        RETURN json_build_object('registro', NULL, 'error', 'El cliente ya tiene una solicitud de baja pendiente');
    END IF;

    INSERT INTO cli_baja_cliente (
        id_cliente, id_motivo_baja, fecha_baja,
        id_usuario_solicita, id_estado_aprobacion,
        id_tipo_solicitud, motivo_detalle,
        id_usuario_creacion, id_usuario_modificacion
    )
    VALUES (
        p_id_cliente, p_id_motivo_baja, CURRENT_DATE,
        p_id_usuario_auditoria, v_id_pendiente,
        v_id_tipo, NULLIF(TRIM(p_motivo_detalle), ''),
        p_id_usuario_auditoria, p_id_usuario_auditoria
    )
    RETURNING id INTO v_id_baja;

    RETURN cli_obtener_baja_cliente(v_id_baja);
END;
$$;


--
-- Name: cli_solicitar_reactivacion_cliente(integer, character varying, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cli_solicitar_reactivacion_cliente(p_id_cliente integer, p_motivo_detalle character varying DEFAULT NULL::character varying, p_id_usuario_auditoria integer DEFAULT NULL::integer, p_id_tipo_solicitud integer DEFAULT NULL::integer) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_id_baja INTEGER;
    v_estado_cliente INT;
    v_id_pendiente INTEGER;
    v_id_tipo INTEGER;
BEGIN
    SET TIME ZONE 'America/Lima';

    SELECT estado INTO v_estado_cliente FROM cli_clientes WHERE id = p_id_cliente;

    IF NOT FOUND THEN
        RETURN json_build_object('registro', NULL, 'error', 'El cliente no existe');
    END IF;

    IF v_estado_cliente = 1 THEN
        RETURN json_build_object('registro', NULL, 'error', 'El cliente ya está activo');
    END IF;

    SELECT lo.id INTO v_id_pendiente
    FROM gen_lista_opciones lo
    INNER JOIN gen_lista l ON lo.id_lista = l.id
    WHERE l.nombre = 'EstadoAprobacion' AND lo.nombre = 'PENDIENTE';

    v_id_tipo := COALESCE(p_id_tipo_solicitud, (SELECT lo.id
        FROM gen_lista_opciones lo
        INNER JOIN gen_lista l ON lo.id_lista = l.id
        WHERE l.nombre = 'TipoSolicitud' AND lo.nombre = 'REACTIVACION'));

    IF EXISTS (
        SELECT 1 FROM cli_baja_cliente
        WHERE id_cliente = p_id_cliente
          AND estado = 1
          AND id_estado_aprobacion = v_id_pendiente
          AND id_tipo_solicitud = v_id_tipo
    ) THEN
        RETURN json_build_object('registro', NULL, 'error', 'El cliente ya tiene una solicitud de reactivación pendiente');
    END IF;

    INSERT INTO cli_baja_cliente (
        id_cliente, id_tipo_solicitud, motivo_detalle,
        id_usuario_solicita, id_estado_aprobacion,
        id_usuario_creacion, id_usuario_modificacion
    )
    VALUES (
        p_id_cliente, v_id_tipo, NULLIF(TRIM(p_motivo_detalle), ''),
        p_id_usuario_auditoria, v_id_pendiente,
        p_id_usuario_auditoria, p_id_usuario_auditoria
    )


    RETURNING id INTO v_id_baja;

    RETURN cli_obtener_baja_cliente(v_id_baja);
END;
$$;


--
-- Name: cli_validar_documento_cliente(character varying, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cli_validar_documento_cliente(p_numero_documento character varying, p_id_excluir integer DEFAULT NULL::integer) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_existe BOOLEAN;
BEGIN
    SELECT EXISTS (
        SELECT 1 FROM cli_clientes
        WHERE numero_documento = p_numero_documento
          AND (p_id_excluir IS NULL OR id <> p_id_excluir)
    ) INTO v_existe;

    RETURN json_build_object('existe', v_existe);
END;
$$;


--
-- Name: com_actualizar_compra_cabecera(integer, character varying, integer, integer, boolean, integer, date, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.com_actualizar_compra_cabecera(p_id_comprobante integer, p_glosa character varying DEFAULT NULL::character varying, p_id_condicion_pago integer DEFAULT NULL::integer, p_id_categoria_gasto integer DEFAULT NULL::integer, p_declarar_sunat boolean DEFAULT NULL::boolean, p_id_usuario_auditoria integer DEFAULT NULL::integer, p_fecha_vencimiento_cxp date DEFAULT NULL::date, p_cuotas_cxp jsonb DEFAULT NULL::jsonb) RETURNS json
    LANGUAGE plpgsql
    AS $$
BEGIN
    SET TIME ZONE 'America/Lima';

    IF NOT EXISTS (SELECT 1 FROM com_comprobante_compra WHERE id = p_id_comprobante AND estado = 1) THEN
        RETURN json_build_object('error', 'La compra no existe o está anulada', 'registro', NULL);
    END IF;

    UPDATE com_comprobante_compra
    SET glosa               = COALESCE(p_glosa, glosa),
        id_condicion_pago   = COALESCE(p_id_condicion_pago, id_condicion_pago),
        id_categoria_gasto  = COALESCE(p_id_categoria_gasto, id_categoria_gasto),
        declarar_sunat      = COALESCE(p_declarar_sunat, declarar_sunat),
        id_usuario_modificacion = p_id_usuario_auditoria,
        fecha_modificacion  = NOW()
    WHERE id = p_id_comprobante;

    PERFORM com_sincronizar_cxp_compra(
        p_id_comprobante,
        p_id_usuario_auditoria,
        p_fecha_vencimiento_cxp,
        p_cuotas_cxp
    );

    RETURN com_obtener_compra(p_id_comprobante);
END;
$$;


--
-- Name: com_actualizar_compra_detalle(integer, numeric, numeric, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.com_actualizar_compra_detalle(p_id_detalle integer, p_cantidad numeric DEFAULT NULL::numeric, p_precio_unitario numeric DEFAULT NULL::numeric, p_id_usuario_auditoria integer DEFAULT NULL::integer) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_detalle             RECORD;
    v_nueva_cantidad      NUMERIC(12,4);
    v_nuevo_precio        NUMERIC(12,6);
    v_delta               NUMERIC(12,4);
    v_importe             NUMERIC(12,4);
    v_result_movimiento   JSON;
BEGIN
    SET TIME ZONE 'America/Lima';

    SELECT
        d.id,
        d.id_comprobante,
        d.id_producto,
        d.cantidad,
        d.precio_unitario,
        d.afecta_stock,
        COALESCE(d.id_almacen, c.id_almacen) AS id_almacen,
        c.fecha,
        c.serie,
        c.numero
    INTO v_detalle
    FROM com_comprobante_compra_detalle d
    JOIN com_comprobante_compra c ON c.id = d.id_comprobante
    WHERE d.id = p_id_detalle
      AND d.estado = 1
      AND c.estado = 1
    FOR UPDATE OF d, c;

    IF v_detalle.id IS NULL THEN
        RETURN json_build_object('error', 'La línea no existe o la compra está anulada', 'registro', NULL);
    END IF;

    v_nueva_cantidad := COALESCE(p_cantidad, v_detalle.cantidad);
    v_nuevo_precio := COALESCE(p_precio_unitario, v_detalle.precio_unitario);

    IF v_nueva_cantidad IS NULL OR v_nueva_cantidad <= 0 THEN
        RETURN json_build_object('error', 'La cantidad debe ser mayor a cero', 'registro', NULL);
    END IF;

    IF v_nuevo_precio IS NULL OR v_nuevo_precio < 0 THEN
        RETURN json_build_object('error', 'El precio unitario no puede ser negativo', 'registro', NULL);
    END IF;

    -- Sin cambios relevantes
    IF v_nueva_cantidad = v_detalle.cantidad
       AND COALESCE(v_nuevo_precio, 0) = COALESCE(v_detalle.precio_unitario, 0)
    THEN
        RETURN com_obtener_compra(v_detalle.id_comprobante);
    END IF;

    v_delta := v_nueva_cantidad - v_detalle.cantidad;

    IF v_detalle.afecta_stock AND v_delta <> 0 THEN
        IF v_delta > 0 THEN
            v_result_movimiento := inv_registrar_movimiento(
                p_naturaleza                => 'PRODUCTO',
                p_codigo_tipo_movimiento    => 'INGRESO',
                p_fecha                     => v_detalle.fecha,
                p_id_producto               => v_detalle.id_producto,
                p_cantidad                  => v_delta,
                p_id_almacen_origen         => v_detalle.id_almacen,
                p_codigo_tipo_documento_origen => 'COMPRA',
                p_id_documento_origen       => v_detalle.id,
                p_glosa                     => 'Ajuste (+) compra ' || v_detalle.serie || '-' || v_detalle.numero,
                p_id_usuario_auditoria      => p_id_usuario_auditoria,
                p_forzar                    => TRUE
            );
        ELSE
            v_result_movimiento := inv_registrar_movimiento(
                p_naturaleza                => 'PRODUCTO',
                p_codigo_tipo_movimiento    => 'SALIDA',
                p_fecha                     => CURRENT_DATE,
                p_id_producto               => v_detalle.id_producto,
                p_cantidad                  => ABS(v_delta),
                p_id_almacen_origen         => v_detalle.id_almacen,
                p_codigo_tipo_documento_origen => 'DEVOLUCION',
                p_id_documento_origen       => v_detalle.id,
                p_glosa                     => 'Ajuste (-) compra ' || v_detalle.serie || '-' || v_detalle.numero,
                p_id_usuario_auditoria      => p_id_usuario_auditoria,
                p_forzar                    => TRUE
            );
        END IF;

        IF (v_result_movimiento->>'error') IS NOT NULL THEN
            RETURN json_build_object('error', v_result_movimiento->>'error', 'registro', NULL);
        END IF;
    END IF;

    v_importe := v_nueva_cantidad * v_nuevo_precio;

    UPDATE com_comprobante_compra_detalle
    SET cantidad = v_nueva_cantidad,
        precio_unitario = v_nuevo_precio,
        importe = v_importe,
        id_usuario_modificacion = p_id_usuario_auditoria,
        fecha_modificacion = NOW()
    WHERE id = p_id_detalle;

    PERFORM com_recalcular_totales_compra(v_detalle.id_comprobante, p_id_usuario_auditoria);

    RETURN com_obtener_compra(v_detalle.id_comprobante);
END;
$$;


--
-- Name: com_anular_compra(integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.com_anular_compra(p_id_comprobante integer, p_id_usuario_auditoria integer DEFAULT NULL::integer) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_detalle             RECORD;
    v_id_almacen_default  INTEGER;
    v_serie               VARCHAR;
    v_numero              VARCHAR;
    v_id_tipo_salida      INTEGER;
    v_id_tipo_doc_ref     INTEGER;
    v_result_movimiento   JSON;
    v_stock_actual        NUMERIC(12,4);
    v_faltantes           TEXT := '';
    v_nombre_producto     VARCHAR;
    v_nombre_almacen      VARCHAR;
    v_id_estado_retornado INTEGER;
    v_id_estado_enviado   INTEGER;
    v_orden               RECORD;
    v_hay_pagos_cxp       BOOLEAN;
    v_id_cuenta_padre     INTEGER;
BEGIN
    SET TIME ZONE 'America/Lima';

    SELECT id_almacen, serie, numero
    INTO v_id_almacen_default, v_serie, v_numero
    FROM com_comprobante_compra
    WHERE id = p_id_comprobante AND estado = 1
    FOR UPDATE;

    IF NOT FOUND THEN
        RETURN json_build_object('eliminado', FALSE, 'id', p_id_comprobante);
    END IF;

    -- No anular si la CxP vinculada ya tiene pagos.
    SELECT EXISTS (
        SELECT 1
        FROM fin_pago p
        JOIN fin_cuenta c ON c.id = p.id_cuenta
        WHERE p.estado = 1
          AND c.estado = 1
          AND (
              c.id_comprobante_compra = p_id_comprobante
              OR c.id_cuenta_padre IN (
                  SELECT fc.id
                  FROM fin_cuenta fc
                  WHERE fc.id_comprobante_compra = p_id_comprobante
                    AND fc.estado = 1
                    AND fc.id_cuenta_padre IS NULL
              )
          )
    ) INTO v_hay_pagos_cxp;

    IF v_hay_pagos_cxp THEN
        RETURN json_build_object(
            'eliminado', FALSE,
            'id', p_id_comprobante,
            'error', 'No se puede anular: la cuenta por pagar vinculada tiene pagos registrados. Anule primero los pagos en Finanzas.'
        );
    END IF;

    SELECT glo.id INTO v_id_tipo_salida
    FROM gen_lista_opciones glo
    JOIN gen_lista gl ON gl.id = glo.id_lista
    WHERE gl.nombre = 'TipoMovInv' AND glo.nombre = 'SALIDA' AND glo.estado = 1;

    SELECT glo.id INTO v_id_tipo_doc_ref
    FROM gen_lista_opciones glo
    JOIN gen_lista gl ON gl.id = glo.id_lista
    WHERE gl.nombre = 'TipoDocumentoRef' AND glo.nombre = 'DEVOLUCION' AND glo.estado = 1;

    -- ---------- PASO 1: VALIDACIÓN COMPLETA (sin modificar nada aún) ----------
    -- Se bloquean (FOR UPDATE) las filas de pro_stock involucradas para que
    -- ninguna venta/compra concurrente cambie el stock entre esta validación
    -- y la reversa real del paso 2 (misma transacción, mismo lock).
    FOR v_detalle IN
        SELECT d.id, d.id_producto, d.cantidad,
               COALESCE(d.id_almacen, v_id_almacen_default) AS id_almacen
        FROM com_comprobante_compra_detalle d
        WHERE d.id_comprobante = p_id_comprobante
          AND d.afecta_stock = TRUE
          AND d.estado = 1
    LOOP
        SELECT stock INTO v_stock_actual
        FROM pro_stock
        WHERE id_producto = v_detalle.id_producto
          AND id_almacen = v_detalle.id_almacen
          AND estado = 1
        FOR UPDATE;

        v_stock_actual := COALESCE(v_stock_actual, 0);

        IF v_stock_actual < v_detalle.cantidad THEN
            SELECT nombre INTO v_nombre_producto FROM pro_producto WHERE id = v_detalle.id_producto;
            SELECT nombre INTO v_nombre_almacen FROM gen_almacen WHERE id = v_detalle.id_almacen;

            v_faltantes := v_faltantes || format(
                E'\n- %s en %s: ingresó %s, disponible %s, falta %s',
                v_nombre_producto, v_nombre_almacen,
                v_detalle.cantidad, v_stock_actual, (v_detalle.cantidad - v_stock_actual)
            );
        END IF;
    END LOOP;

    IF v_faltantes <> '' THEN
        RETURN json_build_object(
            'eliminado', FALSE, 'id', p_id_comprobante,
            'error', 'No se puede anular: el stock ya fue consumido por ventas u otros movimientos posteriores. Regularice el inventario antes de anular.' || v_faltantes
        );
    END IF;

    -- ---------- PASO 2: REVERSA REAL (ya validado que hay stock suficiente) ----------
    FOR v_detalle IN
        SELECT id, id_producto, cantidad, COALESCE(id_almacen, v_id_almacen_default) AS id_almacen
        FROM com_comprobante_compra_detalle
        WHERE id_comprobante = p_id_comprobante
          AND afecta_stock = TRUE
          AND estado = 1
    LOOP
        v_result_movimiento := inv_registrar_movimiento(
            p_naturaleza                => 'PRODUCTO',
            p_codigo_tipo_movimiento    => 'SALIDA',
            p_fecha                     => CURRENT_DATE,
            p_id_producto               => v_detalle.id_producto,
            p_id_balon                  => NULL,
            p_cantidad                  => v_detalle.cantidad,
            p_id_almacen_origen         => v_detalle.id_almacen,
            p_id_almacen_destino        => NULL,
            p_id_cliente                => NULL,
            p_codigo_tipo_documento_origen => 'DEVOLUCION',
            p_id_documento_origen       => v_detalle.id,
            p_glosa                     => 'Reversa por anulación de compra ' || v_serie || '-' || v_numero,
            p_id_usuario_auditoria      => p_id_usuario_auditoria,
            p_forzar                    => TRUE
        );

        IF (v_result_movimiento->>'error') IS NOT NULL THEN
            RAISE EXCEPTION 'No se pudo anular: %', v_result_movimiento->>'error';
        END IF;
    END LOOP;

    UPDATE com_comprobante_compra
    SET estado = 0,
        id_usuario_modificacion = p_id_usuario_auditoria,
        fecha_modificacion = NOW()
    WHERE id = p_id_comprobante;

    UPDATE com_comprobante_compra_detalle
    SET estado = 0,
        id_usuario_modificacion = p_id_usuario_auditoria,
        fecha_modificacion = NOW()
    WHERE id_comprobante = p_id_comprobante;

    -- Desvincular órdenes de recarga planta que apuntaban a esta compra.
    SELECT lo.id INTO v_id_estado_retornado
    FROM gen_lista_opciones lo
    INNER JOIN gen_lista l ON l.id = lo.id_lista
    WHERE l.nombre = 'EstadoRecargaPlanta' AND lo.nombre = 'RETORNADO' AND lo.estado = 1
    LIMIT 1;

    SELECT lo.id INTO v_id_estado_enviado
    FROM gen_lista_opciones lo
    INNER JOIN gen_lista l ON l.id = lo.id_lista
    WHERE l.nombre = 'EstadoRecargaPlanta' AND lo.nombre = 'ENVIADO' AND lo.estado = 1
    LIMIT 1;

    FOR v_orden IN
        SELECT id, fecha_llegada_almacen, id_almacen
        FROM bal_recarga_planta
        WHERE id_comprobante_compra = p_id_comprobante
          AND estado = 1
    LOOP
        PERFORM com_revertir_cilindros_recarga_compra(
            v_orden.id,
            p_id_comprobante,
            p_id_usuario_auditoria
        );

        UPDATE bal_recarga_planta
        SET
            id_comprobante_compra = NULL,
            serie_factura = NULL,
            numero_factura = NULL,
            id_estado = CASE
                WHEN v_orden.fecha_llegada_almacen IS NOT NULL THEN COALESCE(v_id_estado_retornado, id_estado)
                ELSE COALESCE(v_id_estado_enviado, id_estado)
            END,
            id_usuario_modificacion = p_id_usuario_auditoria,
            fecha_modificacion = NOW()
        WHERE id = v_orden.id;
    END LOOP;

    UPDATE bal_movimiento_recarga
    SET
        id_comprobante_compra = NULL,
        serie_factura = NULL,
        numero_factura = NULL,
        id_usuario_modificacion = p_id_usuario_auditoria,
        fecha_modificacion = NOW()
    WHERE id_comprobante_compra = p_id_comprobante
      AND estado = 1;

    -- Baja lógica de CxP vinculada (cabeceras + cuotas hijas). Ya validado sin pagos.
    FOR v_id_cuenta_padre IN
        SELECT fc.id
        FROM fin_cuenta fc
        WHERE fc.id_comprobante_compra = p_id_comprobante
          AND fc.estado = 1
          AND fc.id_cuenta_padre IS NULL
    LOOP
        UPDATE fin_cuenta
        SET estado = 0,
            id_usuario_modificacion = p_id_usuario_auditoria,
            fecha_modificacion = NOW()
        WHERE id = v_id_cuenta_padre
           OR id_cuenta_padre = v_id_cuenta_padre;
    END LOOP;

    RETURN json_build_object('eliminado', TRUE, 'id', p_id_comprobante);
END;
$$;


--
-- Name: com_crear_compra(integer, character varying, character varying, date, integer, integer, jsonb, integer, integer, integer, integer, integer, integer, integer, boolean, character varying, integer, boolean, date, character varying, date, date, integer, character varying, character varying, date, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.com_crear_compra(p_id_tipo_comprobante integer, p_serie character varying, p_numero character varying, p_fecha date, p_id_proveedor integer, p_id_almacen integer, p_detalles jsonb, p_id_comprobante_referencia integer DEFAULT NULL::integer, p_id_recarga_planta integer DEFAULT NULL::integer, p_id_tipo_registro integer DEFAULT NULL::integer, p_id_categoria_gasto integer DEFAULT NULL::integer, p_id_sucursal integer DEFAULT NULL::integer, p_id_moneda integer DEFAULT NULL::integer, p_id_condicion_pago integer DEFAULT NULL::integer, p_declarar_sunat boolean DEFAULT false, p_glosa character varying DEFAULT NULL::character varying, p_id_usuario_auditoria integer DEFAULT NULL::integer, p_registrar_retorno_balones boolean DEFAULT false, p_fecha_llegada_almacen date DEFAULT NULL::date, p_lote character varying DEFAULT NULL::character varying, p_fecha_vencimiento_lote date DEFAULT NULL::date, p_fecha_prueba_hidrostatica date DEFAULT NULL::date, p_id_guia_retorno integer DEFAULT NULL::integer, p_serie_guia_ingreso character varying DEFAULT NULL::character varying, p_numero_guia_ingreso character varying DEFAULT NULL::character varying, p_fecha_vencimiento_cxp date DEFAULT NULL::date, p_cuotas_cxp jsonb DEFAULT NULL::jsonb) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_id_compra           INTEGER;
    v_link_planta         JSON;
    v_id_detalle          INTEGER;
    v_item                INTEGER := 0;
    v_linea               JSONB;
    v_id_producto         INTEGER;
    v_id_almacen_linea    INTEGER;
    v_cantidad            NUMERIC(12,4);
    v_precio_unitario     NUMERIC(12,6);
    v_afecta_stock        BOOLEAN;
    v_importe             NUMERIC(12,4);
    v_total_bruto         NUMERIC(12,4) := 0;
    v_tasa_igv            NUMERIC(6,4) := 0.18;
    v_base_imponible      NUMERIC(12,4);
    v_igv_calculado       NUMERIC(12,4);
    v_id_tipo_ingreso     INTEGER;
    v_id_tipo_doc_ref     INTEGER;
    v_result_movimiento   JSON;
    v_descripcion_linea   VARCHAR;
    v_ref_estado          INTEGER;
    v_ref_serie           VARCHAR;
    v_ref_numero          VARCHAR;
    v_glosa_final         VARCHAR;
    v_recarga_id_comprobante INTEGER;
    v_recarga_estado_nombre  VARCHAR;
    v_registrar_retorno   BOOLEAN;
    v_fecha_llegada       DATE;
    v_lote                VARCHAR;
    v_fecha_venc_lote     DATE;
    v_fecha_ph            DATE;
BEGIN
    SET TIME ZONE 'America/Lima';
 
    IF p_fecha IS NULL THEN
        RETURN json_build_object('error', 'La fecha de la compra es obligatoria', 'registro', NULL);
    END IF;
 
    IF NOT EXISTS (
        SELECT 1 FROM cli_clientes WHERE id = p_id_proveedor AND estado = 1
    ) THEN
        RETURN json_build_object('error', 'El proveedor indicado no existe o está inactivo', 'registro', NULL);
    END IF;
 
    IF NOT EXISTS (
        SELECT 1 FROM gen_almacen WHERE id = p_id_almacen AND estado = 1
    ) THEN
        RETURN json_build_object('error', 'El almacén (por defecto) indicado no existe o está inactivo', 'registro', NULL);
    END IF;
 
    -- El detalle de productos es opcional: se puede registrar la cabecera
    -- (por ejemplo, ligada a una orden de recarga en planta externa) y
    -- agregar las líneas después con com_crear_compra_detalle.
    IF p_detalles IS NOT NULL AND jsonb_typeof(p_detalles) IS DISTINCT FROM 'array' THEN
        RETURN json_build_object('error', 'El detalle de productos debe ser un arreglo JSON', 'registro', NULL);
    END IF;

    v_glosa_final := p_glosa;
    IF p_id_comprobante_referencia IS NOT NULL THEN
        SELECT estado, serie, numero INTO v_ref_estado, v_ref_serie, v_ref_numero
        FROM com_comprobante_compra
        WHERE id = p_id_comprobante_referencia;
 
        IF v_ref_estado IS NULL THEN
            RETURN json_build_object('error', 'La compra de referencia indicada no existe', 'registro', NULL);
        END IF;
 
        IF v_ref_estado <> 0 THEN
            RETURN json_build_object(
                'error', 'La compra de referencia debe estar anulada antes de registrar la corrección (serie ' || v_ref_serie || '-' || v_ref_numero || ' sigue activa)',
                'registro', NULL
            );
        END IF;
 
        IF v_glosa_final IS NULL THEN
            v_glosa_final := 'Corrige compra anulada ' || v_ref_serie || '-' || v_ref_numero;
        END IF;
    END IF;

    -- La orden debe existir, estar activa, y NO estar ya cerrada/facturada
    -- (id_comprobante_compra ya seteado por bal_finalizar_recarga_planta en
    -- una compra anterior) — si no, se estaría facturando la misma orden
    -- dos veces.
    IF p_id_recarga_planta IS NOT NULL THEN
        SELECT rp.id_comprobante_compra, est.nombre
        INTO v_recarga_id_comprobante, v_recarga_estado_nombre
        FROM bal_recarga_planta rp
        LEFT JOIN gen_lista_opciones est ON est.id = rp.id_estado
        WHERE rp.id = p_id_recarga_planta AND rp.estado = 1;

        IF NOT FOUND THEN
            RETURN json_build_object('error', 'La orden de recarga en planta externa indicada no existe o está inactiva', 'registro', NULL);
        END IF;

        IF v_recarga_id_comprobante IS NOT NULL OR v_recarga_estado_nombre = 'CERRADO' THEN
            RETURN json_build_object(
                'error', 'La orden de recarga en planta externa indicada ya está cerrada/facturada y no se puede volver a vincular',
                'registro', NULL
            );
        END IF;
    END IF;

    -- IDs de listas resueltos una sola vez (no dentro del loop). Solo hace
    -- falta que estén configuradas si de verdad hay líneas que procesar.
    IF p_detalles IS NOT NULL AND jsonb_array_length(p_detalles) > 0 THEN
        SELECT glo.id INTO v_id_tipo_ingreso
        FROM gen_lista_opciones glo
        JOIN gen_lista gl ON gl.id = glo.id_lista
        WHERE gl.nombre = 'TipoMovInv' AND glo.nombre = 'INGRESO' AND glo.estado = 1;

        SELECT glo.id INTO v_id_tipo_doc_ref
        FROM gen_lista_opciones glo
        JOIN gen_lista gl ON gl.id = glo.id_lista
        WHERE gl.nombre = 'TipoDocumentoRef' AND glo.nombre = 'COMPRA' AND glo.estado = 1;

        IF v_id_tipo_ingreso IS NULL OR v_id_tipo_doc_ref IS NULL THEN
            RAISE EXCEPTION 'Faltan configurar las opciones INGRESO (TipoMovInv) o COMPRA (TipoDocumentoRef) en gen_lista_opciones';
        END IF;
    END IF;

    -- Cabecera (totales en 0; se recalculan al final con lo realmente insertado)
    INSERT INTO com_comprobante_compra (
        id_tipo_comprobante, serie, numero, fecha, id_proveedor,
        id_tipo_registro, id_categoria_gasto, id_sucursal, id_almacen,
        id_moneda, id_condicion_pago, sub_total, igv, total_importe,
        declarar_sunat, glosa, id_comprobante_referencia, id_recarga_planta,
        id_usuario_creacion, id_usuario_modificacion
    ) VALUES (
        p_id_tipo_comprobante, p_serie, p_numero, p_fecha, p_id_proveedor,
        p_id_tipo_registro, p_id_categoria_gasto, p_id_sucursal, p_id_almacen,
        p_id_moneda, p_id_condicion_pago, 0, 0, 0,
        p_declarar_sunat, v_glosa_final, p_id_comprobante_referencia, p_id_recarga_planta,
        p_id_usuario_auditoria, p_id_usuario_auditoria
    )
    RETURNING id INTO v_id_compra;
 
    FOR v_linea IN SELECT * FROM jsonb_array_elements(COALESCE(p_detalles, '[]'::JSONB))
    LOOP
        v_item := v_item + 1;
 
        v_id_producto := (v_linea->>'id_producto')::INTEGER;
        v_cantidad := (v_linea->>'cantidad')::NUMERIC;
        v_precio_unitario := COALESCE((v_linea->>'precio_unitario')::NUMERIC, 0);
        v_id_almacen_linea := COALESCE((v_linea->>'id_almacen')::INTEGER, p_id_almacen);
 
        IF v_id_producto IS NULL THEN
            RAISE EXCEPTION 'La línea % no tiene id_producto', v_item;
        END IF;
 
        IF v_cantidad IS NULL OR v_cantidad <= 0 THEN
            RAISE EXCEPTION 'La cantidad de la línea % debe ser mayor a cero', v_item;
        END IF;
 
        IF NOT EXISTS (SELECT 1 FROM gen_almacen WHERE id = v_id_almacen_linea AND estado = 1) THEN
            RAISE EXCEPTION 'El almacén id=% de la línea % no existe o está inactivo', v_id_almacen_linea, v_item;
        END IF;
 
        SELECT afecta_stock INTO v_afecta_stock
        FROM pro_producto
        WHERE id = v_id_producto AND estado = 1;
 
        IF v_afecta_stock IS NULL THEN
            RAISE EXCEPTION 'El producto id=% de la línea % no existe o está inactivo', v_id_producto, v_item;
        END IF;
 
        v_importe := v_cantidad * v_precio_unitario;
        v_total_bruto := v_total_bruto + v_importe;
 
        v_descripcion_linea := v_linea->>'descripcion';
        IF v_descripcion_linea IS NULL THEN
            SELECT nombre INTO v_descripcion_linea FROM pro_producto WHERE id = v_id_producto;
        END IF;
 
        INSERT INTO com_comprobante_compra_detalle (
            id_comprobante, item, id_clasificacion_gasto, id_producto, descripcion,
            id_unidad_medida, id_almacen, cantidad, precio_unitario, importe,
            afecta_stock, id_usuario_creacion, id_usuario_modificacion
        ) VALUES (
            v_id_compra, v_item,
            (v_linea->>'id_clasificacion_gasto')::INTEGER,
            v_id_producto,
            v_descripcion_linea,
            (v_linea->>'id_unidad_medida')::INTEGER,
            v_id_almacen_linea,
            v_cantidad, v_precio_unitario, v_importe,
            v_afecta_stock, p_id_usuario_auditoria, p_id_usuario_auditoria
        )
        RETURNING id INTO v_id_detalle;
 
        IF v_afecta_stock THEN
            v_result_movimiento := inv_registrar_movimiento(
                p_naturaleza                => 'PRODUCTO',
                p_codigo_tipo_movimiento    => 'INGRESO',
                p_fecha                     => p_fecha,
                p_id_producto               => v_id_producto,
                p_id_balon                  => NULL,
                p_cantidad                  => v_cantidad,
                p_id_almacen_origen         => v_id_almacen_linea,
                p_id_almacen_destino        => NULL,
                p_id_cliente                => NULL,
                p_codigo_tipo_documento_origen => 'COMPRA',
                p_id_documento_origen       => v_id_detalle,
                p_glosa                     => 'Ingreso por compra ' || p_serie || '-' || p_numero,
                p_id_usuario_auditoria      => p_id_usuario_auditoria
            );
 
            IF (v_result_movimiento->>'error') IS NOT NULL THEN
                RAISE EXCEPTION '%', v_result_movimiento->>'error';
            END IF;
        END IF;
 
    END LOOP;
 
    v_base_imponible := ROUND(v_total_bruto / (1 + v_tasa_igv), 4);
    v_igv_calculado := v_total_bruto - v_base_imponible;

    UPDATE com_comprobante_compra
    SET sub_total = v_base_imponible,
        igv = v_igv_calculado,
        total_importe = v_total_bruto,
        afecta_inventario = EXISTS (
            SELECT 1
            FROM com_comprobante_compra_detalle
            WHERE id_comprobante = v_id_compra
              AND afecta_stock = TRUE
              AND estado = 1
        )
    WHERE id = v_id_compra;

    -- Vínculo opcional con orden de recarga planta externa (factura de costo).
    -- El gas NO ingresa a pro_stock: el retorno físico va por bal_actualizar_recarga_planta.
    IF p_id_recarga_planta IS NOT NULL THEN
        IF NOT EXISTS (
            SELECT 1 FROM bal_recarga_planta WHERE id = p_id_recarga_planta AND estado = 1
        ) THEN
            RAISE EXCEPTION 'Orden de recarga planta no encontrada o inactiva';
        END IF;

        IF EXISTS (
            SELECT 1
            FROM bal_recarga_planta
            WHERE id = p_id_recarga_planta
              AND estado = 1
              AND id_proveedor IS NOT NULL
              AND p_id_proveedor IS NOT NULL
              AND id_proveedor <> p_id_proveedor
        ) THEN
            RAISE EXCEPTION 'El proveedor de la compra no coincide con el de la orden de recarga';
        END IF;

        IF EXISTS (
            SELECT 1
            FROM bal_recarga_planta
            WHERE id = p_id_recarga_planta
              AND estado = 1
              AND id_comprobante_compra IS NOT NULL
              AND id_comprobante_compra <> v_id_compra
        ) THEN
            RAISE EXCEPTION 'La orden de recarga ya tiene otra compra vinculada';
        END IF;

        -- Retorno físico: checkbox o fecha de llegada enviada desde Compras.
        -- Protocolo (lote/venc/P.H.) puede venir en params o ya estar en la orden.
        v_registrar_retorno := COALESCE(p_registrar_retorno_balones, FALSE)
            OR p_fecha_llegada_almacen IS NOT NULL;

        SELECT
            COALESCE(NULLIF(TRIM(p_lote), ''), NULLIF(TRIM(rp.lote), '')),
            COALESCE(p_fecha_vencimiento_lote, rp.fecha_vencimiento_lote),
            COALESCE(p_fecha_prueba_hidrostatica, rp.fecha_prueba_hidrostatica)
        INTO v_lote, v_fecha_venc_lote, v_fecha_ph
        FROM bal_recarga_planta rp
        WHERE rp.id = p_id_recarga_planta AND rp.estado = 1;

        IF v_registrar_retorno THEN
            v_fecha_llegada := COALESCE(p_fecha_llegada_almacen, p_fecha);

            IF v_lote IS NULL OR v_fecha_venc_lote IS NULL OR v_fecha_ph IS NULL THEN
                RAISE EXCEPTION
                    'Para registrar el retorno de cilindros indique lote, vencimiento y P.H. (o complételos en la orden de recarga).';
            END IF;
        ELSE
            v_fecha_llegada := NULL;
        END IF;

        v_link_planta := bal_actualizar_recarga_planta(
            p_id                    => p_id_recarga_planta,
            p_id_almacen            => p_id_almacen,
            p_id_guia_retorno       => p_id_guia_retorno,
            p_serie_guia_ingreso    => p_serie_guia_ingreso,
            p_numero_guia_ingreso   => p_numero_guia_ingreso,
            -- Serie/número de factura no se replican: quedan en la compra y las
            -- lecturas de la orden los resuelven por JOIN vía este FK.
            p_id_comprobante_compra => v_id_compra,
            p_fecha_llegada_almacen => v_fecha_llegada,
            p_lote                  => v_lote,
            p_fecha_vencimiento_lote => v_fecha_venc_lote,
            p_fecha_prueba_hidrostatica => v_fecha_ph,
            p_id_usuario_auditoria  => p_id_usuario_auditoria
        );

        IF v_link_planta->>'error' IS NOT NULL THEN
            RAISE EXCEPTION '%', v_link_planta->>'error';
        END IF;
    END IF;

    -- Crédito / cuotas: genera CxP vinculada a la compra según condición de pago.
    PERFORM com_generar_cxp_compra(
        v_id_compra,
        p_id_usuario_auditoria,
        p_fecha_vencimiento_cxp,
        p_cuotas_cxp
    );

    RETURN com_obtener_compra(v_id_compra);
END;
$$;


--
-- Name: com_crear_compra_detalle(integer, integer, numeric, numeric, integer, character varying, integer, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.com_crear_compra_detalle(p_id_comprobante integer, p_id_producto integer, p_cantidad numeric, p_precio_unitario numeric DEFAULT 0, p_id_clasificacion_gasto integer DEFAULT NULL::integer, p_descripcion character varying DEFAULT NULL::character varying, p_id_unidad_medida integer DEFAULT NULL::integer, p_id_almacen integer DEFAULT NULL::integer, p_id_usuario_auditoria integer DEFAULT NULL::integer) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_id_detalle          INTEGER;
    v_item                INTEGER;
    v_afecta_stock        BOOLEAN;
    v_id_almacen_cabecera INTEGER;
    v_id_almacen_linea    INTEGER;
    v_fecha               DATE;
    v_serie               VARCHAR;
    v_numero              VARCHAR;
    v_importe             NUMERIC(12,4);
    v_result_movimiento   JSON;
    v_descripcion_linea   VARCHAR;
BEGIN
    SET TIME ZONE 'America/Lima';

    IF p_cantidad IS NULL OR p_cantidad <= 0 THEN
        RETURN json_build_object('error', 'La cantidad debe ser mayor a cero', 'registro', NULL);
    END IF;

    SELECT id_almacen, fecha, serie, numero
    INTO v_id_almacen_cabecera, v_fecha, v_serie, v_numero
    FROM com_comprobante_compra
    WHERE id = p_id_comprobante AND estado = 1
    FOR UPDATE;

    IF v_id_almacen_cabecera IS NULL THEN
        RETURN json_build_object('error', 'La compra indicada no existe o está anulada', 'registro', NULL);
    END IF;

    SELECT afecta_stock INTO v_afecta_stock
    FROM pro_producto
    WHERE id = p_id_producto AND estado = 1;

    IF v_afecta_stock IS NULL THEN
        RETURN json_build_object('error', 'El producto indicado no existe o está inactivo', 'registro', NULL);
    END IF;

    v_id_almacen_linea := COALESCE(p_id_almacen, v_id_almacen_cabecera);

    IF NOT EXISTS (SELECT 1 FROM gen_almacen WHERE id = v_id_almacen_linea AND estado = 1) THEN
        RETURN json_build_object('error', 'El almacén indicado no existe o está inactivo', 'registro', NULL);
    END IF;

    SELECT COALESCE(MAX(item), 0) + 1 INTO v_item
    FROM com_comprobante_compra_detalle
    WHERE id_comprobante = p_id_comprobante;

    v_importe := p_cantidad * p_precio_unitario;

    v_descripcion_linea := p_descripcion;
    IF v_descripcion_linea IS NULL THEN
        SELECT nombre INTO v_descripcion_linea FROM pro_producto WHERE id = p_id_producto;
    END IF;

    INSERT INTO com_comprobante_compra_detalle (
        id_comprobante, item, id_clasificacion_gasto, id_producto, descripcion,
        id_unidad_medida, id_almacen, cantidad, precio_unitario, importe,
        afecta_stock, id_usuario_creacion, id_usuario_modificacion
    ) VALUES (
        p_id_comprobante, v_item, p_id_clasificacion_gasto, p_id_producto, v_descripcion_linea,
        p_id_unidad_medida, v_id_almacen_linea, p_cantidad, p_precio_unitario, v_importe,
        v_afecta_stock, p_id_usuario_auditoria, p_id_usuario_auditoria
    )
    RETURNING id INTO v_id_detalle;

    IF v_afecta_stock THEN
        v_result_movimiento := inv_registrar_movimiento(
            p_naturaleza                => 'PRODUCTO',
            p_codigo_tipo_movimiento    => 'INGRESO',
            p_fecha                     => v_fecha,
            p_id_producto               => p_id_producto,
            p_cantidad                  => p_cantidad,
            p_id_almacen_origen         => v_id_almacen_linea,
            p_codigo_tipo_documento_origen => 'COMPRA',
            p_id_documento_origen       => v_id_detalle,
            p_glosa                     => 'Ingreso por compra ' || v_serie || '-' || v_numero,
            p_id_usuario_auditoria      => p_id_usuario_auditoria
        );

        IF (v_result_movimiento->>'error') IS NOT NULL THEN
            RAISE EXCEPTION '%', v_result_movimiento->>'error';
        END IF;
    END IF;

    UPDATE com_comprobante_compra
    SET afecta_inventario = EXISTS (
            SELECT 1
            FROM com_comprobante_compra_detalle
            WHERE id_comprobante = p_id_comprobante
              AND afecta_stock = TRUE
              AND estado = 1
        ),
        id_usuario_modificacion = p_id_usuario_auditoria,
        fecha_modificacion = NOW()
    WHERE id = p_id_comprobante;

    PERFORM com_recalcular_totales_compra(p_id_comprobante, p_id_usuario_auditoria);

    RETURN com_obtener_compra(p_id_comprobante);
END;
$$;


--
-- Name: com_eliminar_compra_detalle(integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.com_eliminar_compra_detalle(p_id_detalle integer, p_id_usuario_auditoria integer DEFAULT NULL::integer) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_detalle             RECORD;
    v_serie               VARCHAR;
    v_numero              VARCHAR;
    v_result_movimiento   JSON;
BEGIN
    SET TIME ZONE 'America/Lima';

    SELECT
        d.id,
        d.id_comprobante,
        d.id_producto,
        d.cantidad,
        d.afecta_stock,
        COALESCE(d.id_almacen, c.id_almacen) AS id_almacen,
        c.serie,
        c.numero
    INTO v_detalle
    FROM com_comprobante_compra_detalle d
    JOIN com_comprobante_compra c ON c.id = d.id_comprobante
    WHERE d.id = p_id_detalle AND d.estado = 1 AND c.estado = 1
    FOR UPDATE OF d, c;

    IF v_detalle.id IS NULL THEN
        RETURN json_build_object('eliminado', FALSE, 'id', p_id_detalle);
    END IF;

    v_serie := v_detalle.serie;
    v_numero := v_detalle.numero;

    IF v_detalle.afecta_stock THEN
        v_result_movimiento := inv_registrar_movimiento(
            p_naturaleza                => 'PRODUCTO',
            p_codigo_tipo_movimiento    => 'SALIDA',
            p_fecha                     => CURRENT_DATE,
            p_id_producto               => v_detalle.id_producto,
            p_cantidad                  => v_detalle.cantidad,
            p_id_almacen_origen         => v_detalle.id_almacen,
            p_codigo_tipo_documento_origen => 'DEVOLUCION',
            p_id_documento_origen       => v_detalle.id,
            p_glosa                     => 'Reversa por eliminación de línea compra ' || v_serie || '-' || v_numero,
            p_id_usuario_auditoria      => p_id_usuario_auditoria,
            p_forzar                    => TRUE
        );

        IF (v_result_movimiento->>'error') IS NOT NULL THEN
            RETURN json_build_object(
                'eliminado', FALSE,
                'id', p_id_detalle,
                'error', v_result_movimiento->>'error'
            );
        END IF;
    END IF;

    UPDATE com_comprobante_compra_detalle
    SET estado = 0,
        id_usuario_modificacion = p_id_usuario_auditoria,
        fecha_modificacion = NOW()
    WHERE id = p_id_detalle;

    UPDATE com_comprobante_compra
    SET afecta_inventario = EXISTS (
            SELECT 1
            FROM com_comprobante_compra_detalle
            WHERE id_comprobante = v_detalle.id_comprobante
              AND afecta_stock = TRUE
              AND estado = 1
        ),
        id_usuario_modificacion = p_id_usuario_auditoria,
        fecha_modificacion = NOW()
    WHERE id = v_detalle.id_comprobante;

    PERFORM com_recalcular_totales_compra(v_detalle.id_comprobante, p_id_usuario_auditoria);

    RETURN json_build_object('eliminado', TRUE, 'id', p_id_detalle);
END;
$$;


--
-- Name: com_generar_cxp_compra(integer, integer, date, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.com_generar_cxp_compra(p_id_comprobante integer, p_id_usuario_auditoria integer DEFAULT NULL::integer, p_fecha_vencimiento date DEFAULT NULL::date, p_cuotas jsonb DEFAULT NULL::jsonb) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_id_proveedor      INTEGER;
    v_fecha             DATE;
    v_serie             VARCHAR;
    v_numero            VARCHAR;
    v_total             NUMERIC(12,4);
    v_id_condicion      INTEGER;
    v_estado            INTEGER;
    v_dias_credito      INTEGER := 0;
    v_numero_cuotas     INTEGER := 0;
    v_dia_mes_pago      INTEGER;
    v_fecha_primera     DATE;
    v_fecha_venc        DATE;
    v_mes_base          DATE;
    v_ultimo_dia_mes    DATE;
    v_id_tipo_pagar     INTEGER;
    v_cxp_result        JSON;
    v_numero_comp       VARCHAR;
    v_id_padre          INTEGER;
    v_cuota             JSONB;
    v_idx               INTEGER;
    v_fecha_cuota       DATE;
    v_monto_cuota       NUMERIC(12,4);
BEGIN
    SET TIME ZONE 'America/Lima';

    SELECT
        c.id_proveedor,
        c.fecha,
        c.serie,
        c.numero,
        COALESCE(c.total_importe, 0),
        c.id_condicion_pago,
        c.estado
    INTO
        v_id_proveedor,
        v_fecha,
        v_serie,
        v_numero,
        v_total,
        v_id_condicion,
        v_estado
    FROM com_comprobante_compra c
    WHERE c.id = p_id_comprobante;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'La compra id=% no existe', p_id_comprobante;
    END IF;

    IF v_estado <> 1 THEN
        RETURN;
    END IF;

    IF v_id_condicion IS NULL OR v_total <= 0 OR v_id_proveedor IS NULL THEN
        RETURN;
    END IF;

    IF EXISTS (
        SELECT 1
        FROM fin_cuenta fc
        WHERE fc.id_comprobante_compra = p_id_comprobante
          AND fc.estado = 1
    ) THEN
        RETURN;
    END IF;

    SELECT
        COALESCE(cp.dias_credito, 0),
        COALESCE(cp.numero_cuotas, 0),
        cp.dia_mes_pago
    INTO v_dias_credito, v_numero_cuotas, v_dia_mes_pago
    FROM gen_condicion_pago cp
    WHERE cp.id = v_id_condicion
      AND cp.estado = 1;

    IF NOT FOUND THEN
        RETURN;
    END IF;

    IF p_cuotas IS NOT NULL
       AND jsonb_typeof(p_cuotas) = 'array'
       AND jsonb_array_length(p_cuotas) > 1 THEN
        v_numero_cuotas := jsonb_array_length(p_cuotas);
        v_fecha_primera := COALESCE(
            NULLIF(p_cuotas->0->>'fechaPago', '')::DATE,
            NULLIF(p_cuotas->0->>'fecha_pago', '')::DATE
        );
        IF v_fecha_primera IS NOT NULL THEN
            v_dia_mes_pago := COALESCE(v_dia_mes_pago, EXTRACT(DAY FROM v_fecha_primera)::INTEGER);
        END IF;
    END IF;

    IF NOT (v_dias_credito > 0 OR v_numero_cuotas > 1) THEN
        RETURN;
    END IF;

    v_numero_comp := COALESCE(v_serie, '') || '-' || COALESCE(v_numero, '');

    IF v_numero_cuotas > 1 THEN
        IF v_fecha_primera IS NULL THEN
            IF v_dia_mes_pago IS NULL OR v_dia_mes_pago < 1 OR v_dia_mes_pago > 31 THEN
                RAISE EXCEPTION
                    'La condición de pago en cuotas requiere día del mes a pagar (1 a 31).';
            END IF;

            IF v_dias_credito > 0 THEN
                v_fecha_primera := v_fecha + v_dias_credito;
            ELSE
                v_mes_base := date_trunc('month', v_fecha)::date;
                v_ultimo_dia_mes := (v_mes_base + INTERVAL '1 month - 1 day')::date;
                v_fecha_primera := LEAST(
                    (v_mes_base + ((v_dia_mes_pago - 1) * INTERVAL '1 day'))::date,
                    v_ultimo_dia_mes
                );
                IF v_fecha_primera < v_fecha THEN
                    v_mes_base := (v_mes_base + INTERVAL '1 month')::date;
                    v_ultimo_dia_mes := (v_mes_base + INTERVAL '1 month - 1 day')::date;
                    v_fecha_primera := LEAST(
                        (v_mes_base + ((v_dia_mes_pago - 1) * INTERVAL '1 day'))::date,
                        v_ultimo_dia_mes
                    );
                END IF;
            END IF;
        END IF;

        IF v_dia_mes_pago IS NULL OR v_dia_mes_pago < 1 OR v_dia_mes_pago > 31 THEN
            v_dia_mes_pago := EXTRACT(DAY FROM v_fecha_primera)::INTEGER;
        END IF;

        v_cxp_result := fin_crear_cuenta_cuotas(
            'PAGAR',
            v_id_proveedor,
            NULL,
            v_fecha,
            v_total,
            v_numero_cuotas,
            v_fecha_primera,
            v_dia_mes_pago,
            format(
                'CxP en %s cuotas (día %s) %s',
                v_numero_cuotas,
                v_dia_mes_pago,
                v_numero_comp
            ),
            NULL,
            NULL,
            NULL,
            v_numero_comp,
            p_id_usuario_auditoria,
            NULL,
            p_id_comprobante
        );

        IF v_cxp_result->>'error' IS NOT NULL THEN
            RAISE EXCEPTION '%', v_cxp_result->>'error';
        END IF;

        IF p_cuotas IS NOT NULL
           AND jsonb_typeof(p_cuotas) = 'array'
           AND jsonb_array_length(p_cuotas) > 0 THEN
            v_id_padre := (v_cxp_result->'registro'->>'id')::INTEGER;
            FOR v_idx IN 0 .. jsonb_array_length(p_cuotas) - 1 LOOP
                v_cuota := p_cuotas->v_idx;
                v_fecha_cuota := COALESCE(
                    NULLIF(v_cuota->>'fechaPago', '')::DATE,
                    NULLIF(v_cuota->>'fecha_pago', '')::DATE
                );
                v_monto_cuota := COALESCE(
                    NULLIF(v_cuota->>'monto', '')::NUMERIC,
                    NULL
                );
                UPDATE fin_cuenta h
                SET fecha_vencimiento = COALESCE(v_fecha_cuota, h.fecha_vencimiento),
                    monto_pendiente = COALESCE(v_monto_cuota, h.monto_pendiente),
                    monto_saldo = COALESCE(v_monto_cuota, h.monto_saldo)
                WHERE h.id_cuenta_padre = v_id_padre
                  AND h.numero_cuota = v_idx + 1
                  AND h.estado = 1;
            END LOOP;
        END IF;
    ELSE
        v_fecha_venc := COALESCE(p_fecha_vencimiento, v_fecha + v_dias_credito);

        SELECT glo.id
        INTO v_id_tipo_pagar
        FROM gen_lista_opciones glo
        JOIN gen_lista gl ON gl.id = glo.id_lista
        WHERE gl.nombre = 'TipoCuentaFinanciera'
          AND glo.nombre = 'PAGAR'
          AND glo.estado = 1
        LIMIT 1;

        IF v_id_tipo_pagar IS NULL THEN
            RAISE EXCEPTION
                'No está configurado el tipo de cuenta PAGAR (TipoCuentaFinanciera).';
        END IF;

        INSERT INTO fin_cuenta (
            id_tipo_cuenta,
            id_tercero,
            id_comprobante_compra,
            numero_comprobante,
            fecha_emision,
            fecha_vencimiento,
            monto_pendiente,
            monto_abonado,
            monto_saldo,
            descripcion,
            id_usuario_creacion,
            id_usuario_modificacion
        ) VALUES (
            v_id_tipo_pagar,
            v_id_proveedor,
            p_id_comprobante,
            v_numero_comp,
            v_fecha,
            v_fecha_venc,
            v_total,
            0,
            v_total,
            format(
                'CxP por compra a crédito (%s días) %s',
                v_dias_credito,
                v_numero_comp
            ),
            p_id_usuario_auditoria,
            p_id_usuario_auditoria
        );
    END IF;
END;
$$;


--
-- Name: com_listar_compras(character varying, integer, integer, integer, integer, date, date, integer, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.com_listar_compras(p_busqueda character varying DEFAULT ''::character varying, p_limite integer DEFAULT 10, p_offset integer DEFAULT 0, p_id_proveedor integer DEFAULT NULL::integer, p_id_almacen integer DEFAULT NULL::integer, p_fecha_desde date DEFAULT NULL::date, p_fecha_hasta date DEFAULT NULL::date, p_estado integer DEFAULT NULL::integer, p_id_tipo_registro integer DEFAULT NULL::integer, p_id_categoria_gasto integer DEFAULT NULL::integer) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_registros JSON;
    v_total     BIGINT;
BEGIN
    SET TIME ZONE 'America/Lima';

    SELECT COUNT(*) INTO v_total
    FROM com_comprobante_compra c
    LEFT JOIN cli_clientes pr ON pr.id = c.id_proveedor
    WHERE (p_id_proveedor IS NULL OR c.id_proveedor = p_id_proveedor)
      AND (p_id_almacen IS NULL OR c.id_almacen = p_id_almacen)
      AND (p_fecha_desde IS NULL OR c.fecha >= p_fecha_desde)
      AND (p_fecha_hasta IS NULL OR c.fecha <= p_fecha_hasta)
      AND (p_estado IS NULL OR c.estado = p_estado)
      AND (p_id_tipo_registro IS NULL OR c.id_tipo_registro = p_id_tipo_registro)
      AND (p_id_categoria_gasto IS NULL OR c.id_categoria_gasto = p_id_categoria_gasto)
      AND (
          p_busqueda = ''
          OR LOWER(COALESCE(c.serie, '')) LIKE LOWER('%' || p_busqueda || '%')
          OR LOWER(COALESCE(c.numero, '')) LIKE LOWER('%' || p_busqueda || '%')
          OR LOWER(COALESCE(c.glosa, '')) LIKE LOWER('%' || p_busqueda || '%')
          OR LOWER(COALESCE(pr.razon_social, '')) LIKE LOWER('%' || p_busqueda || '%')
          OR LOWER(COALESCE(pr.nombres, '')) LIKE LOWER('%' || p_busqueda || '%')
          OR LOWER(COALESCE(pr.apellido_paterno, '')) LIKE LOWER('%' || p_busqueda || '%')
          OR LOWER(COALESCE(pr.numero_documento, '')) LIKE LOWER('%' || p_busqueda || '%')
      );

    SELECT COALESCE(json_agg(row_to_json(t)), '[]'::json) INTO v_registros
    FROM (
        SELECT
            c.id, c.serie, c.numero, c.fecha,
            c.id_proveedor,
            COALESCE(
                NULLIF(TRIM(pr.razon_social), ''),
                NULLIF(TRIM(CONCAT_WS(' ', pr.nombres, pr.apellido_paterno, pr.apellido_materno)), ''),
                pr.numero_documento
            ) AS nombre_proveedor,
            c.id_almacen, alm.nombre AS almacen,
            c.id_tipo_registro, tr.nombre AS tipo_registro,
            c.id_categoria_gasto, cat.nombre AS categoria_gasto,
            c.sub_total, c.total_importe,
            c.estado,
            com_tiene_movimientos_inventario(c.id) AS tiene_movimientos_inventario,
            c.id_comprobante_referencia
        FROM com_comprobante_compra c
        LEFT JOIN cli_clientes pr ON pr.id = c.id_proveedor
        LEFT JOIN gen_almacen alm ON alm.id = c.id_almacen
        LEFT JOIN gen_lista_opciones tr ON tr.id = c.id_tipo_registro
        LEFT JOIN gen_lista_opciones cat ON cat.id = c.id_categoria_gasto
        WHERE (p_id_proveedor IS NULL OR c.id_proveedor = p_id_proveedor)
          AND (p_id_almacen IS NULL OR c.id_almacen = p_id_almacen)
          AND (p_fecha_desde IS NULL OR c.fecha >= p_fecha_desde)
          AND (p_fecha_hasta IS NULL OR c.fecha <= p_fecha_hasta)
          AND (p_estado IS NULL OR c.estado = p_estado)
          AND (p_id_tipo_registro IS NULL OR c.id_tipo_registro = p_id_tipo_registro)
          AND (p_id_categoria_gasto IS NULL OR c.id_categoria_gasto = p_id_categoria_gasto)
          AND (
              p_busqueda = ''
              OR LOWER(COALESCE(c.serie, '')) LIKE LOWER('%' || p_busqueda || '%')
              OR LOWER(COALESCE(c.numero, '')) LIKE LOWER('%' || p_busqueda || '%')
              OR LOWER(COALESCE(c.glosa, '')) LIKE LOWER('%' || p_busqueda || '%')
              OR LOWER(COALESCE(pr.razon_social, '')) LIKE LOWER('%' || p_busqueda || '%')
              OR LOWER(COALESCE(pr.nombres, '')) LIKE LOWER('%' || p_busqueda || '%')
              OR LOWER(COALESCE(pr.apellido_paterno, '')) LIKE LOWER('%' || p_busqueda || '%')
              OR LOWER(COALESCE(pr.numero_documento, '')) LIKE LOWER('%' || p_busqueda || '%')
          )
        ORDER BY c.fecha DESC, c.id DESC
        LIMIT p_limite OFFSET p_offset
    ) t;

    RETURN json_build_object('registros', v_registros, 'total', v_total);
END;
$$;


--
-- Name: com_obtener_compra(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.com_obtener_compra(p_id integer) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_cabecera JSON;
    v_detalle  JSON;
    v_cuenta   JSON;
BEGIN
    SELECT json_build_object(
        'id',                        c.id,
        'id_tipo_comprobante',       c.id_tipo_comprobante,
        'tipo_comprobante',          tc.nombre,
        'serie',                     c.serie,
        'numero',                    c.numero,
        'fecha',                     c.fecha,
        'id_proveedor',              c.id_proveedor,
        'proveedor',                 COALESCE(
                                          NULLIF(TRIM(pr.razon_social), ''),
                                          NULLIF(TRIM(CONCAT_WS(' ', pr.nombres, pr.apellido_paterno, pr.apellido_materno)), ''),
                                          pr.numero_documento
                                      ),
        'proveedor_documento',       pr.numero_documento,
        'id_tipo_registro',          c.id_tipo_registro,
        'tipo_registro',             tr.nombre,
        'id_categoria_gasto',        c.id_categoria_gasto,
        'categoria_gasto',           cat.nombre,
        'id_sucursal',               c.id_sucursal,
        'sucursal',                  suc.nombre,
        'id_almacen',                c.id_almacen,
        'almacen',                   alm.nombre,
        'id_moneda',                 c.id_moneda,
        'moneda',                    mon.nombre,
        'id_condicion_pago',         c.id_condicion_pago,
        'condicion_pago',            cp.nombre,
        'sub_total',                 c.sub_total,
        'igv',                       c.igv,
        'total_importe',             c.total_importe,
        'afecta_inventario',         c.afecta_inventario,
        'declarar_sunat',            c.declarar_sunat,
        'glosa',                     c.glosa,
        'id_estado',                 c.id_estado,
        'estado_pago',               est.nombre,
        'estado',                    c.estado,
        'id_comprobante_referencia', c.id_comprobante_referencia,
        'id_recarga_planta',         c.id_recarga_planta,
        'numero_recarga_planta',     rp.numero,
        'tiene_movimientos_inventario', com_tiene_movimientos_inventario(c.id),
        -- Activa: se puede editar cabecera y líneas (ingresos/salidas según afecta_stock)
        'puede_modificarse_parcial', (c.estado = 1),
        'fecha_creacion',            c.fecha_creacion,
        'fecha_modificacion',        c.fecha_modificacion
    )
    INTO v_cabecera
    FROM com_comprobante_compra c
    LEFT JOIN cli_clientes pr             ON pr.id = c.id_proveedor
    LEFT JOIN gen_lista_opciones tc       ON tc.id = c.id_tipo_comprobante
    LEFT JOIN gen_lista_opciones tr       ON tr.id = c.id_tipo_registro
    LEFT JOIN gen_lista_opciones cat      ON cat.id = c.id_categoria_gasto
    LEFT JOIN gen_sucursal suc            ON suc.id = c.id_sucursal
    LEFT JOIN gen_almacen alm             ON alm.id = c.id_almacen
    LEFT JOIN gen_lista_opciones mon      ON mon.id = c.id_moneda
    LEFT JOIN gen_condicion_pago cp       ON cp.id = c.id_condicion_pago
    LEFT JOIN gen_lista_opciones est      ON est.id = c.id_estado
    LEFT JOIN bal_recarga_planta rp       ON rp.id = c.id_recarga_planta
    WHERE c.id = p_id;

    IF v_cabecera IS NULL THEN
        RETURN json_build_object('error', 'La compra no existe', 'registro', NULL);
    END IF;

    SELECT COALESCE(json_agg(d ORDER BY (d->>'item')::INTEGER), '[]'::json)
    INTO v_detalle
    FROM (
        SELECT json_build_object(
            'id',                     cd.id,
            'item',                   cd.item,
            'id_producto',            cd.id_producto,
            'codigo_producto',        p.codigo,
            'nombre_producto',        p.nombre,
            'descripcion',            cd.descripcion,
            'id_unidad_medida',       cd.id_unidad_medida,
            'unidad_medida',          um.nombre,
            'id_almacen',             cd.id_almacen,
            'almacen',                alm2.nombre,
            'cantidad',               cd.cantidad,
            'precio_unitario',        cd.precio_unitario,
            'importe',                cd.importe,
            'afecta_stock',           cd.afecta_stock,
            'id_clasificacion_gasto', cd.id_clasificacion_gasto,
            'clasificacion_gasto',    CASE WHEN cg.id IS NOT NULL
                                          THEN cg.grupo || ' > ' || cg.subgrupo || ' > ' || cg.sub_subgrupo
                                          ELSE NULL END,
            'id_estado_pago',         cd.id_estado_pago,
            'fecha_pago',             cd.fecha_pago,
            'estado',                 cd.estado
        ) AS d
        FROM com_comprobante_compra_detalle cd
        JOIN pro_producto p                        ON p.id = cd.id_producto
        LEFT JOIN gen_lista_opciones um             ON um.id = cd.id_unidad_medida
        LEFT JOIN gen_almacen alm2                  ON alm2.id = cd.id_almacen
        LEFT JOIN gen_clasificacion_gasto cg        ON cg.id = cd.id_clasificacion_gasto
        WHERE cd.id_comprobante = p_id
          AND cd.estado = 1
    ) sub;

    SELECT json_build_object(
        'id', fc.id,
        'descripcion', fc.descripcion,
        'numero_cuotas_total', fc.numero_cuotas_total,
        'monto_pendiente', fc.monto_pendiente,
        'monto_abonado', COALESCE(fc.monto_abonado, 0),
        'saldo', COALESCE(fc.monto_saldo, fc.monto_pendiente - COALESCE(fc.monto_abonado, 0)),
        'fecha_vencimiento', fc.fecha_vencimiento,
        'cuotas', (
            SELECT COALESCE(json_agg(
                json_build_object(
                    'id', h.id,
                    'numero_cuota', h.numero_cuota,
                    'fecha_vencimiento', h.fecha_vencimiento,
                    'monto_pendiente', h.monto_pendiente,
                    'monto_abonado', COALESCE(h.monto_abonado, 0),
                    'saldo', COALESCE(h.monto_saldo, h.monto_pendiente - COALESCE(h.monto_abonado, 0))
                ) ORDER BY h.numero_cuota
            ), '[]'::json)
            FROM fin_cuenta h
            WHERE h.id_cuenta_padre = fc.id AND h.estado = 1
        )
    )
    INTO v_cuenta
    FROM fin_cuenta fc
    WHERE fc.id_comprobante_compra = p_id
      AND fc.estado = 1
      AND fc.id_cuenta_padre IS NULL
    ORDER BY fc.id
    LIMIT 1;

    RETURN json_build_object(
        'error', NULL,
        'registro', json_build_object(
            'cabecera', v_cabecera,
            'detalle', v_detalle,
            'cuenta_por_pagar', v_cuenta
        )
    );
END;
$$;


--
-- Name: com_recalcular_totales_compra(integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.com_recalcular_totales_compra(p_id_comprobante integer, p_id_usuario_auditoria integer DEFAULT NULL::integer) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_total_bruto     NUMERIC(12,4);
    v_tasa_igv        NUMERIC(6,4) := 0.18;
    v_base_imponible  NUMERIC(12,4);
    v_igv_calculado   NUMERIC(12,4);
BEGIN
    SELECT COALESCE(SUM(importe), 0) INTO v_total_bruto
    FROM com_comprobante_compra_detalle
    WHERE id_comprobante = p_id_comprobante AND estado = 1;

    v_base_imponible := ROUND(v_total_bruto / (1 + v_tasa_igv), 4);
    v_igv_calculado := v_total_bruto - v_base_imponible;

    UPDATE com_comprobante_compra
    SET sub_total = v_base_imponible,
        igv = v_igv_calculado,
        total_importe = v_total_bruto,
        id_usuario_modificacion = p_id_usuario_auditoria,
        fecha_modificacion = NOW()
    WHERE id = p_id_comprobante;

    -- Si la cabecera se creó sin líneas (total 0) y ahora hay importe + crédito/cuotas,
    -- genera la CxP (idempotente si ya existe).
    PERFORM com_sincronizar_cxp_compra(p_id_comprobante, p_id_usuario_auditoria);
END;
$$;


--
-- Name: com_revertir_cilindros_recarga_compra(integer, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.com_revertir_cilindros_recarga_compra(p_id_recarga_planta integer, p_id_comprobante integer, p_id_usuario integer DEFAULT NULL::integer) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_det RECORD;
    v_estado VARCHAR;
    v_id_recarga_ext INTEGER;
    v_id_tipo_doc_compra INTEGER;
    v_id_tipo_doc_recarga INTEGER;
BEGIN
    SELECT lo.id INTO v_id_recarga_ext
    FROM gen_lista_opciones lo
    INNER JOIN gen_lista l ON l.id = lo.id_lista
    WHERE l.nombre = 'EstadoBalon' AND lo.nombre = 'EN_RECARGA_EXTERNA' AND lo.estado = 1
    LIMIT 1;

    SELECT lo.id INTO v_id_tipo_doc_compra
    FROM gen_lista_opciones lo
    INNER JOIN gen_lista l ON l.id = lo.id_lista
    WHERE l.nombre = 'TipoDocumentoRef' AND lo.nombre = 'COMPRA' AND lo.estado = 1
    LIMIT 1;

    SELECT lo.id INTO v_id_tipo_doc_recarga
    FROM gen_lista_opciones lo
    INNER JOIN gen_lista l ON l.id = lo.id_lista
    WHERE l.nombre = 'TipoDocumentoRef' AND lo.nombre = 'RECARGA' AND lo.estado = 1
    LIMIT 1;

    FOR v_det IN
        SELECT d.id_balon
        FROM bal_recarga_planta_detalle d
        WHERE d.id_recarga_planta = p_id_recarga_planta
          AND d.estado = 1
    LOOP
        SELECT eb.nombre INTO v_estado
        FROM bal_balon b
        LEFT JOIN gen_lista_opciones eb ON eb.id = b.id_estado_balon
        WHERE b.id = v_det.id_balon AND b.estado = 1;

        IF COALESCE(v_estado, '') NOT IN ('EN_ALMACEN', 'EN_RECARGA_EXTERNA') THEN
            RAISE EXCEPTION
                'No se puede anular la compra: el cilindro % ya no está en almacén ni en recarga externa (estado %).',
                v_det.id_balon,
                COALESCE(v_estado, 'sin estado');
        END IF;

        IF COALESCE(v_estado, '') = 'EN_ALMACEN' AND v_id_recarga_ext IS NOT NULL THEN
            UPDATE bal_balon
            SET
                id_estado_balon = v_id_recarga_ext,
                id_almacen = NULL,
                id_usuario_modificacion = p_id_usuario,
                fecha_modificacion = NOW()
            WHERE id = v_det.id_balon AND estado = 1;
        END IF;
    END LOOP;

    -- Entradas de cilindro ya repuntadas a COMPRA: reapuntar solo naturaleza BALON
    -- (no tocar INGRESO de producto; com_anular_compra lo compensa con SALIDA)
    -- para poder revertirlas con inv_revertir_por_documento('RECARGA', orden).
    IF v_id_tipo_doc_compra IS NOT NULL AND v_id_tipo_doc_recarga IS NOT NULL THEN
        UPDATE inv_movimiento m
        SET
            id_documento_origen = p_id_recarga_planta,
            id_tipo_documento_origen = v_id_tipo_doc_recarga,
            id_usuario_modificacion = p_id_usuario,
            fecha_modificacion = NOW()
        WHERE m.estado = 1
          AND m.naturaleza = 'BALON'
          AND m.id_tipo_documento_origen = v_id_tipo_doc_compra
          AND m.id_documento_origen = p_id_comprobante
          AND m.id_balon IN (
              SELECT d.id_balon
              FROM bal_recarga_planta_detalle d
              WHERE d.id_recarga_planta = p_id_recarga_planta
                AND d.estado = 1
          )
          AND m.id_tipo_movimiento IN (
              SELECT lo.id
              FROM gen_lista_opciones lo
              INNER JOIN gen_lista l ON l.id = lo.id_lista
              WHERE l.nombre = 'TipoMovBalon'
                AND lo.nombre IN ('ENTRADA_LLENADO', 'ENTRADA_PLANTA_EXTERNA')
                AND lo.estado = 1
          );
    END IF;

    -- Revierte entradas aún bajo RECARGA (orden) y las que acabamos de reapuntar.
    PERFORM inv_revertir_por_documento('RECARGA', p_id_recarga_planta, p_id_usuario);

    -- inv_revertir deja cilindros en EN_ALMACEN; al anular compra deben volver a EN_RECARGA_EXTERNA.
    IF v_id_recarga_ext IS NOT NULL THEN
        UPDATE bal_balon b
        SET
            id_estado_balon = v_id_recarga_ext,
            id_almacen = NULL,
            id_usuario_modificacion = p_id_usuario,
            fecha_modificacion = NOW()
        WHERE b.estado = 1
          AND b.id IN (
              SELECT d.id_balon
              FROM bal_recarga_planta_detalle d
              WHERE d.id_recarga_planta = p_id_recarga_planta
                AND d.estado = 1
          );
    END IF;
END;
$$;


--
-- Name: com_sincronizar_cxp_compra(integer, integer, date, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.com_sincronizar_cxp_compra(p_id_comprobante integer, p_id_usuario_auditoria integer DEFAULT NULL::integer, p_fecha_vencimiento date DEFAULT NULL::date, p_cuotas jsonb DEFAULT NULL::jsonb) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_total NUMERIC(12,4);
    v_id_condicion INTEGER;
    v_estado INTEGER;
    v_dias INTEGER := 0;
    v_cuotas INTEGER := 0;
    v_requiere BOOLEAN := FALSE;
    v_existe BOOLEAN := FALSE;
    v_hay_pagos BOOLEAN := FALSE;
    v_monto_actual NUMERIC(12,4);
BEGIN
    SET TIME ZONE 'America/Lima';

    SELECT COALESCE(c.total_importe, 0), c.id_condicion_pago, c.estado
    INTO v_total, v_id_condicion, v_estado
    FROM com_comprobante_compra c
    WHERE c.id = p_id_comprobante;

    IF NOT FOUND OR v_estado <> 1 THEN
        RETURN;
    END IF;

    IF v_id_condicion IS NOT NULL THEN
        SELECT COALESCE(cp.dias_credito, 0), COALESCE(cp.numero_cuotas, 0)
        INTO v_dias, v_cuotas
        FROM gen_condicion_pago cp
        WHERE cp.id = v_id_condicion AND cp.estado = 1;
    END IF;

    IF p_cuotas IS NOT NULL
       AND jsonb_typeof(p_cuotas) = 'array'
       AND jsonb_array_length(p_cuotas) > 1 THEN
        v_cuotas := jsonb_array_length(p_cuotas);
    END IF;

    v_requiere := v_total > 0 AND (v_dias > 0 OR v_cuotas > 1);

    SELECT EXISTS (
        SELECT 1 FROM fin_cuenta fc
        WHERE fc.id_comprobante_compra = p_id_comprobante
          AND fc.estado = 1
          AND fc.id_cuenta_padre IS NULL
    ) INTO v_existe;

    v_hay_pagos := fin_cuenta_documento_tiene_pagos(NULL, p_id_comprobante);

    IF NOT v_requiere THEN
        IF v_hay_pagos THEN
            RAISE EXCEPTION
                'No se puede pasar a contado: la cuenta por pagar ya tiene pagos. Anule los pagos en Finanzas.';
        END IF;
        IF v_existe THEN
            PERFORM fin_bajar_cuentas_documento(p_id_usuario_auditoria, NULL, p_id_comprobante);
        END IF;
        RETURN;
    END IF;

    IF v_hay_pagos THEN
        SELECT COALESCE(fc.monto_pendiente, 0)
        INTO v_monto_actual
        FROM fin_cuenta fc
        WHERE fc.id_comprobante_compra = p_id_comprobante
          AND fc.estado = 1
          AND fc.id_cuenta_padre IS NULL
        ORDER BY fc.id
        LIMIT 1;

        IF ABS(COALESCE(v_monto_actual, 0) - v_total) > 0.009 THEN
            RAISE EXCEPTION
                'No se puede cambiar el total de la compra: la CxP ya tiene pagos. Anule los pagos en Finanzas.';
        END IF;
        RETURN;
    END IF;

    IF v_existe THEN
        PERFORM fin_bajar_cuentas_documento(p_id_usuario_auditoria, NULL, p_id_comprobante);
    END IF;

    PERFORM com_generar_cxp_compra(
        p_id_comprobante,
        p_id_usuario_auditoria,
        p_fecha_vencimiento,
        p_cuotas
    );
END;
$$;


--
-- Name: com_tiene_movimientos_inventario(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.com_tiene_movimientos_inventario(p_id_comprobante integer) RETURNS boolean
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_tiene BOOLEAN;
BEGIN
    SELECT EXISTS (
        SELECT 1
        FROM com_comprobante_compra_detalle
        WHERE id_comprobante = p_id_comprobante
          AND afecta_stock = TRUE
          AND estado = 1
    ) INTO v_tiene;
 
    RETURN v_tiene;
END;
$$;


--
-- Name: dash_almacenes_operativos(integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.dash_almacenes_operativos(p_limite integer DEFAULT 20, p_offset integer DEFAULT 0) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_total_almacenes BIGINT := 0;
    v_registros JSON;
BEGIN
    SET TIME ZONE 'America/Lima';

    SELECT COUNT(*) INTO v_total_almacenes
    FROM gen_almacen
    WHERE estado = 1;

    SELECT COALESCE(json_agg(row_to_json(t)), '[]'::JSON) INTO v_registros
    FROM (
        SELECT 
            a.id AS id_almacen,
            a.nombre AS almacen,
            s.nombre AS sucursal,
            a.ubicacion,
            COALESCE(d.nombre, '—') AS distrito,
            COALESCE(prov.nombre, '—') AS provincia,
            (
                SELECT COUNT(*) 
                FROM pro_stock ps 
                WHERE ps.id_almacen = a.id AND ps.estado = 1 AND ps.stock > 0
            ) AS total_items_con_stock
        FROM gen_almacen a
        INNER JOIN gen_sucursal s ON a.id_sucursal = s.id
        LEFT JOIN gen_distrito d ON a.id_distrito = d.id
        LEFT JOIN gen_provincia prov ON a.id_provincia = prov.id
        WHERE a.estado = 1
        ORDER BY a.id ASC
        LIMIT p_limite OFFSET p_offset
    ) t;

    RETURN json_build_object(
        'totalAlmacenesOperativos', v_total_almacenes,
        'registros', v_registros
    );
END;
$$;


--
-- Name: dash_balones_alquilados(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.dash_balones_alquilados(p_id_cliente integer DEFAULT NULL::integer) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_id_estado INT;
  v_result JSON;
BEGIN
  SET TIME ZONE 'America/Lima';

  SELECT glo.id INTO v_id_estado
  FROM gen_lista_opciones glo
  JOIN gen_lista gl ON gl.id = glo.id_lista
  WHERE gl.nombre = 'EstadoBalon' AND glo.nombre = 'ALQUILADO'
  LIMIT 1;

  SELECT json_build_object(
    'cantidad', COUNT(*),
    'detalle', COALESCE(json_agg(
      json_build_object(
        'idBalon', b.id,
        'codigoBalon', b.codigo_balon,
        'tipoBalon', tb.nombre,
        'idCliente', c.id,
        'cliente', COALESCE(c.razon_social, c.nombres),
        'fechaInicio', al.fecha_inicio,
        'fechaFinPactada', al.fecha_fin_pactada
      )
    ), '[]'::json)
  )
  INTO v_result
  FROM bal_balon b
  LEFT JOIN bal_tipo_balon tb ON tb.id = b.id_tipo_balon
  LEFT JOIN cli_clientes c ON c.id = b.id_cliente_ubicacion
  LEFT JOIN LATERAL (
    SELECT al.fecha_inicio, al.fecha_fin_pactada
    FROM bal_alquiler_detalle ad
    JOIN bal_alquiler al ON al.id = ad.id_alquiler
    WHERE ad.id_balon = b.id
      AND ad.fecha_devolucion IS NULL
      AND ad.estado = 1
    ORDER BY al.fecha_inicio DESC
    LIMIT 1
  ) al ON TRUE
  WHERE b.id_estado_balon = v_id_estado
    AND b.estado = 1
    AND (p_id_cliente IS NULL OR b.id_cliente_ubicacion = p_id_cliente);

  RETURN v_result;
END;
$$;


--
-- Name: dash_balones_bajas_solicitadas(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.dash_balones_bajas_solicitadas() RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_result JSON;
BEGIN
  SET TIME ZONE 'America/Lima';

  SELECT json_build_object(
    'cantidad', COUNT(*),
    'detalle', COALESCE(json_agg(
      json_build_object(
        'idBaja', bb.id,
        'idBalon', b.id,
        'codigoBalon', b.codigo_balon,
        'motivo', mb.nombre,
        'motivoDetalle', bb.motivo_detalle,
        'fechaBaja', bb.fecha_baja,
        'usuarioSolicita', us.nombre
      )
      ORDER BY bb.fecha_baja
    ), '[]'::json)
  )
  INTO v_result
  FROM bal_baja_balon bb
  JOIN bal_balon b ON b.id = bb.id_balon
  LEFT JOIN gen_lista_opciones mb ON mb.id = bb.id_motivo_baja
  LEFT JOIN auth_usuarios us ON us.id = bb.id_usuario_solicita
  WHERE bb.estado = 1
    AND bb.estado_aprobacion = 'PENDIENTE';

  RETURN v_result;
END;
$$;


--
-- Name: dash_balones_en_almacen(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.dash_balones_en_almacen(p_id_cliente integer DEFAULT NULL::integer) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_id_estado INT;
  v_result JSON;
BEGIN
  SET TIME ZONE 'America/Lima';

  SELECT glo.id INTO v_id_estado
  FROM gen_lista_opciones glo
  JOIN gen_lista gl ON gl.id = glo.id_lista
  WHERE gl.nombre = 'EstadoBalon' AND glo.nombre = 'EN_ALMACEN'
  LIMIT 1;

  SELECT json_build_object(
    'cantidad', COUNT(*),
    'detalle', COALESCE(json_agg(
      json_build_object(
        'idBalon', b.id,
        'codigoBalon', b.codigo_balon,
        'tipoBalon', tb.nombre,
        'idAlmacen', b.id_almacen,
        'almacen', a.nombre
      )
    ), '[]'::json)
  )
  INTO v_result
  FROM bal_balon b
  LEFT JOIN bal_tipo_balon tb ON tb.id = b.id_tipo_balon
  LEFT JOIN gen_almacen a ON a.id = b.id_almacen
  WHERE b.id_estado_balon = v_id_estado
    AND b.estado = 1
    AND (p_id_cliente IS NULL OR b.id_cliente_ubicacion = p_id_cliente);

  RETURN v_result;
END;
$$;


--
-- Name: dash_balones_mantenimiento(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.dash_balones_mantenimiento(p_id_cliente integer DEFAULT NULL::integer) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_id_pendiente INT;
  v_id_en_proceso INT;
  v_result JSON;
BEGIN
  SET TIME ZONE 'America/Lima';

  SELECT glo.id INTO v_id_pendiente
  FROM gen_lista_opciones glo
  JOIN gen_lista gl ON gl.id = glo.id_lista
  WHERE gl.nombre = 'EstadoDocumento' AND glo.nombre = 'PENDIENTE'
  LIMIT 1;

  SELECT glo.id INTO v_id_en_proceso
  FROM gen_lista_opciones glo
  JOIN gen_lista gl ON gl.id = glo.id_lista
  WHERE gl.nombre = 'EstadoDocumento' AND glo.nombre = 'EN_PROCESO'
  LIMIT 1;

  SELECT json_build_object(
    'cantidad', COUNT(*),
    'detalle', COALESCE(json_agg(
      json_build_object(
        'idBalon', b.id,
        'codigoBalon', b.codigo_balon,
        'tipoBalon', tb.nombre,
        'tipoMantenimiento', tm.nombre,
        'fechaIngreso', m.fecha_ingreso,
        'esExterno', m.es_externo
      )
    ), '[]'::json)
  )
  INTO v_result
  FROM bal_mantenimiento m
  JOIN bal_balon b ON b.id = m.id_balon
  LEFT JOIN bal_tipo_balon tb ON tb.id = b.id_tipo_balon
  LEFT JOIN gen_lista_opciones tm ON tm.id = m.id_tipo_mantenimiento
  WHERE m.id_estado IN (v_id_pendiente, v_id_en_proceso)
    AND m.estado = 1
    AND (p_id_cliente IS NULL OR b.id_cliente_ubicacion = p_id_cliente);

  RETURN v_result;
END;
$$;


--
-- Name: dash_balones_ph_por_vencer(integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.dash_balones_ph_por_vencer(p_dias_alerta integer DEFAULT 30, p_id_cliente integer DEFAULT NULL::integer) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_id_baja INT;
  v_result JSON;
BEGIN
  SET TIME ZONE 'America/Lima';

  SELECT glo.id INTO v_id_baja
  FROM gen_lista_opciones glo
  JOIN gen_lista gl ON gl.id = glo.id_lista
  WHERE gl.nombre = 'EstadoBalon' AND glo.nombre = 'DADO_DE_BAJA'
  LIMIT 1;

  SELECT json_build_object(
    'cantidad', COUNT(*),
    'detalle', COALESCE(json_agg(
      json_build_object(
        'idBalon', b.id,
        'codigoBalon', b.codigo_balon,
        'tipoBalon', tb.nombre,
        'fechaProximaPh', b.fecha_proxima_prueba_hidrostatica,
        'diasRestantes', (b.fecha_proxima_prueba_hidrostatica - CURRENT_DATE),
        'vencido', (b.fecha_proxima_prueba_hidrostatica < CURRENT_DATE)
      )
      ORDER BY b.fecha_proxima_prueba_hidrostatica
    ), '[]'::json)
  )
  INTO v_result
  FROM bal_balon b
  LEFT JOIN bal_tipo_balon tb ON tb.id = b.id_tipo_balon
  WHERE b.fecha_proxima_prueba_hidrostatica IS NOT NULL
    AND b.fecha_proxima_prueba_hidrostatica <= (CURRENT_DATE + (p_dias_alerta || ' days')::INTERVAL)
    AND (v_id_baja IS NULL OR b.id_estado_balon IS DISTINCT FROM v_id_baja)
    AND b.estado = 1
    AND (p_id_cliente IS NULL OR b.id_cliente_ubicacion = p_id_cliente);

  RETURN v_result;
END;
$$;


--
-- Name: dash_balones_prestados(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.dash_balones_prestados(p_id_cliente integer DEFAULT NULL::integer) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_id_estado INT;
  v_result JSON;
BEGIN
  SET TIME ZONE 'America/Lima';

  SELECT glo.id INTO v_id_estado
  FROM gen_lista_opciones glo
  JOIN gen_lista gl ON gl.id = glo.id_lista
  WHERE gl.nombre = 'EstadoBalon' AND glo.nombre = 'PRESTADO_CLIENTE'
  LIMIT 1;

  SELECT json_build_object(
    'cantidad', COUNT(*),
    'detalle', COALESCE(json_agg(
      json_build_object(
        'idBalon', b.id,
        'codigoBalon', b.codigo_balon,
        'tipoBalon', tb.nombre,
        'idCliente', c.id,
        'cliente', COALESCE(c.razon_social, c.nombres),
        'fechaPrestamo', pd.fecha_prestamo,
        'fechaVencimiento', pd.fecha_vencimiento
      )
    ), '[]'::json)
  )
  INTO v_result
  FROM bal_balon b
  LEFT JOIN bal_tipo_balon tb ON tb.id = b.id_tipo_balon
  LEFT JOIN cli_clientes c ON c.id = b.id_cliente_ubicacion
  LEFT JOIN LATERAL (
    SELECT pd.fecha_prestamo, pd.fecha_vencimiento
    FROM bal_prestamo_detalle pd
    WHERE pd.id_balon = b.id
      AND pd.fecha_devolucion IS NULL
      AND pd.estado = 1
    ORDER BY pd.fecha_prestamo DESC
    LIMIT 1
  ) pd ON TRUE
  WHERE b.id_estado_balon = v_id_estado
    AND b.estado = 1
    AND (p_id_cliente IS NULL OR b.id_cliente_ubicacion = p_id_cliente);

  RETURN v_result;
END;
$$;


--
-- Name: dash_clientes_con_deuda(integer, date, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.dash_clientes_con_deuda(p_id_cliente integer DEFAULT NULL::integer, p_fecha_desde date DEFAULT NULL::date, p_fecha_hasta date DEFAULT NULL::date) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_id_tipo_cobrar INT;
  v_result JSON;
BEGIN
  SET TIME ZONE 'America/Lima';

  SELECT glo.id INTO v_id_tipo_cobrar
  FROM gen_lista_opciones glo
  JOIN gen_lista gl ON gl.id = glo.id_lista
  WHERE gl.nombre = 'TipoCuentaFinanciera' AND glo.nombre = 'COBRAR'
  LIMIT 1;

  SELECT json_build_object(
    'cantidad', COUNT(*),
    'detalle', COALESCE(json_agg(cliente_deuda), '[]'::json)
  )
  INTO v_result
  FROM (
    SELECT
      c.id AS "idCliente",
      c.razon_social AS "razonSocial",
      c.nombres,
      c.numero_documento AS "numeroDocumento",
      SUM(fc.monto_saldo) AS "montoTotalDeuda",
      json_agg(
        json_build_object(
          'idCuenta', fc.id,
          'idComprobante', fc.id_comprobante_venta,
          'serie', vc.serie,
          'numero', vc.numero,
          'fechaEmision', fc.fecha_emision,
          'fechaVencimiento', fc.fecha_vencimiento,
          'montoSaldo', fc.monto_saldo,
          'diasRetraso', GREATEST(CURRENT_DATE - fc.fecha_vencimiento, 0),
          'estadoPago', CASE
            WHEN fc.fecha_vencimiento IS NOT NULL AND fc.fecha_vencimiento < CURRENT_DATE THEN 'VENCIDO'
            ELSE 'CORRIENTE'
          END,
          'productos', (
            SELECT COALESCE(json_agg(
              json_build_object(
                'idProducto', p.id,
                'nombre', p.nombre,
                'cantidad', vcd.cantidad,
                'importe', vcd.importe
              )
            ), '[]'::json)
            FROM ven_comprobante_detalle vcd
            JOIN pro_producto p ON p.id = vcd.id_producto
            WHERE vcd.id_comprobante = fc.id_comprobante_venta
              AND vcd.estado = 1
          )
        )
        ORDER BY fc.fecha_vencimiento
      ) AS comprobantes
    FROM fin_cuenta fc
    JOIN cli_clientes c ON c.id = fc.id_tercero
    LEFT JOIN ven_comprobante vc ON vc.id = fc.id_comprobante_venta
    WHERE fc.id_tipo_cuenta = v_id_tipo_cobrar
      AND fc.monto_saldo > 0
      AND fc.estado = 1
      AND (p_id_cliente IS NULL OR c.id = p_id_cliente)
      AND (p_fecha_desde IS NULL OR fc.fecha_emision >= p_fecha_desde)
      AND (p_fecha_hasta IS NULL OR fc.fecha_emision <= p_fecha_hasta)
    GROUP BY c.id, c.razon_social, c.nombres, c.numero_documento
    ORDER BY SUM(fc.monto_saldo) DESC
  ) cliente_deuda;

  RETURN v_result;
END;
$$;


--
-- Name: dash_clientes_mora(integer, date, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.dash_clientes_mora(p_dias_urgente integer DEFAULT 30, p_fecha_desde date DEFAULT NULL::date, p_fecha_hasta date DEFAULT NULL::date) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_id_tipo_cobrar INT;
    v_result         JSON;
BEGIN
    SET TIME ZONE 'America/Lima';

    SELECT glo.id INTO v_id_tipo_cobrar
    FROM gen_lista_opciones glo
    JOIN gen_lista gl ON gl.id = glo.id_lista
    WHERE gl.nombre = 'TipoCuentaFinanciera' AND glo.nombre = 'COBRAR'
    LIMIT 1;

    WITH mora AS (
        SELECT
            c.id AS id_cliente,
            COALESCE(c.razon_social, c.nombres) AS cliente,
            SUM(fc.monto_saldo) AS monto_vencido,
            MAX(CURRENT_DATE - fc.fecha_vencimiento) AS dias_retraso_max
        FROM fin_cuenta fc
        JOIN cli_clientes c ON c.id = fc.id_tercero
        WHERE fc.estado = 1
          AND fc.id_tipo_cuenta = v_id_tipo_cobrar
          AND fc.monto_saldo > 0
          AND fc.fecha_vencimiento IS NOT NULL
          AND fc.fecha_vencimiento < CURRENT_DATE
          AND (p_fecha_desde IS NULL OR fc.fecha_emision >= p_fecha_desde)
          AND (p_fecha_hasta IS NULL OR fc.fecha_emision <= p_fecha_hasta)
        GROUP BY c.id, c.razon_social, c.nombres
    )
    SELECT json_build_object(
        'cantidadDeudoresMora', COUNT(*),
        'cantidadUrgentes', COUNT(*) FILTER (WHERE dias_retraso_max > p_dias_urgente),
        'diasUrgente', p_dias_urgente,
        'detalle', COALESCE(json_agg(
            json_build_object(
                'idCliente', id_cliente,
                'cliente', cliente,
                'montoVencido', monto_vencido,
                'diasRetraso', dias_retraso_max,
                'urgente', dias_retraso_max > p_dias_urgente
            )
            ORDER BY dias_retraso_max DESC
        ), '[]'::json)
    )
    INTO v_result
    FROM mora;

    RETURN v_result;
END;
$$;


--
-- Name: dash_compras_netas(date, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.dash_compras_netas(p_fecha_desde date DEFAULT NULL::date, p_fecha_hasta date DEFAULT NULL::date) RETURNS numeric
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_total NUMERIC(14,2);
BEGIN
    SET TIME ZONE 'America/Lima';

    SELECT COALESCE(SUM(total_importe), 0)
    INTO v_total
    FROM com_comprobante_compra
    WHERE estado = 1
      AND (p_fecha_desde IS NULL OR fecha >= p_fecha_desde)
      AND (p_fecha_hasta IS NULL OR fecha <= p_fecha_hasta);

    RETURN v_total;
END;
$$;


--
-- Name: dash_creditos_otorgados(date, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.dash_creditos_otorgados(p_fecha_desde date DEFAULT NULL::date, p_fecha_hasta date DEFAULT NULL::date) RETURNS numeric
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_id_tipo_cobrar INT;
    v_total          NUMERIC(14,2);
BEGIN
    SET TIME ZONE 'America/Lima';

    SELECT glo.id INTO v_id_tipo_cobrar
    FROM gen_lista_opciones glo
    JOIN gen_lista gl ON gl.id = glo.id_lista
    WHERE gl.nombre = 'TipoCuentaFinanciera' AND glo.nombre = 'COBRAR'
    LIMIT 1;

    SELECT COALESCE(SUM(fc.monto_pendiente), 0)
    INTO v_total
    FROM fin_cuenta fc
    WHERE fc.estado = 1
      AND fc.id_tipo_cuenta = v_id_tipo_cobrar
      AND fc.numero_cuotas_total IS NULL
      AND (p_fecha_desde IS NULL OR fc.fecha_emision >= p_fecha_desde)
      AND (p_fecha_hasta IS NULL OR fc.fecha_emision <= p_fecha_hasta);

    RETURN v_total;
END;
$$;


--
-- Name: dash_demanda_gases(date, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.dash_demanda_gases(p_fecha_desde date DEFAULT NULL::date, p_fecha_hasta date DEFAULT NULL::date) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_result JSON;
BEGIN
    SET TIME ZONE 'America/Lima';

    -- Antes: dos sentencias SELECT separadas reutilizaban el mismo WITH ("detalle_gas"),
    -- pero un CTE solo existe dentro de la sentencia que lo declara; la segunda sentencia
    -- fallaba en tiempo de ejecución con "relation detalle_gas does not exist" y la
    -- función nunca llegó a devolver datos. Se une todo en una sola sentencia.
    WITH detalle_gas AS (
        SELECT
            p.id AS id_producto,
            p.nombre,
            SUM(vcd.cantidad) AS cantidad
        FROM ven_comprobante_detalle vcd
        JOIN ven_comprobante vc ON vc.id = vcd.id_comprobante
        JOIN pro_producto p ON p.id = vcd.id_producto
        WHERE vcd.estado = 1
          AND vc.estado = 1
          AND vc.id_tipo_comprobante IN (102, 104, 192)
          AND COALESCE(p.es_gas, FALSE) = TRUE
          AND (p_fecha_desde IS NULL OR vc.fecha >= p_fecha_desde)
          AND (p_fecha_hasta IS NULL OR vc.fecha <= p_fecha_hasta)
        GROUP BY p.id, p.nombre
    ),
    totales AS (
        SELECT COALESCE(SUM(cantidad), 0) AS total FROM detalle_gas
    )
    SELECT json_build_object(
        'totalCantidad', (SELECT total FROM totales),
        'detalle', COALESCE(json_agg(
            json_build_object(
                'idProducto', d.id_producto,
                'producto', d.nombre,
                'cantidad', d.cantidad,
                'porcentaje', CASE WHEN t.total > 0 THEN ROUND(d.cantidad / t.total * 100, 2) ELSE 0 END
            )
            ORDER BY d.cantidad DESC
        ), '[]'::json)
    )
    INTO v_result
    FROM detalle_gas d
    CROSS JOIN totales t;

    RETURN v_result;
END;
$$;


--
-- Name: dash_deuda_cuentas(character varying, integer, date, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.dash_deuda_cuentas(p_tipo character varying, p_id_cliente integer DEFAULT NULL::integer, p_fecha_desde date DEFAULT NULL::date, p_fecha_hasta date DEFAULT NULL::date) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_id_tipo INT;
    v_res     JSON;
BEGIN
    SET TIME ZONE 'America/Lima';

    SELECT glo.id INTO v_id_tipo
    FROM gen_lista_opciones glo
    JOIN gen_lista gl ON gl.id = glo.id_lista
    WHERE gl.nombre = 'TipoCuentaFinanciera'
      AND glo.nombre = UPPER(p_tipo)
    LIMIT 1;
    WITH c AS (
        SELECT
            COALESCE(fc.id_tercero::text, fc.tercero_nombre) AS tercero_key,
            COALESCE(fc.monto_saldo, fc.monto_pendiente - COALESCE(fc.monto_abonado, 0)) AS saldo,
            COALESCE(fc.monto_abonado, 0) AS abonado,
            fc.fecha_vencimiento
        FROM fin_cuenta fc
        WHERE fc.estado = 1
          AND (v_id_tipo IS NULL OR fc.id_tipo_cuenta = v_id_tipo)
          AND fc.numero_cuotas_total IS NULL
          AND (p_id_cliente IS NULL OR fc.id_tercero = p_id_cliente)
          AND (p_fecha_desde IS NULL OR fc.fecha_emision >= p_fecha_desde)
          AND (p_fecha_hasta IS NULL OR fc.fecha_emision <= p_fecha_hasta)
    )
    SELECT json_build_object(
        'totalPendiente',   COALESCE(SUM(saldo) FILTER (WHERE saldo > 0), 0),
        'cantidadCuentas',  COUNT(*) FILTER (WHERE saldo > 0),
        'totalVencido',     COALESCE(SUM(saldo) FILTER (WHERE saldo > 0 AND fecha_vencimiento IS NOT NULL AND fecha_vencimiento < CURRENT_DATE), 0),
        'cantidadVencidas', COUNT(*) FILTER (WHERE saldo > 0 AND fecha_vencimiento IS NOT NULL AND fecha_vencimiento < CURRENT_DATE),
        'cantidadTerceros', COUNT(DISTINCT tercero_key) FILTER (WHERE saldo > 0),
        'totalCobrado',     COALESCE(SUM(abonado) FILTER (WHERE UPPER(p_tipo) = 'COBRAR'), 0),
        'totalPagado',      COALESCE(SUM(abonado) FILTER (WHERE UPPER(p_tipo) = 'PAGAR'), 0)
    ) INTO v_res
    FROM c;

    RETURN v_res;
END;
$$;


--
-- Name: dash_ganancias_del_dia(date, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.dash_ganancias_del_dia(p_fecha date DEFAULT CURRENT_DATE, p_limite integer DEFAULT 20, p_offset integer DEFAULT 0) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_ganancia_total NUMERIC(12,4) := 0;
    v_total_items BIGINT := 0;
    v_registros JSON;
BEGIN
    SET TIME ZONE 'America/Lima';

    SELECT 
        COALESCE(SUM(vd.importe - (COALESCE(cp.costo_producto, 0) * vd.cantidad)), 0),
        COUNT(*)
    INTO v_ganancia_total, v_total_items
    FROM ven_comprobante_detalle vd
    INNER JOIN ven_comprobante v ON vd.id_comprobante = v.id
    LEFT JOIN pro_catalogo_precio cp ON vd.id_producto = cp.id_producto
    WHERE v.fecha = p_fecha AND v.estado = 1 AND vd.estado = 1;

    SELECT COALESCE(json_agg(row_to_json(t)), '[]'::JSON) INTO v_registros
    FROM (
        SELECT 
            vd.id,
            CONCAT(v.serie, '-', v.numero) AS comprobante,
            p.nombre AS producto,
            vd.cantidad,
            vd.precio_unitario,
            vd.importe AS venta_total,
            COALESCE(cp.costo_producto, 0) AS costo_unitario,
            (COALESCE(cp.costo_producto, 0) * vd.cantidad) AS costo_total,
            (vd.importe - (COALESCE(cp.costo_producto, 0) * vd.cantidad)) AS ganancia_neta
        FROM ven_comprobante_detalle vd
        INNER JOIN ven_comprobante v ON vd.id_comprobante = v.id
        INNER JOIN pro_producto p ON vd.id_producto = p.id
        LEFT JOIN pro_catalogo_precio cp ON vd.id_producto = cp.id_producto
        WHERE v.fecha = p_fecha AND v.estado = 1 AND vd.estado = 1
        ORDER BY ganancia_neta DESC
        LIMIT p_limite OFFSET p_offset
    ) t;

    RETURN json_build_object(
        'gananciaTotal', v_ganancia_total,
        'totalItemsVendidos', v_total_items,
        'registros', v_registros
    );
END;
$$;


--
-- Name: dash_garantias_alquiler(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.dash_garantias_alquiler() RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_id_estado_activo INT;
    v_id_tipo_cobro     INT;
    v_total_en_caja     NUMERIC(14,2);
    v_contratos_activos INT;
    v_por_devolver      NUMERIC(14,2);
    v_ingresado_mes     NUMERIC(14,2);
BEGIN
    SET TIME ZONE 'America/Lima';

    SELECT glo.id INTO v_id_estado_activo
    FROM gen_lista_opciones glo
    JOIN gen_lista gl ON gl.id = glo.id_lista
    WHERE gl.nombre = 'EstadoAlquiler' AND glo.nombre = 'ACTIVO'
    LIMIT 1;

    SELECT glo.id INTO v_id_tipo_cobro
    FROM gen_lista_opciones glo
    JOIN gen_lista gl ON gl.id = glo.id_lista
    WHERE gl.nombre = 'TipoMovimientoGarantia' AND glo.nombre = 'COBRO'
    LIMIT 1;

    -- Total de garantías de alquiler con saldo pendiente de devolución.
    SELECT COALESCE(SUM(g.monto_saldo), 0)
    INTO v_total_en_caja
    FROM ven_garantia g
    WHERE g.estado = 1
      AND g.id_alquiler IS NOT NULL
      AND g.monto_saldo > 0;

    -- Contratos de alquiler vigentes.
    SELECT COUNT(*)
    INTO v_contratos_activos
    FROM bal_alquiler al
    WHERE al.estado = 1
      AND (v_id_estado_activo IS NULL OR al.id_estado = v_id_estado_activo);

    -- Garantías con saldo pendiente cuyo alquiler ya finalizó (hay que devolverlas).
    SELECT COALESCE(SUM(g.monto_saldo), 0)
    INTO v_por_devolver
    FROM ven_garantia g
    JOIN bal_alquiler al ON al.id = g.id_alquiler
    WHERE g.estado = 1
      AND g.monto_saldo > 0
      AND (al.fecha_fin_real IS NOT NULL OR al.fecha_fin_pactada < CURRENT_DATE);

    -- Monto cobrado (ingresado) este mes por garantías de alquiler.
    SELECT COALESCE(SUM(gm.monto), 0)
    INTO v_ingresado_mes
    FROM ven_garantia_movimiento gm
    JOIN ven_garantia g ON g.id = gm.id_garantia
    WHERE gm.estado = 1
      AND g.id_alquiler IS NOT NULL
      AND (v_id_tipo_cobro IS NULL OR gm.id_tipo_movimiento = v_id_tipo_cobro)
      AND DATE_TRUNC('month', gm.fecha) = DATE_TRUNC('month', CURRENT_DATE);

    RETURN json_build_object(
        'totalEnCaja', v_total_en_caja,
        'contratosActivos', v_contratos_activos,
        'porDevolverClientes', v_por_devolver,
        'ingresadoEsteMes', v_ingresado_mes
    );
END;
$$;


--
-- Name: dash_historico_ventas_compras(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.dash_historico_ventas_compras(p_anio integer DEFAULT NULL::integer) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_anio   INT := COALESCE(p_anio, EXTRACT(YEAR FROM CURRENT_DATE)::INT);
    v_result JSON;
BEGIN
    SET TIME ZONE 'America/Lima';

    WITH meses AS (
        SELECT generate_series(1, 12) AS mes
    ),
    ventas AS (
        SELECT EXTRACT(MONTH FROM vc.fecha)::INT AS mes, SUM(vc.total_importe) AS total
        FROM ven_comprobante vc
        WHERE vc.estado = 1
          AND vc.id_tipo_comprobante IN (102, 104, 192)
          AND EXTRACT(YEAR FROM vc.fecha) = v_anio
        GROUP BY 1
    ),
    compras AS (
        SELECT EXTRACT(MONTH FROM cc.fecha)::INT AS mes, SUM(cc.total_importe) AS total
        FROM com_comprobante_compra cc
        WHERE cc.estado = 1
          AND EXTRACT(YEAR FROM cc.fecha) = v_anio
        GROUP BY 1
    )
    SELECT json_build_object(
        'anio', v_anio,
        'meses', json_agg(
            json_build_object(
                'mes', m.mes,
                'nombreMes', TO_CHAR(TO_DATE(m.mes::text, 'MM'), 'Mon'),
                'ventas', COALESCE(v.total, 0),
                'compras', COALESCE(c.total, 0)
            )
            ORDER BY m.mes
        )
    )
    INTO v_result
    FROM meses m
    LEFT JOIN ventas v ON v.mes = m.mes
    LEFT JOIN compras c ON c.mes = m.mes;

    RETURN v_result;
END;
$$;


--
-- Name: dash_inventario_resumen(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.dash_inventario_resumen(p_id_almacen integer DEFAULT NULL::integer) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_valor_total NUMERIC(14,2);
    v_margen_prom NUMERIC(6,2);
BEGIN
    SET TIME ZONE 'America/Lima';

    SELECT COALESCE(SUM(s.stock * p.precio_compra), 0)
    INTO v_valor_total
    FROM pro_stock s
    JOIN pro_producto p ON p.id = s.id_producto
    WHERE s.estado = 1
      AND p.estado = 1
      AND (p_id_almacen IS NULL OR s.id_almacen = p_id_almacen);

    SELECT ROUND(AVG((p.precio - p.precio_compra) / p.precio * 100), 2)
    INTO v_margen_prom
    FROM pro_producto p
    WHERE p.estado = 1
      AND COALESCE(p.es_servicio, FALSE) = FALSE
      AND p.precio > 0;

    RETURN json_build_object(
        'valorTotalInventario', v_valor_total,
        'margenPromedio', COALESCE(v_margen_prom, 0)
    );
END;
$$;


--
-- Name: dash_margen_promedio(integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.dash_margen_promedio(p_limite integer DEFAULT 20, p_offset integer DEFAULT 0) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_margen_promedio NUMERIC(6,2) := 0;
    v_registros JSON;
BEGIN
    SET TIME ZONE 'America/Lima';

    SELECT COALESCE(AVG(
        CASE 
            WHEN cp.porcentaje_margen IS NOT NULL THEN cp.porcentaje_margen
            WHEN cp.costo_producto > 0 THEN ((cp.precio_final - cp.costo_producto) / cp.costo_producto) * 100
            ELSE 0 
        END
    ), 0) INTO v_margen_promedio
    FROM pro_catalogo_precio cp
    WHERE cp.estado = 1 AND (cp.precio_final > 0 OR cp.porcentaje_margen > 0);

    SELECT COALESCE(json_agg(row_to_json(t)), '[]'::JSON) INTO v_registros
    FROM (
        SELECT 
            cp.id,
            cp.nombre_item,
            p.nombre AS producto_vinculado,
            COALESCE(cp.costo_producto, 0) AS costo,
            COALESCE(cp.precio_final, 0) AS precio_venta,
            ROUND(
                COALESCE(
                    cp.porcentaje_margen,
                    CASE WHEN cp.costo_producto > 0 THEN ((cp.precio_final - cp.costo_producto) / cp.costo_producto) * 100 ELSE 0 END
                ), 2
            ) AS porcentaje_margen
        FROM pro_catalogo_precio cp
        LEFT JOIN pro_producto p ON cp.id_producto = p.id
        WHERE cp.estado = 1
        ORDER BY porcentaje_margen DESC
        LIMIT p_limite OFFSET p_offset
    ) t;

    RETURN json_build_object(
        'margenPromedioPorcentaje', ROUND(v_margen_promedio, 2),
        'registros', v_registros
    );
END;
$$;


--
-- Name: dash_monto_mora(date, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.dash_monto_mora(p_fecha date DEFAULT CURRENT_DATE, p_limite integer DEFAULT 20, p_offset integer DEFAULT 0) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_monto_mora_total NUMERIC(12,4) := 0;
    v_total_deudores BIGINT := 0;
    v_id_tipo_cobrar INTEGER;
    v_registros JSON;
BEGIN
    SET TIME ZONE 'America/Lima';

    SELECT id INTO v_id_tipo_cobrar
    FROM gen_lista_opciones
    WHERE LOWER(nombre) LIKE '%cobrar%' OR LOWER(nombre) LIKE '%cliente%'
    LIMIT 1;

    SELECT COALESCE(SUM(monto_saldo), 0), COUNT(*)
    INTO v_monto_mora_total, v_total_deudores
    FROM fin_cuenta
    WHERE estado = 1 
      AND monto_saldo > 0 
      AND fecha_vencimiento < p_fecha
      AND (v_id_tipo_cobrar IS NULL OR id_tipo_cuenta = v_id_tipo_cobrar);

    SELECT COALESCE(json_agg(row_to_json(t)), '[]'::JSON) INTO v_registros
    FROM (
        SELECT 
            fc.id,
            COALESCE(c.razon_social, CONCAT(c.nombres, ' ', c.apellido_paterno)) AS cliente,
            c.telefono,
            CONCAT(vc.serie, '-', vc.numero) AS comprobante,
            fc.fecha_emision,
            fc.fecha_vencimiento,
            (p_fecha - fc.fecha_vencimiento) AS dias_mora,
            fc.monto_pendiente,
            fc.monto_abonado,
            fc.monto_saldo
        FROM fin_cuenta fc
        INNER JOIN cli_clientes c ON fc.id_tercero = c.id
        LEFT JOIN ven_comprobante vc ON fc.id_comprobante_venta = vc.id
        WHERE fc.estado = 1 
          AND fc.monto_saldo > 0 
          AND fc.fecha_vencimiento < p_fecha
          AND (v_id_tipo_cobrar IS NULL OR fc.id_tipo_cuenta = v_id_tipo_cobrar)
        ORDER BY dias_mora DESC, fc.monto_saldo DESC
        LIMIT p_limite OFFSET p_offset
    ) t;

    RETURN json_build_object(
        'montoMoraTotal', v_monto_mora_total,
        'totalDeudores', v_total_deudores,
        'registros', v_registros
    );
END;
$$;


--
-- Name: dash_obtener_solicitudes_baja(integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.dash_obtener_solicitudes_baja(p_limite integer DEFAULT 10, p_offset integer DEFAULT 0) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_total_clientes_pendientes BIGINT := 0;
    v_total_balones_pendientes BIGINT := 0;
    v_total_general BIGINT := 0;
    v_id_pendiente_cliente INTEGER;

    v_lista_balones JSON;
    v_lista_clientes JSON;
BEGIN
    SET TIME ZONE 'America/Lima';

    SELECT id INTO v_id_pendiente_cliente
    FROM gen_lista_opciones
    WHERE LOWER(nombre) = 'pendiente'
    LIMIT 1;

    SELECT COUNT(*) INTO v_total_clientes_pendientes
    FROM cli_baja_cliente
    WHERE estado = 1 
      AND (v_id_pendiente_cliente IS NULL OR id_estado_aprobacion = v_id_pendiente_cliente);

    SELECT COUNT(*) INTO v_total_balones_pendientes
    FROM bal_baja_balon
    WHERE estado = 1 
      AND UPPER(estado_aprobacion) = 'PENDIENTE';

    v_total_general := v_total_clientes_pendientes + v_total_balones_pendientes;

    SELECT COALESCE(json_agg(row_to_json(t)), '[]'::JSON) INTO v_lista_balones
    FROM (
        SELECT
            bb.id,
            bb.id_balon,
            b.codigo_balon AS cilindro,
            COALESCE(m.nombre, bb.motivo_detalle, '—') AS motivo,
            COALESCE(u.nombre, 'Sistema') AS solicitante,
            bb.fecha_baja,
            bb.fecha_creacion::DATE AS fecha_solicitado,
            bb.monto_venta AS monto,
            bb.estado_aprobacion AS estado,
            bb.motivo_detalle
        FROM bal_baja_balon bb
        INNER JOIN bal_balon b ON bb.id_balon = b.id
        LEFT JOIN gen_lista_opciones m ON bb.id_motivo_baja = m.id
        LEFT JOIN auth_usuarios u ON bb.id_usuario_solicita = u.id
        WHERE bb.estado = 1
          AND UPPER(bb.estado_aprobacion) = 'PENDIENTE'
        ORDER BY bb.fecha_creacion DESC
        LIMIT p_limite
        OFFSET p_offset
    ) t;

    SELECT COALESCE(json_agg(row_to_json(t)), '[]'::JSON) INTO v_lista_clientes
    FROM (
        SELECT
            cb.id,
            cb.id_cliente,
            COALESCE(c.razon_social, CONCAT(c.nombres, ' ', c.apellido_paterno)) AS cliente,
            COALESCE(m.nombre, cb.motivo_detalle, '—') AS motivo,
            COALESCE(u.nombre, 'Sistema') AS solicitante,
            cb.fecha_creacion::DATE AS fecha_solicitado,
            COALESCE(est.nombre, 'PENDIENTE') AS estado,
            cb.id_estado_aprobacion,
            cb.motivo_detalle
        FROM cli_baja_cliente cb
        INNER JOIN cli_clientes c ON cb.id_cliente = c.id
        LEFT JOIN gen_lista_opciones m ON cb.id_motivo_baja = m.id
        LEFT JOIN auth_usuarios u ON cb.id_usuario_solicita = u.id
        LEFT JOIN gen_lista_opciones est ON cb.id_estado_aprobacion = est.id
        WHERE cb.estado = 1
          AND (v_id_pendiente_cliente IS NULL OR cb.id_estado_aprobacion = v_id_pendiente_cliente)
        ORDER BY cb.fecha_creacion DESC
        LIMIT p_limite
        OFFSET p_offset
    ) t;

    RETURN json_build_object(
        'resumen', json_build_object(
            'totalGeneral', v_total_general,
            'totalClientesPendientes', v_total_clientes_pendientes,
            'totalBalonesPendientes', v_total_balones_pendientes
        ),
        'balones', json_build_object(
            'registros', v_lista_balones,
            'totalPendientes', v_total_balones_pendientes
        ),
        'clientes', json_build_object(
            'registros', v_lista_clientes,
            'totalPendientes', v_total_clientes_pendientes
        )
    );
END;
$$;


--
-- Name: dash_operaciones_registradas(date, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.dash_operaciones_registradas(p_fecha date DEFAULT CURRENT_DATE, p_limite integer DEFAULT 20, p_offset integer DEFAULT 0) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_cant_recargas BIGINT := 0;
    v_cant_alquileres BIGINT := 0;
    v_cant_mantenimientos BIGINT := 0;
    v_total_movimientos BIGINT := 0;
    v_registros JSON;
BEGIN
    SET TIME ZONE 'America/Lima';

    SELECT COUNT(*) INTO v_cant_recargas FROM bal_movimiento_recarga WHERE fecha_salida_almacen = p_fecha AND estado = 1;
    SELECT COUNT(*) INTO v_cant_alquileres FROM bal_alquiler WHERE fecha_inicio = p_fecha AND estado = 1;
    SELECT COUNT(*) INTO v_cant_mantenimientos FROM bal_mantenimiento WHERE fecha_ingreso = p_fecha AND estado = 1;

    v_total_movimientos := v_cant_recargas + v_cant_alquileres + v_cant_mantenimientos;

    SELECT COALESCE(json_agg(row_to_json(t)), '[]'::JSON) INTO v_registros
    FROM (
        SELECT 'RECARGA' AS tipo_operacion, r.id, r.fecha_salida_almacen AS fecha, 
               COALESCE(c.razon_social, 'Mostrador') AS cliente, p.nombre AS detalle, r.capacidad AS valor
        FROM bal_movimiento_recarga r
        LEFT JOIN cli_clientes c ON r.id_cliente = c.id
        LEFT JOIN pro_producto p ON r.id_producto = p.id
        WHERE r.fecha_salida_almacen = p_fecha AND r.estado = 1

        UNION ALL

        SELECT 'ALQUILER' AS tipo_operacion, a.id, a.fecha_inicio AS fecha, 
               c.razon_social AS cliente, a.numero_alquiler AS detalle, a.total_cobrado AS valor
        FROM bal_alquiler a
        LEFT JOIN cli_clientes c ON a.id_cliente = c.id
        WHERE a.fecha_inicio = p_fecha AND a.estado = 1

        UNION ALL

        SELECT 'MANTENIMIENTO' AS tipo_operacion, m.id, m.fecha_ingreso AS fecha, 
               COALESCE(c.razon_social, 'Taller') AS cliente, m.descripcion AS detalle, m.costo AS valor
        FROM bal_mantenimiento m
        LEFT JOIN cli_clientes c ON m.id_proveedor = c.id
        WHERE m.fecha_ingreso = p_fecha AND m.estado = 1

        ORDER BY fecha DESC
        LIMIT p_limite OFFSET p_offset
    ) t;

    RETURN json_build_object(
        'totalMovimientos', v_total_movimientos,
        'desglose', json_build_object(
            'recargas', v_cant_recargas,
            'alquileres', v_cant_alquileres,
            'mantenimientos', v_cant_mantenimientos
        ),
        'registros', v_registros
    );
END;
$$;


--
-- Name: dash_productos_registrados(character varying, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.dash_productos_registrados(p_busqueda character varying DEFAULT ''::character varying, p_limite integer DEFAULT 20, p_offset integer DEFAULT 0) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_total_activos BIGINT := 0;
    v_registros JSON;
BEGIN
    SET TIME ZONE 'America/Lima';

    SELECT COUNT(*) INTO v_total_activos
    FROM pro_producto
    WHERE estado = 1;

    SELECT COALESCE(json_agg(row_to_json(t)), '[]'::JSON) INTO v_registros
    FROM (
        SELECT 
            p.id,
            p.codigo,
            p.codigo_barra,
            p.nombre AS producto,
            sc.nombre AS subcategoria,
            cat.nombre AS categoria,
            p.marca,
            p.presentacion,
            um.nombre AS unidad_medida,
            p.precio AS precio_venta,
            p.precio_compra,
            p.es_gas,
            p.es_servicio,
            p.es_alquilable,
            p.afecta_stock,
            p.fecha_creacion
        FROM pro_producto p
        LEFT JOIN pro_sub_categoria sc ON p.id_sub_categoria = sc.id
        LEFT JOIN pro_categoria cat ON sc.id_categoria = cat.id
        LEFT JOIN gen_lista_opciones um ON p.id_unidad_medida = um.id
        WHERE p.estado = 1
          AND (
              p_busqueda = ''
              OR LOWER(p.nombre) LIKE LOWER('%' || p_busqueda || '%')
              OR LOWER(p.codigo) LIKE LOWER('%' || p_busqueda || '%')
          )
        ORDER BY p.id DESC
        LIMIT p_limite OFFSET p_offset
    ) t;

    RETURN json_build_object(
        'totalProductosActivos', v_total_activos,
        'registros', v_registros
    );
END;
$$;


--
-- Name: dash_stock_critico(integer, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.dash_stock_critico(p_id_almacen integer DEFAULT NULL::integer, p_limite integer DEFAULT 20, p_offset integer DEFAULT 0) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_total_criticos BIGINT := 0;
    v_registros JSON;
BEGIN
    SET TIME ZONE 'America/Lima';

    SELECT COUNT(*) INTO v_total_criticos
    FROM pro_stock ps
    INNER JOIN pro_producto p ON ps.id_producto = p.id
    WHERE ps.estado = 1 
      AND p.estado = 1
      AND ps.stock <= ps.stock_minimo
      AND (p_id_almacen IS NULL OR ps.id_almacen = p_id_almacen);

    SELECT COALESCE(json_agg(row_to_json(t)), '[]'::JSON) INTO v_registros
    FROM (
        SELECT 
            ps.id AS id_stock,
            ps.id_producto,
            p.codigo AS codigo_producto,
            p.nombre AS producto,
            p.marca,
            p.presentacion,
            sc.nombre AS subcategoria,
            cat.nombre AS categoria,
            a.nombre AS almacen,
            ps.stock AS stock_actual,
            ps.stock_minimo,
            (ps.stock_minimo - ps.stock) AS unidades_faltantes,
            CASE 
                WHEN ps.stock = 0 THEN 'AGOTADO'
                ELSE 'STOCK_CRITICO'
            END AS nivel_alerta,
            um.nombre AS unidad_medida
        FROM pro_stock ps
        INNER JOIN pro_producto p ON ps.id_producto = p.id
        INNER JOIN gen_almacen a ON ps.id_almacen = a.id
        LEFT JOIN pro_sub_categoria sc ON p.id_sub_categoria = sc.id
        LEFT JOIN pro_categoria cat ON sc.id_categoria = cat.id
        LEFT JOIN gen_lista_opciones um ON p.id_unidad_medida = um.id
        WHERE ps.estado = 1 
          AND p.estado = 1
          AND ps.stock <= ps.stock_minimo
          AND (p_id_almacen IS NULL OR ps.id_almacen = p_id_almacen)
        ORDER BY ps.stock ASC, unidades_faltantes DESC
        LIMIT p_limite OFFSET p_offset
    ) t;

    RETURN json_build_object(
        'totalStockCritico', v_total_criticos,
        'registros', v_registros
    );
END;
$$;


--
-- Name: dash_stock_por_categoria(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.dash_stock_por_categoria(p_id_almacen integer DEFAULT NULL::integer) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_result JSON;
BEGIN
    SET TIME ZONE 'America/Lima';

    -- Mismo bug que dash_demanda_gases: dos sentencias separadas reutilizaban el CTE
    -- "valorizado", pero un WITH solo existe dentro de la sentencia que lo declara.
    -- La segunda sentencia fallaba con "relation valorizado does not exist".
    WITH valorizado AS (
        SELECT
            c.id AS id_categoria,
            COALESCE(c.nombre, 'Sin categoría') AS categoria,
            SUM(s.stock * p.precio_compra) AS valor
        FROM pro_stock s
        JOIN pro_producto p ON p.id = s.id_producto
        LEFT JOIN pro_sub_categoria sc ON sc.id = p.id_sub_categoria
        LEFT JOIN pro_categoria c ON c.id = sc.id_categoria
        WHERE s.estado = 1
          AND p.estado = 1
          AND (p_id_almacen IS NULL OR s.id_almacen = p_id_almacen)
        GROUP BY c.id, c.nombre
    ),
    totales AS (
        SELECT COALESCE(SUM(valor), 0) AS valor_total FROM valorizado
    )
    SELECT json_build_object(
        'valorTotal', (SELECT valor_total FROM totales),
        'detalle', COALESCE(json_agg(
            json_build_object(
                'idCategoria', v.id_categoria,
                'categoria', v.categoria,
                'valor', v.valor,
                'porcentaje', CASE WHEN t.valor_total > 0 THEN ROUND(v.valor / t.valor_total * 100, 2) ELSE 0 END
            )
            ORDER BY v.valor DESC
        ), '[]'::json)
    )
    INTO v_result
    FROM valorizado v
    CROSS JOIN totales t;

    RETURN v_result;
END;
$$;


--
-- Name: dash_top_clientes_venta(date, date, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.dash_top_clientes_venta(p_fecha_desde date DEFAULT NULL::date, p_fecha_hasta date DEFAULT NULL::date, p_limite integer DEFAULT 10) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_desde  DATE := COALESCE(p_fecha_desde, DATE_TRUNC('month', CURRENT_DATE)::date);
    v_hasta  DATE := COALESCE(p_fecha_hasta, (DATE_TRUNC('month', CURRENT_DATE) + INTERVAL '1 month - 1 day')::date);
    v_result JSON;
BEGIN
    SET TIME ZONE 'America/Lima';

    SELECT COALESCE(json_agg(t), '[]'::json)
    INTO v_result
    FROM (
        SELECT
            c.id AS "idCliente",
            COALESCE(c.razon_social, c.nombres) AS cliente,
            COUNT(DISTINCT vc.id) AS "cantidadComprobantes",
            SUM(vc.total_importe) AS "totalVenta"
        FROM ven_comprobante vc
        JOIN cli_clientes c ON c.id = vc.id_cliente
        WHERE vc.estado = 1
          AND vc.id_tipo_comprobante IN (102, 104, 192)
          AND vc.fecha >= v_desde
          AND vc.fecha <= v_hasta
        GROUP BY c.id, c.razon_social, c.nombres
        ORDER BY SUM(vc.total_importe) DESC
        LIMIT p_limite
    ) t;

    RETURN json_build_object(
        'fechaDesde', v_desde,
        'fechaHasta', v_hasta,
        'detalle', v_result
    );
END;
$$;


--
-- Name: dash_total_balones(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.dash_total_balones(p_id_cliente integer DEFAULT NULL::integer) RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_total INTEGER;
BEGIN
  SET TIME ZONE 'America/Lima';

  SELECT COUNT(*)::INTEGER
  INTO v_total
  FROM bal_balon
  WHERE estado = 1
    AND (p_id_cliente IS NULL OR id_cliente_ubicacion = p_id_cliente);

  RETURN v_total;
END;
$$;


--
-- Name: dash_total_clientes(integer, date, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.dash_total_clientes(p_id_cliente integer DEFAULT NULL::integer, p_fecha_desde date DEFAULT NULL::date, p_fecha_hasta date DEFAULT NULL::date) RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_total INTEGER;
BEGIN
    SET TIME ZONE 'America/Lima';

    SELECT COUNT(*)::INTEGER
    INTO v_total
    FROM cli_clientes
    WHERE estado = 1
      AND (p_id_cliente IS NULL OR id = p_id_cliente)
      AND (p_fecha_desde IS NULL OR fecha_creacion::date >= p_fecha_desde)
      AND (p_fecha_hasta IS NULL OR fecha_creacion::date <= p_fecha_hasta);

    RETURN v_total;
END;
$$;


--
-- Name: dash_valor_total_inventario(integer, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.dash_valor_total_inventario(p_id_almacen integer DEFAULT NULL::integer, p_limite integer DEFAULT 20, p_offset integer DEFAULT 0) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_valor_total NUMERIC(14,4) := 0;
    v_total_items_stock BIGINT := 0;
    v_registros JSON;
BEGIN
    SET TIME ZONE 'America/Lima';

    SELECT 
        COALESCE(SUM(ps.stock * COALESCE(NULLIF(p.precio_compra, 0), p.precio, 0)), 0),
        COUNT(*)
    INTO v_valor_total, v_total_items_stock
    FROM pro_stock ps
    INNER JOIN pro_producto p ON ps.id_producto = p.id
    WHERE ps.estado = 1 
      AND p.estado = 1 
      AND ps.stock > 0
      AND (p_id_almacen IS NULL OR ps.id_almacen = p_id_almacen);

    SELECT COALESCE(json_agg(row_to_json(t)), '[]'::JSON) INTO v_registros
    FROM (
        SELECT 
            ps.id AS id_stock,
            p.codigo,
            p.nombre AS producto,
            a.nombre AS almacen,
            ps.stock,
            COALESCE(NULLIF(p.precio_compra, 0), p.precio, 0) AS costo_unitario,
            ROUND(ps.stock * COALESCE(NULLIF(p.precio_compra, 0), p.precio, 0), 2) AS valor_total_item
        FROM pro_stock ps
        INNER JOIN pro_producto p ON ps.id_producto = p.id
        INNER JOIN gen_almacen a ON ps.id_almacen = a.id
        WHERE ps.estado = 1 
          AND p.estado = 1 
          AND ps.stock > 0
          AND (p_id_almacen IS NULL OR ps.id_almacen = p_id_almacen)
        ORDER BY valor_total_item DESC
        LIMIT p_limite OFFSET p_offset
    ) t;

    RETURN json_build_object(
        'valorTotalInventario', ROUND(v_valor_total, 2),
        'totalItemsEnStock', v_total_items_stock,
        'registros', v_registros
    );
END;
$$;


--
-- Name: dash_velocidad_salida(date, date, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.dash_velocidad_salida(p_fecha_desde date DEFAULT NULL::date, p_fecha_hasta date DEFAULT NULL::date, p_id_almacen integer DEFAULT NULL::integer, p_limite integer DEFAULT 20) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_result JSON;
BEGIN
    SET TIME ZONE 'America/Lima';

    WITH stock_prod AS (
        SELECT
            s.id_producto,
            SUM(s.stock) AS stock_actual
        FROM pro_stock s
        WHERE s.estado = 1
          AND (p_id_almacen IS NULL OR s.id_almacen = p_id_almacen)
        GROUP BY s.id_producto
    ),
    ventas_prod AS (
        SELECT
            vcd.id_producto,
            SUM(vcd.cantidad) AS cantidad_vendida
        FROM ven_comprobante_detalle vcd
        JOIN ven_comprobante vc ON vc.id = vcd.id_comprobante
        WHERE vcd.estado = 1
          AND vc.estado = 1
          AND vc.id_tipo_comprobante IN (102, 104, 192)
          AND (p_fecha_desde IS NULL OR vc.fecha >= p_fecha_desde)
          AND (p_fecha_hasta IS NULL OR vc.fecha <= p_fecha_hasta)
        GROUP BY vcd.id_producto
    ),
    calculo AS (
        SELECT
            p.id AS id_producto,
            p.nombre AS producto,
            COALESCE(c.nombre, 'Sin categoría') AS categoria,
            COALESCE(sp.stock_actual, 0) AS stock_actual,
            COALESCE(vp.cantidad_vendida, 0) AS cantidad_vendida,
            CASE WHEN COALESCE(sp.stock_actual, 0) > 0
                THEN ROUND(COALESCE(vp.cantidad_vendida, 0) / sp.stock_actual, 2)
                ELSE NULL
            END AS rotacion,
            CASE WHEN p.precio > 0
                THEN ROUND((p.precio - p.precio_compra) / p.precio * 100, 2)
                ELSE NULL
            END AS margen_unitario
        FROM pro_producto p
        LEFT JOIN pro_sub_categoria sc ON sc.id = p.id_sub_categoria
        LEFT JOIN pro_categoria c ON c.id = sc.id_categoria
        LEFT JOIN stock_prod sp ON sp.id_producto = p.id
        LEFT JOIN ventas_prod vp ON vp.id_producto = p.id
        WHERE p.estado = 1
          AND COALESCE(p.es_servicio, FALSE) = FALSE
          AND COALESCE(p.afecta_stock, TRUE) = TRUE
    )
    SELECT COALESCE(json_agg(t), '[]'::json)
    INTO v_result
    FROM (
        SELECT
            id_producto AS "idProducto",
            producto,
            categoria,
            stock_actual AS "stockActual",
            cantidad_vendida AS "cantidadVendida",
            rotacion,
            CASE
                WHEN rotacion IS NULL THEN 'SIN_STOCK'
                WHEN rotacion >= 8 THEN 'MUY_ALTA'
                WHEN rotacion >= 4 THEN 'ALTA'
                WHEN rotacion >= 1.5 THEN 'MEDIA'
                ELSE 'BAJA'
            END AS "nivelRotacion",
            margen_unitario AS "margenUnitario"
        FROM calculo
        ORDER BY rotacion DESC NULLS LAST
        LIMIT p_limite
    ) t;

    RETURN json_build_object('detalle', v_result);
END;
$$;


--
-- Name: dash_venta_gases_comparativo(integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.dash_venta_gases_comparativo(p_anio integer DEFAULT NULL::integer, p_mes integer DEFAULT NULL::integer) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_fecha_ref     DATE;
    v_inicio_actual DATE;
    v_fin_actual    DATE;
    v_inicio_ant    DATE;
    v_fin_ant       DATE;
    v_result        JSON;
BEGIN
    SET TIME ZONE 'America/Lima';

    v_fecha_ref := MAKE_DATE(
        COALESCE(p_anio, EXTRACT(YEAR FROM CURRENT_DATE)::INT),
        COALESCE(p_mes, EXTRACT(MONTH FROM CURRENT_DATE)::INT),
        1
    );

    v_inicio_actual := DATE_TRUNC('month', v_fecha_ref)::date;
    v_fin_actual    := (DATE_TRUNC('month', v_fecha_ref) + INTERVAL '1 month - 1 day')::date;
    v_inicio_ant    := (DATE_TRUNC('month', v_fecha_ref) - INTERVAL '1 month')::date;
    v_fin_ant       := (v_inicio_actual - INTERVAL '1 day')::date;

    WITH ventas_gas AS (
        SELECT
            p.id AS id_producto,
            p.nombre,
            SUM(vcd.cantidad) FILTER (WHERE vc.fecha BETWEEN v_inicio_actual AND v_fin_actual) AS cantidad_actual,
            SUM(vcd.cantidad) FILTER (WHERE vc.fecha BETWEEN v_inicio_ant AND v_fin_ant) AS cantidad_anterior
        FROM ven_comprobante_detalle vcd
        JOIN ven_comprobante vc ON vc.id = vcd.id_comprobante
        JOIN pro_producto p ON p.id = vcd.id_producto
        WHERE vcd.estado = 1
          AND vc.estado = 1
          AND vc.id_tipo_comprobante IN (102, 104, 192)
          AND COALESCE(p.es_gas, FALSE) = TRUE
          AND vc.fecha BETWEEN v_inicio_ant AND v_fin_actual
        GROUP BY p.id, p.nombre
    )
    SELECT json_build_object(
        'mesActual', json_build_object('anio', EXTRACT(YEAR FROM v_inicio_actual), 'mes', EXTRACT(MONTH FROM v_inicio_actual)),
        'mesAnterior', json_build_object('anio', EXTRACT(YEAR FROM v_inicio_ant), 'mes', EXTRACT(MONTH FROM v_inicio_ant)),
        'detalle', COALESCE(json_agg(
            json_build_object(
                'idProducto', id_producto,
                'producto', nombre,
                'cantidadActual', COALESCE(cantidad_actual, 0),
                'cantidadAnterior', COALESCE(cantidad_anterior, 0)
            )
            ORDER BY COALESCE(cantidad_actual, 0) DESC
        ), '[]'::json)
    )
    INTO v_result
    FROM ventas_gas;

    RETURN v_result;
END;
$$;


--
-- Name: dash_ventas_del_dia(date, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.dash_ventas_del_dia(p_fecha date DEFAULT CURRENT_DATE, p_limite integer DEFAULT 20, p_offset integer DEFAULT 0) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_total_monto NUMERIC(12,4) := 0;
    v_total_registros BIGINT := 0;
    v_registros JSON;
BEGIN
    SET TIME ZONE 'America/Lima';

    SELECT COALESCE(SUM(total_importe), 0), COUNT(*)
    INTO v_total_monto, v_total_registros
    FROM ven_comprobante
    WHERE fecha = p_fecha AND estado = 1;

    SELECT COALESCE(json_agg(row_to_json(t)), '[]'::JSON) INTO v_registros
    FROM (
        SELECT 
            v.id,
            CONCAT(v.serie, '-', v.numero) AS comprobante,
            COALESCE(c.razon_social, CONCAT(c.nombres, ' ', c.apellido_paterno)) AS cliente,
            c.numero_documento AS doc_cliente,
            v.sub_total,
            v.igv,
            v.total_importe,
            cp.nombre AS condicion_pago,
            m.nombre AS moneda,
            v.fecha,
            v.fecha_creacion
        FROM ven_comprobante v
        LEFT JOIN cli_clientes c ON v.id_cliente = c.id
        LEFT JOIN gen_condicion_pago cp ON v.id_condicion_pago = cp.id
        LEFT JOIN gen_lista_opciones m ON v.id_moneda = m.id
        WHERE v.fecha = p_fecha AND v.estado = 1
        ORDER BY v.id DESC
        LIMIT p_limite OFFSET p_offset
    ) t;

    RETURN json_build_object(
        'montoTotal', v_total_monto,
        'totalRegistros', v_total_registros,
        'registros', v_registros
    );
END;
$$;


--
-- Name: dash_ventas_netas(date, date, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.dash_ventas_netas(p_fecha_desde date DEFAULT NULL::date, p_fecha_hasta date DEFAULT NULL::date, p_id_cliente integer DEFAULT NULL::integer) RETURNS numeric
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_total NUMERIC(14,2);
BEGIN
    SET TIME ZONE 'America/Lima';

    SELECT COALESCE(SUM(total_importe), 0)
    INTO v_total
    FROM ven_comprobante
    WHERE estado = 1
      AND id_tipo_comprobante IN (102, 104, 192)
      AND (p_fecha_desde IS NULL OR fecha >= p_fecha_desde)
      AND (p_fecha_hasta IS NULL OR fecha <= p_fecha_hasta)
      AND (p_id_cliente IS NULL OR id_cliente = p_id_cliente);

    RETURN v_total;
END;
$$;


--
-- Name: fin_abonar_por_nota_credito(integer, integer, numeric, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fin_abonar_por_nota_credito(p_id_comprobante_origen integer, p_id_nota_credito integer, p_monto numeric, p_id_usuario integer DEFAULT NULL::integer) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_restante NUMERIC(12,2);
    v_aplicar NUMERIC(12,2);
    v_hijo RECORD;
    v_serie VARCHAR;
    v_numero VARCHAR;
BEGIN
    SET TIME ZONE 'America/Lima';

    v_restante := fin_redondear_monto(p_monto);
    IF v_restante IS NULL OR v_restante <= 0 OR p_id_comprobante_origen IS NULL THEN
        RETURN;
    END IF;

    SELECT serie, numero INTO v_serie, v_numero
    FROM ven_comprobante
    WHERE id = p_id_nota_credito;

    FOR v_hijo IN
        SELECT h.id, fin_redondear_monto(COALESCE(h.monto_saldo, 0)) AS saldo
        FROM fin_cuenta h
        WHERE h.estado = 1
          AND fin_redondear_monto(COALESCE(h.monto_saldo, 0)) > 0
          AND (
              (
                  h.id_comprobante_venta = p_id_comprobante_origen
                  AND h.id_cuenta_padre IS NULL
                  AND h.numero_cuotas_total IS NULL
              )
              OR h.id_cuenta_padre IN (
                  SELECT fc.id
                  FROM fin_cuenta fc
                  WHERE fc.id_comprobante_venta = p_id_comprobante_origen
                    AND fc.estado = 1
                    AND fc.id_cuenta_padre IS NULL
              )
          )
        ORDER BY COALESCE(h.numero_cuota, 0), h.fecha_vencimiento, h.id
    LOOP
        EXIT WHEN v_restante <= 0;
        IF v_hijo.saldo <= 0 THEN
            CONTINUE;
        END IF;

        v_aplicar := LEAST(v_restante, v_hijo.saldo);

        INSERT INTO fin_pago (
            id_cuenta, fecha_pago, monto, referencia, observacion, id_sucursal, id_usuario_creacion
        ) VALUES (
            v_hijo.id,
            CURRENT_DATE,
            v_aplicar,
            format('NC %s-%s', COALESCE(v_serie, ''), COALESCE(v_numero, '')),
            format('Abono automático por nota de crédito #%s', p_id_nota_credito),
            fin_sucursal_de_cuenta(v_hijo.id),
            p_id_usuario
        );

        UPDATE fin_cuenta
        SET monto_abonado = fin_redondear_monto(COALESCE(monto_abonado, 0) + v_aplicar),
            monto_saldo = fin_redondear_monto(GREATEST(monto_saldo - v_aplicar, 0)),
            id_usuario_modificacion = p_id_usuario,
            fecha_modificacion = NOW()
        WHERE id = v_hijo.id;

        IF (SELECT id_cuenta_padre FROM fin_cuenta WHERE id = v_hijo.id) IS NOT NULL THEN
            PERFORM fin_refrescar_cabecera_plan(
                (SELECT id_cuenta_padre FROM fin_cuenta WHERE id = v_hijo.id)
            );
        END IF;

        v_restante := fin_redondear_monto(v_restante - v_aplicar);
    END LOOP;
END;
$$;


--
-- Name: fin_abrir_caja_sesion(date, numeric, integer, character varying, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fin_abrir_caja_sesion(p_fecha date, p_monto_inicial numeric, p_id_sucursal integer DEFAULT NULL::integer, p_observacion character varying DEFAULT NULL::character varying, p_id_usuario integer DEFAULT NULL::integer) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_estado_abierta INT;
    v_existente RECORD;
    v_abierta RECORD;
    v_id INT;
    v_registro JSON;
    v_hora_txt TEXT;
BEGIN
    SET TIME ZONE 'America/Lima';

    SELECT lo.id INTO v_estado_abierta
    FROM gen_lista_opciones lo
    INNER JOIN gen_lista l ON l.id = lo.id_lista
    WHERE l.nombre = 'EstadoCaja' AND lo.nombre = 'ABIERTA'
    LIMIT 1;

    IF v_estado_abierta IS NULL THEN
        RETURN json_build_object('error', 'No existe estado de caja ABIERTA', 'registro', NULL);
    END IF;

    IF p_fecha IS NULL THEN
        RETURN json_build_object('error', 'La fecha es obligatoria', 'registro', NULL);
    END IF;

    IF COALESCE(p_monto_inicial, 0) < 0 THEN
        RETURN json_build_object('error', 'El monto inicial no puede ser negativo', 'registro', NULL);
    END IF;

    -- Una sola sesión por fecha + sucursal (abierta o cerrada).
    SELECT s.* INTO v_existente
    FROM fin_caja_sesion s
    WHERE s.estado = 1
      AND s.fecha = p_fecha
      AND COALESCE(s.id_sucursal, 0) = COALESCE(p_id_sucursal, 0)
    LIMIT 1;

    IF FOUND THEN
        v_hora_txt := to_char(v_existente.fecha_apertura AT TIME ZONE 'America/Lima', 'DD/MM/YYYY HH24:MI');
        RETURN json_build_object(
            'error', format(
                'Ya existe una sesión de caja para esa fecha (abierta el %s). No se puede repetir la misma fecha.',
                COALESCE(v_hora_txt, to_char(p_fecha, 'DD/MM/YYYY'))
            ),
            'registro', NULL
        );
    END IF;

    -- No abrir otra si ya hay una caja ABIERTA en la misma sucursal (otra fecha).
    SELECT s.* INTO v_abierta
    FROM fin_caja_sesion s
    WHERE s.estado = 1
      AND s.id_estado = v_estado_abierta
      AND COALESCE(s.id_sucursal, 0) = COALESCE(p_id_sucursal, 0)
    LIMIT 1;

    IF FOUND THEN
        v_hora_txt := to_char(v_abierta.fecha_apertura AT TIME ZONE 'America/Lima', 'DD/MM/YYYY HH24:MI');
        RETURN json_build_object(
            'error', format(
                'Ya hay una caja ABIERTA del %s (apertura %s). Ciérrala antes de abrir otra.',
                to_char(v_abierta.fecha, 'DD/MM/YYYY'),
                COALESCE(v_hora_txt, '—')
            ),
            'registro', NULL
        );
    END IF;

    BEGIN
        INSERT INTO fin_caja_sesion (
            fecha, id_sucursal, id_estado, monto_inicial,
            observacion_apertura, fecha_apertura, id_usuario_apertura,
            id_usuario_creacion
        ) VALUES (
            p_fecha, p_id_sucursal, v_estado_abierta, COALESCE(p_monto_inicial, 0),
            NULLIF(TRIM(p_observacion), ''), NOW(), p_id_usuario,
            p_id_usuario
        )
        RETURNING id INTO v_id;
    EXCEPTION
        WHEN unique_violation THEN
            RETURN json_build_object(
                'error', 'Ya existe una sesión de caja para esa fecha / sucursal. No se puede repetir.',
                'registro', NULL
            );
    END;

    SELECT row_to_json(t) INTO v_registro
    FROM (
        SELECT
            s.id,
            s.fecha,
            s.id_sucursal AS "idSucursal",
            suc.nombre AS "nombreSucursal",
            s.id_estado AS "idEstado",
            est.nombre AS "estadoCaja",
            s.monto_inicial AS "montoInicial",
            s.monto_efectivo_contado AS "montoEfectivoContado",
            s.monto_esperado AS "montoEsperado",
            s.diferencia,
            s.observacion_apertura AS "observacionApertura",
            s.observacion_cierre AS "observacionCierre",
            s.fecha_apertura AS "fechaApertura",
            s.fecha_cierre AS "fechaCierre",
            s.id_usuario_apertura AS "idUsuarioApertura",
            s.id_usuario_cierre AS "idUsuarioCierre"
        FROM fin_caja_sesion s
        LEFT JOIN gen_sucursal suc ON suc.id = s.id_sucursal
        LEFT JOIN gen_lista_opciones est ON est.id = s.id_estado
        WHERE s.id = v_id
    ) t;

    RETURN json_build_object('registro', v_registro);
END;
$$;


--
-- Name: fin_abrir_caja_sesion(date, numeric, integer, character varying, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fin_abrir_caja_sesion(p_fecha date, p_monto_inicial numeric, p_id_sucursal integer DEFAULT NULL::integer, p_observacion character varying DEFAULT NULL::character varying, p_id_usuario integer DEFAULT NULL::integer, p_id_sesion integer DEFAULT NULL::integer) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_estado_abierta INT;
    v_estado_cerrada INT;
    v_existente RECORD;
    v_abierta RECORD;
    v_id INT;
    v_registro JSON;
    v_hora_txt TEXT;
BEGIN
    SET TIME ZONE 'America/Lima';

    SELECT lo.id INTO v_estado_abierta
    FROM gen_lista_opciones lo
    INNER JOIN gen_lista l ON l.id = lo.id_lista
    WHERE l.nombre = 'EstadoCaja' AND lo.nombre = 'ABIERTA'
    LIMIT 1;

    SELECT lo.id INTO v_estado_cerrada
    FROM gen_lista_opciones lo
    INNER JOIN gen_lista l ON l.id = lo.id_lista
    WHERE l.nombre = 'EstadoCaja' AND lo.nombre = 'CERRADA'
    LIMIT 1;

    IF v_estado_abierta IS NULL THEN
        RETURN json_build_object('error', 'No existe estado de caja ABIERTA', 'registro', NULL);
    END IF;

    IF p_fecha IS NULL THEN
        RETURN json_build_object('error', 'La fecha es obligatoria', 'registro', NULL);
    END IF;

    IF COALESCE(p_monto_inicial, 0) < 0 THEN
        RETURN json_build_object('error', 'El monto inicial no puede ser negativo', 'registro', NULL);
    END IF;

    -- Reapertura explícita por ID (flujo "Reabrir caja" del frontend).
    IF p_id_sesion IS NOT NULL THEN
        SELECT s.* INTO v_existente
        FROM fin_caja_sesion s
        WHERE s.id = p_id_sesion
          AND s.estado = 1
        LIMIT 1;

        IF NOT FOUND THEN
            RETURN json_build_object('error', 'Sesión de caja no encontrada', 'registro', NULL);
        END IF;

        IF v_existente.id_estado = v_estado_abierta THEN
            v_hora_txt := to_char(
                v_existente.fecha_apertura AT TIME ZONE 'America/Lima',
                'DD/MM/YYYY HH24:MI'
            );
            RETURN json_build_object(
                'error', format(
                    'La caja del %s ya está ABIERTA (desde %s).',
                    to_char(v_existente.fecha, 'DD/MM/YYYY'),
                    COALESCE(v_hora_txt, '—')
                ),
                'registro', NULL
            );
        END IF;

        -- Otra caja abierta en la misma sucursal (fecha distinta).
        SELECT s.* INTO v_abierta
        FROM fin_caja_sesion s
        WHERE s.estado = 1
          AND s.id_estado = v_estado_abierta
          AND s.id <> v_existente.id
          AND COALESCE(s.id_sucursal, 0) = COALESCE(v_existente.id_sucursal, 0)
        LIMIT 1;

        IF FOUND THEN
            v_hora_txt := to_char(
                v_abierta.fecha_apertura AT TIME ZONE 'America/Lima',
                'DD/MM/YYYY HH24:MI'
            );
            RETURN json_build_object(
                'error', format(
                    'Ya hay otra caja ABIERTA del %s (apertura %s). Ciérrala antes de reabrir.',
                    to_char(v_abierta.fecha, 'DD/MM/YYYY'),
                    COALESCE(v_hora_txt, '—')
                ),
                'registro', NULL
            );
        END IF;

        UPDATE fin_caja_sesion
        SET id_estado = v_estado_abierta,
            fecha_apertura = NOW(),
            id_usuario_apertura = p_id_usuario,
            observacion_apertura = NULLIF(TRIM(p_observacion), ''),
            monto_inicial = ROUND(COALESCE(p_monto_inicial, 0), 2),
            fecha_cierre = NULL,
            id_usuario_cierre = NULL,
            monto_efectivo_contado = NULL,
            monto_esperado = NULL,
            diferencia = NULL,
            observacion_cierre = NULL,
            id_usuario_modificacion = p_id_usuario,
            fecha_modificacion = NOW()
        WHERE id = v_existente.id
        RETURNING id INTO v_id;

        SELECT row_to_json(t) INTO v_registro
        FROM (
            SELECT
                s.id,
                s.fecha,
                s.id_sucursal AS "idSucursal",
                suc.nombre AS "nombreSucursal",
                s.id_estado AS "idEstado",
                est.nombre AS "estadoCaja",
                s.monto_inicial AS "montoInicial",
                s.monto_efectivo_contado AS "montoEfectivoContado",
                s.monto_esperado AS "montoEsperado",
                s.diferencia,
                s.observacion_apertura AS "observacionApertura",
                s.observacion_cierre AS "observacionCierre",
                s.fecha_apertura AS "fechaApertura",
                s.fecha_cierre AS "fechaCierre",
                s.id_usuario_apertura AS "idUsuarioApertura",
                s.id_usuario_cierre AS "idUsuarioCierre"
            FROM fin_caja_sesion s
            LEFT JOIN gen_sucursal suc ON suc.id = s.id_sucursal
            LEFT JOIN gen_lista_opciones est ON est.id = s.id_estado
            WHERE s.id = v_id
        ) t;

        RETURN json_build_object('registro', v_registro);
    END IF;

    -- Una sola sesión por fecha + sucursal (apertura nueva o reapertura por fecha).
    SELECT s.* INTO v_existente
    FROM fin_caja_sesion s
    WHERE s.estado = 1
      AND s.fecha = p_fecha
      AND COALESCE(s.id_sucursal, 0) = COALESCE(p_id_sucursal, 0)
    LIMIT 1;

    IF FOUND THEN
        IF v_existente.id_estado = v_estado_abierta THEN
            v_hora_txt := to_char(
                v_existente.fecha_apertura AT TIME ZONE 'America/Lima',
                'DD/MM/YYYY HH24:MI'
            );
            RETURN json_build_object(
                'error', format(
                    'Ya hay una caja ABIERTA del %s (apertura %s). Ciérrala antes de abrir otra.',
                    to_char(v_existente.fecha, 'DD/MM/YYYY'),
                    COALESCE(v_hora_txt, '—')
                ),
                'registro', NULL
            );
        END IF;

        SELECT s.* INTO v_abierta
        FROM fin_caja_sesion s
        WHERE s.estado = 1
          AND s.id_estado = v_estado_abierta
          AND s.id <> v_existente.id
          AND COALESCE(s.id_sucursal, 0) = COALESCE(p_id_sucursal, 0)
        LIMIT 1;

        IF FOUND THEN
            v_hora_txt := to_char(
                v_abierta.fecha_apertura AT TIME ZONE 'America/Lima',
                'DD/MM/YYYY HH24:MI'
            );
            RETURN json_build_object(
                'error', format(
                    'Ya hay otra caja ABIERTA del %s (apertura %s). Ciérrala antes de reabrir.',
                    to_char(v_abierta.fecha, 'DD/MM/YYYY'),
                    COALESCE(v_hora_txt, '—')
                ),
                'registro', NULL
            );
        END IF;

        UPDATE fin_caja_sesion
        SET id_estado = v_estado_abierta,
            fecha_apertura = NOW(),
            id_usuario_apertura = p_id_usuario,
            observacion_apertura = NULLIF(TRIM(p_observacion), ''),
            monto_inicial = ROUND(COALESCE(p_monto_inicial, 0), 2),
            fecha_cierre = NULL,
            id_usuario_cierre = NULL,
            monto_efectivo_contado = NULL,
            monto_esperado = NULL,
            diferencia = NULL,
            observacion_cierre = NULL,
            id_usuario_modificacion = p_id_usuario,
            fecha_modificacion = NOW()
        WHERE id = v_existente.id
        RETURNING id INTO v_id;
    ELSE
        SELECT s.* INTO v_abierta
        FROM fin_caja_sesion s
        WHERE s.estado = 1
          AND s.id_estado = v_estado_abierta
          AND COALESCE(s.id_sucursal, 0) = COALESCE(p_id_sucursal, 0)
        LIMIT 1;

        IF FOUND THEN
            v_hora_txt := to_char(
                v_abierta.fecha_apertura AT TIME ZONE 'America/Lima',
                'DD/MM/YYYY HH24:MI'
            );
            RETURN json_build_object(
                'error', format(
                    'Ya hay una caja ABIERTA del %s (apertura %s). Ciérrala antes de abrir otra.',
                    to_char(v_abierta.fecha, 'DD/MM/YYYY'),
                    COALESCE(v_hora_txt, '—')
                ),
                'registro', NULL
            );
        END IF;

        BEGIN
            INSERT INTO fin_caja_sesion (
                fecha, id_sucursal, id_estado, monto_inicial,
                observacion_apertura, fecha_apertura, id_usuario_apertura,
                id_usuario_creacion
            ) VALUES (
                p_fecha, p_id_sucursal, v_estado_abierta, ROUND(COALESCE(p_monto_inicial, 0), 2),
                NULLIF(TRIM(p_observacion), ''), NOW(), p_id_usuario,
                p_id_usuario
            )
            RETURNING id INTO v_id;
        EXCEPTION
            WHEN unique_violation THEN
                -- Fallback: fila CERRADA existente → reabrir en lugar de fallar.
                SELECT s.* INTO v_existente
                FROM fin_caja_sesion s
                WHERE s.estado = 1
                  AND s.fecha = p_fecha
                  AND COALESCE(s.id_sucursal, 0) = COALESCE(p_id_sucursal, 0)
                LIMIT 1;

                IF FOUND AND v_existente.id_estado IS DISTINCT FROM v_estado_abierta THEN
                    UPDATE fin_caja_sesion
                    SET id_estado = v_estado_abierta,
                        fecha_apertura = NOW(),
                        id_usuario_apertura = p_id_usuario,
                        observacion_apertura = NULLIF(TRIM(p_observacion), ''),
                        monto_inicial = ROUND(COALESCE(p_monto_inicial, 0), 2),
                        fecha_cierre = NULL,
                        id_usuario_cierre = NULL,
                        monto_efectivo_contado = NULL,
                        monto_esperado = NULL,
                        diferencia = NULL,
                        observacion_cierre = NULL,
                        id_usuario_modificacion = p_id_usuario,
                        fecha_modificacion = NOW()
                    WHERE id = v_existente.id
                    RETURNING id INTO v_id;
                ELSE
                    RETURN json_build_object(
                        'error', 'Ya existe una sesión de caja para esa fecha y sucursal.',
                        'registro', NULL
                    );
                END IF;
        END;
    END IF;

    SELECT row_to_json(t) INTO v_registro
    FROM (
        SELECT
            s.id,
            s.fecha,
            s.id_sucursal AS "idSucursal",
            suc.nombre AS "nombreSucursal",
            s.id_estado AS "idEstado",
            est.nombre AS "estadoCaja",
            s.monto_inicial AS "montoInicial",
            s.monto_efectivo_contado AS "montoEfectivoContado",
            s.monto_esperado AS "montoEsperado",
            s.diferencia,
            s.observacion_apertura AS "observacionApertura",
            s.observacion_cierre AS "observacionCierre",
            s.fecha_apertura AS "fechaApertura",
            s.fecha_cierre AS "fechaCierre",
            s.id_usuario_apertura AS "idUsuarioApertura",
            s.id_usuario_cierre AS "idUsuarioCierre"
        FROM fin_caja_sesion s
        LEFT JOIN gen_sucursal suc ON suc.id = s.id_sucursal
        LEFT JOIN gen_lista_opciones est ON est.id = s.id_estado
        WHERE s.id = v_id
    ) t;

    RETURN json_build_object('registro', v_registro);
END;
$$;


--
-- Name: fin_actualizar_cuenta(integer, character varying, integer, character varying, date, date, numeric, character varying, character varying, character varying, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fin_actualizar_cuenta(p_id integer, p_tipo character varying DEFAULT NULL::character varying, p_id_tercero integer DEFAULT NULL::integer, p_tercero_nombre character varying DEFAULT NULL::character varying, p_fecha_emision date DEFAULT NULL::date, p_fecha_vencimiento date DEFAULT NULL::date, p_monto numeric DEFAULT NULL::numeric, p_descripcion character varying DEFAULT NULL::character varying, p_observacion character varying DEFAULT NULL::character varying, p_numero_comprobante character varying DEFAULT NULL::character varying, p_id_usuario integer DEFAULT NULL::integer) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_cuenta        fin_cuenta%ROWTYPE;
    v_id_tipo       INT;
    v_tiene_pagos   BOOLEAN;
    v_es_plan       BOOLEAN;
    v_nuevo_tercero INT;
    v_registro      JSON;
BEGIN
    SET TIME ZONE 'America/Lima';

    SELECT * INTO v_cuenta FROM fin_cuenta WHERE id = p_id AND estado = 1;
    IF NOT FOUND THEN
        RETURN json_build_object('registro', NULL, 'error', 'La cuenta no existe o está inactiva');
    END IF;

    -- No permitir editar cuotas hijas directamente
    IF v_cuenta.id_cuenta_padre IS NOT NULL THEN
        RETURN json_build_object('registro', NULL, 'error',
            'No se puede editar una cuota individual; edita la cuenta padre del plan');
    END IF;

    -- Validación opcional del tipo
    IF p_tipo IS NOT NULL THEN
        SELECT glo.id INTO v_id_tipo
        FROM gen_lista_opciones glo
        JOIN gen_lista gl ON gl.id = glo.id_lista
        WHERE gl.nombre = 'TipoCuentaFinanciera' AND glo.nombre = UPPER(p_tipo)
        LIMIT 1;
        IF v_id_tipo IS NOT NULL AND v_cuenta.id_tipo_cuenta <> v_id_tipo THEN
            RETURN json_build_object('registro', NULL, 'error', 'La cuenta no corresponde al tipo indicado');
        END IF;
    END IF;

    v_es_plan := (v_cuenta.numero_cuotas_total IS NOT NULL);

    SELECT EXISTS(
        SELECT 1 FROM fin_pago WHERE id_cuenta = p_id AND estado = 1
    ) INTO v_tiene_pagos;

    -- Si hay pagos y quieren cambiar campos "financieros" (tercero/monto/fecha_emision), rechazar
    IF v_tiene_pagos AND (
        p_id_tercero IS NOT NULL
        OR (p_tercero_nombre IS NOT NULL AND p_tercero_nombre <> '')
        OR p_fecha_emision IS NOT NULL
        OR p_monto IS NOT NULL
    ) THEN
        RETURN json_build_object('registro', NULL, 'error',
            'Esta cuenta ya tiene pagos: solo puedes editar descripción, observación, comprobante y fecha de vencimiento');
    END IF;

    IF v_es_plan AND (
        p_id_tercero IS NOT NULL
        OR (p_tercero_nombre IS NOT NULL AND p_tercero_nombre <> '')
        OR p_fecha_emision IS NOT NULL
        OR p_monto IS NOT NULL
        OR p_fecha_vencimiento IS NOT NULL
    ) THEN
        RETURN json_build_object('registro', NULL, 'error',
            'Esta cuenta es un plan de cuotas: solo puedes editar descripción, observación y comprobante');
    END IF;

    -- Validaciones de valores
    IF p_id_tercero IS NOT NULL THEN
        SELECT id INTO v_nuevo_tercero FROM cli_clientes WHERE id = p_id_tercero AND estado = 1;
        IF v_nuevo_tercero IS NULL THEN
            RETURN json_build_object('registro', NULL, 'error', 'El tercero no existe o está inactivo');
        END IF;
    END IF;

    IF p_monto IS NOT NULL AND p_monto <= 0 THEN
        RETURN json_build_object('registro', NULL, 'error', 'El monto debe ser mayor a cero');
    END IF;

    IF p_fecha_vencimiento IS NOT NULL
       AND COALESCE(p_fecha_emision, v_cuenta.fecha_emision) IS NOT NULL
       AND p_fecha_vencimiento < COALESCE(p_fecha_emision, v_cuenta.fecha_emision) THEN
        RETURN json_build_object('registro', NULL, 'error',
            'La fecha de vencimiento no puede ser anterior a la emisión');
    END IF;

    -- Actualización dinámica: solo cambia lo que llega no-null
    UPDATE fin_cuenta SET
        id_tercero          = COALESCE(p_id_tercero, id_tercero),
        tercero_nombre      = CASE
            WHEN p_tercero_nombre IS NULL THEN tercero_nombre
            WHEN TRIM(p_tercero_nombre) = '' THEN NULL
            ELSE TRIM(p_tercero_nombre)
        END,
        fecha_emision       = COALESCE(p_fecha_emision, fecha_emision),
        fecha_vencimiento   = COALESCE(p_fecha_vencimiento, fecha_vencimiento),
        monto_pendiente     = COALESCE(p_monto, monto_pendiente),
        monto_saldo         = CASE
            WHEN p_monto IS NOT NULL THEN p_monto - COALESCE(monto_abonado, 0)
            ELSE monto_saldo
        END,
        descripcion         = CASE
            WHEN p_descripcion IS NULL THEN descripcion
            WHEN TRIM(p_descripcion) = '' THEN NULL
            ELSE TRIM(p_descripcion)
        END,
        observacion         = CASE
            WHEN p_observacion IS NULL THEN observacion
            WHEN TRIM(p_observacion) = '' THEN NULL
            ELSE TRIM(p_observacion)
        END,
        numero_comprobante  = CASE
            WHEN p_numero_comprobante IS NULL THEN numero_comprobante
            WHEN TRIM(p_numero_comprobante) = '' THEN NULL
            ELSE TRIM(p_numero_comprobante)
        END,
        id_usuario_modificacion = p_id_usuario,
        fecha_modificacion  = NOW()
    WHERE id = p_id;

    -- Validar que quede tercero (uno de los dos)
    SELECT * INTO v_cuenta FROM fin_cuenta WHERE id = p_id;
    IF v_cuenta.id_tercero IS NULL AND (v_cuenta.tercero_nombre IS NULL OR TRIM(v_cuenta.tercero_nombre) = '') THEN
        RETURN json_build_object('registro', NULL, 'error',
            'Debe quedar al menos un tercero (id o nombre libre)');
    END IF;

    -- Devolver el registro actualizado
    SELECT row_to_json(t) INTO v_registro
    FROM (
        SELECT
            fc.id, fc.id_tipo_cuenta, tcu.nombre AS tipo,
            fc.id_tercero, fc.tercero_nombre,
            COALESCE(
                NULLIF(TRIM(ter.razon_social), ''),
                NULLIF(TRIM(CONCAT_WS(' ', ter.nombres, ter.apellido_paterno, ter.apellido_materno)), ''),
                fc.tercero_nombre,
                'Tercero #' || fc.id
            ) AS tercero,
            ter.numero_documento AS documento_tercero,
            fc.descripcion, fc.numero_comprobante,
            fc.fecha_emision, fc.fecha_vencimiento,
            fc.monto_pendiente, fc.monto_abonado, fc.monto_saldo AS saldo,
            fc.observacion
        FROM fin_cuenta fc
        JOIN gen_lista_opciones tcu ON tcu.id = fc.id_tipo_cuenta
        LEFT JOIN cli_clientes ter ON ter.id = fc.id_tercero
        WHERE fc.id = p_id
    ) t;

    RETURN json_build_object('registro', v_registro);
END;
$$;


--
-- Name: fin_actualizar_garantia(integer, date, integer, integer, numeric, character varying, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fin_actualizar_garantia(p_id integer, p_fecha date DEFAULT NULL::date, p_id_cliente integer DEFAULT NULL::integer, p_id_medio_pago integer DEFAULT NULL::integer, p_importe numeric DEFAULT NULL::numeric, p_observacion character varying DEFAULT NULL::character varying, p_id_usuario integer DEFAULT NULL::integer) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_garantia   fin_garantia%ROWTYPE;
    v_id_cliente INT;
    v_registro   JSON;
BEGIN
    SET TIME ZONE 'America/Lima';

    SELECT * INTO v_garantia FROM fin_garantia WHERE id = p_id AND estado = 1;
    IF NOT FOUND THEN
        RETURN json_build_object('registro', NULL, 'error', 'La garantía no existe o está inactiva');
    END IF;

    -- No permitir editar datos si ya fue reembolsada
    IF v_garantia.fecha_reembolso IS NOT NULL THEN
        RETURN json_build_object('registro', NULL, 'error',
            'Esta garantía ya fue reembolsada. Anula el reembolso primero para editarla.');
    END IF;

    IF p_id_cliente IS NOT NULL THEN
        SELECT id INTO v_id_cliente FROM cli_clientes WHERE id = p_id_cliente AND estado = 1;
        IF v_id_cliente IS NULL THEN
            RETURN json_build_object('registro', NULL, 'error', 'El cliente no existe o está inactivo');
        END IF;
    END IF;

    IF p_importe IS NOT NULL AND p_importe <= 0 THEN
        RETURN json_build_object('registro', NULL, 'error', 'El importe debe ser mayor a cero');
    END IF;

    UPDATE fin_garantia SET
        fecha         = COALESCE(p_fecha, fecha),
        id_cliente    = COALESCE(p_id_cliente, id_cliente),
        id_medio_pago = COALESCE(p_id_medio_pago, id_medio_pago),
        importe       = COALESCE(p_importe, importe),
        observacion   = CASE
            WHEN p_observacion IS NULL THEN observacion
            WHEN TRIM(p_observacion) = '' THEN NULL
            ELSE TRIM(p_observacion)
        END,
        id_usuario_modificacion = p_id_usuario,
        fecha_modificacion = NOW()
    WHERE id = p_id;

    SELECT row_to_json(t) INTO v_registro FROM (
        SELECT
            g.id, g.fecha,
            g.id_cliente,
            COALESCE(NULLIF(TRIM(c.razon_social), ''),
                     NULLIF(TRIM(CONCAT_WS(' ', c.nombres, c.apellido_paterno, c.apellido_materno)), ''),
                     'Cliente #' || g.id_cliente) AS cliente,
            c.numero_documento AS documento_cliente,
            g.id_medio_pago, mp.nombre AS medio_pago,
            g.importe, g.observacion,
            g.fecha_reembolso,
            g.id_medio_reembolso, mr.nombre AS medio_reembolso,
            g.observacion_reembolso,
            g.id_estado, est.nombre AS estado_texto
        FROM fin_garantia g
        JOIN cli_clientes c ON c.id = g.id_cliente
        LEFT JOIN gen_lista_opciones mp  ON mp.id = g.id_medio_pago
        LEFT JOIN gen_lista_opciones mr  ON mr.id = g.id_medio_reembolso
        LEFT JOIN gen_lista_opciones est ON est.id = g.id_estado
        WHERE g.id = p_id
    ) t;

    RETURN json_build_object('registro', v_registro);
END;
$$;


--
-- Name: fin_anular_pago(integer, character varying, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fin_anular_pago(p_id_pago integer, p_tipo character varying DEFAULT NULL::character varying, p_id_usuario integer DEFAULT NULL::integer) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_id_tipo INT;
    v_pago    fin_pago%ROWTYPE;
    v_cuenta  fin_cuenta%ROWTYPE;
    v_err_caja TEXT;
    v_id_sucursal INT;
BEGIN
    SET TIME ZONE 'America/Lima';

    SELECT * INTO v_pago FROM fin_pago WHERE id = p_id_pago AND estado = 1;
    IF NOT FOUND THEN
        RETURN json_build_object('eliminado', false, 'id', p_id_pago, 'error', 'El pago no existe o ya fue anulado');
    END IF;

    v_id_sucursal := COALESCE(v_pago.id_sucursal, fin_sucursal_de_cuenta(v_pago.id_cuenta));
    v_err_caja := fin_caja_assert_abierta(v_pago.fecha_pago, v_id_sucursal);
    IF v_err_caja IS NOT NULL THEN
        RETURN json_build_object('eliminado', false, 'id', p_id_pago, 'error', v_err_caja);
    END IF;

    SELECT * INTO v_cuenta FROM fin_cuenta WHERE id = v_pago.id_cuenta;

    IF p_tipo IS NOT NULL THEN
        SELECT glo.id INTO v_id_tipo
        FROM gen_lista_opciones glo
        JOIN gen_lista gl ON gl.id = glo.id_lista
        WHERE gl.nombre = 'TipoCuentaFinanciera'
          AND glo.nombre = UPPER(p_tipo)
        LIMIT 1;

        IF v_id_tipo IS NOT NULL AND v_cuenta.id_tipo_cuenta <> v_id_tipo THEN
            RETURN json_build_object('eliminado', false, 'id', p_id_pago, 'error', 'El pago no corresponde al tipo indicado');
        END IF;
    END IF;

    UPDATE fin_pago
       SET estado = 0,
           id_usuario_modificacion = p_id_usuario,
           fecha_modificacion = NOW()
     WHERE id = p_id_pago;

    UPDATE fin_cuenta
       SET monto_abonado = fin_redondear_monto(GREATEST(COALESCE(monto_abonado, 0) - v_pago.monto, 0)),
           monto_saldo   = fin_redondear_monto(
               GREATEST(monto_pendiente - GREATEST(COALESCE(monto_abonado, 0) - v_pago.monto, 0), 0)
           ),
           id_usuario_modificacion = p_id_usuario,
           fecha_modificacion = NOW()
     WHERE id = v_pago.id_cuenta;

    IF v_cuenta.id_cuenta_padre IS NOT NULL THEN
        PERFORM fin_refrescar_cabecera_plan(v_cuenta.id_cuenta_padre);
    END IF;

    RETURN json_build_object('eliminado', true, 'id', p_id_pago);
END;
$$;


--
-- Name: fin_anular_reembolso_garantia(integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fin_anular_reembolso_garantia(p_id integer, p_id_usuario integer DEFAULT NULL::integer) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_garantia    fin_garantia%ROWTYPE;
    v_id_activa   INT;
BEGIN
    SET TIME ZONE 'America/Lima';

    SELECT * INTO v_garantia FROM fin_garantia WHERE id = p_id AND estado = 1;
    IF NOT FOUND THEN
        RETURN json_build_object('registro', NULL, 'error', 'La garantía no existe o está inactiva');
    END IF;

    IF v_garantia.fecha_reembolso IS NULL THEN
        RETURN json_build_object('registro', NULL, 'error',
            'Esta garantía aún no tiene reembolso registrado; nada que anular.');
    END IF;

    SELECT glo.id INTO v_id_activa
    FROM gen_lista_opciones glo
    JOIN gen_lista gl ON gl.id = glo.id_lista
    WHERE gl.nombre = 'EstadoGarantia' AND glo.nombre = 'ACTIVA'
    LIMIT 1;

    UPDATE fin_garantia SET
        fecha_reembolso       = NULL,
        id_medio_reembolso    = NULL,
        observacion_reembolso = NULL,
        id_usuario_reembolso  = NULL,
        id_estado             = COALESCE(v_id_activa, id_estado),
        id_usuario_modificacion = p_id_usuario,
        fecha_modificacion    = NOW()
    WHERE id = p_id;

    RETURN json_build_object('registro', json_build_object('id', p_id, 'estado_texto', 'ACTIVA'));
END;
$$;


--
-- Name: fin_bajar_cuentas_documento(integer, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fin_bajar_cuentas_documento(p_id_usuario integer, p_id_comprobante_venta integer DEFAULT NULL::integer, p_id_comprobante_compra integer DEFAULT NULL::integer) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_id_padre INTEGER;
BEGIN
    FOR v_id_padre IN
        SELECT fc.id
        FROM fin_cuenta fc
        WHERE fc.estado = 1
          AND fc.id_cuenta_padre IS NULL
          AND (
              (p_id_comprobante_venta IS NOT NULL AND fc.id_comprobante_venta = p_id_comprobante_venta)
              OR (p_id_comprobante_compra IS NOT NULL AND fc.id_comprobante_compra = p_id_comprobante_compra)
          )
    LOOP
        UPDATE fin_cuenta
        SET estado = 0,
            id_usuario_modificacion = p_id_usuario,
            fecha_modificacion = NOW()
        WHERE id = v_id_padre
           OR id_cuenta_padre = v_id_padre;
    END LOOP;
END;
$$;


--
-- Name: fin_caja_assert_abierta(date, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fin_caja_assert_abierta(p_fecha date, p_id_sucursal integer DEFAULT NULL::integer) RETURNS text
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_estado VARCHAR;
    v_pendiente_fecha DATE;
    v_hoy DATE;
BEGIN
    SET TIME ZONE 'America/Lima';
    v_hoy := CURRENT_DATE;

    IF p_fecha IS NULL THEN
        RETURN 'La fecha es obligatoria para validar la caja';
    END IF;

    SELECT UPPER(est.nombre) INTO v_estado
    FROM fin_caja_sesion s
    INNER JOIN gen_lista_opciones est ON est.id = s.id_estado
    WHERE s.estado = 1
      AND s.fecha = p_fecha
      AND COALESCE(s.id_sucursal, 0) = COALESCE(p_id_sucursal, 0)
    ORDER BY s.id DESC
    LIMIT 1;

    IF v_estado = 'ABIERTA' THEN
        -- Caja de un día anterior aún abierta: bloquear ventas/movimientos.
        -- El cierre (arqueo) no usa este assert.
        IF p_fecha < v_hoy THEN
            RETURN format(
                'La caja del %s quedó abierta. Debes cerrarla (arqueo) en Ventas → Caja antes de registrar más operaciones, y luego abrir la caja de hoy.',
                to_char(p_fecha, 'DD/MM/YYYY')
            );
        END IF;
        RETURN NULL;
    END IF;

    IF v_estado = 'CERRADA' THEN
        RETURN 'La caja de esta fecha ya está cerrada. No se pueden registrar más operaciones.';
    END IF;

    IF v_estado IS NOT NULL THEN
        RETURN 'La sesión de caja no está abierta.';
    END IF;

    -- Sin sesión en p_fecha: ¿hay alguna ABIERTA de otro día?
    SELECT s.fecha INTO v_pendiente_fecha
    FROM fin_caja_sesion s
    INNER JOIN gen_lista_opciones est ON est.id = s.id_estado
    WHERE s.estado = 1
      AND UPPER(est.nombre) = 'ABIERTA'
      AND COALESCE(s.id_sucursal, 0) = COALESCE(p_id_sucursal, 0)
      AND s.fecha < v_hoy
    ORDER BY s.fecha ASC
    LIMIT 1;

    IF v_pendiente_fecha IS NOT NULL THEN
        RETURN format(
            'Hay una caja sin cerrar del %s. Ciérrala en Ventas → Caja (arqueo) antes de abrir o operar la de hoy.',
            to_char(v_pendiente_fecha, 'DD/MM/YYYY')
        );
    END IF;

    RETURN 'No hay caja abierta para esta fecha. Abre la caja en Ventas → Caja antes de continuar.';
END;
$$;


--
-- Name: fin_caja_calcular_totales(date, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fin_caja_calcular_totales(p_fecha date, p_id_sucursal integer DEFAULT NULL::integer) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_ventas_contado NUMERIC(14,4) := 0;
    v_ventas_credito NUMERIC(14,4) := 0;
    v_ventas_caja NUMERIC(14,4) := 0;
    v_cobranzas NUMERIC(14,4) := 0;
    v_cobranzas_caja NUMERIC(14,4) := 0;
    v_gastos_caja NUMERIC(14,4) := 0;
    v_gastos_compra NUMERIC(14,4) := 0;
    v_depositos NUMERIC(14,4) := 0;
    v_garantias_cobro NUMERIC(14,4) := 0;
    v_garantias_cobro_caja NUMERIC(14,4) := 0;
    v_garantias_dev NUMERIC(14,4) := 0;
    v_garantias_dev_caja NUMERIC(14,4) := 0;
BEGIN
    SET TIME ZONE 'America/Lima';

    SELECT
        COALESCE(SUM(CASE WHEN COALESCE(UPPER(mp.nombre), '') <> 'CREDITO' THEN c.total_importe ELSE 0 END), 0),
        COALESCE(SUM(CASE WHEN UPPER(mp.nombre) = 'CREDITO' THEN c.total_importe ELSE 0 END), 0),
        COALESCE(SUM(CASE
            WHEN UPPER(COALESCE(mp.nombre, 'EFECTIVO')) IN ('EFECTIVO', 'YAPE', 'PLIN')
            THEN c.total_importe ELSE 0 END), 0)
    INTO v_ventas_contado, v_ventas_credito, v_ventas_caja
    FROM ven_comprobante c
    LEFT JOIN gen_lista_opciones mp ON mp.id = c.id_medio_pago
    LEFT JOIN gen_lista_opciones est ON est.id = c.id_estado
    LEFT JOIN gen_lista_opciones tip ON tip.id = c.id_tipo_comprobante
    WHERE c.estado = 1
      AND c.fecha = p_fecha
      AND (p_id_sucursal IS NULL OR c.id_sucursal = p_id_sucursal OR c.id_sucursal IS NULL)
      AND COALESCE(UPPER(est.nombre), '') <> 'ANULADO'
      AND COALESCE(UPPER(tip.nombre), '') NOT IN ('NOTA_CREDITO', 'NOTA_DEBITO');

    SELECT
        COALESCE(SUM(p.monto), 0),
        COALESCE(SUM(CASE
            WHEN UPPER(COALESCE(mp.nombre, 'EFECTIVO')) IN ('EFECTIVO', 'YAPE', 'PLIN')
            THEN p.monto ELSE 0 END), 0)
    INTO v_cobranzas, v_cobranzas_caja
    FROM fin_pago p
    INNER JOIN fin_cuenta cu ON cu.id = p.id_cuenta AND cu.estado = 1
    INNER JOIN gen_lista_opciones tc ON tc.id = cu.id_tipo_cuenta
    LEFT JOIN gen_lista_opciones mp ON mp.id = p.id_medio_pago
    WHERE p.estado = 1
      AND p.fecha_pago = p_fecha
      AND UPPER(tc.nombre) = 'COBRAR'
      AND (
          p_id_sucursal IS NULL
          OR COALESCE(p.id_sucursal, fin_sucursal_de_cuenta(cu.id)) = p_id_sucursal
      );

    SELECT COALESCE(SUM(g.monto), 0)
    INTO v_gastos_caja
    FROM fin_caja_gasto g
    LEFT JOIN fin_caja_sesion s ON s.id = g.id_sesion AND s.estado = 1
    WHERE g.estado = 1 AND g.fecha = p_fecha
      AND (p_id_sucursal IS NULL OR s.id_sucursal = p_id_sucursal);

    SELECT COALESCE(SUM(cc.total_importe), 0)
    INTO v_gastos_compra
    FROM com_comprobante_compra cc
    LEFT JOIN gen_lista_opciones tr ON tr.id = cc.id_tipo_registro
    WHERE cc.estado = 1
      AND cc.fecha = p_fecha
      AND UPPER(COALESCE(tr.nombre, '')) = 'GASTO'
      AND (p_id_sucursal IS NULL OR cc.id_sucursal = p_id_sucursal OR cc.id_sucursal IS NULL);

    SELECT COALESCE(SUM(d.monto), 0)
    INTO v_depositos
    FROM fin_caja_deposito d
    LEFT JOIN fin_caja_sesion s ON s.id = d.id_sesion AND s.estado = 1
    WHERE d.estado = 1 AND d.fecha = p_fecha
      AND (p_id_sucursal IS NULL OR s.id_sucursal = p_id_sucursal);

    -- Cobros de garantía que no viajan ya en el total del CPE (factura/boleta/NV)
    SELECT
        COALESCE(SUM(gm.monto), 0),
        COALESCE(SUM(CASE
            WHEN UPPER(COALESCE(mp.nombre, 'EFECTIVO')) IN ('EFECTIVO', 'YAPE', 'PLIN')
            THEN gm.monto ELSE 0 END), 0)
    INTO v_garantias_cobro, v_garantias_cobro_caja
    FROM ven_garantia_movimiento gm
    INNER JOIN gen_lista_opciones tm ON tm.id = gm.id_tipo_movimiento
    LEFT JOIN ven_comprobante c ON c.id = gm.id_comprobante
    LEFT JOIN gen_lista_opciones tip ON tip.id = c.id_tipo_comprobante
    LEFT JOIN ven_garantia g ON g.id = gm.id_garantia
    LEFT JOIN gen_lista_opciones mp ON mp.id = COALESCE(gm.id_medio_pago, g.id_medio_pago)
    WHERE gm.estado = 1
      AND gm.fecha = p_fecha
      AND UPPER(tm.nombre) = 'COBRO'
      AND (
          p_id_sucursal IS NULL
          OR COALESCE(gm.id_sucursal, c.id_sucursal) = p_id_sucursal
          OR COALESCE(gm.id_sucursal, c.id_sucursal) IS NULL
      )
      AND (
          gm.id_comprobante IS NULL
          OR c.id IS NULL
          OR COALESCE(UPPER(tip.nombre), '') IN ('NOTA_CREDITO', 'NOTA_DEBITO')
      );

    SELECT
        COALESCE(SUM(gm.monto), 0),
        COALESCE(SUM(CASE
            WHEN UPPER(COALESCE(mp.nombre, 'EFECTIVO')) IN ('EFECTIVO', 'YAPE', 'PLIN')
            THEN gm.monto ELSE 0 END), 0)
    INTO v_garantias_dev, v_garantias_dev_caja
    FROM ven_garantia_movimiento gm
    INNER JOIN gen_lista_opciones tm ON tm.id = gm.id_tipo_movimiento
    LEFT JOIN ven_garantia g ON g.id = gm.id_garantia
    LEFT JOIN gen_lista_opciones mp ON mp.id = COALESCE(
        gm.id_medio_pago,
        g.id_medio_reembolso,
        g.id_medio_pago
    )
    WHERE gm.estado = 1
      AND gm.fecha = p_fecha
      AND UPPER(tm.nombre) = 'DEVOLUCION'
      AND (
          p_id_sucursal IS NULL
          OR gm.id_sucursal = p_id_sucursal
          OR gm.id_sucursal IS NULL
      );

    RETURN json_build_object(
        'ventasContado', v_ventas_contado,
        'ventasCredito', v_ventas_credito,
        'ventasMediosCaja', v_ventas_caja,
        'cobranzas', v_cobranzas,
        'cobranzasMediosCaja', v_cobranzas_caja,
        'gastosCaja', v_gastos_caja,
        'gastosCompra', v_gastos_compra,
        'gastos', v_gastos_caja + v_gastos_compra,
        'depositos', v_depositos,
        'garantiasCobro', v_garantias_cobro,
        'garantiasCobroMediosCaja', v_garantias_cobro_caja,
        'garantiasDevolucion', v_garantias_dev,
        'garantiasDevolucionMediosCaja', v_garantias_dev_caja
    );
END;
$$;


--
-- Name: fin_cerrar_caja_sesion(integer, numeric, character varying, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fin_cerrar_caja_sesion(p_id integer, p_monto_efectivo_contado numeric, p_observacion character varying DEFAULT NULL::character varying, p_id_usuario integer DEFAULT NULL::integer) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_sesion RECORD;
    v_estado_cerrada INT;
    v_totales JSON;
    v_esperado NUMERIC(14,4);
    v_diferencia NUMERIC(14,4);
    v_registro JSON;
BEGIN
    SET TIME ZONE 'America/Lima';

    SELECT lo.id INTO v_estado_cerrada
    FROM gen_lista_opciones lo
    INNER JOIN gen_lista l ON l.id = lo.id_lista
    WHERE l.nombre = 'EstadoCaja' AND lo.nombre = 'CERRADA'
    LIMIT 1;

    SELECT s.*, est.nombre AS estado_nombre
    INTO v_sesion
    FROM fin_caja_sesion s
    LEFT JOIN gen_lista_opciones est ON est.id = s.id_estado
    WHERE s.id = p_id AND s.estado = 1;

    IF NOT FOUND THEN
        RETURN json_build_object('error', 'Sesión de caja no encontrada', 'registro', NULL);
    END IF;

    IF UPPER(COALESCE(v_sesion.estado_nombre, '')) = 'CERRADA' THEN
        RETURN json_build_object('error', 'La caja ya está cerrada', 'registro', NULL);
    END IF;

    IF p_monto_efectivo_contado IS NULL OR p_monto_efectivo_contado < 0 THEN
        RETURN json_build_object('error', 'Indique el efectivo contado (arqueo)', 'registro', NULL);
    END IF;

    v_totales := fin_caja_calcular_totales(v_sesion.fecha, v_sesion.id_sucursal);
    v_esperado := COALESCE(v_sesion.monto_inicial, 0)
        + COALESCE((v_totales->>'ventasMediosCaja')::NUMERIC, 0)
        + COALESCE((v_totales->>'cobranzasMediosCaja')::NUMERIC, 0)
        + COALESCE((v_totales->>'garantiasCobroMediosCaja')::NUMERIC, 0)
        - COALESCE((v_totales->>'depositos')::NUMERIC, 0)
        - COALESCE((v_totales->>'gastosCaja')::NUMERIC, 0)
        - COALESCE((v_totales->>'garantiasDevolucionMediosCaja')::NUMERIC, 0);
    v_diferencia := COALESCE(p_monto_efectivo_contado, 0) - v_esperado;

    UPDATE fin_caja_sesion
    SET id_estado = v_estado_cerrada,
        monto_efectivo_contado = p_monto_efectivo_contado,
        monto_esperado = v_esperado,
        diferencia = v_diferencia,
        observacion_cierre = NULLIF(TRIM(p_observacion), ''),
        fecha_cierre = NOW(),
        id_usuario_cierre = p_id_usuario,
        id_usuario_modificacion = p_id_usuario,
        fecha_modificacion = NOW()
    WHERE id = p_id;

    SELECT row_to_json(t) INTO v_registro
    FROM (
        SELECT
            s.id,
            s.fecha,
            s.id_sucursal AS "idSucursal",
            suc.nombre AS "nombreSucursal",
            s.id_estado AS "idEstado",
            est.nombre AS "estadoCaja",
            s.monto_inicial AS "montoInicial",
            s.monto_efectivo_contado AS "montoEfectivoContado",
            s.monto_esperado AS "montoEsperado",
            s.diferencia,
            s.observacion_apertura AS "observacionApertura",
            s.observacion_cierre AS "observacionCierre",
            s.fecha_apertura AS "fechaApertura",
            s.fecha_cierre AS "fechaCierre",
            s.id_usuario_apertura AS "idUsuarioApertura",
            s.id_usuario_cierre AS "idUsuarioCierre",
            v_totales AS totales
        FROM fin_caja_sesion s
        LEFT JOIN gen_sucursal suc ON suc.id = s.id_sucursal
        LEFT JOIN gen_lista_opciones est ON est.id = s.id_estado
        WHERE s.id = p_id
    ) t;

    RETURN json_build_object('registro', v_registro);
END;
$$;


--
-- Name: fin_crear_caja_deposito(date, numeric, integer, integer, character varying, character varying, integer, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fin_crear_caja_deposito(p_fecha date, p_monto numeric, p_id_cuenta_bancaria integer DEFAULT NULL::integer, p_id_medio_pago integer DEFAULT NULL::integer, p_numero_operacion character varying DEFAULT NULL::character varying, p_observacion character varying DEFAULT NULL::character varying, p_id_sesion integer DEFAULT NULL::integer, p_id_usuario integer DEFAULT NULL::integer, p_id_sucursal integer DEFAULT NULL::integer) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_id INT;
    v_registro JSON;
    v_sesion_id INT;
    v_sucursal INT;
    v_err_caja TEXT;
BEGIN
    SET TIME ZONE 'America/Lima';

    IF p_fecha IS NULL OR COALESCE(p_monto, 0) <= 0 THEN
        RETURN json_build_object('error', 'Fecha y monto (> 0) son obligatorios', 'registro', NULL);
    END IF;

    v_sucursal := p_id_sucursal;
    v_sesion_id := p_id_sesion;

    IF v_sesion_id IS NOT NULL THEN
        SELECT s.id_sucursal INTO v_sucursal
        FROM fin_caja_sesion s
        INNER JOIN gen_lista_opciones est ON est.id = s.id_estado
        WHERE s.id = v_sesion_id AND s.estado = 1 AND UPPER(est.nombre) = 'ABIERTA';

        IF NOT FOUND THEN
            RETURN json_build_object('error', 'La sesión de caja indicada no está abierta', 'registro', NULL);
        END IF;
    ELSE
        SELECT s.id, s.id_sucursal INTO v_sesion_id, v_sucursal
        FROM fin_caja_sesion s
        INNER JOIN gen_lista_opciones est ON est.id = s.id_estado
        WHERE s.estado = 1 AND s.fecha = p_fecha AND UPPER(est.nombre) = 'ABIERTA'
          AND COALESCE(s.id_sucursal, 0) = COALESCE(p_id_sucursal, 0)
        ORDER BY s.id DESC
        LIMIT 1;
    END IF;

    v_err_caja := fin_caja_assert_abierta(p_fecha, v_sucursal);
    IF v_err_caja IS NOT NULL THEN
        RETURN json_build_object('error', v_err_caja, 'registro', NULL);
    END IF;

    INSERT INTO fin_caja_deposito (
        id_sesion, fecha, monto, id_cuenta_bancaria, id_medio_pago,
        numero_operacion, observacion, id_usuario_creacion
    ) VALUES (
        v_sesion_id, p_fecha, p_monto, p_id_cuenta_bancaria, p_id_medio_pago,
        NULLIF(TRIM(p_numero_operacion), ''), NULLIF(TRIM(p_observacion), ''), p_id_usuario
    )
    RETURNING id INTO v_id;

    SELECT row_to_json(t) INTO v_registro
    FROM (
        SELECT
            d.id, d.fecha, d.monto,
            d.id_cuenta_bancaria AS "idCuentaBancaria",
            COALESCE(cb.titular, cb.numero_cuenta) AS "cuentaBancaria",
            d.id_medio_pago AS "idMedioPago",
            mp.nombre AS "medioPago",
            d.numero_operacion AS "numeroOperacion",
            d.observacion,
            d.id_sesion AS "idSesion"
        FROM fin_caja_deposito d
        LEFT JOIN gen_cuenta_bancaria cb ON cb.id = d.id_cuenta_bancaria
        LEFT JOIN gen_lista_opciones mp ON mp.id = d.id_medio_pago
        WHERE d.id = v_id
    ) t;

    RETURN json_build_object('registro', v_registro);
END;
$$;


--
-- Name: fin_crear_caja_gasto(date, character varying, numeric, integer, integer, character varying, character varying, integer, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fin_crear_caja_gasto(p_fecha date, p_concepto character varying, p_monto numeric, p_id_medio_pago integer DEFAULT NULL::integer, p_id_categoria_gasto integer DEFAULT NULL::integer, p_numero_operacion character varying DEFAULT NULL::character varying, p_observacion character varying DEFAULT NULL::character varying, p_id_sesion integer DEFAULT NULL::integer, p_id_usuario integer DEFAULT NULL::integer, p_id_sucursal integer DEFAULT NULL::integer) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_id INT;
    v_registro JSON;
    v_sesion_id INT;
    v_sucursal INT;
    v_err_caja TEXT;
BEGIN
    SET TIME ZONE 'America/Lima';

    IF p_fecha IS NULL OR NULLIF(TRIM(p_concepto), '') IS NULL OR COALESCE(p_monto, 0) <= 0 THEN
        RETURN json_build_object('error', 'Fecha, concepto y monto (> 0) son obligatorios', 'registro', NULL);
    END IF;

    v_sucursal := p_id_sucursal;
    v_sesion_id := p_id_sesion;

    IF v_sesion_id IS NOT NULL THEN
        SELECT s.id_sucursal INTO v_sucursal
        FROM fin_caja_sesion s
        INNER JOIN gen_lista_opciones est ON est.id = s.id_estado
        WHERE s.id = v_sesion_id AND s.estado = 1 AND UPPER(est.nombre) = 'ABIERTA';

        IF NOT FOUND THEN
            RETURN json_build_object('error', 'La sesión de caja indicada no está abierta', 'registro', NULL);
        END IF;
    ELSE
        SELECT s.id, s.id_sucursal INTO v_sesion_id, v_sucursal
        FROM fin_caja_sesion s
        INNER JOIN gen_lista_opciones est ON est.id = s.id_estado
        WHERE s.estado = 1 AND s.fecha = p_fecha AND UPPER(est.nombre) = 'ABIERTA'
          AND COALESCE(s.id_sucursal, 0) = COALESCE(p_id_sucursal, 0)
        ORDER BY s.id DESC
        LIMIT 1;
    END IF;

    v_err_caja := fin_caja_assert_abierta(p_fecha, v_sucursal);
    IF v_err_caja IS NOT NULL THEN
        RETURN json_build_object('error', v_err_caja, 'registro', NULL);
    END IF;

    INSERT INTO fin_caja_gasto (
        id_sesion, fecha, concepto, monto, id_medio_pago, id_categoria_gasto,
        numero_operacion, observacion, id_usuario_creacion
    ) VALUES (
        v_sesion_id, p_fecha, TRIM(p_concepto), p_monto, p_id_medio_pago, p_id_categoria_gasto,
        NULLIF(TRIM(p_numero_operacion), ''), NULLIF(TRIM(p_observacion), ''), p_id_usuario
    )
    RETURNING id INTO v_id;

    SELECT row_to_json(t) INTO v_registro
    FROM (
        SELECT
            g.id, g.fecha, g.concepto, g.monto,
            g.id_medio_pago AS "idMedioPago",
            mp.nombre AS "medioPago",
            g.id_categoria_gasto AS "idCategoriaGasto",
            cat.nombre AS "categoriaGasto",
            g.numero_operacion AS "numeroOperacion",
            g.observacion,
            g.id_sesion AS "idSesion"
        FROM fin_caja_gasto g
        LEFT JOIN gen_lista_opciones mp ON mp.id = g.id_medio_pago
        LEFT JOIN gen_lista_opciones cat ON cat.id = g.id_categoria_gasto
        WHERE g.id = v_id
    ) t;

    RETURN json_build_object('registro', v_registro);
END;
$$;


--
-- Name: fin_crear_caja_observacion(date, character varying, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fin_crear_caja_observacion(p_fecha date, p_texto character varying, p_id_usuario integer DEFAULT NULL::integer) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_id INT;
    v_registro JSON;
BEGIN
    SET TIME ZONE 'America/Lima';

    IF p_fecha IS NULL OR NULLIF(TRIM(p_texto), '') IS NULL THEN
        RETURN json_build_object('error', 'Fecha y texto son obligatorios', 'registro', NULL);
    END IF;

    INSERT INTO fin_caja_observacion (fecha, texto, id_usuario_creacion)
    VALUES (p_fecha, TRIM(p_texto), p_id_usuario)
    RETURNING id INTO v_id;

    SELECT row_to_json(t) INTO v_registro
    FROM (
        SELECT
            o.id, o.fecha, o.texto,
            o.id_usuario_creacion AS "idUsuarioCreacion",
            u.nombre AS "usuario",
            o.fecha_creacion AS "fechaCreacion"
        FROM fin_caja_observacion o
        LEFT JOIN auth_usuarios u ON u.id = o.id_usuario_creacion
        WHERE o.id = v_id
    ) t;

    RETURN json_build_object('registro', v_registro);
END;
$$;


--
-- Name: fin_crear_cuenta(character varying, integer, character varying, date, date, numeric, character varying, character varying, integer, numeric, character varying, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fin_crear_cuenta(p_tipo character varying, p_id_tercero integer DEFAULT NULL::integer, p_tercero_nombre character varying DEFAULT NULL::character varying, p_fecha_emision date DEFAULT NULL::date, p_fecha_vencimiento date DEFAULT NULL::date, p_monto numeric DEFAULT NULL::numeric, p_descripcion character varying DEFAULT NULL::character varying, p_observacion character varying DEFAULT NULL::character varying, p_id_banco integer DEFAULT NULL::integer, p_tasa_interes numeric DEFAULT NULL::numeric, p_numero_comprobante character varying DEFAULT NULL::character varying, p_id_usuario integer DEFAULT NULL::integer) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_id_tipo    INT;
    v_id_tercero INT;
    v_nombre     VARCHAR;
    v_id_cuenta  INT;
    v_registro   JSON;
BEGIN
    SET TIME ZONE 'America/Lima';

    -- Validar tipo
    SELECT glo.id INTO v_id_tipo
    FROM gen_lista_opciones glo
    JOIN gen_lista gl ON gl.id = glo.id_lista
    WHERE gl.nombre = 'TipoCuentaFinanciera'
      AND glo.nombre = UPPER(COALESCE(p_tipo, ''))
    LIMIT 1;

    IF v_id_tipo IS NULL THEN
        RETURN json_build_object(
            'registro', NULL,
            'error', format(
                'Tipo de cuenta inválido. Recibido: %L. Opciones existentes en TipoCuentaFinanciera: [%s]. Ejecuta el seed fin_tipo_cuenta_opciones.sql si está vacío.',
                p_tipo,
                COALESCE((
                    SELECT string_agg(glo.nombre, ', ')
                    FROM gen_lista_opciones glo
                    JOIN gen_lista gl ON gl.id = glo.id_lista
                    WHERE gl.nombre = 'TipoCuentaFinanciera'
                ), 'vacío')
            )
        );
    END IF;

    -- Validar tercero: al menos uno de los dos
    v_nombre := NULLIF(TRIM(p_tercero_nombre), '');

    IF p_id_tercero IS NULL AND v_nombre IS NULL THEN
        RETURN json_build_object('registro', NULL, 'error', 'Debe indicar el tercero (cliente/proveedor) o su nombre');
    END IF;

    IF p_id_tercero IS NOT NULL THEN
        SELECT id INTO v_id_tercero
        FROM cli_clientes
        WHERE id = p_id_tercero AND estado = 1;

        IF v_id_tercero IS NULL THEN
            RETURN json_build_object('registro', NULL, 'error', 'El tercero no existe o está inactivo');
        END IF;
    END IF;

    -- Validar fechas
    IF p_fecha_emision IS NULL THEN
        RETURN json_build_object('registro', NULL, 'error', 'La fecha de emisión es obligatoria');
    END IF;

    IF p_fecha_vencimiento IS NOT NULL AND p_fecha_vencimiento < p_fecha_emision THEN
        RETURN json_build_object('registro', NULL, 'error', 'La fecha de vencimiento no puede ser anterior a la emisión');
    END IF;

    -- Validar monto
    IF p_monto IS NULL OR p_monto <= 0 THEN
        RETURN json_build_object('registro', NULL, 'error', 'El monto debe ser mayor a cero');
    END IF;

    -- Inserción
    INSERT INTO fin_cuenta (
        id_tipo_cuenta, id_tercero, tercero_nombre,
        fecha_emision, fecha_vencimiento,
        monto_pendiente, monto_abonado, monto_saldo,
        descripcion, observacion,
        id_banco, tasa_interes,
        numero_comprobante,
        id_usuario_creacion
    ) VALUES (
        v_id_tipo, v_id_tercero, v_nombre,
        p_fecha_emision, p_fecha_vencimiento,
        fin_redondear_monto(p_monto), 0, fin_redondear_monto(p_monto),
        NULLIF(TRIM(p_descripcion), ''),
        NULLIF(TRIM(p_observacion), ''),
        p_id_banco, p_tasa_interes,
        NULLIF(TRIM(p_numero_comprobante), ''),
        p_id_usuario
    )
    RETURNING id INTO v_id_cuenta;

    SELECT row_to_json(t) INTO v_registro
    FROM (
        SELECT
            fc.id,
            fc.id_tipo_cuenta,
            UPPER(p_tipo) AS tipo,
            fc.id_tercero,
            fc.tercero_nombre,
            COALESCE(
                NULLIF(TRIM(ter.razon_social), ''),
                NULLIF(TRIM(CONCAT_WS(' ', ter.nombres, ter.apellido_paterno, ter.apellido_materno)), ''),
                fc.tercero_nombre,
                'Tercero #' || fc.id
            ) AS tercero,
            ter.numero_documento AS documento_tercero,
            fc.descripcion,
            fc.numero_comprobante,
            fc.fecha_emision,
            fc.fecha_vencimiento,
            fc.monto_pendiente,
            fc.monto_abonado,
            fc.monto_saldo AS saldo,
            fc.observacion,
            fc.id_banco,
            fc.tasa_interes
        FROM fin_cuenta fc
        LEFT JOIN cli_clientes ter ON ter.id = fc.id_tercero
        WHERE fc.id = v_id_cuenta
    ) t;

    RETURN json_build_object('registro', v_registro);
END;
$$;


--
-- Name: fin_crear_cuenta_cuotas(character varying, integer, character varying, date, numeric, integer, date, integer, character varying, character varying, integer, numeric, character varying, integer, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fin_crear_cuenta_cuotas(p_tipo character varying, p_id_tercero integer DEFAULT NULL::integer, p_tercero_nombre character varying DEFAULT NULL::character varying, p_fecha_emision date DEFAULT NULL::date, p_monto_total numeric DEFAULT NULL::numeric, p_numero_cuotas integer DEFAULT NULL::integer, p_fecha_primera_cuota date DEFAULT NULL::date, p_dia_mes_pago integer DEFAULT NULL::integer, p_descripcion character varying DEFAULT NULL::character varying, p_observacion character varying DEFAULT NULL::character varying, p_id_banco integer DEFAULT NULL::integer, p_tasa_interes numeric DEFAULT NULL::numeric, p_numero_comprobante character varying DEFAULT NULL::character varying, p_id_usuario integer DEFAULT NULL::integer, p_id_comprobante_venta integer DEFAULT NULL::integer, p_id_comprobante_compra integer DEFAULT NULL::integer) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_id_tipo         INT;
    v_id_tercero      INT;
    v_nombre          VARCHAR;
    v_id_padre        INT;
    v_monto_total     NUMERIC(12,2);
    v_monto_cuota     NUMERIC(12,2);
    v_ultima_cuota    NUMERIC(12,2);
    v_fecha_cuota     DATE;
    v_mes_base        DATE;
    v_ultimo_dia_mes  DATE;
    v_i               INT;
    v_registro        JSON;
BEGIN
    SET TIME ZONE 'America/Lima';

    SELECT glo.id INTO v_id_tipo
    FROM gen_lista_opciones glo
    JOIN gen_lista gl ON gl.id = glo.id_lista
    WHERE gl.nombre = 'TipoCuentaFinanciera' AND glo.nombre = UPPER(COALESCE(p_tipo, ''))
    LIMIT 1;

    IF v_id_tipo IS NULL THEN
        RETURN json_build_object(
            'registro', NULL,
            'error', format(
                'Tipo de cuenta inválido. Recibido: %L. Opciones existentes en TipoCuentaFinanciera: [%s].',
                p_tipo,
                COALESCE((
                    SELECT string_agg(glo.nombre, ', ')
                    FROM gen_lista_opciones glo
                    JOIN gen_lista gl ON gl.id = glo.id_lista
                    WHERE gl.nombre = 'TipoCuentaFinanciera'
                ), 'vacío')
            )
        );
    END IF;

    v_nombre := NULLIF(TRIM(p_tercero_nombre), '');
    IF p_id_tercero IS NULL AND v_nombre IS NULL THEN
        RETURN json_build_object('registro', NULL, 'error', 'Debe indicar el tercero o su nombre');
    END IF;

    IF p_id_tercero IS NOT NULL THEN
        SELECT id INTO v_id_tercero FROM cli_clientes WHERE id = p_id_tercero AND estado = 1;
        IF v_id_tercero IS NULL THEN
            RETURN json_build_object('registro', NULL, 'error', 'El tercero no existe o está inactivo');
        END IF;
    END IF;

    IF p_fecha_emision IS NULL THEN
        RETURN json_build_object('registro', NULL, 'error', 'La fecha de emisión es obligatoria');
    END IF;

    IF p_fecha_primera_cuota IS NULL THEN
        RETURN json_build_object('registro', NULL, 'error', 'La fecha de la primera cuota es obligatoria');
    END IF;

    IF p_fecha_primera_cuota < p_fecha_emision THEN
        RETURN json_build_object('registro', NULL, 'error', 'La primera cuota no puede ser anterior a la emisión');
    END IF;

    IF p_monto_total IS NULL OR p_monto_total <= 0 THEN
        RETURN json_build_object('registro', NULL, 'error', 'El monto total debe ser mayor a cero');
    END IF;

    IF p_numero_cuotas IS NULL OR p_numero_cuotas < 1 THEN
        RETURN json_build_object('registro', NULL, 'error', 'El número de cuotas debe ser al menos 1');
    END IF;

    IF p_dia_mes_pago IS NULL OR p_dia_mes_pago < 1 OR p_dia_mes_pago > 31 THEN
        RETURN json_build_object('registro', NULL, 'error', 'El día del mes de pago debe estar entre 1 y 31');
    END IF;

    v_monto_total  := fin_redondear_monto(p_monto_total);
    v_monto_cuota  := ROUND(v_monto_total / p_numero_cuotas, 2);
    v_ultima_cuota := v_monto_total - (v_monto_cuota * (p_numero_cuotas - 1));

    -- Cabecera
    INSERT INTO fin_cuenta (
        id_tipo_cuenta, id_tercero, tercero_nombre,
        id_comprobante_venta, id_comprobante_compra,
        fecha_emision, fecha_vencimiento,
        monto_pendiente, monto_abonado, monto_saldo,
        numero_cuotas_total,
        descripcion, observacion,
        id_banco, tasa_interes,
        numero_comprobante,
        id_usuario_creacion,
        id_usuario_modificacion
    ) VALUES (
        v_id_tipo, v_id_tercero, v_nombre,
        p_id_comprobante_venta, p_id_comprobante_compra,
        p_fecha_emision, NULL,
        v_monto_total, 0, v_monto_total,
        p_numero_cuotas,
        NULLIF(TRIM(p_descripcion), ''),
        NULLIF(TRIM(p_observacion), ''),
        p_id_banco, p_tasa_interes,
        NULLIF(TRIM(p_numero_comprobante), ''),
        p_id_usuario,
        p_id_usuario
    )
    RETURNING id INTO v_id_padre;

    -- Cuotas hijas
    FOR v_i IN 1..p_numero_cuotas LOOP
        IF v_i = 1 THEN
            v_fecha_cuota := p_fecha_primera_cuota;
        ELSE
            v_mes_base := date_trunc('month', p_fecha_primera_cuota)::date
                          + ((v_i - 1) * INTERVAL '1 month');
            v_ultimo_dia_mes := (v_mes_base + INTERVAL '1 month - 1 day')::date;
            v_fecha_cuota := LEAST(
                (v_mes_base + ((p_dia_mes_pago - 1) * INTERVAL '1 day'))::date,
                v_ultimo_dia_mes
            );
        END IF;

        INSERT INTO fin_cuenta (
            id_tipo_cuenta, id_tercero, tercero_nombre,
            id_comprobante_venta, id_comprobante_compra,
            id_cuenta_padre, numero_cuota,
            fecha_emision, fecha_vencimiento,
            monto_pendiente, monto_abonado, monto_saldo,
            descripcion,
            id_usuario_creacion,
            id_usuario_modificacion
        ) VALUES (
            v_id_tipo, v_id_tercero, v_nombre,
            p_id_comprobante_venta, p_id_comprobante_compra,
            v_id_padre, v_i,
            p_fecha_emision, v_fecha_cuota,
            CASE WHEN v_i = p_numero_cuotas THEN v_ultima_cuota ELSE v_monto_cuota END,
            0,
            CASE WHEN v_i = p_numero_cuotas THEN v_ultima_cuota ELSE v_monto_cuota END,
            'Cuota ' || v_i || ' de ' || p_numero_cuotas,
            p_id_usuario,
            p_id_usuario
        );
    END LOOP;

    SELECT row_to_json(t) INTO v_registro
    FROM (
        SELECT
            fc.id,
            UPPER(p_tipo) AS tipo,
            fc.id_tercero,
            fc.tercero_nombre,
            COALESCE(
                NULLIF(TRIM(ter.razon_social), ''),
                NULLIF(TRIM(CONCAT_WS(' ', ter.nombres, ter.apellido_paterno, ter.apellido_materno)), ''),
                fc.tercero_nombre,
                'Tercero #' || fc.id
            ) AS tercero,
            fc.descripcion,
            fc.fecha_emision,
            fc.monto_pendiente,
            fc.numero_cuotas_total,
            fc.id_banco,
            fc.tasa_interes,
            (
                SELECT COALESCE(json_agg(
                    json_build_object(
                        'id', h.id,
                        'numeroCuota', h.numero_cuota,
                        'fechaVencimiento', h.fecha_vencimiento,
                        'monto', h.monto_pendiente
                    ) ORDER BY h.numero_cuota
                ), '[]'::json)
                FROM fin_cuenta h
                WHERE h.id_cuenta_padre = fc.id AND h.estado = 1
            ) AS cuotas
        FROM fin_cuenta fc
        LEFT JOIN cli_clientes ter ON ter.id = fc.id_tercero
        WHERE fc.id = v_id_padre
    ) t;

    RETURN json_build_object('registro', v_registro);
END;
$$;


--
-- Name: fin_crear_garantia(date, integer, integer, numeric, character varying, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fin_crear_garantia(p_fecha date, p_id_cliente integer, p_id_medio_pago integer, p_importe numeric, p_observacion character varying DEFAULT NULL::character varying, p_id_usuario integer DEFAULT NULL::integer) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_id_cliente INT;
    v_id_estado  INT;
    v_id_garantia INT;
    v_registro JSON;
BEGIN
    SET TIME ZONE 'America/Lima';

    IF p_fecha IS NULL THEN
        RETURN json_build_object('registro', NULL, 'error', 'La fecha es obligatoria');
    END IF;
    IF p_id_cliente IS NULL THEN
        RETURN json_build_object('registro', NULL, 'error', 'El cliente es obligatorio');
    END IF;

    SELECT id INTO v_id_cliente FROM cli_clientes WHERE id = p_id_cliente AND estado = 1;
    IF v_id_cliente IS NULL THEN
        RETURN json_build_object('registro', NULL, 'error', 'El cliente no existe o está inactivo');
    END IF;

    IF p_importe IS NULL OR p_importe <= 0 THEN
        RETURN json_build_object('registro', NULL, 'error', 'El importe debe ser mayor a cero');
    END IF;

    SELECT glo.id INTO v_id_estado
    FROM gen_lista_opciones glo
    JOIN gen_lista gl ON gl.id = glo.id_lista
    WHERE gl.nombre = 'EstadoGarantia' AND glo.nombre = 'ACTIVA'
    LIMIT 1;

    INSERT INTO fin_garantia (
        fecha, id_cliente, id_medio_pago, importe, observacion,
        id_estado, id_usuario_creacion
    ) VALUES (
        p_fecha, v_id_cliente, p_id_medio_pago, p_importe,
        NULLIF(TRIM(p_observacion), ''),
        v_id_estado, p_id_usuario
    ) RETURNING id INTO v_id_garantia;

    SELECT row_to_json(t) INTO v_registro FROM (
        SELECT
            g.id, g.fecha,
            g.id_cliente,
            COALESCE(NULLIF(TRIM(c.razon_social), ''),
                     NULLIF(TRIM(CONCAT_WS(' ', c.nombres, c.apellido_paterno, c.apellido_materno)), ''),
                     'Cliente #' || g.id_cliente) AS cliente,
            c.numero_documento AS documento_cliente,
            g.id_medio_pago, mp.nombre AS medio_pago,
            g.importe, g.observacion,
            g.fecha_reembolso,
            g.id_medio_reembolso, mr.nombre AS medio_reembolso,
            g.observacion_reembolso,
            g.id_estado, est.nombre AS estado_texto,
            g.fecha_creacion
        FROM fin_garantia g
        JOIN cli_clientes c ON c.id = g.id_cliente
        LEFT JOIN gen_lista_opciones mp  ON mp.id = g.id_medio_pago
        LEFT JOIN gen_lista_opciones mr  ON mr.id = g.id_medio_reembolso
        LEFT JOIN gen_lista_opciones est ON est.id = g.id_estado
        WHERE g.id = v_id_garantia
    ) t;

    RETURN json_build_object('registro', v_registro);
END;
$$;


--
-- Name: fin_cuenta_documento_tiene_pagos(integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fin_cuenta_documento_tiene_pagos(p_id_comprobante_venta integer DEFAULT NULL::integer, p_id_comprobante_compra integer DEFAULT NULL::integer) RETURNS boolean
    LANGUAGE plpgsql STABLE
    AS $$
BEGIN
    RETURN EXISTS (
        SELECT 1
        FROM fin_pago p
        JOIN fin_cuenta c ON c.id = p.id_cuenta
        WHERE p.estado = 1
          AND c.estado = 1
          AND (
              (
                  p_id_comprobante_venta IS NOT NULL
                  AND (
                      c.id_comprobante_venta = p_id_comprobante_venta
                      OR c.id_cuenta_padre IN (
                          SELECT fc.id
                          FROM fin_cuenta fc
                          WHERE fc.id_comprobante_venta = p_id_comprobante_venta
                            AND fc.estado = 1
                            AND fc.id_cuenta_padre IS NULL
                      )
                  )
              )
              OR (
                  p_id_comprobante_compra IS NOT NULL
                  AND (
                      c.id_comprobante_compra = p_id_comprobante_compra
                      OR c.id_cuenta_padre IN (
                          SELECT fc.id
                          FROM fin_cuenta fc
                          WHERE fc.id_comprobante_compra = p_id_comprobante_compra
                            AND fc.estado = 1
                            AND fc.id_cuenta_padre IS NULL
                      )
                  )
              )
          )
    );
END;
$$;


--
-- Name: fin_eliminar_caja_deposito(integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fin_eliminar_caja_deposito(p_id integer, p_id_usuario integer DEFAULT NULL::integer) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_fecha DATE;
    v_id_sesion INT;
    v_estado VARCHAR;
    v_err TEXT;
BEGIN
    SET TIME ZONE 'America/Lima';

    SELECT d.fecha, d.id_sesion
    INTO v_fecha, v_id_sesion
    FROM fin_caja_deposito d
    WHERE d.id = p_id AND d.estado = 1;

    IF v_fecha IS NULL THEN
        RETURN json_build_object('error', 'Depósito no encontrado', 'eliminado', false);
    END IF;

    IF v_id_sesion IS NOT NULL THEN
        SELECT UPPER(est.nombre) INTO v_estado
        FROM fin_caja_sesion s
        INNER JOIN gen_lista_opciones est ON est.id = s.id_estado
        WHERE s.id = v_id_sesion AND s.estado = 1;

        IF v_estado IS DISTINCT FROM 'ABIERTA' THEN
            RETURN json_build_object(
                'error',
                'Solo se puede anular un depósito mientras la caja esté abierta. Si ya cerró, no se modifica el arqueo.',
                'eliminado',
                false
            );
        END IF;
    ELSE
        v_err := fin_caja_assert_abierta(v_fecha, NULL);
        IF v_err IS NOT NULL THEN
            RETURN json_build_object('error', v_err, 'eliminado', false);
        END IF;
    END IF;

    UPDATE fin_caja_deposito
    SET estado = 0, id_usuario_modificacion = p_id_usuario, fecha_modificacion = NOW()
    WHERE id = p_id AND estado = 1;

    IF NOT FOUND THEN
        RETURN json_build_object('error', 'Depósito no encontrado', 'eliminado', false);
    END IF;

    RETURN json_build_object('eliminado', true, 'id', p_id);
END;
$$;


