CREATE FUNCTION public.fin_eliminar_garantia(p_id integer, p_id_usuario integer DEFAULT NULL::integer) RETURNS json
    LANGUAGE plpgsql
    AS $$
BEGIN
    SET TIME ZONE 'America/Lima';

    UPDATE fin_garantia
       SET estado = 0,
           id_usuario_modificacion = p_id_usuario,
           fecha_modificacion = NOW()
     WHERE id = p_id AND estado = 1;

    IF NOT FOUND THEN
        RETURN json_build_object('eliminado', false, 'id', p_id, 'error', 'La garantía no existe o ya está inactiva');
    END IF;

    RETURN json_build_object('eliminado', true, 'id', p_id);
END;
$$;


--
-- Name: fin_estado_cuenta_calculado(numeric, numeric, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fin_estado_cuenta_calculado(p_saldo numeric, p_monto_abonado numeric, p_fecha_vencimiento date) RETURNS character varying
    LANGUAGE sql STABLE
    AS $$
    SELECT CASE
        WHEN fin_redondear_monto(p_saldo) <= 0 THEN 'PAGADO'
        WHEN p_fecha_vencimiento IS NOT NULL AND p_fecha_vencimiento < CURRENT_DATE THEN 'VENCIDO'
        WHEN fin_redondear_monto(p_monto_abonado) > 0 THEN 'PARCIAL'
        ELSE 'PENDIENTE'
    END;
$$;


--
-- Name: fin_listar_caja_gastos(character varying, integer, integer, date, date, integer, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fin_listar_caja_gastos(p_buscar character varying DEFAULT ''::character varying, p_limite integer DEFAULT 10, p_offset integer DEFAULT 0, p_fecha_desde date DEFAULT NULL::date, p_fecha_hasta date DEFAULT NULL::date, p_id_categoria_gasto integer DEFAULT NULL::integer, p_id_sesion integer DEFAULT NULL::integer, p_estado integer DEFAULT 1) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_result JSON;
BEGIN
    SET TIME ZONE 'America/Lima';

    WITH filtrado AS (
        SELECT g.*
        FROM fin_caja_gasto g
        WHERE (p_estado IS NULL OR g.estado = p_estado)
          AND (p_fecha_desde IS NULL OR g.fecha >= p_fecha_desde)
          AND (p_fecha_hasta IS NULL OR g.fecha <= p_fecha_hasta)
          AND (p_id_categoria_gasto IS NULL OR g.id_categoria_gasto = p_id_categoria_gasto)
          AND (p_id_sesion IS NULL OR g.id_sesion = p_id_sesion)
          AND (
              p_buscar = ''
              OR LOWER(COALESCE(g.concepto, '')) LIKE LOWER('%' || p_buscar || '%')
              OR LOWER(COALESCE(g.observacion, '')) LIKE LOWER('%' || p_buscar || '%')
              OR LOWER(COALESCE(g.numero_operacion, '')) LIKE LOWER('%' || p_buscar || '%')
          )
    )
    SELECT json_build_object(
        'total', (SELECT COUNT(*) FROM filtrado),
        'resumen', json_build_object(
            'total', (SELECT COALESCE(SUM(f.monto), 0) FROM filtrado f)
        ),
        'registros', COALESCE((
            SELECT json_agg(row_to_json(p) ORDER BY p.fecha DESC, p.id DESC)
            FROM (
                SELECT
                    f.id,
                    f.fecha,
                    f.concepto,
                    f.monto,
                    f.id_medio_pago AS "idMedioPago",
                    mp.nombre AS "medioPago",
                    f.id_categoria_gasto AS "idCategoriaGasto",
                    cat.nombre AS "categoriaGasto",
                    f.numero_operacion AS "numeroOperacion",
                    f.observacion,
                    f.id_sesion AS "idSesion",
                    f.estado
                FROM filtrado f
                LEFT JOIN gen_lista_opciones mp ON mp.id = f.id_medio_pago
                LEFT JOIN gen_lista_opciones cat ON cat.id = f.id_categoria_gasto
                ORDER BY f.fecha DESC, f.id DESC
                LIMIT p_limite
                OFFSET p_offset
            ) p
        ), '[]'::json)
    )
    INTO v_result;

    RETURN v_result;
END;
$$;


--
-- Name: fin_listar_caja_pendiente_cierre(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fin_listar_caja_pendiente_cierre(p_id_sucursal integer DEFAULT NULL::integer) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_registros JSON;
BEGIN
    SET TIME ZONE 'America/Lima';

    SELECT COALESCE(json_agg(row_to_json(t) ORDER BY t.fecha ASC, t.id ASC), '[]'::json)
    INTO v_registros
    FROM (
        SELECT
            s.id,
            s.fecha,
            s.id_sucursal AS "idSucursal",
            suc.nombre AS "nombreSucursal",
            est.nombre AS "estadoCaja",
            s.monto_inicial AS "montoInicial",
            s.fecha_apertura AS "fechaApertura",
            ua.nombre AS "usuarioApertura",
            (CURRENT_DATE - s.fecha) AS "diasAbierta"
        FROM fin_caja_sesion s
        INNER JOIN gen_lista_opciones est ON est.id = s.id_estado
        LEFT JOIN gen_sucursal suc ON suc.id = s.id_sucursal
        LEFT JOIN auth_usuarios ua ON ua.id = s.id_usuario_apertura
        WHERE s.estado = 1
          AND UPPER(est.nombre) = 'ABIERTA'
          AND s.fecha < CURRENT_DATE
          AND (p_id_sucursal IS NULL OR s.id_sucursal = p_id_sucursal)
    ) t;

    RETURN json_build_object('registros', v_registros, 'total', jsonb_array_length(v_registros::jsonb));
END;
$$;


--
-- Name: fin_listar_caja_sesiones(date, date, integer, character varying, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fin_listar_caja_sesiones(p_fecha_desde date DEFAULT NULL::date, p_fecha_hasta date DEFAULT NULL::date, p_id_sucursal integer DEFAULT NULL::integer, p_estado_caja character varying DEFAULT NULL::character varying, p_limite integer DEFAULT 20, p_offset integer DEFAULT 0) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_registros JSON;
    v_total BIGINT;
BEGIN
    SET TIME ZONE 'America/Lima';

    SELECT COUNT(*) INTO v_total
    FROM fin_caja_sesion s
    LEFT JOIN gen_lista_opciones est ON est.id = s.id_estado
    WHERE s.estado = 1
      AND (p_fecha_desde IS NULL OR s.fecha >= p_fecha_desde)
      AND (p_fecha_hasta IS NULL OR s.fecha <= p_fecha_hasta)
      AND (p_id_sucursal IS NULL OR s.id_sucursal = p_id_sucursal)
      AND (p_estado_caja IS NULL OR UPPER(est.nombre) = UPPER(p_estado_caja));

    SELECT COALESCE(json_agg(row_to_json(t)), '[]'::json) INTO v_registros
    FROM (
        SELECT
            s.id,
            s.fecha,
            s.id_sucursal AS "idSucursal",
            suc.nombre AS "nombreSucursal",
            est.nombre AS "estadoCaja",
            s.monto_inicial AS "montoInicial",
            s.monto_efectivo_contado AS "montoEfectivoContado",
            s.monto_esperado AS "montoEsperado",
            s.diferencia,
            s.fecha_apertura AS "fechaApertura",
            s.fecha_cierre AS "fechaCierre",
            ua.nombre AS "usuarioApertura",
            uc.nombre AS "usuarioCierre"
        FROM fin_caja_sesion s
        LEFT JOIN gen_sucursal suc ON suc.id = s.id_sucursal
        LEFT JOIN gen_lista_opciones est ON est.id = s.id_estado
        LEFT JOIN auth_usuarios ua ON ua.id = s.id_usuario_apertura
        LEFT JOIN auth_usuarios uc ON uc.id = s.id_usuario_cierre
        WHERE s.estado = 1
          AND (p_fecha_desde IS NULL OR s.fecha >= p_fecha_desde)
          AND (p_fecha_hasta IS NULL OR s.fecha <= p_fecha_hasta)
          AND (p_id_sucursal IS NULL OR s.id_sucursal = p_id_sucursal)
          AND (p_estado_caja IS NULL OR UPPER(est.nombre) = UPPER(p_estado_caja))
        ORDER BY s.fecha DESC, s.id DESC
        LIMIT GREATEST(COALESCE(p_limite, 20), 1)
        OFFSET GREATEST(COALESCE(p_offset, 0), 0)
    ) t;

    RETURN json_build_object('registros', v_registros, 'total', v_total);
END;
$$;


--
-- Name: fin_listar_cuentas(character varying, integer, character varying, integer, character varying, integer, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fin_listar_cuentas(p_tipo character varying DEFAULT NULL::character varying, p_id_tercero integer DEFAULT NULL::integer, p_estado character varying DEFAULT NULL::character varying, p_solo_pendientes integer DEFAULT NULL::integer, p_buscar character varying DEFAULT NULL::character varying, p_id_padre integer DEFAULT NULL::integer, p_limite integer DEFAULT 10, p_offset integer DEFAULT 0) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_resultado JSON;
    v_buscar    VARCHAR;
    v_id_tipo   INT;
BEGIN
    SET TIME ZONE 'America/Lima';

    v_buscar := NULLIF(TRIM(p_buscar), '');

    SELECT glo.id INTO v_id_tipo
    FROM gen_lista_opciones glo
    JOIN gen_lista gl ON gl.id = glo.id_lista
    WHERE gl.nombre = 'TipoCuentaFinanciera'
      AND glo.nombre = UPPER(p_tipo)
    LIMIT 1;

    WITH base AS (
        SELECT
            fc.id,
            fc.id_tipo_cuenta,
            UPPER(p_tipo) AS tipo,
            fc.id_tercero,
            fc.tercero_nombre,
            COALESCE(
                NULLIF(TRIM(ter.razon_social), ''),
                NULLIF(TRIM(CONCAT_WS(' ', ter.nombres, ter.apellido_paterno, ter.apellido_materno)), ''),
                fc.tercero_nombre,
                'Tercero #' || fc.id
            ) AS tercero,
            ter.numero_documento AS documento_tercero,
            fc.id_comprobante_venta,
            fc.id_comprobante_compra,
            fc.id_cuenta_padre,
            fc.numero_cuota,
            fc.numero_cuotas_total,
            fc.descripcion,
            fc.id_banco,
            fc.tasa_interes,
            fc.numero_comprobante,
            COALESCE(
                NULLIF(CONCAT_WS('-', vc.serie, vc.numero), '-'),
                NULLIF(CONCAT_WS('-', cc.serie, cc.numero), '-'),
                fc.numero_comprobante
            ) AS comprobante,
            fc.fecha_emision,
            fc.fecha_vencimiento,
            fin_redondear_monto(fc.monto_pendiente) AS monto_pendiente,
            fin_redondear_monto(COALESCE(fc.monto_abonado, 0)) AS monto_abonado,
            fin_redondear_monto(COALESCE(fc.monto_saldo, fc.monto_pendiente - COALESCE(fc.monto_abonado, 0))) AS saldo,
            fc.observacion,
            -- Indica si es cabecera de un plan de cuotas
            (fc.numero_cuotas_total IS NOT NULL) AS es_plan
        FROM fin_cuenta fc
        LEFT JOIN cli_clientes ter ON ter.id = fc.id_tercero
        LEFT JOIN ven_comprobante vc ON vc.id = fc.id_comprobante_venta
        LEFT JOIN com_comprobante_compra cc ON cc.id = fc.id_comprobante_compra
        WHERE fc.estado = 1
          AND (v_id_tipo IS NULL OR fc.id_tipo_cuenta = v_id_tipo)
          AND (p_id_tercero IS NULL OR fc.id_tercero = p_id_tercero)
          -- Alcance: si p_id_padre viene, listar hijas; si no, solo primer nivel
          AND (
                (p_id_padre IS NULL AND fc.id_cuenta_padre IS NULL)
             OR (p_id_padre IS NOT NULL AND fc.id_cuenta_padre = p_id_padre)
          )
    ),
    calculado AS (
        SELECT b.*,
            fin_estado_cuenta_calculado(b.saldo, b.monto_abonado, b.fecha_vencimiento) AS estado_calculado,
            CASE
                WHEN b.saldo > 0
                     AND b.fecha_vencimiento IS NOT NULL
                     AND b.fecha_vencimiento < CURRENT_DATE
                    THEN (CURRENT_DATE - b.fecha_vencimiento)
                ELSE 0
            END AS dias_vencido
        FROM base b
    ),
    filtrados AS (
        SELECT * FROM calculado c
        WHERE (p_estado IS NULL OR c.estado_calculado = UPPER(p_estado))
          AND (p_solo_pendientes IS NULL OR p_solo_pendientes <> 1 OR c.saldo > 0)
          AND (
                v_buscar IS NULL
                OR c.tercero ILIKE '%' || v_buscar || '%'
                OR c.documento_tercero ILIKE '%' || v_buscar || '%'
                OR c.comprobante ILIKE '%' || v_buscar || '%'
                OR c.descripcion ILIKE '%' || v_buscar || '%'
              )
    ),
    total_count AS (
        SELECT COUNT(*) AS total FROM filtrados
    ),
    paginados AS (
        SELECT * FROM filtrados
        ORDER BY
            COALESCE(numero_cuota, 0),
            (fecha_vencimiento IS NULL),
            fecha_vencimiento ASC,
            id DESC
        LIMIT p_limite
        OFFSET p_offset
    )
    SELECT json_build_object(
        'total', COALESCE((SELECT total FROM total_count), 0),
        'registros', COALESCE((SELECT json_agg(row_to_json(p)) FROM paginados p), '[]'::json)
    ) INTO v_resultado;

    RETURN v_resultado;
END;
$$;


--
-- Name: fin_listar_garantias(character varying, integer, date, date, character varying, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fin_listar_garantias(p_buscar character varying DEFAULT NULL::character varying, p_id_cliente integer DEFAULT NULL::integer, p_desde date DEFAULT NULL::date, p_hasta date DEFAULT NULL::date, p_estado character varying DEFAULT NULL::character varying, p_limite integer DEFAULT 10, p_offset integer DEFAULT 0) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_resultado JSON;
    v_buscar    VARCHAR;
    v_id_estado_filtro INT;
BEGIN
    SET TIME ZONE 'America/Lima';
    v_buscar := NULLIF(TRIM(p_buscar), '');

    IF p_estado IS NOT NULL AND UPPER(p_estado) IN ('ACTIVA', 'DEVUELTA') THEN
        SELECT glo.id INTO v_id_estado_filtro
        FROM gen_lista_opciones glo
        JOIN gen_lista gl ON gl.id = glo.id_lista
        WHERE gl.nombre = 'EstadoGarantia' AND glo.nombre = UPPER(p_estado)
        LIMIT 1;
    END IF;

    WITH base AS (
        SELECT
            g.id, g.fecha,
            g.id_cliente,
            COALESCE(NULLIF(TRIM(c.razon_social), ''),
                     NULLIF(TRIM(CONCAT_WS(' ', c.nombres, c.apellido_paterno, c.apellido_materno)), ''),
                     'Cliente #' || g.id_cliente) AS cliente,
            c.numero_documento AS documento_cliente,
            g.id_medio_pago, mp.nombre AS medio_pago,
            g.importe, g.observacion,
            g.fecha_reembolso,
            g.id_medio_reembolso, mr.nombre AS medio_reembolso,
            g.observacion_reembolso,
            g.id_estado, est.nombre AS estado_texto,
            g.fecha_creacion
        FROM fin_garantia g
        JOIN cli_clientes c ON c.id = g.id_cliente
        LEFT JOIN gen_lista_opciones mp  ON mp.id = g.id_medio_pago
        LEFT JOIN gen_lista_opciones mr  ON mr.id = g.id_medio_reembolso
        LEFT JOIN gen_lista_opciones est ON est.id = g.id_estado
        WHERE g.estado = 1
          AND (p_id_cliente IS NULL OR g.id_cliente = p_id_cliente)
          AND (p_desde IS NULL OR g.fecha >= p_desde)
          AND (p_hasta IS NULL OR g.fecha <= p_hasta)
          AND (v_id_estado_filtro IS NULL OR g.id_estado = v_id_estado_filtro)
          AND (
                v_buscar IS NULL
                OR c.razon_social ILIKE '%' || v_buscar || '%'
                OR c.nombres ILIKE '%' || v_buscar || '%'
                OR c.apellido_paterno ILIKE '%' || v_buscar || '%'
                OR c.apellido_materno ILIKE '%' || v_buscar || '%'
                OR c.numero_documento ILIKE '%' || v_buscar || '%'
                OR g.observacion ILIKE '%' || v_buscar || '%'
                OR g.observacion_reembolso ILIKE '%' || v_buscar || '%'
              )
    ),
    total_count AS (SELECT COUNT(*) AS total FROM base),
    paginados AS (
        SELECT * FROM base
        ORDER BY fecha DESC, id DESC
        LIMIT p_limite OFFSET p_offset
    )
    SELECT json_build_object(
        'total', COALESCE((SELECT total FROM total_count), 0),
        'registros', COALESCE((SELECT json_agg(row_to_json(p)) FROM paginados p), '[]'::json)
    ) INTO v_resultado;

    RETURN v_resultado;
END;
$$;


--
-- Name: fin_listar_medios_pago(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fin_listar_medios_pago() RETURNS json
    LANGUAGE sql STABLE
    AS $$
    SELECT COALESCE(
        json_agg(
            json_build_object('id', glo.id, 'nombre', glo.nombre)
            ORDER BY glo.id
        ),
        '[]'::json
    )
    FROM gen_lista_opciones glo
    JOIN gen_lista gl ON gl.id = glo.id_lista
    WHERE gl.nombre = 'MedioPago';
$$;


--
-- Name: fin_obtener_caja_dia(date, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fin_obtener_caja_dia(p_fecha date, p_id_sucursal integer DEFAULT NULL::integer) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_sesion_id INT;
    v_totales JSON;
    v_registro JSON;
BEGIN
    SET TIME ZONE 'America/Lima';

    IF p_fecha IS NULL THEN
        RETURN json_build_object('error', 'La fecha es obligatoria', 'registro', NULL);
    END IF;

    SELECT s.id INTO v_sesion_id
    FROM fin_caja_sesion s
    WHERE s.estado = 1
      AND s.fecha = p_fecha
      AND COALESCE(s.id_sucursal, 0) = COALESCE(p_id_sucursal, 0)
    LIMIT 1;

    v_totales := fin_caja_calcular_totales(p_fecha, p_id_sucursal);

    IF v_sesion_id IS NOT NULL THEN
        RETURN fin_obtener_caja_sesion(v_sesion_id);
    END IF;

    SELECT json_build_object(
        'id', NULL,
        'fecha', p_fecha,
        'idSucursal', p_id_sucursal,
        'estadoCaja', NULL,
        'montoInicial', 0,
        'totales', v_totales,
        'cajaEsperada',
            COALESCE((v_totales->>'ventasMediosCaja')::NUMERIC, 0)
            + COALESCE((v_totales->>'cobranzasMediosCaja')::NUMERIC, 0)
            + COALESCE((v_totales->>'garantiasCobroMediosCaja')::NUMERIC, 0)
            - COALESCE((v_totales->>'depositos')::NUMERIC, 0)
            - COALESCE((v_totales->>'gastosCaja')::NUMERIC, 0)
            - COALESCE((v_totales->>'garantiasDevolucionMediosCaja')::NUMERIC, 0)
    ) INTO v_registro;

    RETURN json_build_object('registro', v_registro);
END;
$$;


--
-- Name: fin_obtener_caja_sesion(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fin_obtener_caja_sesion(p_id integer) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_registro JSON;
    v_totales JSON;
    v_fecha DATE;
    v_id_sucursal INT;
    v_gastos JSON;
    v_depositos JSON;
BEGIN
    SET TIME ZONE 'America/Lima';

    SELECT s.fecha, s.id_sucursal INTO v_fecha, v_id_sucursal
    FROM fin_caja_sesion s WHERE s.id = p_id AND s.estado = 1;

    IF v_fecha IS NULL THEN
        RETURN json_build_object('error', 'Sesión no encontrada', 'registro', NULL);
    END IF;

    v_totales := fin_caja_calcular_totales(v_fecha, v_id_sucursal);

    SELECT COALESCE(json_agg(row_to_json(g) ORDER BY g.id), '[]'::JSON) INTO v_gastos
    FROM (
        SELECT
            cg.id,
            cg.fecha,
            cg.concepto,
            cg.monto,
            cg.id_medio_pago AS "idMedioPago",
            mp.nombre AS "medioPago",
            cg.numero_operacion AS "numeroOperacion",
            cg.observacion
        FROM fin_caja_gasto cg
        LEFT JOIN gen_lista_opciones mp ON mp.id = cg.id_medio_pago
        WHERE cg.estado = 1 AND cg.id_sesion = p_id
    ) g;

    SELECT COALESCE(json_agg(row_to_json(d) ORDER BY d.id), '[]'::JSON) INTO v_depositos
    FROM (
        SELECT
            cd.id,
            cd.fecha,
            cd.monto,
            cd.id_cuenta_bancaria AS "idCuentaBancaria",
            COALESCE(cb.titular, cb.numero_cuenta) AS "cuentaBancaria",
            cd.id_medio_pago AS "idMedioPago",
            mp.nombre AS "medioPago",
            cd.numero_operacion AS "numeroOperacion",
            cd.observacion
        FROM fin_caja_deposito cd
        LEFT JOIN gen_cuenta_bancaria cb ON cb.id = cd.id_cuenta_bancaria
        LEFT JOIN gen_lista_opciones mp ON mp.id = cd.id_medio_pago
        WHERE cd.estado = 1 AND cd.id_sesion = p_id
    ) d;

    SELECT row_to_json(t) INTO v_registro
    FROM (
        SELECT
            s.id,
            s.fecha,
            s.id_sucursal AS "idSucursal",
            suc.nombre AS "nombreSucursal",
            s.id_estado AS "idEstado",
            est.nombre AS "estadoCaja",
            s.monto_inicial AS "montoInicial",
            s.monto_efectivo_contado AS "montoEfectivoContado",
            s.monto_esperado AS "montoEsperado",
            s.diferencia,
            s.observacion_apertura AS "observacionApertura",
            s.observacion_cierre AS "observacionCierre",
            s.fecha_apertura AS "fechaApertura",
            s.fecha_cierre AS "fechaCierre",
            s.id_usuario_apertura AS "idUsuarioApertura",
            ua.nombre AS "usuarioApertura",
            s.id_usuario_cierre AS "idUsuarioCierre",
            uc.nombre AS "usuarioCierre",
            v_totales AS totales,
            v_gastos AS gastos,
            v_depositos AS depositos,
            (
                COALESCE(s.monto_inicial, 0)
                + COALESCE((v_totales->>'ventasMediosCaja')::NUMERIC, 0)
                + COALESCE((v_totales->>'cobranzasMediosCaja')::NUMERIC, 0)
                + COALESCE((v_totales->>'garantiasCobroMediosCaja')::NUMERIC, 0)
                - COALESCE((v_totales->>'depositos')::NUMERIC, 0)
                - COALESCE((v_totales->>'gastosCaja')::NUMERIC, 0)
                - COALESCE((v_totales->>'garantiasDevolucionMediosCaja')::NUMERIC, 0)
            ) AS "cajaEsperada"
        FROM fin_caja_sesion s
        LEFT JOIN gen_sucursal suc ON suc.id = s.id_sucursal
        LEFT JOIN gen_lista_opciones est ON est.id = s.id_estado
        LEFT JOIN auth_usuarios ua ON ua.id = s.id_usuario_apertura
        LEFT JOIN auth_usuarios uc ON uc.id = s.id_usuario_cierre
        WHERE s.id = p_id
    ) t;

    RETURN json_build_object('registro', v_registro);
END;
$$;


--
-- Name: fin_obtener_cuenta(integer, character varying); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fin_obtener_cuenta(p_id integer, p_tipo character varying DEFAULT NULL::character varying) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_registro JSON;
    v_id_tipo  INT;
BEGIN
    SET TIME ZONE 'America/Lima';

    IF p_tipo IS NOT NULL THEN
        SELECT glo.id INTO v_id_tipo
        FROM gen_lista_opciones glo
        JOIN gen_lista gl ON gl.id = glo.id_lista
        WHERE gl.nombre = 'TipoCuentaFinanciera'
          AND glo.nombre = UPPER(p_tipo)
        LIMIT 1;
    END IF;

    SELECT row_to_json(t) INTO v_registro
    FROM (
        SELECT
            fc.id,
            fc.id_tipo_cuenta,
            tcu.nombre AS tipo,
            fc.id_tercero,
            fc.tercero_nombre,
            COALESCE(
                NULLIF(TRIM(ter.razon_social), ''),
                NULLIF(TRIM(CONCAT_WS(' ', ter.nombres, ter.apellido_paterno, ter.apellido_materno)), ''),
                fc.tercero_nombre,
                'Tercero #' || fc.id
            ) AS tercero,
            ter.numero_documento AS documento_tercero,
            fc.id_comprobante_venta,
            fc.id_comprobante_compra,
            fc.id_cuenta_padre,
            fc.numero_cuota,
            fc.numero_cuotas_total,
            fc.descripcion,
            fc.id_banco,
            ban.nombre AS banco,
            fc.tasa_interes,
            fc.numero_comprobante,
            COALESCE(
                NULLIF(CONCAT_WS('-', vc.serie, vc.numero), '-'),
                NULLIF(CONCAT_WS('-', cc.serie, cc.numero), '-'),
                fc.numero_comprobante
            ) AS comprobante,
            fc.fecha_emision,
            fc.fecha_vencimiento,
            fin_redondear_monto(fc.monto_pendiente) AS monto_pendiente,
            fin_redondear_monto(COALESCE(fc.monto_abonado, 0)) AS monto_abonado,
            fin_redondear_monto(COALESCE(fc.monto_saldo, fc.monto_pendiente - COALESCE(fc.monto_abonado, 0))) AS saldo,
            fin_estado_cuenta_calculado(
                COALESCE(fc.monto_saldo, fc.monto_pendiente - COALESCE(fc.monto_abonado, 0)),
                COALESCE(fc.monto_abonado, 0),
                fc.fecha_vencimiento
            ) AS estado_calculado,
            fc.observacion,
            -- Cuotas hijas (solo cuando es cabecera de plan)
            (
                SELECT COALESCE(json_agg(
                    json_build_object(
                        'id', h.id,
                        'numeroCuota', h.numero_cuota,
                        'fechaVencimiento', h.fecha_vencimiento,
                        'montoPendiente', fin_redondear_monto(h.monto_pendiente),
                        'montoAbonado', fin_redondear_monto(COALESCE(h.monto_abonado, 0)),
                        'saldo', fin_redondear_monto(COALESCE(h.monto_saldo, h.monto_pendiente - COALESCE(h.monto_abonado, 0))),
                        'estadoCalculado',
                        fin_estado_cuenta_calculado(
                            COALESCE(h.monto_saldo, h.monto_pendiente - COALESCE(h.monto_abonado, 0)),
                            COALESCE(h.monto_abonado, 0),
                            h.fecha_vencimiento
                        )
                    ) ORDER BY h.numero_cuota
                ), '[]'::json)
                FROM fin_cuenta h
                WHERE h.id_cuenta_padre = fc.id AND h.estado = 1
            ) AS cuotas,
            -- Pagos aplicados directamente a esta cuenta
            COALESCE((
                SELECT json_agg(
                    json_build_object(
                        'id', p.id,
                        'fechaPago', p.fecha_pago,
                        'monto', p.monto,
                        'idMedioPago', p.id_medio_pago,
                        'medioPago', mp.nombre,
                        'idCuentaBancaria', p.id_cuenta_bancaria,
                        'numeroOperacion', p.numero_operacion,
                        'referencia', p.referencia,
                        'observacion', p.observacion,
                        'fechaCreacion', p.fecha_creacion
                    )
                    ORDER BY p.fecha_pago DESC, p.id DESC
                )
                FROM fin_pago p
                LEFT JOIN gen_lista_opciones mp ON mp.id = p.id_medio_pago
                WHERE p.id_cuenta = fc.id AND p.estado = 1
            ), '[]'::json) AS pagos
        FROM fin_cuenta fc
        JOIN gen_lista_opciones tcu ON tcu.id = fc.id_tipo_cuenta
        LEFT JOIN cli_clientes ter ON ter.id = fc.id_tercero
        LEFT JOIN gen_lista_opciones ban ON ban.id = fc.id_banco
        LEFT JOIN ven_comprobante vc ON vc.id = fc.id_comprobante_venta
        LEFT JOIN com_comprobante_compra cc ON cc.id = fc.id_comprobante_compra
        WHERE fc.id = p_id
          AND fc.estado = 1
          AND (v_id_tipo IS NULL OR fc.id_tipo_cuenta = v_id_tipo)
    ) t;

    RETURN json_build_object('registro', v_registro);
END;
$$;


--
-- Name: fin_obtener_libro_diario(date, date, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fin_obtener_libro_diario(p_fecha_desde date, p_fecha_hasta date DEFAULT NULL::date, p_id_cliente integer DEFAULT NULL::integer, p_id_sucursal integer DEFAULT NULL::integer) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_hasta DATE;
    v_ventas JSON;
    v_cobranzas JSON;
    v_gastos JSON;
    v_depositos JSON;
    v_observaciones JSON;
    v_totales JSON;
    v_dias JSON;
BEGIN
    SET TIME ZONE 'America/Lima';

    IF p_fecha_desde IS NULL THEN
        RETURN json_build_object('error', 'fechaDesde es obligatoria', 'registro', NULL);
    END IF;

    v_hasta := COALESCE(p_fecha_hasta, p_fecha_desde);

    IF v_hasta < p_fecha_desde THEN
        RETURN json_build_object('error', 'fechaHasta no puede ser menor que fechaDesde', 'registro', NULL);
    END IF;

    -- Ventas
    SELECT COALESCE(json_agg(row_to_json(t) ORDER BY t.fecha, t.id), '[]'::json)
    INTO v_ventas
    FROM (
        SELECT
            c.id,
            c.fecha,
            tip.nombre AS "tipoComprobante",
            c.serie,
            c.numero,
            (c.serie || '-' || c.numero) AS "serieNumero",
            c.id_cliente AS "idCliente",
            COALESCE(
                NULLIF(TRIM(cli.razon_social), ''),
                TRIM(CONCAT_WS(' ', cli.nombres, cli.apellido_paterno, cli.apellido_materno))
            ) AS cliente,
            mp.nombre AS "medioPago",
            CASE WHEN UPPER(COALESCE(mp.nombre, '')) = 'CREDITO' THEN true ELSE false END AS "esCredito",
            c.total_importe AS "totalImporte",
            (
                SELECT string_agg(
                    COALESCE(d.descripcion, pr.nombre)
                    || CASE WHEN d.cantidad IS NOT NULL THEN ' × ' || TRIM(TO_CHAR(d.cantidad, 'FM999999990.####')) ELSE '' END
                    || CASE WHEN um.nombre IS NOT NULL THEN ' ' || um.nombre ELSE '' END,
                    '; '
                )
                FROM ven_comprobante_detalle d
                LEFT JOIN pro_producto pr ON pr.id = d.id_producto
                LEFT JOIN gen_lista_opciones um ON um.id = COALESCE(d.id_unidad_medida, pr.id_unidad_medida)
                WHERE d.id_comprobante = c.id AND d.estado = 1
            ) AS "detalleProductos"
        FROM ven_comprobante c
        LEFT JOIN gen_lista_opciones tip ON tip.id = c.id_tipo_comprobante
        LEFT JOIN gen_lista_opciones mp ON mp.id = c.id_medio_pago
        LEFT JOIN gen_lista_opciones est ON est.id = c.id_estado
        LEFT JOIN cli_clientes cli ON cli.id = c.id_cliente
        WHERE c.estado = 1
          AND c.fecha BETWEEN p_fecha_desde AND v_hasta
          AND (p_id_cliente IS NULL OR c.id_cliente = p_id_cliente)
          AND (p_id_sucursal IS NULL OR c.id_sucursal = p_id_sucursal OR c.id_sucursal IS NULL)
          AND COALESCE(UPPER(est.nombre), '') <> 'ANULADO'
          AND COALESCE(UPPER(tip.nombre), '') NOT IN ('NOTA_CREDITO', 'NOTA_DEBITO')
    ) t;

    -- Cobranzas
    SELECT COALESCE(json_agg(row_to_json(t) ORDER BY t."fechaPago", t.id), '[]'::json)
    INTO v_cobranzas
    FROM (
        SELECT
            p.id,
            p.fecha_pago AS "fechaPago",
            p.monto,
            mp.nombre AS "medioPago",
            p.numero_operacion AS "numeroOperacion",
            p.observacion,
            cu.id AS "idCuenta",
            COALESCE(
                NULLIF(TRIM(cu.tercero_nombre), ''),
                NULLIF(TRIM(cli.razon_social), ''),
                TRIM(CONCAT_WS(' ', cli.nombres, cli.apellido_paterno, cli.apellido_materno))
            ) AS cliente,
            cu.id_tercero AS "idCliente"
        FROM fin_pago p
        INNER JOIN fin_cuenta cu ON cu.id = p.id_cuenta AND cu.estado = 1
        INNER JOIN gen_lista_opciones tc ON tc.id = cu.id_tipo_cuenta
        LEFT JOIN gen_lista_opciones mp ON mp.id = p.id_medio_pago
        LEFT JOIN cli_clientes cli ON cli.id = cu.id_tercero
        WHERE p.estado = 1
          AND p.fecha_pago BETWEEN p_fecha_desde AND v_hasta
          AND UPPER(tc.nombre) = 'COBRAR'
          AND (p_id_cliente IS NULL OR cu.id_tercero = p_id_cliente)
    ) t;

    -- Gastos (caja menudos + compras tipo GASTO)
    SELECT COALESCE(json_agg(row_to_json(t) ORDER BY t.fecha, t.origen, t.id), '[]'::json)
    INTO v_gastos
    FROM (
        SELECT
            g.id,
            g.fecha,
            'CAJA'::text AS origen,
            g.concepto,
            g.monto,
            mp.nombre AS "medioPago",
            g.observacion
        FROM fin_caja_gasto g
        LEFT JOIN gen_lista_opciones mp ON mp.id = g.id_medio_pago
        WHERE g.estado = 1
          AND g.fecha BETWEEN p_fecha_desde AND v_hasta
        UNION ALL
        SELECT
            cc.id,
            cc.fecha,
            'COMPRA'::text AS origen,
            COALESCE(
                NULLIF(TRIM(cc.glosa), ''),
                NULLIF(TRIM(CONCAT_WS('-', cc.serie, cc.numero)), ''),
                'Gasto compra'
            ) AS concepto,
            cc.total_importe AS monto,
            NULL::varchar AS "medioPago",
            cc.glosa AS observacion
        FROM com_comprobante_compra cc
        LEFT JOIN gen_lista_opciones tr ON tr.id = cc.id_tipo_registro
        WHERE cc.estado = 1
          AND cc.fecha BETWEEN p_fecha_desde AND v_hasta
          AND UPPER(COALESCE(tr.nombre, '')) = 'GASTO'
    ) t;

    -- Depósitos
    SELECT COALESCE(json_agg(row_to_json(t) ORDER BY t.fecha, t.id), '[]'::json)
    INTO v_depositos
    FROM (
        SELECT
            d.id,
            d.fecha,
            d.monto,
            COALESCE(cb.titular, cb.numero_cuenta) AS "cuentaBancaria",
            mp.nombre AS "medioPago",
            d.numero_operacion AS "numeroOperacion",
            d.observacion
        FROM fin_caja_deposito d
        LEFT JOIN gen_cuenta_bancaria cb ON cb.id = d.id_cuenta_bancaria
        LEFT JOIN gen_lista_opciones mp ON mp.id = d.id_medio_pago
        WHERE d.estado = 1
          AND d.fecha BETWEEN p_fecha_desde AND v_hasta
    ) t;

    -- Observaciones
    SELECT COALESCE(json_agg(row_to_json(t) ORDER BY t.fecha, t.id), '[]'::json)
    INTO v_observaciones
    FROM (
        SELECT
            o.id,
            o.fecha,
            o.texto,
            u.nombre AS usuario,
            o.fecha_creacion AS "fechaCreacion"
        FROM fin_caja_observacion o
        LEFT JOIN auth_usuarios u ON u.id = o.id_usuario_creacion
        WHERE o.estado = 1
          AND o.fecha BETWEEN p_fecha_desde AND v_hasta
    ) t;

    -- Totales del rango (suma día a día cuando hay filtro sucursal; si no, una pasada)
    SELECT json_build_object(
        'ventasContado', COALESCE(SUM((t.tot->>'ventasContado')::NUMERIC), 0),
        'ventasCredito', COALESCE(SUM((t.tot->>'ventasCredito')::NUMERIC), 0),
        'ventasMediosCaja', COALESCE(SUM((t.tot->>'ventasMediosCaja')::NUMERIC), 0),
        'cobranzas', COALESCE(SUM((t.tot->>'cobranzas')::NUMERIC), 0),
        'cobranzasMediosCaja', COALESCE(SUM((t.tot->>'cobranzasMediosCaja')::NUMERIC), 0),
        'gastosCaja', COALESCE(SUM((t.tot->>'gastosCaja')::NUMERIC), 0),
        'gastosCompra', COALESCE(SUM((t.tot->>'gastosCompra')::NUMERIC), 0),
        'gastos', COALESCE(SUM((t.tot->>'gastos')::NUMERIC), 0),
        'depositos', COALESCE(SUM((t.tot->>'depositos')::NUMERIC), 0)
    )
    INTO v_totales
    FROM (
        SELECT fin_caja_calcular_totales(d::date, p_id_sucursal) AS tot
        FROM generate_series(p_fecha_desde, v_hasta, '1 day'::interval) d
    ) t;

    -- Desglose por día (útil en filtro mes)
    SELECT COALESCE(json_agg(row_to_json(x) ORDER BY x.fecha), '[]'::json)
    INTO v_dias
    FROM (
        SELECT
            d::date AS fecha,
            fin_caja_calcular_totales(d::date, p_id_sucursal) AS totales
        FROM generate_series(p_fecha_desde, v_hasta, '1 day'::interval) d
    ) x;

    RETURN json_build_object(
        'registro', json_build_object(
            'fechaDesde', p_fecha_desde,
            'fechaHasta', v_hasta,
            'idCliente', p_id_cliente,
            'idSucursal', p_id_sucursal,
            'ventas', v_ventas,
            'cobranzas', v_cobranzas,
            'gastos', v_gastos,
            'depositos', v_depositos,
            'observaciones', v_observaciones,
            'totales', v_totales,
            'dias', v_dias
        )
    );
END;
$$;


--
-- Name: fin_redondear_monto(numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fin_redondear_monto(p_monto numeric) RETURNS numeric
    LANGUAGE sql IMMUTABLE
    AS $$
    SELECT ROUND(COALESCE(p_monto, 0), 2)::NUMERIC(12,2);
$$;


--
-- Name: fin_reembolsar_garantia(integer, date, integer, character varying, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fin_reembolsar_garantia(p_id integer, p_fecha_reembolso date, p_id_medio_reembolso integer, p_observacion_reembolso character varying DEFAULT NULL::character varying, p_id_usuario integer DEFAULT NULL::integer) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_garantia  fin_garantia%ROWTYPE;
    v_id_devuelta INT;
    v_registro JSON;
BEGIN
    SET TIME ZONE 'America/Lima';

    SELECT * INTO v_garantia FROM fin_garantia WHERE id = p_id AND estado = 1;
    IF NOT FOUND THEN
        RETURN json_build_object('registro', NULL, 'error', 'La garantía no existe o está inactiva');
    END IF;

    IF v_garantia.fecha_reembolso IS NOT NULL THEN
        RETURN json_build_object('registro', NULL, 'error',
            'Esta garantía ya fue reembolsada el ' || to_char(v_garantia.fecha_reembolso, 'DD/MM/YYYY'));
    END IF;

    IF p_fecha_reembolso IS NULL THEN
        RETURN json_build_object('registro', NULL, 'error', 'La fecha del reembolso es obligatoria');
    END IF;

    IF p_fecha_reembolso < v_garantia.fecha THEN
        RETURN json_build_object('registro', NULL, 'error',
            format('La fecha del reembolso (%s) no puede ser anterior a la fecha de recepción de la garantía (%s)',
                to_char(p_fecha_reembolso, 'DD/MM/YYYY'),
                to_char(v_garantia.fecha, 'DD/MM/YYYY')));
    END IF;

    SELECT glo.id INTO v_id_devuelta
    FROM gen_lista_opciones glo
    JOIN gen_lista gl ON gl.id = glo.id_lista
    WHERE gl.nombre = 'EstadoGarantia' AND glo.nombre = 'DEVUELTA'
    LIMIT 1;

    UPDATE fin_garantia SET
        fecha_reembolso       = p_fecha_reembolso,
        id_medio_reembolso    = p_id_medio_reembolso,
        observacion_reembolso = NULLIF(TRIM(p_observacion_reembolso), ''),
        id_usuario_reembolso  = p_id_usuario,
        id_estado             = COALESCE(v_id_devuelta, id_estado),
        id_usuario_modificacion = p_id_usuario,
        fecha_modificacion    = NOW()
    WHERE id = p_id;

    SELECT row_to_json(t) INTO v_registro FROM (
        SELECT
            g.id, g.fecha,
            g.id_cliente,
            COALESCE(NULLIF(TRIM(c.razon_social), ''),
                     NULLIF(TRIM(CONCAT_WS(' ', c.nombres, c.apellido_paterno, c.apellido_materno)), ''),
                     'Cliente #' || g.id_cliente) AS cliente,
            c.numero_documento AS documento_cliente,
            g.id_medio_pago, mp.nombre AS medio_pago,
            g.importe, g.observacion,
            g.fecha_reembolso,
            g.id_medio_reembolso, mr.nombre AS medio_reembolso,
            g.observacion_reembolso,
            g.id_estado, est.nombre AS estado_texto
        FROM fin_garantia g
        JOIN cli_clientes c ON c.id = g.id_cliente
        LEFT JOIN gen_lista_opciones mp  ON mp.id = g.id_medio_pago
        LEFT JOIN gen_lista_opciones mr  ON mr.id = g.id_medio_reembolso
        LEFT JOIN gen_lista_opciones est ON est.id = g.id_estado
        WHERE g.id = p_id
    ) t;

    RETURN json_build_object('registro', v_registro);
END;
$$;


--
-- Name: fin_refrescar_cabecera_plan(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fin_refrescar_cabecera_plan(p_id_padre integer) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_pendiente        NUMERIC(12,2);
    v_total_abonado    NUMERIC(12,2);
    v_total_saldo      NUMERIC(12,2);
    v_hijas_pendientes INTEGER;
BEGIN
    IF p_id_padre IS NULL THEN
        RETURN;
    END IF;

    SELECT fin_redondear_monto(monto_pendiente)
    INTO v_pendiente
    FROM fin_cuenta
    WHERE id = p_id_padre AND estado = 1;

    IF v_pendiente IS NULL THEN
        RETURN;
    END IF;

    SELECT
        fin_redondear_monto(COALESCE(SUM(COALESCE(monto_abonado, 0)), 0)),
        fin_redondear_monto(COALESCE(SUM(COALESCE(
            monto_saldo,
            monto_pendiente - COALESCE(monto_abonado, 0)
        )), 0)),
        COUNT(*) FILTER (
            WHERE fin_redondear_monto(COALESCE(
                monto_saldo,
                monto_pendiente - COALESCE(monto_abonado, 0)
            )) > 0
        )
    INTO v_total_abonado, v_total_saldo, v_hijas_pendientes
    FROM fin_cuenta
    WHERE id_cuenta_padre = p_id_padre AND estado = 1;

    IF COALESCE(v_hijas_pendientes, 0) = 0 THEN
        v_total_abonado := v_pendiente;
        v_total_saldo := 0;
    END IF;

    UPDATE fin_cuenta
    SET
        monto_abonado = v_total_abonado,
        monto_saldo = v_total_saldo,
        fecha_modificacion = NOW()
    WHERE id = p_id_padre;
END;
$$;


--
-- Name: fin_registrar_pago(integer, character varying, date, numeric, integer, integer, character varying, character varying, character varying, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fin_registrar_pago(p_id_cuenta integer, p_tipo character varying, p_fecha_pago date DEFAULT NULL::date, p_monto numeric DEFAULT NULL::numeric, p_id_medio_pago integer DEFAULT NULL::integer, p_id_cuenta_bancaria integer DEFAULT NULL::integer, p_numero_operacion character varying DEFAULT NULL::character varying, p_referencia character varying DEFAULT NULL::character varying, p_observacion character varying DEFAULT NULL::character varying, p_id_usuario integer DEFAULT NULL::integer, p_id_sucursal integer DEFAULT NULL::integer) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_id_tipo     INT;
    v_cuenta      fin_cuenta%ROWTYPE;
    v_saldo       NUMERIC(12,2);
    v_monto       NUMERIC(12,2);
    v_nuevo_saldo NUMERIC(12,2);
    v_id_pago     INT;
    v_err_caja TEXT;
    v_id_sucursal INT;
BEGIN
    SET TIME ZONE 'America/Lima';

    v_id_sucursal := COALESCE(p_id_sucursal, fin_sucursal_de_cuenta(p_id_cuenta));

    v_err_caja := fin_caja_assert_abierta(COALESCE(p_fecha_pago, CURRENT_DATE), v_id_sucursal);
    IF v_err_caja IS NOT NULL THEN
        RETURN json_build_object('registro', NULL, 'error', v_err_caja);
    END IF;

    SELECT glo.id INTO v_id_tipo
    FROM gen_lista_opciones glo
    JOIN gen_lista gl ON gl.id = glo.id_lista
    WHERE gl.nombre = 'TipoCuentaFinanciera'
      AND glo.nombre = UPPER(p_tipo)
    LIMIT 1;

    SELECT * INTO v_cuenta FROM fin_cuenta WHERE id = p_id_cuenta AND estado = 1;
    IF NOT FOUND THEN
        RETURN json_build_object('registro', NULL, 'error', 'La cuenta no existe o está inactiva');
    END IF;

    IF v_id_tipo IS NOT NULL AND v_cuenta.id_tipo_cuenta <> v_id_tipo THEN
        RETURN json_build_object('registro', NULL, 'error', 'La cuenta no corresponde al tipo indicado');
    END IF;

    -- No permitir pagar directamente contra la cabecera de un plan de cuotas
    IF v_cuenta.numero_cuotas_total IS NOT NULL THEN
        RETURN json_build_object('registro', NULL, 'error',
            'Esta cuenta es un plan de cuotas: registra el pago sobre la cuota correspondiente');
    END IF;

    v_saldo := fin_redondear_monto(
        COALESCE(v_cuenta.monto_saldo, v_cuenta.monto_pendiente - COALESCE(v_cuenta.monto_abonado, 0))
    );
    v_monto := fin_redondear_monto(p_monto);

    IF v_monto IS NULL OR v_monto <= 0 THEN
        RETURN json_build_object('registro', NULL, 'error', 'El monto debe ser mayor a cero');
    END IF;

    IF v_monto > v_saldo THEN
        RETURN json_build_object('registro', NULL, 'error', 'El monto excede el saldo pendiente');
    END IF;

    -- La fecha de pago no puede ser anterior a la emisión de la cuenta
    IF COALESCE(p_fecha_pago, CURRENT_DATE) < v_cuenta.fecha_emision THEN
        RETURN json_build_object(
            'registro', NULL,
            'error', format(
                'La fecha del pago (%s) no puede ser anterior a la fecha de emisión de la cuenta (%s)',
                to_char(COALESCE(p_fecha_pago, CURRENT_DATE), 'DD/MM/YYYY'),
                to_char(v_cuenta.fecha_emision, 'DD/MM/YYYY')
            )
        );
    END IF;

    INSERT INTO fin_pago (
        id_cuenta, fecha_pago, monto,
        id_medio_pago, id_cuenta_bancaria, numero_operacion,
        referencia, observacion, id_sucursal, id_usuario_creacion
    ) VALUES (
        p_id_cuenta,
        COALESCE(p_fecha_pago, CURRENT_DATE),
        v_monto,
        p_id_medio_pago,
        p_id_cuenta_bancaria,
        NULLIF(TRIM(p_numero_operacion), ''),
        NULLIF(TRIM(p_referencia), ''),
        NULLIF(TRIM(p_observacion), ''),
        v_id_sucursal,
        p_id_usuario
    )
    RETURNING id INTO v_id_pago;

    v_nuevo_saldo := fin_redondear_monto(v_saldo - v_monto);

    IF v_nuevo_saldo <= 0 THEN
        UPDATE fin_cuenta
           SET monto_abonado = fin_redondear_monto(monto_pendiente),
               monto_saldo   = 0,
               id_usuario_modificacion = p_id_usuario,
               fecha_modificacion = NOW()
         WHERE id = p_id_cuenta;
        v_nuevo_saldo := 0;
    ELSE
        UPDATE fin_cuenta
           SET monto_abonado = fin_redondear_monto(COALESCE(monto_abonado, 0) + v_monto),
               monto_saldo   = v_nuevo_saldo,
               id_usuario_modificacion = p_id_usuario,
               fecha_modificacion = NOW()
         WHERE id = p_id_cuenta;
    END IF;

    IF v_cuenta.id_cuenta_padre IS NOT NULL THEN
        PERFORM fin_refrescar_cabecera_plan(v_cuenta.id_cuenta_padre);
    END IF;

    RETURN json_build_object(
        'registro', json_build_object(
            'id', v_id_pago,
            'idCuenta', p_id_cuenta,
            'monto', v_monto,
            'saldoRestante', v_nuevo_saldo
        )
    );
END;
$$;


--
-- Name: fin_resumen_cuentas(character varying); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fin_resumen_cuentas(p_tipo character varying) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_id_tipo INT;
    v_res     JSON;
BEGIN
    SET TIME ZONE 'America/Lima';

    SELECT glo.id INTO v_id_tipo
    FROM gen_lista_opciones glo
    JOIN gen_lista gl ON gl.id = glo.id_lista
    WHERE gl.nombre = 'TipoCuentaFinanciera'
      AND glo.nombre = UPPER(p_tipo)
    LIMIT 1;

    -- Excluimos las CABECERAS de planes de cuotas para no contar doble
    -- (su monto_pendiente ya está distribuido en las cuotas hijas).
    WITH c AS (
        SELECT
            COALESCE(fc.id_tercero::text, fc.tercero_nombre) AS tercero_key,
            fin_redondear_monto(COALESCE(fc.monto_saldo, fc.monto_pendiente - COALESCE(fc.monto_abonado, 0))) AS saldo,
            fc.fecha_vencimiento
        FROM fin_cuenta fc
        WHERE fc.estado = 1
          AND (v_id_tipo IS NULL OR fc.id_tipo_cuenta = v_id_tipo)
          AND fc.numero_cuotas_total IS NULL
    )
    SELECT json_build_object(
        'totalPendiente',   COALESCE(SUM(saldo) FILTER (WHERE saldo > 0), 0),
        'cantidadCuentas',  COUNT(*) FILTER (WHERE saldo > 0),
        'totalVencido',     COALESCE(SUM(saldo) FILTER (WHERE saldo > 0 AND fecha_vencimiento IS NOT NULL AND fecha_vencimiento < CURRENT_DATE), 0),
        'cantidadVencidas', COUNT(*) FILTER (WHERE saldo > 0 AND fecha_vencimiento IS NOT NULL AND fecha_vencimiento < CURRENT_DATE),
        'cantidadTerceros', COUNT(DISTINCT tercero_key) FILTER (WHERE saldo > 0)
    ) INTO v_res
    FROM c;

    RETURN v_res;
END;
$$;


--
-- Name: fin_saldos_por_tercero(character varying, date, character varying, integer, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fin_saldos_por_tercero(p_tipo character varying DEFAULT 'COBRAR'::character varying, p_fecha_corte date DEFAULT CURRENT_DATE, p_buscar character varying DEFAULT NULL::character varying, p_solo_pendientes integer DEFAULT 1, p_limite integer DEFAULT 50, p_offset integer DEFAULT 0) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_id_tipo   INT;
    v_buscar    VARCHAR;
    v_corte     DATE;
    v_registros JSON;
    v_total     BIGINT;
    v_resumen   JSON;
BEGIN
    SET TIME ZONE 'America/Lima';

    v_buscar := NULLIF(TRIM(COALESCE(p_buscar, '')), '');
    v_corte  := COALESCE(p_fecha_corte, CURRENT_DATE);

    SELECT glo.id INTO v_id_tipo
    FROM gen_lista_opciones glo
    JOIN gen_lista gl ON gl.id = glo.id_lista
    WHERE gl.nombre = 'TipoCuentaFinanciera'
      AND glo.nombre = UPPER(p_tipo)
    LIMIT 1;

    WITH cuentas AS (
        SELECT
            fc.id,
            fc.id_tercero,
            COALESCE(
                NULLIF(TRIM(ter.razon_social), ''),
                NULLIF(TRIM(CONCAT_WS(' ', ter.nombres, ter.apellido_paterno, ter.apellido_materno)), ''),
                fc.tercero_nombre,
                'Tercero #' || fc.id
            ) AS tercero,
            ter.numero_documento AS documento_tercero,
            COALESCE(fc.id_tercero::text, LOWER(TRIM(COALESCE(fc.tercero_nombre, '')))) AS tercero_key,
            fc.monto_pendiente::NUMERIC AS debe,
            COALESCE((
                SELECT SUM(p.monto)
                FROM fin_pago p
                WHERE p.id_cuenta = fc.id
                  AND p.estado = 1
                  AND p.fecha_pago <= v_corte
            ), 0)::NUMERIC AS abonado
        FROM fin_cuenta fc
        LEFT JOIN cli_clientes ter ON ter.id = fc.id_tercero
        WHERE fc.estado = 1
          AND (v_id_tipo IS NULL OR fc.id_tipo_cuenta = v_id_tipo)
          AND fc.numero_cuotas_total IS NULL
          AND (fc.fecha_emision IS NULL OR fc.fecha_emision <= v_corte)
          AND (
              v_buscar IS NULL
              OR gen_texto_coincide(COALESCE(ter.razon_social, ''), v_buscar)
              OR gen_texto_coincide(COALESCE(ter.nombres, ''), v_buscar)
              OR gen_texto_coincide(COALESCE(fc.tercero_nombre, ''), v_buscar)
              OR gen_texto_coincide(COALESCE(ter.numero_documento, ''), v_buscar)
              OR gen_texto_coincide(COALESCE(fc.numero_comprobante, ''), v_buscar)
          )
    ),
    por_cuenta AS (
        SELECT
            *,
            GREATEST(debe - abonado, 0)::NUMERIC AS saldo
        FROM cuentas
    ),
    agrupado AS (
        SELECT
            MAX(id_tercero) AS id_tercero,
            MAX(tercero) AS tercero,
            MAX(documento_tercero) AS documento_tercero,
            tercero_key,
            COUNT(*)::INT AS cantidad_cuentas,
            SUM(debe)::NUMERIC AS debe,
            SUM(abonado)::NUMERIC AS abonado,
            SUM(saldo)::NUMERIC AS saldo
        FROM por_cuenta
        GROUP BY tercero_key
    ),
    filtrado AS (
        SELECT *
        FROM agrupado
        WHERE COALESCE(p_solo_pendientes, 1) = 0
           OR saldo > 0
    ),
    agregado AS (
        SELECT
            (SELECT COUNT(*) FROM filtrado) AS total,
            (
                SELECT COALESCE(json_agg(row_to_json(t)), '[]'::JSON)
                FROM (
                    SELECT
                        id_tercero,
                        tercero,
                        documento_tercero,
                        cantidad_cuentas,
                        debe,
                        abonado,
                        saldo
                    FROM filtrado
                    ORDER BY saldo DESC, tercero ASC
                    LIMIT GREATEST(COALESCE(p_limite, 50), 1)
                    OFFSET GREATEST(COALESCE(p_offset, 0), 0)
                ) t
            ) AS registros,
            (
                SELECT json_build_object(
                    'fechaCorte', v_corte,
                    'totalDebe', COALESCE(SUM(debe), 0),
                    'totalAbonado', COALESCE(SUM(abonado), 0),
                    'totalSaldo', COALESCE(SUM(saldo), 0),
                    'cantidadTerceros', COUNT(*)
                )
                FROM filtrado
            ) AS resumen
    )
    SELECT a.total, a.registros, a.resumen
    INTO v_total, v_registros, v_resumen
    FROM agregado a;

    RETURN json_build_object(
        'registros', COALESCE(v_registros, '[]'::JSON),
        'total', COALESCE(v_total, 0),
        'resumen', COALESCE(
            v_resumen,
            json_build_object(
                'fechaCorte', v_corte,
                'totalDebe', 0,
                'totalAbonado', 0,
                'totalSaldo', 0,
                'cantidadTerceros', 0
            )
        )
    );
END;
$$;


--
-- Name: fin_sucursal_de_cuenta(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fin_sucursal_de_cuenta(p_id_cuenta integer) RETURNS integer
    LANGUAGE sql STABLE
    AS $$
    SELECT COALESCE(
        vc.id_sucursal,
        vc_padre.id_sucursal,
        cc.id_sucursal,
        cc_padre.id_sucursal
    )
    FROM fin_cuenta fc
    LEFT JOIN ven_comprobante vc ON vc.id = fc.id_comprobante_venta
    LEFT JOIN fin_cuenta fp ON fp.id = fc.id_cuenta_padre
    LEFT JOIN ven_comprobante vc_padre ON vc_padre.id = fp.id_comprobante_venta
    LEFT JOIN com_comprobante_compra cc ON cc.id = fc.id_comprobante_compra
    LEFT JOIN com_comprobante_compra cc_padre ON cc_padre.id = fp.id_comprobante_compra
    WHERE fc.id = p_id_cuenta;
$$;


--
-- Name: fin_verificar_duplicado_pago(integer, date, numeric, integer, character varying); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fin_verificar_duplicado_pago(p_id_cuenta integer, p_fecha_pago date, p_monto numeric, p_dias_ventana integer DEFAULT 7, p_numero_comprobante character varying DEFAULT NULL::character varying) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_cuenta           fin_cuenta%ROWTYPE;
    v_id_tercero       INT;
    v_tercero_nombre   VARCHAR;
    v_comp             VARCHAR;
    v_pago_factura     RECORD;
    v_pago_exacto      RECORD;
    v_pago_probable    RECORD;
BEGIN
    SET TIME ZONE 'America/Lima';

    SELECT * INTO v_cuenta FROM fin_cuenta WHERE id = p_id_cuenta AND estado = 1;
    IF NOT FOUND THEN
        RETURN json_build_object('duplicado', false);
    END IF;

    v_id_tercero     := v_cuenta.id_tercero;
    v_tercero_nombre := v_cuenta.tercero_nombre;
    v_comp := NULLIF(TRIM(COALESCE(
        NULLIF(TRIM(p_numero_comprobante), ''),
        (
            SELECT NULLIF(CONCAT_WS('-', vc.serie, vc.numero), '-')
            FROM ven_comprobante vc
            WHERE vc.id = v_cuenta.id_comprobante_venta
        ),
        (
            SELECT NULLIF(CONCAT_WS('-', cc.serie, cc.numero), '-')
            FROM com_comprobante_compra cc
            WHERE cc.id = v_cuenta.id_comprobante_compra
        ),
        v_cuenta.numero_comprobante
    )), '');

    -- 1) MISMO COMPROBANTE al mismo tercero (independiente del monto) → alta
    IF v_comp IS NOT NULL THEN
        SELECT
            p.id,
            p.fecha_pago,
            p.monto,
            COALESCE(
                NULLIF(CONCAT_WS('-', vc.serie, vc.numero), '-'),
                NULLIF(CONCAT_WS('-', cc.serie, cc.numero), '-'),
                c.numero_comprobante
            ) AS numero_comprobante,
            c.id AS id_cuenta
          INTO v_pago_factura
        FROM fin_pago p
        JOIN fin_cuenta c ON c.id = p.id_cuenta
        LEFT JOIN ven_comprobante vc ON vc.id = c.id_comprobante_venta
        LEFT JOIN com_comprobante_compra cc ON cc.id = c.id_comprobante_compra
        WHERE p.estado = 1
          AND c.estado = 1
          AND (
            (v_id_tercero IS NOT NULL AND c.id_tercero = v_id_tercero)
            OR (v_id_tercero IS NULL AND v_tercero_nombre IS NOT NULL AND c.tercero_nombre = v_tercero_nombre)
          )
          AND UPPER(REPLACE(COALESCE(
                NULLIF(CONCAT_WS('-', vc.serie, vc.numero), '-'),
                NULLIF(CONCAT_WS('-', cc.serie, cc.numero), '-'),
                c.numero_comprobante,
                ''
              ), ' ', '')) = UPPER(REPLACE(v_comp, ' ', ''))
        ORDER BY p.id DESC
        LIMIT 1;

        IF v_pago_factura.id IS NOT NULL THEN
            RETURN json_build_object(
                'duplicado', true,
                'severidad', 'alta',
                'mensaje', format(
                    'Ya hay un pago registrado para el mismo comprobante (%s) de este tercero el %s por %s.',
                    v_comp,
                    to_char(v_pago_factura.fecha_pago, 'DD/MM/YYYY'),
                    to_char(v_pago_factura.monto, 'FM999,999,990.00')
                ),
                'pagoExistente', json_build_object(
                    'id', v_pago_factura.id,
                    'idCuenta', v_pago_factura.id_cuenta,
                    'fechaPago', v_pago_factura.fecha_pago,
                    'monto', v_pago_factura.monto,
                    'numeroComprobante', v_pago_factura.numero_comprobante
                )
            );
        END IF;
    END IF;

    -- 2) DUPLICADO EXACTO: mismo tercero + monto + fecha
    SELECT p.id, p.fecha_pago, p.monto, c.numero_comprobante, c.id AS id_cuenta
      INTO v_pago_exacto
    FROM fin_pago p
    JOIN fin_cuenta c ON c.id = p.id_cuenta
    WHERE p.estado = 1
      AND p.fecha_pago = p_fecha_pago
      AND ABS(p.monto - p_monto) < 0.0001
      AND (
        (v_id_tercero IS NOT NULL AND c.id_tercero = v_id_tercero)
        OR (v_id_tercero IS NULL AND v_tercero_nombre IS NOT NULL AND c.tercero_nombre = v_tercero_nombre)
      )
    ORDER BY p.id DESC
    LIMIT 1;

    IF v_pago_exacto.id IS NOT NULL THEN
        RETURN json_build_object(
            'duplicado', true,
            'severidad', 'alta',
            'mensaje', format(
                'Ya existe un pago del mismo monto (%s) en la misma fecha (%s) para este tercero.',
                to_char(p_monto, 'FM999,999,990.00'),
                to_char(p_fecha_pago, 'DD/MM/YYYY')
            ),
            'pagoExistente', json_build_object(
                'id', v_pago_exacto.id,
                'idCuenta', v_pago_exacto.id_cuenta,
                'fechaPago', v_pago_exacto.fecha_pago,
                'monto', v_pago_exacto.monto,
                'numeroComprobante', v_pago_exacto.numero_comprobante
            )
        );
    END IF;

    -- 3) DUPLICADO PROBABLE: mismo tercero + mismo monto en la ventana de días
    SELECT p.id, p.fecha_pago, p.monto, c.id AS id_cuenta
      INTO v_pago_probable
    FROM fin_pago p
    JOIN fin_cuenta c ON c.id = p.id_cuenta
    WHERE p.estado = 1
      AND ABS(p.monto - p_monto) < 0.0001
      AND p.fecha_pago BETWEEN (p_fecha_pago - COALESCE(p_dias_ventana, 7))
                          AND (p_fecha_pago + COALESCE(p_dias_ventana, 7))
      AND (
        (v_id_tercero IS NOT NULL AND c.id_tercero = v_id_tercero)
        OR (v_id_tercero IS NULL AND v_tercero_nombre IS NOT NULL AND c.tercero_nombre = v_tercero_nombre)
      )
    ORDER BY p.fecha_pago DESC, p.id DESC
    LIMIT 1;

    IF v_pago_probable.id IS NOT NULL THEN
        RETURN json_build_object(
            'duplicado', true,
            'severidad', 'media',
            'mensaje', format(
                'A este tercero se le registró un pago por %s el %s. ¿Confirmas que no es el mismo pago?',
                to_char(p_monto, 'FM999,999,990.00'),
                to_char(v_pago_probable.fecha_pago, 'DD/MM/YYYY')
            ),
            'pagoExistente', json_build_object(
                'id', v_pago_probable.id,
                'idCuenta', v_pago_probable.id_cuenta,
                'fechaPago', v_pago_probable.fecha_pago,
                'monto', v_pago_probable.monto
            )
        );
    END IF;

    RETURN json_build_object('duplicado', false);
END;
$$;


--
-- Name: gen_actualizar_almacen(integer, integer, character varying, character varying, character varying, integer, integer, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gen_actualizar_almacen(p_id integer, p_id_sucursal integer DEFAULT NULL::integer, p_nombre character varying DEFAULT NULL::character varying, p_ubicacion character varying DEFAULT NULL::character varying, p_descripcion character varying DEFAULT NULL::character varying, p_id_departamento integer DEFAULT NULL::integer, p_id_provincia integer DEFAULT NULL::integer, p_id_distrito integer DEFAULT NULL::integer, p_id_usuario_auditoria integer DEFAULT NULL::integer) RETURNS json
    LANGUAGE plpgsql
    AS $$
BEGIN
    SET TIME ZONE 'America/Lima';

    UPDATE gen_almacen
    SET
        id_sucursal = COALESCE(p_id_sucursal, id_sucursal),
        nombre = COALESCE(p_nombre, nombre),
        ubicacion = COALESCE(p_ubicacion, ubicacion),
        descripcion = COALESCE(p_descripcion, descripcion),
        id_departamento = COALESCE(p_id_departamento, id_departamento),
        id_provincia = COALESCE(p_id_provincia, id_provincia),
        id_distrito = COALESCE(p_id_distrito, id_distrito),
        id_usuario_modificacion = p_id_usuario_auditoria,
        fecha_modificacion = NOW()
    WHERE id = p_id AND estado = 1;

    IF NOT FOUND THEN
        RETURN json_build_object('registro', NULL);
    END IF;

    RETURN gen_obtener_almacen(p_id);
END;
$$;


--
-- Name: gen_actualizar_chofer(integer, integer, integer, character varying, character varying, character varying, integer, character varying, character varying, character varying, date, date, integer, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gen_actualizar_chofer(p_id integer, p_id_cliente integer DEFAULT NULL::integer, p_id_trabajador integer DEFAULT NULL::integer, p_apellido_paterno character varying DEFAULT NULL::character varying, p_apellido_materno character varying DEFAULT NULL::character varying, p_nombres character varying DEFAULT NULL::character varying, p_id_tipo_documento integer DEFAULT NULL::integer, p_numero_documento character varying DEFAULT NULL::character varying, p_telefono character varying DEFAULT NULL::character varying, p_codigo_licencia character varying DEFAULT NULL::character varying, p_fecha_emision date DEFAULT NULL::date, p_fecha_vencimiento date DEFAULT NULL::date, p_id_tipo_licencia integer DEFAULT NULL::integer, p_id_categoria_licencia integer DEFAULT NULL::integer, p_id_usuario_auditoria integer DEFAULT NULL::integer) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_id_licencia INTEGER;
    v_id_cliente_actual INTEGER;
    v_id_trabajador_actual INTEGER;
BEGIN
    SET TIME ZONE 'America/Lima';

    SELECT id_cliente, id_trabajador INTO v_id_cliente_actual, v_id_trabajador_actual
    FROM gen_chofer WHERE id = p_id AND estado = 1;

    IF v_id_cliente_actual IS NULL THEN
        RETURN json_build_object('registro', NULL, 'error', 'No existe un chofer con id ' || p_id);
    END IF;

    IF p_id_trabajador IS NOT NULL AND NOT EXISTS (
        SELECT 1 FROM tra_trabajadores WHERE id = p_id_trabajador AND estado = 1
    ) THEN
        RETURN json_build_object('error', 'El trabajador indicado no existe.', 'registro', NULL);
    END IF;

    IF (COALESCE(p_id_cliente, v_id_cliente_actual) IS NULL) AND (p_id_trabajador IS NULL) AND v_id_trabajador_actual IS NULL THEN
        RETURN json_build_object('error', 'El chofer de flota propia debe vincularse a un trabajador.', 'registro', NULL);
    END IF;

    IF (COALESCE(p_id_cliente, v_id_cliente_actual) IS NOT NULL) AND (COALESCE(p_id_trabajador, v_id_trabajador_actual) IS NOT NULL) THEN
        RETURN json_build_object('error', 'Un chofer de cliente no puede vincularse a un trabajador de la empresa.', 'registro', NULL);
    END IF;

    IF p_numero_documento IS NOT NULL AND EXISTS (
        SELECT 1 FROM gen_chofer WHERE numero_documento = p_numero_documento AND id <> p_id AND estado = 1
    ) THEN
        RETURN json_build_object('error', 'Ya existe otro chofer registrado con el documento ' || p_numero_documento, 'registro', NULL);
    END IF;

    BEGIN
        UPDATE gen_chofer
        SET
            id_cliente = COALESCE(p_id_cliente, id_cliente),
            id_trabajador = COALESCE(p_id_trabajador, id_trabajador),
            apellido_paterno = COALESCE(p_apellido_paterno, apellido_paterno),
            apellido_materno = COALESCE(p_apellido_materno, apellido_materno),
            nombres = COALESCE(p_nombres, nombres),
            id_tipo_documento = COALESCE(p_id_tipo_documento, id_tipo_documento),
            numero_documento = COALESCE(p_numero_documento, numero_documento),
            telefono = COALESCE(p_telefono, telefono),
            id_usuario_modificacion = p_id_usuario_auditoria,
            fecha_modificacion = NOW()
        WHERE id = p_id AND estado = 1;

        IF p_codigo_licencia IS NOT NULL OR p_fecha_emision IS NOT NULL OR p_fecha_vencimiento IS NOT NULL
           OR p_id_tipo_licencia IS NOT NULL OR p_id_categoria_licencia IS NOT NULL THEN

            SELECT id INTO v_id_licencia
            FROM gen_licencia
            WHERE id_chofer = p_id AND estado = 1
            ORDER BY fecha_emision DESC, id DESC
            LIMIT 1;

            IF v_id_licencia IS NOT NULL THEN
                UPDATE gen_licencia SET
                    codigo                  = COALESCE(p_codigo_licencia, codigo),
                    fecha_emision           = COALESCE(p_fecha_emision, fecha_emision),
                    fecha_vencimiento       = COALESCE(p_fecha_vencimiento, fecha_vencimiento),
                    id_tipo_licencia        = COALESCE(p_id_tipo_licencia, id_tipo_licencia),
                    id_categoria_licencia   = COALESCE(p_id_categoria_licencia, id_categoria_licencia),
                    id_usuario_modificacion = p_id_usuario_auditoria,
                    fecha_modificacion      = NOW()
                WHERE id = v_id_licencia;
            ELSIF p_codigo_licencia IS NOT NULL AND p_fecha_emision IS NOT NULL AND p_fecha_vencimiento IS NOT NULL THEN
                INSERT INTO gen_licencia (
                    id_tipo_licencia, id_categoria_licencia, id_chofer, codigo,
                    fecha_emision, fecha_vencimiento,
                    id_usuario_creacion, id_usuario_modificacion
                )
                VALUES (
                    p_id_tipo_licencia, p_id_categoria_licencia, p_id, p_codigo_licencia,
                    p_fecha_emision, p_fecha_vencimiento,
                    p_id_usuario_auditoria, p_id_usuario_auditoria
                );
            END IF;
        END IF;

    EXCEPTION
        WHEN unique_violation THEN
            RETURN json_build_object('error', 'Ya existe un registro con datos duplicados', 'registro', NULL);
        WHEN foreign_key_violation THEN
            RETURN json_build_object('error', 'Uno de los datos de tipo o categoría no es válido', 'registro', NULL);
        WHEN OTHERS THEN
            RETURN json_build_object('error', 'No se pudo actualizar el chofer: ' || SQLERRM, 'registro', NULL);
    END;

    RETURN gen_obtener_chofer(p_id);
END;
$$;


--
-- Name: gen_actualizar_condicion_pago(integer, character varying, character varying, integer, integer, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gen_actualizar_condicion_pago(p_id integer, p_codigo character varying DEFAULT NULL::character varying, p_nombre character varying DEFAULT NULL::character varying, p_dias_credito integer DEFAULT NULL::integer, p_numero_cuotas integer DEFAULT NULL::integer, p_dia_mes_pago integer DEFAULT NULL::integer, p_id_usuario_auditoria integer DEFAULT NULL::integer) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_dias INTEGER;
    v_cuotas INTEGER;
    v_dia INTEGER;
BEGIN
    SET TIME ZONE 'America/Lima';

    IF NOT EXISTS (SELECT 1 FROM gen_condicion_pago WHERE id = p_id AND estado = 1) THEN
        RETURN json_build_object('registro', NULL);
    END IF;

    SELECT
        COALESCE(p_dias_credito, dias_credito),
        NULLIF(COALESCE(p_numero_cuotas, numero_cuotas), 0),
        COALESCE(p_dia_mes_pago, dia_mes_pago)
    INTO v_dias, v_cuotas, v_dia
    FROM gen_condicion_pago
    WHERE id = p_id;

    -- Si el cliente envía explícitamente null de cuotas vía p_numero_cuotas = 0
    -- (Nest mapea "sin cuotas" a 0 o null). Preferimos: si p_numero_cuotas viene
    -- como NULL desde Nest significa "limpiar" solo cuando también se manda
    -- p_dias_credito (actualización completa del formulario).
    IF p_dias_credito IS NOT NULL THEN
        v_dias := p_dias_credito;
        v_cuotas := NULLIF(p_numero_cuotas, 0);
        v_dia := p_dia_mes_pago;
    END IF;

    IF v_dias < 0 THEN
        RETURN json_build_object('error', 'Los días de crédito no pueden ser negativos', 'registro', NULL);
    END IF;

    IF COALESCE(v_cuotas, 0) > 1 THEN
        IF v_dia IS NULL OR v_dia < 1 OR v_dia > 31 THEN
            RETURN json_build_object(
                'error',
                'En plan de cuotas debes indicar el día del mes a cobrar (1 a 31)',
                'registro',
                NULL
            );
        END IF;
    ELSE
        v_cuotas := NULL;
        v_dia := NULL;
    END IF;

    UPDATE gen_condicion_pago
    SET
        codigo = COALESCE(p_codigo, codigo),
        nombre = COALESCE(p_nombre, nombre),
        dias_credito = v_dias,
        numero_cuotas = v_cuotas,
        dia_mes_pago = v_dia,
        id_usuario_modificacion = p_id_usuario_auditoria,
        fecha_modificacion = NOW()
    WHERE id = p_id AND estado = 1;

    RETURN gen_obtener_condicion_pago(p_id);
END;
$$;


--
-- Name: gen_actualizar_configuracion_servicio(integer, character varying, character varying, character varying, character varying, character varying, character varying, character varying, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gen_actualizar_configuracion_servicio(p_id integer, p_codigo character varying DEFAULT NULL::character varying, p_nombre character varying DEFAULT NULL::character varying, p_usuario character varying DEFAULT NULL::character varying, p_contrasena character varying DEFAULT NULL::character varying, p_email character varying DEFAULT NULL::character varying, p_url character varying DEFAULT NULL::character varying, p_observacion character varying DEFAULT NULL::character varying, p_id_usuario_auditoria integer DEFAULT NULL::integer) RETURNS json
    LANGUAGE plpgsql
    AS $$
BEGIN
    SET TIME ZONE 'America/Lima';

    UPDATE gen_configuracion_servicio
    SET
        codigo = COALESCE(p_codigo, codigo),
        nombre = COALESCE(p_nombre, nombre),
        usuario = COALESCE(p_usuario, usuario),
        contrasena = COALESCE(p_contrasena, contrasena),
        email = COALESCE(p_email, email),
        url = COALESCE(p_url, url),
        observacion = COALESCE(p_observacion, observacion),
        id_usuario_modificacion = p_id_usuario_auditoria,
        fecha_modificacion = NOW()
    WHERE id = p_id AND estado = 1;

    IF NOT FOUND THEN
        RETURN json_build_object('registro', NULL);
    END IF;

    RETURN gen_obtener_configuracion_servicio(p_id);
END;
$$;


--
-- Name: gen_actualizar_configuracion_sunat(integer, integer, character varying, character varying, character varying, character varying, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gen_actualizar_configuracion_sunat(p_id integer, p_id_empresa integer DEFAULT NULL::integer, p_usuario_sol character varying DEFAULT NULL::character varying, p_clave_sol character varying DEFAULT NULL::character varying, p_certificado_digital character varying DEFAULT NULL::character varying, p_clave_certificado character varying DEFAULT NULL::character varying, p_id_ambiente integer DEFAULT NULL::integer, p_id_usuario_auditoria integer DEFAULT NULL::integer) RETURNS json
    LANGUAGE plpgsql
    AS $$
BEGIN
    SET TIME ZONE 'America/Lima';

    UPDATE gen_configuracion_sunat
    SET
        id_empresa = COALESCE(p_id_empresa, id_empresa),
        usuario_sol = COALESCE(p_usuario_sol, usuario_sol),
        clave_sol = COALESCE(p_clave_sol, clave_sol),
        certificado_digital = COALESCE(p_certificado_digital, certificado_digital),
        clave_certificado = COALESCE(p_clave_certificado, clave_certificado),
        id_ambiente = COALESCE(p_id_ambiente, id_ambiente),
        id_usuario_modificacion = p_id_usuario_auditoria,
        fecha_modificacion = NOW()
    WHERE id = p_id AND estado = 1;

    IF NOT FOUND THEN
        RETURN json_build_object('registro', NULL);
    END IF;

    RETURN gen_obtener_configuracion_sunat(p_id);
END;
$$;


--
-- Name: gen_actualizar_configuracion_sunat(integer, integer, character varying, character varying, character varying, character varying, integer, character varying, boolean, character varying, text, character varying, character varying, character varying, character varying, character varying, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gen_actualizar_configuracion_sunat(p_id integer, p_id_empresa integer DEFAULT NULL::integer, p_usuario_sol character varying DEFAULT NULL::character varying, p_clave_sol character varying DEFAULT NULL::character varying, p_certificado_digital character varying DEFAULT NULL::character varying, p_clave_certificado character varying DEFAULT NULL::character varying, p_id_ambiente integer DEFAULT NULL::integer, p_proveedor_pse character varying DEFAULT NULL::character varying, p_pse_habilitado boolean DEFAULT NULL::boolean, p_api_base_url character varying DEFAULT NULL::character varying, p_api_token text DEFAULT NULL::text, p_api_usuario character varying DEFAULT NULL::character varying, p_api_clave character varying DEFAULT NULL::character varying, p_ruc_emisor character varying DEFAULT NULL::character varying, p_client_id character varying DEFAULT NULL::character varying, p_client_secret character varying DEFAULT NULL::character varying, p_timeout_ms integer DEFAULT NULL::integer, p_id_usuario_auditoria integer DEFAULT NULL::integer) RETURNS json
    LANGUAGE plpgsql
    AS $$
BEGIN
    SET TIME ZONE 'America/Lima';

    UPDATE gen_configuracion_sunat
    SET
        id_empresa = COALESCE(p_id_empresa, id_empresa),
        usuario_sol = COALESCE(p_usuario_sol, usuario_sol),
        clave_sol = COALESCE(p_clave_sol, clave_sol),
        certificado_digital = COALESCE(p_certificado_digital, certificado_digital),
        clave_certificado = COALESCE(p_clave_certificado, clave_certificado),
        id_ambiente = COALESCE(p_id_ambiente, id_ambiente),
        proveedor_pse = CASE
            WHEN p_proveedor_pse IS NULL THEN proveedor_pse
            ELSE NULLIF(TRIM(p_proveedor_pse), '')
        END,
        pse_habilitado = COALESCE(p_pse_habilitado, pse_habilitado),
        api_base_url = CASE
            WHEN p_api_base_url IS NULL THEN api_base_url
            ELSE NULLIF(TRIM(p_api_base_url), '')
        END,
        api_token = CASE
            WHEN p_api_token IS NULL THEN api_token
            WHEN TRIM(p_api_token) = '' THEN api_token
            ELSE TRIM(p_api_token)
        END,
        api_usuario = CASE
            WHEN p_api_usuario IS NULL THEN api_usuario
            ELSE NULLIF(TRIM(p_api_usuario), '')
        END,
        api_clave = CASE
            WHEN p_api_clave IS NULL THEN api_clave
            WHEN TRIM(p_api_clave) = '' THEN api_clave
            ELSE TRIM(p_api_clave)
        END,
        ruc_emisor = CASE
            WHEN p_ruc_emisor IS NULL THEN ruc_emisor
            ELSE NULLIF(TRIM(p_ruc_emisor), '')
        END,
        client_id = CASE
            WHEN p_client_id IS NULL THEN client_id
            ELSE NULLIF(TRIM(p_client_id), '')
        END,
        client_secret = CASE
            WHEN p_client_secret IS NULL THEN client_secret
            WHEN TRIM(p_client_secret) = '' THEN client_secret
            ELSE TRIM(p_client_secret)
        END,
        timeout_ms = COALESCE(p_timeout_ms, timeout_ms),
        id_usuario_modificacion = p_id_usuario_auditoria,
        fecha_modificacion = NOW()
    WHERE id = p_id AND estado = 1;

    IF NOT FOUND THEN
        RETURN json_build_object('registro', NULL);
    END IF;

    RETURN gen_obtener_configuracion_sunat(p_id);
END;
$$;


--
-- Name: gen_actualizar_cuenta_bancaria(integer, integer, integer, integer, character varying, character varying, character varying, character varying, boolean, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gen_actualizar_cuenta_bancaria(p_id integer, p_id_cliente integer DEFAULT NULL::integer, p_id_banco integer DEFAULT NULL::integer, p_id_tipo_cuenta integer DEFAULT NULL::integer, p_titular character varying DEFAULT NULL::character varying, p_numero_cuenta character varying DEFAULT NULL::character varying, p_numero_cuenta_interbancaria character varying DEFAULT NULL::character varying, p_telefono_billetera character varying DEFAULT NULL::character varying, p_es_principal boolean DEFAULT NULL::boolean, p_id_usuario_auditoria integer DEFAULT NULL::integer) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_current_id_cliente INTEGER;
BEGIN
    SET TIME ZONE 'America/Lima';

    SELECT id_cliente INTO v_current_id_cliente
    FROM gen_cuenta_bancaria
    WHERE id = p_id AND estado = 1;

    IF NOT FOUND THEN
        RETURN json_build_object('registro', NULL);
    END IF;

    IF p_es_principal IS TRUE THEN
        UPDATE gen_cuenta_bancaria
        SET es_principal = FALSE
        WHERE id <> p_id
          AND ((v_current_id_cliente IS NULL AND id_cliente IS NULL)
               OR (v_current_id_cliente IS NOT NULL AND id_cliente = v_current_id_cliente));
    END IF;

    UPDATE gen_cuenta_bancaria
    SET
        id_cliente = COALESCE(p_id_cliente, id_cliente),
        id_banco = COALESCE(p_id_banco, id_banco),
        id_tipo_cuenta = COALESCE(p_id_tipo_cuenta, id_tipo_cuenta),
        titular = COALESCE(p_titular, titular),
        numero_cuenta = COALESCE(p_numero_cuenta, numero_cuenta),
        numero_cuenta_interbancaria = COALESCE(p_numero_cuenta_interbancaria, numero_cuenta_interbancaria),
        telefono_billetera = COALESCE(p_telefono_billetera, telefono_billetera),
        es_principal = COALESCE(p_es_principal, es_principal),
        id_usuario_modificacion = p_id_usuario_auditoria,
        fecha_modificacion = NOW()
    WHERE id = p_id AND estado = 1;

    RETURN gen_obtener_cuenta_bancaria(p_id);
END;
$$;


