--

CREATE FUNCTION public.gen_actualizar_documento_vencimiento(p_id integer, p_id_categoria integer DEFAULT NULL::integer, p_descripcion character varying DEFAULT NULL::character varying, p_id_vehiculo integer DEFAULT NULL::integer, p_fecha_vencimiento date DEFAULT NULL::date, p_fecha_renovacion date DEFAULT NULL::date, p_numero_documento character varying DEFAULT NULL::character varying, p_observacion character varying DEFAULT NULL::character varying, p_id_estado integer DEFAULT NULL::integer, p_id_usuario_auditoria integer DEFAULT NULL::integer, p_id_sucursal integer DEFAULT NULL::integer, p_reemplazar_alcance boolean DEFAULT true) RETURNS json
    LANGUAGE plpgsql
    AS $$
BEGIN
    SET TIME ZONE 'America/Lima';

    UPDATE gen_documento_vencimiento
    SET
        id_categoria = COALESCE(p_id_categoria, id_categoria),
        descripcion = COALESCE(p_descripcion, descripcion),
        id_vehiculo = CASE WHEN p_reemplazar_alcance THEN p_id_vehiculo ELSE COALESCE(p_id_vehiculo, id_vehiculo) END,
        id_sucursal = CASE WHEN p_reemplazar_alcance THEN p_id_sucursal ELSE COALESCE(p_id_sucursal, id_sucursal) END,
        fecha_vencimiento = COALESCE(p_fecha_vencimiento, fecha_vencimiento),
        fecha_renovacion = COALESCE(p_fecha_renovacion, fecha_renovacion),
        numero_documento = COALESCE(p_numero_documento, numero_documento),
        observacion = COALESCE(p_observacion, observacion),
        id_estado = COALESCE(p_id_estado, id_estado),
        id_usuario_modificacion = p_id_usuario_auditoria,
        fecha_modificacion = NOW()
    WHERE id = p_id AND estado = 1;

    IF NOT FOUND THEN
        RETURN json_build_object('registro', NULL);
    END IF;

    RETURN gen_obtener_documento_vencimiento(p_id);
END;
$$;


--
-- Name: gen_actualizar_empresa(integer, character varying, character varying, character varying, character varying, character varying, character varying, numeric, numeric, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gen_actualizar_empresa(p_id integer, p_ruc character varying DEFAULT NULL::character varying, p_razon_social character varying DEFAULT NULL::character varying, p_nombre_comercial character varying DEFAULT NULL::character varying, p_direccion character varying DEFAULT NULL::character varying, p_telefono character varying DEFAULT NULL::character varying, p_email character varying DEFAULT NULL::character varying, p_tolerancia_m3_ruta_pueblo numeric DEFAULT NULL::numeric, p_psi_minimo_util numeric DEFAULT NULL::numeric, p_id_usuario_auditoria integer DEFAULT NULL::integer) RETURNS json
    LANGUAGE plpgsql
    AS $$
BEGIN
    SET TIME ZONE 'America/Lima';

    IF p_tolerancia_m3_ruta_pueblo IS NOT NULL AND p_tolerancia_m3_ruta_pueblo < 0 THEN
        RETURN json_build_object('error', 'La tolerancia de ruta pueblos no puede ser negativa', 'registro', NULL);
    END IF;

    IF p_psi_minimo_util IS NOT NULL AND p_psi_minimo_util < 0 THEN
        RETURN json_build_object('error', 'El umbral PSI mínimo no puede ser negativo', 'registro', NULL);
    END IF;

    UPDATE gen_empresa
    SET
        ruc = COALESCE(p_ruc, ruc),
        razon_social = COALESCE(p_razon_social, razon_social),
        nombre_comercial = COALESCE(p_nombre_comercial, nombre_comercial),
        direccion = COALESCE(p_direccion, direccion),
        telefono = COALESCE(p_telefono, telefono),
        email = COALESCE(p_email, email),
        tolerancia_m3_ruta_pueblo = COALESCE(p_tolerancia_m3_ruta_pueblo, tolerancia_m3_ruta_pueblo),
        psi_minimo_util = COALESCE(p_psi_minimo_util, psi_minimo_util),
        id_usuario_modificacion = p_id_usuario_auditoria,
        fecha_modificacion = NOW()
    WHERE id = p_id AND estado = 1;

    IF NOT FOUND THEN
        RETURN json_build_object('registro', NULL);
    END IF;

    RETURN gen_obtener_empresa(p_id);
END;
$$;


