--
-- Name: gen_actualizar_vehiculo(integer, integer, integer, character varying, character varying, character varying, character varying, character varying, integer, character varying, character varying, character varying, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gen_actualizar_vehiculo(p_id integer, p_id_cliente integer DEFAULT NULL::integer, p_id_tipo_vehiculo integer DEFAULT NULL::integer, p_placa character varying DEFAULT NULL::character varying, p_placa2 character varying DEFAULT NULL::character varying, p_marca character varying DEFAULT NULL::character varying, p_marca2 character varying DEFAULT NULL::character varying, p_modelo character varying DEFAULT NULL::character varying, p_anio integer DEFAULT NULL::integer, p_color character varying DEFAULT NULL::character varying, p_certificado_inscripcion character varying DEFAULT NULL::character varying, p_certificado2 character varying DEFAULT NULL::character varying, p_id_usuario_auditoria integer DEFAULT NULL::integer) RETURNS json
    LANGUAGE plpgsql
    AS $$
BEGIN
    SET TIME ZONE 'America/Lima';

    IF p_placa IS NOT NULL AND EXISTS (
        SELECT 1 FROM gen_vehiculo
        WHERE placa = p_placa AND estado = 1 AND id <> p_id
    ) THEN
        RETURN json_build_object('registro', NULL, 'error', 'Ya existe un vehículo activo con esa placa');
    END IF;

    UPDATE gen_vehiculo
    SET
        id_cliente = COALESCE(p_id_cliente, id_cliente),
        id_tipo_vehiculo = COALESCE(p_id_tipo_vehiculo, id_tipo_vehiculo),
        placa = COALESCE(p_placa, placa),
        placa2 = COALESCE(p_placa2, placa2),
        marca = COALESCE(p_marca, marca),
        marca2 = COALESCE(p_marca2, marca2),
        modelo = COALESCE(p_modelo, modelo),
        anio = COALESCE(p_anio, anio),
        color = COALESCE(p_color, color),
        certificado_inscripcion = COALESCE(p_certificado_inscripcion, certificado_inscripcion),
        certificado2 = COALESCE(p_certificado2, certificado2),
        id_usuario_modificacion = p_id_usuario_auditoria,
        fecha_modificacion = NOW()
    WHERE id = p_id AND estado = 1;

    IF NOT FOUND THEN
        RETURN json_build_object('registro', NULL);
    END IF;

    RETURN gen_obtener_vehiculo(p_id);
END;
$$;


--
-- Name: gen_contar_notificaciones_no_leidas(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gen_contar_notificaciones_no_leidas(p_id_usuario integer) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_total INTEGER;
BEGIN
    SET TIME ZONE 'America/Lima';

    IF p_id_usuario IS NULL THEN
        RETURN json_build_object('total', 0);
    END IF;

    SELECT COUNT(*)::INTEGER
    INTO v_total
    FROM gen_notificacion
    WHERE id_usuario = p_id_usuario
      AND estado = 1
      AND leida = FALSE;

    RETURN json_build_object('total', COALESCE(v_total, 0));
END;
$$;


--
-- Name: gen_crear_almacen(integer, character varying, character varying, character varying, integer, integer, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gen_crear_almacen(p_id_sucursal integer, p_nombre character varying, p_ubicacion character varying DEFAULT NULL::character varying, p_descripcion character varying DEFAULT NULL::character varying, p_id_departamento integer DEFAULT NULL::integer, p_id_provincia integer DEFAULT NULL::integer, p_id_distrito integer DEFAULT NULL::integer, p_id_usuario_auditoria integer DEFAULT NULL::integer) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_id INTEGER;
BEGIN
    SET TIME ZONE 'America/Lima';

    INSERT INTO gen_almacen (
        id_sucursal,
        nombre,
        ubicacion,
        descripcion,
        id_departamento,
        id_provincia,
        id_distrito,
        id_usuario_creacion,
        id_usuario_modificacion
    )
    VALUES (
        p_id_sucursal,
        p_nombre,
        p_ubicacion,
        p_descripcion,
        p_id_departamento,
        p_id_provincia,
        p_id_distrito,
        p_id_usuario_auditoria,
        p_id_usuario_auditoria
    )
    RETURNING id INTO v_id;

    RETURN gen_obtener_almacen(v_id);
END;
$$;


--
-- Name: gen_crear_archivo(character varying, character varying, character varying, character varying, character varying, character varying, bigint, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gen_crear_archivo(p_nombre_original character varying, p_nombre_almacenado character varying, p_ruta character varying, p_bucket character varying, p_mime_type character varying DEFAULT NULL::character varying, p_extension character varying DEFAULT NULL::character varying, p_tamanio_bytes bigint DEFAULT NULL::bigint, p_id_empresa integer DEFAULT NULL::integer, p_id_usuario_auditoria integer DEFAULT NULL::integer) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_id INTEGER;
BEGIN
    SET TIME ZONE 'America/Lima';

    INSERT INTO gen_archivo (
        nombre_original,
        nombre_almacenado,
        ruta,
        bucket,
        mime_type,
        extension,
        tamanio_bytes,
        id_empresa,
        estado,
        id_usuario_creacion,
        id_usuario_modificacion
    )
    VALUES (
        p_nombre_original,
        p_nombre_almacenado,
        p_ruta,
        p_bucket,
        p_mime_type,
        p_extension,
        p_tamanio_bytes,
        p_id_empresa,
        1,
        p_id_usuario_auditoria,
        p_id_usuario_auditoria
    )
    ON CONFLICT (bucket, ruta) DO UPDATE
    SET
        nombre_original = EXCLUDED.nombre_original,
        nombre_almacenado = EXCLUDED.nombre_almacenado,
        mime_type = EXCLUDED.mime_type,
        extension = EXCLUDED.extension,
        tamanio_bytes = EXCLUDED.tamanio_bytes,
        id_empresa = COALESCE(EXCLUDED.id_empresa, gen_archivo.id_empresa),
        estado = 1,
        id_usuario_modificacion = p_id_usuario_auditoria,
        fecha_modificacion = NOW()
    RETURNING id INTO v_id;

    RETURN gen_obtener_archivo(v_id);
END;
$$;


--
-- Name: gen_crear_chofer(character varying, integer, integer, character varying, character varying, integer, character varying, character varying, character varying, date, date, integer, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gen_crear_chofer(p_nombres character varying, p_id_cliente integer DEFAULT NULL::integer, p_id_trabajador integer DEFAULT NULL::integer, p_apellido_paterno character varying DEFAULT NULL::character varying, p_apellido_materno character varying DEFAULT NULL::character varying, p_id_tipo_documento integer DEFAULT NULL::integer, p_numero_documento character varying DEFAULT NULL::character varying, p_telefono character varying DEFAULT NULL::character varying, p_codigo_licencia character varying DEFAULT NULL::character varying, p_fecha_emision date DEFAULT NULL::date, p_fecha_vencimiento date DEFAULT NULL::date, p_id_tipo_licencia integer DEFAULT NULL::integer, p_id_categoria_licencia integer DEFAULT NULL::integer, p_id_usuario_auditoria integer DEFAULT NULL::integer) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_id_chofer INTEGER;
BEGIN
    SET TIME ZONE 'America/Lima';

    IF p_id_cliente IS NULL AND p_id_trabajador IS NULL THEN
        RETURN json_build_object('error', 'El chofer de flota propia debe vincularse a un trabajador.', 'registro', NULL);
    END IF;

    IF p_id_cliente IS NOT NULL AND p_id_trabajador IS NOT NULL THEN
        RETURN json_build_object('error', 'Un chofer de cliente no puede vincularse a un trabajador de la empresa.', 'registro', NULL);
    END IF;

    IF p_id_cliente IS NOT NULL AND p_nombres IS NULL THEN
        RETURN json_build_object('error', 'El nombre es obligatorio para choferes de cliente.', 'registro', NULL);
    END IF;

    IF p_id_trabajador IS NOT NULL AND NOT EXISTS (
        SELECT 1 FROM tra_trabajadores WHERE id = p_id_trabajador AND estado = 1
    ) THEN
        RETURN json_build_object('error', 'El trabajador indicado no existe.', 'registro', NULL);
    END IF;

    IF p_numero_documento IS NOT NULL AND EXISTS (
        SELECT 1 FROM gen_chofer WHERE numero_documento = p_numero_documento AND estado = 1
    ) THEN
        RETURN json_build_object('error', 'Ya existe un chofer registrado con el documento ' || p_numero_documento, 'registro', NULL);
    END IF;

    BEGIN
        INSERT INTO gen_chofer (
            id_cliente, id_trabajador, apellido_paterno, apellido_materno, nombres,
            id_tipo_documento, numero_documento, telefono,
            id_usuario_creacion, id_usuario_modificacion
        )
        VALUES (
            p_id_cliente, p_id_trabajador, p_apellido_paterno, p_apellido_materno, p_nombres,
            p_id_tipo_documento, p_numero_documento, p_telefono,
            p_id_usuario_auditoria, p_id_usuario_auditoria
        )
        RETURNING id INTO v_id_chofer;

        -- Licencia (opcional al crear el chofer)
        IF p_codigo_licencia IS NOT NULL THEN
            INSERT INTO gen_licencia (
                id_tipo_licencia, id_categoria_licencia, id_chofer, codigo,
                fecha_emision, fecha_vencimiento,
                id_usuario_creacion, id_usuario_modificacion
            )
            VALUES (
                p_id_tipo_licencia, p_id_categoria_licencia, v_id_chofer, p_codigo_licencia,
                p_fecha_emision, p_fecha_vencimiento,
                p_id_usuario_auditoria, p_id_usuario_auditoria
            );
        END IF;

    EXCEPTION
        WHEN unique_violation THEN
            RETURN json_build_object('error', 'Ya existe un registro con datos duplicados (documento o código de licencia)', 'registro', NULL);
        WHEN foreign_key_violation THEN
            RETURN json_build_object('error', 'Uno de los datos de cliente, tipo o categoría no es válido', 'registro', NULL);
        WHEN OTHERS THEN
            RETURN json_build_object('error', 'No se pudo crear el chofer: ' || SQLERRM, 'registro', NULL);
    END;

    RETURN gen_obtener_chofer(v_id_chofer);
END;
$$;


--
-- Name: gen_crear_condicion_pago(character varying, character varying, integer, integer, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gen_crear_condicion_pago(p_codigo character varying, p_nombre character varying, p_dias_credito integer DEFAULT 0, p_numero_cuotas integer DEFAULT NULL::integer, p_dia_mes_pago integer DEFAULT NULL::integer, p_id_usuario_auditoria integer DEFAULT NULL::integer) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_id INTEGER;
    v_dias INTEGER;
    v_cuotas INTEGER;
    v_dia INTEGER;
BEGIN
    SET TIME ZONE 'America/Lima';

    v_dias := COALESCE(p_dias_credito, 0);
    v_cuotas := NULLIF(p_numero_cuotas, 0);
    v_dia := p_dia_mes_pago;

    IF v_dias < 0 THEN
        RETURN json_build_object('error', 'Los días de crédito no pueden ser negativos', 'registro', NULL);
    END IF;

    IF v_cuotas IS NOT NULL AND v_cuotas < 1 THEN
        RETURN json_build_object('error', 'El número de cuotas debe ser al menos 1', 'registro', NULL);
    END IF;

    IF COALESCE(v_cuotas, 0) > 1 THEN
        IF v_dia IS NULL OR v_dia < 1 OR v_dia > 31 THEN
            RETURN json_build_object(
                'error',
                'En plan de cuotas debes indicar el día del mes a cobrar (1 a 31)',
                'registro',
                NULL
            );
        END IF;
    ELSE
        -- Contado / crédito simple: no guardar día de cobro
        v_dia := NULL;
        IF COALESCE(v_cuotas, 0) <= 1 THEN
            v_cuotas := NULL;
        END IF;
    END IF;

    INSERT INTO gen_condicion_pago (
        codigo,
        nombre,
        dias_credito,
        numero_cuotas,
        dia_mes_pago,
        id_usuario_creacion,
        id_usuario_modificacion
    )
    VALUES (
        p_codigo,
        p_nombre,
        v_dias,
        v_cuotas,
        v_dia,
        p_id_usuario_auditoria,
        p_id_usuario_auditoria
    )
    RETURNING id INTO v_id;

    RETURN gen_obtener_condicion_pago(v_id);
END;
$$;


