--
-- Name: gen_crear_lista_opcion(integer, character varying, character varying, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gen_crear_lista_opcion(p_id_lista integer, p_nombre character varying, p_descripcion character varying DEFAULT NULL::character varying, p_id_usuario_auditoria integer DEFAULT NULL::integer) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_id INTEGER;
    v_nombre VARCHAR(150);
BEGIN
    SET TIME ZONE 'America/Lima';

    IF p_id_lista IS NULL THEN
        RETURN json_build_object('error', 'El id_lista es obligatorio', 'registro', NULL);
    END IF;

    IF NOT EXISTS (
        SELECT 1 FROM gen_lista WHERE id = p_id_lista AND estado = 1
    ) THEN
        RETURN json_build_object('error', 'La lista indicada no existe o está inactiva', 'registro', NULL);
    END IF;

    v_nombre := TRIM(COALESCE(p_nombre, ''));
    IF v_nombre = '' THEN
        RETURN json_build_object('error', 'El nombre de la opción es obligatorio', 'registro', NULL);
    END IF;

    IF EXISTS (
        SELECT 1
        FROM gen_lista_opciones
        WHERE id_lista = p_id_lista
          AND estado = 1
          AND LOWER(TRIM(nombre)) = LOWER(v_nombre)
    ) THEN
        RETURN json_build_object(
            'error', 'Ya existe una opción activa con ese nombre en la lista',
            'registro', NULL
        );
    END IF;

    INSERT INTO gen_lista_opciones (
        id_lista,
        nombre,
        descripcion,
        id_usuario_creacion,
        id_usuario_modificacion
    )
    VALUES (
        p_id_lista,
        v_nombre,
        NULLIF(TRIM(COALESCE(p_descripcion, '')), ''),
        p_id_usuario_auditoria,
        p_id_usuario_auditoria
    )
    RETURNING id INTO v_id;

    RETURN json_build_object(
        'error', NULL,
        'registro', (
            SELECT row_to_json(t)
            FROM (
                SELECT
                    lo.id,
                    lo.id_lista,
                    l.nombre AS nombre_lista,
                    lo.nombre,
                    lo.descripcion,
                    lo.estado
                FROM gen_lista_opciones lo
                INNER JOIN gen_lista l ON lo.id_lista = l.id
                WHERE lo.id = v_id
            ) t
        )
    );
END;
$$;


--
-- Name: gen_crear_notificacion(integer, character varying, character varying, text, json, integer, character varying, character varying, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gen_crear_notificacion(p_id_usuario integer, p_codigo_tipo character varying, p_titulo character varying, p_mensaje text DEFAULT NULL::text, p_payload json DEFAULT '{}'::json, p_id_referencia integer DEFAULT NULL::integer, p_tipo_referencia character varying DEFAULT NULL::character varying, p_clave_dedupe character varying DEFAULT NULL::character varying, p_id_usuario_auditoria integer DEFAULT NULL::integer) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_id INTEGER;
    v_codigo VARCHAR;
    v_clave VARCHAR;
BEGIN
    SET TIME ZONE 'America/Lima';

    IF p_id_usuario IS NULL THEN
        RETURN json_build_object('error', 'El destinatario es obligatorio', 'registro', NULL);
    END IF;

    IF NOT EXISTS (SELECT 1 FROM auth_usuarios WHERE id = p_id_usuario AND estado = TRUE) THEN
        RETURN json_build_object('error', 'El usuario destinatario no existe o está inactivo', 'registro', NULL);
    END IF;

    v_codigo := UPPER(TRIM(COALESCE(p_codigo_tipo, '')));
    IF v_codigo = '' THEN
        RETURN json_build_object('error', 'El tipo de notificación es obligatorio', 'registro', NULL);
    END IF;

    IF NULLIF(TRIM(p_titulo), '') IS NULL THEN
        RETURN json_build_object('error', 'El título es obligatorio', 'registro', NULL);
    END IF;

    v_clave := NULLIF(TRIM(p_clave_dedupe), '');

    IF v_clave IS NOT NULL THEN
        SELECT id INTO v_id
        FROM gen_notificacion
        WHERE id_usuario = p_id_usuario
          AND clave_dedupe = v_clave
          AND estado = 1
        LIMIT 1;

        IF v_id IS NOT NULL THEN
            RETURN (
                SELECT json_build_object(
                    'registro', (gen_obtener_notificacion(v_id, p_id_usuario))->'registro',
                    'creada', FALSE
                )
            );
        END IF;
    END IF;

    INSERT INTO gen_notificacion (
        id_usuario,
        codigo_tipo,
        titulo,
        mensaje,
        payload,
        id_referencia,
        tipo_referencia,
        clave_dedupe,
        id_usuario_creacion,
        id_usuario_modificacion
    )
    VALUES (
        p_id_usuario,
        v_codigo,
        TRIM(p_titulo),
        NULLIF(TRIM(p_mensaje), ''),
        COALESCE(p_payload, '{}'::JSON)::JSONB,
        p_id_referencia,
        NULLIF(TRIM(p_tipo_referencia), ''),
        v_clave,
        p_id_usuario_auditoria,
        p_id_usuario_auditoria
    )
    RETURNING id INTO v_id;

    RETURN json_build_object(
        'registro', (gen_obtener_notificacion(v_id, p_id_usuario))->'registro',
        'creada', TRUE
    );
END;
$$;


--
