--
-- Name: gen_listar_almacenes(character varying, integer, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gen_listar_almacenes(p_busqueda character varying DEFAULT ''::character varying, p_limite integer DEFAULT 10, p_offset integer DEFAULT 0, p_id_sucursal integer DEFAULT NULL::integer) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_registros JSON;
    v_total BIGINT;
BEGIN
    SET TIME ZONE 'America/Lima';

    SELECT COUNT(*) INTO v_total
    FROM gen_almacen a
    INNER JOIN gen_sucursal s ON a.id_sucursal = s.id
    WHERE a.estado = 1
      AND (p_id_sucursal IS NULL OR a.id_sucursal = p_id_sucursal)
      AND (
          p_busqueda = ''
          OR gen_texto_coincide(a.nombre, p_busqueda)
          OR gen_texto_coincide(COALESCE(a.ubicacion, ''), p_busqueda)
          OR gen_texto_coincide(COALESCE(a.descripcion, ''), p_busqueda)
          OR gen_texto_coincide(s.nombre, p_busqueda)
      );

    SELECT COALESCE(json_agg(row_to_json(t)), '[]'::JSON) INTO v_registros
    FROM (
        SELECT
            a.id,
            a.id_sucursal,
            s.nombre AS nombre_sucursal,
            a.nombre,
            a.ubicacion,
            a.descripcion,
            a.id_departamento,
            a.id_provincia,
            a.id_distrito,
            a.estado,
            a.fecha_creacion,
            a.fecha_modificacion,
            a.id_usuario_creacion,
            uc.nombre AS nombre_usuario_creacion,
            a.id_usuario_modificacion,
            um.nombre AS nombre_usuario_modificacion
        FROM gen_almacen a
        INNER JOIN gen_sucursal s ON a.id_sucursal = s.id
        LEFT JOIN auth_usuarios uc ON a.id_usuario_creacion = uc.id
        LEFT JOIN auth_usuarios um ON a.id_usuario_modificacion = um.id
        WHERE a.estado = 1
          AND (p_id_sucursal IS NULL OR a.id_sucursal = p_id_sucursal)
          AND (
              p_busqueda = ''
              OR gen_texto_coincide(a.nombre, p_busqueda)
              OR gen_texto_coincide(COALESCE(a.ubicacion, ''), p_busqueda)
              OR gen_texto_coincide(COALESCE(a.descripcion, ''), p_busqueda)
              OR gen_texto_coincide(s.nombre, p_busqueda)
          )
        ORDER BY a.nombre ASC
        LIMIT p_limite
        OFFSET p_offset
    ) t;

    RETURN json_build_object('registros', v_registros, 'total', v_total);
END;
$$;


--
-- Name: gen_listar_archivos(character varying, integer, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gen_listar_archivos(p_busqueda character varying DEFAULT ''::character varying, p_id_empresa integer DEFAULT NULL::integer, p_limite integer DEFAULT 10, p_offset integer DEFAULT 0) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_registros JSON;
    v_total BIGINT;
BEGIN
    SET TIME ZONE 'America/Lima';

    SELECT COUNT(*) INTO v_total
    FROM gen_archivo a
    WHERE a.estado = 1
      AND (p_id_empresa IS NULL OR a.id_empresa = p_id_empresa)
      AND (
          p_busqueda = ''
          OR gen_texto_coincide(a.nombre_original, p_busqueda)
          OR gen_texto_coincide(a.ruta, p_busqueda)
          OR gen_texto_coincide(COALESCE(a.mime_type, ''), p_busqueda)
      );

    SELECT COALESCE(json_agg(row_to_json(t)), '[]'::JSON) INTO v_registros
    FROM (
        SELECT
            a.id,
            a.nombre_original,
            a.nombre_almacenado,
            a.ruta,
            a.bucket,
            a.mime_type,
            a.extension,
            a.tamanio_bytes,
            a.id_empresa,
            e.nombre_comercial AS nombre_empresa,
            a.estado,
            a.fecha_creacion,
            a.fecha_modificacion,
            a.id_usuario_creacion,
            uc.nombre AS nombre_usuario_creacion,
            a.id_usuario_modificacion,
            um.nombre AS nombre_usuario_modificacion
        FROM gen_archivo a
        LEFT JOIN gen_empresa e ON a.id_empresa = e.id
        LEFT JOIN auth_usuarios uc ON a.id_usuario_creacion = uc.id
        LEFT JOIN auth_usuarios um ON a.id_usuario_modificacion = um.id
        WHERE a.estado = 1
          AND (p_id_empresa IS NULL OR a.id_empresa = p_id_empresa)
          AND (
              p_busqueda = ''
              OR gen_texto_coincide(a.nombre_original, p_busqueda)
              OR gen_texto_coincide(a.ruta, p_busqueda)
              OR gen_texto_coincide(COALESCE(a.mime_type, ''), p_busqueda)
          )
        ORDER BY a.fecha_creacion DESC
        LIMIT p_limite
        OFFSET p_offset
    ) t;

    RETURN json_build_object('registros', v_registros, 'total', v_total);
END;
$$;


--
-- Name: gen_listar_choferes(integer, character varying, integer, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gen_listar_choferes(p_solo_activos integer DEFAULT NULL::integer, p_buscar character varying DEFAULT ''::character varying, p_limite integer DEFAULT 10, p_offset integer DEFAULT 0, p_id_cliente integer DEFAULT NULL::integer) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_registros JSON;
    v_total BIGINT;
BEGIN
    SET TIME ZONE 'America/Lima';

    SELECT COUNT(*) INTO v_total
    FROM gen_chofer ch
    LEFT JOIN cli_clientes c ON ch.id_cliente = c.id
    LEFT JOIN tra_trabajadores tr ON tr.id = ch.id_trabajador
    WHERE (p_solo_activos IS NULL OR ch.estado = p_solo_activos)
      AND (
          p_id_cliente IS NULL
          OR ch.id_cliente = p_id_cliente
          OR (p_id_cliente = -1 AND ch.id_cliente IS NULL)
      )
      AND (
          p_buscar = ''
          OR gen_texto_coincide(COALESCE(tr.nombres, ch.nombres), p_buscar)
          OR gen_texto_coincide(COALESCE(tr.apellido_paterno, ch.apellido_paterno), p_buscar)
          OR gen_texto_coincide(COALESCE(tr.apellido_materno, ch.apellido_materno), p_buscar)
          OR gen_texto_coincide(COALESCE(tr.numero_documento, ch.numero_documento), p_buscar)
      );

    SELECT COALESCE(json_agg(row_to_json(t)), '[]'::JSON) INTO v_registros
    FROM (
        SELECT
            ch.id,
            ch.id_cliente,
            c.razon_social AS cliente_razon_social,
            c.nombres AS cliente_nombres,
            c.apellido_paterno AS cliente_apellido_paterno,
            c.apellido_materno AS cliente_apellido_materno,
            c.numero_documento AS cliente_numero_documento,
            ch.id_trabajador,
            (ch.id_trabajador IS NOT NULL) AS es_chofer_empresa,
            COALESCE(tr.apellido_paterno, ch.apellido_paterno) AS apellido_paterno,
            COALESCE(tr.apellido_materno, ch.apellido_materno) AS apellido_materno,
            COALESCE(tr.nombres, ch.nombres) AS nombres,
            COALESCE(tr.id_tipo_documento, ch.id_tipo_documento) AS id_tipo_documento,
            td.nombre AS nombre_tipo_documento,
            COALESCE(tr.numero_documento, ch.numero_documento) AS numero_documento,
            ch.telefono,
            ch.estado,
            ch.fecha_creacion,
            ch.fecha_modificacion,
            ch.id_usuario_creacion,
            uc.nombre AS nombre_usuario_creacion,
            ch.id_usuario_modificacion,
            um.nombre AS nombre_usuario_modificacion
        FROM gen_chofer ch
        LEFT JOIN cli_clientes c ON ch.id_cliente = c.id
        LEFT JOIN tra_trabajadores tr ON tr.id = ch.id_trabajador
        LEFT JOIN gen_lista_opciones td ON COALESCE(tr.id_tipo_documento, ch.id_tipo_documento) = td.id
        LEFT JOIN auth_usuarios uc ON ch.id_usuario_creacion = uc.id
        LEFT JOIN auth_usuarios um ON ch.id_usuario_modificacion = um.id
        WHERE (p_solo_activos IS NULL OR ch.estado = p_solo_activos)
          AND (
              p_id_cliente IS NULL
              OR ch.id_cliente = p_id_cliente
              OR (p_id_cliente = -1 AND ch.id_cliente IS NULL)
          )
          AND (
              p_buscar = ''
              OR gen_texto_coincide(COALESCE(tr.nombres, ch.nombres), p_buscar)
              OR gen_texto_coincide(COALESCE(tr.apellido_paterno, ch.apellido_paterno), p_buscar)
              OR gen_texto_coincide(COALESCE(tr.apellido_materno, ch.apellido_materno), p_buscar)
              OR gen_texto_coincide(COALESCE(tr.numero_documento, ch.numero_documento), p_buscar)
          )
        ORDER BY COALESCE(tr.nombres, ch.nombres) ASC
        LIMIT p_limite
        OFFSET p_offset
    ) t;

    RETURN json_build_object('registros', v_registros, 'total', v_total);
END;
$$;


--
-- Name: gen_listar_condiciones_pago(character varying, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gen_listar_condiciones_pago(p_busqueda character varying DEFAULT ''::character varying, p_limite integer DEFAULT 10, p_offset integer DEFAULT 0) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_registros JSON;
    v_total BIGINT;
BEGIN
    SET TIME ZONE 'America/Lima';

    SELECT COUNT(*) INTO v_total
    FROM gen_condicion_pago cp
    WHERE cp.estado = 1
      AND (
          p_busqueda = ''
          OR gen_texto_coincide(cp.codigo, p_busqueda)
          OR gen_texto_coincide(cp.nombre, p_busqueda)
      );

    SELECT COALESCE(json_agg(row_to_json(t)), '[]'::JSON) INTO v_registros
    FROM (
        SELECT
            cp.id,
            cp.codigo,
            cp.nombre,
            cp.dias_credito,
            cp.numero_cuotas,
            cp.dia_mes_pago,
            CASE
                WHEN COALESCE(cp.numero_cuotas, 0) > 1 THEN 'CUOTAS'
                WHEN COALESCE(cp.dias_credito, 0) > 0 THEN 'CREDITO'
                ELSE 'CONTADO'
            END AS modalidad,
            cp.estado,
            cp.fecha_creacion,
            cp.fecha_modificacion,
            cp.id_usuario_creacion,
            uc.nombre AS nombre_usuario_creacion,
            cp.id_usuario_modificacion,
            um.nombre AS nombre_usuario_modificacion
        FROM gen_condicion_pago cp
        LEFT JOIN auth_usuarios uc ON cp.id_usuario_creacion = uc.id
        LEFT JOIN auth_usuarios um ON cp.id_usuario_modificacion = um.id
        WHERE cp.estado = 1
          AND (
              p_busqueda = ''
              OR gen_texto_coincide(cp.codigo, p_busqueda)
              OR gen_texto_coincide(cp.nombre, p_busqueda)
          )
        ORDER BY cp.nombre ASC
        LIMIT p_limite
        OFFSET p_offset
    ) t;

    RETURN json_build_object('registros', v_registros, 'total', v_total);
END;
$$;


--
-- Name: gen_listar_configuraciones_servicio(character varying, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gen_listar_configuraciones_servicio(p_busqueda character varying DEFAULT ''::character varying, p_limite integer DEFAULT 10, p_offset integer DEFAULT 0) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_registros JSON;
    v_total BIGINT;
BEGIN
    SET TIME ZONE 'America/Lima';

    SELECT COUNT(*) INTO v_total
    FROM gen_configuracion_servicio cs
    WHERE cs.estado = 1
      AND (
          p_busqueda = ''
          OR gen_texto_coincide(cs.codigo, p_busqueda)
          OR gen_texto_coincide(cs.nombre, p_busqueda)
          OR gen_texto_coincide(COALESCE(cs.usuario, ''), p_busqueda)
          OR gen_texto_coincide(COALESCE(cs.email, ''), p_busqueda)
          OR gen_texto_coincide(COALESCE(cs.url, ''), p_busqueda)
      );

    SELECT COALESCE(json_agg(row_to_json(t)), '[]'::JSON) INTO v_registros
    FROM (
        SELECT
            cs.id,
            cs.codigo,
            cs.nombre,
            cs.usuario,
            (cs.contrasena IS NOT NULL AND TRIM(cs.contrasena) <> '') AS tiene_contrasena,
            cs.email,
            cs.url,
            cs.observacion,
            cs.estado,
            cs.fecha_creacion,
            cs.fecha_modificacion,
            cs.id_usuario_creacion,
            uc.nombre AS nombre_usuario_creacion,
            cs.id_usuario_modificacion,
            um.nombre AS nombre_usuario_modificacion
        FROM gen_configuracion_servicio cs
        LEFT JOIN auth_usuarios uc ON cs.id_usuario_creacion = uc.id
        LEFT JOIN auth_usuarios um ON cs.id_usuario_modificacion = um.id
        WHERE cs.estado = 1
          AND (
              p_busqueda = ''
              OR gen_texto_coincide(cs.codigo, p_busqueda)
              OR gen_texto_coincide(cs.nombre, p_busqueda)
              OR gen_texto_coincide(COALESCE(cs.usuario, ''), p_busqueda)
              OR gen_texto_coincide(COALESCE(cs.email, ''), p_busqueda)
              OR gen_texto_coincide(COALESCE(cs.url, ''), p_busqueda)
          )
        ORDER BY cs.nombre ASC
        LIMIT p_limite
        OFFSET p_offset
    ) t;

    RETURN json_build_object('registros', v_registros, 'total', v_total);
END;
$$;


--
-- Name: gen_listar_configuraciones_sunat(character varying, integer, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gen_listar_configuraciones_sunat(p_busqueda character varying DEFAULT ''::character varying, p_limite integer DEFAULT 10, p_offset integer DEFAULT 0, p_id_empresa integer DEFAULT NULL::integer) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_registros JSON;
    v_total BIGINT;
BEGIN
    SET TIME ZONE 'America/Lima';

    SELECT COUNT(*) INTO v_total
    FROM gen_configuracion_sunat cs
    INNER JOIN gen_empresa e ON cs.id_empresa = e.id
    LEFT JOIN gen_lista_opciones lo ON cs.id_ambiente = lo.id
    WHERE cs.estado = 1
      AND (p_id_empresa IS NULL OR cs.id_empresa = p_id_empresa)
      AND (
          p_busqueda = ''
          OR gen_texto_coincide(cs.usuario_sol, p_busqueda)
          OR gen_texto_coincide(COALESCE(e.nombre_comercial, ''), p_busqueda)
          OR gen_texto_coincide(COALESCE(lo.nombre, ''), p_busqueda)
          OR gen_texto_coincide(COALESCE(cs.proveedor_pse, ''), p_busqueda)
      );

    SELECT COALESCE(json_agg(row_to_json(t)), '[]'::JSON) INTO v_registros
    FROM (
        SELECT
            cs.id,
            cs.id_empresa,
            e.nombre_comercial,
            e.ruc AS ruc_empresa,
            cs.usuario_sol,
            cs.clave_sol,
            cs.certificado_digital,
            cs.clave_certificado,
            (cs.clave_sol IS NOT NULL AND TRIM(cs.clave_sol) <> '') AS tiene_clave_sol,
            (cs.clave_certificado IS NOT NULL AND TRIM(cs.clave_certificado) <> '') AS tiene_clave_certificado,
            cs.id_ambiente,
            lo.nombre AS nombre_ambiente,
            cs.proveedor_pse,
            cs.pse_habilitado,
            cs.api_base_url,
            cs.api_token,
            (cs.api_token IS NOT NULL AND TRIM(cs.api_token) <> '') AS tiene_api_token,
            cs.api_usuario,
            cs.api_clave,
            (cs.api_clave IS NOT NULL AND TRIM(cs.api_clave) <> '') AS tiene_api_clave,
            COALESCE(NULLIF(TRIM(cs.ruc_emisor), ''), e.ruc) AS ruc_emisor,
            cs.client_id,
            cs.client_secret,
            (cs.client_secret IS NOT NULL AND TRIM(cs.client_secret) <> '') AS tiene_client_secret,
            cs.timeout_ms,
            cs.estado,
            cs.fecha_creacion,
            cs.fecha_modificacion,
            cs.id_usuario_creacion,
            uc.nombre AS nombre_usuario_creacion,
            cs.id_usuario_modificacion,
            um.nombre AS nombre_usuario_modificacion
        FROM gen_configuracion_sunat cs
        INNER JOIN gen_empresa e ON cs.id_empresa = e.id
        LEFT JOIN gen_lista_opciones lo ON cs.id_ambiente = lo.id
        LEFT JOIN auth_usuarios uc ON cs.id_usuario_creacion = uc.id
        LEFT JOIN auth_usuarios um ON cs.id_usuario_modificacion = um.id
        WHERE cs.estado = 1
          AND (p_id_empresa IS NULL OR cs.id_empresa = p_id_empresa)
          AND (
              p_busqueda = ''
              OR gen_texto_coincide(cs.usuario_sol, p_busqueda)
              OR gen_texto_coincide(COALESCE(e.nombre_comercial, ''), p_busqueda)
              OR gen_texto_coincide(COALESCE(lo.nombre, ''), p_busqueda)
              OR gen_texto_coincide(COALESCE(cs.proveedor_pse, ''), p_busqueda)
          )
        ORDER BY e.nombre_comercial ASC, cs.usuario_sol ASC
        LIMIT p_limite
        OFFSET p_offset
    ) t;

    RETURN json_build_object('registros', v_registros, 'total', v_total);
END;
$$;


--
-- Name: gen_listar_cuentas_bancarias(integer, character varying, integer, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gen_listar_cuentas_bancarias(p_solo_activos integer DEFAULT NULL::integer, p_buscar character varying DEFAULT ''::character varying, p_limite integer DEFAULT 10, p_offset integer DEFAULT 0, p_id_cliente integer DEFAULT NULL::integer) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_registros JSON;
    v_total BIGINT;
BEGIN
    SET TIME ZONE 'America/Lima';

    SELECT COUNT(*) INTO v_total
    FROM gen_cuenta_bancaria cb
    WHERE (p_solo_activos IS NULL OR cb.estado = p_solo_activos)
      AND (p_id_cliente IS NULL OR cb.id_cliente = p_id_cliente OR (p_id_cliente = -1 AND cb.id_cliente IS NULL))
      AND (
          p_buscar = ''
          OR gen_texto_coincide(COALESCE(cb.titular, ''), p_buscar)
          OR gen_texto_coincide(COALESCE(cb.numero_cuenta, ''), p_buscar)
          OR gen_texto_coincide(COALESCE(cb.numero_cuenta_interbancaria, ''), p_buscar)
          OR gen_texto_coincide(COALESCE(cb.telefono_billetera, ''), p_buscar)
      );

    SELECT COALESCE(json_agg(row_to_json(t)), '[]'::JSON) INTO v_registros
    FROM (
        SELECT
            cb.id,
            cb.id_cliente,
            c.razon_social AS cliente_razon_social,
            c.nombres AS cliente_nombres,
            c.apellido_paterno AS cliente_apellido_paterno,
            c.apellido_materno AS cliente_apellido_materno,
            c.numero_documento AS cliente_numero_documento,
            cb.id_banco,
            b.nombre AS nombre_banco,
            cb.id_tipo_cuenta,
            tc.nombre AS nombre_tipo_cuenta,
            cb.titular,
            cb.numero_cuenta,
            cb.numero_cuenta_interbancaria,
            cb.telefono_billetera,
            cb.es_principal,
            cb.estado,
            cb.fecha_creacion,
            cb.fecha_modificacion,
            cb.id_usuario_creacion,
            uc.nombre AS nombre_usuario_creacion,
            cb.id_usuario_modificacion,
            um.nombre AS nombre_usuario_modificacion
        FROM gen_cuenta_bancaria cb
        LEFT JOIN cli_clientes c ON cb.id_cliente = c.id
        LEFT JOIN gen_lista_opciones b ON cb.id_banco = b.id
        LEFT JOIN gen_lista_opciones tc ON cb.id_tipo_cuenta = tc.id
        LEFT JOIN auth_usuarios uc ON cb.id_usuario_creacion = uc.id
        LEFT JOIN auth_usuarios um ON cb.id_usuario_modificacion = um.id
        WHERE (p_solo_activos IS NULL OR cb.estado = p_solo_activos)
          AND (p_id_cliente IS NULL OR cb.id_cliente = p_id_cliente OR (p_id_cliente = -1 AND cb.id_cliente IS NULL))
          AND (
              p_buscar = ''
              OR gen_texto_coincide(COALESCE(cb.titular, ''), p_buscar)
              OR gen_texto_coincide(COALESCE(cb.numero_cuenta, ''), p_buscar)
              OR gen_texto_coincide(COALESCE(cb.numero_cuenta_interbancaria, ''), p_buscar)
              OR gen_texto_coincide(COALESCE(cb.telefono_billetera, ''), p_buscar)
          )
        ORDER BY cb.es_principal DESC, cb.id ASC
        LIMIT p_limite
        OFFSET p_offset
    ) t;

    RETURN json_build_object('registros', v_registros, 'total', v_total);
END;
$$;


--
-- Name: gen_listar_departamentos(integer); Type: FUNCTION; Schema: public; Owner: -
