--
-- Name: gen_listar_documentos_por_vencer_notificar(integer, integer, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gen_listar_documentos_por_vencer_notificar(p_dias_min integer DEFAULT 3, p_dias_max integer DEFAULT 7, p_fecha date DEFAULT NULL::date) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_fecha DATE;
    v_min INTEGER;
    v_max INTEGER;
    v_registros JSON;
BEGIN
    SET TIME ZONE 'America/Lima';
    v_fecha := COALESCE(p_fecha, CURRENT_DATE);
    v_min := GREATEST(COALESCE(p_dias_min, 3), 0);
    v_max := GREATEST(COALESCE(p_dias_max, 7), v_min);

    SELECT COALESCE(json_agg(t.row_data ORDER BY t.fecha_vencimiento, t.id), '[]'::JSON)
    INTO v_registros
    FROM (
        SELECT json_build_object(
            'id', dv.id,
            'descripcion', dv.descripcion,
            'numero_documento', dv.numero_documento,
            'fecha_vencimiento', dv.fecha_vencimiento,
            'dias_para_vencer', (dv.fecha_vencimiento - v_fecha),
            'nombre_categoria', cat.nombre,
            'id_vehiculo', dv.id_vehiculo,
            'vehiculo_placa', v.placa,
            'nombre_estado', est.nombre
        ) AS row_data,
        dv.id,
        dv.fecha_vencimiento
        FROM gen_documento_vencimiento dv
        LEFT JOIN gen_lista_opciones cat ON cat.id = dv.id_categoria
        LEFT JOIN gen_vehiculo v ON v.id = dv.id_vehiculo
        LEFT JOIN gen_lista_opciones est ON est.id = dv.id_estado
        WHERE dv.estado = 1
          AND dv.fecha_vencimiento IS NOT NULL
          AND dv.fecha_vencimiento BETWEEN (v_fecha + v_min) AND (v_fecha + v_max)
    ) t;

    RETURN json_build_object('registros', v_registros);
END;
$$;


--
-- Name: gen_listar_documentos_vencidos_notificar(date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gen_listar_documentos_vencidos_notificar(p_fecha date DEFAULT NULL::date) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_fecha DATE;
    v_registros JSON;
BEGIN
    SET TIME ZONE 'America/Lima';
    v_fecha := COALESCE(p_fecha, CURRENT_DATE);

    SELECT COALESCE(json_agg(t.row_data ORDER BY t.fecha_vencimiento, t.id), '[]'::JSON)
    INTO v_registros
    FROM (
        SELECT json_build_object(
            'id', dv.id,
            'descripcion', dv.descripcion,
            'numero_documento', dv.numero_documento,
            'fecha_vencimiento', dv.fecha_vencimiento,
            'dias_vencido', (v_fecha - dv.fecha_vencimiento),
            'nombre_categoria', cat.nombre,
            'id_vehiculo', dv.id_vehiculo,
            'vehiculo_placa', v.placa,
            'nombre_estado', est.nombre
        ) AS row_data,
        dv.id,
        dv.fecha_vencimiento
        FROM gen_documento_vencimiento dv
        LEFT JOIN gen_lista_opciones cat ON cat.id = dv.id_categoria
        LEFT JOIN gen_vehiculo v ON v.id = dv.id_vehiculo
        LEFT JOIN gen_lista_opciones est ON est.id = dv.id_estado
        WHERE dv.estado = 1
          AND dv.fecha_vencimiento IS NOT NULL
          AND dv.fecha_vencimiento < v_fecha
    ) t;

    RETURN json_build_object('registros', v_registros);
END;
$$;


--
-- Name: gen_listar_documentos_vencimiento(integer, character varying, integer, integer, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gen_listar_documentos_vencimiento(p_solo_activos integer DEFAULT NULL::integer, p_buscar character varying DEFAULT ''::character varying, p_limite integer DEFAULT 10, p_offset integer DEFAULT 0, p_id_categoria integer DEFAULT NULL::integer, p_id_vehiculo integer DEFAULT NULL::integer) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_registros JSON;
    v_total BIGINT;
BEGIN
    SET TIME ZONE 'America/Lima';

    SELECT COUNT(*) INTO v_total
    FROM gen_documento_vencimiento dv
    WHERE (p_solo_activos IS NULL OR dv.estado = p_solo_activos)
      AND (p_id_categoria IS NULL OR dv.id_categoria = p_id_categoria)
      AND (p_id_vehiculo IS NULL OR dv.id_vehiculo = p_id_vehiculo)
      AND (
          p_buscar = ''
          OR gen_texto_coincide(COALESCE(dv.descripcion, ''), p_buscar)
          OR gen_texto_coincide(COALESCE(dv.numero_documento, ''), p_buscar)
          OR gen_texto_coincide(COALESCE(dv.observacion, ''), p_buscar)
      );

    SELECT COALESCE(json_agg(row_to_json(t)), '[]'::JSON) INTO v_registros
    FROM (
        SELECT
            dv.id,
            dv.id_categoria,
            cat.nombre AS nombre_categoria,
            dv.descripcion,
            dv.id_vehiculo,
            v.placa AS vehiculo_placa,
            v.marca AS vehiculo_marca,
            v.modelo AS vehiculo_modelo,
            dv.fecha_vencimiento,
            dv.fecha_renovacion,
            dv.numero_documento,
            dv.observacion,
            dv.id_estado,
            est.nombre AS nombre_estado,
            dv.estado,
            dv.fecha_creacion,
            dv.fecha_modificacion,
            dv.id_usuario_creacion,
            uc.nombre AS nombre_usuario_creacion,
            dv.id_usuario_modificacion,
            um.nombre AS nombre_usuario_modificacion
        FROM gen_documento_vencimiento dv
        LEFT JOIN gen_lista_opciones cat ON dv.id_categoria = cat.id
        LEFT JOIN gen_vehiculo v ON dv.id_vehiculo = v.id
        LEFT JOIN gen_lista_opciones est ON dv.id_estado = est.id
        LEFT JOIN auth_usuarios uc ON dv.id_usuario_creacion = uc.id
        LEFT JOIN auth_usuarios um ON dv.id_usuario_modificacion = um.id
        WHERE (p_solo_activos IS NULL OR dv.estado = p_solo_activos)
          AND (p_id_categoria IS NULL OR dv.id_categoria = p_id_categoria)
          AND (p_id_vehiculo IS NULL OR dv.id_vehiculo = p_id_vehiculo)
          AND (
              p_buscar = ''
              OR gen_texto_coincide(COALESCE(dv.descripcion, ''), p_buscar)
              OR gen_texto_coincide(COALESCE(dv.numero_documento, ''), p_buscar)
              OR gen_texto_coincide(COALESCE(dv.observacion, ''), p_buscar)
          )
        ORDER BY dv.fecha_vencimiento ASC, dv.id ASC
        LIMIT p_limite
        OFFSET p_offset
    ) t;

    RETURN json_build_object('registros', v_registros, 'total', v_total);
END;
$$;


--
-- Name: gen_listar_documentos_vencimiento(integer, character varying, integer, integer, integer, integer, integer, character varying, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gen_listar_documentos_vencimiento(p_solo_activos integer DEFAULT NULL::integer, p_buscar character varying DEFAULT ''::character varying, p_limite integer DEFAULT 10, p_offset integer DEFAULT 0, p_id_categoria integer DEFAULT NULL::integer, p_id_vehiculo integer DEFAULT NULL::integer, p_id_sucursal integer DEFAULT NULL::integer, p_estado character varying DEFAULT NULL::character varying, p_dias_alerta integer DEFAULT 30) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_result JSON;
    v_hoy DATE;
    v_dias_alerta INTEGER;
    v_estado VARCHAR;
BEGIN
    SET TIME ZONE 'America/Lima';
    v_hoy := CURRENT_DATE;
    v_dias_alerta := GREATEST(COALESCE(p_dias_alerta, 30), 0);
    v_estado := NULLIF(TRIM(UPPER(COALESCE(p_estado, ''))), '');
    WITH base AS (
        SELECT
            dv.*,
            CASE
                WHEN dv.fecha_vencimiento < v_hoy THEN 'VENCIDO'
                WHEN dv.fecha_vencimiento <= v_hoy + (v_dias_alerta || ' days')::interval THEN 'POR_VENCER'
                ELSE 'VIGENTE'
            END AS estado_calculado,
            (dv.fecha_vencimiento - v_hoy) AS dias_para_vencer
        FROM gen_documento_vencimiento dv
        WHERE (p_solo_activos IS NULL OR dv.estado = p_solo_activos)
          AND (p_id_categoria IS NULL OR dv.id_categoria = p_id_categoria)
          AND (p_id_vehiculo IS NULL OR dv.id_vehiculo = p_id_vehiculo)
          AND (p_id_sucursal IS NULL OR dv.id_sucursal = p_id_sucursal)
          AND (
              p_buscar = ''
              OR gen_texto_coincide(COALESCE(dv.descripcion, ''), p_buscar)
              OR gen_texto_coincide(COALESCE(dv.numero_documento, ''), p_buscar)
              OR gen_texto_coincide(COALESCE(dv.observacion, ''), p_buscar)
          )
    ),
    filtrado AS (
        SELECT * FROM base
        WHERE v_estado IS NULL OR estado_calculado = v_estado
    )
    SELECT json_build_object(
        'total', (SELECT COUNT(*) FROM filtrado),
        'resumen', json_build_object(
            'vigentes', (SELECT COUNT(*) FROM base WHERE estado_calculado = 'VIGENTE'),
            'porVencer', (SELECT COUNT(*) FROM base WHERE estado_calculado = 'POR_VENCER'),
            'vencidos', (SELECT COUNT(*) FROM base WHERE estado_calculado = 'VENCIDO')
        ),
        'registros', COALESCE((
            SELECT json_agg(row_to_json(p) ORDER BY p.fecha_vencimiento ASC, p.id ASC)
            FROM (
                SELECT
                    f.id,
                    f.id_categoria,
                    cat.nombre AS nombre_categoria,
                    f.descripcion,
                    f.id_vehiculo,
                    veh.placa AS vehiculo_placa,
                    veh.marca AS vehiculo_marca,
                    veh.modelo AS vehiculo_modelo,
                    f.id_sucursal,
                    suc.nombre AS sucursal_nombre,
                    f.fecha_vencimiento,
                    f.fecha_renovacion,
                    f.numero_documento,
                    f.observacion,
                    f.id_estado,
                    f.estado_calculado,
                    f.dias_para_vencer,
                    f.estado,
                    f.fecha_creacion,
                    f.fecha_modificacion,
                    f.id_usuario_creacion,
                    uc.nombre AS nombre_usuario_creacion,
                    f.id_usuario_modificacion,
                    um.nombre AS nombre_usuario_modificacion
                FROM filtrado f
                LEFT JOIN gen_lista_opciones cat ON f.id_categoria = cat.id
                LEFT JOIN gen_vehiculo veh ON f.id_vehiculo = veh.id
                LEFT JOIN gen_sucursal suc ON f.id_sucursal = suc.id
                LEFT JOIN auth_usuarios uc ON f.id_usuario_creacion = uc.id
                LEFT JOIN auth_usuarios um ON f.id_usuario_modificacion = um.id
                ORDER BY f.fecha_vencimiento ASC, f.id ASC
                LIMIT p_limite
                OFFSET p_offset
            ) p
        ), '[]'::json)
    )
    INTO v_result;
    RETURN v_result;
END;
$$;


--
-- Name: gen_listar_empresas(character varying, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gen_listar_empresas(p_busqueda character varying DEFAULT ''::character varying, p_limite integer DEFAULT 10, p_offset integer DEFAULT 0) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_registros JSON;
    v_total BIGINT;
BEGIN
    SET TIME ZONE 'America/Lima';

    SELECT COUNT(*) INTO v_total
    FROM gen_empresa e
    WHERE e.estado = 1
      AND (
          p_busqueda = ''
          OR gen_texto_coincide(e.ruc, p_busqueda)
          OR gen_texto_coincide(COALESCE(e.razon_social, ''), p_busqueda)
          OR gen_texto_coincide(COALESCE(e.nombre_comercial, ''), p_busqueda)
          OR gen_texto_coincide(COALESCE(e.email, ''), p_busqueda)
      );

    SELECT COALESCE(json_agg(row_to_json(t)), '[]'::JSON) INTO v_registros
    FROM (
        SELECT
            e.id,
            e.ruc,
            e.razon_social,
            e.nombre_comercial,
            e.direccion,
            e.telefono,
            e.email,
            e.tolerancia_m3_ruta_pueblo,
            e.psi_minimo_util,
            e.estado,
            e.fecha_creacion,
            e.fecha_modificacion,
            e.id_usuario_creacion,
            uc.nombre AS nombre_usuario_creacion,
            e.id_usuario_modificacion,
            um.nombre AS nombre_usuario_modificacion
        FROM gen_empresa e
        LEFT JOIN auth_usuarios uc ON e.id_usuario_creacion = uc.id
        LEFT JOIN auth_usuarios um ON e.id_usuario_modificacion = um.id
        WHERE e.estado = 1
          AND (
              p_busqueda = ''
              OR gen_texto_coincide(e.ruc, p_busqueda)
              OR gen_texto_coincide(COALESCE(e.razon_social, ''), p_busqueda)
              OR gen_texto_coincide(COALESCE(e.nombre_comercial, ''), p_busqueda)
              OR gen_texto_coincide(COALESCE(e.email, ''), p_busqueda)
          )
        ORDER BY e.nombre_comercial ASC
        LIMIT p_limite
        OFFSET p_offset
    ) t;

    RETURN json_build_object('registros', v_registros, 'total', v_total);
END;
$$;


--
-- Name: gen_listar_licencias(integer, character varying, integer, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gen_listar_licencias(p_solo_activos integer DEFAULT NULL::integer, p_buscar character varying DEFAULT ''::character varying, p_limite integer DEFAULT 10, p_offset integer DEFAULT 0, p_id_chofer integer DEFAULT NULL::integer) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_registros JSON;
    v_total BIGINT;
BEGIN
    SET TIME ZONE 'America/Lima';

    SELECT COUNT(*) INTO v_total
    FROM gen_licencia gl
    WHERE (p_solo_activos IS NULL OR gl.estado = p_solo_activos)
      AND (p_id_chofer IS NULL OR gl.id_chofer = p_id_chofer)
      AND (
          p_buscar = ''
          OR gen_texto_coincide(gl.codigo, p_buscar)
      );

    SELECT COALESCE(json_agg(row_to_json(t)), '[]'::JSON) INTO v_registros
    FROM (
        SELECT
            gl.id,
            gl.id_chofer,
            ch.nombres AS chofer_nombres,
            ch.apellido_paterno AS chofer_apellido_paterno,
            ch.apellido_materno AS chofer_apellido_materno,
            ch.numero_documento AS chofer_numero_documento,
            gl.codigo,
            gl.id_tipo_licencia,
            tlo.nombre AS nombre_tipo_licencia,
            gl.id_categoria_licencia,
            clo.nombre AS nombre_categoria_licencia,
            gl.fecha_emision,
            gl.fecha_vencimiento,
            gl.estado,
            gl.fecha_creacion,
            gl.fecha_modificacion,
            gl.id_usuario_creacion,
            uc.nombre AS nombre_usuario_creacion,
            gl.id_usuario_modificacion,
            um.nombre AS nombre_usuario_modificacion
        FROM gen_licencia gl
        LEFT JOIN gen_chofer ch ON gl.id_chofer = ch.id
        LEFT JOIN gen_lista_opciones tlo ON gl.id_tipo_licencia = tlo.id
        LEFT JOIN gen_lista_opciones clo ON gl.id_categoria_licencia = clo.id
        LEFT JOIN auth_usuarios uc ON gl.id_usuario_creacion = uc.id
        LEFT JOIN auth_usuarios um ON gl.id_usuario_modificacion = um.id
        WHERE (p_solo_activos IS NULL OR gl.estado = p_solo_activos)
          AND (p_id_chofer IS NULL OR gl.id_chofer = p_id_chofer)
          AND (
              p_buscar = ''
              OR gen_texto_coincide(gl.codigo, p_buscar)
          )
        ORDER BY gl.fecha_vencimiento DESC
        LIMIT p_limite
        OFFSET p_offset
    ) t;

    RETURN json_build_object('registros', v_registros, 'total', v_total);
END;
$$;


--
-- Name: gen_listar_licencias_por_vencer_notificar(integer, integer, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gen_listar_licencias_por_vencer_notificar(p_dias_min integer DEFAULT 3, p_dias_max integer DEFAULT 7, p_fecha date DEFAULT NULL::date) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_fecha DATE;
    v_min INTEGER;
    v_max INTEGER;
    v_registros JSON;
BEGIN
    SET TIME ZONE 'America/Lima';
    v_fecha := COALESCE(p_fecha, CURRENT_DATE);
    v_min := GREATEST(COALESCE(p_dias_min, 3), 0);
    v_max := GREATEST(COALESCE(p_dias_max, 7), v_min);

    SELECT COALESCE(json_agg(t.row_data ORDER BY t.fecha_vencimiento, t.id), '[]'::JSON)
    INTO v_registros
    FROM (
        SELECT json_build_object(
            'id', gl.id,
            'codigo', gl.codigo,
            'fecha_vencimiento', gl.fecha_vencimiento,
            'dias_para_vencer', (gl.fecha_vencimiento - v_fecha),
            'nombre_tipo_licencia', tlo.nombre,
            'nombre_categoria_licencia', clo.nombre,
            'chofer_nombre', TRIM(CONCAT_WS(' ', ch.nombres, ch.apellido_paterno, ch.apellido_materno)),
            'id_chofer', gl.id_chofer
        ) AS row_data,
        gl.id,
        gl.fecha_vencimiento
        FROM gen_licencia gl
        LEFT JOIN gen_chofer ch ON ch.id = gl.id_chofer
        LEFT JOIN gen_lista_opciones tlo ON tlo.id = gl.id_tipo_licencia
        LEFT JOIN gen_lista_opciones clo ON clo.id = gl.id_categoria_licencia
        WHERE gl.estado = 1
          AND gl.fecha_vencimiento IS NOT NULL
          AND gl.fecha_vencimiento BETWEEN (v_fecha + v_min) AND (v_fecha + v_max)
    ) t;

    RETURN json_build_object('registros', v_registros);
END;
$$;


--
-- Name: gen_listar_licencias_vencidas_notificar(date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gen_listar_licencias_vencidas_notificar(p_fecha date DEFAULT NULL::date) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_fecha DATE;
    v_registros JSON;
BEGIN
    SET TIME ZONE 'America/Lima';
    v_fecha := COALESCE(p_fecha, CURRENT_DATE);

    SELECT COALESCE(json_agg(t.row_data ORDER BY t.fecha_vencimiento, t.id), '[]'::JSON)
    INTO v_registros
    FROM (
        SELECT json_build_object(
            'id', gl.id,
            'codigo', gl.codigo,
            'fecha_vencimiento', gl.fecha_vencimiento,
            'dias_vencido', (v_fecha - gl.fecha_vencimiento),
            'nombre_tipo_licencia', tlo.nombre,
            'nombre_categoria_licencia', clo.nombre,
            'chofer_nombre', TRIM(CONCAT_WS(' ', ch.nombres, ch.apellido_paterno, ch.apellido_materno)),
            'id_chofer', gl.id_chofer
        ) AS row_data,
        gl.id,
        gl.fecha_vencimiento
        FROM gen_licencia gl
        LEFT JOIN gen_chofer ch ON ch.id = gl.id_chofer
        LEFT JOIN gen_lista_opciones tlo ON tlo.id = gl.id_tipo_licencia
        LEFT JOIN gen_lista_opciones clo ON clo.id = gl.id_categoria_licencia
        WHERE gl.estado = 1
          AND gl.fecha_vencimiento IS NOT NULL
          AND gl.fecha_vencimiento < v_fecha
    ) t;

    RETURN json_build_object('registros', v_registros);
END;
$$;


--
-- Name: gen_listar_lista_opciones(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gen_listar_lista_opciones(p_id_lista integer) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_registros JSON;
BEGIN
    SET TIME ZONE 'America/Lima';

    IF p_id_lista IS NULL THEN
        RETURN '[]'::JSON;
    END IF;

    SELECT COALESCE(json_agg(row_to_json(t) ORDER BY t.nombre ASC), '[]'::JSON) INTO v_registros
    FROM (
        SELECT
            lo.id,
            lo.id_lista,
            l.nombre AS nombre_lista,
            lo.nombre,
            lo.descripcion,
            lo.estado
        FROM gen_lista_opciones lo
        INNER JOIN gen_lista l ON lo.id_lista = l.id
        WHERE lo.estado = 1
          AND l.estado = 1
          AND lo.id_lista = p_id_lista
    ) t;

    RETURN v_registros;
END;
$$;


--
-- Name: gen_listar_notificaciones(integer, integer, character varying, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gen_listar_notificaciones(p_id_usuario integer, p_solo_no_leidas integer DEFAULT 0, p_buscar character varying DEFAULT ''::character varying, p_limite integer DEFAULT 20, p_offset integer DEFAULT 0) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_total INTEGER;
    v_registros JSON;
    v_buscar VARCHAR;
BEGIN
    SET TIME ZONE 'America/Lima';

    IF p_id_usuario IS NULL THEN
        RETURN json_build_object('error', 'El usuario es obligatorio', 'registros', '[]'::JSON, 'total', 0);
    END IF;

    v_buscar := LOWER(TRIM(COALESCE(p_buscar, '')));

    SELECT COUNT(*)::INTEGER
    INTO v_total
    FROM gen_notificacion n
    WHERE n.id_usuario = p_id_usuario
      AND n.estado = 1
      AND (COALESCE(p_solo_no_leidas, 0) = 0 OR n.leida = FALSE)
      AND (
          v_buscar = ''
          OR LOWER(n.titulo) LIKE '%' || v_buscar || '%'
          OR LOWER(COALESCE(n.mensaje, '')) LIKE '%' || v_buscar || '%'
          OR LOWER(n.codigo_tipo) LIKE '%' || v_buscar || '%'
      );

    SELECT COALESCE(json_agg(t.row_data), '[]'::JSON)
    INTO v_registros
    FROM (
        SELECT json_build_object(
            'id', n.id,
            'id_usuario', n.id_usuario,
            'codigo_tipo', n.codigo_tipo,
            'titulo', n.titulo,
            'mensaje', n.mensaje,
            'payload', n.payload,
            'id_referencia', n.id_referencia,
            'tipo_referencia', n.tipo_referencia,
            'clave_dedupe', n.clave_dedupe,
            'leida', n.leida,
            'fecha_lectura', n.fecha_lectura,
            'fecha_creacion', n.fecha_creacion,
            'fecha_modificacion', n.fecha_modificacion
        ) AS row_data
        FROM gen_notificacion n
        WHERE n.id_usuario = p_id_usuario
          AND n.estado = 1
          AND (COALESCE(p_solo_no_leidas, 0) = 0 OR n.leida = FALSE)
          AND (
              v_buscar = ''
              OR LOWER(n.titulo) LIKE '%' || v_buscar || '%'
              OR LOWER(COALESCE(n.mensaje, '')) LIKE '%' || v_buscar || '%'
              OR LOWER(n.codigo_tipo) LIKE '%' || v_buscar || '%'
          )
        ORDER BY n.leida ASC, n.fecha_creacion DESC
        LIMIT GREATEST(COALESCE(p_limite, 20), 1)
        OFFSET GREATEST(COALESCE(p_offset, 0), 0)
    ) t;

    RETURN json_build_object('registros', v_registros, 'total', v_total);
END;
$$;


--
-- Name: gen_listar_paises(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gen_listar_paises() RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_registros JSON;
BEGIN
    SET TIME ZONE 'America/Lima';

    SELECT COALESCE(json_agg(row_to_json(t) ORDER BY t.nombre ASC), '[]'::JSON) INTO v_registros
    FROM (
        SELECT
            p.id,
            p.nombre,
            p.estado
        FROM gen_pais p
        WHERE p.estado = 1
    ) t;

    RETURN v_registros;
END;
$$;


--
-- Name: gen_listar_provincias(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gen_listar_provincias(p_id_departamento integer DEFAULT NULL::integer) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_registros JSON;
BEGIN
    SET TIME ZONE 'America/Lima';

    SELECT COALESCE(json_agg(row_to_json(t) ORDER BY t.nombre ASC), '[]'::JSON) INTO v_registros
    FROM (
        SELECT
            pr.id,
            pr.id_departamento,
            d.nombre AS nombre_departamento,
            d.id_pais,
            pr.nombre,
            pr.estado
        FROM gen_provincia pr
        INNER JOIN gen_departamento d ON pr.id_departamento = d.id
        WHERE pr.estado = 1
          AND d.estado = 1
          AND (p_id_departamento IS NULL OR pr.id_departamento = p_id_departamento)
    ) t;

    RETURN v_registros;
END;
$$;


--
-- Name: gen_listar_sucursales(character varying, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gen_listar_sucursales(p_busqueda character varying DEFAULT ''::character varying, p_limite integer DEFAULT 10, p_offset integer DEFAULT 0) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_registros JSON;
    v_total BIGINT;
BEGIN
    SET TIME ZONE 'America/Lima';

    SELECT COUNT(*) INTO v_total
    FROM gen_sucursal s
    WHERE s.estado = 1
      AND (
          p_busqueda = ''
          OR gen_texto_coincide(s.codigo, p_busqueda)
          OR gen_texto_coincide(s.nombre, p_busqueda)
          OR gen_texto_coincide(COALESCE(s.direccion, ''), p_busqueda)
          OR gen_texto_coincide(COALESCE(s.telefono, ''), p_busqueda)
      );

    SELECT COALESCE(json_agg(row_to_json(t)), '[]'::JSON) INTO v_registros
    FROM (
        SELECT
            s.id,
            s.codigo,
            s.nombre,
            s.direccion,
            s.id_departamento,
            dep.nombre AS nombre_departamento,
            s.id_provincia,
            prov.nombre AS nombre_provincia,
            s.id_distrito,
            dist.nombre AS nombre_distrito,
            s.telefono,
            s.estado,
            s.fecha_creacion,
            s.fecha_modificacion,
            s.id_usuario_creacion,
            uc.nombre AS nombre_usuario_creacion,
            s.id_usuario_modificacion,
            um.nombre AS nombre_usuario_modificacion
        FROM gen_sucursal s
        LEFT JOIN gen_departamento dep ON dep.id = s.id_departamento
        LEFT JOIN gen_provincia prov ON prov.id = s.id_provincia
        LEFT JOIN gen_distrito dist ON dist.id = s.id_distrito
        LEFT JOIN auth_usuarios uc ON s.id_usuario_creacion = uc.id
        LEFT JOIN auth_usuarios um ON s.id_usuario_modificacion = um.id
        WHERE s.estado = 1
          AND (
              p_busqueda = ''
              OR gen_texto_coincide(s.codigo, p_busqueda)
              OR gen_texto_coincide(s.nombre, p_busqueda)
              OR gen_texto_coincide(COALESCE(s.direccion, ''), p_busqueda)
              OR gen_texto_coincide(COALESCE(s.telefono, ''), p_busqueda)
          )
        ORDER BY s.nombre ASC
        LIMIT p_limite
        OFFSET p_offset
    ) t;

    RETURN json_build_object('registros', v_registros, 'total', v_total);
END;
$$;


--
-- Name: gen_listar_vehiculos(integer, character varying, integer, integer, integer, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gen_listar_vehiculos(p_solo_activos integer DEFAULT NULL::integer, p_buscar character varying DEFAULT ''::character varying, p_limite integer DEFAULT 10, p_offset integer DEFAULT 0, p_id_cliente integer DEFAULT NULL::integer, p_solo_flota_propia boolean DEFAULT NULL::boolean) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_registros JSON;
    v_total BIGINT;
BEGIN
    SET TIME ZONE 'America/Lima';

    SELECT COUNT(*) INTO v_total
    FROM gen_vehiculo v
    WHERE (p_solo_activos IS NULL OR v.estado = p_solo_activos)
      AND (
          p_id_cliente IS NULL
          OR v.id_cliente = p_id_cliente
          OR (p_id_cliente = -1 AND v.id_cliente IS NULL)
      )
      AND (
          p_solo_flota_propia IS NULL
          OR (p_solo_flota_propia IS TRUE AND v.id_cliente IS NULL)
          OR (p_solo_flota_propia IS FALSE AND v.id_cliente IS NOT NULL)
      )
      AND (
          p_buscar = ''
          OR gen_texto_coincide(v.placa, p_buscar)
          OR gen_texto_coincide(COALESCE(v.placa2, ''), p_buscar)
          OR gen_texto_coincide(COALESCE(v.marca, ''), p_buscar)
          OR gen_texto_coincide(COALESCE(v.modelo, ''), p_buscar)
      );

    SELECT COALESCE(json_agg(row_to_json(t)), '[]'::JSON) INTO v_registros
    FROM (
        SELECT
            v.id,
            v.id_cliente,
            c.razon_social AS cliente_razon_social,
            c.nombres AS cliente_nombres,
            c.apellido_paterno AS cliente_apellido_paterno,
            c.apellido_materno AS cliente_apellido_materno,
            c.numero_documento AS cliente_numero_documento,
            v.id_tipo_vehiculo,
            tv.nombre AS nombre_tipo_vehiculo,
            v.placa,
            v.placa2,
            v.marca,
            v.marca2,
            v.modelo,
            v.anio,
            v.color,
            v.certificado_inscripcion,
            v.certificado2,
            v.estado,
            v.fecha_creacion,
            v.fecha_modificacion,
            v.id_usuario_creacion,
            uc.nombre AS nombre_usuario_creacion,
            v.id_usuario_modificacion,
            um.nombre AS nombre_usuario_modificacion
        FROM gen_vehiculo v
        LEFT JOIN cli_clientes c ON v.id_cliente = c.id
        LEFT JOIN gen_lista_opciones tv ON v.id_tipo_vehiculo = tv.id
        LEFT JOIN auth_usuarios uc ON v.id_usuario_creacion = uc.id
        LEFT JOIN auth_usuarios um ON v.id_usuario_modificacion = um.id
        WHERE (p_solo_activos IS NULL OR v.estado = p_solo_activos)
          AND (
              p_id_cliente IS NULL
              OR v.id_cliente = p_id_cliente
              OR (p_id_cliente = -1 AND v.id_cliente IS NULL)
          )
          AND (
              p_solo_flota_propia IS NULL
              OR (p_solo_flota_propia IS TRUE AND v.id_cliente IS NULL)
              OR (p_solo_flota_propia IS FALSE AND v.id_cliente IS NOT NULL)
          )
          AND (
              p_buscar = ''
              OR gen_texto_coincide(v.placa, p_buscar)
              OR gen_texto_coincide(COALESCE(v.placa2, ''), p_buscar)
              OR gen_texto_coincide(COALESCE(v.marca, ''), p_buscar)
              OR gen_texto_coincide(COALESCE(v.modelo, ''), p_buscar)
          )
        ORDER BY v.placa ASC
        LIMIT p_limite
        OFFSET p_offset
    ) t;

    RETURN json_build_object('registros', v_registros, 'total', v_total);
END;
$$;


--
-- Name: gen_marcar_notificacion_leida(integer, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gen_marcar_notificacion_leida(p_id integer, p_id_usuario integer, p_id_usuario_auditoria integer DEFAULT NULL::integer) RETURNS json
    LANGUAGE plpgsql
    AS $$
BEGIN
    SET TIME ZONE 'America/Lima';

    UPDATE gen_notificacion
    SET leida = TRUE,
        fecha_lectura = COALESCE(fecha_lectura, NOW()),
        id_usuario_modificacion = p_id_usuario_auditoria,
        fecha_modificacion = NOW()
    WHERE id = p_id
      AND id_usuario = p_id_usuario
      AND estado = 1
      AND leida = FALSE;

    IF NOT FOUND THEN
        -- Ya leída o inexistente: devolver registro actual si pertenece al usuario
        RETURN gen_obtener_notificacion(p_id, p_id_usuario);
    END IF;

    RETURN gen_obtener_notificacion(p_id, p_id_usuario);
END;
$$;


--
-- Name: gen_marcar_todas_notificaciones_leidas(integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gen_marcar_todas_notificaciones_leidas(p_id_usuario integer, p_id_usuario_auditoria integer DEFAULT NULL::integer) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_actualizadas INTEGER;
BEGIN
    SET TIME ZONE 'America/Lima';

    IF p_id_usuario IS NULL THEN
        RETURN json_build_object('error', 'El usuario es obligatorio', 'actualizadas', 0);
    END IF;

    UPDATE gen_notificacion
    SET leida = TRUE,
        fecha_lectura = COALESCE(fecha_lectura, NOW()),
        id_usuario_modificacion = p_id_usuario_auditoria,
        fecha_modificacion = NOW()
    WHERE id_usuario = p_id_usuario
      AND estado = 1
      AND leida = FALSE;

    GET DIAGNOSTICS v_actualizadas = ROW_COUNT;

    RETURN json_build_object('actualizadas', v_actualizadas);
END;
$$;


--
-- Name: gen_normalizar_texto(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gen_normalizar_texto(p_texto text) RETURNS text
    LANGUAGE sql IMMUTABLE PARALLEL SAFE
    AS $$
  SELECT lower(
    translate(
      coalesce(p_texto, ''),
      'ÁÀÄÂáàäâÉÈËÊéèëêÍÌÏÎíìïîÓÒÖÔóòöôÚÙÜÛúùüûÝýÑñÇç',
      'AAAAaaaaEEEEeeeeIIIIiiiiOOOOooooUUUUuuuuYyNnCc'
    )
  );
$$;


--
-- Name: gen_obtener_almacen(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gen_obtener_almacen(p_id integer) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_registro JSON;
BEGIN
    SET TIME ZONE 'America/Lima';

    SELECT row_to_json(t) INTO v_registro
    FROM (
        SELECT
            a.id,
            a.id_sucursal,
            s.nombre AS nombre_sucursal,
            a.nombre,
            a.ubicacion,
            a.descripcion,
            a.id_departamento,
            a.id_provincia,
            a.id_distrito,
            a.estado,
            a.fecha_creacion,
            a.fecha_modificacion,
            a.id_usuario_creacion,
            uc.nombre AS nombre_usuario_creacion,
            a.id_usuario_modificacion,
            um.nombre AS nombre_usuario_modificacion
        FROM gen_almacen a
        INNER JOIN gen_sucursal s ON a.id_sucursal = s.id
        LEFT JOIN auth_usuarios uc ON a.id_usuario_creacion = uc.id
        LEFT JOIN auth_usuarios um ON a.id_usuario_modificacion = um.id
        WHERE a.id = p_id AND a.estado = 1
    ) t;

    RETURN json_build_object('registro', v_registro);
END;
$$;


--
-- Name: gen_obtener_archivo(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gen_obtener_archivo(p_id integer) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_registro JSON;
BEGIN
    SET TIME ZONE 'America/Lima';

    SELECT row_to_json(t) INTO v_registro
    FROM (
        SELECT
            a.id,
            a.nombre_original,
            a.nombre_almacenado,
            a.ruta,
            a.bucket,
            a.mime_type,
            a.extension,
            a.tamanio_bytes,
            a.id_empresa,
            e.nombre_comercial AS nombre_empresa,
            a.estado,
            a.fecha_creacion,
            a.fecha_modificacion,
            a.id_usuario_creacion,
            uc.nombre AS nombre_usuario_creacion,
            a.id_usuario_modificacion,
            um.nombre AS nombre_usuario_modificacion
        FROM gen_archivo a
        LEFT JOIN gen_empresa e ON a.id_empresa = e.id
        LEFT JOIN auth_usuarios uc ON a.id_usuario_creacion = uc.id
        LEFT JOIN auth_usuarios um ON a.id_usuario_modificacion = um.id
        WHERE a.id = p_id AND a.estado = 1
    ) t;

    RETURN json_build_object('registro', v_registro);
END;
$$;


--
-- Name: gen_obtener_archivo_por_ruta(character varying, character varying); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gen_obtener_archivo_por_ruta(p_bucket character varying, p_ruta character varying) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_id INTEGER;
BEGIN
    SET TIME ZONE 'America/Lima';

    SELECT a.id INTO v_id
    FROM gen_archivo a
    WHERE a.bucket = p_bucket
      AND a.ruta = p_ruta
      AND a.estado = 1
    LIMIT 1;

    IF v_id IS NULL THEN
        RETURN json_build_object('registro', NULL);
    END IF;

    RETURN gen_obtener_archivo(v_id);
END;
$$;


--
-- Name: gen_obtener_chofer(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gen_obtener_chofer(p_id integer) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_registro JSON;
BEGIN
    SET TIME ZONE 'America/Lima';

    SELECT row_to_json(t) INTO v_registro
    FROM (
        SELECT
            ch.id,
            ch.id_cliente,
            c.razon_social AS cliente_razon_social,
            c.nombres AS cliente_nombres,
            c.apellido_paterno AS cliente_apellido_paterno,
            c.apellido_materno AS cliente_apellido_materno,
            c.numero_documento AS cliente_numero_documento,
            ch.id_trabajador,
            (ch.id_trabajador IS NOT NULL) AS es_chofer_empresa,
            COALESCE(tr.apellido_paterno, ch.apellido_paterno) AS apellido_paterno,
            COALESCE(tr.apellido_materno, ch.apellido_materno) AS apellido_materno,
            COALESCE(tr.nombres, ch.nombres) AS nombres,
            COALESCE(tr.id_tipo_documento, ch.id_tipo_documento) AS id_tipo_documento,
            td.nombre AS nombre_tipo_documento,
            COALESCE(tr.numero_documento, ch.numero_documento) AS numero_documento,
            ch.telefono,

            -- Licencia vigente (la más reciente activa)
            lic.id                    AS id_licencia,
            lic.codigo                AS codigo_licencia,
            lic.fecha_emision,
            lic.fecha_vencimiento,
            lic.id_tipo_licencia,
            tl.nombre                 AS nombre_tipo_licencia,
            lic.id_categoria_licencia,
            cl.nombre                 AS nombre_categoria_licencia,

            ch.estado,
            ch.fecha_creacion,
            ch.fecha_modificacion,
            ch.id_usuario_creacion,
            uc.nombre AS nombre_usuario_creacion,
            ch.id_usuario_modificacion,
            um.nombre AS nombre_usuario_modificacion
        FROM gen_chofer ch
        LEFT JOIN cli_clientes c ON ch.id_cliente = c.id
        LEFT JOIN tra_trabajadores tr ON tr.id = ch.id_trabajador
        LEFT JOIN gen_lista_opciones td ON COALESCE(tr.id_tipo_documento, ch.id_tipo_documento) = td.id
        LEFT JOIN auth_usuarios uc ON ch.id_usuario_creacion = uc.id
        LEFT JOIN auth_usuarios um ON ch.id_usuario_modificacion = um.id

        LEFT JOIN LATERAL (
            SELECT gl.*
            FROM gen_licencia gl
            WHERE gl.id_chofer = ch.id
              AND gl.estado = 1
            ORDER BY gl.fecha_emision DESC, gl.id DESC
            LIMIT 1
        ) lic ON TRUE
        LEFT JOIN gen_lista_opciones tl ON lic.id_tipo_licencia = tl.id
        LEFT JOIN gen_lista_opciones cl ON lic.id_categoria_licencia = cl.id

        WHERE ch.id = p_id AND ch.estado = 1
    ) t;

    RETURN json_build_object('registro', v_registro);
END;
$$;


--
-- Name: gen_obtener_condicion_pago(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gen_obtener_condicion_pago(p_id integer) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_registro JSON;
BEGIN
    SET TIME ZONE 'America/Lima';

    SELECT row_to_json(t) INTO v_registro
    FROM (
        SELECT
            cp.id,
            cp.codigo,
            cp.nombre,
            cp.dias_credito,
            cp.numero_cuotas,
            cp.dia_mes_pago,
            CASE
                WHEN COALESCE(cp.numero_cuotas, 0) > 1 THEN 'CUOTAS'
                WHEN COALESCE(cp.dias_credito, 0) > 0 THEN 'CREDITO'
                ELSE 'CONTADO'
            END AS modalidad,
            cp.estado,
            cp.fecha_creacion,
            cp.fecha_modificacion,
            cp.id_usuario_creacion,
            uc.nombre AS nombre_usuario_creacion,
            cp.id_usuario_modificacion,
            um.nombre AS nombre_usuario_modificacion
        FROM gen_condicion_pago cp
        LEFT JOIN auth_usuarios uc ON cp.id_usuario_creacion = uc.id
        LEFT JOIN auth_usuarios um ON cp.id_usuario_modificacion = um.id
        WHERE cp.id = p_id AND cp.estado = 1
    ) t;

    RETURN json_build_object('registro', v_registro);
END;
$$;


