--
-- Name: gen_obtener_notificacion(integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gen_obtener_notificacion(p_id integer, p_id_usuario integer DEFAULT NULL::integer) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_registro JSON;
BEGIN
    SET TIME ZONE 'America/Lima';

    SELECT json_build_object(
        'id', n.id,
        'id_usuario', n.id_usuario,
        'codigo_tipo', n.codigo_tipo,
        'titulo', n.titulo,
        'mensaje', n.mensaje,
        'payload', n.payload,
        'id_referencia', n.id_referencia,
        'tipo_referencia', n.tipo_referencia,
        'clave_dedupe', n.clave_dedupe,
        'leida', n.leida,
        'fecha_lectura', n.fecha_lectura,
        'fecha_creacion', n.fecha_creacion,
        'fecha_modificacion', n.fecha_modificacion
    )
    INTO v_registro
    FROM gen_notificacion n
    WHERE n.id = p_id
      AND n.estado = 1
      AND (p_id_usuario IS NULL OR n.id_usuario = p_id_usuario);

    IF v_registro IS NULL THEN
        RETURN json_build_object('registro', NULL);
    END IF;

    RETURN json_build_object('registro', v_registro);
END;
$$;


--
-- Name: gen_obtener_sucursal(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gen_obtener_sucursal(p_id integer) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_registro JSON;
BEGIN
    SET TIME ZONE 'America/Lima';

    SELECT row_to_json(t) INTO v_registro
    FROM (
        SELECT
            s.id,
            s.codigo,
            s.nombre,
            s.direccion,
            s.id_departamento,
            dep.nombre AS nombre_departamento,
            s.id_provincia,
            prov.nombre AS nombre_provincia,
            s.id_distrito,
            dist.nombre AS nombre_distrito,
            s.telefono,
            s.estado,
            s.fecha_creacion,
            s.fecha_modificacion,
            s.id_usuario_creacion,
            uc.nombre AS nombre_usuario_creacion,
            s.id_usuario_modificacion,
            um.nombre AS nombre_usuario_modificacion
        FROM gen_sucursal s
        LEFT JOIN gen_departamento dep ON dep.id = s.id_departamento
        LEFT JOIN gen_provincia prov ON prov.id = s.id_provincia
        LEFT JOIN gen_distrito dist ON dist.id = s.id_distrito
        LEFT JOIN auth_usuarios uc ON s.id_usuario_creacion = uc.id
        LEFT JOIN auth_usuarios um ON s.id_usuario_modificacion = um.id
        WHERE s.id = p_id AND s.estado = 1
    ) t;

    RETURN json_build_object('registro', v_registro);
END;
$$;


--
-- Name: gen_obtener_vehiculo(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gen_obtener_vehiculo(p_id integer) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_registro JSON;
BEGIN
    SET TIME ZONE 'America/Lima';

    SELECT row_to_json(t) INTO v_registro
    FROM (
        SELECT
            v.id,
            v.id_cliente,
            c.razon_social AS cliente_razon_social,
            c.nombres AS cliente_nombres,
            c.apellido_paterno AS cliente_apellido_paterno,
            c.apellido_materno AS cliente_apellido_materno,
            c.numero_documento AS cliente_numero_documento,
            v.id_tipo_vehiculo,
            tv.nombre AS nombre_tipo_vehiculo,
            v.placa,
            v.placa2,
            v.marca,
            v.marca2,
            v.modelo,
            v.anio,
            v.color,
            v.certificado_inscripcion,
            v.certificado2,
            v.estado,
            v.fecha_creacion,
            v.fecha_modificacion,
            v.id_usuario_creacion,
            uc.nombre AS nombre_usuario_creacion,
            v.id_usuario_modificacion,
            um.nombre AS nombre_usuario_modificacion
        FROM gen_vehiculo v
        LEFT JOIN cli_clientes c ON v.id_cliente = c.id
        LEFT JOIN gen_lista_opciones tv ON v.id_tipo_vehiculo = tv.id
        LEFT JOIN auth_usuarios uc ON v.id_usuario_creacion = uc.id
        LEFT JOIN auth_usuarios um ON v.id_usuario_modificacion = um.id
        WHERE v.id = p_id AND v.estado = 1
    ) t;

    RETURN json_build_object('registro', v_registro);
END;
$$;


--
-- Name: gen_texto_coincide(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gen_texto_coincide(p_haystack text, p_needle text) RETURNS boolean
    LANGUAGE sql IMMUTABLE PARALLEL SAFE
    AS $$
  SELECT CASE
    WHEN nullif(btrim(coalesce(p_needle, '')), '') IS NULL THEN TRUE
    ELSE gen_normalizar_texto(p_haystack) LIKE '%' || gen_normalizar_texto(p_needle) || '%'
  END;
$$;


--
-- Name: gen_upsert_facturacion_apisperu(boolean, character varying, text, integer, character varying, character varying, character varying, character varying, character varying, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gen_upsert_facturacion_apisperu(p_habilitado boolean DEFAULT true, p_url character varying DEFAULT NULL::character varying, p_token text DEFAULT NULL::text, p_timeout_ms integer DEFAULT NULL::integer, p_client_id character varying DEFAULT NULL::character varying, p_client_secret character varying DEFAULT NULL::character varying, p_ruc_emisor character varying DEFAULT NULL::character varying, p_usuario character varying DEFAULT NULL::character varying, p_contrasena character varying DEFAULT NULL::character varying, p_id_usuario_auditoria integer DEFAULT NULL::integer) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_id INTEGER;
    v_id_empresa INTEGER;
BEGIN
    SET TIME ZONE 'America/Lima';

    -- p_usuario / p_contrasena / p_ruc_emisor se ignoran aquí:
    -- el RUC vive en gen_empresa; usuario/clave SOL se editan en la pantalla SUNAT.

    SELECT cs.id, cs.id_empresa INTO v_id, v_id_empresa
    FROM gen_configuracion_sunat cs
    WHERE cs.estado = 1
    ORDER BY cs.id
    LIMIT 1;

    IF v_id IS NULL THEN
        SELECT id INTO v_id_empresa
        FROM gen_empresa
        WHERE estado = 1
        ORDER BY id
        LIMIT 1;

        IF v_id_empresa IS NULL THEN
            RETURN json_build_object(
              'registro', NULL,
              'error', 'No hay empresa registrada. Configura Empresa primero.'
            );
        END IF;

        INSERT INTO gen_configuracion_sunat (
            id_empresa,
            usuario_sol,
            clave_sol,
            apisperu_habilitado,
            apisperu_url,
            apisperu_token,
            apisperu_timeout_ms,
            client_id_gre,
            client_secret_gre,
            id_usuario_creacion,
            id_usuario_modificacion
        )
        VALUES (
            v_id_empresa,
            NULL,
            NULL,
            COALESCE(p_habilitado, TRUE),
            NULLIF(TRIM(COALESCE(p_url, '')), ''),
            NULLIF(TRIM(COALESCE(p_token, '')), ''),
            COALESCE(p_timeout_ms, 60000),
            NULLIF(TRIM(COALESCE(p_client_id, '')), ''),
            NULLIF(TRIM(COALESCE(p_client_secret, '')), ''),
            p_id_usuario_auditoria,
            p_id_usuario_auditoria
        )
        RETURNING id INTO v_id;
    ELSE
        UPDATE gen_configuracion_sunat
        SET
            apisperu_habilitado = COALESCE(p_habilitado, apisperu_habilitado),
            apisperu_url = COALESCE(NULLIF(TRIM(COALESCE(p_url, '')), ''), apisperu_url),
            apisperu_token = CASE
                WHEN p_token IS NULL OR TRIM(p_token) = '' THEN apisperu_token
                ELSE TRIM(p_token)
            END,
            apisperu_timeout_ms = COALESCE(p_timeout_ms, apisperu_timeout_ms),
            client_id_gre = CASE
                WHEN p_client_id IS NULL THEN client_id_gre
                WHEN TRIM(p_client_id) = '' THEN NULL
                ELSE TRIM(p_client_id)
            END,
            client_secret_gre = CASE
                WHEN p_client_secret IS NULL OR TRIM(p_client_secret) = '' THEN client_secret_gre
                ELSE TRIM(p_client_secret)
            END,
            id_usuario_modificacion = p_id_usuario_auditoria,
            fecha_modificacion = NOW()
        WHERE id = v_id;
    END IF;

    RETURN gen_obtener_facturacion_apisperu();
END;
$$;


--
-- Name: gre_actualizar_guia_remision(integer, date, date, integer, integer, integer, integer, integer, numeric, integer, character varying, integer, integer, character varying, integer, integer, integer, integer, integer, integer, character varying, json, json, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gre_actualizar_guia_remision(p_id integer, p_fecha date DEFAULT NULL::date, p_fecha_traslado date DEFAULT NULL::date, p_id_sucursal integer DEFAULT NULL::integer, p_id_almacen integer DEFAULT NULL::integer, p_id_cliente integer DEFAULT NULL::integer, p_id_motivo_traslado integer DEFAULT NULL::integer, p_id_unidad_medida integer DEFAULT NULL::integer, p_peso_bruto numeric DEFAULT NULL::numeric, p_numero_bultos integer DEFAULT NULL::integer, p_direccion_origen character varying DEFAULT NULL::character varying, p_id_distrito_origen integer DEFAULT NULL::integer, p_id_destinatario integer DEFAULT NULL::integer, p_direccion_llegada character varying DEFAULT NULL::character varying, p_id_distrito_llegada integer DEFAULT NULL::integer, p_id_modalidad_traslado integer DEFAULT NULL::integer, p_id_transportista integer DEFAULT NULL::integer, p_id_chofer integer DEFAULT NULL::integer, p_id_vehiculo integer DEFAULT NULL::integer, p_id_responsable integer DEFAULT NULL::integer, p_observaciones character varying DEFAULT NULL::character varying, p_detalles json DEFAULT NULL::json, p_referencias json DEFAULT NULL::json, p_id_usuario_auditoria integer DEFAULT NULL::integer) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_estado_sunat VARCHAR;
    v_codigo_modalidad VARCHAR;
    v_id_tipo INTEGER;
    v_id_modalidad INTEGER;
    v_id_destinatario INTEGER;
    v_id_distrito_origen INTEGER;
    v_id_distrito_llegada INTEGER;
    v_peso NUMERIC;
    v_detalle JSON;
    v_ref JSON;
    v_item INTEGER := 0;
    v_salidas JSON;
BEGIN
    SET TIME ZONE 'America/Lima';

    SELECT es.nombre, g.id_tipo_guia_remision
    INTO v_estado_sunat, v_id_tipo
    FROM gre_guia_remision g
    LEFT JOIN gen_lista_opciones es ON g.id_estado_sunat = es.id
    WHERE g.id = p_id AND g.estado = 1;

    IF v_estado_sunat IS NULL AND v_id_tipo IS NULL THEN
        RETURN json_build_object('error', 'GuÃ­a de remisiÃ³n no encontrada', 'registro', NULL);
    END IF;

    IF v_estado_sunat = 'ACEPTADO' THEN
        RETURN json_build_object(
            'error', 'No se puede editar una guÃ­a aceptada por SUNAT',
            'registro', NULL
        );
    END IF;

    SELECT
        COALESCE(p_id_modalidad_traslado, g.id_modalidad_traslado),
        COALESCE(p_id_destinatario, g.id_destinatario),
        COALESCE(p_id_distrito_origen, g.id_distrito_origen),
        COALESCE(p_id_distrito_llegada, g.id_distrito_llegada),
        COALESCE(p_peso_bruto, g.peso_bruto)
    INTO
        v_id_modalidad,
        v_id_destinatario,
        v_id_distrito_origen,
        v_id_distrito_llegada,
        v_peso
    FROM gre_guia_remision g
    WHERE g.id = p_id AND g.estado = 1;

    IF v_id_destinatario IS NULL THEN
        RETURN json_build_object('error', 'El destinatario es obligatorio', 'registro', NULL);
    END IF;

    IF v_id_distrito_origen IS NULL OR v_id_distrito_llegada IS NULL THEN
        RETURN json_build_object('error', 'Distrito de origen y llegada son obligatorios (ubigeo SUNAT)', 'registro', NULL);
    END IF;

    IF COALESCE(v_peso, 0) <= 0 THEN
        RETURN json_build_object('error', 'El peso bruto debe ser mayor a cero', 'registro', NULL);
    END IF;

    SELECT lo.descripcion INTO v_codigo_modalidad
    FROM gen_lista_opciones lo
    WHERE lo.id = v_id_modalidad AND lo.estado = 1;

    IF v_codigo_modalidad = '02'
       AND (
           COALESCE(p_id_chofer, (SELECT id_chofer FROM gre_guia_remision WHERE id = p_id)) IS NULL
           OR COALESCE(p_id_vehiculo, (SELECT id_vehiculo FROM gre_guia_remision WHERE id = p_id)) IS NULL
       )
    THEN
        RETURN json_build_object('error', 'Transporte privado requiere chofer y vehÃ­culo', 'registro', NULL);
    END IF;

    IF v_codigo_modalidad = '01'
       AND COALESCE(p_id_transportista, (SELECT id_transportista FROM gre_guia_remision WHERE id = p_id)) IS NULL
    THEN
        RETURN json_build_object('error', 'Transporte pÃºblico requiere transportista', 'registro', NULL);
    END IF;

    IF p_detalles IS NOT NULL THEN
        IF json_typeof(p_detalles) <> 'array' OR json_array_length(p_detalles) = 0 THEN
            RETURN json_build_object('error', 'Debe registrar al menos un Ã­tem', 'registro', NULL);
        END IF;
    END IF;

    UPDATE gre_guia_remision
    SET
        fecha = COALESCE(p_fecha, fecha),
        fecha_traslado = COALESCE(p_fecha_traslado, fecha_traslado),
        id_sucursal = COALESCE(p_id_sucursal, id_sucursal),
        id_almacen = COALESCE(p_id_almacen, id_almacen),
        id_cliente = COALESCE(p_id_cliente, id_cliente),
        id_motivo_traslado = COALESCE(p_id_motivo_traslado, id_motivo_traslado),
        id_unidad_medida = COALESCE(p_id_unidad_medida, id_unidad_medida),
        peso_bruto = COALESCE(p_peso_bruto, peso_bruto),
        numero_bultos = COALESCE(p_numero_bultos, numero_bultos),
        direccion_origen = COALESCE(NULLIF(TRIM(p_direccion_origen), ''), direccion_origen),
        id_distrito_origen = COALESCE(p_id_distrito_origen, id_distrito_origen),
        id_destinatario = COALESCE(p_id_destinatario, id_destinatario),
        direccion_llegada = COALESCE(NULLIF(TRIM(p_direccion_llegada), ''), direccion_llegada),
        id_distrito_llegada = COALESCE(p_id_distrito_llegada, id_distrito_llegada),
        id_modalidad_traslado = COALESCE(p_id_modalidad_traslado, id_modalidad_traslado),
        id_transportista = CASE
            WHEN p_id_modalidad_traslado IS NOT NULL AND v_codigo_modalidad = '02' THEN NULL
            ELSE COALESCE(p_id_transportista, id_transportista)
        END,
        id_chofer = CASE
            WHEN p_id_modalidad_traslado IS NOT NULL AND v_codigo_modalidad = '01' THEN NULL
            ELSE COALESCE(p_id_chofer, id_chofer)
        END,
        id_vehiculo = CASE
            WHEN p_id_modalidad_traslado IS NOT NULL AND v_codigo_modalidad = '01' THEN NULL
            ELSE COALESCE(p_id_vehiculo, id_vehiculo)
        END,
        id_responsable = COALESCE(p_id_responsable, id_responsable),
        observaciones = CASE
            WHEN p_observaciones IS NULL THEN observaciones
            ELSE NULLIF(TRIM(p_observaciones), '')
        END,
        id_usuario_modificacion = p_id_usuario_auditoria,
        fecha_modificacion = NOW()
    WHERE id = p_id AND estado = 1;

    IF p_detalles IS NOT NULL THEN
        UPDATE gre_guia_remision_detalle
        SET estado = 0,
            id_usuario_modificacion = p_id_usuario_auditoria,
            fecha_modificacion = NOW()
        WHERE id_guia_remision = p_id AND estado = 1;

        v_item := 0;
        FOR v_detalle IN SELECT value FROM json_array_elements(p_detalles)
        LOOP
            v_item := v_item + 1;

            IF (v_detalle->>'idProducto') IS NULL AND (v_detalle->>'id_producto') IS NULL THEN
                RETURN json_build_object('error', format('Ãtem %s: producto obligatorio', v_item), 'registro', NULL);
            END IF;

            IF COALESCE((v_detalle->>'cantidad')::NUMERIC, 0) <= 0 THEN
                RETURN json_build_object('error', format('Ãtem %s: cantidad invÃ¡lida', v_item), 'registro', NULL);
            END IF;

            INSERT INTO gre_guia_remision_detalle (
                id_guia_remision, item, id_producto, descripcion,
                id_unidad_medida, cantidad, id_balon, glosa,
                id_usuario_creacion, id_usuario_modificacion
            ) VALUES (
                p_id,
                COALESCE((v_detalle->>'item')::INTEGER, v_item),
                COALESCE((v_detalle->>'idProducto')::INTEGER, (v_detalle->>'id_producto')::INTEGER),
                NULLIF(TRIM(COALESCE(v_detalle->>'descripcion', '')), ''),
                COALESCE((v_detalle->>'idUnidadMedida')::INTEGER, (v_detalle->>'id_unidad_medida')::INTEGER),
                (v_detalle->>'cantidad')::NUMERIC,
                COALESCE((v_detalle->>'idBalon')::INTEGER, (v_detalle->>'id_balon')::INTEGER),
                NULLIF(TRIM(COALESCE(v_detalle->>'glosa', '')), ''),
                p_id_usuario_auditoria,
                p_id_usuario_auditoria
            );
        END LOOP;
    END IF;

    IF p_referencias IS NOT NULL AND json_typeof(p_referencias) = 'array' THEN
        UPDATE gre_documentos_referencia
        SET estado = 0,
            id_usuario_modificacion = p_id_usuario_auditoria,
            fecha_modificacion = NOW()
        WHERE id_guia_remision = p_id AND estado = 1;

        FOR v_ref IN SELECT value FROM json_array_elements(p_referencias)
        LOOP
            INSERT INTO gre_documentos_referencia (
                id_guia_remision, id_tipo_comprobante, serie, numero, fecha,
                id_usuario_creacion, id_usuario_modificacion
            ) VALUES (
                p_id,
                COALESCE((v_ref->>'idTipoComprobante')::INTEGER, (v_ref->>'id_tipo_comprobante')::INTEGER),
                NULLIF(UPPER(TRIM(COALESCE(v_ref->>'serie', ''))), ''),
                NULLIF(TRIM(COALESCE(v_ref->>'numero', '')), ''),
                NULLIF(v_ref->>'fecha', '')::DATE,
                p_id_usuario_auditoria,
                p_id_usuario_auditoria
            );
        END LOOP;
    END IF;

    -- CY1: salidas idempotentes para cilindros presentes en la guÃ­a
    v_salidas := bal_aplicar_salidas_guia_remision(p_id, p_id_usuario_auditoria);
    IF v_salidas->>'error' IS NOT NULL THEN
        RAISE EXCEPTION '%', v_salidas->>'error';
    END IF;

    RETURN gre_obtener_guia_remision(p_id);
END;
$$;


--
-- Name: gre_actualizar_guia_remision(integer, date, date, integer, integer, integer, integer, integer, numeric, integer, character varying, integer, integer, character varying, character varying, character varying, integer, integer, integer, integer, integer, integer, character varying, json, json, integer, character varying, character varying); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gre_actualizar_guia_remision(p_id integer, p_fecha date DEFAULT NULL::date, p_fecha_traslado date DEFAULT NULL::date, p_id_sucursal integer DEFAULT NULL::integer, p_id_almacen integer DEFAULT NULL::integer, p_id_cliente integer DEFAULT NULL::integer, p_id_motivo_traslado integer DEFAULT NULL::integer, p_id_unidad_medida integer DEFAULT NULL::integer, p_peso_bruto numeric DEFAULT NULL::numeric, p_numero_bultos integer DEFAULT NULL::integer, p_direccion_origen character varying DEFAULT NULL::character varying, p_id_distrito_origen integer DEFAULT NULL::integer, p_id_destinatario integer DEFAULT NULL::integer, p_destinatario_nombre character varying DEFAULT NULL::character varying, p_destinatario_documento character varying DEFAULT NULL::character varying, p_direccion_llegada character varying DEFAULT NULL::character varying, p_id_distrito_llegada integer DEFAULT NULL::integer, p_id_modalidad_traslado integer DEFAULT NULL::integer, p_id_transportista integer DEFAULT NULL::integer, p_id_chofer integer DEFAULT NULL::integer, p_id_vehiculo integer DEFAULT NULL::integer, p_id_responsable integer DEFAULT NULL::integer, p_observaciones character varying DEFAULT NULL::character varying, p_detalles json DEFAULT NULL::json, p_referencias json DEFAULT NULL::json, p_id_usuario_auditoria integer DEFAULT NULL::integer, p_remitente_nombre character varying DEFAULT NULL::character varying, p_remitente_documento character varying DEFAULT NULL::character varying) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_estado_sunat VARCHAR;
    v_codigo_modalidad VARCHAR;
    v_codigo_tipo VARCHAR;
    v_id_tipo INTEGER;
    v_id_modalidad INTEGER;
    v_id_destinatario INTEGER;
    v_destinatario_nombre VARCHAR(255);
    v_destinatario_documento VARCHAR(20);
    v_id_cliente INTEGER;
    v_remitente_nombre VARCHAR(255);
    v_remitente_documento VARCHAR(20);
    v_id_distrito_origen INTEGER;
    v_id_distrito_llegada INTEGER;
    v_peso NUMERIC;
    v_detalle JSON;
    v_ref JSON;
    v_item INTEGER := 0;
    v_salidas JSON;
    v_ids_conservar INTEGER[] := ARRAY[]::INTEGER[];
    v_id_balon_linea INTEGER;
    v_rev JSON;
BEGIN
    SET TIME ZONE 'America/Lima';

    SELECT es.nombre, g.id_tipo_guia_remision
    INTO v_estado_sunat, v_id_tipo
    FROM gre_guia_remision g
    LEFT JOIN gen_lista_opciones es ON g.id_estado_sunat = es.id
    WHERE g.id = p_id AND g.estado = 1;

    IF v_estado_sunat IS NULL AND v_id_tipo IS NULL THEN
        RETURN json_build_object('error', 'Guía de remisión no encontrada', 'registro', NULL);
    END IF;

    IF v_estado_sunat = 'ACEPTADO' THEN
        RETURN json_build_object(
            'error', 'No se puede editar una guía aceptada por SUNAT',
            'registro', NULL
        );
    END IF;

    SELECT
        COALESCE(p_id_modalidad_traslado, g.id_modalidad_traslado),
        CASE
            WHEN p_destinatario_nombre IS NOT NULL
                 AND NULLIF(TRIM(p_destinatario_nombre), '') IS NOT NULL THEN NULL
            WHEN p_id_destinatario IS NOT NULL THEN p_id_destinatario
            ELSE g.id_destinatario
        END,
        CASE
            WHEN p_id_destinatario IS NOT NULL THEN NULL
            WHEN p_destinatario_nombre IS NOT NULL THEN NULLIF(TRIM(p_destinatario_nombre), '')
            ELSE NULLIF(TRIM(g.destinatario_nombre), '')
        END,
        CASE
            WHEN p_id_destinatario IS NOT NULL THEN NULL
            WHEN p_destinatario_documento IS NOT NULL THEN NULLIF(TRIM(p_destinatario_documento), '')
            ELSE NULLIF(TRIM(g.destinatario_documento), '')
        END,
        CASE
            WHEN p_remitente_nombre IS NOT NULL
                 AND NULLIF(TRIM(p_remitente_nombre), '') IS NOT NULL THEN NULL
            WHEN p_id_cliente IS NOT NULL THEN p_id_cliente
            ELSE g.id_cliente
        END,
        CASE
            WHEN p_id_cliente IS NOT NULL THEN NULL
            WHEN p_remitente_nombre IS NOT NULL THEN NULLIF(TRIM(p_remitente_nombre), '')
            ELSE NULLIF(TRIM(g.remitente_nombre), '')
        END,
        CASE
            WHEN p_id_cliente IS NOT NULL THEN NULL
            WHEN p_remitente_documento IS NOT NULL THEN NULLIF(TRIM(p_remitente_documento), '')
            ELSE NULLIF(TRIM(g.remitente_documento), '')
        END,
        COALESCE(p_id_distrito_origen, g.id_distrito_origen),
        COALESCE(p_id_distrito_llegada, g.id_distrito_llegada),
        COALESCE(p_peso_bruto, g.peso_bruto)
    INTO
        v_id_modalidad,
        v_id_destinatario,
        v_destinatario_nombre,
        v_destinatario_documento,
        v_id_cliente,
        v_remitente_nombre,
        v_remitente_documento,
        v_id_distrito_origen,
        v_id_distrito_llegada,
        v_peso
    FROM gre_guia_remision g
    WHERE g.id = p_id AND g.estado = 1;

    IF v_id_destinatario IS NULL
       AND (v_destinatario_nombre IS NULL OR v_destinatario_documento IS NULL)
    THEN
        RETURN json_build_object(
            'error',
            'El destinatario es obligatorio: selecciona un cliente o ingresa nombre y documento',
            'registro',
            NULL
        );
    END IF;

    SELECT lo.descripcion INTO v_codigo_tipo
    FROM gen_lista_opciones lo
    WHERE lo.id = v_id_tipo AND lo.estado = 1;

    IF v_codigo_tipo = '31'
       AND v_id_cliente IS NULL
       AND (v_remitente_nombre IS NULL OR v_remitente_documento IS NULL)
    THEN
        RETURN json_build_object(
            'error',
            'El remitente es obligatorio en GRE transportista: selecciona un cliente o ingresa nombre y documento',
            'registro',
            NULL
        );
    END IF;

    IF v_id_distrito_origen IS NULL OR v_id_distrito_llegada IS NULL THEN
        RETURN json_build_object('error', 'Distrito de origen y llegada son obligatorios (ubigeo SUNAT)', 'registro', NULL);
    END IF;

    IF COALESCE(v_peso, 0) <= 0 THEN
        RETURN json_build_object('error', 'El peso bruto debe ser mayor a cero', 'registro', NULL);
    END IF;

    SELECT lo.descripcion INTO v_codigo_modalidad
    FROM gen_lista_opciones lo
    WHERE lo.id = v_id_modalidad AND lo.estado = 1;

    IF v_codigo_modalidad = '02'
       AND (
           COALESCE(p_id_chofer, (SELECT id_chofer FROM gre_guia_remision WHERE id = p_id)) IS NULL
           OR COALESCE(p_id_vehiculo, (SELECT id_vehiculo FROM gre_guia_remision WHERE id = p_id)) IS NULL
       )
    THEN
        RETURN json_build_object('error', 'Transporte privado requiere chofer y vehículo', 'registro', NULL);
    END IF;

    IF v_codigo_modalidad = '01'
       AND COALESCE(p_id_transportista, (SELECT id_transportista FROM gre_guia_remision WHERE id = p_id)) IS NULL
    THEN
        RETURN json_build_object('error', 'Transporte público requiere transportista', 'registro', NULL);
    END IF;

    IF p_detalles IS NOT NULL THEN
        IF json_typeof(p_detalles) <> 'array' OR json_array_length(p_detalles) = 0 THEN
            RETURN json_build_object('error', 'Debe registrar al menos un ítem', 'registro', NULL);
        END IF;
    END IF;

    UPDATE gre_guia_remision
    SET
        fecha = COALESCE(p_fecha, fecha),
        fecha_traslado = COALESCE(p_fecha_traslado, fecha_traslado),
        id_sucursal = COALESCE(p_id_sucursal, id_sucursal),
        id_almacen = COALESCE(p_id_almacen, id_almacen),
        id_cliente = v_id_cliente,
        remitente_nombre = v_remitente_nombre,
        remitente_documento = v_remitente_documento,
        id_motivo_traslado = COALESCE(p_id_motivo_traslado, id_motivo_traslado),
        id_unidad_medida = COALESCE(p_id_unidad_medida, id_unidad_medida),
        peso_bruto = COALESCE(p_peso_bruto, peso_bruto),
        numero_bultos = COALESCE(p_numero_bultos, numero_bultos),
        direccion_origen = COALESCE(NULLIF(TRIM(p_direccion_origen), ''), direccion_origen),
        id_distrito_origen = COALESCE(p_id_distrito_origen, id_distrito_origen),
        id_destinatario = v_id_destinatario,
        destinatario_nombre = v_destinatario_nombre,
        destinatario_documento = v_destinatario_documento,
        direccion_llegada = COALESCE(NULLIF(TRIM(p_direccion_llegada), ''), direccion_llegada),
        id_distrito_llegada = COALESCE(p_id_distrito_llegada, id_distrito_llegada),
        id_modalidad_traslado = COALESCE(p_id_modalidad_traslado, id_modalidad_traslado),
        id_transportista = CASE
            WHEN p_id_modalidad_traslado IS NOT NULL AND v_codigo_modalidad = '02' THEN NULL
            ELSE COALESCE(p_id_transportista, id_transportista)
        END,
        id_chofer = CASE
            WHEN p_id_modalidad_traslado IS NOT NULL AND v_codigo_modalidad = '01' THEN NULL
            ELSE COALESCE(p_id_chofer, id_chofer)
        END,
        id_vehiculo = CASE
            WHEN p_id_modalidad_traslado IS NOT NULL AND v_codigo_modalidad = '01' THEN NULL
            ELSE COALESCE(p_id_vehiculo, id_vehiculo)
        END,
        id_responsable = COALESCE(p_id_responsable, id_responsable),
        observaciones = CASE
            WHEN p_observaciones IS NULL THEN observaciones
            ELSE NULLIF(TRIM(p_observaciones), '')
        END,
        id_usuario_modificacion = p_id_usuario_auditoria,
        fecha_modificacion = NOW()
    WHERE id = p_id AND estado = 1;

    IF p_detalles IS NOT NULL THEN
        UPDATE gre_guia_remision_detalle
        SET estado = 0,
            id_usuario_modificacion = p_id_usuario_auditoria,
            fecha_modificacion = NOW()
        WHERE id_guia_remision = p_id AND estado = 1;

        v_item := 0;
        FOR v_detalle IN SELECT value FROM json_array_elements(p_detalles)
        LOOP
            v_item := v_item + 1;

            IF (v_detalle->>'idProducto') IS NULL
               AND (v_detalle->>'id_producto') IS NULL
               AND (v_detalle->>'idBalon') IS NULL
               AND (v_detalle->>'id_balon') IS NULL
               AND NULLIF(TRIM(COALESCE(v_detalle->>'glosa', v_detalle->>'descripcion', '')), '') IS NULL
            THEN
                RETURN json_build_object(
                    'error',
                    format('Ítem %s: indica cilindro, producto o descripción', v_item),
                    'registro',
                    NULL
                );
            END IF;

            IF COALESCE((v_detalle->>'cantidad')::NUMERIC, 0) <= 0 THEN
                RETURN json_build_object('error', format('Ítem %s: cantidad inválida', v_item), 'registro', NULL);
            END IF;

            INSERT INTO gre_guia_remision_detalle (
                id_guia_remision, item, id_producto, descripcion,
                id_unidad_medida, cantidad, id_balon, glosa,
                id_usuario_creacion, id_usuario_modificacion
            ) VALUES (
                p_id,
                COALESCE((v_detalle->>'item')::INTEGER, v_item),
                COALESCE((v_detalle->>'idProducto')::INTEGER, (v_detalle->>'id_producto')::INTEGER),
                NULLIF(TRIM(COALESCE(v_detalle->>'descripcion', '')), ''),
                COALESCE((v_detalle->>'idUnidadMedida')::INTEGER, (v_detalle->>'id_unidad_medida')::INTEGER),
                (v_detalle->>'cantidad')::NUMERIC,
                COALESCE((v_detalle->>'idBalon')::INTEGER, (v_detalle->>'id_balon')::INTEGER),
                NULLIF(TRIM(COALESCE(v_detalle->>'glosa', '')), ''),
                p_id_usuario_auditoria,
                p_id_usuario_auditoria
            );

            v_id_balon_linea := COALESCE(
                (v_detalle->>'idBalon')::INTEGER,
                (v_detalle->>'id_balon')::INTEGER
            );
            IF v_id_balon_linea IS NOT NULL THEN
                v_ids_conservar := array_append(v_ids_conservar, v_id_balon_linea);
            END IF;
        END LOOP;
    END IF;

    IF p_referencias IS NOT NULL AND json_typeof(p_referencias) = 'array' THEN
        UPDATE gre_documentos_referencia
        SET estado = 0,
            id_usuario_modificacion = p_id_usuario_auditoria,
            fecha_modificacion = NOW()
        WHERE id_guia_remision = p_id AND estado = 1;

        FOR v_ref IN SELECT value FROM json_array_elements(p_referencias)
        LOOP
            INSERT INTO gre_documentos_referencia (
                id_guia_remision, id_tipo_comprobante, id_comprobante, serie, numero, fecha,
                id_usuario_creacion, id_usuario_modificacion
            ) VALUES (
                p_id,
                COALESCE((v_ref->>'idTipoComprobante')::INTEGER, (v_ref->>'id_tipo_comprobante')::INTEGER),
                COALESCE((v_ref->>'idComprobante')::INTEGER, (v_ref->>'id_comprobante')::INTEGER),
                NULLIF(UPPER(TRIM(COALESCE(v_ref->>'serie', ''))), ''),
                NULLIF(TRIM(COALESCE(v_ref->>'numero', '')), ''),
                NULLIF(v_ref->>'fecha', '')::DATE,
                p_id_usuario_auditoria,
                p_id_usuario_auditoria
            );
        END LOOP;
    END IF;

    IF p_detalles IS NOT NULL THEN
        v_rev := bal_revertir_salidas_guia_remision(p_id, v_ids_conservar, p_id_usuario_auditoria);
        IF v_rev->>'error' IS NOT NULL THEN
            RAISE EXCEPTION '%', v_rev->>'error';
        END IF;
    END IF;

    -- CY1: salidas idempotentes para cilindros presentes en la guía
    v_salidas := bal_aplicar_salidas_guia_remision(p_id, p_id_usuario_auditoria);
    IF v_salidas->>'error' IS NOT NULL THEN
        RAISE EXCEPTION '%', v_salidas->>'error';
    END IF;

    RETURN gre_obtener_guia_remision(p_id);
END;
$$;


--
-- Name: gre_crear_guia_remision(integer, character varying, character varying, date, date, integer, integer, integer, integer, integer, numeric, integer, character varying, integer, integer, character varying, integer, integer, integer, integer, integer, integer, character varying, json, json, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gre_crear_guia_remision(p_id_tipo_guia_remision integer, p_serie character varying, p_numero character varying DEFAULT NULL::character varying, p_fecha date DEFAULT NULL::date, p_fecha_traslado date DEFAULT NULL::date, p_id_sucursal integer DEFAULT NULL::integer, p_id_almacen integer DEFAULT NULL::integer, p_id_cliente integer DEFAULT NULL::integer, p_id_motivo_traslado integer DEFAULT NULL::integer, p_id_unidad_medida integer DEFAULT NULL::integer, p_peso_bruto numeric DEFAULT NULL::numeric, p_numero_bultos integer DEFAULT NULL::integer, p_direccion_origen character varying DEFAULT NULL::character varying, p_id_distrito_origen integer DEFAULT NULL::integer, p_id_destinatario integer DEFAULT NULL::integer, p_direccion_llegada character varying DEFAULT NULL::character varying, p_id_distrito_llegada integer DEFAULT NULL::integer, p_id_modalidad_traslado integer DEFAULT NULL::integer, p_id_transportista integer DEFAULT NULL::integer, p_id_chofer integer DEFAULT NULL::integer, p_id_vehiculo integer DEFAULT NULL::integer, p_id_responsable integer DEFAULT NULL::integer, p_observaciones character varying DEFAULT NULL::character varying, p_detalles json DEFAULT '[]'::json, p_referencias json DEFAULT NULL::json, p_id_usuario_auditoria integer DEFAULT NULL::integer) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_id INTEGER;
    v_serie VARCHAR(10);
    v_numero VARCHAR(15);
    v_fecha DATE;
    v_fecha_traslado DATE;
    v_id_estado_sunat INTEGER;
    v_id_estado INTEGER;
    v_codigo_tipo VARCHAR;
    v_codigo_modalidad VARCHAR;
    v_detalle JSON;
    v_ref JSON;
    v_item INTEGER := 0;
    v_salidas JSON;
BEGIN
    SET TIME ZONE 'America/Lima';

    v_serie := UPPER(TRIM(COALESCE(p_serie, '')));
    v_fecha := COALESCE(p_fecha, CURRENT_DATE);
    v_fecha_traslado := COALESCE(p_fecha_traslado, v_fecha);

    IF p_id_tipo_guia_remision IS NULL THEN
        RETURN json_build_object('error', 'El tipo de guÃ­a es obligatorio', 'registro', NULL);
    END IF;

    IF v_serie = '' THEN
        RETURN json_build_object('error', 'La serie es obligatoria', 'registro', NULL);
    END IF;

    IF p_id_sucursal IS NULL OR p_id_almacen IS NULL THEN
        RETURN json_build_object('error', 'Sucursal y almacÃ©n son obligatorios', 'registro', NULL);
    END IF;

    IF p_id_destinatario IS NULL THEN
        RETURN json_build_object('error', 'El destinatario es obligatorio', 'registro', NULL);
    END IF;

    IF p_id_motivo_traslado IS NULL OR p_id_modalidad_traslado IS NULL THEN
        RETURN json_build_object('error', 'Motivo y modalidad de traslado son obligatorios', 'registro', NULL);
    END IF;

    IF p_id_distrito_origen IS NULL OR p_id_distrito_llegada IS NULL THEN
        RETURN json_build_object('error', 'Distrito de origen y llegada son obligatorios (ubigeo SUNAT)', 'registro', NULL);
    END IF;

    IF COALESCE(p_peso_bruto, 0) <= 0 THEN
        RETURN json_build_object('error', 'El peso bruto debe ser mayor a cero', 'registro', NULL);
    END IF;

    IF p_detalles IS NULL OR json_typeof(p_detalles) <> 'array' OR json_array_length(p_detalles) = 0 THEN
        RETURN json_build_object('error', 'Debe registrar al menos un Ã­tem', 'registro', NULL);
    END IF;

    SELECT lo.descripcion INTO v_codigo_tipo
    FROM gen_lista_opciones lo
    WHERE lo.id = p_id_tipo_guia_remision AND lo.estado = 1;

    IF v_codigo_tipo IS NULL THEN
        RETURN json_build_object('error', 'Tipo de guÃ­a invÃ¡lido', 'registro', NULL);
    END IF;

    -- Serie GRE remitente inicia con T; transportista con V (convenciÃ³n SUNAT)
    IF v_codigo_tipo = '09' AND LEFT(v_serie, 1) <> 'T' THEN
        RETURN json_build_object('error', 'La serie de GRE remitente (09) debe iniciar con T (ej. T001)', 'registro', NULL);
    END IF;

    IF v_codigo_tipo = '31' AND LEFT(v_serie, 1) <> 'V' THEN
        RETURN json_build_object('error', 'La serie de GRE transportista (31) debe iniciar con V (ej. V001)', 'registro', NULL);
    END IF;

    SELECT lo.descripcion INTO v_codigo_modalidad
    FROM gen_lista_opciones lo
    WHERE lo.id = p_id_modalidad_traslado AND lo.estado = 1;

    IF v_codigo_modalidad = '02' AND (p_id_chofer IS NULL OR p_id_vehiculo IS NULL) THEN
        RETURN json_build_object('error', 'Transporte privado requiere chofer y vehÃ­culo', 'registro', NULL);
    END IF;

    IF v_codigo_modalidad = '01' AND p_id_transportista IS NULL THEN
        RETURN json_build_object('error', 'Transporte pÃºblico requiere transportista', 'registro', NULL);
    END IF;

    SELECT lo.id INTO v_id_estado_sunat
    FROM gen_lista_opciones lo
    INNER JOIN gen_lista l ON l.id = lo.id_lista
    WHERE l.nombre = 'EstadoSunat' AND lo.nombre = 'PENDIENTE' AND lo.estado = 1
    LIMIT 1;

    SELECT lo.id INTO v_id_estado
    FROM gen_lista_opciones lo
    INNER JOIN gen_lista l ON l.id = lo.id_lista
    WHERE l.nombre = 'EstadoGuiaRemision' AND lo.nombre = 'PENDIENTE' AND lo.estado = 1
    LIMIT 1;

    IF p_numero IS NULL OR TRIM(p_numero) = '' THEN
        SELECT (gre_obtener_siguiente_numero(v_serie)->>'numero') INTO v_numero;
    ELSE
        v_numero := LPAD(REGEXP_REPLACE(TRIM(p_numero), '[^0-9]', '', 'g'), 8, '0');
    END IF;

    IF EXISTS (
        SELECT 1 FROM gre_guia_remision
        WHERE estado = 1 AND UPPER(serie) = v_serie AND numero = v_numero
    ) THEN
        RETURN json_build_object('error', 'Ya existe una guÃ­a con esa serie y nÃºmero', 'registro', NULL);
    END IF;

    BEGIN
        INSERT INTO gre_guia_remision (
            id_tipo_guia_remision, serie, numero, id_estado_sunat,
            fecha, tipo_cambio, id_sucursal, id_almacen, id_cliente,
            fecha_traslado, id_motivo_traslado, id_unidad_medida,
            peso_bruto, numero_bultos,
            direccion_origen, id_distrito_origen,
            id_destinatario, direccion_llegada, id_distrito_llegada,
            id_modalidad_traslado, id_transportista, id_chofer, id_vehiculo,
            id_responsable, observaciones, id_estado,
            id_usuario_creacion, id_usuario_modificacion
        ) VALUES (
            p_id_tipo_guia_remision, v_serie, v_numero, v_id_estado_sunat,
            v_fecha, 3.5, p_id_sucursal, p_id_almacen, p_id_cliente,
            v_fecha_traslado, p_id_motivo_traslado, p_id_unidad_medida,
            p_peso_bruto, COALESCE(p_numero_bultos, 1),
            NULLIF(TRIM(p_direccion_origen), ''), p_id_distrito_origen,
            p_id_destinatario, NULLIF(TRIM(p_direccion_llegada), ''), p_id_distrito_llegada,
            p_id_modalidad_traslado, p_id_transportista, p_id_chofer, p_id_vehiculo,
            p_id_responsable, NULLIF(TRIM(p_observaciones), ''), v_id_estado,
            p_id_usuario_auditoria, p_id_usuario_auditoria
        )
        RETURNING id INTO v_id;
    EXCEPTION
        WHEN unique_violation THEN
            RETURN json_build_object('error', 'Ya existe una guÃ­a con esa serie y nÃºmero', 'registro', NULL);
    END;

    FOR v_detalle IN SELECT value FROM json_array_elements(p_detalles)
    LOOP
        v_item := v_item + 1;

        IF (v_detalle->>'idProducto') IS NULL AND (v_detalle->>'id_producto') IS NULL THEN
            RETURN json_build_object('error', format('Ãtem %s: producto obligatorio', v_item), 'registro', NULL);
        END IF;

        IF COALESCE((v_detalle->>'cantidad')::NUMERIC, 0) <= 0 THEN
            RETURN json_build_object('error', format('Ãtem %s: cantidad invÃ¡lida', v_item), 'registro', NULL);
        END IF;

        INSERT INTO gre_guia_remision_detalle (
            id_guia_remision, item, id_producto, descripcion,
            id_unidad_medida, cantidad, id_balon, glosa,
            id_usuario_creacion, id_usuario_modificacion
        ) VALUES (
            v_id,
            COALESCE((v_detalle->>'item')::INTEGER, v_item),
            COALESCE((v_detalle->>'idProducto')::INTEGER, (v_detalle->>'id_producto')::INTEGER),
            NULLIF(TRIM(COALESCE(v_detalle->>'descripcion', '')), ''),
            COALESCE((v_detalle->>'idUnidadMedida')::INTEGER, (v_detalle->>'id_unidad_medida')::INTEGER),
            (v_detalle->>'cantidad')::NUMERIC,
            COALESCE((v_detalle->>'idBalon')::INTEGER, (v_detalle->>'id_balon')::INTEGER),
            NULLIF(TRIM(COALESCE(v_detalle->>'glosa', '')), ''),
            p_id_usuario_auditoria,
            p_id_usuario_auditoria
        );
    END LOOP;

    IF p_referencias IS NOT NULL AND json_typeof(p_referencias) = 'array' THEN
        FOR v_ref IN SELECT value FROM json_array_elements(p_referencias)
        LOOP
            INSERT INTO gre_documentos_referencia (
                id_guia_remision, id_tipo_comprobante, serie, numero, fecha,
                id_usuario_creacion, id_usuario_modificacion
            ) VALUES (
                v_id,
                COALESCE((v_ref->>'idTipoComprobante')::INTEGER, (v_ref->>'id_tipo_comprobante')::INTEGER),
                NULLIF(UPPER(TRIM(COALESCE(v_ref->>'serie', ''))), ''),
                NULLIF(TRIM(COALESCE(v_ref->>'numero', '')), ''),
                NULLIF(v_ref->>'fecha', '')::DATE,
                p_id_usuario_auditoria,
                p_id_usuario_auditoria
            );
        END LOOP;
    END IF;

    -- CY1: salida automÃ¡tica de cilindros con cÃ³digo en la GRE
    v_salidas := bal_aplicar_salidas_guia_remision(v_id, p_id_usuario_auditoria);
    IF v_salidas->>'error' IS NOT NULL THEN
        RAISE EXCEPTION '%', v_salidas->>'error';
    END IF;

    RETURN gre_obtener_guia_remision(v_id);
END;
$$;


--
-- Name: gre_crear_guia_remision(integer, character varying, character varying, date, date, integer, integer, integer, integer, integer, numeric, integer, character varying, integer, integer, character varying, character varying, character varying, integer, integer, integer, integer, integer, integer, character varying, json, json, integer, character varying, character varying); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gre_crear_guia_remision(p_id_tipo_guia_remision integer, p_serie character varying, p_numero character varying DEFAULT NULL::character varying, p_fecha date DEFAULT NULL::date, p_fecha_traslado date DEFAULT NULL::date, p_id_sucursal integer DEFAULT NULL::integer, p_id_almacen integer DEFAULT NULL::integer, p_id_cliente integer DEFAULT NULL::integer, p_id_motivo_traslado integer DEFAULT NULL::integer, p_id_unidad_medida integer DEFAULT NULL::integer, p_peso_bruto numeric DEFAULT NULL::numeric, p_numero_bultos integer DEFAULT NULL::integer, p_direccion_origen character varying DEFAULT NULL::character varying, p_id_distrito_origen integer DEFAULT NULL::integer, p_id_destinatario integer DEFAULT NULL::integer, p_destinatario_nombre character varying DEFAULT NULL::character varying, p_destinatario_documento character varying DEFAULT NULL::character varying, p_direccion_llegada character varying DEFAULT NULL::character varying, p_id_distrito_llegada integer DEFAULT NULL::integer, p_id_modalidad_traslado integer DEFAULT NULL::integer, p_id_transportista integer DEFAULT NULL::integer, p_id_chofer integer DEFAULT NULL::integer, p_id_vehiculo integer DEFAULT NULL::integer, p_id_responsable integer DEFAULT NULL::integer, p_observaciones character varying DEFAULT NULL::character varying, p_detalles json DEFAULT '[]'::json, p_referencias json DEFAULT NULL::json, p_id_usuario_auditoria integer DEFAULT NULL::integer, p_remitente_nombre character varying DEFAULT NULL::character varying, p_remitente_documento character varying DEFAULT NULL::character varying) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_id INTEGER;
    v_serie VARCHAR(10);
    v_numero VARCHAR(15);
    v_fecha DATE;
    v_fecha_traslado DATE;
    v_id_estado_sunat INTEGER;
    v_id_estado INTEGER;
    v_codigo_tipo VARCHAR;
    v_codigo_modalidad VARCHAR;
    v_detalle JSON;
    v_ref JSON;
    v_item INTEGER := 0;
    v_salidas JSON;
    v_destinatario_nombre VARCHAR(255);
    v_destinatario_documento VARCHAR(20);
    v_id_destinatario INTEGER;
    v_remitente_nombre VARCHAR(255);
    v_remitente_documento VARCHAR(20);
    v_id_cliente INTEGER;
BEGIN
    SET TIME ZONE 'America/Lima';

    v_serie := UPPER(TRIM(COALESCE(p_serie, '')));
    v_fecha := COALESCE(p_fecha, CURRENT_DATE);
    v_fecha_traslado := COALESCE(p_fecha_traslado, v_fecha);
    v_destinatario_nombre := NULLIF(TRIM(p_destinatario_nombre), '');
    v_destinatario_documento := NULLIF(TRIM(p_destinatario_documento), '');
    -- Nombre libre tiene prioridad: no amarra FK de cliente
    v_id_destinatario := CASE
        WHEN v_destinatario_nombre IS NOT NULL THEN NULL
        ELSE p_id_destinatario
    END;
    v_remitente_nombre := NULLIF(TRIM(p_remitente_nombre), '');
    v_remitente_documento := NULLIF(TRIM(p_remitente_documento), '');
    v_id_cliente := CASE
        WHEN v_remitente_nombre IS NOT NULL THEN NULL
        ELSE p_id_cliente
    END;

    IF p_id_tipo_guia_remision IS NULL THEN
        RETURN json_build_object('error', 'El tipo de guía es obligatorio', 'registro', NULL);
    END IF;

    IF v_serie = '' THEN
        RETURN json_build_object('error', 'La serie es obligatoria', 'registro', NULL);
    END IF;

    IF p_id_sucursal IS NULL OR p_id_almacen IS NULL THEN
        RETURN json_build_object('error', 'Sucursal y almacén son obligatorios', 'registro', NULL);
    END IF;

    IF v_id_destinatario IS NULL AND (v_destinatario_nombre IS NULL OR v_destinatario_documento IS NULL) THEN
        RETURN json_build_object(
            'error',
            'El destinatario es obligatorio: selecciona un cliente o ingresa nombre y documento',
            'registro',
            NULL
        );
    END IF;

    IF p_id_motivo_traslado IS NULL OR p_id_modalidad_traslado IS NULL THEN
        RETURN json_build_object('error', 'Motivo y modalidad de traslado son obligatorios', 'registro', NULL);
    END IF;

    IF p_id_distrito_origen IS NULL OR p_id_distrito_llegada IS NULL THEN
        RETURN json_build_object('error', 'Distrito de origen y llegada son obligatorios (ubigeo SUNAT)', 'registro', NULL);
    END IF;

    IF COALESCE(p_peso_bruto, 0) <= 0 THEN
        RETURN json_build_object('error', 'El peso bruto debe ser mayor a cero', 'registro', NULL);
    END IF;

    IF p_detalles IS NULL OR json_typeof(p_detalles) <> 'array' OR json_array_length(p_detalles) = 0 THEN
        RETURN json_build_object('error', 'Debe registrar al menos un ítem', 'registro', NULL);
    END IF;

    SELECT lo.descripcion INTO v_codigo_tipo
    FROM gen_lista_opciones lo
    WHERE lo.id = p_id_tipo_guia_remision AND lo.estado = 1;

    IF v_codigo_tipo IS NULL THEN
        RETURN json_build_object('error', 'Tipo de guía inválido', 'registro', NULL);
    END IF;

    -- Serie GRE remitente inicia con T; transportista con V (convención SUNAT)
    IF v_codigo_tipo = '09' AND LEFT(v_serie, 1) <> 'T' THEN
        RETURN json_build_object('error', 'La serie de GRE remitente (09) debe iniciar con T (ej. T001)', 'registro', NULL);
    END IF;

    IF v_codigo_tipo = '31' AND LEFT(v_serie, 1) <> 'V' THEN
        RETURN json_build_object('error', 'La serie de GRE transportista (31) debe iniciar con V (ej. V001)', 'registro', NULL);
    END IF;

    IF v_codigo_tipo = '31'
       AND v_id_cliente IS NULL
       AND (v_remitente_nombre IS NULL OR v_remitente_documento IS NULL)
    THEN
        RETURN json_build_object(
            'error',
            'El remitente es obligatorio en GRE transportista: selecciona un cliente o ingresa nombre y documento',
            'registro',
            NULL
        );
    END IF;

    SELECT lo.descripcion INTO v_codigo_modalidad
    FROM gen_lista_opciones lo
    WHERE lo.id = p_id_modalidad_traslado AND lo.estado = 1;

    IF v_codigo_modalidad = '02' AND (p_id_chofer IS NULL OR p_id_vehiculo IS NULL) THEN
        RETURN json_build_object('error', 'Transporte privado requiere chofer y vehículo', 'registro', NULL);
    END IF;

    IF v_codigo_modalidad = '01' AND p_id_transportista IS NULL THEN
        RETURN json_build_object('error', 'Transporte público requiere transportista', 'registro', NULL);
    END IF;

    SELECT lo.id INTO v_id_estado_sunat
    FROM gen_lista_opciones lo
    INNER JOIN gen_lista l ON l.id = lo.id_lista
    WHERE l.nombre = 'EstadoSunat' AND lo.nombre = 'PENDIENTE' AND lo.estado = 1
    LIMIT 1;

    SELECT lo.id INTO v_id_estado
    FROM gen_lista_opciones lo
    INNER JOIN gen_lista l ON l.id = lo.id_lista
    WHERE l.nombre = 'EstadoGuiaRemision' AND lo.nombre = 'PENDIENTE' AND lo.estado = 1
    LIMIT 1;

    IF p_numero IS NULL OR TRIM(p_numero) = '' THEN
        SELECT (gre_obtener_siguiente_numero(v_serie)->>'numero') INTO v_numero;
    ELSE
        v_numero := LPAD(REGEXP_REPLACE(TRIM(p_numero), '[^0-9]', '', 'g'), 8, '0');
    END IF;

    IF EXISTS (
        SELECT 1 FROM gre_guia_remision
        WHERE estado = 1 AND UPPER(serie) = v_serie AND numero = v_numero
    ) THEN
        RETURN json_build_object('error', 'Ya existe una guía con esa serie y número', 'registro', NULL);
    END IF;

    BEGIN
        INSERT INTO gre_guia_remision (
            id_tipo_guia_remision, serie, numero, id_estado_sunat,
            fecha, tipo_cambio, id_sucursal, id_almacen, id_cliente,
            remitente_nombre, remitente_documento,
            fecha_traslado, id_motivo_traslado, id_unidad_medida,
            peso_bruto, numero_bultos,
            direccion_origen, id_distrito_origen,
            id_destinatario, destinatario_nombre, destinatario_documento,
            direccion_llegada, id_distrito_llegada,
            id_modalidad_traslado, id_transportista, id_chofer, id_vehiculo,
            id_responsable, observaciones, id_estado,
            id_usuario_creacion, id_usuario_modificacion
        ) VALUES (
            p_id_tipo_guia_remision, v_serie, v_numero, v_id_estado_sunat,
            v_fecha, 3.5, p_id_sucursal, p_id_almacen, v_id_cliente,
            v_remitente_nombre, v_remitente_documento,
            v_fecha_traslado, p_id_motivo_traslado, p_id_unidad_medida,
            p_peso_bruto, COALESCE(p_numero_bultos, 1),
            NULLIF(TRIM(p_direccion_origen), ''), p_id_distrito_origen,
            v_id_destinatario, v_destinatario_nombre, v_destinatario_documento,
            NULLIF(TRIM(p_direccion_llegada), ''), p_id_distrito_llegada,
            p_id_modalidad_traslado, p_id_transportista, p_id_chofer, p_id_vehiculo,
            p_id_responsable, NULLIF(TRIM(p_observaciones), ''), v_id_estado,
            p_id_usuario_auditoria, p_id_usuario_auditoria
        )
        RETURNING id INTO v_id;
    EXCEPTION
        WHEN unique_violation THEN
            RETURN json_build_object('error', 'Ya existe una guía con esa serie y número', 'registro', NULL);
    END;

    FOR v_detalle IN SELECT value FROM json_array_elements(p_detalles)
    LOOP
        v_item := v_item + 1;

        IF (v_detalle->>'idProducto') IS NULL
           AND (v_detalle->>'id_producto') IS NULL
           AND (v_detalle->>'idBalon') IS NULL
           AND (v_detalle->>'id_balon') IS NULL
           AND NULLIF(TRIM(COALESCE(v_detalle->>'glosa', v_detalle->>'descripcion', '')), '') IS NULL
        THEN
            RETURN json_build_object(
                'error',
                format('Ítem %s: indica cilindro, producto o descripción', v_item),
                'registro',
                NULL
            );
        END IF;

        IF COALESCE((v_detalle->>'cantidad')::NUMERIC, 0) <= 0 THEN
            RETURN json_build_object('error', format('Ítem %s: cantidad inválida', v_item), 'registro', NULL);
        END IF;

        INSERT INTO gre_guia_remision_detalle (
            id_guia_remision, item, id_producto, descripcion,
            id_unidad_medida, cantidad, id_balon, glosa,
            id_usuario_creacion, id_usuario_modificacion
        ) VALUES (
            v_id,
            COALESCE((v_detalle->>'item')::INTEGER, v_item),
            COALESCE((v_detalle->>'idProducto')::INTEGER, (v_detalle->>'id_producto')::INTEGER),
            NULLIF(TRIM(COALESCE(v_detalle->>'descripcion', '')), ''),
            COALESCE((v_detalle->>'idUnidadMedida')::INTEGER, (v_detalle->>'id_unidad_medida')::INTEGER),
            (v_detalle->>'cantidad')::NUMERIC,
            COALESCE((v_detalle->>'idBalon')::INTEGER, (v_detalle->>'id_balon')::INTEGER),
            NULLIF(TRIM(COALESCE(v_detalle->>'glosa', '')), ''),
            p_id_usuario_auditoria,
            p_id_usuario_auditoria
        );
    END LOOP;

    IF p_referencias IS NOT NULL AND json_typeof(p_referencias) = 'array' THEN
        FOR v_ref IN SELECT value FROM json_array_elements(p_referencias)
        LOOP
            INSERT INTO gre_documentos_referencia (
                id_guia_remision, id_tipo_comprobante, id_comprobante, serie, numero, fecha,
                id_usuario_creacion, id_usuario_modificacion
            ) VALUES (
                v_id,
                COALESCE((v_ref->>'idTipoComprobante')::INTEGER, (v_ref->>'id_tipo_comprobante')::INTEGER),
                COALESCE((v_ref->>'idComprobante')::INTEGER, (v_ref->>'id_comprobante')::INTEGER),
                NULLIF(UPPER(TRIM(COALESCE(v_ref->>'serie', ''))), ''),
                NULLIF(TRIM(COALESCE(v_ref->>'numero', '')), ''),
                NULLIF(v_ref->>'fecha', '')::DATE,
                p_id_usuario_auditoria,
                p_id_usuario_auditoria
            );
        END LOOP;
    END IF;

    -- CY1: salida automática de cilindros con código en la GRE
    v_salidas := bal_aplicar_salidas_guia_remision(v_id, p_id_usuario_auditoria);
    IF v_salidas->>'error' IS NOT NULL THEN
        RAISE EXCEPTION '%', v_salidas->>'error';
    END IF;

    RETURN gre_obtener_guia_remision(v_id);
END;
$$;


--
-- Name: gre_eliminar_guia_remision(integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gre_eliminar_guia_remision(p_id integer, p_id_usuario_auditoria integer DEFAULT NULL::integer) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_estado_sunat VARCHAR;
    v_orden_numero VARCHAR;
    v_rev JSON;
BEGIN
    SET TIME ZONE 'America/Lima';

    IF NOT EXISTS (
        SELECT 1 FROM gre_guia_remision WHERE id = p_id AND estado = 1
    ) THEN
        RETURN json_build_object('eliminado', FALSE, 'id', p_id);
    END IF;

    SELECT es.nombre INTO v_estado_sunat
    FROM gre_guia_remision g
    LEFT JOIN gen_lista_opciones es ON g.id_estado_sunat = es.id
    WHERE g.id = p_id AND g.estado = 1;

    IF v_estado_sunat = 'ACEPTADO' THEN
        RETURN json_build_object(
            'error', 'No se puede eliminar una guía aceptada por SUNAT',
            'eliminado', FALSE,
            'id', p_id
        );
    END IF;

    SELECT rp.numero
    INTO v_orden_numero
    FROM bal_recarga_planta rp
    WHERE rp.estado = 1
      AND (rp.id_guia_salida = p_id OR rp.id_guia_retorno = p_id)
    ORDER BY rp.id
    LIMIT 1;

    IF v_orden_numero IS NOT NULL THEN
        RETURN json_build_object(
            'error',
            format(
                'No se puede eliminar: la guía está vinculada a la orden de recarga %s',
                v_orden_numero
            ),
            'eliminado',
            FALSE,
            'id',
            p_id
        );
    END IF;

    v_rev := bal_revertir_salidas_guia_remision(p_id, NULL, p_id_usuario_auditoria);
    IF v_rev->>'error' IS NOT NULL THEN
        RETURN json_build_object(
            'error', v_rev->>'error',
            'eliminado', FALSE,
            'id', p_id
        );
    END IF;

    UPDATE gre_guia_remision
    SET estado = 0,
        id_usuario_modificacion = p_id_usuario_auditoria,
        fecha_modificacion = NOW()
    WHERE id = p_id;

    UPDATE gre_guia_remision_detalle
    SET estado = 0,
        id_usuario_modificacion = p_id_usuario_auditoria,
        fecha_modificacion = NOW()
    WHERE id_guia_remision = p_id AND estado = 1;

    UPDATE gre_documentos_referencia
    SET estado = 0,
        id_usuario_modificacion = p_id_usuario_auditoria,
        fecha_modificacion = NOW()
    WHERE id_guia_remision = p_id AND estado = 1;

    RETURN json_build_object('eliminado', TRUE, 'id', p_id);
END;
$$;


--
-- Name: gre_listar_guias_pendientes_notificar(integer, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gre_listar_guias_pendientes_notificar(p_dias_min integer DEFAULT 1, p_fecha date DEFAULT NULL::date) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_fecha DATE;
    v_min INTEGER;
    v_registros JSON;
BEGIN
    SET TIME ZONE 'America/Lima';
    v_fecha := COALESCE(p_fecha, CURRENT_DATE);
    v_min := GREATEST(COALESCE(p_dias_min, 1), 0);

    SELECT COALESCE(json_agg(t.row_data ORDER BY t.fecha, t.id), '[]'::JSON)
    INTO v_registros
    FROM (
        SELECT json_build_object(
            'id', g.id,
            'serie', g.serie,
            'numero', g.numero,
            'fecha', g.fecha,
            'ticket_sunat', g.ticket_sunat,
            'dias_pendiente', (v_fecha - g.fecha),
            'nombre_estado_sunat', es.nombre
        ) AS row_data,
        g.id,
        g.fecha
        FROM gre_guia_remision g
        LEFT JOIN gen_lista_opciones es ON es.id = g.id_estado_sunat
        WHERE g.estado = 1
          AND COALESCE(es.nombre, '') = 'PENDIENTE'
          AND NULLIF(TRIM(g.ticket_sunat), '') IS NOT NULL
          AND g.fecha IS NOT NULL
          AND (v_fecha - g.fecha) >= v_min
    ) t;

    RETURN json_build_object('registros', v_registros);
END;
$$;


--
-- Name: gre_listar_guias_remision(character varying, integer, integer, integer, integer, integer, integer, date, date, character varying); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gre_listar_guias_remision(p_busqueda character varying DEFAULT ''::character varying, p_limite integer DEFAULT 10, p_offset integer DEFAULT 0, p_id_tipo_guia integer DEFAULT NULL::integer, p_id_destinatario integer DEFAULT NULL::integer, p_id_estado integer DEFAULT NULL::integer, p_id_estado_sunat integer DEFAULT NULL::integer, p_fecha_desde date DEFAULT NULL::date, p_fecha_hasta date DEFAULT NULL::date, p_serie character varying DEFAULT NULL::character varying) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_registros JSON;
    v_total BIGINT;
BEGIN
    SET TIME ZONE 'America/Lima';

    SELECT COUNT(*) INTO v_total
    FROM gre_guia_remision g
    LEFT JOIN cli_clientes dest ON g.id_destinatario = dest.id
    WHERE g.estado = 1
      AND (p_id_tipo_guia IS NULL OR g.id_tipo_guia_remision = p_id_tipo_guia)
      AND (p_id_destinatario IS NULL OR g.id_destinatario = p_id_destinatario)
      AND (p_id_estado IS NULL OR g.id_estado = p_id_estado)
      AND (p_id_estado_sunat IS NULL OR g.id_estado_sunat = p_id_estado_sunat)
      AND (p_fecha_desde IS NULL OR g.fecha >= p_fecha_desde)
      AND (p_fecha_hasta IS NULL OR g.fecha <= p_fecha_hasta)
      AND (p_serie IS NULL OR p_serie = '' OR g.serie = TRIM(p_serie))
      AND (
          p_busqueda = ''
          OR gen_texto_coincide(g.serie, p_busqueda)
          OR gen_texto_coincide(g.numero, p_busqueda)
          OR gen_texto_coincide(COALESCE(dest.razon_social, ''), p_busqueda)
          OR gen_texto_coincide(COALESCE(dest.numero_documento, ''), p_busqueda)
          OR gen_texto_coincide(COALESCE(g.destinatario_nombre, ''), p_busqueda)
          OR gen_texto_coincide(COALESCE(g.destinatario_documento, ''), p_busqueda)
          OR gen_texto_coincide(COALESCE(g.remitente_nombre, ''), p_busqueda)
          OR gen_texto_coincide(COALESCE(g.remitente_documento, ''), p_busqueda)
          OR gen_texto_coincide(COALESCE(g.observaciones, ''), p_busqueda)
      );

    SELECT COALESCE(json_agg(row_to_json(t)), '[]'::JSON) INTO v_registros
    FROM (
        SELECT
            g.id,
            g.id_tipo_guia_remision,
            tg.nombre AS nombre_tipo_guia,
            tg.descripcion AS codigo_tipo_guia,
            g.serie,
            g.numero,
            g.fecha,
            g.fecha_traslado,
            g.id_destinatario,
            COALESCE(
                NULLIF(TRIM(g.destinatario_nombre), ''),
                dest.razon_social,
                TRIM(CONCAT_WS(' ', dest.nombres, dest.apellido_paterno, dest.apellido_materno))
            ) AS nombre_destinatario,
            COALESCE(
                NULLIF(TRIM(g.destinatario_documento), ''),
                dest.numero_documento
            ) AS documento_destinatario,
            g.id_motivo_traslado,
            mt.nombre AS nombre_motivo_traslado,
            mt.descripcion AS codigo_motivo_traslado,
            g.id_modalidad_traslado,
            md.nombre AS nombre_modalidad_traslado,
            md.descripcion AS codigo_modalidad_traslado,
            g.peso_bruto,
            g.numero_bultos,
            g.id_estado,
            eg.nombre AS nombre_estado,
            g.id_estado_sunat,
            es.nombre AS nombre_estado_sunat,
            g.ticket_sunat,
            g.estado,
            g.fecha_creacion,
            (
                SELECT COUNT(*)::INTEGER
                FROM gre_guia_remision_detalle d
                WHERE d.id_guia_remision = g.id AND d.estado = 1
            ) AS total_detalles,
            (
                EXISTS (
                    SELECT 1
                    FROM bal_recarga_planta rp
                    WHERE rp.estado = 1
                      AND (rp.id_guia_salida = g.id OR rp.id_guia_retorno = g.id)
                )
            ) AS vinculada_recarga_planta,
            (
                CASE
                    WHEN COALESCE(es.nombre, '') = 'ACEPTADO' THEN FALSE
                    WHEN EXISTS (
                        SELECT 1
                        FROM bal_recarga_planta rp
                        WHERE rp.estado = 1
                          AND (rp.id_guia_salida = g.id OR rp.id_guia_retorno = g.id)
                    ) THEN FALSE
                    ELSE TRUE
                END
            ) AS puede_eliminar,
            (
                CASE
                    WHEN COALESCE(es.nombre, '') = 'ACEPTADO' THEN 'aceptada SUNAT'
                    WHEN EXISTS (
                        SELECT 1
                        FROM bal_recarga_planta rp
                        WHERE rp.estado = 1
                          AND rp.id_guia_salida = g.id
                    ) THEN 'vinculada a orden de recarga'
                    WHEN EXISTS (
                        SELECT 1
                        FROM bal_recarga_planta rp
                        WHERE rp.estado = 1
                          AND rp.id_guia_retorno = g.id
                    ) THEN 'vinculada a retorno de recarga'
                    ELSE NULL
                END
            ) AS motivo_bloqueo_eliminar
        FROM gre_guia_remision g
        LEFT JOIN gen_lista_opciones tg ON g.id_tipo_guia_remision = tg.id
        LEFT JOIN gen_lista_opciones mt ON g.id_motivo_traslado = mt.id
        LEFT JOIN gen_lista_opciones md ON g.id_modalidad_traslado = md.id
        LEFT JOIN gen_lista_opciones eg ON g.id_estado = eg.id
        LEFT JOIN gen_lista_opciones es ON g.id_estado_sunat = es.id
        LEFT JOIN cli_clientes dest ON g.id_destinatario = dest.id
        WHERE g.estado = 1
          AND (p_id_tipo_guia IS NULL OR g.id_tipo_guia_remision = p_id_tipo_guia)
          AND (p_id_destinatario IS NULL OR g.id_destinatario = p_id_destinatario)
          AND (p_id_estado IS NULL OR g.id_estado = p_id_estado)
          AND (p_id_estado_sunat IS NULL OR g.id_estado_sunat = p_id_estado_sunat)
          AND (p_fecha_desde IS NULL OR g.fecha >= p_fecha_desde)
          AND (p_fecha_hasta IS NULL OR g.fecha <= p_fecha_hasta)
          AND (p_serie IS NULL OR p_serie = '' OR g.serie = TRIM(p_serie))
          AND (
              p_busqueda = ''
              OR gen_texto_coincide(g.serie, p_busqueda)
              OR gen_texto_coincide(g.numero, p_busqueda)
              OR gen_texto_coincide(COALESCE(dest.razon_social, ''), p_busqueda)
              OR gen_texto_coincide(COALESCE(dest.numero_documento, ''), p_busqueda)
              OR gen_texto_coincide(COALESCE(g.destinatario_nombre, ''), p_busqueda)
              OR gen_texto_coincide(COALESCE(g.destinatario_documento, ''), p_busqueda)
              OR gen_texto_coincide(COALESCE(g.remitente_nombre, ''), p_busqueda)
              OR gen_texto_coincide(COALESCE(g.remitente_documento, ''), p_busqueda)
              OR gen_texto_coincide(COALESCE(g.observaciones, ''), p_busqueda)
          )
        ORDER BY g.fecha DESC, g.id DESC
        LIMIT p_limite
        OFFSET p_offset
    ) t;

    RETURN json_build_object('registros', v_registros, 'total', v_total);
END;
$$;


--
-- Name: gre_obtener_guia_remision(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gre_obtener_guia_remision(p_id integer) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_registro JSON;
    v_detalles JSON;
    v_referencias JSON;
BEGIN
    SET TIME ZONE 'America/Lima';

    SELECT row_to_json(t) INTO v_registro
    FROM (
        SELECT
            g.id,
            g.id_tipo_guia_remision,
            tg.nombre AS nombre_tipo_guia,
            tg.descripcion AS codigo_tipo_guia,
            g.serie,
            g.numero,
            g.id_estado_sunat,
            es.nombre AS nombre_estado_sunat,
            g.ticket_sunat,
            g.hash_documento,
            g.fecha,
            g.tipo_cambio,
            g.id_sucursal,
            suc.nombre AS nombre_sucursal,
            g.id_almacen,
            alm.nombre AS nombre_almacen,
            g.id_cliente,
            COALESCE(
                NULLIF(TRIM(g.remitente_nombre), ''),
                cli.razon_social,
                TRIM(CONCAT_WS(' ', cli.nombres, cli.apellido_paterno, cli.apellido_materno))
            ) AS nombre_cliente,
            COALESCE(
                NULLIF(TRIM(g.remitente_documento), ''),
                cli.numero_documento
            ) AS documento_cliente,
            cli_td.descripcion AS codigo_tipo_doc_cliente,
            cli_td.nombre AS nombre_tipo_doc_cliente,
            g.fecha_traslado,
            g.id_motivo_traslado,
            mt.nombre AS nombre_motivo_traslado,
            mt.descripcion AS codigo_motivo_traslado,
            g.id_unidad_medida,
            um.nombre AS nombre_unidad_medida,
            um.descripcion AS codigo_unidad_medida,
            g.peso_bruto,
            g.numero_bultos,
            g.direccion_origen,
            g.id_distrito_origen,
            do_orig.nombre AS nombre_distrito_origen,
            do_orig.codigo_ubigeo AS ubigeo_origen,
            do_orig.id_provincia AS id_provincia_origen,
            po_orig.id_departamento AS id_departamento_origen,
            dep_orig.id_pais AS id_pais_origen,
            g.id_destinatario,
            COALESCE(
                NULLIF(TRIM(g.destinatario_nombre), ''),
                dest.razon_social,
                TRIM(CONCAT_WS(' ', dest.nombres, dest.apellido_paterno, dest.apellido_materno))
            ) AS nombre_destinatario,
            COALESCE(
                NULLIF(TRIM(g.destinatario_documento), ''),
                dest.numero_documento
            ) AS documento_destinatario,
            td.descripcion AS codigo_tipo_doc_destinatario,
            td.nombre AS nombre_tipo_doc_destinatario,
            g.direccion_llegada,
            g.id_distrito_llegada,
            do_lleg.nombre AS nombre_distrito_llegada,
            do_lleg.codigo_ubigeo AS ubigeo_llegada,
            do_lleg.id_provincia AS id_provincia_llegada,
            po_lleg.id_departamento AS id_departamento_llegada,
            dep_lleg.id_pais AS id_pais_llegada,
            g.id_modalidad_traslado,
            md.nombre AS nombre_modalidad_traslado,
            md.descripcion AS codigo_modalidad_traslado,
            g.id_transportista,
            COALESCE(
                transp.razon_social,
                TRIM(CONCAT_WS(' ', transp.nombres, transp.apellido_paterno, transp.apellido_materno))
            ) AS nombre_transportista,
            transp.numero_documento AS documento_transportista,
            g.id_chofer,
            TRIM(CONCAT_WS(' ', ch.nombres, ch.apellido_paterno, ch.apellido_materno)) AS nombre_chofer,
            ch.numero_documento AS documento_chofer,
            ch_td.descripcion AS codigo_tipo_doc_chofer,
            lic.codigo AS licencia_chofer,
            g.id_vehiculo,
            veh.placa AS placa_vehiculo,
            g.id_responsable,
            g.observaciones,
            g.periodo_contable,
            g.operacion,
            g.id_estado,
            eg.nombre AS nombre_estado,
            g.estado,
            g.fecha_creacion,
            g.fecha_modificacion
        FROM gre_guia_remision g
        LEFT JOIN gen_lista_opciones tg ON g.id_tipo_guia_remision = tg.id
        LEFT JOIN gen_lista_opciones es ON g.id_estado_sunat = es.id
        LEFT JOIN gen_lista_opciones mt ON g.id_motivo_traslado = mt.id
        LEFT JOIN gen_lista_opciones um ON g.id_unidad_medida = um.id
        LEFT JOIN gen_lista_opciones md ON g.id_modalidad_traslado = md.id
        LEFT JOIN gen_lista_opciones eg ON g.id_estado = eg.id
        LEFT JOIN gen_sucursal suc ON g.id_sucursal = suc.id
        LEFT JOIN gen_almacen alm ON g.id_almacen = alm.id
        LEFT JOIN cli_clientes cli ON g.id_cliente = cli.id
        LEFT JOIN gen_lista_opciones cli_td ON cli.id_tipo_documento = cli_td.id
        LEFT JOIN cli_clientes dest ON g.id_destinatario = dest.id
        LEFT JOIN gen_lista_opciones td ON dest.id_tipo_documento = td.id
        LEFT JOIN cli_clientes transp ON g.id_transportista = transp.id
        LEFT JOIN gen_chofer ch ON g.id_chofer = ch.id
        LEFT JOIN gen_lista_opciones ch_td ON ch.id_tipo_documento = ch_td.id
        LEFT JOIN LATERAL (
            SELECT gl.codigo
            FROM gen_licencia gl
            WHERE gl.id_chofer = ch.id AND gl.estado = 1
            ORDER BY gl.id DESC
            LIMIT 1
        ) lic ON TRUE
        LEFT JOIN gen_vehiculo veh ON g.id_vehiculo = veh.id
        LEFT JOIN gen_distrito do_orig ON g.id_distrito_origen = do_orig.id
        LEFT JOIN gen_provincia po_orig ON do_orig.id_provincia = po_orig.id
        LEFT JOIN gen_departamento dep_orig ON po_orig.id_departamento = dep_orig.id
        LEFT JOIN gen_distrito do_lleg ON g.id_distrito_llegada = do_lleg.id
        LEFT JOIN gen_provincia po_lleg ON do_lleg.id_provincia = po_lleg.id
        LEFT JOIN gen_departamento dep_lleg ON po_lleg.id_departamento = dep_lleg.id
        WHERE g.id = p_id AND g.estado = 1
    ) t;

    IF v_registro IS NULL THEN
        RETURN json_build_object('error', 'Guía de remisión no encontrada');
    END IF;

    SELECT COALESCE(json_agg(row_to_json(d) ORDER BY d.item), '[]'::JSON)
    INTO v_detalles
    FROM (
        SELECT
            det.id,
            det.item,
            det.id_producto,
            p.codigo AS codigo_producto,
            p.nombre AS nombre_producto,
            det.descripcion,
            COALESCE(det.id_unidad_medida, tb.id_unidad_medida) AS id_unidad_medida,
            COALESCE(umd.nombre, umt.nombre) AS nombre_unidad_medida,
            COALESCE(umd.descripcion, umt.descripcion) AS codigo_unidad_medida,
            det.cantidad,
            det.id_balon,
            bal.codigo_balon AS codigo_balon,
            tb.capacidad AS capacidad_tipo_balon,
            tb.capacidad AS capacidad,
            eb.nombre AS nombre_estado_balon,
            det.glosa
        FROM gre_guia_remision_detalle det
        LEFT JOIN pro_producto p ON det.id_producto = p.id
        LEFT JOIN gen_lista_opciones umd ON det.id_unidad_medida = umd.id
        LEFT JOIN bal_balon bal ON det.id_balon = bal.id
        LEFT JOIN bal_tipo_balon tb ON tb.id = bal.id_tipo_balon
        LEFT JOIN gen_lista_opciones umt ON umt.id = tb.id_unidad_medida
        LEFT JOIN gen_lista_opciones eb ON eb.id = bal.id_estado_balon
        WHERE det.id_guia_remision = p_id AND det.estado = 1
    ) d;

    SELECT COALESCE(json_agg(row_to_json(r) ORDER BY r.id), '[]'::JSON)
    INTO v_referencias
    FROM (
        SELECT
            ref.id,
            ref.id_tipo_comprobante,
            tc.nombre AS nombre_tipo_comprobante,
            tc.descripcion AS codigo_tipo_comprobante,
            ref.id_comprobante,
            ref.serie,
            ref.numero,
            ref.fecha
        FROM gre_documentos_referencia ref
        LEFT JOIN gen_lista_opciones tc ON ref.id_tipo_comprobante = tc.id
        WHERE ref.id_guia_remision = p_id AND ref.estado = 1
    ) r;

    RETURN json_build_object(
        'registro', v_registro,
        'detalles', v_detalles,
        'referencias', v_referencias
    );
END;
$$;


--
-- Name: gre_obtener_siguiente_numero(character varying); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gre_obtener_siguiente_numero(p_serie character varying) RETURNS json
    LANGUAGE plpgsql
    AS $_$
DECLARE
    v_serie VARCHAR(10);
    v_ultimo BIGINT;
    v_siguiente VARCHAR(15);
BEGIN
    SET TIME ZONE 'America/Lima';

    v_serie := UPPER(TRIM(p_serie));
    IF v_serie = '' THEN
        RETURN json_build_object('error', 'La serie es obligatoria');
    END IF;

    -- UNIQUE(serie, numero) incluye anulados: el siguiente debe considerar todos los estados.
    SELECT COALESCE(MAX(numero::BIGINT), 0)
    INTO v_ultimo
    FROM gre_guia_remision
    WHERE UPPER(TRIM(serie)) = v_serie
      AND numero ~ '^[0-9]+$';

    v_siguiente := LPAD((v_ultimo + 1)::TEXT, 8, '0');

    RETURN json_build_object(
        'serie', v_serie,
        'numero', v_siguiente
    );
END;
$_$;


--
-- Name: gre_registrar_respuesta_sunat(integer, character varying, character varying, text, text, character varying, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gre_registrar_respuesta_sunat(p_id integer, p_ticket_sunat character varying DEFAULT NULL::character varying, p_hash_documento character varying DEFAULT NULL::character varying, p_xml_firmado text DEFAULT NULL::text, p_cdr_respuesta text DEFAULT NULL::text, p_nombre_estado_sunat character varying DEFAULT NULL::character varying, p_id_usuario_auditoria integer DEFAULT NULL::integer) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_id_estado_sunat INTEGER;
    v_id_estado_op INTEGER;
BEGIN
    SET TIME ZONE 'America/Lima';

    IF NOT EXISTS (SELECT 1 FROM gre_guia_remision WHERE id = p_id AND estado = 1) THEN
        RETURN json_build_object('error', 'Guía de remisión no encontrada');
    END IF;

    IF p_nombre_estado_sunat IS NOT NULL AND TRIM(p_nombre_estado_sunat) <> '' THEN
        SELECT lo.id INTO v_id_estado_sunat
        FROM gen_lista_opciones lo
        INNER JOIN gen_lista l ON l.id = lo.id_lista
        WHERE l.nombre = 'EstadoSunat'
          AND lo.nombre = UPPER(TRIM(p_nombre_estado_sunat))
          AND lo.estado = 1
        LIMIT 1;

        IF v_id_estado_sunat IS NULL THEN
            RETURN json_build_object('error', format('Estado SUNAT %s no configurado', p_nombre_estado_sunat));
        END IF;
    END IF;

    IF UPPER(TRIM(COALESCE(p_nombre_estado_sunat, ''))) = 'ACEPTADO' THEN
        SELECT lo.id INTO v_id_estado_op
        FROM gen_lista_opciones lo
        INNER JOIN gen_lista l ON l.id = lo.id_lista
        WHERE l.nombre = 'EstadoGuiaRemision' AND lo.nombre = 'ENVIADO' AND lo.estado = 1
        LIMIT 1;
    END IF;

    UPDATE gre_guia_remision
    SET ticket_sunat = COALESCE(NULLIF(TRIM(p_ticket_sunat), ''), ticket_sunat),
        hash_documento = COALESCE(NULLIF(TRIM(p_hash_documento), ''), hash_documento),
        xml_firmado = COALESCE(p_xml_firmado, xml_firmado),
        cdr_respuesta = COALESCE(p_cdr_respuesta, cdr_respuesta),
        id_estado_sunat = COALESCE(v_id_estado_sunat, id_estado_sunat),
        id_estado = COALESCE(v_id_estado_op, id_estado),
        id_usuario_modificacion = p_id_usuario_auditoria,
        fecha_modificacion = NOW()
    WHERE id = p_id;

    RETURN gre_obtener_guia_remision(p_id);
END;
$$;


--
-- Name: inv_eliminar_movimiento(integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.inv_eliminar_movimiento(p_id integer, p_id_usuario_auditoria integer DEFAULT NULL::integer) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_mov inv_movimiento%ROWTYPE;
    v_nombre_tipo_mov VARCHAR;
    v_es_salida BOOLEAN;
    v_es_traslado BOOLEAN;
    v_id_stock INTEGER;
    v_stock_actual NUMERIC(12,4);
    v_stock_revertido NUMERIC(12,4);
    v_id_estado_en_almacen INTEGER;
    v_id_almacen_stock INTEGER;
BEGIN
    SET TIME ZONE 'America/Lima';

    SELECT * INTO v_mov FROM inv_movimiento WHERE id = p_id AND estado = 1 FOR UPDATE;

    IF NOT FOUND THEN
        RETURN json_build_object('eliminado', FALSE, 'id', p_id);
    END IF;

    IF v_mov.id_documento_origen IS NOT NULL THEN
        RETURN json_build_object(
            'eliminado', FALSE, 'id', p_id,
            'error', 'No se puede anular un movimiento vinculado a un documento; anula el documento origen'
        );
    END IF;

    SELECT nombre INTO v_nombre_tipo_mov FROM gen_lista_opciones WHERE id = v_mov.id_tipo_movimiento;
    v_es_salida := (v_mov.stock_nuevo IS NOT NULL AND v_mov.stock_anterior IS NOT NULL AND v_mov.stock_nuevo < v_mov.stock_anterior)
                   OR (v_nombre_tipo_mov ILIKE '%SALIDA%');
    v_es_traslado := (v_mov.naturaleza = 'PRODUCTO' AND UPPER(COALESCE(v_nombre_tipo_mov, '')) = 'TRASLADO');
    IF v_es_traslado THEN
        v_es_salida := TRUE;
    END IF;

    IF v_mov.id_producto IS NOT NULL AND v_mov.stock_anterior IS NOT NULL AND v_mov.stock_nuevo IS NOT NULL THEN
        -- PRODUCTO siempre mueve el almacén origen. BALON+gas puede haber movido el destino
        -- (p.ej. ENTRADA_LLENADO), según la misma resolución que usó inv_registrar_movimiento.
        IF v_mov.naturaleza = 'PRODUCTO' THEN
            v_id_almacen_stock := v_mov.id_almacen_origen;
        ELSE
            v_id_almacen_stock := COALESCE(
                CASE WHEN v_es_salida THEN v_mov.id_almacen_origen ELSE v_mov.id_almacen_destino END,
                v_mov.id_almacen_origen,
                v_mov.id_almacen_destino
            );
        END IF;

        SELECT id, stock INTO v_id_stock, v_stock_actual
        FROM pro_stock
        WHERE id_almacen = v_id_almacen_stock AND id_producto = v_mov.id_producto AND estado = 1
        FOR UPDATE;

        IF v_id_stock IS NULL THEN
            RETURN json_build_object('eliminado', FALSE, 'id', p_id, 'error', 'No se encontró el registro de stock para revertir el movimiento');
        END IF;

        v_stock_revertido := v_stock_actual + (CASE WHEN v_es_salida THEN v_mov.cantidad ELSE -v_mov.cantidad END);
        IF v_stock_revertido < 0 THEN
            RETURN json_build_object('eliminado', FALSE, 'id', p_id, 'error', 'No se puede anular el movimiento porque revertiría un stock negativo');
        END IF;

        UPDATE pro_stock
        SET stock = v_stock_revertido, id_usuario_modificacion = p_id_usuario_auditoria, fecha_modificacion = NOW()
        WHERE id = v_id_stock;

        IF v_es_traslado AND v_mov.id_almacen_destino IS NOT NULL THEN
            SELECT id, stock INTO v_id_stock, v_stock_actual
            FROM pro_stock
            WHERE id_almacen = v_mov.id_almacen_destino AND id_producto = v_mov.id_producto AND estado = 1
            FOR UPDATE;

            IF v_id_stock IS NULL THEN
                RETURN json_build_object('eliminado', FALSE, 'id', p_id, 'error', 'No se encontró el stock de destino para revertir el traslado');
            END IF;

            v_stock_revertido := v_stock_actual - v_mov.cantidad;
            IF v_stock_revertido < 0 THEN
                RETURN json_build_object('eliminado', FALSE, 'id', p_id, 'error', 'No se puede anular el traslado porque el destino ya no tiene esa cantidad');
            END IF;

            UPDATE pro_stock
            SET stock = v_stock_revertido, id_usuario_modificacion = p_id_usuario_auditoria, fecha_modificacion = NOW()
            WHERE id = v_id_stock;
        END IF;
    END IF;

    IF v_mov.naturaleza = 'BALON' AND v_mov.id_balon IS NOT NULL THEN
        SELECT lo.id INTO v_id_estado_en_almacen
        FROM gen_lista_opciones lo
        INNER JOIN gen_lista l ON l.id = lo.id_lista
        WHERE l.nombre = 'EstadoBalon' AND lo.nombre = 'EN_ALMACEN' AND lo.estado = 1
        LIMIT 1;

        IF v_id_estado_en_almacen IS NOT NULL THEN
            UPDATE bal_balon
            SET
                id_estado_balon = v_id_estado_en_almacen,
                id_cliente_ubicacion = NULL,
                id_almacen = COALESCE(v_mov.id_almacen_origen, v_mov.id_almacen_destino, id_almacen),
                id_usuario_modificacion = p_id_usuario_auditoria,
                fecha_modificacion = NOW()
            WHERE id = v_mov.id_balon AND estado = 1;
        END IF;
    END IF;

    UPDATE inv_movimiento
    SET estado = 0, id_usuario_modificacion = p_id_usuario_auditoria, fecha_modificacion = NOW()
    WHERE id = p_id AND estado = 1;

    RETURN json_build_object('eliminado', TRUE, 'id', p_id);
END;
$$;


--
-- Name: inv_listar_movimientos(character varying, integer, integer, character varying, integer, integer, integer, integer, integer, integer, date, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.inv_listar_movimientos(p_busqueda character varying DEFAULT ''::character varying, p_limite integer DEFAULT 10, p_offset integer DEFAULT 0, p_naturaleza character varying DEFAULT NULL::character varying, p_id_producto integer DEFAULT NULL::integer, p_id_balon integer DEFAULT NULL::integer, p_id_almacen integer DEFAULT NULL::integer, p_id_tipo_movimiento integer DEFAULT NULL::integer, p_id_tipo_documento_origen integer DEFAULT NULL::integer, p_id_documento_origen integer DEFAULT NULL::integer, p_fecha_desde date DEFAULT NULL::date, p_fecha_hasta date DEFAULT NULL::date) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_registros JSON;
    v_total BIGINT;
    v_resumen JSON;
BEGIN
    SET TIME ZONE 'America/Lima';

    SELECT
        COUNT(*),
        json_build_object(
            'total', COUNT(*),
            'producto', COUNT(*) FILTER (WHERE m.naturaleza = 'PRODUCTO'),
            'balon', COUNT(*) FILTER (WHERE m.naturaleza = 'BALON'),
            'salidas', COUNT(*) FILTER (WHERE tm.nombre ILIKE '%SALIDA%'),
            'entradas', COUNT(*) FILTER (WHERE tm.nombre ILIKE '%ENTRADA%' OR tm.nombre = 'INGRESO')
        )
    INTO v_total, v_resumen
    FROM inv_movimiento m
    LEFT JOIN pro_producto p ON p.id = m.id_producto
    LEFT JOIN bal_balon b ON b.id = m.id_balon
    LEFT JOIN gen_almacen a ON a.id = m.id_almacen_origen
    LEFT JOIN gen_lista_opciones tm ON tm.id = m.id_tipo_movimiento
    WHERE m.estado = 1
      AND (p_naturaleza IS NULL OR m.naturaleza = UPPER(TRIM(p_naturaleza)))
      AND (p_id_producto IS NULL OR m.id_producto = p_id_producto)
      AND (p_id_balon IS NULL OR m.id_balon = p_id_balon)
      AND (p_id_almacen IS NULL OR m.id_almacen_origen = p_id_almacen OR m.id_almacen_destino = p_id_almacen)
      AND (p_id_tipo_movimiento IS NULL OR m.id_tipo_movimiento = p_id_tipo_movimiento)
      AND (p_id_tipo_documento_origen IS NULL OR m.id_tipo_documento_origen = p_id_tipo_documento_origen)
      AND (p_id_documento_origen IS NULL OR m.id_documento_origen = p_id_documento_origen)
      AND (p_fecha_desde IS NULL OR m.fecha >= p_fecha_desde)
      AND (p_fecha_hasta IS NULL OR m.fecha <= p_fecha_hasta)
      AND (
          p_busqueda = ''
          OR gen_texto_coincide(COALESCE(m.glosa, ''), p_busqueda)
          OR gen_texto_coincide(COALESCE(p.codigo, ''), p_busqueda)
          OR gen_texto_coincide(COALESCE(p.nombre, ''), p_busqueda)
          OR gen_texto_coincide(COALESCE(b.numero_serie, ''), p_busqueda)
          OR gen_texto_coincide(COALESCE(a.nombre, ''), p_busqueda)
          OR gen_texto_coincide(COALESCE(tm.nombre, ''), p_busqueda)
      );

    SELECT COALESCE(json_agg(row_to_json(t)), '[]'::JSON) INTO v_registros
    FROM (
        SELECT
            m.id,
            m.fecha,
            m.naturaleza,
            m.id_tipo_movimiento,
            tm.nombre AS nombre_tipo_movimiento,
            m.id_producto,
            p.codigo AS codigo_producto,
            p.nombre AS nombre_producto,
            COALESCE(p.es_gas, FALSE) AS es_gas,
            m.id_balon,
            b.numero_serie AS numero_serie_balon,
            m.cantidad,
            umed.nombre AS nombre_unidad_medida,
            m.id_almacen_origen,
            ao.nombre AS nombre_almacen_origen,
            m.id_almacen_destino,
            ad.nombre AS nombre_almacen_destino,
            m.id_cliente,
            COALESCE(
                NULLIF(TRIM(cli.razon_social), ''),
                NULLIF(TRIM(CONCAT_WS(' ', cli.nombres, cli.apellido_paterno, cli.apellido_materno)), ''),
                cli.numero_documento
            ) AS nombre_cliente,
            m.stock_anterior,
            m.stock_nuevo,
            m.id_documento_origen,
            m.id_tipo_documento_origen,
            tdo.nombre AS nombre_tipo_documento_origen,
            m.id_movimiento_padre,
            (m.id_documento_origen IS NULL) AS puede_anular,
            m.glosa,
            m.estado,
            m.fecha_creacion,
            m.fecha_modificacion,
            m.id_usuario_creacion,
            uc.nombre AS nombre_usuario_creacion
        FROM inv_movimiento m
        LEFT JOIN pro_producto p ON p.id = m.id_producto
        LEFT JOIN bal_balon b ON b.id = m.id_balon
        LEFT JOIN gen_lista_opciones umed ON umed.id = m.id_unidad_medida
        LEFT JOIN gen_almacen ao ON ao.id = m.id_almacen_origen
        LEFT JOIN gen_almacen ad ON ad.id = m.id_almacen_destino
        LEFT JOIN gen_almacen a ON a.id = m.id_almacen_origen
        LEFT JOIN cli_clientes cli ON cli.id = m.id_cliente
        LEFT JOIN gen_lista_opciones tm ON tm.id = m.id_tipo_movimiento
        LEFT JOIN gen_lista_opciones tdo ON tdo.id = m.id_tipo_documento_origen
        LEFT JOIN auth_usuarios uc ON uc.id = m.id_usuario_creacion
        WHERE m.estado = 1
          AND (p_naturaleza IS NULL OR m.naturaleza = UPPER(TRIM(p_naturaleza)))
          AND (p_id_producto IS NULL OR m.id_producto = p_id_producto)
          AND (p_id_balon IS NULL OR m.id_balon = p_id_balon)
          AND (p_id_almacen IS NULL OR m.id_almacen_origen = p_id_almacen OR m.id_almacen_destino = p_id_almacen)
          AND (p_id_tipo_movimiento IS NULL OR m.id_tipo_movimiento = p_id_tipo_movimiento)
          AND (p_id_tipo_documento_origen IS NULL OR m.id_tipo_documento_origen = p_id_tipo_documento_origen)
          AND (p_id_documento_origen IS NULL OR m.id_documento_origen = p_id_documento_origen)
          AND (p_fecha_desde IS NULL OR m.fecha >= p_fecha_desde)
          AND (p_fecha_hasta IS NULL OR m.fecha <= p_fecha_hasta)
          AND (
              p_busqueda = ''
              OR gen_texto_coincide(COALESCE(m.glosa, ''), p_busqueda)
              OR gen_texto_coincide(COALESCE(p.codigo, ''), p_busqueda)
              OR gen_texto_coincide(COALESCE(p.nombre, ''), p_busqueda)
              OR gen_texto_coincide(COALESCE(b.numero_serie, ''), p_busqueda)
              OR gen_texto_coincide(COALESCE(a.nombre, ''), p_busqueda)
              OR gen_texto_coincide(COALESCE(tm.nombre, ''), p_busqueda)
          )
        ORDER BY m.fecha DESC, m.id DESC
        LIMIT p_limite
        OFFSET p_offset
    ) t;

    RETURN json_build_object(
        'registros', v_registros,
        'total', v_total,
        'resumen', v_resumen
    );
END;
$$;


--
-- Name: inv_obtener_movimiento(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.inv_obtener_movimiento(p_id integer) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_registro JSON;
BEGIN
    SET TIME ZONE 'America/Lima';

    SELECT row_to_json(t) INTO v_registro
    FROM (
        SELECT
            m.id,
            m.fecha,
            m.naturaleza,
            m.id_tipo_movimiento,
            tm.nombre AS nombre_tipo_movimiento,
            m.id_producto,
            p.codigo AS codigo_producto,
            p.nombre AS nombre_producto,
            COALESCE(p.es_gas, FALSE) AS es_gas,
            m.id_balon,
            b.numero_serie AS numero_serie_balon,
            m.cantidad,
            m.id_unidad_medida,
            umed.nombre AS nombre_unidad_medida,
            m.id_almacen_origen,
            ao.nombre AS nombre_almacen_origen,
            m.id_almacen_destino,
            ad.nombre AS nombre_almacen_destino,
            m.id_cliente,
            COALESCE(
                NULLIF(TRIM(cli.razon_social), ''),
                NULLIF(TRIM(CONCAT_WS(' ', cli.nombres, cli.apellido_paterno, cli.apellido_materno)), ''),
                cli.numero_documento
            ) AS nombre_cliente,
            m.id_documento_origen,
            m.id_tipo_documento_origen,
            tdo.nombre AS nombre_tipo_documento_origen,
            m.id_movimiento_padre,
            m.stock_anterior,
            m.stock_nuevo,
            m.id_estado_balon_snapshot,
            eb.nombre AS nombre_estado_balon_snapshot,
            m.glosa,
            m.estado,
            m.fecha_creacion,
            m.fecha_modificacion,
            m.id_usuario_creacion,
            uc.nombre AS nombre_usuario_creacion,
            m.id_usuario_modificacion,
            um.nombre AS nombre_usuario_modificacion
        FROM inv_movimiento m
        LEFT JOIN pro_producto p ON p.id = m.id_producto
        LEFT JOIN bal_balon b ON b.id = m.id_balon
        LEFT JOIN gen_lista_opciones umed ON umed.id = m.id_unidad_medida
        LEFT JOIN gen_almacen ao ON ao.id = m.id_almacen_origen
        LEFT JOIN gen_almacen ad ON ad.id = m.id_almacen_destino
        LEFT JOIN cli_clientes cli ON cli.id = m.id_cliente
        LEFT JOIN gen_lista_opciones tm ON tm.id = m.id_tipo_movimiento
        LEFT JOIN gen_lista_opciones tdo ON tdo.id = m.id_tipo_documento_origen
        LEFT JOIN gen_lista_opciones eb ON eb.id = m.id_estado_balon_snapshot
        LEFT JOIN auth_usuarios uc ON uc.id = m.id_usuario_creacion
        LEFT JOIN auth_usuarios um ON um.id = m.id_usuario_modificacion
        WHERE m.id = p_id AND m.estado = 1
    ) t;

    RETURN json_build_object('registro', v_registro);
END;
$$;


--
-- Name: inv_registrar_movimiento(character varying, character varying, timestamp without time zone, integer, integer, numeric, integer, integer, integer, character varying, integer, character varying, integer, integer, character varying, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.inv_registrar_movimiento(p_naturaleza character varying, p_codigo_tipo_movimiento character varying, p_fecha timestamp without time zone DEFAULT now(), p_id_producto integer DEFAULT NULL::integer, p_id_balon integer DEFAULT NULL::integer, p_cantidad numeric DEFAULT 0, p_id_almacen_origen integer DEFAULT NULL::integer, p_id_almacen_destino integer DEFAULT NULL::integer, p_id_cliente integer DEFAULT NULL::integer, p_codigo_tipo_documento_origen character varying DEFAULT NULL::character varying, p_id_documento_origen integer DEFAULT NULL::integer, p_glosa character varying DEFAULT NULL::character varying, p_id_usuario_auditoria integer DEFAULT NULL::integer, p_id_movimiento_padre integer DEFAULT NULL::integer, p_sentido_ajuste character varying DEFAULT NULL::character varying, p_forzar boolean DEFAULT false) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_naturaleza VARCHAR;
    v_id_tipo_mov INTEGER;
    v_nombre_tipo_mov VARCHAR;
    v_id_tipo_doc INTEGER;
    v_id_existente INTEGER;
    v_cantidad NUMERIC(12,4);
    v_es_salida BOOLEAN;
    v_es_traslado BOOLEAN;
    v_id INTEGER;
    -- rama PRODUCTO
    v_afecta_stock BOOLEAN;
    v_id_unidad_medida INTEGER;
    v_id_stock INTEGER;
    v_id_stock_dest INTEGER;
    v_stock_anterior NUMERIC(12,4);
    v_stock_nuevo NUMERIC(12,4);
    v_stock_dest_ant NUMERIC(12,4);
    -- rama BALON
    v_nombre_estado_actual VARCHAR;
    v_codigo_estado_destino VARCHAR;
    v_cliente_destino INTEGER;
    v_limpiar_almacen BOOLEAN;
    v_codigo_contenido VARCHAR;
    v_id_estado_balon INTEGER;
    v_id_almacen_balon INTEGER;
BEGIN
    SET TIME ZONE 'America/Lima';

    v_naturaleza := UPPER(TRIM(COALESCE(p_naturaleza, '')));
    IF v_naturaleza NOT IN ('PRODUCTO', 'BALON') THEN
        RETURN json_build_object('error', 'naturaleza debe ser PRODUCTO o BALON', 'registro', NULL);
    END IF;

    IF v_naturaleza = 'PRODUCTO' AND p_id_producto IS NULL THEN
        RETURN json_build_object('error', 'id_producto es obligatorio para naturaleza PRODUCTO', 'registro', NULL);
    END IF;

    IF v_naturaleza = 'BALON' AND p_id_balon IS NULL THEN
        RETURN json_build_object('error', 'id_balon es obligatorio para naturaleza BALON', 'registro', NULL);
    END IF;

    IF p_codigo_tipo_movimiento IS NULL OR TRIM(p_codigo_tipo_movimiento) = '' THEN
        RETURN json_build_object('error', 'El tipo de movimiento es obligatorio', 'registro', NULL);
    END IF;

    SELECT lo.id, lo.nombre INTO v_id_tipo_mov, v_nombre_tipo_mov
    FROM gen_lista_opciones lo
    INNER JOIN gen_lista l ON l.id = lo.id_lista
    WHERE l.nombre = 'TipoMovInvUnificado'
      AND lo.nombre = UPPER(TRIM(p_codigo_tipo_movimiento))
      AND lo.estado = 1
    LIMIT 1;

    IF v_id_tipo_mov IS NULL THEN
        RETURN json_build_object(
            'error', format('Tipo de movimiento %s no configurado', UPPER(TRIM(p_codigo_tipo_movimiento))),
            'registro', NULL
        );
    END IF;

    IF p_codigo_tipo_documento_origen IS NOT NULL AND TRIM(p_codigo_tipo_documento_origen) <> '' THEN
        SELECT lo.id INTO v_id_tipo_doc
        FROM gen_lista_opciones lo
        INNER JOIN gen_lista l ON l.id = lo.id_lista
        WHERE l.nombre = 'TipoDocumentoRef'
          AND lo.nombre = UPPER(TRIM(p_codigo_tipo_documento_origen))
          AND lo.estado = 1
        LIMIT 1;

        IF v_id_tipo_doc IS NULL THEN
            RETURN json_build_object(
                'error', format('Tipo de documento origen %s no configurado', UPPER(TRIM(p_codigo_tipo_documento_origen))),
                'registro', NULL
            );
        END IF;
    END IF;

    -- Anti-duplicación: mismo documento + mismo tipo + mismo producto/balón ya registrado.
    IF p_id_documento_origen IS NOT NULL AND v_id_tipo_doc IS NOT NULL AND NOT COALESCE(p_forzar, FALSE) THEN
        SELECT m.id INTO v_id_existente
        FROM inv_movimiento m
        WHERE m.estado = 1
          AND m.naturaleza = v_naturaleza
          AND m.id_tipo_documento_origen = v_id_tipo_doc
          AND m.id_documento_origen = p_id_documento_origen
          AND m.id_tipo_movimiento = v_id_tipo_mov
          AND (v_naturaleza <> 'PRODUCTO' OR m.id_producto = p_id_producto)
          AND (v_naturaleza <> 'BALON' OR m.id_balon = p_id_balon)
        ORDER BY m.id
        LIMIT 1;

        IF v_id_existente IS NOT NULL THEN
            RETURN (inv_obtener_movimiento(v_id_existente)::JSONB || jsonb_build_object('creado', FALSE))::JSON;
        END IF;
    END IF;

    v_cantidad := ABS(COALESCE(p_cantidad, 0));
    v_es_traslado := (v_naturaleza = 'PRODUCTO' AND UPPER(v_nombre_tipo_mov) = 'TRASLADO');
    -- RECARGA_CLIENTE no lleva el prefijo SALIDA_ pero sí es salida de gas hacia el cliente.
    v_es_salida := v_nombre_tipo_mov ILIKE '%SALIDA%' OR UPPER(v_nombre_tipo_mov) = 'RECARGA_CLIENTE';

    IF UPPER(v_nombre_tipo_mov) = 'AJUSTE' AND UPPER(TRIM(COALESCE(p_sentido_ajuste, ''))) = 'MENOS' THEN
        v_es_salida := TRUE;
    END IF;

    IF v_naturaleza = 'PRODUCTO' THEN
        IF v_cantidad <= 0 THEN
            RETURN json_build_object('error', 'La cantidad debe ser mayor a cero', 'registro', NULL);
        END IF;

        IF NOT EXISTS (SELECT 1 FROM pro_producto WHERE id = p_id_producto AND estado = 1) THEN
            RETURN json_build_object('error', 'El producto indicado no existe o está inactivo', 'registro', NULL);
        END IF;

        IF p_id_almacen_origen IS NULL OR NOT EXISTS (
            SELECT 1 FROM gen_almacen WHERE id = p_id_almacen_origen AND estado = 1
        ) THEN
            RETURN json_build_object('error', 'El almacén indicado no existe o está inactivo', 'registro', NULL);
        END IF;

        SELECT COALESCE(afecta_stock, FALSE), id_unidad_medida
        INTO v_afecta_stock, v_id_unidad_medida
        FROM pro_producto WHERE id = p_id_producto;

        IF v_es_traslado THEN
            IF p_id_almacen_destino IS NULL THEN
                RETURN json_build_object('error', 'El traslado requiere almacén de destino', 'registro', NULL);
            END IF;
            IF p_id_almacen_destino = p_id_almacen_origen THEN
                RETURN json_build_object('error', 'El almacén de destino debe ser distinto al de origen', 'registro', NULL);
            END IF;
            IF NOT EXISTS (SELECT 1 FROM gen_almacen WHERE id = p_id_almacen_destino AND estado = 1) THEN
                RETURN json_build_object('error', 'El almacén de destino no existe o está inactivo', 'registro', NULL);
            END IF;
        END IF;

        v_stock_anterior := 0;
        v_stock_nuevo := 0;

        IF v_afecta_stock THEN
            SELECT id, stock INTO v_id_stock, v_stock_anterior
            FROM pro_stock
            WHERE id_almacen = p_id_almacen_origen AND id_producto = p_id_producto AND estado = 1
            FOR UPDATE;

            IF v_id_stock IS NULL THEN
                INSERT INTO pro_stock (id_almacen, id_producto, stock, stock_minimo, id_usuario_creacion, id_usuario_modificacion)
                VALUES (p_id_almacen_origen, p_id_producto, 0, 0, p_id_usuario_auditoria, p_id_usuario_auditoria)
                RETURNING id, stock INTO v_id_stock, v_stock_anterior;
            END IF;

            IF v_es_salida THEN
                v_stock_nuevo := v_stock_anterior - v_cantidad;
            ELSE
                v_stock_nuevo := v_stock_anterior + v_cantidad;
            END IF;

            IF v_stock_nuevo < 0 THEN
                RETURN json_build_object('error', 'Stock insuficiente para registrar la salida', 'registro', NULL);
            END IF;

            UPDATE pro_stock
            SET stock = v_stock_nuevo, id_usuario_modificacion = p_id_usuario_auditoria, fecha_modificacion = NOW()
            WHERE id = v_id_stock;

            IF v_es_traslado THEN
                SELECT id, stock INTO v_id_stock_dest, v_stock_dest_ant
                FROM pro_stock
                WHERE id_almacen = p_id_almacen_destino AND id_producto = p_id_producto AND estado = 1
                FOR UPDATE;

                IF v_id_stock_dest IS NULL THEN
                    INSERT INTO pro_stock (id_almacen, id_producto, stock, stock_minimo, id_usuario_creacion, id_usuario_modificacion)
                    VALUES (p_id_almacen_destino, p_id_producto, 0, 0, p_id_usuario_auditoria, p_id_usuario_auditoria)
                    RETURNING id, stock INTO v_id_stock_dest, v_stock_dest_ant;
                END IF;

                UPDATE pro_stock
                SET stock = COALESCE(v_stock_dest_ant, 0) + v_cantidad,
                    id_usuario_modificacion = p_id_usuario_auditoria, fecha_modificacion = NOW()
                WHERE id = v_id_stock_dest;
            END IF;
        END IF;

        INSERT INTO inv_movimiento (
            fecha, id_tipo_movimiento, naturaleza, id_producto, cantidad, id_unidad_medida,
            id_almacen_origen, id_almacen_destino, id_cliente,
            id_documento_origen, id_tipo_documento_origen, id_movimiento_padre,
            stock_anterior, stock_nuevo, glosa,
            id_usuario_creacion, id_usuario_modificacion
        )
        VALUES (
            COALESCE(p_fecha, NOW()), v_id_tipo_mov, 'PRODUCTO', p_id_producto, v_cantidad, v_id_unidad_medida,
            p_id_almacen_origen, p_id_almacen_destino, p_id_cliente,
            p_id_documento_origen, v_id_tipo_doc, p_id_movimiento_padre,
            CASE WHEN v_afecta_stock THEN v_stock_anterior ELSE NULL END,
            CASE WHEN v_afecta_stock THEN v_stock_nuevo ELSE NULL END,
            p_glosa, p_id_usuario_auditoria, p_id_usuario_auditoria
        )
        RETURNING id INTO v_id;

        RETURN (inv_obtener_movimiento(v_id)::JSONB || jsonb_build_object('creado', TRUE))::JSON;
    END IF;

    -- ============== naturaleza = BALON ==============

    SELECT eb.nombre, b.id_almacen
    INTO v_nombre_estado_actual, v_id_almacen_balon
    FROM bal_balon b
    LEFT JOIN gen_lista_opciones eb ON eb.id = b.id_estado_balon
    WHERE b.id = p_id_balon AND b.estado = 1
    FOR UPDATE OF b;

    IF NOT FOUND THEN
        RETURN json_build_object('error', 'El cilindro indicado no existe o está inactivo', 'registro', NULL);
    END IF;

    IF COALESCE(v_nombre_estado_actual, '') IN ('DADO_DE_BAJA', 'ROBO') THEN
        RETURN json_build_object(
            'error', 'No se puede registrar movimiento de un cilindro dado de baja o reportado como robo',
            'registro', NULL
        );
    END IF;

    -- Mismo mapeo tipo→estado que bal_aplicar_custodia_tipo_movimiento (custodia "Libro").
    v_limpiar_almacen := FALSE;
    v_codigo_contenido := NULL;
    v_cliente_destino := NULL;
    CASE v_nombre_tipo_mov
        WHEN 'SALIDA_PRESTAMO' THEN
            v_codigo_estado_destino := 'PRESTADO_CLIENTE'; v_cliente_destino := p_id_cliente; v_limpiar_almacen := TRUE;
        WHEN 'SALIDA_ALQUILER' THEN
            v_codigo_estado_destino := 'ALQUILADO'; v_cliente_destino := p_id_cliente; v_limpiar_almacen := TRUE;
        WHEN 'SALIDA_VENTA' THEN
            v_codigo_estado_destino := 'EN_PODER_CLIENTE'; v_cliente_destino := p_id_cliente; v_limpiar_almacen := TRUE;
        WHEN 'SALIDA_ENTREGA_CLIENTE' THEN
            v_codigo_estado_destino := 'EN_PODER_CLIENTE'; v_cliente_destino := p_id_cliente; v_limpiar_almacen := TRUE;
        WHEN 'SALIDA_MANTENIMIENTO' THEN
            v_codigo_estado_destino := 'EN_MANTENIMIENTO';
        WHEN 'SALIDA_PLANTA_EXTERNA' THEN
            v_codigo_estado_destino := 'EN_RECARGA_EXTERNA'; v_limpiar_almacen := TRUE; v_codigo_contenido := 'VACIO';
        WHEN 'ENTRADA_DEVOLUCION', 'ENTRADA_MANTENIMIENTO', 'RETORNO_LIMA' THEN
            v_codigo_estado_destino := 'EN_ALMACEN';
        WHEN 'ENTRADA_LLENADO', 'ENTRADA_PLANTA_EXTERNA' THEN
            v_codigo_estado_destino := 'EN_ALMACEN'; v_codigo_contenido := 'LLENO';
        WHEN 'RECARGA_CLIENTE' THEN
            v_codigo_estado_destino := 'EN_PODER_CLIENTE'; v_cliente_destino := p_id_cliente; v_limpiar_almacen := TRUE;
        WHEN 'TRASLADO_LIMA' THEN
            v_codigo_estado_destino := 'EN_RUTA_LIMA'; v_limpiar_almacen := TRUE;
        ELSE
            v_codigo_estado_destino := NULL;
    END CASE;

    IF v_codigo_estado_destino IS NOT NULL THEN
        SELECT lo.id INTO v_id_estado_balon
        FROM gen_lista_opciones lo
        INNER JOIN gen_lista l ON l.id = lo.id_lista
        WHERE l.nombre = 'EstadoBalon' AND lo.nombre = v_codigo_estado_destino AND lo.estado = 1
        LIMIT 1;

        IF v_id_estado_balon IS NULL THEN
            RETURN json_build_object('error', format('Estado %s no configurado', v_codigo_estado_destino), 'registro', NULL);
        END IF;

        UPDATE bal_balon
        SET
            id_estado_balon = v_id_estado_balon,
            id_cliente_ubicacion = CASE WHEN v_cliente_destino IS NOT NULL THEN v_cliente_destino ELSE NULL END,
            id_almacen = CASE
                WHEN v_limpiar_almacen THEN NULL
                ELSE COALESCE(p_id_almacen_destino, p_id_almacen_origen, id_almacen)
            END,
            id_usuario_modificacion = p_id_usuario_auditoria,
            fecha_modificacion = NOW()
        WHERE id = p_id_balon AND estado = 1;
    END IF;

    -- Si el movimiento del balón también mueve gas, se refleja en pro_stock del gas.
    v_stock_anterior := NULL;
    v_stock_nuevo := NULL;
    IF p_id_producto IS NOT NULL AND v_cantidad > 0 THEN
        DECLARE
            v_id_almacen_gas INTEGER;
        BEGIN
            v_id_almacen_gas := COALESCE(
                CASE WHEN v_es_salida THEN p_id_almacen_origen ELSE p_id_almacen_destino END,
                p_id_almacen_origen, p_id_almacen_destino, v_id_almacen_balon
            );

            IF v_id_almacen_gas IS NOT NULL THEN
                SELECT id, stock INTO v_id_stock, v_stock_anterior
                FROM pro_stock
                WHERE id_almacen = v_id_almacen_gas AND id_producto = p_id_producto AND estado = 1
                FOR UPDATE;

                IF v_id_stock IS NULL THEN
                    INSERT INTO pro_stock (id_almacen, id_producto, stock, stock_minimo, id_usuario_creacion, id_usuario_modificacion)
                    VALUES (v_id_almacen_gas, p_id_producto, 0, 0, p_id_usuario_auditoria, p_id_usuario_auditoria)
                    RETURNING id, stock INTO v_id_stock, v_stock_anterior;
                END IF;

                IF v_es_salida THEN
                    v_stock_nuevo := v_stock_anterior - v_cantidad;
                ELSE
                    v_stock_nuevo := v_stock_anterior + v_cantidad;
                END IF;

                IF v_stock_nuevo < 0 THEN
                    RETURN json_build_object('error', 'Stock de gas insuficiente para registrar la salida', 'registro', NULL);
                END IF;

                UPDATE pro_stock
                SET stock = v_stock_nuevo, id_usuario_modificacion = p_id_usuario_auditoria, fecha_modificacion = NOW()
                WHERE id = v_id_stock;
            END IF;
        END;
    END IF;

    SELECT id_unidad_medida INTO v_id_unidad_medida FROM pro_producto WHERE id = p_id_producto;

    INSERT INTO inv_movimiento (
        fecha, id_tipo_movimiento, naturaleza, id_producto, id_balon, cantidad, id_unidad_medida,
        id_almacen_origen, id_almacen_destino, id_cliente,
        id_documento_origen, id_tipo_documento_origen, id_movimiento_padre,
        stock_anterior, stock_nuevo, id_estado_balon_snapshot, glosa,
        id_usuario_creacion, id_usuario_modificacion
    )
    VALUES (
        COALESCE(p_fecha, NOW()), v_id_tipo_mov, 'BALON', p_id_producto, p_id_balon, v_cantidad, v_id_unidad_medida,
        p_id_almacen_origen, p_id_almacen_destino, COALESCE(v_cliente_destino, p_id_cliente),
        p_id_documento_origen, v_id_tipo_doc, p_id_movimiento_padre,
        v_stock_anterior, v_stock_nuevo, v_id_estado_balon, p_glosa,
        p_id_usuario_auditoria, p_id_usuario_auditoria
    )
    RETURNING id INTO v_id;

    RETURN (inv_obtener_movimiento(v_id)::JSONB || jsonb_build_object('creado', TRUE))::JSON;
END;
$$;


--
-- Name: inv_repuntar_documento(character varying, integer, character varying, integer, character varying, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.inv_repuntar_documento(p_codigo_tipo_documento_origen_actual character varying, p_id_documento_origen_actual integer, p_codigo_tipo_documento_origen_nuevo character varying, p_id_documento_origen_nuevo integer, p_glosa character varying DEFAULT NULL::character varying, p_id_usuario_auditoria integer DEFAULT NULL::integer) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_id_tipo_doc_actual INTEGER;
    v_id_tipo_doc_nuevo INTEGER;
    v_count INTEGER;
BEGIN
    SET TIME ZONE 'America/Lima';

    IF p_id_documento_origen_actual IS NULL OR p_id_documento_origen_nuevo IS NULL THEN
        RETURN json_build_object('error', 'Documento origen actual y nuevo son obligatorios', 'repuntados', 0);
    END IF;

    SELECT lo.id INTO v_id_tipo_doc_actual
    FROM gen_lista_opciones lo
    INNER JOIN gen_lista l ON l.id = lo.id_lista
    WHERE l.nombre = 'TipoDocumentoRef'
      AND lo.nombre = UPPER(TRIM(COALESCE(p_codigo_tipo_documento_origen_actual, '')))
      AND lo.estado = 1
    LIMIT 1;

    SELECT lo.id INTO v_id_tipo_doc_nuevo
    FROM gen_lista_opciones lo
    INNER JOIN gen_lista l ON l.id = lo.id_lista
    WHERE l.nombre = 'TipoDocumentoRef'
      AND lo.nombre = UPPER(TRIM(COALESCE(p_codigo_tipo_documento_origen_nuevo, '')))
      AND lo.estado = 1
    LIMIT 1;

    IF v_id_tipo_doc_actual IS NULL OR v_id_tipo_doc_nuevo IS NULL THEN
        RETURN json_build_object('error', 'Tipo de documento origen no configurado', 'repuntados', 0);
    END IF;

    UPDATE inv_movimiento
    SET id_documento_origen = p_id_documento_origen_nuevo,
        id_tipo_documento_origen = v_id_tipo_doc_nuevo,
        glosa = COALESCE(NULLIF(TRIM(p_glosa), ''), glosa),
        id_usuario_modificacion = p_id_usuario_auditoria,
        fecha_modificacion = NOW()
    WHERE id_tipo_documento_origen = v_id_tipo_doc_actual
      AND id_documento_origen = p_id_documento_origen_actual
      AND estado = 1;

    GET DIAGNOSTICS v_count = ROW_COUNT;

    RETURN json_build_object('repuntados', v_count);
END;
$$;


--
-- Name: inv_revertir_por_documento(character varying, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.inv_revertir_por_documento(p_codigo_tipo_documento_origen character varying, p_id_documento_origen integer, p_id_usuario_auditoria integer DEFAULT NULL::integer) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_id_tipo_doc INTEGER;
    v_id_estado_en_almacen INTEGER;
    v_mov RECORD;
    v_nombre_tipo_mov VARCHAR;
    v_es_salida BOOLEAN;
    v_es_traslado BOOLEAN;
    v_id_stock INTEGER;
    v_stock_actual NUMERIC(12,4);
    v_stock_revertido NUMERIC(12,4);
    v_id_almacen_stock INTEGER;
    v_count INTEGER := 0;
BEGIN
    SET TIME ZONE 'America/Lima';

    IF p_id_documento_origen IS NULL THEN
        RETURN json_build_object('revertidos', 0, 'error', 'id_documento_origen es obligatorio');
    END IF;

    SELECT lo.id INTO v_id_tipo_doc
    FROM gen_lista_opciones lo
    INNER JOIN gen_lista l ON l.id = lo.id_lista
    WHERE l.nombre = 'TipoDocumentoRef'
      AND lo.nombre = UPPER(TRIM(COALESCE(p_codigo_tipo_documento_origen, '')))
      AND lo.estado = 1
    LIMIT 1;

    IF v_id_tipo_doc IS NULL THEN
        RETURN json_build_object(
            'revertidos', 0,
            'error', format('Tipo de documento origen %s no configurado', UPPER(TRIM(COALESCE(p_codigo_tipo_documento_origen, ''))))
        );
    END IF;

    FOR v_mov IN
        SELECT * FROM inv_movimiento
        WHERE estado = 1
          AND id_tipo_documento_origen = v_id_tipo_doc
          AND id_documento_origen = p_id_documento_origen
        ORDER BY id
        FOR UPDATE
    LOOP
        SELECT nombre INTO v_nombre_tipo_mov FROM gen_lista_opciones WHERE id = v_mov.id_tipo_movimiento;
        v_es_salida := (v_mov.stock_nuevo IS NOT NULL AND v_mov.stock_anterior IS NOT NULL AND v_mov.stock_nuevo < v_mov.stock_anterior)
                       OR (v_nombre_tipo_mov ILIKE '%SALIDA%');
        v_es_traslado := (v_mov.naturaleza = 'PRODUCTO' AND UPPER(COALESCE(v_nombre_tipo_mov, '')) = 'TRASLADO');
        IF v_es_traslado THEN
            v_es_salida := TRUE;
        END IF;

        -- Revertir stock (producto, o gas cargado por un movimiento de balón).
        IF v_mov.id_producto IS NOT NULL AND v_mov.stock_anterior IS NOT NULL AND v_mov.stock_nuevo IS NOT NULL THEN
            -- PRODUCTO siempre mueve el almacén origen. BALON+gas puede haber movido el destino
            -- (p.ej. ENTRADA_LLENADO), según la misma resolución que usó inv_registrar_movimiento.
            IF v_mov.naturaleza = 'PRODUCTO' THEN
                v_id_almacen_stock := v_mov.id_almacen_origen;
            ELSE
                v_id_almacen_stock := COALESCE(
                    CASE WHEN v_es_salida THEN v_mov.id_almacen_origen ELSE v_mov.id_almacen_destino END,
                    v_mov.id_almacen_origen,
                    v_mov.id_almacen_destino
                );
            END IF;

            SELECT id, stock INTO v_id_stock, v_stock_actual
            FROM pro_stock
            WHERE id_almacen = v_id_almacen_stock AND id_producto = v_mov.id_producto AND estado = 1
            FOR UPDATE;

            IF v_id_stock IS NOT NULL THEN
                v_stock_revertido := v_stock_actual + (CASE WHEN v_es_salida THEN v_mov.cantidad ELSE -v_mov.cantidad END);
                IF v_stock_revertido >= 0 THEN
                    UPDATE pro_stock
                    SET stock = v_stock_revertido, id_usuario_modificacion = p_id_usuario_auditoria, fecha_modificacion = NOW()
                    WHERE id = v_id_stock;
                END IF;
            END IF;

            IF v_es_traslado AND v_mov.id_almacen_destino IS NOT NULL THEN
                SELECT id, stock INTO v_id_stock, v_stock_actual
                FROM pro_stock
                WHERE id_almacen = v_mov.id_almacen_destino AND id_producto = v_mov.id_producto AND estado = 1
                FOR UPDATE;

                IF v_id_stock IS NOT NULL THEN
                    v_stock_revertido := v_stock_actual - v_mov.cantidad;
                    IF v_stock_revertido >= 0 THEN
                        UPDATE pro_stock
                        SET stock = v_stock_revertido, id_usuario_modificacion = p_id_usuario_auditoria, fecha_modificacion = NOW()
                        WHERE id = v_id_stock;
                    END IF;
                END IF;
            END IF;
        END IF;

        -- Revertir custodia de balón a EN_ALMACEN.
        IF v_mov.naturaleza = 'BALON' AND v_mov.id_balon IS NOT NULL THEN
            SELECT lo.id INTO v_id_estado_en_almacen
            FROM gen_lista_opciones lo
            INNER JOIN gen_lista l ON l.id = lo.id_lista
            WHERE l.nombre = 'EstadoBalon' AND lo.nombre = 'EN_ALMACEN' AND lo.estado = 1
            LIMIT 1;

            IF v_id_estado_en_almacen IS NOT NULL THEN
                UPDATE bal_balon
                SET
                    id_estado_balon = v_id_estado_en_almacen,
                    id_cliente_ubicacion = NULL,
                    id_almacen = COALESCE(v_mov.id_almacen_origen, v_mov.id_almacen_destino, id_almacen),
                    id_usuario_modificacion = p_id_usuario_auditoria,
                    fecha_modificacion = NOW()
                WHERE id = v_mov.id_balon AND estado = 1;
            END IF;
        END IF;

        UPDATE inv_movimiento
        SET estado = 0, id_usuario_modificacion = p_id_usuario_auditoria, fecha_modificacion = NOW()
        WHERE id = v_mov.id;

        v_count := v_count + 1;
    END LOOP;

    RETURN json_build_object('revertidos', v_count);
END;
$$;


--
-- Name: inv_saldo_gas(integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.inv_saldo_gas(p_id_producto_gas integer, p_id_almacen integer) RETURNS numeric
    LANGUAGE plpgsql STABLE
    AS $$
BEGIN
    RETURN inv_stock_producto(p_id_producto_gas, p_id_almacen);
END;
$$;


--
-- Name: inv_stock_producto(integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.inv_stock_producto(p_id_producto integer, p_id_almacen integer) RETURNS numeric
    LANGUAGE plpgsql STABLE
    AS $$
DECLARE
    v_stock NUMERIC(12,4);
BEGIN
    SELECT stock INTO v_stock
    FROM pro_stock
    WHERE id_producto = p_id_producto AND id_almacen = p_id_almacen AND estado = 1;

    RETURN COALESCE(v_stock, 0);
END;
$$;


--
-- Name: pro_actualizar_catalogo_precio(integer, integer, character varying, character varying, integer, integer, integer, character varying, character varying, numeric, integer, character varying, numeric, numeric, numeric, numeric, numeric, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.pro_actualizar_catalogo_precio(p_id integer, p_id_tipo_catalogo integer DEFAULT NULL::integer, p_periodo character varying DEFAULT NULL::character varying, p_nombre_item character varying DEFAULT NULL::character varying, p_id_producto integer DEFAULT NULL::integer, p_id_tipo_balon integer DEFAULT NULL::integer, p_id_proveedor integer DEFAULT NULL::integer, p_clasificacion character varying DEFAULT NULL::character varying, p_modelo character varying DEFAULT NULL::character varying, p_capacidad numeric DEFAULT NULL::numeric, p_id_unidad_medida integer DEFAULT NULL::integer, p_descripcion_presentacion character varying DEFAULT NULL::character varying, p_costo_producto numeric DEFAULT NULL::numeric, p_costo_flete numeric DEFAULT NULL::numeric, p_porcentaje_margen numeric DEFAULT NULL::numeric, p_precio_final numeric DEFAULT NULL::numeric, p_precio_garantia numeric DEFAULT NULL::numeric, p_id_usuario_auditoria integer DEFAULT NULL::integer) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_nombre_item VARCHAR;
BEGIN
    SET TIME ZONE 'America/Lima';

    v_nombre_item := NULLIF(TRIM(p_nombre_item), '');

    IF p_id_tipo_catalogo IS NOT NULL AND NOT EXISTS (
        SELECT 1 FROM gen_lista_opciones WHERE id = p_id_tipo_catalogo AND estado = 1
    ) THEN
        RETURN json_build_object('error', 'El tipo de catálogo indicado no existe o está inactivo', 'registro', NULL);
    END IF;

    IF p_id_producto IS NOT NULL AND NOT EXISTS (
        SELECT 1 FROM pro_producto WHERE id = p_id_producto AND estado = 1
    ) THEN
        RETURN json_build_object('error', 'El producto indicado no existe o está inactivo', 'registro', NULL);
    END IF;

    IF p_id_tipo_balon IS NOT NULL AND NOT EXISTS (
        SELECT 1 FROM bal_tipo_balon WHERE id = p_id_tipo_balon AND estado = 1
    ) THEN
        RETURN json_build_object('error', 'El tipo de balón indicado no existe o está inactivo', 'registro', NULL);
    END IF;

    IF p_id_proveedor IS NOT NULL AND NOT EXISTS (
        SELECT 1 FROM cli_clientes WHERE id = p_id_proveedor AND estado = 1
    ) THEN
        RETURN json_build_object('error', 'El proveedor indicado no existe o está inactivo', 'registro', NULL);
    END IF;

    UPDATE pro_catalogo_precio
    SET
        id_tipo_catalogo = COALESCE(p_id_tipo_catalogo, id_tipo_catalogo),
        periodo = COALESCE(p_periodo, periodo),
        nombre_item = COALESCE(v_nombre_item, nombre_item),
        id_producto = COALESCE(p_id_producto, id_producto),
        id_tipo_balon = COALESCE(p_id_tipo_balon, id_tipo_balon),
        id_proveedor = COALESCE(p_id_proveedor, id_proveedor),
        clasificacion = COALESCE(p_clasificacion, clasificacion),
        modelo = COALESCE(p_modelo, modelo),
        capacidad = COALESCE(p_capacidad, capacidad),
        id_unidad_medida = COALESCE(p_id_unidad_medida, id_unidad_medida),
        descripcion_presentacion = COALESCE(p_descripcion_presentacion, descripcion_presentacion),
        costo_producto = COALESCE(p_costo_producto, costo_producto),
        costo_flete = COALESCE(p_costo_flete, costo_flete),
        porcentaje_margen = COALESCE(p_porcentaje_margen, porcentaje_margen),
        precio_final = COALESCE(p_precio_final, precio_final),
        precio_garantia = COALESCE(p_precio_garantia, precio_garantia),
        id_usuario_modificacion = p_id_usuario_auditoria,
        fecha_modificacion = NOW()
    WHERE id = p_id AND estado = 1;

    IF NOT FOUND THEN
        RETURN json_build_object('registro', NULL);
    END IF;

    RETURN pro_obtener_catalogo_precio(p_id);
END;
$$;


--
-- Name: pro_actualizar_categoria(integer, character varying, character varying, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.pro_actualizar_categoria(p_id integer, p_nombre character varying DEFAULT NULL::character varying, p_descripcion character varying DEFAULT NULL::character varying, p_id_usuario_auditoria integer DEFAULT NULL::integer) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_nombre VARCHAR;
BEGIN
    SET TIME ZONE 'America/Lima';

    v_nombre := NULLIF(TRIM(p_nombre), '');

    IF v_nombre IS NOT NULL AND EXISTS (
        SELECT 1 FROM pro_categoria
        WHERE estado = 1
          AND LOWER(TRIM(nombre)) = LOWER(v_nombre)
          AND id <> p_id
    ) THEN
        RETURN json_build_object('error', 'Ya existe otra categoría activa con el nombre ' || v_nombre, 'registro', NULL);
    END IF;

    UPDATE pro_categoria
    SET
        nombre = COALESCE(v_nombre, nombre),
        descripcion = COALESCE(p_descripcion, descripcion),
        id_usuario_modificacion = p_id_usuario_auditoria,
        fecha_modificacion = NOW()
    WHERE id = p_id AND estado = 1;

    IF NOT FOUND THEN
        RETURN json_build_object('registro', NULL);
    END IF;

    RETURN pro_obtener_categoria(p_id);
END;
$$;


--
-- Name: pro_actualizar_movimiento(integer, date, character varying, integer, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.pro_actualizar_movimiento(p_id integer, p_fecha date DEFAULT NULL::date, p_glosa character varying DEFAULT NULL::character varying, p_id_documento_ref integer DEFAULT NULL::integer, p_id_tipo_documento_ref integer DEFAULT NULL::integer, p_id_usuario_auditoria integer DEFAULT NULL::integer) RETURNS json
    LANGUAGE plpgsql
    AS $$
BEGIN
    SET TIME ZONE 'America/Lima';

    UPDATE pro_movimientos
    SET
        fecha = COALESCE(p_fecha, fecha),
        glosa = COALESCE(p_glosa, glosa),
        id_documento_ref = COALESCE(p_id_documento_ref, id_documento_ref),
        id_tipo_documento_ref = COALESCE(p_id_tipo_documento_ref, id_tipo_documento_ref),
        id_usuario_modificacion = p_id_usuario_auditoria,
        fecha_modificacion = NOW()
    WHERE id = p_id AND estado = 1;

    IF NOT FOUND THEN
        RETURN json_build_object('registro', NULL);
    END IF;

    RETURN pro_obtener_movimiento(p_id);
END;
$$;


--
-- Name: pro_actualizar_producto(integer, character varying, character varying, character varying, integer, integer, character varying, character varying, boolean, boolean, boolean, boolean, numeric, character varying, integer, numeric, numeric, numeric, numeric, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.pro_actualizar_producto(p_id integer, p_codigo character varying DEFAULT NULL::character varying, p_codigo_barra character varying DEFAULT NULL::character varying, p_nombre character varying DEFAULT NULL::character varying, p_id_sub_categoria integer DEFAULT NULL::integer, p_id_unidad_medida integer DEFAULT NULL::integer, p_marca character varying DEFAULT NULL::character varying, p_presentacion character varying DEFAULT NULL::character varying, p_es_gas boolean DEFAULT NULL::boolean, p_es_servicio boolean DEFAULT NULL::boolean, p_es_alquilable boolean DEFAULT NULL::boolean, p_afecta_stock boolean DEFAULT NULL::boolean, p_precio numeric DEFAULT NULL::numeric, p_codigo_ubicacion character varying DEFAULT NULL::character varying, p_id_usuario_auditoria integer DEFAULT NULL::integer, p_precio_compra numeric DEFAULT NULL::numeric, p_precio_garantia numeric DEFAULT NULL::numeric, p_factor_kg_m3 numeric DEFAULT NULL::numeric, p_factor_lb_m3 numeric DEFAULT NULL::numeric, p_es_mantenimiento boolean DEFAULT NULL::boolean) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_codigo VARCHAR;
    v_nombre VARCHAR;
    v_codigo_ubicacion VARCHAR;
    v_es_alquilable BOOLEAN;
BEGIN
    SET TIME ZONE 'America/Lima';

    v_codigo := NULLIF(TRIM(p_codigo), '');
    v_nombre := NULLIF(TRIM(p_nombre), '');
    v_codigo_ubicacion := CASE
        WHEN p_codigo_ubicacion IS NULL THEN NULL
        ELSE NULLIF(TRIM(p_codigo_ubicacion), '')
    END;

    IF v_codigo IS NOT NULL AND EXISTS (
        SELECT 1 FROM pro_producto
        WHERE LOWER(TRIM(codigo)) = LOWER(v_codigo)
          AND id <> p_id
    ) THEN
        RETURN json_build_object('error', 'Ya existe otro producto con el código ' || v_codigo, 'registro', NULL);
    END IF;

    IF p_codigo_ubicacion IS NOT NULL
       AND v_codigo_ubicacion IS NOT NULL
       AND EXISTS (
           SELECT 1 FROM pro_producto
           WHERE LOWER(TRIM(codigo_ubicacion)) = LOWER(v_codigo_ubicacion)
             AND id <> p_id
       ) THEN
        RETURN json_build_object(
            'error', 'Ya existe otro producto con el código de ubicación ' || v_codigo_ubicacion,
            'registro', NULL
        );
    END IF;

    IF p_id_sub_categoria IS NOT NULL AND NOT EXISTS (
        SELECT 1 FROM pro_sub_categoria WHERE id = p_id_sub_categoria AND estado = 1
    ) THEN
        RETURN json_build_object('error', 'La subcategoría indicada no existe o está inactiva', 'registro', NULL);
    END IF;

    IF p_id_unidad_medida IS NOT NULL AND NOT EXISTS (
        SELECT 1 FROM gen_lista_opciones WHERE id = p_id_unidad_medida AND estado = 1
    ) THEN
        RETURN json_build_object('error', 'La unidad de medida indicada no existe o está inactiva', 'registro', NULL);
    END IF;

    IF p_factor_kg_m3 IS NOT NULL AND p_factor_kg_m3 <= 0 THEN
        RETURN json_build_object('error', 'El factor kg→m³ debe ser mayor a 0', 'registro', NULL);
    END IF;

    IF p_factor_lb_m3 IS NOT NULL AND p_factor_lb_m3 <= 0 THEN
        RETURN json_build_object('error', 'El factor lb→m³ debe ser mayor a 0', 'registro', NULL);
    END IF;

    SELECT COALESCE(p_es_alquilable, es_alquilable)
    INTO v_es_alquilable
    FROM pro_producto
    WHERE id = p_id AND estado = 1;

    IF NOT FOUND THEN
        RETURN json_build_object('registro', NULL);
    END IF;

    UPDATE pro_producto
    SET
        codigo = COALESCE(v_codigo, codigo),
        codigo_barra = COALESCE(p_codigo_barra, codigo_barra),
        codigo_ubicacion = CASE
            WHEN p_codigo_ubicacion IS NULL THEN codigo_ubicacion
            ELSE v_codigo_ubicacion
        END,
        nombre = COALESCE(v_nombre, nombre),
        id_sub_categoria = COALESCE(p_id_sub_categoria, id_sub_categoria),
        id_unidad_medida = COALESCE(p_id_unidad_medida, id_unidad_medida),
        marca = COALESCE(p_marca, marca),
        presentacion = COALESCE(p_presentacion, presentacion),
        es_gas = COALESCE(p_es_gas, es_gas),
        es_servicio = COALESCE(p_es_servicio, es_servicio),
        es_alquilable = v_es_alquilable,
        es_mantenimiento = CASE
            WHEN COALESCE(p_es_servicio, es_servicio)
                 AND NOT COALESCE(p_es_gas, es_gas)
                 AND NOT v_es_alquilable
            THEN COALESCE(p_es_mantenimiento, es_mantenimiento)
            ELSE FALSE
        END,
        afecta_stock = CASE
            WHEN COALESCE(p_es_gas, es_gas) OR COALESCE(p_es_servicio, es_servicio) THEN FALSE
            ELSE COALESCE(p_afecta_stock, afecta_stock)
        END,
        precio = COALESCE(p_precio, precio),
        precio_compra = COALESCE(p_precio_compra, precio_compra),
        precio_garantia = COALESCE(p_precio_garantia, precio_garantia),
        factor_kg_m3 = CASE
            WHEN COALESCE(p_es_gas, es_gas) THEN COALESCE(p_factor_kg_m3, factor_kg_m3)
            ELSE NULL
        END,
        factor_lb_m3 = CASE
            WHEN COALESCE(p_es_gas, es_gas) THEN COALESCE(p_factor_lb_m3, factor_lb_m3)
            ELSE NULL
        END,
        id_usuario_modificacion = p_id_usuario_auditoria,
        fecha_modificacion = NOW()
    WHERE id = p_id AND estado = 1;

    PERFORM pro_asegurar_stock_producto(p_id, p_id_usuario_auditoria);

    RETURN pro_obtener_producto(p_id);
END;
$$;


--
-- Name: pro_actualizar_producto_imagen(integer, integer, boolean, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.pro_actualizar_producto_imagen(p_id integer, p_orden integer DEFAULT NULL::integer, p_es_principal boolean DEFAULT NULL::boolean, p_id_archivo integer DEFAULT NULL::integer, p_id_usuario_auditoria integer DEFAULT NULL::integer) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_id_producto INTEGER;
BEGIN
    SET TIME ZONE 'America/Lima';

    SELECT id_producto INTO v_id_producto
    FROM pro_producto_imagen
    WHERE id = p_id AND estado = 1;

    IF v_id_producto IS NULL THEN
        RETURN json_build_object('registro', NULL);
    END IF;

    IF p_id_archivo IS NOT NULL
       AND NOT EXISTS (SELECT 1 FROM gen_archivo WHERE id = p_id_archivo AND estado = 1) THEN
        RETURN json_build_object('error', 'Archivo no encontrado o inactivo', 'registro', NULL);
    END IF;

    IF p_es_principal = TRUE THEN
        UPDATE pro_producto_imagen
        SET es_principal = FALSE,
            id_usuario_modificacion = p_id_usuario_auditoria,
            fecha_modificacion = NOW()
        WHERE id_producto = v_id_producto
          AND estado = 1
          AND id <> p_id
          AND es_principal = TRUE;
    END IF;

    UPDATE pro_producto_imagen
    SET
        orden = COALESCE(p_orden, orden),
        es_principal = COALESCE(p_es_principal, es_principal),
        id_archivo = COALESCE(p_id_archivo, id_archivo),
        id_usuario_modificacion = p_id_usuario_auditoria,
        fecha_modificacion = NOW()
    WHERE id = p_id AND estado = 1;

    RETURN pro_obtener_producto_imagen(p_id);
END;
$$;


--
-- Name: pro_actualizar_stock(integer, numeric, numeric, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.pro_actualizar_stock(p_id integer, p_stock numeric DEFAULT NULL::numeric, p_stock_minimo numeric DEFAULT NULL::numeric, p_id_usuario_auditoria integer DEFAULT NULL::integer) RETURNS json
    LANGUAGE plpgsql
    AS $_$
DECLARE
    v_id_producto INTEGER;
    v_nombre_unidad VARCHAR;
    v_es_gas BOOLEAN;
BEGIN
    SET TIME ZONE 'America/Lima';

    -- La cantidad solo cambia por movimientos de inventario.
    IF p_stock IS NOT NULL THEN
        RETURN json_build_object(
            'error',
            'La cantidad de stock solo se modifica con movimientos (ingreso, salida o ajuste). Aquí solo puedes cambiar el stock mínimo.',
            'registro',
            NULL
        );
    END IF;

    IF p_stock_minimo IS NOT NULL AND p_stock_minimo < 0 THEN
        RETURN json_build_object('error', 'El stock mínimo no puede ser negativo', 'registro', NULL);
    END IF;

    SELECT s.id_producto
    INTO v_id_producto
    FROM pro_stock s
    WHERE s.id = p_id AND s.estado = 1;

    IF v_id_producto IS NULL THEN
        RETURN json_build_object('registro', NULL);
    END IF;

    SELECT
        REGEXP_REPLACE(UPPER(TRIM(COALESCE(um.nombre, ''))), '\.+$', ''),
        COALESCE(p.es_gas, FALSE)
    INTO v_nombre_unidad, v_es_gas
    FROM pro_producto p
    LEFT JOIN gen_lista_opciones um ON um.id = p.id_unidad_medida
    WHERE p.id = v_id_producto;

    IF NOT COALESCE(v_es_gas, FALSE)
       AND v_nombre_unidad IN ('UNID', 'NIU', 'UND', 'UNI', 'UNIDAD', 'UNIDADES', 'PZ', 'PZA', 'PIEZA', 'PIEZAS')
    THEN
        IF p_stock_minimo IS NOT NULL AND p_stock_minimo <> TRUNC(p_stock_minimo) THEN
            RETURN json_build_object(
                'error',
                'El stock mínimo debe ser entero (unidad de medida UNID)',
                'registro',
                NULL
            );
        END IF;
    END IF;

    UPDATE pro_stock
    SET
        stock_minimo = COALESCE(p_stock_minimo, stock_minimo),
        id_usuario_modificacion = p_id_usuario_auditoria,
        fecha_modificacion = NOW()
    WHERE id = p_id AND estado = 1;

    IF NOT FOUND THEN
        RETURN json_build_object('registro', NULL);
    END IF;

    RETURN pro_obtener_stock(p_id);
END;
$_$;


--
-- Name: pro_actualizar_sub_categoria(integer, integer, character varying, character varying, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.pro_actualizar_sub_categoria(p_id integer, p_id_categoria integer DEFAULT NULL::integer, p_nombre character varying DEFAULT NULL::character varying, p_descripcion character varying DEFAULT NULL::character varying, p_id_usuario_auditoria integer DEFAULT NULL::integer) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_nombre VARCHAR;
    v_id_categoria INTEGER;
BEGIN
    SET TIME ZONE 'America/Lima';

    v_nombre := NULLIF(TRIM(p_nombre), '');

    SELECT COALESCE(p_id_categoria, id_categoria) INTO v_id_categoria
    FROM pro_sub_categoria
    WHERE id = p_id AND estado = 1;

    IF v_id_categoria IS NULL THEN
        RETURN json_build_object('registro', NULL);
    END IF;

    IF p_id_categoria IS NOT NULL AND NOT EXISTS (
        SELECT 1 FROM pro_categoria WHERE id = p_id_categoria AND estado = 1
    ) THEN
        RETURN json_build_object('error', 'La categoría indicada no existe o está inactiva', 'registro', NULL);
    END IF;

    IF v_nombre IS NOT NULL AND EXISTS (
        SELECT 1 FROM pro_sub_categoria
        WHERE estado = 1
          AND id_categoria = v_id_categoria
          AND LOWER(TRIM(nombre)) = LOWER(v_nombre)
          AND id <> p_id
    ) THEN
        RETURN json_build_object('error', 'Ya existe otra subcategoría activa con el nombre ' || v_nombre || ' en esta categoría', 'registro', NULL);
    END IF;

    UPDATE pro_sub_categoria
    SET
        id_categoria = COALESCE(p_id_categoria, id_categoria),
        nombre = COALESCE(v_nombre, nombre),
        descripcion = COALESCE(p_descripcion, descripcion),
        id_usuario_modificacion = p_id_usuario_auditoria,
        fecha_modificacion = NOW()
    WHERE id = p_id AND estado = 1;

    IF NOT FOUND THEN
        RETURN json_build_object('registro', NULL);
    END IF;

    RETURN pro_obtener_sub_categoria(p_id);
END;
$$;


--
-- Name: pro_asegurar_stock_producto(integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.pro_asegurar_stock_producto(p_id_producto integer, p_id_usuario_auditoria integer DEFAULT NULL::integer) RETURNS void
    LANGUAGE plpgsql
    AS $$
BEGIN
    SET TIME ZONE 'America/Lima';

    IF p_id_producto IS NULL THEN
        RETURN;
    END IF;

    -- Cualquier producto con afecta_stock (accesorios y, desde Fase 1, también gas). Nunca servicios.
    IF NOT EXISTS (
        SELECT 1
        FROM pro_producto p
        WHERE p.id = p_id_producto
          AND p.estado = 1
          AND COALESCE(p.afecta_stock, FALSE) = TRUE
          AND COALESCE(p.es_servicio, FALSE) = FALSE
    ) THEN
        RETURN;
    END IF;

    -- Reactivar filas inactivas (UNIQUE id_almacen + id_producto).
    UPDATE pro_stock s
    SET
        estado = 1,
        stock = CASE WHEN s.estado = 0 THEN 0 ELSE s.stock END,
        id_usuario_modificacion = p_id_usuario_auditoria,
        fecha_modificacion = NOW()
    FROM gen_almacen a
    WHERE s.id_almacen = a.id
      AND s.id_producto = p_id_producto
      AND a.estado = 1
      AND s.estado = 0;

    INSERT INTO pro_stock (
        id_almacen,
        id_producto,
        stock,
        stock_minimo,
        id_usuario_creacion,
        id_usuario_modificacion
    )
    SELECT
        a.id,
        p_id_producto,
        0,
        0,
        p_id_usuario_auditoria,
        p_id_usuario_auditoria
    FROM gen_almacen a
    WHERE a.estado = 1
      AND NOT EXISTS (
          SELECT 1
          FROM pro_stock s
          WHERE s.id_almacen = a.id
            AND s.id_producto = p_id_producto
      );
END;
$$;


--
-- Name: pro_crear_catalogo_precio(integer, character varying, character varying, integer, integer, integer, character varying, character varying, numeric, integer, character varying, numeric, numeric, numeric, numeric, numeric, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.pro_crear_catalogo_precio(p_id_tipo_catalogo integer, p_nombre_item character varying, p_periodo character varying DEFAULT NULL::character varying, p_id_producto integer DEFAULT NULL::integer, p_id_tipo_balon integer DEFAULT NULL::integer, p_id_proveedor integer DEFAULT NULL::integer, p_clasificacion character varying DEFAULT NULL::character varying, p_modelo character varying DEFAULT NULL::character varying, p_capacidad numeric DEFAULT NULL::numeric, p_id_unidad_medida integer DEFAULT NULL::integer, p_descripcion_presentacion character varying DEFAULT NULL::character varying, p_costo_producto numeric DEFAULT 0, p_costo_flete numeric DEFAULT 0, p_porcentaje_margen numeric DEFAULT NULL::numeric, p_precio_final numeric DEFAULT NULL::numeric, p_precio_garantia numeric DEFAULT NULL::numeric, p_id_usuario_auditoria integer DEFAULT NULL::integer) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_id INTEGER;
BEGIN
    SET TIME ZONE 'America/Lima';

    IF p_nombre_item IS NULL OR TRIM(p_nombre_item) = '' THEN
        RETURN json_build_object('error', 'El nombre del ítem es obligatorio', 'registro', NULL);
    END IF;

    IF NOT EXISTS (
        SELECT 1 FROM gen_lista_opciones WHERE id = p_id_tipo_catalogo AND estado = 1
    ) THEN
        RETURN json_build_object('error', 'El tipo de catálogo indicado no existe o está inactivo', 'registro', NULL);
    END IF;

    IF p_id_producto IS NOT NULL AND NOT EXISTS (
        SELECT 1 FROM pro_producto WHERE id = p_id_producto AND estado = 1
    ) THEN
        RETURN json_build_object('error', 'El producto indicado no existe o está inactivo', 'registro', NULL);
    END IF;

    IF p_id_tipo_balon IS NOT NULL AND NOT EXISTS (
        SELECT 1 FROM bal_tipo_balon WHERE id = p_id_tipo_balon AND estado = 1
    ) THEN
        RETURN json_build_object('error', 'El tipo de balón indicado no existe o está inactivo', 'registro', NULL);
    END IF;

    IF p_id_proveedor IS NOT NULL AND NOT EXISTS (
        SELECT 1 FROM cli_clientes WHERE id = p_id_proveedor AND estado = 1
    ) THEN
        RETURN json_build_object('error', 'El proveedor indicado no existe o está inactivo', 'registro', NULL);
    END IF;

    INSERT INTO pro_catalogo_precio (
        id_tipo_catalogo,
        periodo,
        nombre_item,
        id_producto,
        id_tipo_balon,
        id_proveedor,
        clasificacion,
        modelo,
        capacidad,
        id_unidad_medida,
        descripcion_presentacion,
        costo_producto,
        costo_flete,
        porcentaje_margen,
        precio_final,
        precio_garantia,
        id_usuario_creacion,
        id_usuario_modificacion
    )
    VALUES (
        p_id_tipo_catalogo,
        p_periodo,
        TRIM(p_nombre_item),
        p_id_producto,
        p_id_tipo_balon,
        p_id_proveedor,
        p_clasificacion,
        p_modelo,
        p_capacidad,
        p_id_unidad_medida,
        p_descripcion_presentacion,
        COALESCE(p_costo_producto, 0),
        COALESCE(p_costo_flete, 0),
        p_porcentaje_margen,
        p_precio_final,
        p_precio_garantia,
        p_id_usuario_auditoria,
        p_id_usuario_auditoria
    )
    RETURNING id INTO v_id;

    RETURN pro_obtener_catalogo_precio(v_id);
END;
$$;


--
-- Name: pro_crear_categoria(character varying, character varying, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.pro_crear_categoria(p_nombre character varying, p_descripcion character varying DEFAULT NULL::character varying, p_id_usuario_auditoria integer DEFAULT NULL::integer) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_id INTEGER;
BEGIN
    SET TIME ZONE 'America/Lima';

    IF p_nombre IS NULL OR TRIM(p_nombre) = '' THEN
        RETURN json_build_object('error', 'El nombre de la categoría es obligatorio', 'registro', NULL);
    END IF;

    IF EXISTS (
        SELECT 1 FROM pro_categoria
        WHERE estado = 1 AND LOWER(TRIM(nombre)) = LOWER(TRIM(p_nombre))
    ) THEN
        RETURN json_build_object('error', 'Ya existe una categoría activa con el nombre ' || TRIM(p_nombre), 'registro', NULL);
    END IF;

    INSERT INTO pro_categoria (
        nombre,
        descripcion,
        id_usuario_creacion,
        id_usuario_modificacion
    )
    VALUES (
        TRIM(p_nombre),
        p_descripcion,
        p_id_usuario_auditoria,
        p_id_usuario_auditoria
    )
    RETURNING id INTO v_id;

    RETURN pro_obtener_categoria(v_id);
END;
$$;


--
-- Name: pro_crear_movimiento(date, integer, integer, integer, numeric, integer, integer, character varying, integer, boolean, integer, character varying); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.pro_crear_movimiento(p_fecha date, p_id_producto integer, p_id_almacen integer, p_id_tipo_movimiento integer, p_cantidad numeric, p_id_documento_ref integer DEFAULT NULL::integer, p_id_tipo_documento_ref integer DEFAULT NULL::integer, p_glosa character varying DEFAULT NULL::character varying, p_id_usuario_auditoria integer DEFAULT NULL::integer, p_forzar_ajuste_stock boolean DEFAULT false, p_id_almacen_destino integer DEFAULT NULL::integer, p_sentido_ajuste character varying DEFAULT NULL::character varying) RETURNS json
    LANGUAGE plpgsql
    AS $_$
DECLARE
    v_id INTEGER;
    v_id_stock INTEGER;
    v_id_stock_dest INTEGER;
    v_stock_anterior NUMERIC(12,4);
    v_stock_nuevo NUMERIC(12,4);
    v_stock_dest_ant NUMERIC(12,4);
    v_cantidad NUMERIC(12,4);
    v_afecta_stock BOOLEAN;
    v_nombre_tipo_movimiento VARCHAR;
    v_es_salida BOOLEAN;
    v_es_traslado BOOLEAN;
    v_nombre_unidad VARCHAR;
    v_es_gas BOOLEAN;
BEGIN
    SET TIME ZONE 'America/Lima';

    IF p_fecha IS NULL THEN
        RETURN json_build_object('error', 'La fecha del movimiento es obligatoria', 'registro', NULL);
    END IF;

    IF p_cantidad IS NULL OR p_cantidad <= 0 THEN
        RETURN json_build_object('error', 'La cantidad debe ser mayor a cero', 'registro', NULL);
    END IF;

    IF NOT EXISTS (SELECT 1 FROM pro_producto WHERE id = p_id_producto AND estado = 1) THEN
        RETURN json_build_object('error', 'El producto indicado no existe o está inactivo', 'registro', NULL);
    END IF;

    IF NOT EXISTS (SELECT 1 FROM gen_almacen WHERE id = p_id_almacen AND estado = 1) THEN
        RETURN json_build_object('error', 'El almacén indicado no existe o está inactivo', 'registro', NULL);
    END IF;

    IF NOT EXISTS (SELECT 1 FROM gen_lista_opciones WHERE id = p_id_tipo_movimiento AND estado = 1) THEN
        RETURN json_build_object('error', 'El tipo de movimiento indicado no existe o está inactivo', 'registro', NULL);
    END IF;

    SELECT
        COALESCE(p.afecta_stock, FALSE),
        REGEXP_REPLACE(UPPER(TRIM(COALESCE(um.nombre, ''))), '\.+$', ''),
        COALESCE(p.es_gas, FALSE)
    INTO v_afecta_stock, v_nombre_unidad, v_es_gas
    FROM pro_producto p
    LEFT JOIN gen_lista_opciones um ON um.id = p.id_unidad_medida
    WHERE p.id = p_id_producto;

    IF COALESCE(p_forzar_ajuste_stock, FALSE) THEN
        v_afecta_stock := TRUE;
    END IF;

    IF NOT COALESCE(v_es_gas, FALSE)
       AND v_nombre_unidad IN ('UNID', 'NIU', 'UND', 'UNI', 'UNIDAD', 'UNIDADES', 'PZ', 'PZA', 'PIEZA', 'PIEZAS')
       AND p_cantidad <> TRUNC(p_cantidad)
    THEN
        RETURN json_build_object(
            'error', 'La cantidad debe ser entera (unidad de medida UNID)',
            'registro', NULL
        );
    END IF;

    SELECT nombre INTO v_nombre_tipo_movimiento
    FROM gen_lista_opciones
    WHERE id = p_id_tipo_movimiento;

    v_cantidad := ABS(p_cantidad);
    v_es_traslado := UPPER(COALESCE(v_nombre_tipo_movimiento, '')) = 'TRASLADO';
    v_es_salida := v_nombre_tipo_movimiento ILIKE '%SALIDA%';

    IF UPPER(COALESCE(v_nombre_tipo_movimiento, '')) = 'AJUSTE'
       AND UPPER(TRIM(COALESCE(p_sentido_ajuste, ''))) = 'MENOS'
    THEN
        v_es_salida := TRUE;
    END IF;

    IF v_es_traslado THEN
        IF p_id_almacen_destino IS NULL THEN
            RETURN json_build_object('error', 'El traslado requiere almacén de destino', 'registro', NULL);
        END IF;
        IF p_id_almacen_destino = p_id_almacen THEN
            RETURN json_build_object('error', 'El almacén de destino debe ser distinto al de origen', 'registro', NULL);
        END IF;
        IF NOT EXISTS (SELECT 1 FROM gen_almacen WHERE id = p_id_almacen_destino AND estado = 1) THEN
            RETURN json_build_object('error', 'El almacén de destino no existe o está inactivo', 'registro', NULL);
        END IF;
        v_es_salida := TRUE;
    END IF;

    v_stock_anterior := 0;
    v_stock_nuevo := 0;

    IF v_afecta_stock THEN
        SELECT id, stock INTO v_id_stock, v_stock_anterior
        FROM pro_stock
        WHERE id_almacen = p_id_almacen
          AND id_producto = p_id_producto
          AND estado = 1
        FOR UPDATE;

        IF v_id_stock IS NULL THEN
            INSERT INTO pro_stock (
                id_almacen, id_producto, stock, stock_minimo,
                id_usuario_creacion, id_usuario_modificacion
            )
            VALUES (
                p_id_almacen, p_id_producto, 0, 0,
                p_id_usuario_auditoria, p_id_usuario_auditoria
            )
            RETURNING id, stock INTO v_id_stock, v_stock_anterior;
        END IF;

        IF v_es_salida THEN
            v_stock_nuevo := v_stock_anterior - v_cantidad;
        ELSE
            v_stock_nuevo := v_stock_anterior + v_cantidad;
        END IF;

        IF v_stock_nuevo < 0 THEN
            RETURN json_build_object('error', 'Stock insuficiente para registrar la salida', 'registro', NULL);
        END IF;

        UPDATE pro_stock
        SET stock = v_stock_nuevo,
            id_usuario_modificacion = p_id_usuario_auditoria,
            fecha_modificacion = NOW()
        WHERE id = v_id_stock;

        IF v_es_traslado THEN
            SELECT id, stock INTO v_id_stock_dest, v_stock_dest_ant
            FROM pro_stock
            WHERE id_almacen = p_id_almacen_destino
              AND id_producto = p_id_producto
              AND estado = 1
            FOR UPDATE;

            IF v_id_stock_dest IS NULL THEN
                INSERT INTO pro_stock (
                    id_almacen, id_producto, stock, stock_minimo,
                    id_usuario_creacion, id_usuario_modificacion
                )
                VALUES (
                    p_id_almacen_destino, p_id_producto, 0, 0,
                    p_id_usuario_auditoria, p_id_usuario_auditoria
                )
                RETURNING id, stock INTO v_id_stock_dest, v_stock_dest_ant;
            END IF;

            UPDATE pro_stock
            SET stock = COALESCE(v_stock_dest_ant, 0) + v_cantidad,
                id_usuario_modificacion = p_id_usuario_auditoria,
                fecha_modificacion = NOW()
            WHERE id = v_id_stock_dest;
        END IF;
    END IF;

    INSERT INTO pro_movimientos (
        fecha, id_producto, id_almacen, id_tipo_movimiento, cantidad,
        stock_anterior, stock_nuevo, id_documento_ref, id_tipo_documento_ref,
        glosa, id_almacen_destino,
        id_usuario_creacion, id_usuario_modificacion
    )
    VALUES (
        p_fecha, p_id_producto, p_id_almacen, p_id_tipo_movimiento, v_cantidad,
        CASE WHEN v_afecta_stock THEN v_stock_anterior ELSE NULL END,
        CASE WHEN v_afecta_stock THEN v_stock_nuevo ELSE NULL END,
        p_id_documento_ref, p_id_tipo_documento_ref, p_glosa, p_id_almacen_destino,
        p_id_usuario_auditoria, p_id_usuario_auditoria
    )
    RETURNING id INTO v_id;

    RETURN pro_obtener_movimiento(v_id);
END;
$_$;


--
-- Name: pro_crear_producto(character varying, character varying, integer, character varying, integer, character varying, character varying, boolean, boolean, boolean, boolean, numeric, character varying, integer, numeric, numeric, numeric, numeric, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.pro_crear_producto(p_codigo character varying, p_nombre character varying, p_id_sub_categoria integer DEFAULT NULL::integer, p_codigo_barra character varying DEFAULT NULL::character varying, p_id_unidad_medida integer DEFAULT NULL::integer, p_marca character varying DEFAULT NULL::character varying, p_presentacion character varying DEFAULT NULL::character varying, p_es_gas boolean DEFAULT false, p_es_servicio boolean DEFAULT false, p_es_alquilable boolean DEFAULT false, p_afecta_stock boolean DEFAULT true, p_precio numeric DEFAULT 0, p_codigo_ubicacion character varying DEFAULT NULL::character varying, p_id_usuario_auditoria integer DEFAULT NULL::integer, p_precio_compra numeric DEFAULT 0, p_precio_garantia numeric DEFAULT 0, p_factor_kg_m3 numeric DEFAULT NULL::numeric, p_factor_lb_m3 numeric DEFAULT NULL::numeric, p_es_mantenimiento boolean DEFAULT false) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_id INTEGER;
    v_codigo_ubicacion VARCHAR;
    v_es_alquilable BOOLEAN;
BEGIN
    SET TIME ZONE 'America/Lima';

    IF p_codigo IS NULL OR TRIM(p_codigo) = '' THEN
        RETURN json_build_object('error', 'El código del producto es obligatorio', 'registro', NULL);
    END IF;

    IF p_nombre IS NULL OR TRIM(p_nombre) = '' THEN
        RETURN json_build_object('error', 'El nombre del producto es obligatorio', 'registro', NULL);
    END IF;

    IF EXISTS (
        SELECT 1 FROM pro_producto
        WHERE LOWER(TRIM(codigo)) = LOWER(TRIM(p_codigo))
    ) THEN
        RETURN json_build_object('error', 'Ya existe un producto con el código ' || TRIM(p_codigo), 'registro', NULL);
    END IF;

    v_codigo_ubicacion := NULLIF(TRIM(p_codigo_ubicacion), '');
    v_es_alquilable := COALESCE(p_es_alquilable, FALSE);

    IF v_codigo_ubicacion IS NOT NULL AND EXISTS (
        SELECT 1 FROM pro_producto
        WHERE LOWER(TRIM(codigo_ubicacion)) = LOWER(v_codigo_ubicacion)
    ) THEN
        RETURN json_build_object(
            'error', 'Ya existe un producto con el código de ubicación ' || v_codigo_ubicacion,
            'registro', NULL
        );
    END IF;

    IF p_id_sub_categoria IS NOT NULL AND NOT EXISTS (
        SELECT 1 FROM pro_sub_categoria WHERE id = p_id_sub_categoria AND estado = 1
    ) THEN
        RETURN json_build_object('error', 'La subcategoría indicada no existe o está inactiva', 'registro', NULL);
    END IF;

    IF p_id_unidad_medida IS NOT NULL AND NOT EXISTS (
        SELECT 1 FROM gen_lista_opciones WHERE id = p_id_unidad_medida AND estado = 1
    ) THEN
        RETURN json_build_object('error', 'La unidad de medida indicada no existe o está inactiva', 'registro', NULL);
    END IF;

    IF p_factor_kg_m3 IS NOT NULL AND p_factor_kg_m3 <= 0 THEN
        RETURN json_build_object('error', 'El factor kg→m³ debe ser mayor a 0', 'registro', NULL);
    END IF;

    IF p_factor_lb_m3 IS NOT NULL AND p_factor_lb_m3 <= 0 THEN
        RETURN json_build_object('error', 'El factor lb→m³ debe ser mayor a 0', 'registro', NULL);
    END IF;

    INSERT INTO pro_producto (
        codigo,
        codigo_barra,
        codigo_ubicacion,
        nombre,
        id_sub_categoria,
        id_unidad_medida,
        marca,
        presentacion,
        es_gas,
        es_servicio,
        es_alquilable,
        es_mantenimiento,
        afecta_stock,
        precio,
        precio_compra,
        precio_garantia,
        factor_kg_m3,
        factor_lb_m3,
        id_usuario_creacion,
        id_usuario_modificacion
    )
    VALUES (
        TRIM(p_codigo),
        p_codigo_barra,
        v_codigo_ubicacion,
        TRIM(p_nombre),
        p_id_sub_categoria,
        p_id_unidad_medida,
        p_marca,
        p_presentacion,
        COALESCE(p_es_gas, FALSE),
        COALESCE(p_es_servicio, FALSE),
        v_es_alquilable,
        CASE
            WHEN COALESCE(p_es_servicio, FALSE)
                 AND NOT COALESCE(p_es_gas, FALSE)
                 AND NOT v_es_alquilable
            THEN COALESCE(p_es_mantenimiento, FALSE)
            ELSE FALSE
        END,
        CASE
            WHEN COALESCE(p_es_gas, FALSE) OR COALESCE(p_es_servicio, FALSE) THEN FALSE
            ELSE COALESCE(p_afecta_stock, TRUE)
        END,
        COALESCE(p_precio, 0),
        COALESCE(p_precio_compra, 0),
        COALESCE(p_precio_garantia, 0),
        CASE WHEN COALESCE(p_es_gas, FALSE) THEN p_factor_kg_m3 ELSE NULL END,
        CASE WHEN COALESCE(p_es_gas, FALSE) THEN p_factor_lb_m3 ELSE NULL END,
        p_id_usuario_auditoria,
        p_id_usuario_auditoria
    )
    RETURNING id INTO v_id;

    PERFORM pro_asegurar_stock_producto(v_id, p_id_usuario_auditoria);

    RETURN pro_obtener_producto(v_id);
END;
$$;


--
-- Name: pro_crear_producto_imagen(integer, integer, integer, boolean, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.pro_crear_producto_imagen(p_id_producto integer, p_id_archivo integer, p_orden integer DEFAULT NULL::integer, p_es_principal boolean DEFAULT false, p_id_usuario_auditoria integer DEFAULT NULL::integer) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_id INTEGER;
    v_orden INTEGER;
    v_es_principal BOOLEAN;
BEGIN
    SET TIME ZONE 'America/Lima';

    IF p_id_producto IS NULL THEN
        RETURN json_build_object('error', 'El id_producto es obligatorio', 'registro', NULL);
    END IF;

    IF NOT EXISTS (SELECT 1 FROM pro_producto WHERE id = p_id_producto AND estado = 1) THEN
        RETURN json_build_object('error', 'Producto no encontrado o inactivo', 'registro', NULL);
    END IF;

    IF p_id_archivo IS NULL THEN
        RETURN json_build_object('error', 'El id_archivo es obligatorio', 'registro', NULL);
    END IF;

    IF NOT EXISTS (SELECT 1 FROM gen_archivo WHERE id = p_id_archivo AND estado = 1) THEN
        RETURN json_build_object('error', 'Archivo no encontrado o inactivo', 'registro', NULL);
    END IF;

    IF p_orden IS NULL THEN
        SELECT COALESCE(MAX(orden), -1) + 1 INTO v_orden
        FROM pro_producto_imagen
        WHERE id_producto = p_id_producto AND estado = 1;
    ELSE
        v_orden := p_orden;
    END IF;

    v_es_principal := COALESCE(p_es_principal, FALSE);

    -- Si es la primera imagen del producto, marcarla como principal
    IF v_es_principal = FALSE
       AND NOT EXISTS (
           SELECT 1 FROM pro_producto_imagen
           WHERE id_producto = p_id_producto AND estado = 1
       ) THEN
        v_es_principal := TRUE;
    END IF;

    IF v_es_principal = TRUE THEN
        UPDATE pro_producto_imagen
        SET es_principal = FALSE,
            id_usuario_modificacion = p_id_usuario_auditoria,
            fecha_modificacion = NOW()
        WHERE id_producto = p_id_producto
          AND estado = 1
          AND es_principal = TRUE;
    END IF;

    INSERT INTO pro_producto_imagen (
        id_producto,
        id_archivo,
        orden,
        es_principal,
        id_usuario_creacion,
        id_usuario_modificacion
    )
    VALUES (
        p_id_producto,
        p_id_archivo,
        v_orden,
        v_es_principal,
        p_id_usuario_auditoria,
        p_id_usuario_auditoria
    )
    RETURNING id INTO v_id;

    RETURN pro_obtener_producto_imagen(v_id);
END;
$$;


--
-- Name: pro_crear_stock(integer, integer, numeric, numeric, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.pro_crear_stock(p_id_almacen integer, p_id_producto integer, p_stock numeric DEFAULT 0, p_stock_minimo numeric DEFAULT 0, p_id_usuario_auditoria integer DEFAULT NULL::integer) RETURNS json
    LANGUAGE plpgsql
    AS $_$
DECLARE
    v_id INTEGER;
    v_id_inactivo INTEGER;
    v_nombre_unidad VARCHAR;
    v_es_gas BOOLEAN;
BEGIN
    SET TIME ZONE 'America/Lima';

    IF NOT EXISTS (
        SELECT 1 FROM gen_almacen WHERE id = p_id_almacen AND estado = 1
    ) THEN
        RETURN json_build_object('error', 'El almacén indicado no existe o está inactivo', 'registro', NULL);
    END IF;

    IF NOT EXISTS (
        SELECT 1 FROM pro_producto WHERE id = p_id_producto AND estado = 1
    ) THEN
        RETURN json_build_object('error', 'El producto indicado no existe o está inactivo', 'registro', NULL);
    END IF;

    IF EXISTS (
        SELECT 1 FROM pro_stock
        WHERE id_almacen = p_id_almacen
          AND id_producto = p_id_producto
          AND estado = 1
    ) THEN
        RETURN json_build_object(
            'error',
            'Ya existe un registro de stock activo para este producto en el almacén',
            'registro',
            NULL
        );
    END IF;

    IF COALESCE(p_stock, 0) < 0 OR COALESCE(p_stock_minimo, 0) < 0 THEN
        RETURN json_build_object('error', 'El stock y el stock mínimo no pueden ser negativos', 'registro', NULL);
    END IF;

    SELECT
        REGEXP_REPLACE(UPPER(TRIM(COALESCE(um.nombre, ''))), '\.+$', ''),
        COALESCE(p.es_gas, FALSE)
    INTO v_nombre_unidad, v_es_gas
    FROM pro_producto p
    LEFT JOIN gen_lista_opciones um ON um.id = p.id_unidad_medida
    WHERE p.id = p_id_producto;

    -- Gases (m³) pueden ser decimales aunque la U.M. esté mal catalogada como UNID.
    IF NOT COALESCE(v_es_gas, FALSE)
       AND v_nombre_unidad IN ('UNID', 'NIU', 'UND', 'UNI', 'UNIDAD', 'UNIDADES', 'PZ', 'PZA', 'PIEZA', 'PIEZAS')
    THEN
        IF COALESCE(p_stock, 0) <> TRUNC(COALESCE(p_stock, 0)) THEN
            RETURN json_build_object(
                'error',
                'El stock debe ser entero (unidad de medida UNID)',
                'registro',
                NULL
            );
        END IF;
        IF COALESCE(p_stock_minimo, 0) <> TRUNC(COALESCE(p_stock_minimo, 0)) THEN
            RETURN json_build_object(
                'error',
                'El stock mínimo debe ser entero (unidad de medida UNID)',
                'registro',
                NULL
            );
        END IF;
    END IF;

    -- Si hubo baja lógica previa, UNIQUE(id_almacen, id_producto) bloquea el INSERT:
    -- reactivar y actualizar cantidades.
    SELECT id
    INTO v_id_inactivo
    FROM pro_stock
    WHERE id_almacen = p_id_almacen
      AND id_producto = p_id_producto
      AND estado = 0
    LIMIT 1;

    IF v_id_inactivo IS NOT NULL THEN
        UPDATE pro_stock
        SET
            stock = COALESCE(p_stock, 0),
            stock_minimo = COALESCE(p_stock_minimo, 0),
            estado = 1,
            id_usuario_modificacion = p_id_usuario_auditoria,
            fecha_modificacion = NOW()
        WHERE id = v_id_inactivo;

        RETURN pro_obtener_stock(v_id_inactivo);
    END IF;

    INSERT INTO pro_stock (
        id_almacen,
        id_producto,
        stock,
        stock_minimo,
        id_usuario_creacion,
        id_usuario_modificacion
    )
    VALUES (
        p_id_almacen,
        p_id_producto,
        COALESCE(p_stock, 0),
        COALESCE(p_stock_minimo, 0),
        p_id_usuario_auditoria,
        p_id_usuario_auditoria
    )
    RETURNING id INTO v_id;

    RETURN pro_obtener_stock(v_id);
END;
$_$;


--
-- Name: pro_crear_sub_categoria(integer, character varying, character varying, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.pro_crear_sub_categoria(p_id_categoria integer, p_nombre character varying, p_descripcion character varying DEFAULT NULL::character varying, p_id_usuario_auditoria integer DEFAULT NULL::integer) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_id INTEGER;
BEGIN
    SET TIME ZONE 'America/Lima';

    IF p_nombre IS NULL OR TRIM(p_nombre) = '' THEN
        RETURN json_build_object('error', 'El nombre de la subcategoría es obligatorio', 'registro', NULL);
    END IF;

    IF NOT EXISTS (
        SELECT 1 FROM pro_categoria WHERE id = p_id_categoria AND estado = 1
    ) THEN
        RETURN json_build_object('error', 'La categoría indicada no existe o está inactiva', 'registro', NULL);
    END IF;

    IF EXISTS (
        SELECT 1 FROM pro_sub_categoria
        WHERE estado = 1
          AND id_categoria = p_id_categoria
          AND LOWER(TRIM(nombre)) = LOWER(TRIM(p_nombre))
    ) THEN
        RETURN json_build_object('error', 'Ya existe una subcategoría activa con el nombre ' || TRIM(p_nombre) || ' en esta categoría', 'registro', NULL);
    END IF;

    INSERT INTO pro_sub_categoria (
        id_categoria,
        nombre,
        descripcion,
        id_usuario_creacion,
        id_usuario_modificacion
    )
    VALUES (
        p_id_categoria,
        TRIM(p_nombre),
        p_descripcion,
        p_id_usuario_auditoria,
        p_id_usuario_auditoria
    )
    RETURNING id INTO v_id;

    RETURN pro_obtener_sub_categoria(v_id);
END;
$$;


--
-- Name: pro_crear_traslado_lote(date, integer, integer, jsonb, character varying, integer, integer, character varying); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.pro_crear_traslado_lote(p_fecha date, p_id_almacen integer, p_id_almacen_destino integer, p_detalles jsonb, p_glosa character varying DEFAULT NULL::character varying, p_id_usuario_auditoria integer DEFAULT NULL::integer, p_id_documento_ref integer DEFAULT NULL::integer, p_codigo_documento_ref character varying DEFAULT NULL::character varying) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_detalle JSONB;
    v_result JSON;
    v_registros JSONB := '[]'::JSONB;
    v_id_producto INTEGER;
    v_cantidad NUMERIC;
    v_total INTEGER := 0;
BEGIN
    SET TIME ZONE 'America/Lima';

    IF p_fecha IS NULL THEN
        RETURN json_build_object('error', 'La fecha del traslado es obligatoria', 'registros', NULL);
    END IF;

    IF p_detalles IS NULL
       OR jsonb_typeof(p_detalles) <> 'array'
       OR jsonb_array_length(p_detalles) = 0
    THEN
        RETURN json_build_object('error', 'Los detalles del traslado son obligatorios', 'registros', NULL);
    END IF;

    IF p_id_almacen IS NULL OR p_id_almacen_destino IS NULL THEN
        RETURN json_build_object('error', 'Almacén origen y destino son obligatorios', 'registros', NULL);
    END IF;

    IF p_id_almacen = p_id_almacen_destino THEN
        RETURN json_build_object(
            'error', 'El almacén de destino debe ser distinto al de origen',
            'registros', NULL
        );
    END IF;

    IF NOT EXISTS (SELECT 1 FROM gen_almacen WHERE id = p_id_almacen AND estado = 1) THEN
        RETURN json_build_object('error', 'El almacén de origen no existe o está inactivo', 'registros', NULL);
    END IF;

    IF NOT EXISTS (SELECT 1 FROM gen_almacen WHERE id = p_id_almacen_destino AND estado = 1) THEN
        RETURN json_build_object('error', 'El almacén de destino no existe o está inactivo', 'registros', NULL);
    END IF;

    FOR v_detalle IN SELECT * FROM jsonb_array_elements(p_detalles)
    LOOP
        v_id_producto := NULLIF(TRIM(COALESCE(v_detalle->>'idProducto', '')), '')::INTEGER;
        v_cantidad := NULLIF(TRIM(COALESCE(v_detalle->>'cantidad', '')), '')::NUMERIC;

        IF v_id_producto IS NULL OR v_cantidad IS NULL OR v_cantidad <= 0 THEN
            RAISE EXCEPTION 'Cada detalle debe incluir idProducto y cantidad mayor a cero';
        END IF;

        v_result := inv_registrar_movimiento(
            p_naturaleza                => 'PRODUCTO',
            p_codigo_tipo_movimiento    => 'TRASLADO',
            p_fecha                     => p_fecha,
            p_id_producto               => v_id_producto,
            p_cantidad                  => v_cantidad,
            p_id_almacen_origen         => p_id_almacen,
            p_id_almacen_destino        => p_id_almacen_destino,
            p_codigo_tipo_documento_origen => p_codigo_documento_ref,
            p_id_documento_origen       => p_id_documento_ref,
            p_glosa                     => p_glosa,
            p_id_usuario_auditoria      => p_id_usuario_auditoria
        );

        IF v_result->>'error' IS NOT NULL THEN
            RAISE EXCEPTION '%', v_result->>'error';
        END IF;

        v_registros := v_registros || jsonb_build_array(v_result->'registro');
        v_total := v_total + 1;
    END LOOP;

    RETURN json_build_object(
        'error', NULL,
        'registros', v_registros,
        'total', v_total
    );
END;
$$;


--
-- Name: pro_eliminar_catalogo_precio(integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.pro_eliminar_catalogo_precio(p_id integer, p_id_usuario_auditoria integer DEFAULT NULL::integer) RETURNS json
    LANGUAGE plpgsql
    AS $$
BEGIN
    SET TIME ZONE 'America/Lima';

    UPDATE pro_catalogo_precio
    SET estado = 0,
        id_usuario_modificacion = p_id_usuario_auditoria,
        fecha_modificacion = NOW()
    WHERE id = p_id AND estado = 1;

    IF NOT FOUND THEN
        RETURN json_build_object('eliminado', FALSE, 'id', p_id);
    END IF;

    RETURN json_build_object('eliminado', TRUE, 'id', p_id);
END;
$$;


