CREATE FUNCTION public.pro_etiqueta_producto(p_id integer) RETURNS text
    LANGUAGE sql STABLE
    AS $$
    SELECT COALESCE(
        NULLIF(
            TRIM(CONCAT_WS(
                ' — ',
                NULLIF(TRIM(p.codigo), ''),
                NULLIF(TRIM(p.nombre), '')
            )),
            ''
        ),
        'Producto #' || p_id
    )
    FROM pro_producto p
    WHERE p.id = p_id;
$$;


--
-- Name: pro_generar_codigo_producto(character varying); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.pro_generar_codigo_producto(p_prefijo character varying DEFAULT 'PRO'::character varying) RETURNS json
    LANGUAGE plpgsql
    AS $_$
DECLARE
    v_prefijo VARCHAR(10);
    v_siguiente INTEGER;
    v_codigo VARCHAR(30);
BEGIN
    SET TIME ZONE 'America/Lima';

    v_prefijo := UPPER(TRIM(COALESCE(NULLIF(TRIM(p_prefijo), ''), 'PRO')));
    v_prefijo := regexp_replace(v_prefijo, '[^A-Z0-9]', '', 'g');

    IF v_prefijo IS NULL OR LENGTH(v_prefijo) < 2 THEN
        v_prefijo := 'PRO';
    ELSIF LENGTH(v_prefijo) > 10 THEN
        v_prefijo := LEFT(v_prefijo, 10);
    END IF;

    SELECT COALESCE(
        MAX(
            CASE
                WHEN UPPER(TRIM(codigo)) ~ ('^' || v_prefijo || '-[0-9]+$')
                    THEN NULLIF(regexp_replace(UPPER(TRIM(codigo)), '^.*-', ''), '')::INTEGER
                ELSE NULL
            END
        ),
        0
    ) + 1
    INTO v_siguiente
    FROM pro_producto;

    v_codigo := v_prefijo || '-' || LPAD(v_siguiente::TEXT, GREATEST(3, LENGTH(v_siguiente::TEXT)), '0');

    IF EXISTS (
        SELECT 1
        FROM pro_producto
        WHERE LOWER(TRIM(codigo)) = LOWER(v_codigo)
    ) THEN
        RETURN json_build_object(
            'error', 'Ya existe un producto con el código ' || v_codigo,
            'registro', NULL
        );
    END IF;

    RETURN json_build_object(
        'registro', json_build_object('codigo', v_codigo)
    );
END;
$_$;


--
-- Name: pro_generar_codigo_ubicacion(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.pro_generar_codigo_ubicacion() RETURNS json
    LANGUAGE plpgsql
    AS $_$
DECLARE
    v_siguiente INTEGER;
    v_codigo VARCHAR(20);
BEGIN
    SET TIME ZONE 'America/Lima';

    SELECT COALESCE(MAX(codigo_ubicacion::INTEGER), 0) + 1
    INTO v_siguiente
    FROM pro_producto
    WHERE codigo_ubicacion ~ '^\d+$';

    v_codigo := LPAD(v_siguiente::TEXT, GREATEST(4, LENGTH(v_siguiente::TEXT)), '0');

    RETURN json_build_object(
        'registro', json_build_object('codigo_ubicacion', v_codigo)
    );
END;
$_$;


--
-- Name: pro_generar_codigo_ubicacion(character varying, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.pro_generar_codigo_ubicacion(p_prefijo character varying DEFAULT NULL::character varying, p_id_producto integer DEFAULT NULL::integer) RETURNS json
    LANGUAGE plpgsql
    AS $_$
DECLARE
    v_prefijo VARCHAR(17);
    v_siguiente INTEGER;
    v_codigo VARCHAR(20);
    v_actualizado INTEGER;
BEGIN
    SET TIME ZONE 'America/Lima';

    v_prefijo := UPPER(TRIM(COALESCE(p_prefijo, '')));
    v_prefijo := regexp_replace(v_prefijo, '[^A-Z0-9\-]', '', 'g');
    v_prefijo := regexp_replace(v_prefijo, '-+', '-', 'g');
    v_prefijo := TRIM(BOTH '-' FROM v_prefijo);

    IF v_prefijo IS NULL OR LENGTH(v_prefijo) < 2 THEN
        SELECT COALESCE(MAX(codigo_ubicacion::INTEGER), 0) + 1
        INTO v_siguiente
        FROM pro_producto
        WHERE codigo_ubicacion ~ '^\d+$';

        v_codigo := LPAD(v_siguiente::TEXT, GREATEST(4, LENGTH(v_siguiente::TEXT)), '0');
    ELSE
        IF LENGTH(v_prefijo) > 17 THEN
            v_prefijo := LEFT(v_prefijo, 17);
        END IF;

        SELECT COALESCE(
            MAX(
                CASE
                    WHEN codigo_ubicacion ~ ('^' || v_prefijo || '-[0-9]+$')
                        THEN NULLIF(regexp_replace(codigo_ubicacion, '^.*-', ''), '')::INTEGER
                    ELSE NULL
                END
            ),
            0
        ) + 1
        INTO v_siguiente
        FROM pro_producto;

        v_codigo := v_prefijo || '-' || LPAD(v_siguiente::TEXT, 2, '0');

        IF LENGTH(v_codigo) > 20 THEN
            RETURN json_build_object(
                'error', 'El código de ubicación generado supera el máximo permitido'
            );
        END IF;
    END IF;

    IF EXISTS (
        SELECT 1
        FROM pro_producto
        WHERE LOWER(TRIM(codigo_ubicacion)) = LOWER(v_codigo)
          AND (p_id_producto IS NULL OR id <> p_id_producto)
    ) THEN
        RETURN json_build_object(
            'error', 'Ya existe un producto con el código de ubicación ' || v_codigo
        );
    END IF;

    IF p_id_producto IS NOT NULL THEN
        UPDATE pro_producto
        SET
            codigo_ubicacion = v_codigo,
            fecha_modificacion = NOW()
        WHERE id = p_id_producto;

        GET DIAGNOSTICS v_actualizado = ROW_COUNT;

        IF v_actualizado = 0 THEN
            RETURN json_build_object(
                'error', 'Producto ' || p_id_producto || ' no encontrado'
            );
        END IF;
    END IF;

    RETURN json_build_object(
        'registro', json_build_object('codigo_ubicacion', v_codigo)
    );
END;
$_$;


--
-- Name: pro_listar_catalogo_precios(character varying, integer, integer, integer, integer, integer, character varying); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.pro_listar_catalogo_precios(p_busqueda character varying DEFAULT ''::character varying, p_limite integer DEFAULT 10, p_offset integer DEFAULT 0, p_id_tipo_catalogo integer DEFAULT NULL::integer, p_id_producto integer DEFAULT NULL::integer, p_id_proveedor integer DEFAULT NULL::integer, p_periodo character varying DEFAULT NULL::character varying) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_registros JSON;
    v_total BIGINT;
BEGIN
    SET TIME ZONE 'America/Lima';

    SELECT COUNT(*) INTO v_total
    FROM pro_catalogo_precio cp
    LEFT JOIN gen_lista_opciones tc ON cp.id_tipo_catalogo = tc.id
    LEFT JOIN pro_producto p ON cp.id_producto = p.id
    LEFT JOIN cli_clientes prov ON cp.id_proveedor = prov.id
    WHERE cp.estado = 1
      AND (p_id_tipo_catalogo IS NULL OR cp.id_tipo_catalogo = p_id_tipo_catalogo)
      AND (p_id_producto IS NULL OR cp.id_producto = p_id_producto)
      AND (p_id_proveedor IS NULL OR cp.id_proveedor = p_id_proveedor)
      AND (p_periodo IS NULL OR cp.periodo = p_periodo)
      AND (
          p_busqueda = ''
          OR gen_texto_coincide(cp.nombre_item, p_busqueda)
          OR gen_texto_coincide(COALESCE(cp.periodo, ''), p_busqueda)
          OR gen_texto_coincide(COALESCE(cp.clasificacion, ''), p_busqueda)
          OR gen_texto_coincide(COALESCE(cp.modelo, ''), p_busqueda)
          OR gen_texto_coincide(COALESCE(p.nombre, ''), p_busqueda)
          OR gen_texto_coincide(COALESCE(prov.razon_social, ''), p_busqueda)
          OR gen_texto_coincide(COALESCE(tc.nombre, ''), p_busqueda)
      );

    SELECT COALESCE(json_agg(row_to_json(t)), '[]'::JSON) INTO v_registros
    FROM (
        SELECT
            cp.id,
            cp.id_tipo_catalogo,
            tc.nombre AS nombre_tipo_catalogo,
            cp.periodo,
            cp.nombre_item,
            cp.id_producto,
            p.codigo AS codigo_producto,
            p.nombre AS nombre_producto,
            cp.id_tipo_balon,
            tb.nombre AS nombre_tipo_balon,
            cp.id_proveedor,
            COALESCE(prov.razon_social, prov.nombres) AS nombre_proveedor,
            cp.clasificacion,
            cp.modelo,
            cp.capacidad,
            cp.id_unidad_medida,
            um.nombre AS nombre_unidad_medida,
            cp.descripcion_presentacion,
            cp.costo_producto,
            cp.costo_flete,
            cp.porcentaje_margen,
            cp.precio_final,
            cp.precio_garantia,
            cp.estado,
            cp.fecha_creacion,
            cp.fecha_modificacion,
            cp.id_usuario_creacion,
            uc.nombre AS nombre_usuario_creacion,
            cp.id_usuario_modificacion,
            um2.nombre AS nombre_usuario_modificacion
        FROM pro_catalogo_precio cp
        LEFT JOIN gen_lista_opciones tc ON cp.id_tipo_catalogo = tc.id
        LEFT JOIN pro_producto p ON cp.id_producto = p.id
        LEFT JOIN bal_tipo_balon tb ON cp.id_tipo_balon = tb.id
        LEFT JOIN cli_clientes prov ON cp.id_proveedor = prov.id
        LEFT JOIN gen_lista_opciones um ON cp.id_unidad_medida = um.id
        LEFT JOIN auth_usuarios uc ON cp.id_usuario_creacion = uc.id
        LEFT JOIN auth_usuarios um2 ON cp.id_usuario_modificacion = um2.id
        WHERE cp.estado = 1
          AND (p_id_tipo_catalogo IS NULL OR cp.id_tipo_catalogo = p_id_tipo_catalogo)
          AND (p_id_producto IS NULL OR cp.id_producto = p_id_producto)
          AND (p_id_proveedor IS NULL OR cp.id_proveedor = p_id_proveedor)
          AND (p_periodo IS NULL OR cp.periodo = p_periodo)
          AND (
              p_busqueda = ''
              OR gen_texto_coincide(cp.nombre_item, p_busqueda)
              OR gen_texto_coincide(COALESCE(cp.periodo, ''), p_busqueda)
              OR gen_texto_coincide(COALESCE(cp.clasificacion, ''), p_busqueda)
              OR gen_texto_coincide(COALESCE(cp.modelo, ''), p_busqueda)
              OR gen_texto_coincide(COALESCE(p.nombre, ''), p_busqueda)
              OR gen_texto_coincide(COALESCE(prov.razon_social, ''), p_busqueda)
              OR gen_texto_coincide(COALESCE(tc.nombre, ''), p_busqueda)
          )
        ORDER BY cp.periodo DESC NULLS LAST, cp.nombre_item ASC
        LIMIT p_limite
        OFFSET p_offset
    ) t;

    RETURN json_build_object('registros', v_registros, 'total', v_total);
END;
$$;


--
-- Name: pro_listar_categorias(character varying, integer, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.pro_listar_categorias(p_busqueda character varying DEFAULT ''::character varying, p_limite integer DEFAULT 10, p_offset integer DEFAULT 0, p_solo_activos integer DEFAULT 1) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_registros JSON;
    v_total BIGINT;
BEGIN
    SET TIME ZONE 'America/Lima';

    SELECT COUNT(*) INTO v_total
    FROM pro_categoria c
    WHERE (p_solo_activos IS NULL OR c.estado = p_solo_activos)
      AND (
          p_busqueda = ''
          OR gen_texto_coincide(c.nombre, p_busqueda)
          OR gen_texto_coincide(COALESCE(c.descripcion, ''), p_busqueda)
      );

    SELECT COALESCE(json_agg(row_to_json(t)), '[]'::JSON) INTO v_registros
    FROM (
        SELECT
            c.id,
            c.nombre,
            c.descripcion,
            c.estado,
            c.fecha_creacion,
            c.fecha_modificacion,
            c.id_usuario_creacion,
            uc.nombre AS nombre_usuario_creacion,
            c.id_usuario_modificacion,
            um.nombre AS nombre_usuario_modificacion,
            (
                SELECT COUNT(*)::INTEGER
                FROM pro_sub_categoria sc
                WHERE sc.id_categoria = c.id AND sc.estado = 1
            ) AS total_sub_categorias,
            (
                SELECT COALESCE(json_agg(sc.nombre ORDER BY sc.nombre ASC), '[]'::JSON)
                FROM pro_sub_categoria sc
                WHERE sc.id_categoria = c.id AND sc.estado = 1
            ) AS nombres_sub_categorias
        FROM pro_categoria c
        LEFT JOIN auth_usuarios uc ON c.id_usuario_creacion = uc.id
        LEFT JOIN auth_usuarios um ON c.id_usuario_modificacion = um.id
        WHERE (p_solo_activos IS NULL OR c.estado = p_solo_activos)
          AND (
              p_busqueda = ''
              OR gen_texto_coincide(c.nombre, p_busqueda)
              OR gen_texto_coincide(COALESCE(c.descripcion, ''), p_busqueda)
          )
        ORDER BY c.nombre ASC
        LIMIT p_limite
        OFFSET p_offset
    ) t;

    RETURN json_build_object('registros', v_registros, 'total', v_total);
END;
$$;


--
-- Name: pro_listar_movimientos(character varying, integer, integer, integer, integer, integer, date, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.pro_listar_movimientos(p_busqueda character varying DEFAULT ''::character varying, p_limite integer DEFAULT 10, p_offset integer DEFAULT 0, p_id_producto integer DEFAULT NULL::integer, p_id_almacen integer DEFAULT NULL::integer, p_id_tipo_movimiento integer DEFAULT NULL::integer, p_fecha_desde date DEFAULT NULL::date, p_fecha_hasta date DEFAULT NULL::date) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_registros JSON;
    v_total BIGINT;
    v_resumen JSON;
BEGIN
    SET TIME ZONE 'America/Lima';

    SELECT
        COUNT(*),
        json_build_object(
            'total', COUNT(*),
            'ingresos', COUNT(*) FILTER (WHERE tm.nombre ILIKE '%INGRESO%'),
            'salidas', COUNT(*) FILTER (WHERE tm.nombre ILIKE '%SALIDA%'),
            'ajustes', COUNT(*) FILTER (WHERE tm.nombre ILIKE '%AJUSTE%')
        )
    INTO v_total, v_resumen
    FROM pro_movimientos m
    INNER JOIN pro_producto p ON m.id_producto = p.id
    INNER JOIN gen_almacen a ON m.id_almacen = a.id
    LEFT JOIN gen_lista_opciones tm ON m.id_tipo_movimiento = tm.id
    WHERE m.estado = 1
      AND (p_id_producto IS NULL OR m.id_producto = p_id_producto)
      AND (p_id_almacen IS NULL OR m.id_almacen = p_id_almacen)
      AND (p_id_tipo_movimiento IS NULL OR m.id_tipo_movimiento = p_id_tipo_movimiento)
      AND (p_fecha_desde IS NULL OR m.fecha >= p_fecha_desde)
      AND (p_fecha_hasta IS NULL OR m.fecha <= p_fecha_hasta)
      AND (
          p_busqueda = ''
          OR gen_texto_coincide(COALESCE(m.glosa, ''), p_busqueda)
          OR gen_texto_coincide(p.codigo, p_busqueda)
          OR gen_texto_coincide(p.nombre, p_busqueda)
          OR gen_texto_coincide(a.nombre, p_busqueda)
          OR gen_texto_coincide(COALESCE(tm.nombre, ''), p_busqueda)
      );

    SELECT COALESCE(json_agg(row_to_json(t)), '[]'::JSON) INTO v_registros
    FROM (
        SELECT
            m.id,
            m.fecha,
            m.id_producto,
            p.codigo AS codigo_producto,
            p.nombre AS nombre_producto,
            p.afecta_stock,
            COALESCE(p.es_gas, FALSE) AS es_gas,
            umed.nombre AS nombre_unidad_medida,
            m.id_almacen,
            a.nombre AS nombre_almacen,
            m.id_almacen_destino,
            adest.nombre AS nombre_almacen_destino,
            m.id_tipo_movimiento,
            tm.nombre AS nombre_tipo_movimiento,
            m.cantidad,
            m.stock_anterior,
            m.stock_nuevo,
            m.id_documento_ref,
            m.id_tipo_documento_ref,
            tdr.nombre AS nombre_tipo_documento_ref,
            m.glosa,
            m.estado,
            CASE
                WHEN m.id_documento_ref IS NOT NULL THEN FALSE
                WHEN NOT COALESCE(p.afecta_stock, FALSE)
                  OR m.stock_anterior IS NULL
                  OR m.stock_nuevo IS NULL
                THEN TRUE
                WHEN st.id IS NULL THEN FALSE
                WHEN tm.nombre ILIKE '%SALIDA%' THEN TRUE
                WHEN COALESCE(st.stock, 0) - m.cantidad < 0 THEN FALSE
                ELSE TRUE
            END AS puede_anular,
            CASE
                WHEN m.id_documento_ref IS NOT NULL THEN 'Vinculado a una venta'
                WHEN NOT COALESCE(p.afecta_stock, FALSE)
                  OR m.stock_anterior IS NULL
                  OR m.stock_nuevo IS NULL
                THEN NULL
                WHEN st.id IS NULL THEN 'Sin registro de stock para revertir'
                WHEN tm.nombre ILIKE '%SALIDA%' THEN NULL
                WHEN COALESCE(st.stock, 0) - m.cantidad < 0 THEN 'Revertiría stock negativo'
                ELSE NULL
            END AS motivo_bloqueo_anulacion,
            m.fecha_creacion,
            m.fecha_modificacion,
            m.id_usuario_creacion,
            uc.nombre AS nombre_usuario_creacion,
            m.id_usuario_modificacion,
            um.nombre AS nombre_usuario_modificacion
        FROM pro_movimientos m
        INNER JOIN pro_producto p ON m.id_producto = p.id
        INNER JOIN gen_almacen a ON m.id_almacen = a.id
        LEFT JOIN gen_almacen adest ON m.id_almacen_destino = adest.id
        LEFT JOIN gen_lista_opciones umed ON umed.id = p.id_unidad_medida
        LEFT JOIN gen_lista_opciones tm ON m.id_tipo_movimiento = tm.id
        LEFT JOIN gen_lista_opciones tdr ON m.id_tipo_documento_ref = tdr.id
        LEFT JOIN auth_usuarios uc ON m.id_usuario_creacion = uc.id
        LEFT JOIN auth_usuarios um ON m.id_usuario_modificacion = um.id
        LEFT JOIN pro_stock st
            ON st.id_almacen = m.id_almacen
           AND st.id_producto = m.id_producto
           AND st.estado = 1
        WHERE m.estado = 1
          AND (p_id_producto IS NULL OR m.id_producto = p_id_producto)
          AND (p_id_almacen IS NULL OR m.id_almacen = p_id_almacen)
          AND (p_id_tipo_movimiento IS NULL OR m.id_tipo_movimiento = p_id_tipo_movimiento)
          AND (p_fecha_desde IS NULL OR m.fecha >= p_fecha_desde)
          AND (p_fecha_hasta IS NULL OR m.fecha <= p_fecha_hasta)
          AND (
              p_busqueda = ''
              OR gen_texto_coincide(COALESCE(m.glosa, ''), p_busqueda)
              OR gen_texto_coincide(p.codigo, p_busqueda)
              OR gen_texto_coincide(p.nombre, p_busqueda)
              OR gen_texto_coincide(a.nombre, p_busqueda)
              OR gen_texto_coincide(COALESCE(tm.nombre, ''), p_busqueda)
          )
        ORDER BY m.fecha DESC, m.id DESC
        LIMIT p_limite
        OFFSET p_offset
    ) t;

    RETURN json_build_object(
        'registros', v_registros,
        'total', v_total,
        'resumen', v_resumen
    );
END;
$$;


--
-- Name: pro_listar_producto_imagenes(integer, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.pro_listar_producto_imagenes(p_id_producto integer, p_limite integer DEFAULT 50, p_offset integer DEFAULT 0) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_registros JSON;
    v_total BIGINT;
BEGIN
    SET TIME ZONE 'America/Lima';

    IF p_id_producto IS NULL THEN
        RETURN json_build_object(
            'error', 'El id_producto es obligatorio',
            'registros', '[]'::JSON,
            'total', 0
        );
    END IF;

    SELECT COUNT(*) INTO v_total
    FROM pro_producto_imagen pi
    WHERE pi.estado = 1
      AND pi.id_producto = p_id_producto;

    SELECT COALESCE(json_agg(row_to_json(t)), '[]'::JSON) INTO v_registros
    FROM (
        SELECT
            pi.id,
            pi.id_producto,
            p.codigo AS codigo_producto,
            p.nombre AS nombre_producto,
            pi.id_archivo,
            a.nombre_original,
            a.nombre_almacenado,
            a.ruta,
            a.bucket,
            a.mime_type,
            a.extension,
            a.tamanio_bytes,
            pi.orden,
            pi.es_principal,
            pi.estado,
            pi.fecha_creacion,
            pi.fecha_modificacion,
            pi.id_usuario_creacion,
            uc.nombre AS nombre_usuario_creacion,
            pi.id_usuario_modificacion,
            um.nombre AS nombre_usuario_modificacion
        FROM pro_producto_imagen pi
        INNER JOIN pro_producto p ON pi.id_producto = p.id
        INNER JOIN gen_archivo a ON pi.id_archivo = a.id
        LEFT JOIN auth_usuarios uc ON pi.id_usuario_creacion = uc.id
        LEFT JOIN auth_usuarios um ON pi.id_usuario_modificacion = um.id
        WHERE pi.estado = 1
          AND pi.id_producto = p_id_producto
        ORDER BY pi.es_principal DESC, pi.orden ASC, pi.id ASC
        LIMIT p_limite
        OFFSET p_offset
    ) t;

    RETURN json_build_object('registros', v_registros, 'total', v_total);
END;
$$;


--
-- Name: pro_listar_productos(character varying, integer, integer, integer, integer, boolean, boolean, boolean, boolean, integer, integer, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.pro_listar_productos(p_busqueda character varying DEFAULT ''::character varying, p_limite integer DEFAULT 10, p_offset integer DEFAULT 0, p_id_sub_categoria integer DEFAULT NULL::integer, p_id_categoria integer DEFAULT NULL::integer, p_es_gas boolean DEFAULT NULL::boolean, p_es_servicio boolean DEFAULT NULL::boolean, p_es_alquilable boolean DEFAULT NULL::boolean, p_afecta_stock boolean DEFAULT NULL::boolean, p_solo_activos integer DEFAULT 1, p_id_almacen integer DEFAULT NULL::integer, p_es_mantenimiento boolean DEFAULT NULL::boolean) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_registros JSON;
    v_total BIGINT;
    v_resumen JSON;
BEGIN
    SET TIME ZONE 'America/Lima';

    SELECT
        COUNT(*),
        json_build_object(
            'total', COUNT(*),
            'accesorios', COUNT(*) FILTER (
                WHERE COALESCE(p.es_gas, FALSE) = FALSE
                  AND COALESCE(p.es_servicio, FALSE) = FALSE
            ),
            'gases', COUNT(*) FILTER (WHERE COALESCE(p.es_gas, FALSE) = TRUE),
            'servicios', COUNT(*) FILTER (WHERE COALESCE(p.es_servicio, FALSE) = TRUE)
        )
    INTO v_total, v_resumen
    FROM pro_producto p
    LEFT JOIN pro_sub_categoria sc ON p.id_sub_categoria = sc.id
    LEFT JOIN pro_categoria c ON sc.id_categoria = c.id
    WHERE (p_solo_activos IS NULL OR p.estado = p_solo_activos)
      AND (p_id_sub_categoria IS NULL OR p.id_sub_categoria = p_id_sub_categoria)
      AND (p_id_categoria IS NULL OR sc.id_categoria = p_id_categoria)
      AND (p_es_gas IS NULL OR p.es_gas = p_es_gas)
      AND (p_es_servicio IS NULL OR p.es_servicio = p_es_servicio)
      AND (p_es_alquilable IS NULL OR p.es_alquilable = p_es_alquilable)
      AND (p_afecta_stock IS NULL OR p.afecta_stock = p_afecta_stock)
      AND (p_es_mantenimiento IS NULL OR p.es_mantenimiento = p_es_mantenimiento)
      AND (
          p_busqueda = ''
          OR gen_texto_coincide(p.codigo, p_busqueda)
          OR gen_texto_coincide(COALESCE(p.codigo_barra, ''), p_busqueda)
          OR gen_texto_coincide(COALESCE(p.codigo_ubicacion, ''), p_busqueda)
          OR gen_texto_coincide(p.nombre, p_busqueda)
          OR gen_texto_coincide(COALESCE(p.marca, ''), p_busqueda)
          OR gen_texto_coincide(COALESCE(p.presentacion, ''), p_busqueda)
          OR gen_texto_coincide(COALESCE(sc.nombre, ''), p_busqueda)
          OR gen_texto_coincide(COALESCE(c.nombre, ''), p_busqueda)
      );

    SELECT COALESCE(json_agg(row_to_json(t)), '[]'::JSON) INTO v_registros
    FROM (
        SELECT
            p.id,
            p.codigo,
            p.codigo_barra,
            p.codigo_ubicacion,
            p.nombre,
            p.id_sub_categoria,
            sc.nombre AS nombre_sub_categoria,
            sc.id_categoria,
            c.nombre AS nombre_categoria,
            p.id_unidad_medida,
            um.nombre AS nombre_unidad_medida,
            p.marca,
            p.presentacion,
            p.es_gas,
            p.es_servicio,
            p.es_alquilable,
            p.es_mantenimiento,
            p.afecta_stock,
            p.precio,
            p.precio_compra,
            p.precio_garantia,
            p.estado,
            EXISTS (
                SELECT 1
                FROM pro_stock s
                WHERE s.id_producto = p.id
                  AND s.estado = 1
                  AND s.stock <> 0
            ) AS tiene_stock,
            CASE
                WHEN p_id_almacen IS NULL THEN NULL
                ELSE COALESCE(st.stock, 0)
            END AS stock_actual,
            CASE
                WHEN p_id_almacen IS NULL THEN NULL
                ELSE COALESCE(st.stock_minimo, 0)
            END AS stock_minimo,
            CASE
                WHEN p_id_almacen IS NULL THEN NULL
                ELSE COALESCE(st.stock, 0) <= COALESCE(st.stock_minimo, 0)
            END AS stock_bajo,
            img.ruta AS imagen_principal_ruta,
            p.fecha_creacion,
            p.fecha_modificacion,
            p.id_usuario_creacion,
            uc.nombre AS nombre_usuario_creacion,
            p.id_usuario_modificacion,
            um2.nombre AS nombre_usuario_modificacion
        FROM pro_producto p
        LEFT JOIN pro_sub_categoria sc ON p.id_sub_categoria = sc.id
        LEFT JOIN pro_categoria c ON sc.id_categoria = c.id
        LEFT JOIN gen_lista_opciones um ON p.id_unidad_medida = um.id
        LEFT JOIN auth_usuarios uc ON p.id_usuario_creacion = uc.id
        LEFT JOIN auth_usuarios um2 ON p.id_usuario_modificacion = um2.id
        LEFT JOIN pro_stock st
            ON st.id_producto = p.id
           AND st.estado = 1
           AND p_id_almacen IS NOT NULL
           AND st.id_almacen = p_id_almacen
        LEFT JOIN LATERAL (
            SELECT a.ruta
            FROM pro_producto_imagen pi
            INNER JOIN gen_archivo a ON a.id = pi.id_archivo
            WHERE pi.id_producto = p.id
              AND pi.estado = 1
            ORDER BY pi.es_principal DESC, pi.orden ASC, pi.id ASC
            LIMIT 1
        ) img ON TRUE
        WHERE (p_solo_activos IS NULL OR p.estado = p_solo_activos)
          AND (p_id_sub_categoria IS NULL OR p.id_sub_categoria = p_id_sub_categoria)
          AND (p_id_categoria IS NULL OR sc.id_categoria = p_id_categoria)
          AND (p_es_gas IS NULL OR p.es_gas = p_es_gas)
          AND (p_es_servicio IS NULL OR p.es_servicio = p_es_servicio)
          AND (p_es_alquilable IS NULL OR p.es_alquilable = p_es_alquilable)
          AND (p_afecta_stock IS NULL OR p.afecta_stock = p_afecta_stock)
          AND (p_es_mantenimiento IS NULL OR p.es_mantenimiento = p_es_mantenimiento)
          AND (
              p_busqueda = ''
              OR gen_texto_coincide(p.codigo, p_busqueda)
              OR gen_texto_coincide(COALESCE(p.codigo_barra, ''), p_busqueda)
              OR gen_texto_coincide(COALESCE(p.codigo_ubicacion, ''), p_busqueda)
              OR gen_texto_coincide(p.nombre, p_busqueda)
              OR gen_texto_coincide(COALESCE(p.marca, ''), p_busqueda)
              OR gen_texto_coincide(COALESCE(p.presentacion, ''), p_busqueda)
              OR gen_texto_coincide(COALESCE(sc.nombre, ''), p_busqueda)
              OR gen_texto_coincide(COALESCE(c.nombre, ''), p_busqueda)
          )
        ORDER BY p.fecha_creacion DESC NULLS LAST, p.id DESC
        LIMIT p_limite
        OFFSET p_offset
    ) t;

    RETURN json_build_object(
        'registros', v_registros,
        'total', v_total,
        'resumen', v_resumen
    );
END;
$$;


--
-- Name: pro_listar_stock(character varying, integer, integer, integer, integer, boolean, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.pro_listar_stock(p_busqueda character varying DEFAULT ''::character varying, p_limite integer DEFAULT 10, p_offset integer DEFAULT 0, p_id_almacen integer DEFAULT NULL::integer, p_id_producto integer DEFAULT NULL::integer, p_solo_bajo_minimo boolean DEFAULT NULL::boolean, p_solo_activos integer DEFAULT 1) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_registros JSON;
    v_total BIGINT;
    v_resumen JSON;
BEGIN
    SET TIME ZONE 'America/Lima';

    -- Stock de productos: accesorios y, desde Fase 1, también gas (pro_stock unificado).
    SELECT
        COUNT(*),
        json_build_object(
            'total_items', COUNT(*),
            'bajo_minimo', COUNT(*) FILTER (WHERE s.stock <= s.stock_minimo),
            'ok', COUNT(*) FILTER (WHERE s.stock > s.stock_minimo),
            'stock_total', COALESCE(SUM(s.stock), 0)
        )
    INTO v_total, v_resumen
    FROM pro_stock s
    INNER JOIN gen_almacen a ON s.id_almacen = a.id
    INNER JOIN pro_producto p ON s.id_producto = p.id
    WHERE (p_solo_activos IS NULL OR s.estado = p_solo_activos)
      AND (p_solo_activos IS DISTINCT FROM 1 OR (a.estado = 1 AND p.estado = 1))
      AND (p_id_almacen IS NULL OR s.id_almacen = p_id_almacen)
      AND (p_id_producto IS NULL OR s.id_producto = p_id_producto)
      AND (
          p_solo_bajo_minimo IS NULL
          OR (p_solo_bajo_minimo = TRUE AND s.stock <= s.stock_minimo)
          OR (p_solo_bajo_minimo = FALSE AND s.stock > s.stock_minimo)
      )
      AND (
          p_busqueda = ''
          OR gen_texto_coincide(a.nombre, p_busqueda)
          OR gen_texto_coincide(p.codigo, p_busqueda)
          OR gen_texto_coincide(p.nombre, p_busqueda)
      );

    SELECT COALESCE(json_agg(row_to_json(t)), '[]'::JSON) INTO v_registros
    FROM (
        SELECT
            s.id,
            s.id_almacen,
            a.nombre AS nombre_almacen,
            a.id_sucursal,
            suc.nombre AS nombre_sucursal,
            s.id_producto,
            p.codigo AS codigo_producto,
            p.nombre AS nombre_producto,
            COALESCE(p.es_gas, FALSE) AS es_gas,
            p.id_unidad_medida,
            um.nombre AS nombre_unidad_medida,
            sc.id AS id_sub_categoria,
            sc.nombre AS nombre_sub_categoria,
            cat.id AS id_categoria,
            cat.nombre AS nombre_categoria,
            s.stock,
            s.stock_minimo,
            (s.stock <= s.stock_minimo) AS bajo_minimo,
            s.estado,
            s.fecha_creacion,
            s.fecha_modificacion,
            s.id_usuario_creacion,
            uc.nombre AS nombre_usuario_creacion,
            s.id_usuario_modificacion,
            um2.nombre AS nombre_usuario_modificacion
        FROM pro_stock s
        INNER JOIN gen_almacen a ON s.id_almacen = a.id
        INNER JOIN gen_sucursal suc ON a.id_sucursal = suc.id
        INNER JOIN pro_producto p ON s.id_producto = p.id
        LEFT JOIN pro_sub_categoria sc ON p.id_sub_categoria = sc.id
        LEFT JOIN pro_categoria cat ON sc.id_categoria = cat.id
        LEFT JOIN gen_lista_opciones um ON p.id_unidad_medida = um.id
        LEFT JOIN auth_usuarios uc ON s.id_usuario_creacion = uc.id
        LEFT JOIN auth_usuarios um2 ON s.id_usuario_modificacion = um2.id
        WHERE (p_solo_activos IS NULL OR s.estado = p_solo_activos)
          AND (p_solo_activos IS DISTINCT FROM 1 OR (a.estado = 1 AND p.estado = 1))
          AND (p_id_almacen IS NULL OR s.id_almacen = p_id_almacen)
          AND (p_id_producto IS NULL OR s.id_producto = p_id_producto)
          AND (
              p_solo_bajo_minimo IS NULL
              OR (p_solo_bajo_minimo = TRUE AND s.stock <= s.stock_minimo)
              OR (p_solo_bajo_minimo = FALSE AND s.stock > s.stock_minimo)
          )
          AND (
              p_busqueda = ''
              OR gen_texto_coincide(a.nombre, p_busqueda)
              OR gen_texto_coincide(p.codigo, p_busqueda)
              OR gen_texto_coincide(p.nombre, p_busqueda)
          )
        ORDER BY a.nombre ASC, p.nombre ASC
        LIMIT p_limite
        OFFSET p_offset
    ) t;

    RETURN json_build_object(
        'registros', v_registros,
        'total', v_total,
        'resumen', v_resumen
    );
END;
$$;


--
-- Name: pro_listar_stock_bajo_notificar(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.pro_listar_stock_bajo_notificar() RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_registros JSON;
BEGIN
    SET TIME ZONE 'America/Lima';

    SELECT COALESCE(json_agg(t.row_data ORDER BY t.es_cero DESC, t.nombre_almacen, t.nombre_producto), '[]'::JSON)
    INTO v_registros
    FROM (
        SELECT json_build_object(
            'id', s.id,
            'id_almacen', s.id_almacen,
            'nombre_almacen', a.nombre,
            'id_producto', s.id_producto,
            'codigo_producto', p.codigo,
            'nombre_producto', p.nombre,
            'stock', s.stock,
            'stock_minimo', s.stock_minimo,
            'es_cero', (s.stock <= 0)
        ) AS row_data,
        a.nombre AS nombre_almacen,
        p.nombre AS nombre_producto,
        (s.stock <= 0) AS es_cero
        FROM pro_stock s
        INNER JOIN gen_almacen a ON a.id = s.id_almacen AND a.estado = 1
        INNER JOIN pro_producto p ON p.id = s.id_producto AND p.estado = 1
        WHERE s.estado = 1
          AND COALESCE(p.afecta_stock, TRUE) = TRUE
          AND s.stock <= COALESCE(s.stock_minimo, 0)
    ) t;

    RETURN json_build_object('registros', v_registros);
END;
$$;


--
-- Name: pro_listar_sub_categorias(character varying, integer, integer, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.pro_listar_sub_categorias(p_busqueda character varying DEFAULT ''::character varying, p_limite integer DEFAULT 10, p_offset integer DEFAULT 0, p_id_categoria integer DEFAULT NULL::integer, p_solo_activos integer DEFAULT 1) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_registros JSON;
    v_total BIGINT;
BEGIN
    SET TIME ZONE 'America/Lima';

    SELECT COUNT(*) INTO v_total
    FROM pro_sub_categoria sc
    INNER JOIN pro_categoria c ON sc.id_categoria = c.id
    WHERE (p_solo_activos IS NULL OR sc.estado = p_solo_activos)
      AND (p_solo_activos IS DISTINCT FROM 1 OR c.estado = 1)
      AND (p_id_categoria IS NULL OR sc.id_categoria = p_id_categoria)
      AND (
          p_busqueda = ''
          OR gen_texto_coincide(sc.nombre, p_busqueda)
          OR gen_texto_coincide(COALESCE(sc.descripcion, ''), p_busqueda)
          OR gen_texto_coincide(c.nombre, p_busqueda)
      );

    SELECT COALESCE(json_agg(row_to_json(t)), '[]'::JSON) INTO v_registros
    FROM (
        SELECT
            sc.id,
            sc.id_categoria,
            c.nombre AS nombre_categoria,
            sc.nombre,
            sc.descripcion,
            sc.estado,
            sc.fecha_creacion,
            sc.fecha_modificacion,
            sc.id_usuario_creacion,
            uc.nombre AS nombre_usuario_creacion,
            sc.id_usuario_modificacion,
            um.nombre AS nombre_usuario_modificacion,
            (
                SELECT COUNT(*)::INTEGER
                FROM pro_producto p
                WHERE p.id_sub_categoria = sc.id AND p.estado = 1
            ) AS total_productos,
            (
                SELECT COALESCE(json_agg(p.nombre ORDER BY p.nombre ASC), '[]'::JSON)
                FROM pro_producto p
                WHERE p.id_sub_categoria = sc.id AND p.estado = 1
            ) AS nombres_productos
        FROM pro_sub_categoria sc
        INNER JOIN pro_categoria c ON sc.id_categoria = c.id
        LEFT JOIN auth_usuarios uc ON sc.id_usuario_creacion = uc.id
        LEFT JOIN auth_usuarios um ON sc.id_usuario_modificacion = um.id
        WHERE (p_solo_activos IS NULL OR sc.estado = p_solo_activos)
          AND (p_solo_activos IS DISTINCT FROM 1 OR c.estado = 1)
          AND (p_id_categoria IS NULL OR sc.id_categoria = p_id_categoria)
          AND (
              p_busqueda = ''
              OR gen_texto_coincide(sc.nombre, p_busqueda)
              OR gen_texto_coincide(COALESCE(sc.descripcion, ''), p_busqueda)
              OR gen_texto_coincide(c.nombre, p_busqueda)
          )
        ORDER BY c.nombre ASC, sc.nombre ASC
        LIMIT p_limite
        OFFSET p_offset
    ) t;

    RETURN json_build_object('registros', v_registros, 'total', v_total);
END;
$$;


--
-- Name: pro_obtener_catalogo_precio(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.pro_obtener_catalogo_precio(p_id integer) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_registro JSON;
BEGIN
    SET TIME ZONE 'America/Lima';

    SELECT row_to_json(t) INTO v_registro
    FROM (
        SELECT
            cp.id,
            cp.id_tipo_catalogo,
            tc.nombre AS nombre_tipo_catalogo,
            cp.periodo,
            cp.nombre_item,
            cp.id_producto,
            p.codigo AS codigo_producto,
            p.nombre AS nombre_producto,
            cp.id_tipo_balon,
            tb.nombre AS nombre_tipo_balon,
            cp.id_proveedor,
            COALESCE(prov.razon_social, prov.nombres) AS nombre_proveedor,
            cp.clasificacion,
            cp.modelo,
            cp.capacidad,
            cp.id_unidad_medida,
            um.nombre AS nombre_unidad_medida,
            cp.descripcion_presentacion,
            cp.costo_producto,
            cp.costo_flete,
            cp.porcentaje_margen,
            cp.precio_final,
            cp.precio_garantia,
            cp.estado,
            cp.fecha_creacion,
            cp.fecha_modificacion,
            cp.id_usuario_creacion,
            uc.nombre AS nombre_usuario_creacion,
            cp.id_usuario_modificacion,
            um2.nombre AS nombre_usuario_modificacion
        FROM pro_catalogo_precio cp
        LEFT JOIN gen_lista_opciones tc ON cp.id_tipo_catalogo = tc.id
        LEFT JOIN pro_producto p ON cp.id_producto = p.id
        LEFT JOIN bal_tipo_balon tb ON cp.id_tipo_balon = tb.id
        LEFT JOIN cli_clientes prov ON cp.id_proveedor = prov.id
        LEFT JOIN gen_lista_opciones um ON cp.id_unidad_medida = um.id
        LEFT JOIN auth_usuarios uc ON cp.id_usuario_creacion = uc.id
        LEFT JOIN auth_usuarios um2 ON cp.id_usuario_modificacion = um2.id
        WHERE cp.id = p_id AND cp.estado = 1
    ) t;

    RETURN json_build_object('registro', v_registro);
END;
$$;


