--
-- Name: gen_condicion_pago; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.gen_condicion_pago (
    id integer NOT NULL,
    codigo character varying(10) NOT NULL,
    nombre character varying(100) NOT NULL,
    dias_credito integer DEFAULT 0 NOT NULL,
    estado integer DEFAULT 1 NOT NULL,
    id_usuario_creacion integer,
    id_usuario_modificacion integer,
    fecha_creacion timestamp without time zone DEFAULT now(),
    fecha_modificacion timestamp without time zone DEFAULT now(),
    numero_cuotas integer,
    dia_mes_pago integer,
    CONSTRAINT chk_gen_condicion_pago_cuotas CHECK (((numero_cuotas IS NULL) OR ((numero_cuotas >= 1) AND ((numero_cuotas = 1) OR ((dia_mes_pago IS NOT NULL) AND ((dia_mes_pago >= 1) AND (dia_mes_pago <= 31)))))))
);


--
-- Name: COLUMN gen_condicion_pago.dias_credito; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.gen_condicion_pago.dias_credito IS 'Días hasta vencimiento (crédito simple) o hasta la primera cuota.';


--
-- Name: COLUMN gen_condicion_pago.numero_cuotas; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.gen_condicion_pago.numero_cuotas IS 'Cantidad de cuotas del plan. NULL o 1 = sin plan de cuotas.';


--
-- Name: COLUMN gen_condicion_pago.dia_mes_pago; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.gen_condicion_pago.dia_mes_pago IS 'Día del mes (1..31) para cobro de cuotas mensuales.';


